window.__FULL_WORDS_DATA__ = [{"id":1,"word":"ambition","pronunciation":"/æmˈbɪn/","meaning":"n.野心;雄心;抱负","unit":1,"lesson":1,"seq":1,"isStar":false,"memo":"谐音 单词发音类似“俺必胜”→雄心，抱负","example":"He found an outlet for his ambition in his work. 他在工作中找到了施展抱负的途径。","derivative":"ambitious /æm'bɪəs/ adj.有雄心的，有抱负的"},{"id":2,"word":"ambitious","pronunciation":"/æmˈbʃəs/","meaning":"adj.有雄心的,有抱负的","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":3,"word":"aggressive","pronunciation":"/əˈɡresɪv/","meaning":"adj.好斗的,侵略的;有进取心的","unit":1,"lesson":1,"seq":2,"isStar":false,"memo":"联想 ag-(一再地) + gress(走) + -ive(形容词后缀) → 一再地(为了梦想)向前走 → 有进取心的","example":"The dog is aggressive towards strangers. 这只狗对陌生人有攻击性。","derivative":"aggression /ə'gren/ n.攻击性；侵略"},{"id":4,"word":"aggression","pronunciation":"/əˈɡreʃn/","meaning":"n.攻击性;侵略","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":5,"word":"congress","pronunciation":"/ˈkɒŋɡres/","meaning":"n.国会;议会;代表大会","unit":1,"lesson":1,"seq":3,"isStar":false,"memo":"构词 con-(一起) + gress(走) → 所有代表走到一起，参加大会 → 国会，议会；代表大会","example":"Congress has already taken some modest steps. 国会已经采取了一些温和的措施。","derivative":"congressional /kən'greʃənl/ adj.国会的；代表大会的"},{"id":6,"word":"congressional","pronunciation":"/ˌkɒŋɡreʃənl/","meaning":"adj.国会的;代表大会的","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":7,"word":"parliament","pronunciation":"/ˈpɑləmənt/","meaning":"n.议会,国会","unit":1,"lesson":1,"seq":4,"isStar":false,"memo":"联想 parlia(音似“怕了”) + -ment(名词后缀) → “国会”是该国最大的权力机构，有些人看到就怕了。","example":"The issue was debated in Parliament. 议会就这个问题进行了辩论。","derivative":"parliamentary /ˌpɑːlə'mentri/ adj.议会的，国会的"},{"id":8,"word":"parliamentary","pronunciation":"/pɑːləˈmentri/","meaning":"adj.议会的,国会的","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":9,"word":"ambassador","pronunciation":"/æmˈbæsədə(r)/","meaning":"n.大使,使节;代表","unit":1,"lesson":1,"seq":5,"isStar":false,"memo":"对照 embassy n.大使馆 → ambassador n.大使，使节","example":"The ambassador refused all interviews. 该大使拒绝了所有的采访。"},{"id":10,"word":"conquer","pronunciation":"/ˈkɒŋkə(r)/","meaning":"v.战胜,征服;攻克","unit":1,"lesson":1,"seq":6,"isStar":false,"memo":"联想 con-(所有) + quer(音似“克”) → 他攻克了所有的困难 → 战胜，征服","example":"The only way to conquer a fear is to face it. 战胜恐惧的唯一方法是正视恐惧。","derivative":"conquest /'kɒŋkwest/ n.征服；占领；占领的地区\nconqueror /'kɒŋkərə(r)/ n.征服者；占领者；胜利者"},{"id":11,"word":"conquest","pronunciation":"/ˈkɒŋkwest/","meaning":"n.征服;占领;占领的地区","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":12,"word":"conqueror","pronunciation":"/ˈkɒkərə(r)/","meaning":"n.征服者;占领者;胜利者","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":13,"word":"eminent","pronunciation":"/ˈemɪnənt/","meaning":"adj.杰出的,有名的;明显的","unit":1,"lesson":1,"seq":7,"isStar":false},{"id":14,"word":"eminence","pronunciation":"/ˈemɪnəns/","meaning":"n.卓越,著名","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":15,"word":"prominent","pronunciation":"/'prɒmɪnənt/","meaning":"adj.突出的;卓越的,著名的;重要的","unit":1,"lesson":1,"seq":8,"isStar":false,"memo":"联想 pro-(提前) + minent(联想 eminent)→提前变得杰出的→突出的","example":"He played a prominent part in the campaign. 他在这次运动中发挥了重要作用。","derivative":"prominence /'prɒmɪnəns/ n.重要;突出;卓越;出名"},{"id":16,"word":"prominence","pronunciation":"/'prmɪnəns/","meaning":"n.重要;突出;卓越,出名","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":17,"word":"outstanding","pronunciation":"/aʊt'stændɪŋ/","meaning":"adj.杰出的;突出的;重要的","unit":1,"lesson":1,"seq":9,"isStar":false,"memo":"构词 out(向外) + stand(站) + -ing(形容词后缀)→站出来的→突出的","example":"He is an outstanding speaker. 他是一位杰出的演说家。"},{"id":18,"word":"remark","pronunciation":"/rɪ'mɑːk/","meaning":"n.言论;评论 v.谈到;评论","unit":1,"lesson":1,"seq":10,"isStar":false,"memo":"构词 re-(重复) + mark(标记)→重复标记→谈到;评论","example":"How does the woman feel about his remarks? 这位女士对他的言论有什么感想?"},{"id":19,"word":"remarkable","pronunciation":"/rɪ'mɑːkəbl/","meaning":"adj.显著的;非凡的","unit":1,"lesson":1,"seq":0,"isStar":true,"memo":"构词+联想：re-（再）+mark（标记）+able→值得你‘再标记一遍’的亮点！就像朋友圈刷到神级笔记，必须双击+截图+转发。","example":"The research team achieved a remarkable breakthrough in renewable battery technology. 研究团队在可充电电池技术领域取得了非凡的突破。","derivative":"remarkably /rɪ'mɑːkəbli/ adv.显著地；非凡地"},{"id":20,"word":"comment","pronunciation":"/'kɒment/","meaning":"n.评论;批评 v.评论;表达意见","unit":1,"lesson":1,"seq":11,"isStar":false,"memo":"联想 com-(共同) + men(人) + t(联想“他”)→所有人共同“评论”他。","example":"There was a lot of comment about his behaviour. 对他的行为举止有很多的指责。"},{"id":21,"word":"commentary","pronunciation":"/'kɒməntri/","meaning":"n.现场解说,实况报道;评注;批评","unit":1,"lesson":1,"seq":12,"isStar":false,"memo":"构词 comment(评论) + -ary(名词后缀)→评注","example":"I can't hear the football commentary. 我听不到足球比赛的现场解说。"},{"id":22,"word":"commentator","pronunciation":"/'kɒmənteɪtə(r)/","meaning":"n.评论员;实况解说员","unit":1,"lesson":1,"seq":13,"isStar":false},{"id":23,"word":"brilliant","pronunciation":"/'brɪliənt/","meaning":"adj.明亮的;巧妙的;聪颖的;使人印象深的","unit":1,"lesson":1,"seq":14,"isStar":false,"memo":"联想 bri（联想 bright）+ (l) lian（联想“脸”）+ t(联想“他”)→他的脸很亮→明亮的","example":"She had no patience for brilliant but irrelevant figures of speech. 她对那些巧妙但无关紧要的修辞手法没有耐心。","derivative":"brilliance /'brɪljəns/ n.才华;光彩"},{"id":24,"word":"brilliance","pronunciation":"/'brɪliəns/","meaning":"n.才华;光彩","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":25,"word":"fabulous","pronunciation":"/'fæbjələs/","meaning":"adj.极好的,绝妙的;巨大的","unit":1,"lesson":1,"seq":15,"isStar":false},{"id":26,"word":"terrific","pronunciation":"/tə'rɪfɪk/","meaning":"adj.极好的;了不起的;巨大的","unit":1,"lesson":1,"seq":16,"isStar":false,"memo":"联想 ter(音似“特”)+ ri(联想“日”)+ fic (音似“非可”)→特别的日子里非提不可的事,一定是“极好的”事。\n对照 没有可怕的(terrible)事情发生就是极好的(terrific)。","example":"I've got a terrific amount of work to do. 我有大量的工作要做。"},{"id":27,"word":"grand","pronunciation":"/ɡrænd/","meaning":"adj.壮丽的,堂皇的;宏大的;极好的","unit":1,"lesson":1,"seq":17,"isStar":false,"memo":"联想 联想 grandfather 和 grandmother→祖父母比父母的辈分大→宏大的;极好的","example":"She attended the supermarket's grand opening ceremony. 她参加了超市盛大的开业典礼。"},{"id":28,"word":"magnificent","pronunciation":"/mæɡ'nɪfɪsnt/","meaning":"adj.壮丽的,宏伟的","unit":1,"lesson":1,"seq":18,"isStar":false,"memo":"联想 ma(联想“妈”)+ g(联想“哥”)+ ni (联想“你”)+ ficent(音似“飞身”)→妈妈、哥哥和你等一家人观看空中飞人表演,场面很壮观→壮丽的,宏伟的","example":"They praised the magnificent architecture of the Imperial Palace. 他们称赞故宫的宏伟建筑。"},{"id":29,"word":"magnitude","pronunciation":"/'mæɡnɪtjuːd/","meaning":"n.重大,重要性","unit":1,"lesson":1,"seq":19,"isStar":false,"memo":"对照 壮丽的(magnificent)场面体现了文化传承的重要性(magnitude)。","example":"They didn't seem to appreciate the magnitude of the problem. 他们似乎没有意识到这个问题的重要性。"},{"id":30,"word":"magnify","pronunciation":"/'mæɡnɪfaɪ/","meaning":"v.放大,扩大;增强;夸大","unit":1,"lesson":1,"seq":20,"isStar":false,"example":"The microscope can magnify the object 100 times in diameter. 这台显微镜能把物体的直径放大 100 倍。"},{"id":31,"word":"exception","pronunciation":"/ɪk'sepʃn/","meaning":"n.例外","unit":1,"lesson":1,"seq":21,"isStar":false,"example":"Nobody had much money at the time and I was no exception. 那时候谁都没有很多钱,我也不例外。"},{"id":32,"word":"exceptional","pronunciation":"/ɪk'sepʃənl/","meaning":"adj.杰出的;不寻常的,罕见的;特别的","unit":1,"lesson":1,"seq":22,"isStar":false,"memo":"构词 exception(例外)+ -al(形容词后缀)→例外的→杰出的;不寻常的","example":"Capital punishment is allowable only under exceptional circumstances. 只有在特殊情况下才允许判死刑。"},{"id":33,"word":"exemplary","pronunciation":"/ɪɡ'zempləri/","meaning":"adj.典范的,可作榜样的","unit":1,"lesson":1,"seq":23,"isStar":false},{"id":34,"word":"exemplify","pronunciation":"/ɪɡ'zemplɪfaɪ/","meaning":"v.举例说明;是……的典范/榜样","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":35,"word":"instance","pronunciation":"/'ɪnstəns/","meaning":"n.例子,事例 v.举……为例","unit":1,"lesson":1,"seq":24,"isStar":false,"memo":"谐音：单词发音类似“因事谈事”→我们要就事论事，举“例子”谈事。","example":"The creative aspects of advertisement, for instance, often cover up the defects in products. 例如，广告的创意往往掩盖了产品的缺陷。"},{"id":36,"word":"tremendous","pronunciation":"/trə'mendəs/","meaning":"adj.巨大的,极大的;极好的","unit":1,"lesson":1,"seq":25,"isStar":false,"memo":"联想：tre(联想 tree) + men(联想“门”) + dou(联想“都”) + s(联想“死”) → 门前两棵树都死了，这给她造成了“极大的”心理伤害。","example":"One of humans’ key characteristics is tremendous linguistic and cognitive diversity. 人类的一个重要特征是庞大的语言和认知多样性。"},{"id":37,"word":"coordinate","pronunciation":"/kəʊ'ɔːdɪneɪt/","meaning":"n.坐标;套装 /kə'ɔːdɪneɪt/ v.使协调;使相互配合","unit":1,"lesson":1,"seq":26,"isStar":false,"memo":"对照：普通的(ordinary)我们需要努力协调(coordinate)自己的心态。","example":"Goal-setting does help coordinate and motivate people. 设定目标确实有助于协调和激励人们。","derivative":"coordination /kəˌɔːdˈneɪʃn/ n.协作；协调；配合 coordinator /kəʊˈɔːdɪneɪtə(r)/ n.协调者"},{"id":38,"word":"coordination","pronunciation":"/kəʊˌːdɪ'neʃn/","meaning":"n.协作;协调;配合","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":39,"word":"coordinator","pronunciation":"/kəʊ'ɔːdɪneɪtə(r)/","meaning":"n.协调者","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":40,"word":"subordinate","pronunciation":"/sə'bɔːdɪnət/","meaning":"n.下属 adj.下级的;次要的 /sə'bɔːdɪneɪt/ v.把……置于次要地位;使从属于……","unit":1,"lesson":1,"seq":27,"isStar":false,"memo":"联想：sub-(在……下面) + ordinate(联想 ordinary)→在一般的下面→下级的；次要的","example":"He had been under attack for shifting responsibility to his subordinates. 他因将责任推卸给下属而受到抨击。","derivative":"subordination /səˌbɔːdɪˈneɪʃn/ n.附属；从属"},{"id":41,"word":"subordination","pronunciation":"/səˌbɔdɪ'neɪn/","meaning":"n.附属;从属","unit":1,"lesson":1,"seq":0,"isStar":true},{"id":42,"word":"surface","pronunciation":"/'sɜːfs/","meaning":"n.表面 v.升到水面;显露,暴露","unit":1,"lesson":2,"seq":1,"isStar":false,"memo":"构词 sur-(上面)+face(脸,面)→表面","example":"The chance of these bacteria being on most surfaces is very low. 这些细菌出现在大多数物体表面的概率非常低。"},{"id":43,"word":"surf","pronunciation":"/sɜːf/","meaning":"v.冲浪;漫游 n.激浪","unit":1,"lesson":2,"seq":2,"isStar":false},{"id":44,"word":"surfing","pronunciation":"/'sɜːfɪŋ/","meaning":"n.冲浪运动;(互联网上)冲浪","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":45,"word":"surplus","pronunciation":"/'sɜːpləs/","meaning":"n.剩余,过剩 adj.过剩的,剩余的","unit":1,"lesson":2,"seq":3,"isStar":false,"memo":"联想 sur(音似“蛇”)+p(联想“扑”)+lu(联想“鹿”)+s(联想“死”)→蛇扑向一头鹿并把它咬死了,吃了很久还有“剩余”。","example":"If you have surplus vegetables, you'll do a vegetable soup. 如果你有剩余的蔬菜,你可以做蔬菜汤。"},{"id":46,"word":"surpass","pronunciation":"/sə'pɑːs/","meaning":"v.超过;胜过,优于","unit":1,"lesson":2,"seq":4,"isStar":false,"memo":"构词 sur-(上面)+pass(通过)→从上面通过→超过;胜过","example":"No physicist is likely to surpass Einstein in the next 100 years. 在未来的100年里,没有物理学家能够超过爱因斯坦。"},{"id":47,"word":"transcend","pronunciation":"/træn'send/","meaning":"v.超出,超越","unit":1,"lesson":2,"seq":5,"isStar":false,"memo":"联想 trans-(从……到……)+ce(=cess,走)+nd→他走南闯北,能力“超越”了许多人。","example":"The film transcends national and cultural barriers. 这部电影超越国家和文化界限。"},{"id":48,"word":"precede","pronunciation":"/prɪ'sid/","meaning":"v.先于,在……前面","unit":1,"lesson":2,"seq":6,"isStar":false,"memo":"联想 pre-(在前)+ce(走)+de→先于,在……前面","example":"He was preceded in birth by one sister. 他有一个先于他出生的姐姐。\npreceding /prɪˈsiːdɪŋ/ adj.在先的,前面的","derivative":"preceding /prɪˈsiːdɪŋ/ adj.在先的,前面的"},{"id":49,"word":"preceding","pronunciation":"/prɪ'siːdɪŋ/","meaning":"adj.在先的,前面的","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":50,"word":"precedent","pronunciation":"/'presɪdənt/","meaning":"n.前例,先例;惯例","unit":1,"lesson":2,"seq":7,"isStar":false},{"id":51,"word":"unprecedented","pronunciation":"/ʌn'presɪdentɪd/","meaning":"adj.前所未有的,空前的","unit":1,"lesson":2,"seq":8,"isStar":false,"memo":"[构词] un-(否定前缀) + precedent(先例) + -ed(形容词后缀)→前所未有的,空前的","example":"It will face challenges unprecedented in its history. 它将面临历史上前所未有的挑战。"},{"id":52,"word":"predecessor","pronunciation":"/'priːdsesə(r)/","meaning":"n.前任,前辈;前身,原先的东西;被替代的事物","unit":1,"lesson":2,"seq":9,"isStar":false,"memo":"[联想] pre-(在前) + de(联想“的”) + cess(走) + -or(表示人的后缀)→在前面走的人→前任,前辈","example":"He is sure to surpass the achievements of his predecessor. 他的成就一定会超过他的前辈。"},{"id":53,"word":"concede","pronunciation":"/kən'siːd/","meaning":"v.承认;让步","unit":1,"lesson":2,"seq":10,"isStar":false,"memo":"[联想] con-(都) + ce(走) + de→都走开,退让→让步","example":"He concedes his research runs counter to a very large body of literature. 他承认他的研究与大量文献背道而驰。","derivative":"concession /kən'seʃn/ n.承认,许可;让步,妥协"},{"id":54,"word":"concession","pronunciation":"/kən'seʃn/","meaning":"n.承认,许可;让步,妥协","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":55,"word":"succeed","pronunciation":"/sək'siːd/","meaning":"v.成功,有成就;达到目的,实现目标;继任","unit":1,"lesson":2,"seq":11,"isStar":false,"memo":"[联想] suc-(在下) + ce(走) + ed→从下往上走→成功","example":"You will have to work hard if you are to succeed. 要想有成就,你必须苦干。"},{"id":56,"word":"successor","pronunciation":"/sək'sesə(r)/","meaning":"n.继承者,接任者;接替的事物","unit":1,"lesson":2,"seq":12,"isStar":false,"memo":"[联想] success(成功) + -or(表示人的后缀)→成功继承王位的人就是“继承者”。","example":"The program has just come to an end, with no successor. 这个计划刚结束,没有接替的计划。"},{"id":57,"word":"succession","pronunciation":"/sək'seʃn/","meaning":"n.连续的人(或事物);一连串,一系列;继任,接替","unit":1,"lesson":2,"seq":13,"isStar":false,"memo":"[联想] success(成功) + -ion(名词后缀)→成功无法“继任”,努力才有明天。","example":"For the next ten years a succession of books sounded the alarm. 在接下来的十年里,一系列书籍敲响了警钟。"},{"id":58,"word":"successive","pronunciation":"/sək'sesɪv/","meaning":"adj.接连的,连续的","unit":1,"lesson":2,"seq":0,"isStar":true,"memo":"success（成功）+ -ive → 连续成功？不！是‘接二连三’像赶ddl：周一交报告、周二做pre、周三考小测…","example":"The team won three successive championships. 该队连续三次夺得冠军。","derivative":"succession /səkˈseʃ(ə)n/ n.连续；继任"},{"id":59,"word":"exceed","pronunciation":"/ɪk'siːd/","meaning":"v.超过(数目或数量);超越(法律命令等的)限制","unit":1,"lesson":2,"seq":14,"isStar":false,"memo":"[联想] ex-(往外) + ce(走) + ed→往外走→青出于蓝而胜于蓝→超过","example":"In China, the household-savings rate exceeds 20%. 在中国,家庭储蓄率超过20%。"},{"id":60,"word":"exceedingly","pronunciation":"/ɪk'sidɪŋli/","meaning":"adv.极其,非常","unit":1,"lesson":2,"seq":15,"isStar":false,"memo":"[构词] exceed(超过) + -ing(形容词后缀) + -ly(副词后缀)→超过地→极其,非常","example":"The task proved to be exceedingly difficult, requiring all our skills and patience. 这项任务极其艰巨,需要我们所有的技能和耐心。"},{"id":61,"word":"excess","pronunciation":"/ɪk'ses/","meaning":"n.超过;过度,过分 /'eksəs/ adj.过多的","unit":1,"lesson":2,"seq":16,"isStar":false,"memo":"[联想] ex-(往外) + cess(走)→因为他的“过度”消费,他口袋里的钱都往外走了。","example":"These diseases have much to do with excess weight. 这些疾病与超重有很大关系。"},{"id":62,"word":"excessive","pronunciation":"/ɪk'sesɪv/","meaning":"adj.过多的,过度的","unit":1,"lesson":2,"seq":17,"isStar":false,"memo":"[构词] excess(过度) + -ive(形容词后缀)→过多的,过度的","example":"In this city, the excessive rain comes at early spring. 在该市,早春时节雨水过多。"},{"id":63,"word":"recede","pronunciation":"/rɪ'siːd/","meaning":"v.逐渐远去;逐渐减弱;消退","unit":1,"lesson":2,"seq":18,"isStar":false},{"id":64,"word":"recession","pronunciation":"/rɪ'seʃn/","meaning":"n.经济衰退;退后","unit":1,"lesson":2,"seq":0,"isStar":true,"memo":"【构词】re-（回）+ cess-（走）+ -ion → ‘往回走’→经济倒退→衰退；谐音‘瑞信崩’——瑞信一崩，全球 recession！","example":"Many startups struggled to survive during the recent economic recession. 许多初创企业在最近的经济衰退中艰难求生。","derivative":"recessionary /rɪ'seʃənəri/ adj.衰退的；萧条的"},{"id":65,"word":"proceed","pronunciation":"/prə'siːd/","meaning":"v.继续做(或从事、进行);前进","unit":1,"lesson":2,"seq":19,"isStar":false,"memo":"[构词] pro-(往前)+ceed(走)→前进","example":"Out of 20 such requests, six customers proceeded with the purchase. 在20个这样的请求中,有六个客户继续购买。","derivative":"proceeding /prəˈsiːdɪŋ/ n.事件;诉讼"},{"id":66,"word":"proceeding","pronunciation":"/prə'siːdɪŋ/","meaning":"n.事件;诉讼","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":67,"word":"procession","pronunciation":"/prə'seʃn/","meaning":"n.队列;列队行进","unit":1,"lesson":2,"seq":20,"isStar":false,"memo":"[构词] process(列队行进)+-ion(名词后缀)→队列;列队行进","example":"The procession passed right by my front door. 队伍正好从我家门前经过。"},{"id":68,"word":"procedure","pronunciation":"/prə'siːdʒə(r)/","meaning":"n.(正常)程序,步骤;手术","unit":1,"lesson":2,"seq":21,"isStar":false,"memo":"[联想] proced(联想 proceed)+-ure(名词后缀)→他前进的每一步都按“程序”进行。","example":"The next day I repeated the procedure. 第二天我重复了这个步骤。"},{"id":69,"word":"ancestor","pronunciation":"/'ænsestə(r)/","meaning":"n.祖先;原始种型;原型","unit":1,"lesson":2,"seq":22,"isStar":false,"memo":"[联想] an-(一个)+cest(走)+-or(表示人的后缀)→一个走在前面的人→祖先","example":"They call out their ancestors' names. 他们喊出他们祖先的名字。","derivative":"ancestry /ˈænsestri/ n.祖宗,祖先"},{"id":70,"word":"ancestry","pronunciation":"/'ænsestri/","meaning":"n.祖宗,祖先","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":71,"word":"access","pronunciation":"/'ækses/","meaning":"n.进入权;使用权;人口,通道;到达 v.进入;到达;使用;获取","unit":1,"lesson":2,"seq":23,"isStar":false,"memo":"[联想] ac-(一再地)+cess(走)→他一再地走进去→进入","example":"They will be denied access to confidential records. 他们将无权获取机密档案。"},{"id":72,"word":"accessible","pronunciation":"/ək'sesəbl/","meaning":"adj.易到达的;易进入的;易使用的; 易接近的;平易近人的;易懂的","unit":1,"lesson":2,"seq":24,"isStar":false},{"id":73,"word":"accessory","pronunciation":"/ək'sesəri/","meaning":"n.附件,附属品;配件;同谋","unit":1,"lesson":2,"seq":25,"isStar":false,"example":"We stock a large range of bicycle accessories. 我们贮存了各类自行车配件。"},{"id":74,"word":"ascend","pronunciation":"/ə'send/","meaning":"v.上升;登上;晋升","unit":1,"lesson":2,"seq":26,"isStar":false,"memo":"[联想] as-(一再地)+ce(走)+nd→一再地朝上走→上升","example":"Colorful balloons ascended slowly into the sky. 五颜六色的气球慢慢升上天空。","derivative":"ascendancy /ə'sendənsi/ n.优势;支配地位"},{"id":75,"word":"ascendancy","pronunciation":"/ə'sendənsi/","meaning":"n.优势;支配地位","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":76,"word":"soar","pronunciation":"/sɔː(r)/","meaning":"v.急升,猛增;高飞","unit":1,"lesson":2,"seq":27,"isStar":false,"memo":"[谐音] 单词发音类似“嗖”→烟花“嗖”的一声飞上天→急升;高飞","example":"The prices of imported goods will soar. 进口商品的价格将飙升。"},{"id":77,"word":"surge","pronunciation":"/sɜːd/","meaning":"n. & v.急剧上升;激增","unit":1,"lesson":2,"seq":28,"isStar":false,"memo":"[联想] sur-(上面)+ge(联想“哥”)→当你成功时,哥哥对你的赞美次数会“激增”。","example":"Unemployment rate has surged in every occupational category. 失业率在各工种中急剧上升。"},{"id":78,"word":"stable","pronunciation":"/'steɪbl/","meaning":"adj.稳定的,稳固的 n.马厩","unit":1,"lesson":2,"seq":29,"isStar":false,"memo":"[联想] s(联想“似”)+table(桌子)→它的结构似桌子一样稳定→稳定的,稳固的","example":"The current conditions were set fair for stable economic development. 现状适合经济稳定发展。","derivative":"stabilise/-ize /'steɪbəlaz/ v.(使)稳定,稳固\nstability /stə'bləti/ n.稳定(性);稳固(性)"},{"id":79,"word":"stabilise/-ize","pronunciation":"/'steɪbəlaɪz/","meaning":"v.(使)稳定,稳固","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":80,"word":"stability","pronunciation":"/stə'bɪləti/","meaning":"n.稳定(性);稳固(性)","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":81,"word":"descend","pronunciation":"/dɪ'send/","meaning":"v.下降,下来;下斜;降临","unit":1,"lesson":2,"seq":30,"isStar":false,"memo":"[联想] de-(往下)+s+ce(走)+nd→下降","example":"She descended the stairs slowly. 她缓慢地走下楼梯。"},{"id":82,"word":"descent","pronunciation":"/dɪ'sent/","meaning":"n.下降,降落;降临;斜坡;出身","unit":1,"lesson":2,"seq":31,"isStar":false,"memo":"[联想] de-(往下)+scent(音同 sent)→往下发送→下降,降落","example":"The plane began its descent to Heathrow. 飞机开始向希思罗机场降落。"},{"id":83,"word":"descendant","pronunciation":"/dɪ'sendənt/","meaning":"n.后代","unit":1,"lesson":2,"seq":32,"isStar":false,"memo":"[构词] descend(下降;降临)+-ant(表示人的后缀)→接下来的人或即将来临的人→后代","example":"Our descendants might at last live in a world at peace with itself. 我们的后代可能最终生活在一个和平相处的世界里。"},{"id":84,"word":"offspring","pronunciation":"/'ɒfsprɪŋ/","meaning":"n.子女;后代;幼崽","unit":1,"lesson":2,"seq":33,"isStar":false,"example":"His offspring are diligent and intelligent. 他的后代既勤奋又聪明。"},{"id":85,"word":"inherit","pronunciation":"/ɪnherɪt/","meaning":"v.继承(遗产);经遗传获得;接替,继任","unit":1,"lesson":2,"seq":34,"isStar":false,"example":"He has inherited his mother's patience. 他继承了他母亲的耐心。","derivative":"inheritance /ɪnˈhertəns/ n.继承物;遗产;继承"},{"id":86,"word":"inheritance","pronunciation":"/ɪnˈherɪtəns/","meaning":"n.继承物;遗产;继承","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":87,"word":"inherent","pronunciation":"/ɪnˈherənt; ɪnhɪərənt/","meaning":"adj.内在的,固有的","unit":1,"lesson":2,"seq":35,"isStar":false,"memo":"联想 inher(联想 inherit) + -ent(形容词后缀)→经遗传获得的→内在的,固有的","example":"Conflict is inherent in our society. 在我们的社会中冲突是难免的。"},{"id":88,"word":"coherent","pronunciation":"/kəʊˈhɪərənt/","meaning":"adj.连贯的,一致的;有条理的;清楚易懂的","unit":1,"lesson":2,"seq":36,"isStar":false,"memo":"联想 co-(共同) + her(e)(在这儿) + -ent(形容词后缀)→连贯的,一致的","example":"You're not being very coherent. 你的话前后不太一致。","derivative":"coherence /kəʊhɪərəns/ n.连贯性;条理性"},{"id":89,"word":"coherence","pronunciation":"/kəʊˈhɪərəns/","meaning":"n.连贯性;条理性","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":90,"word":"cohesion","pronunciation":"/kəʊhiːʒn/","meaning":"n.黏合,结合;凝聚性","unit":1,"lesson":2,"seq":37,"isStar":false},{"id":91,"word":"cohesive","pronunciation":"/kəʊˈhiːsv/","meaning":"adj.使结合的;使凝结的;有凝聚力的","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":92,"word":"heir","pronunciation":"/eə(r)/","meaning":"n.继承人;后嗣","unit":1,"lesson":2,"seq":38,"isStar":false,"memo":"谐音 单词发音类似“爱儿”→他很爱他的儿子,所以把儿子列为他财产的“继承人”。","example":"He is going to be heir to a large fortune. 他即将成为一大笔财产的继承人。","derivative":"heiress /ˈeərəs; ˈheərəs/ n.女继承人;嗣女"},{"id":93,"word":"heiress","pronunciation":"/eəˈres; ˈeərəs/","meaning":"n.女继承人;嗣女","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":94,"word":"heritage","pronunciation":"/ˈherɪtdʒ/","meaning":"n.遗产","unit":1,"lesson":2,"seq":39,"isStar":false,"memo":"联想 her(她) + it(它) + age(年龄)→她到了一定年龄才能继承它,这是父母留给她的“遗产”。","example":"Everyone can be welcomed on Mauna Kea to embrace their cultural heritage. 欢迎每个人来到莫纳克亚山,拥抱他们的文化遗产。"},{"id":95,"word":"legacy","pronunciation":"/ˈleɡəsi/","meaning":"n.遗产;遗留问题;后遗症","unit":1,"lesson":2,"seq":40,"isStar":false,"memo":"谐音 单词发音类似“赖哥死”→赖哥死后留下了“遗产”。","example":"The invasion left a legacy of hatred and fear. 这次入侵留下的是仇恨和恐惧。"},{"id":96,"word":"gene","pronunciation":"/dʒiːn/","meaning":"n.基因","unit":1,"lesson":2,"seq":41,"isStar":false,"memo":"谐音 单词发音类似“基因”。"},{"id":97,"word":"genetic","pronunciation":"/dəˈnetɪk/","meaning":"adj.基因的;遗传学的","unit":1,"lesson":2,"seq":0,"isStar":true,"derivative":"genetically /dʒəˈnetɪkli/ adv.从遗传学角度；从基因方面"},{"id":98,"word":"genetically","pronunciation":"/dʒəˈnetɪkli/","meaning":"adv.从遗传学角度;从基因方面","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":99,"word":"genre","pronunciation":"/ˈʒɒnrə/","meaning":"n.体裁;类型","unit":1,"lesson":2,"seq":42,"isStar":false},{"id":100,"word":"generate","pronunciation":"/ˈdʒenəreɪt/","meaning":"v.产生;引起","unit":1,"lesson":2,"seq":43,"isStar":false,"memo":"[联想] gene(基因) + rat(老鼠) + e → 老鼠的基因决定了其繁殖能力很强，这会“产生”一些问题。","example":"How is the field generated? 电场是如何产生的？","derivative":"generator /ˈdʒenəreɪtə(r)/ n.发电机；发生器"},{"id":101,"word":"generator","pronunciation":"/ˈdʒenəreɪtə(r)/","meaning":"n.发电机;发生器","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":102,"word":"homogeneous","pronunciation":"/ˌhɒməˈdʒiːniəs/","meaning":"adj.同种类的","unit":1,"lesson":2,"seq":44,"isStar":false,"memo":"[联想] homo-(同一的) + gene(基因) + -ous (形容词后缀) → 同一基因的 → 同种类的","example":"Old people are not a homogeneous group. 老年人不都是同一类型的。"},{"id":103,"word":"degenerate","pronunciation":"/dɪˈdenəreɪt/","meaning":"v.使退化;恶化","unit":1,"lesson":2,"seq":45,"isStar":false,"memo":"[构词] de-(往下，偏离) + generate(产生) → 向下产生，偏离常态 → 使退化；恶化","example":"His health degenerated quickly. 他的健康状况迅速恶化。","derivative":"degeneration /dɪˌdʒenəˈreɪʃn/ n.蜕化；衰退；堕落"},{"id":104,"word":"degeneration","pronunciation":"/dɪdʒenəˈreɪʃn/","meaning":"n.蜕化;衰退;堕落","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":105,"word":"deteriorate","pronunciation":"/dˈtɪəriəreɪt/","meaning":"v.恶化,退化","unit":1,"lesson":2,"seq":46,"isStar":false,"memo":"[联想] de(联想“弟”) + teri(联想“特日”) + o(形似矿井口) + rate → 在这特殊的日子，弟弟想起矿井环境“恶化”前的景象。","example":"If he worked hard, his health would deteriorate. 如果他工作太辛苦，他的健康状况会恶化。","derivative":"deterioration /dɪˌtɪəriəˈreɪʃn/ n.恶化"},{"id":106,"word":"deterioration","pronunciation":"/dɪˌtɪəriəˈreɪʃn/","meaning":"n.恶化","unit":1,"lesson":2,"seq":0,"isStar":true},{"id":107,"word":"terror","pronunciation":"/'terə(r)/","meaning":"n.惊恐,恐惧;恐怖活动","unit":1,"lesson":3,"seq":1,"isStar":false,"memo":"[谐音] 单词发音类似“太弱”→如果一个国家太软弱，它就会对恐怖分子的“恐怖活动”感到“恐惧”。","example":"Her eyes were wild with terror. 她的眼睛里充满了恐惧。","derivative":"terrorism /'terərɪzəm/ n.恐怖主义\nterrorist /'terərɪst/ n.恐怖分子"},{"id":108,"word":"terrorism","pronunciation":"/'terərızəm/","meaning":"n.恐怖主义","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":109,"word":"terrorist","pronunciation":"/'terərist/","meaning":"n.恐怖分子","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":110,"word":"terrify","pronunciation":"/'terıfaı/","meaning":"v.使恐惧,使害怕","unit":1,"lesson":3,"seq":2,"isStar":false,"memo":"[联想] terr(联想 terror) + -ify(动词后缀) →使恐惧,使害怕","example":"They could sometimes terrify adults. 它们有时会吓到成年人。","derivative":"terrible /'terəbl/ adj.可怕的;非常严重的\nterribly /'terəbli/ adv.非常;很"},{"id":111,"word":"terrible","pronunciation":"/'terəbl/","meaning":"adj.可怕的;非常严重的","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":112,"word":"terribly","pronunciation":"/'terəbli/","meaning":"adv.非常,很","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":113,"word":"frighten","pronunciation":"/'fraıtn/","meaning":"v.使惊吓,使惊恐","unit":1,"lesson":3,"seq":3,"isStar":false,"memo":"[对照] 他打架(fight)时用花打人，只是为了使对方惊恐(frighten)。","example":"I didn't mean to frighten you. 我没有吓唬你的意思。","derivative":"fright /fraɪt/ n.惊吓;恐怖"},{"id":114,"word":"fright","pronunciation":"/fraıt/","meaning":"n.惊吓;恐怖","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":115,"word":"embody","pronunciation":"/ım'bɒdi/","meaning":"v.具体表现,体现;代表;包含;收录","unit":1,"lesson":3,"seq":4,"isStar":false,"memo":"[构词] em-(使) + body(身体)→赋予形体，使有形化→体现","example":"They embody the most sophisticated technology. 它们体现了最先进的技术。"},{"id":116,"word":"embed","pronunciation":"/ım'bed/","meaning":"v.把……牢牢地嵌入(或插入、埋入)","unit":1,"lesson":3,"seq":5,"isStar":false,"memo":"[联想] em(音似“一木”) + bed(床)→他把一根木头牢牢地嵌入了床板→把……牢牢地嵌入","example":"Consumption has become a central pillar of life in industrial areas and is even embedded in social values. 消费已成为工业化地区生活的核心支柱，甚至已嵌入社会价值观之中。"},{"id":117,"word":"scare","pronunciation":"/skeə(r)/","meaning":"n.恐慌,惊吓,惊恐 v.害怕;使惊恐","unit":1,"lesson":3,"seq":6,"isStar":false,"example":"Don't you realise what a scare you've given us all? 难道你没有意识到你给我们所有人带来了多大的惊吓吗？","derivative":"scary /'skeəri/ adj.恐怖的;吓人的"},{"id":118,"word":"scary","pronunciation":"/'skeəri/","meaning":"adj.恐怖的,吓人的","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":119,"word":"panic","pronunciation":"/'pænık/","meaning":"n.惊慌,恐慌 v.(使)恐慌","unit":1,"lesson":3,"seq":7,"isStar":false,"memo":"[联想] pa(联想“怕”) + ni(联想“你”) + c (音似“磕”)→小时候，奶奶很怕你磕到→恐慌","example":"They were in a state of panic. 他们处于恐慌的状态中。"},{"id":120,"word":"deter","pronunciation":"/dı'tɜ:(r)/","meaning":"v.制止,阻止;威慑,使不敢","unit":1,"lesson":3,"seq":8,"isStar":false,"memo":"谐音：单词发音类似“弟特”→弟弟特别淘气，总是做出格的事，我要及时“制止”他。","example":"Will this harsher punishment effectively deter criminals? 这种更严厉的惩罚能有效威慑罪犯吗？","derivative":"deterrent /dɪˈtɜːrənt/ n.威慑物 adj.威慑的；制止的"},{"id":121,"word":"deterrent","pronunciation":"/dı'terənt/","meaning":"n.威慑物 adj.威慑的;制止的","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":122,"word":"alert","pronunciation":"/ə'lɜ:t/","meaning":"n.警报;警戒,警惕 adj.警觉的,警惕的 v.向……报警,使警觉","unit":1,"lesson":3,"seq":9,"isStar":false,"memo":"联想：a(一个) + ler(音似“乐”) + t(联想“他”)→他是一个很“警惕的”人，少有快乐时光。","example":"There is a bomb alert on the rail link. 铁路线上有炸弹警报。"},{"id":123,"word":"caution","pronunciation":"/'kɔːʃn/","meaning":"n.小心,谨慎;警告 v.警告","unit":1,"lesson":3,"seq":10,"isStar":false,"memo":"谐音：单词发音类似“靠心”→走路时要靠心，保持“谨慎”，以免摔倒。","example":"She got off with a caution. 她受到了警告。","derivative":"cautious /ˈkɔːʃəs/ adj.谨慎的，小心的"},{"id":124,"word":"cautious","pronunciation":"/'kɔ:ʃəs/","meaning":"adj.谨慎的,小心的","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":125,"word":"precaution","pronunciation":"/prɪ'kɔːʃn/","meaning":"n.预防措施,防备","unit":1,"lesson":3,"seq":11,"isStar":false,"memo":"构词：pre-(提前) + caution(小心)→预防措施，防备","example":"I hope all the precautions against air pollution will be seriously considered. 我希望所有预防空气污染的措施都被认真考虑。","derivative":"precautionary /priˈkɔːʃənəri/ adj.预先警戒的；小心的"},{"id":126,"word":"precautionary","pronunciation":"/prı'kɔ:ʃənəri/","meaning":"adj.预先警戒的;小心的","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":127,"word":"rise","pronunciation":"/raız/","meaning":"n.上涨,增高 v.上升,增长;起身;起义","unit":1,"lesson":3,"seq":12,"isStar":false,"memo":"联想：ri(联想“日”) + se(联想“色”)→等太阳升起后，我们会在山顶上看到别样的景色→上升","example":"Everybody loves a fat pay rise. 人人都喜欢大幅涨薪。"},{"id":128,"word":"arise","pronunciation":"/ə'raɪz/","meaning":"v.出现;产生;起身","unit":1,"lesson":3,"seq":13,"isStar":false,"memo":"对照：后羿射日的故事中，十个太阳本应轮流上升(rise)到天空中，但是后来同时出现(arise)了。","example":"They arise from the advances in technology. 它们源于技术的进步。"},{"id":129,"word":"arouse","pronunciation":"/ə'raʊz/","meaning":"v.唤醒;引起,激起","unit":1,"lesson":3,"seq":14,"isStar":false,"memo":"联想：a-(一再地) + rouse(音似“热死”)→十个太阳同现后，一再地热死人，“引起”了大家的反感。"},{"id":130,"word":"arousal","pronunciation":"/ə'raʊzl/","meaning":"n.激起,引起(感情、态度)","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":131,"word":"raise","pronunciation":"/rez/","meaning":"v.提高,增加;举起;筹集;引起,导致; 养育","unit":1,"lesson":3,"seq":15,"isStar":false,"memo":"[对照] 十个太阳同时出现(arise)在天空,后羿举起(raise)手表示要去射掉其中九个太阳。","example":"They have raised fund to improve the road condition. 他们已筹集资金来改善道路状况。"},{"id":132,"word":"uprising","pronunciation":"/'praɪzɪŋ/","meaning":"n.起义,暴动","unit":1,"lesson":3,"seq":16,"isStar":false},{"id":133,"word":"praise","pronunciation":"/preɪz/","meaning":"n. & v.称赞,赞美,表扬","unit":1,"lesson":3,"seq":17,"isStar":false,"example":"She was praised for her hard work. 她因努力工作而受到表扬。"},{"id":134,"word":"compliment","pronunciation":"/'kɒmplɪmənt/","meaning":"n.赞扬,称赞 /'kɒmplment/ v.赞扬,称赞","unit":1,"lesson":3,"seq":18,"isStar":false,"memo":"[联想] com-(所有)+p(联想“扑”)+li(联想“立”)+men(联想“门”)+t→所有人扑向门口,“赞扬”打虎归来立在门口的武松。","example":"She received several compliments on her speech. 她的演讲得到了一些人的称赞。","derivative":"complimentary /ˌkɒmplɪ'mentri/ adj.表示钦佩的;赞美的"},{"id":135,"word":"complimentary","pronunciation":"/ˌkɒmpl'mentri/","meaning":"adj.表示钦佩的;赞美的","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":136,"word":"appraise","pronunciation":"/ə'preɪz/","meaning":"v.估量;评估;估价;作出评价","unit":1,"lesson":3,"seq":19,"isStar":false,"memo":"[构词] ap-(去)+prais(价格,价值)+-e→去给出价格→评估;估价","example":"He stepped back to appraise his workmanship. 他后退一步,评估自己的手艺。","derivative":"appraisal /ə'preɪzl/ n.评价;估价"},{"id":137,"word":"appraisal","pronunciation":"/ə'preɪzl/","meaning":"n.评价;估价","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":138,"word":"prize","pronunciation":"/praɪz/","meaning":"n.奖品,奖赏 v.珍视,高度重视","unit":1,"lesson":3,"seq":20,"isStar":false,"example":"She won the 1945 Nobel Prize in Literature. 她获得了1945年的诺贝尔文学奖。"},{"id":139,"word":"comprise","pronunciation":"/kəm'praɪz/","meaning":"v.包括,包含;由……组成","unit":1,"lesson":3,"seq":21,"isStar":false,"memo":"[联想] com-(一起)+prise(音同 prize)→“包括”我在内,全班同学都得到了奖品。","example":"The main labor force is comprised of students working part-time. 主要劳动力是由兼职工作的学生组成的。"},{"id":140,"word":"award","pronunciation":"/ə'wɔːd/","meaning":"n.奖品;奖金 v.授予;给予奖励","unit":1,"lesson":3,"seq":22,"isStar":false,"memo":"[谐音] 单词发音类似“a word”→快要下课了,老师多讲了一个表示“奖品”的单词。","example":"You could apply for an award if you have a patent. 如果你有一项专利,你就可以申请一笔奖金。"},{"id":141,"word":"reward","pronunciation":"/rɪ'wɔːd/","meaning":"n.奖励;回报;报酬 v.奖赏;给以报酬","unit":1,"lesson":3,"seq":23,"isStar":false,"memo":"[联想] re-(回)+ward(音似 word)→作为“回报”,学生也给老师讲了个单词。","example":"Rewards can improve performance at work and school. 奖励可以改进工作和学校的表现。","derivative":"rewarding /rɪ'wɔːdɪŋ/ adj.值得的;有益的"},{"id":142,"word":"rewarding","pronunciation":"/rɪ'wɔːdɪŋ/","meaning":"adj.值得的;有益的","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":143,"word":"ward","pronunciation":"/wɔːd/","meaning":"n.病房 v.防止,避免","unit":1,"lesson":3,"seq":24,"isStar":false,"memo":"[对照] 战争(war)中的医院会设置很多病房(ward)。","example":"We have one bed available in Ward 3. 我们3号病房还有一张空床。"},{"id":144,"word":"trophy","pronunciation":"/'trəʊfi/","meaning":"n.奖品;奖杯;战利品","unit":1,"lesson":3,"seq":25,"isStar":false},{"id":145,"word":"catastrophe","pronunciation":"/kə'tæstrəfi/","meaning":"n.灾难,灾祸;困难","unit":1,"lesson":3,"seq":26,"isStar":false,"memo":"联想 cat(猫) + as + trophe(联想 trophy)→“灾难”过后,这只猫因为救了同类而得到了奖品。","example":"It is a psychological catastrophe. 这是一场心理灾难。","derivative":"catastrophic /ˌkætəˈstrɒfk/ adj.灾难性的"},{"id":146,"word":"catastrophic","pronunciation":"/ˌkætə'strɒfk/","meaning":"adj.灾难性的","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":147,"word":"applaud","pronunciation":"/ə'plɔd/","meaning":"v.称赞;鼓掌,拍手喝彩","unit":1,"lesson":3,"seq":27,"isStar":false,"memo":"联想 ap-(一再地) + p(联想“扑”) + laud (音似“老的”)→小狮子一再地扑向大老虎,大家都为它的勇敢“鼓掌”。","example":"For the first time, my father applauded my hard work. 我父亲第一次称赞我的努力工作。","derivative":"applause /əˈplɔːz/ n.掌声;喝彩"},{"id":148,"word":"applause","pronunciation":"/ə'plɔːz/","meaning":"n.掌声;喝彩","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":149,"word":"celebrate","pronunciation":"/'selbreɪt/","meaning":"v.庆祝,庆贺;赞美,颂扬","unit":1,"lesson":3,"seq":28,"isStar":false,"memo":"联想 cele(音似“赛了”) + br(联想“必然”) + ate(cat 的过去式)→比赛完了必然要吃一顿,“庆祝”一下。","example":"Women's progress can be celebrated across a range of fields. 女性在各个领域取得的进步都值得庆祝。"},{"id":150,"word":"celebration","pronunciation":"/ˌselɪˈbreɪn/","meaning":"n.庆典;庆祝活动","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":151,"word":"celebrity","pronunciation":"/səˈlebrəti/","meaning":"n.名人,名流;名望,名誉;著名","unit":1,"lesson":3,"seq":29,"isStar":false},{"id":152,"word":"ceremony","pronunciation":"/ˈserəməni/","meaning":"n.仪式,典礼","unit":1,"lesson":3,"seq":30,"isStar":false,"memo":"谐音 单词发音类似“赛罗蒙你”→赛罗说为你举行一个“典礼”,结果蒙(骗)了你。","example":"Many people attended the ceremony. 很多人出席了该仪式。","derivative":"ceremonial /ˌserɪˈməʊniəl/ adj.礼仪的;礼节的"},{"id":153,"word":"ceremonial","pronunciation":"/ˌserɪˈməʊniəl/","meaning":"adj.礼仪的;礼节的","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":154,"word":"ritual","pronunciation":"/ˈrɪtʃuəl/","meaning":"n.仪式,仪规,礼节;习惯","unit":1,"lesson":3,"seq":31,"isStar":false,"memo":"谐音 单词发音类似“瑞秋”→瑞秋在举行“仪式”。","example":"She objects to the ritual of organised religion. 她反对有组织宗教的仪规。"},{"id":155,"word":"uphold","pronunciation":"/ʌphəʊld/","meaning":"v.支持,维护;维持(原判)","unit":1,"lesson":3,"seq":32,"isStar":false,"memo":"构词 up-(向上) + hold(持有)→支持,维护\n对照 hold up 举起;支持→uphold v.","example":"We have a duty to uphold the law. 维护法律是我们的责任。"},{"id":156,"word":"hoist","pronunciation":"/hɔɪst/","meaning":"n.起重机;吊车 v.吊起,升起,提起","unit":1,"lesson":3,"seq":33,"isStar":false,"memo":"联想 ho(联想 hold) + -ist(后缀)→抓住东西使其升起的设备→起重机"},{"id":157,"word":"elevate","pronunciation":"/ˈelɪveɪt/","meaning":"v.举起,抬起;提拔,晋升;提升","unit":1,"lesson":3,"seq":34,"isStar":false,"memo":"谐音 单词发音类似“爱丽喂特”→爱丽要喂特高的巨人吃饭,必须踮起脚尖,并“举起”手臂。","example":"I built a platform to elevate the bed. 我搭了一个台子,把床抬高了。","derivative":"elevator /'eliveitə(r)/ n.电梯;升降机 elevation /eli'veifn/ n.升高;提拔;提升"},{"id":158,"word":"elevator","pronunciation":"/ˈelɪveɪtə(r)/","meaning":"n.电梯;升降机","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":159,"word":"elevation","pronunciation":"/ˌelɪˈveɪʃn/","meaning":"n.升高;提拔;提升","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":160,"word":"eligible","pronunciation":"/elɪdʒəbl/","meaning":"adj.有资格的;合格的;合适的","unit":1,"lesson":3,"seq":35,"isStar":false,"memo":"联想 eli(音似“爱丽”)+g(联想“格”)+ -ible(形容词后缀)→爱丽是一名“合格的”员工。","example":"They are not eligible for a student loan. 他们没有资格申请学生贷款。","derivative":"eligibility /elidʒə'bɪləti/ n.资格;合格"},{"id":161,"word":"eligibility","pronunciation":"/elɪdʒəbɪləti/","meaning":"n.资格;合格","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":162,"word":"element","pronunciation":"/ˈelɪmənt/","meaning":"n.元素;因素,要素","unit":1,"lesson":3,"seq":36,"isStar":false,"memo":"联想 elemen(音似“爱丽妹”)+t→爱丽的妹妹知道,成功需要很多“因素”。","example":"Cost was a key element in our decision. 成本是我们决策时考虑的一个重要因素。","derivative":"elementary /elɪ'mentri/ adj.基本的;初级的"},{"id":163,"word":"elementary","pronunciation":"/ˌelɪˈmentri/","meaning":"adj.基本的;初级的","unit":1,"lesson":3,"seq":0,"isStar":true,"memo":"element（元素）+ -ary（…的）→化学课上‘元素级’知识！adj.基础的，像ABC一样‘原初又简单’。","example":"Elementary coding skills are now required across disciplines. 基础编程能力如今已成为各学科的必备技能。"},{"id":164,"word":"factor","pronunciation":"/fæktə(r)/","meaning":"n.因素,要素 v.把……化为因素","unit":1,"lesson":3,"seq":37,"isStar":false,"memo":"联想 fact(事实)+-or(后缀)→影响事实的东西→因素,要素","example":"Obesity is a major risk factor for heart disease. 肥胖是心脏病的主要风险因素。"},{"id":165,"word":"ingredient","pronunciation":"/ɪnˈɡridiənt/","meaning":"n.成分,原料;因素,要素","unit":1,"lesson":3,"seq":38,"isStar":false,"memo":"联想 in(里面)+gredi(联想“搁点”)+ent (联想 enter)→做饭时要往锅里搁(放)“原料”。","example":"Topsoil contains few of the ingredients needed for farming. 表层土壤含有少量耕作所必需的成分。"},{"id":166,"word":"ally","pronunciation":"/ˈælaɪ/","meaning":"n.同盟国;盟友 /əlaɪ; ˈælaɪ/ v.与……结盟","unit":1,"lesson":3,"seq":39,"isStar":false,"memo":"谐音 单词发音类似“爱莱”→爱莱是我的“盟友”。","example":"She will regret losing a close political ally. 她将为失去一个亲密的政治盟友而懊悔。","derivative":"alliance /ə'laəns/ n.联盟"},{"id":167,"word":"alliance","pronunciation":"/əˈlaɪəns/","meaning":"n.联盟","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":168,"word":"coalition","pronunciation":"/ˌkəəˈlɪʃn/","meaning":"n.联合政府;联合体,联盟;联合","unit":1,"lesson":3,"seq":40,"isStar":false,"memo":"谐音 单词发音类似“靠我累心”→只依靠我太心累,组成“联盟”才高效。","example":"It will be able to put together a governing coalition. 它将能够组建一个执政联盟。"},{"id":169,"word":"log","pronunciation":"/lɒɡ/","meaning":"n.原木;航海日志;日记 v.记录;行驶;伐木","unit":1,"lesson":3,"seq":41,"isStar":false,"memo":"谐音 单词发音类似“捞个”→他从河里捞上来一块“原木”。"},{"id":170,"word":"barrier","pronunciation":"/ˈbæriə(r)/","meaning":"n.屏障,障碍物;关卡;分界线;隔阂","unit":1,"lesson":3,"seq":42,"isStar":false,"memo":"联想 bar(棒,木条)+rier→用木条做的东西→屏障,障碍物","example":"They have some barriers on their way to academic success. 他们在取得学术成功的道路上有一些障碍。"},{"id":171,"word":"timber","pronunciation":"/ˈtmbə(r)/","meaning":"n.树木,林木;木材,木料","unit":1,"lesson":3,"seq":43,"isStar":false,"memo":"谐音 单词发音类似“挺拔”→“林木”很挺拔。","example":"Timber was still cheap because it could be brought in any quantity from distant woodlands. 木材仍然很便宜,因为可以从遥远的森林里大量地运送过来。"},{"id":172,"word":"embarrass","pronunciation":"/ɪmˈbærəs/","meaning":"v.使尴尬,使难堪","unit":1,"lesson":3,"seq":44,"isStar":false,"memo":"联想 em-(使)+bar(木条)+r+ass(屁股)→他调皮时,妈妈吓唬他要拿木条打他的屁股,这使他很尴尬→使尴尬","example":"The speech was a deliberate attempt to embarrass him. 这一发言蓄意使他难堪。","derivative":"embarrassment /m'bærəsmənt/ n. 尴尬,困境"},{"id":173,"word":"embarrassment","pronunciation":"/ɪmˈbærəsmənt/","meaning":"n.尴尬,困境","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":174,"word":"awkward","pronunciation":"/ˈɔːkwəd/","meaning":"adj.令人尴尬的;笨拙的","unit":1,"lesson":3,"seq":45,"isStar":false,"memo":"联想 awk(音似“拗口”)+ward(音似 word)→他读错了一个拗口的单词,那场面真是“令人尴尬的”。","example":"There was an awkward silence. 有一阵令人尴尬的沉寂。"},{"id":175,"word":"barren","pronunciation":"/ˈbærən/","meaning":"adj.贫瘠的;不育的;不结果实的;无效果的","unit":1,"lesson":3,"seq":46,"isStar":false,"memo":"联想 bar(木条)+ren(联想“人”)→那个人用木条围起来一块“贫瘠的”土地。","example":"Many people think of deserts as barren regions. 许多人认为沙漠是贫瘠地区。"},{"id":176,"word":"bargain","pronunciation":"/ˈbɑːɡən/","meaning":"n.便宜货,协议;交易 v.讨价还价","unit":1,"lesson":3,"seq":47,"isStar":false,"memo":"联想 bar(木条)+gain(得到)→他用木条指着别人卖的东西说想要得到它,于是便开始“讨价还价”。","example":"In fact, the bargain is very pure. 事实上,这种交易非常纯粹。"},{"id":177,"word":"bare","pronunciation":"/beə(r)/","meaning":"adj.赤裸的,裸露的;光秃秃的v.揭开;脱掉","unit":1,"lesson":3,"seq":48,"isStar":false,"memo":"联想 bar(木条)+e(字母音似“姨”)→木条划破了阿姨的衣袖,使她露出了胳膊→裸露的","example":"I got in the habit of going around with bare feet. 我养成了赤脚走路的习惯。","derivative":"barely /'beəli/ adv. 仅仅;勉强可能;几乎不"},{"id":178,"word":"barely","pronunciation":"/ˈbeəli/","meaning":"adv.仅仅;勉强可能;几乎不","unit":1,"lesson":3,"seq":0,"isStar":true},{"id":179,"word":"bald","pronunciation":"/bɔːld/","meaning":"adj.秃头的;光秃秃的;简单的;直截了当的","unit":1,"lesson":3,"seq":49,"isStar":false,"memo":"联想 bal(联想 ball)+d(联想“的”)→那个球面很光滑,没有毛刺,“光秃秃的”。","example":"He started going bald in his twenties. 他二十几岁便开始谢顶。"},{"id":180,"word":"bold","pronunciation":"/bəʊld/","meaning":"adj.勇敢的,大胆的;鲁莽的","unit":1,"lesson":3,"seq":50,"isStar":false,"memo":"联想 b(联想“不”)+old(老的)→不老的人(年轻人)具有冒险精神,做事往往是“大胆的”。","example":"She knew she had to make a bold move to fully commit to her new future. 她知道她必须采取大胆的行动,全身心地投入她的新未来。"},{"id":181,"word":"cricket","pronunciation":"/krɪkɪt/","meaning":"n.板球(运动);蟋蟀","unit":1,"lesson":3,"seq":51,"isStar":false,"memo":"联想 cr(联想“超人”)+i(我)+cket(音似“剋它”)→超人和我剋(打)它→板球","example":"The standard of professional cricket has never been lower. 职业板球的标准从来没这么低过。"},{"id":182,"word":"emerge","pronunciation":"/ɪ'mɜːdʒ/","meaning":"v.出现,浮现;暴露;幸存下来","unit":1,"lesson":4,"seq":1,"isStar":false,"memo":"联想 e-(出来) + merge(音似“磨叽”)→妈妈让他别磨叽了,赶紧出来吃饭→出现","example":"He finally emerged from his room. 他终于从房间里出来了。","derivative":"emergence /ɪˈmɜdʒəns/ n.出现"},{"id":183,"word":"emergence","pronunciation":"/imɜːdʒəns/","meaning":"n.出现","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":184,"word":"emergency","pronunciation":"/imɜːdʒənsi/","meaning":"n.突发事件,紧急情况 adj.紧急的","unit":1,"lesson":4,"seq":2,"isStar":false,"memo":"构词 emerg(出现) + -ency(后缀)→突然出现的事→突发事件,紧急情况","example":"Employees should be fully acquainted with emergency procedures. 雇员们应当十分熟悉应急措施。"},{"id":185,"word":"urgent","pronunciation":"/ˈɜːdʒənt/","meaning":"adj.紧急的,急切的","unit":1,"lesson":4,"seq":3,"isStar":false,"memo":"谐音 单词发音类似“饿紧它”→他太饿了,急切地需要食物→紧急的,急切的","example":"He was called away for some urgent business abroad. 他因国外的一些紧急事务被叫走了。","derivative":"urgency /ˈɜdʒənsi/ n.紧急,迫切"},{"id":186,"word":"urgency","pronunciation":"/ˈɜːdʒənsi/","meaning":"n.紧急,迫切","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":187,"word":"haste","pronunciation":"/heɪst/","meaning":"n.匆忙,仓促","unit":1,"lesson":4,"seq":4,"isStar":false,"memo":"谐音 单词发音类似“恨死他”→她被骗后恨死他了,就“匆忙”离开了他。","example":"Haste makes waste. 欲速则不达。"},{"id":188,"word":"hasten","pronunciation":"/heɪsn/","meaning":"v.促进,使加快","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":189,"word":"hasty","pronunciation":"/ˈhesti/","meaning":"adj.匆忙的;草率的","unit":1,"lesson":4,"seq":5,"isStar":false,"example":"They had to eat a hasty meal, or they would be too late for the concert. 他们不得不匆匆吃顿饭,否则就赶不上音乐会了。"},{"id":190,"word":"submerge","pronunciation":"/səbˈmɜːdʒ/","meaning":"v.淹没,浸没;掩盖","unit":1,"lesson":4,"seq":6,"isStar":false,"memo":"联想 sub-(在下面) + merge(联想 emerge)→在下面出现→淹没","example":"The region will be submerged. 这个地区将被淹没。"},{"id":191,"word":"submarine","pronunciation":"/ˌsʌbməˈriːn; 'sʌbməriːn/","meaning":"n.潜艇 adj.海底的;水下的","unit":1,"lesson":4,"seq":7,"isStar":false,"memo":"构词 sub-(在下面) + marine(海洋的)→海底的","example":"We were trying to plot the course of the submarine. 我们当时正试图标绘出那艘潜艇的航线。"},{"id":192,"word":"marine","pronunciation":"/məˈriːn/","meaning":"adj.海洋的","unit":1,"lesson":4,"seq":8,"isStar":false,"example":"Marine biologists are looking for the secret of turtles’ reproduction. 海洋生物学家正在寻找海龟繁殖的秘密。"},{"id":193,"word":"swamp","pronunciation":"/swɒmp/","meaning":"v.使陷入;淹没 n.沼泽(地)","unit":1,"lesson":4,"seq":9,"isStar":false,"memo":"联想 swam (swim 的过去式) + p (联想“扑”)→他扑到水里游泳,被水“淹没”了。"},{"id":194,"word":"overwhelm","pronunciation":"/ˌəʊvəˈwelm/","meaning":"v.压倒;击败;难以承受;淹没","unit":1,"lesson":4,"seq":10,"isStar":false,"memo":"[联想] over(上面)+whel(联想 wheel)+m(联想 me)→上面的轮子把我“压倒”了。","example":"The little boat was swamped by the waves. 小船被大浪淹没了。\nAt that moment, grief overwhelmed me. 那时，我不胜悲伤。","derivative":"overwhelming /ˌəʊvəwelmɪŋ/ adj.巨大的;压倒性的\noverwhelmingly /ˌəʊvəwelmɪŋli/ adv.巨大地;压倒性地"},{"id":195,"word":"overwhelming","pronunciation":"/ˌəʊvəˈwelmɪŋ/","meaning":"adj.巨大的;压倒性的","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":196,"word":"overwhelmingly","pronunciation":"/ˌəʊvəˈwelmɪŋli/","meaning":"adv.巨大地;压倒性地","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":197,"word":"reel","pronunciation":"/riːl/","meaning":"n.卷轴;卷盘;卷筒 v.眩晕,天旋地转","unit":1,"lesson":4,"seq":11,"isStar":false,"memo":"[对照] 轮子(wheel)一直旋转,让人眩晕(reel)。","example":"When he opened his eyes, the room was reeling. 他睁开眼睛时,房间在旋转。"},{"id":198,"word":"adore","pronunciation":"/əˈdɔː(r)/","meaning":"v.爱慕;热爱","unit":1,"lesson":4,"seq":12,"isStar":false},{"id":199,"word":"adorable","pronunciation":"/əˈdɔːrəbl/","meaning":"adj.可爱的;讨人喜爱的","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":200,"word":"admire","pronunciation":"/ədˈmaɪə(r)/","meaning":"v.赞美;欣赏;钦佩","unit":1,"lesson":4,"seq":13,"isStar":false,"memo":"[联想] ad-(一再地)+m(联想“妹”)+i(我)+re(字母音似“阿姨”)→妹妹和我一再地围着阿姨,因为我们都很“钦佩”她。","example":"She admired his beautiful blue eyes. 她羡慕他那双美丽的蓝眼睛。","derivative":"admirable /ˈædmərəbl/ adj.值得赞赏的,可钦佩的"},{"id":201,"word":"admirable","pronunciation":"/ˈædmərəbl/","meaning":"adj.值得赞赏的,可钦佩的","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":202,"word":"eradicate","pronunciation":"/ɪˈrædkeɪt/","meaning":"v.根除,消灭;杜绝","unit":1,"lesson":4,"seq":14,"isStar":false,"memo":"[联想] e(字母音似“姨”) + ra(联想“让”) + di(联想“弟”) + cate(音似“它”)→阿姨让弟弟剋它(打苍蝇)→根除,消灭","example":"We will aim to finally eradicate disease and poverty. 我们的最终目标是根除疾病和贫穷。","derivative":"eradication /ɪˌrædɪˈkeɪn/ n.根除;消灭;杜绝"},{"id":203,"word":"eradication","pronunciation":"/ɪˌrædɪˈkeʃn/","meaning":"n.根除;消灭;杜绝","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":204,"word":"refrain","pronunciation":"/rɪfreɪn/","meaning":"v.克制;避免 n.经常重复的评价","unit":1,"lesson":4,"seq":15,"isStar":false,"memo":"[联想] re(字母音似“阿姨”) + frain(音似“夫人”)→阿姨要和那位夫人去旅行了,我舍不得她离开,但我“克制”住了。","example":"Please refrain from smoking. 请勿吸烟。"},{"id":205,"word":"regulate","pronunciation":"/'regjuleɪt/","meaning":"v.控制,管理;调整,调节","unit":1,"lesson":4,"seq":16,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + gu(联想“故”) + late(迟到)→阿姨因故迟到，她的秘书马上“调整”了会议的流程。","example":"Their emotions were much harder to regulate. 他们的情绪很难调节。","derivative":"regulation /ˌregju'leɪʃn/ n.规则；条例\nregulator /'regjuleɪtə(r)/ n.监管者；调节器\nregulatory /'regjələtəri/ adj.具有监管权的，监管的"},{"id":206,"word":"regulation","pronunciation":"/ˌregjuˈleɪʃn/","meaning":"n.规则;条例","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":207,"word":"regulator","pronunciation":"/'regjuleɪtə(r)/","meaning":"n.监管者;调节器","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":208,"word":"regulatory","pronunciation":"/'regjələtəri/","meaning":"adj.具有监管权的,监管的","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":209,"word":"regular","pronunciation":"/'regjələ(r)/","meaning":"adj.规则的;有规律的 n.常客","unit":1,"lesson":4,"seq":17,"isStar":false,"memo":"对照 regulate v.控制，管理；调整，调节→ regular adj. & n.","example":"We hold a regular monthly meeting. 我们每月定期举行会议。","derivative":"regularity /ˌregju'lærəti/ n.规律性；经常性；有规律的事物"},{"id":210,"word":"regularity","pronunciation":"/ˌregjuˈlærəti/","meaning":"n.规律性;经常性;有规律的事物","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":211,"word":"irregular","pronunciation":"/ɪ'regjələ(r)/","meaning":"adj.不整齐的;不规则的;不正常的","unit":1,"lesson":4,"seq":18,"isStar":false,"example":"He had bad teeth, which were irregular. 他的牙齿不好，参差不齐。"},{"id":212,"word":"deregulate","pronunciation":"/ˌdiː'regjuleɪt/","meaning":"v.解除控制,撤销管制","unit":1,"lesson":4,"seq":19,"isStar":false},{"id":213,"word":"deregulation","pronunciation":"/diːreɡjuˈleɪʃn/","meaning":"n.解除控制","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":214,"word":"relate","pronunciation":"/rɪˈleɪt/","meaning":"v.有联系,有关联;讲述","unit":1,"lesson":4,"seq":20,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + late(迟到)→阿姨迟到了，她要向我“讲述”理由，因为我们“有关联”。","example":"It is directly related to your commitment. 这直接关系到你的承诺。"},{"id":215,"word":"relation","pronunciation":"/rɪˈleɪʃn/","meaning":"n.关系,联系;亲属","unit":1,"lesson":4,"seq":0,"isStar":true,"derivative":"relationship /rɪ'leɪʃnʃɪp/ n.关系，联系"},{"id":216,"word":"relationship","pronunciation":"/rɪˈleɪʃnɪp/","meaning":"n.关系,联系","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":217,"word":"relative","pronunciation":"/ˈrelətɪv/","meaning":"n.亲戚,亲属 adj.相关联的;比较的,相对的","unit":1,"lesson":4,"seq":21,"isStar":false,"example":"Mary is going to get a little dog from one of her relatives. 玛丽打算从她的一个亲戚那里领养一只小狗。","derivative":"relativity /ˌrelə'tɪvəti/ n.相对论；相对性"},{"id":218,"word":"relativity","pronunciation":"/reləˈtɪvəti/","meaning":"n.相对论;相对性","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":219,"word":"correlate","pronunciation":"/ˈkɒrəleɪt/","meaning":"v.相互关联影响;相互依赖","unit":1,"lesson":4,"seq":22,"isStar":false,"memo":"构词 cor-( = com-, 共同) + relate (有关联)→相互关联影响","example":"The figures do not seem to correlate. 这些数字似乎毫不相干。","derivative":"correlation /ˌkɒrə'leɪʃn/ n.相关；关联\ncorrelative /kə'rælətɪv/ adj.密切相关的；互相依赖的"},{"id":220,"word":"correlation","pronunciation":"/ˌkɒrəˈleɪʃn/","meaning":"n.相关;关联","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":221,"word":"correlative","pronunciation":"/kərelətɪv/","meaning":"adj.密切相关的;互相依赖的","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":222,"word":"resort","pronunciation":"/rˈzɔːt/","meaning":"n.求助;旅游胜地 v.(~to)求助于,诉诸","unit":1,"lesson":4,"seq":23,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + sort(分类)→阿姨让她把各种豆子分类后才能出去，她却“求助”他人。","example":"Meetings at resorts are suddenly unacceptable. 在旅游胜地开会突然变得不可接受。"},{"id":223,"word":"haunt","pronunciation":"/hɔːnt/","meaning":"v.萦绕于脑际,使难以忘却 n.常去的地方","unit":1,"lesson":4,"seq":24,"isStar":false,"example":"For years she was haunted by guilt. 多年来她一直感到愧疚。"},{"id":224,"word":"hound","pronunciation":"/haʊnd/","meaning":"n.猎(狐)犬 v.追踪;追逐;纠缠","unit":1,"lesson":4,"seq":25,"isStar":false},{"id":225,"word":"forth","pronunciation":"/fɔːθ/","meaning":"adv.向前;往外","unit":1,"lesson":4,"seq":26,"isStar":false,"memo":"[联想] for(为了)+th(音似“死”)→他“不见黄河心不死”,誓要“向前”达成目标。","example":"They set forth at dawn. 他们黎明时出发了。"},{"id":226,"word":"forthcoming","pronunciation":"/ˌfɔːθ'kʌmɪŋ/","meaning":"adj.即将发生的,即将出现的","unit":1,"lesson":4,"seq":27,"isStar":false,"memo":"[构词] forth(向前)+coming(到来)→前面要到来的→即将发生的","example":"Financial support was not forthcoming. 财政支援尚未到手。"},{"id":227,"word":"forecast","pronunciation":"/'fɔːkɑːst/","meaning":"n. & v.预测,预报","unit":1,"lesson":4,"seq":28,"isStar":false,"memo":"[构词] fore-(先,前)+cast(投)→事情发生之前就投出来→预测,预报","example":"Experts are forecasting a recovery in the economy. 专家预测经济将复苏。"},{"id":228,"word":"cast","pronunciation":"/kɑːst/","meaning":"v.投射;扔;浇铸 n.演员表,全体演员;投,抛","unit":1,"lesson":4,"seq":29,"isStar":false,"example":"I cast an angry look at him. 我愤怒地看着他。"},{"id":229,"word":"broadcast","pronunciation":"/ˈbrɔːdkɑːst/","meaning":"v.广播;散布,传播 n.广播节目","unit":1,"lesson":4,"seq":30,"isStar":false,"memo":"[构词] broad(宽阔的,广泛的)+cast(投)→广播;散布","example":"Broadcasting his ambition was very much his decision. 宣扬他的抱负在很大程度上是他的决定。"},{"id":230,"word":"foretell","pronunciation":"/fɔːˈtel/","meaning":"v.预言,预测","unit":1,"lesson":4,"seq":31,"isStar":false},{"id":231,"word":"foremost","pronunciation":"/'fɔːməʊst/","meaning":"adj.最重要的;最前的 adv.首先","unit":1,"lesson":4,"seq":32,"isStar":false,"memo":"[构词] fore-(先,前)+most(最)→最重要的;最前的","example":"This question has been foremost in our minds recently. 近来,我们心中一直认为这个问题最重要。"},{"id":232,"word":"beforehand","pronunciation":"/bɪˈfɔhænd/","meaning":"adv.预先,事先","unit":1,"lesson":4,"seq":33,"isStar":false,"memo":"[构词] before(在……之前)+hand(手)→我们习惯于在着手做一件事之前要“预先”做准备。","example":"They make careful preparations beforehand. 他们事先做了周密的准备。"},{"id":233,"word":"foresee","pronunciation":"/fɔːˈsiː/","meaning":"v.预料,预见,预知","unit":1,"lesson":4,"seq":34,"isStar":false,"memo":"[构词] fore-(先,前)+see(看见)→预料,预见,预知","example":"He failed to foresee major problems. 他没能预见到主要问题。","derivative":"foreseeable /fɔːˈsiːəbl/ adj.可预见的,可预知的"},{"id":234,"word":"foreseeable","pronunciation":"/fɔːˈsiːəbl/","meaning":"adj.可预见的,可预知的","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":235,"word":"foresight","pronunciation":"/'fɔːsaɪt/","meaning":"n.深谋远虑,先见之明","unit":1,"lesson":4,"seq":35,"isStar":false,"memo":"构词 forc-(先,前) + sight(看到)→先见之明","example":"The UN had the foresight to convene a “world assembly on ageing” back in 1982. 早在1982年,联合国就有先见之明地召开了一次“世界老龄问题大会”。"},{"id":236,"word":"sight","pronunciation":"/saɪt/","meaning":"n.视力,视觉;景象 v.看到,发现","unit":1,"lesson":4,"seq":36,"isStar":false,"memo":"联想 s(联想 see) + ight(联想 light)→可以看见光线→视力,视觉;景象","example":"The accident deprived him of his sight. 这次事故使他失明。"},{"id":237,"word":"sightseeing","pronunciation":"/'saɪtsiːɪŋ/","meaning":"n.观光","unit":1,"lesson":4,"seq":37,"isStar":false,"example":"While I’m there, I’d also like to do some sightseeing. 当我在那里的时候,我也希望能参观一下。"},{"id":238,"word":"oversight","pronunciation":"/'əʊvəsaɪt/","meaning":"n.监督;疏忽,失察","unit":1,"lesson":4,"seq":38,"isStar":false},{"id":239,"word":"insight","pronunciation":"/'ɪnsaɪt/","meaning":"n.洞察力;领悟,了解","unit":1,"lesson":4,"seq":39,"isStar":false,"memo":"构词 in-(进入) + sight(看到)→看进去→洞察力","example":"These excursions will give you an even deeper insight into our language and culture. 这些短途旅行将会让你对我们的语言和文化有更深入的了解。","derivative":"insightful /ɪnˈsaɪtfʊl/ adj.富有洞察力的"},{"id":240,"word":"insightful","pronunciation":"/ɪn'saɪtfʊl/","meaning":"adj.富有洞察力的","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":241,"word":"horizon","pronunciation":"/hə'raɪzn/","meaning":"n.地平线;范围,视野","unit":1,"lesson":4,"seq":40,"isStar":false,"memo":"联想 ho(音似“好”) + riz(音似 rise) + on →好大的太阳从“地平线”升起来了。","example":"She wanted to travel to broaden her horizons. 她想旅行,以开阔眼界。","derivative":"horizontal /hɔrɪˈzɑntl/ adj.水平的;与地面平行的 n.水平面"},{"id":242,"word":"horizontal","pronunciation":"/ˌhɒrɪ'zntl/","meaning":"adj.水平的;与地面平行的 n.水平面","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":243,"word":"orient","pronunciation":"/'ːriənt/","meaning":"v.确定方向;适应 /'ɔːriənt/ n.东方","unit":1,"lesson":4,"seq":41,"isStar":false,"memo":"联想 o-(表方向) + ri(联想“日”) + ent(联想 enter)→太阳从“东方”进来(升起)了。","example":"The mountaineers found it hard to orient themselves in the fog. 登山者发现在大雾中很难辨认方向。","derivative":"orientation /ˌɔːriənˈteɪʃn/ n.方向;目标;观点 oriental /ˌɔriˈentl/ adj.东亚的;东南亚的"},{"id":244,"word":"orientation","pronunciation":"/ˌɔːrien'teɪʃn/","meaning":"n.方向;目标;观点","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":245,"word":"oriental","pronunciation":"/ˌːri'entl/","meaning":"adj.东方的;东方人的","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":246,"word":"scene","pronunciation":"/sin/","meaning":"n.风景、景色;舞台布景;情景;现场","unit":1,"lesson":4,"seq":42,"isStar":false,"memo":"对照 同音词 scen→我看见了(seen)美丽的风景(scene)。","example":"The human mind can glimpse a rapidly changing scene. 人类的大脑可以瞥见一个迅速变化的场景。","derivative":"scenic /ˈsinɪk/ adj.风景优美的"},{"id":247,"word":"scenic","pronunciation":"/'sinɪk/","meaning":"adj.风景优美的","unit":1,"lesson":4,"seq":0,"isStar":true},{"id":248,"word":"scenario","pronunciation":"/sə'nɑːriəʊ/","meaning":"n.设想;方案;场景","unit":1,"lesson":4,"seq":43,"isStar":false,"memo":"联想 sce(联想 scene) + nario(音似“哪里”)→去哪里看风景要先有个“设想”。","example":"Medical students are not blind to this scenario. 医学生对这种场景并非视而不见。"},{"id":249,"word":"landscape","pronunciation":"/'lændskeɪp/","meaning":"n.风景,景色","unit":1,"lesson":4,"seq":44,"isStar":false,"memo":"联想 land(陆地) + sc(联想“四看”) + ape (猿猴)→陆地上“风景”优美,四周都能看到猿猴。","example":"He loves the beautiful landscape of Australia very much. 他非常喜欢澳大利亚美丽的风景。"},{"id":250,"word":"ecology","pronunciation":"/iˈkɒlədʒi/","meaning":"n.生态；生态学","unit":2,"lesson":1,"seq":1,"isStar":false,"memo":"[联想] e(字母音似“姨”) + cology(音似“靠了鸡”)→阿姨是养鸡能手，办了一个绿色有机“生态”农场来养鸡。","example":"Oil pollution could damage the fragile ecology of the coral reefs. 石油污染可能破坏珊瑚礁脆弱的生态环境。"},{"id":251,"word":"ecological","pronunciation":"/ˌiːkəlɒdʒɪkl/","meaning":"adj.生态的；生态学的","unit":2,"lesson":1,"seq":2,"isStar":false},{"id":252,"word":"ecosystem","pronunciation":"/ˈiːkəʊsɪstəm/","meaning":"n.生态系统","unit":2,"lesson":1,"seq":3,"isStar":false},{"id":253,"word":"system","pronunciation":"/ˈsɪstəm/","meaning":"n.体系，制度；系统","unit":2,"lesson":1,"seq":4,"isStar":false,"example":"How does the system work? 系统是如何工作的?","derivative":"systematic /ˌsɪstəˈmætɪk/ adj.系统的;有条理的"},{"id":254,"word":"systematic","pronunciation":"/ˌsɪstəˈmætɪk/","meaning":"adj.系统的；有条理的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":255,"word":"stalk","pronunciation":"/stɔːk/","meaning":"n.茎，秆；柄 v.跟踪；盯梢","unit":2,"lesson":1,"seq":5,"isStar":false},{"id":256,"word":"stem","pronunciation":"/stem/","meaning":"n.茎，梗 v.阻止，遏制；堵住；起源于","unit":2,"lesson":1,"seq":6,"isStar":false,"memo":"[对照] 他用塞子堵住(stem)了出水蒸气(steam)的气孔。","example":"The stem of the plant looks ugly. 这株植物的茎看起来很丑。"},{"id":257,"word":"limb","pronunciation":"/lɪm/","meaning":"n.肢，翼；大树枝","unit":2,"lesson":1,"seq":7,"isStar":false,"memo":"[联想] li(联想“立”) + m(联想“妹”) + b(联想“臂”)→一只鸟站立在妹妹的手臂上,像站在树枝上一样→肢;大树枝","example":"For a while, she lost the use of her limbs. 好一会儿她四肢都动弹不得。"},{"id":258,"word":"bark","pronunciation":"/bɑːk/","meaning":"n.树皮；(狗等的)吠声 v.(狗)吠叫；厉声质问；擦破……的皮","unit":2,"lesson":1,"seq":8,"isStar":false},{"id":259,"word":"breast","pronunciation":"/brest/","meaning":"n.胸部，胸脯；(女子的)乳房","unit":2,"lesson":1,"seq":9,"isStar":false},{"id":260,"word":"abreast","pronunciation":"/əˈbrest/","meaning":"adv.并列，并排，并肩","unit":2,"lesson":1,"seq":10,"isStar":false},{"id":261,"word":"belly","pronunciation":"/ˈbeli/","meaning":"n.腹部；圆形或凸起部分","unit":2,"lesson":1,"seq":11,"isStar":false},{"id":262,"word":"weed","pronunciation":"/wiːd/","meaning":"n.杂草，野草 v.除草","unit":2,"lesson":1,"seq":12,"isStar":false},{"id":263,"word":"yard","pronunciation":"/jɑːd/","meaning":"n.院子；码(长度单位)","unit":2,"lesson":1,"seq":13,"isStar":false},{"id":264,"word":"insect","pronunciation":"/ˈnsekt/","meaning":"n.昆虫","unit":2,"lesson":1,"seq":14,"isStar":false,"memo":"联想 in(里面) + sect(音似“塞个它”)→他耳朵不舒服去医院，结果医生发现他的耳朵里塞了一只“昆虫”。","example":"Most birds spend most of the day eating insects. 大多数鸟一天大部分时间都在吃昆虫。"},{"id":265,"word":"vegetation","pronunciation":"/vedʒəˈteʃn/","meaning":"n.植物，植被","unit":2,"lesson":1,"seq":15,"isStar":false,"memo":"对照 这里的蔬菜（vegetable）和植被（vegetation）都生长得很好。","example":"Unburnt vegetation rots quickly. 未燃烧的植被很快就会腐烂。"},{"id":266,"word":"bleak","pronunciation":"/bliːk/","meaning":"adj.不乐观的，无望的；阴冷的；荒凉的","unit":2,"lesson":1,"seq":16,"isStar":false,"memo":"谐音 单词发音类似“不立刻”→他不能立刻离开那个“荒凉的”地方。","example":"Don't ask for evidence that justifies this bleak view. 别去找证明这种悲观观点的证据了。"},{"id":267,"word":"blink","pronunciation":"/blɪŋk/","meaning":"v.眨眼睛；(灯光)闪烁 n.眨眼","unit":2,"lesson":1,"seq":17,"isStar":false},{"id":268,"word":"brisk","pronunciation":"/brɪsk/","meaning":"adj.轻快的；敏捷的；麻利的；清新的","unit":2,"lesson":1,"seq":18,"isStar":false,"memo":"联想 b(联想“不”) + risk(冒险)→不想冒险,就要快点离开→麻利的","example":"They set off at a brisk pace. 他们踏着轻快的步伐出发了。"},{"id":269,"word":"humid","pronunciation":"/ˈhjuːmɪd/","meaning":"adj.温暖潮湿的，湿热的","unit":2,"lesson":1,"seq":19,"isStar":false,"memo":"对照：传说人类(human)是女娲用潮湿的(humid)泥土捏成的。","example":"These plants will grow best in a humid atmosphere. 这些植物在湿热的环境中长得最好。","derivative":"humidity /hju:'mɪdəti/ n.湿度；湿热"},{"id":270,"word":"humidity","pronunciation":"/hjuːˈmɪdəti/","meaning":"n.湿度；湿热","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":271,"word":"moist","pronunciation":"/mɪst/","meaning":"adj.潮湿的，湿润的","unit":2,"lesson":1,"seq":20,"isStar":false,"memo":"联想：mo(音似“毛”) + ist→长毛是因为天气潮湿，发霉了→潮湿的","example":"The warm moist air is perfect for growing fruit trees. 温暖湿润的空气最适于果树生长。","derivative":"moisture /'mɪstʃə(r)/ n.潮气；水汽"},{"id":272,"word":"moisture","pronunciation":"/'mɔɪstʃə(r)/","meaning":"n.潮气；水汽","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":273,"word":"damp","pronunciation":"/dæmp/","meaning":"adj.潮湿的 n.潮湿，潮气 v.使潮湿","unit":2,"lesson":1,"seq":21,"isStar":false,"memo":"联想：dam(大坝) + p(联想“趴”)→趴在大坝上，一会儿就感觉到“潮湿”了。","example":"The cottage was cold and damp. 这小屋又冷又湿。","derivative":"dampen /'dæmpən/ v.弄湿；抑制，减弱"},{"id":274,"word":"dampen","pronunciation":"/'dæmpən/","meaning":"v.弄湿；抑制，减弱","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":275,"word":"render","pronunciation":"/'rendə(r)/","meaning":"v.使变得，使处于某状态；给予，回报；呈献","unit":2,"lesson":1,"seq":22,"isStar":false,"memo":"谐音：单词发音类似“润的”→潮湿的天气往往使人的皮肤变得润润的→使变得","example":"It renders us unable to concentrate. 它使我们无法集中注意力。","derivative":"rendering /'rendərɪŋ/ n.演奏；扮演；翻译"},{"id":276,"word":"rendering","pronunciation":"/'rendərɪ/","meaning":"n.演奏；扮演；翻译","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":277,"word":"surrender","pronunciation":"/sə'rendə(r)/","meaning":"v.投降；自首；放弃，交出 n.投降；屈服","unit":2,"lesson":1,"seq":23,"isStar":false,"example":"They demanded unconditional surrender. 他们要求无条件投降。"},{"id":278,"word":"drought","pronunciation":"/draʊt/","meaning":"n.久旱；旱灾","unit":2,"lesson":1,"seq":24,"isStar":false,"example":"Their eggs can survive years of drought. 它们的卵能经受多年的干旱。"},{"id":279,"word":"humble","pronunciation":"/'hʌmbl/","meaning":"adj.谦逊的；卑微的","unit":2,"lesson":1,"seq":25,"isStar":false,"memo":"构词：hum(泥土) + -ble(形容词后缀)→接近泥土的→谦逊的；卑微的","example":"The main character is a young man of humble origin. 主人公是一个出身卑微的年轻人。","derivative":"humbly /'hʌmbli/ adv.卑微地；谦逊地"},{"id":280,"word":"humbly","pronunciation":"/'hʌmbli/","meaning":"adv.卑微地；谦逊地","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":281,"word":"tumble","pronunciation":"/'tʌmbl/","meaning":"n.跌倒 v.跌倒；倒塌；骤降","unit":2,"lesson":1,"seq":26,"isStar":false,"memo":"对照：他现在很卑微(humble)，因为他跌倒(tumble)了。","example":"The price of oil is still tumbling. 油价仍在急剧下跌。"},{"id":282,"word":"humiliate","pronunciation":"/hju:'mɪlieɪt/","meaning":"v.羞辱，使丧失尊严","unit":2,"lesson":1,"seq":27,"isStar":false},{"id":283,"word":"humiliation","pronunciation":"/hjuːmɪli'eɪʃn/","meaning":"n.丢脸；羞辱；耻辱","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":284,"word":"humane","pronunciation":"/hju:'meɪn/","meaning":"adj.善良的，仁慈的；人道的","unit":2,"lesson":1,"seq":28,"isStar":false},{"id":285,"word":"humanist","pronunciation":"/'hju:mənst/","meaning":"n.人文主义者；人文学者","unit":2,"lesson":1,"seq":29,"isStar":false},{"id":286,"word":"humanism","pronunciation":"/'hju:mənɪzəm/","meaning":"n.人文主义","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":287,"word":"humanitarian","pronunciation":"/hju:mænɪ'teəriən/","meaning":"adj.人道主义的；慈善的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":288,"word":"humanity","pronunciation":"/hju:'mænəti/","meaning":"n.人类；人道；仁慈；人文学科","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":289,"word":"feminine","pronunciation":"/'femənɪn/","meaning":"adj.女性特有的，妇女的；阴性的","unit":2,"lesson":1,"seq":30,"isStar":false,"memo":"构词 femin (= female) + -ine (形容词后缀)→女性特有的,妇女的","example":"She loved pretty feminine things. 她喜爱漂亮有女人味的东西。","derivative":"feminism /'femənɪzəm/ n.女权主义;女性主义\nfeminist /'femənɪst/ n.女权主义者;女性主义者"},{"id":290,"word":"feminism","pronunciation":"/'femənɪzəm/","meaning":"n.女权主义；女性主义","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":291,"word":"feminist","pronunciation":"/'femənst/","meaning":"n.女权主义者；女性主义者","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":292,"word":"famine","pronunciation":"/'fæmɪn/","meaning":"n.饥荒，饥饿","unit":2,"lesson":1,"seq":31,"isStar":false,"memo":"联想 fam(联想 farm) + in(里面) + e(字母音似“姨”)→农场里的阿姨“饥饿”了。","example":"The government has to make sure people don’t die of famine. 政府必须确保人们不会死于饥饿。"},{"id":293,"word":"species","pronunciation":"/'spiːʃiːz/","meaning":"n.种,物种","unit":2,"lesson":1,"seq":32,"isStar":false,"memo":"对照 每个物种(species)都有独特的(special)外观。","example":"This preference represents a built-in advantage for the human species. 这种偏好代表了人类物种的内在优势。"},{"id":294,"word":"exist","pronunciation":"/ɪgˈzɪst/","meaning":"v.存在;实际上有;生存","unit":2,"lesson":1,"seq":33,"isStar":false,"example":"Does life exist on other planets? 其他行星上有生命吗?","derivative":"existence /ɡ'zɪstəns/ n.存在;生活,生活方式\nexistent /ɪɡ'zɪstənt/ adj.存在的 n.存在(或实有)的事物\nexisting /ɪɡ'zɪstɪŋ/ adj.现存的;现行的"},{"id":295,"word":"existence","pronunciation":"/ɪgˈzɪstəns/","meaning":"n.存在;生活,生活方式","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":296,"word":"existent","pronunciation":"/gˈzɪstənt/","meaning":"adj.存在的 n.存在(或实有)的事物","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":297,"word":"existing","pronunciation":"/ɪgˈzɪstɪŋ/","meaning":"adj.现存的;现行的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":298,"word":"irrigate","pronunciation":"/'ɪrɪɡeɪt/","meaning":"v.灌溉","unit":2,"lesson":1,"seq":34,"isStar":false,"memo":"[联想] i(形似人)+rr(形似两朵花)+i(形似人)+gate(大门)→两个人站在大门口浇花→灌溉","example":"He wants to use the water to irrigate barren desert land. 他想用这些水来灌溉贫瘠的沙漠土地。","derivative":"irrigation /ˌrɪ'ɡeɪʃn/ n.灌溉"},{"id":299,"word":"irrigation","pronunciation":"/ɪrɪˈɡeɪʃn/","meaning":"n.灌溉","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":300,"word":"irritable","pronunciation":"/'rɪtəbl/","meaning":"adj.急躁的,易怒的","unit":2,"lesson":1,"seq":35,"isStar":false},{"id":301,"word":"irritate","pronunciation":"/'ɪrɪteɪt/","meaning":"v.使烦恼;刺激","unit":2,"lesson":1,"seq":0,"isStar":true,"memo":"ir-（不）+rit（刮擦）+ate（使）→‘刮’得你‘不爽’！像粉笔划黑板、微信弹窗连跳3次——物理刮擦+心理刮擦=暴躁源头。","example":"Constant notifications from social media irritate many users. 社交媒体的持续通知让许多用户感到烦躁。","derivative":"irritation /ˌɪrɪˈteɪʃ(ə)n/ n. 恼怒；刺激"},{"id":302,"word":"irritation","pronunciation":"/ˌɪrɪ'teɪʃn/","meaning":"n.刺激;刺激物;恼人的事","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":303,"word":"irritating","pronunciation":"/'ɪrɪteɪtɪ/","meaning":"adj.气人的,使人不愉快的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":304,"word":"outrage","pronunciation":"/'atreɪdʒ/","meaning":"n.愤怒,愤慨;暴行 v.使震怒,激怒","unit":2,"lesson":1,"seq":36,"isStar":false},{"id":305,"word":"outrageous","pronunciation":"/aʊ'treɪdʒəs/","meaning":"adj.骇人的;无法容忍的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":306,"word":"temper","pronunciation":"/'tempə(r)/","meaning":"n.脾气;心情","unit":2,"lesson":1,"seq":37,"isStar":false,"memo":"[对照] 他的脾气(temper)就像气温(temperature)一样起伏不定。","example":"She cannot stand her boss's bad temper. 她无法忍受老板的坏脾气。"},{"id":307,"word":"temperament","pronunciation":"/'temprəmənt/","meaning":"n.气质,禀性;暴躁;喜怒无常","unit":2,"lesson":1,"seq":38,"isStar":false,"example":"His only weakness is his temperament. 他唯一的弱点是他的脾气。"},{"id":308,"word":"inevitable","pronunciation":"/ɪn'evɪtəbl/","meaning":"adj.不可避免的;惯常的","unit":2,"lesson":1,"seq":39,"isStar":false,"memo":"[联想] in-(否定前缀)+evi(音似“俺为”)+table(桌子)→俺为了买那一张桌子付钱了,这是“不可避免的”。","example":"Sometimes, it is inevitable that the attention is focused elsewhere. 有时,注意力不可避免地被集中在其他地方。"},{"id":309,"word":"organ","pronunciation":"/'ɔːɡən/","meaning":"n.器官;风琴;(官方的)机构,机关","unit":2,"lesson":1,"seq":40,"isStar":false,"memo":"[谐音] 单词发音类似“呕肝”→肝就是人体的“器官”。","example":"Some operations may damage the heart or other organs. 有些手术或许会损伤心脏或其他器官。"},{"id":310,"word":"organic","pronunciation":"/ɔː'ɡænɪk/","meaning":"adj.有机的;绿色的;器官的","unit":2,"lesson":1,"seq":41,"isStar":false,"memo":"[构词] organ(器官)+-ic(形容词后缀)→器官的","example":"The farm went fully organic in 1996. 这个农场在1996年就全部采用有机耕作了。"},{"id":311,"word":"organism","pronunciation":"/'ɔːɡənɪzəm/","meaning":"n.生物;有机体;(尤指)微生物","unit":2,"lesson":1,"seq":42,"isStar":false,"memo":"[构词] organ(器官)+-ism(名词后缀)→生物;有机体","example":"It seems simple enough to distinguish between the organism and the surrounding environment. 区分生物体和周围的环境似乎很简单。"},{"id":312,"word":"sanctuary","pronunciation":"/'sæŋktʃuəri/","meaning":"n.避难所;庇护;鸟兽保护区,禁猎区;圣殿","unit":2,"lesson":1,"seq":43,"isStar":false},{"id":313,"word":"geology","pronunciation":"/dʒi'ɒlədʒi/","meaning":"n.地质学;(某地区的)地质","unit":2,"lesson":1,"seq":44,"isStar":false,"memo":"(构词) geo-(地球，大地) + -logy(表示学科的名词后缀)→地质学","example":"We went on a geology field trip. 我们去进行野外地质考察。","derivative":"geological /ˌdʒiːəˈlɒdʒɪkl/ adj.地质(学)的\ngeologically /ˌdʒiːəˈlɒdʒɪkli/ adv.地质学上"},{"id":314,"word":"geological","pronunciation":"/ˌdʒiːə'lɒdʒɪkl/","meaning":"adj.地质(学)的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":315,"word":"geologically","pronunciation":"/dʒi:ə'ldʒɪkli/","meaning":"adv.地质学上","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":316,"word":"zoology","pronunciation":"/zuˈɒlədi;<br>zəʊˈɒlədʒi/","meaning":"n.动物学","unit":2,"lesson":1,"seq":45,"isStar":false},{"id":317,"word":"zoological","pronunciation":"/ˌzu:ə'lɒdʒɪkl;<br>zəʊə'lɒdʒɪkl/","meaning":"adj.动物学的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":318,"word":"diagnose","pronunciation":"/'daɪəɡnəʊz;<br>daɪəɡ'nəʊz/","meaning":"v.诊断(疾病);判断","unit":2,"lesson":1,"seq":46,"isStar":false,"memo":"(联想) dia(音似“打”) + g(联想“哥”) + nose(鼻子)→我不小心打了哥哥的鼻子，他得去医院“诊断”一下有无受伤。","example":"He was not aware of his illness until diagnosed with it. 直到被诊断出患有此病，他才意识到自己的病情。","derivative":"diagnosis /ˌdaɪəɡˈnəʊsɪs/ n.诊断；判断"},{"id":319,"word":"diagnosis","pronunciation":"/ˌdaɪəɡ'nəʊsɪs/","meaning":"n.诊断;判断","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":320,"word":"clinic","pronunciation":"/'klɪnɪk/","meaning":"n.诊所;临床实习","unit":2,"lesson":1,"seq":47,"isStar":false,"memo":"(对照) 野餐(picnic)时吃坏了肚子得就近找个诊所(clinic)看病。","example":"The clinic provides free consultations for patients. 这个诊所为病患提供免费咨询。","derivative":"clinical /ˈklnɪkl/ adj.诊所的；临床的"},{"id":321,"word":"clinical","pronunciation":"/'klɪnɪkl/","meaning":"adj.诊所的;临床的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":322,"word":"chronic","pronunciation":"/'krɒnɪk/","meaning":"adj.慢性的;长期的","unit":2,"lesson":1,"seq":48,"isStar":false,"memo":"[谐音] 单词发音类似“困扰你的”→慢性病可把人害苦了,让人深感困扰→慢性的","example":"Let's follow that example to battle the acute and chronic challenges that lie ahead. 让我们以此为榜样,与摆在面前的严峻和长期挑战作斗争。","derivative":"chronically /'krɒnɪkli/ adv.慢性地;长期地"},{"id":323,"word":"chronically","pronunciation":"/'krɒnɪkli/","meaning":"adv.慢性地;长期地","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":324,"word":"chronicle","pronunciation":"/'krɒnɪkl/","meaning":"n.编年史,大事记 v.把……载入编 年史;按事件顺序记载","unit":2,"lesson":1,"seq":49,"isStar":false,"memo":"[联想] chronic(长期的)+(c)le(联想 circle) →历史就是一个环绕的、缓慢发展的过程→编年史,大事记","example":"Her achievements are chronicled in a new biography out this week. 她的成就已载入本周出版的一本新传记中。"},{"id":325,"word":"benign","pronunciation":"/bɪ'naɪn/","meaning":"adj.善良的,和善的,慈祥的;良 性的","unit":2,"lesson":1,"seq":50,"isStar":false,"memo":"[联想] be(是)+nign(音似“奶”)→我的奶奶是很“和善的”。","example":"You would never have guessed his intentions from the benign expression on his face. 从他脸上温和的表情你绝对猜不到他的意图。"},{"id":326,"word":"wholesome","pronunciation":"/'həʊlsəm/","meaning":"adj.有益健康的","unit":2,"lesson":1,"seq":51,"isStar":false},{"id":327,"word":"malice","pronunciation":"/'mælɪs/","meaning":"n.恶意;怨恨","unit":2,"lesson":1,"seq":52,"isStar":false,"memo":"[联想] ma(联想“妈”)+lice(联想 Alice,人名)→后妈对爱丽丝没有“恶意”。","example":"She is entirely without malice. 她完全没有恶意。"},{"id":328,"word":"malicious","pronunciation":"/mə'lʃəs/","meaning":"adj.怀有恶意的,恶毒的","unit":2,"lesson":1,"seq":53,"isStar":false},{"id":329,"word":"malignant","pronunciation":"/mə'lɪɡnənt/","meaning":"adj.恶性的;恶意的,恶毒的","unit":2,"lesson":1,"seq":54,"isStar":false},{"id":330,"word":"contagious","pronunciation":"/kən'teɪdʒəs/","meaning":"adj.接触传染的","unit":2,"lesson":1,"seq":55,"isStar":false,"memo":"[构词] con-(一起)+tag(接触)+-ious(形容词后缀)→接触传染的","example":"The new disease proved contagious. 这种新的疾病证明具有传染性。"},{"id":331,"word":"acute","pronunciation":"/ə'kju:t/","meaning":"adj.严重的;敏锐的;急性的","unit":2,"lesson":1,"seq":56,"isStar":false,"memo":"[对照] 一个可爱的(cute)孩子得了很严重的(acute)病。","example":"Punishment can never be an effective cure for acute social problems. 惩罚绝不是解决严重社会问题的有效办法。"},{"id":332,"word":"fatal","pronunciation":"/'feɪtl/","meaning":"adj.致命的;灾难性的","unit":2,"lesson":1,"seq":57,"isStar":false,"memo":"谐音 单词发音类似“肥头”→婴儿得了肥头(大头病)是很“致命的”。","example":"There was a fatal flaw in the plan. 计划中有一个致命的缺陷。","derivative":"fatality /fəˈtæləti/ n.致命性;死亡;宿命"},{"id":333,"word":"fatality","pronunciation":"/fə'tæləti/","meaning":"n.致命性;死亡;宿命","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":334,"word":"severe","pronunciation":"/sɪ'vɪə(r)/","meaning":"adj.十分严重的;严厉的,苛刻的","unit":2,"lesson":1,"seq":58,"isStar":false,"memo":"联想 sever(联想 seven)+e(联想 e-,出来)→七处隐患被排查出来,这是“十分严重的”问题。","example":"The storm caused severe damage. 这场暴风雨造成了严重的破坏。","derivative":"severity /sɪˈverəti/ n.严格,严厉;严重"},{"id":335,"word":"severity","pronunciation":"/sɪ'verəti/","meaning":"n.严格,严厉;严重","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":336,"word":"terminal","pronunciation":"/'tɜ:mɪnl/","meaning":"n.航站楼;终点站;终端 adj.晚期的","unit":2,"lesson":1,"seq":59,"isStar":false,"memo":"联想 term(学期,期限)+inal→属于某个时间期限的末端→终点站;晚期的","example":"He was eventually diagnosed as suffering from terminal cancer. 他最后被诊断患有晚期癌症。","derivative":"terminate /ˈtɜːmɪneɪt/ v.(使)结束;到达终点站"},{"id":337,"word":"terminate","pronunciation":"/'tɜːmneɪt/","meaning":"v.(使)结束;到达终点站","unit":2,"lesson":1,"seq":0,"isStar":true,"memo":"谐音+构词：‘特敏内特’→特别敏感，一碰就‘终止’！term（界限）+inate→划到终点线，立刻停！","example":"The company will terminate the contract if the software fails security audits. 如果该软件未能通过安全审计，公司将终止合同。","derivative":"termination /ˌtɜːmɪ'neɪʃ(ə)n/ n.终止；结束"},{"id":338,"word":"perish","pronunciation":"/'perɪʃ/","meaning":"v.死亡;丧失;湮灭,毁灭;碎裂","unit":2,"lesson":1,"seq":60,"isStar":false,"memo":"谐音 单词发音类似“拍蕊死”→把花朵的花蕊拍死,花朵就会“死亡”。","example":"Most of the butterflies perish in the first frosts of autumn. 大多数蝴蝶在秋季初霜来临时死亡。"},{"id":339,"word":"destroy","pronunciation":"/dɪ'strɔ/","meaning":"v.摧毁,毁灭;破坏","unit":2,"lesson":1,"seq":61,"isStar":false,"example":"Destroying the machines that are coming for our jobs would be nuts. 摧毁即将取代我们工作的机器将是疯狂的。","derivative":"destruction /dˈstrʌkʃn/ n.摧毁;毁灭;破坏\ndestructive /dɪstrʌktɪv/ adj.破坏性的"},{"id":340,"word":"destruction","pronunciation":"/dɪ'strʌkʃn/","meaning":"n.摧毁,毁灭;破坏","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":341,"word":"destructive","pronunciation":"/dɪ'strʌktɪv/","meaning":"adj.破坏性的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":342,"word":"devastate","pronunciation":"/'devəsteɪt/","meaning":"v.摧毁,毁灭;使震惊;使极为忧伤","unit":2,"lesson":1,"seq":62,"isStar":false,"memo":"联想 de-(向下;除去)+vast(广阔的)+-ate(动词后缀)→人们砍伐树木后,广阔的绿地被破坏→摧毁,毁灭","example":"The bomb devastated much of the old part of the city. 这颗炸弹炸毁了旧城的一大片地方。","derivative":"devastating /ˈdevəsteɪtɪ/ adj.毁灭性的;令人震惊的\ndevastation /ˌdevəˈsteɪʃn/ n.毁灭,破坏"},{"id":343,"word":"devastating","pronunciation":"/'devəsteɪtɪŋ/","meaning":"adj.毁灭性的;令人震惊的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":344,"word":"devastation","pronunciation":"/ˌdevə'steɪʃn/","meaning":"n.毁灭;破坏","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":345,"word":"remedy","pronunciation":"/'remədi/","meaning":"n.治疗,疗法;解决办法 v.改正;改进","unit":2,"lesson":1,"seq":63,"isStar":false,"memo":"对照 把悲剧(tragedy)变成喜剧(comedy)是一种解决办法(remedy)。","example":"The best remedy for grief is hard work. 排解忧伤的最好办法就是努力工作。","derivative":"remedial /rɪˈmiːdiəl/ adj.补救的;辅导的"},{"id":346,"word":"remedial","pronunciation":"/rɪ'miːdiəl/","meaning":"adj.补救的;辅导的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":347,"word":"therapy","pronunciation":"/'θerəpi/","meaning":"n.治疗,疗法","unit":2,"lesson":1,"seq":64,"isStar":false,"example":"I was ready for a little retail therapy. 我准备去进行一下购物治疗。","derivative":"therapist /θerəpɪst/ n.(某治疗法的)治疗专家\ntherapeutic(al) /ˌθerəˈpjuːtɪk(əl)/ adj.治疗的"},{"id":348,"word":"therapist","pronunciation":"/'θerəpɪst/","meaning":"n.(某治疗法的)治疗专家","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":349,"word":"therapeutic(al)","pronunciation":"/ˌθerə'pjuːtɪk(l)/","meaning":"adj.治疗的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":350,"word":"salvation","pronunciation":"/sæl'veɪʃn/","meaning":"n.解救;解救途径","unit":2,"lesson":1,"seq":65,"isStar":false},{"id":351,"word":"surgery","pronunciation":"/'sɜːdʒəri/","meaning":"n.外科手术;外科学","unit":2,"lesson":1,"seq":66,"isStar":false,"example":"Good news. I'm not going to have surgery. 好消息,我不需要做手术了。","derivative":"surgical /ˈsɜːrdʒɪkl/ adj.外科的,外科手术的\nsurgeon /ˈsɜrdʒən/ n.外科医生"},{"id":352,"word":"surgical","pronunciation":"/'sɜːdʒɪkl/","meaning":"adj.外科的,外科手术的","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":353,"word":"surgeon","pronunciation":"/'sɜːdʒən/","meaning":"n.外科医生","unit":2,"lesson":1,"seq":67,"isStar":false},{"id":354,"word":"physician","pronunciation":"/fɪ'zɪn/","meaning":"n.医生,(尤指)内科医生","unit":2,"lesson":1,"seq":68,"isStar":false,"memo":"【构词】physic(身体,医学)+-ian(表示人的后缀)→内科医生","example":"My father is busy because he is a physician. 我父亲很忙,因为他是一名医生。"},{"id":355,"word":"medication","pronunciation":"/ˌmedɪ'keɪʃn/","meaning":"n.药,药物","unit":2,"lesson":1,"seq":69,"isStar":false},{"id":356,"word":"tablet","pronunciation":"/'tæblət/","meaning":"n.药片","unit":2,"lesson":1,"seq":70,"isStar":false,"memo":"【谐音】单词发音类似“他不离它”→他生病后离不开吃“药片”。","example":"She took a couple of headache tablets. 她吃了几片治头痛的药。"},{"id":357,"word":"portable","pronunciation":"/'pɔːtəbl/","meaning":"adj.便携式的;手提的 n.手提电脑;便携式电视机","unit":2,"lesson":1,"seq":71,"isStar":false,"memo":"【谐音】单词发音类似“泡腾的”→维生素泡腾片很容易携带→便携式的","example":"We bought a portable last week. 我们上周买了一台手提电脑。","derivative":"n.手提电脑;便携式电视机"},{"id":358,"word":"rescue","pronunciation":"/'reskjuː/","meaning":"n. & v.营救,救援","unit":2,"lesson":1,"seq":72,"isStar":false,"memo":"【联想】re-(回)+s(联想“女孩”)+cue(联想cute)→快回去“营救”那个可爱的女孩。","example":"Robots are coming to the rescue. 机器人正前来救援。"},{"id":359,"word":"obscure","pronunciation":"/əbˈskjʊə(r)/","meaning":"adj.鲜为人知的；模糊的；费解的 v.使模糊；使费解；遮蔽","unit":2,"lesson":1,"seq":73,"isStar":false,"memo":"【联想】ob-(表示方向,对)+s(联想“女孩”)+cure(治疗)→他对那个视线“模糊的”女孩进行治疗。","example":"Differences between races are deliberately obscured. 种族之间的差异被刻意掩盖。","derivative":"v.使模糊;使费解;遮蔽"},{"id":360,"word":"obscurity","pronunciation":"/əbˈskjərəti/","meaning":"n.费解，晦涩；默默无闻","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":361,"word":"vague","pronunciation":"/veɪɡ/","meaning":"adj.模糊的，不清楚的","unit":2,"lesson":1,"seq":74,"isStar":false,"memo":"【谐音】单词发音类似“喂哥”→他听见有个“模糊的”声音喊“喂,哥”。","example":"Through the mist I could just make out a vague figure. 透过薄雾,我只能看见一个模糊的人影。"},{"id":362,"word":"secure","pronunciation":"/sɪˈkjʊə(r)/","meaning":"adj.安全的；可靠的，稳固的 v.保护，使安全","unit":2,"lesson":1,"seq":75,"isStar":false,"memo":"【构词】se-(分开)+cure(=care)→把担心分开,即不需要担心了→安全的","example":"Your foundation is already secure. 你的基础已经稳固了。","derivative":"v.保护,使安全"},{"id":363,"word":"security","pronunciation":"/sɪˈkjʊərəti/","meaning":"n.安全；抵押品；安保","unit":2,"lesson":1,"seq":0,"isStar":true},{"id":364,"word":"consecutive","pronunciation":"/kənˈsekjətɪv/","meaning":"adj.连续不断的","unit":2,"lesson":1,"seq":76,"isStar":false,"memo":"【联想】con-(所有的)+secu(联想secure)+-tive(形容词后缀)→所有的日子都是安全的→连续不断的","example":"Most people in the business would agree that consecutive interpreting is more stressful. 业内大多数人都认为交替传译的压力更大。"},{"id":365,"word":"carbohydrate","pronunciation":"/ˌkɑːbəʊˈhaɪdreɪt/","meaning":"n.碳水化合物","unit":2,"lesson":2,"seq":1,"isStar":false},{"id":366,"word":"saturate","pronunciation":"/sætʃəreɪt/","meaning":"v.使湿透；使充满；使饱和","unit":2,"lesson":2,"seq":2,"isStar":false,"memo":"[联想] sa(音似“塞”) + tur(联想 true) + -ate (动词后缀) → 我的包真的塞满了 → 使充满;使饱和","example":"The continuous rain had saturated the soil. 连绵不断的雨使土地湿透了。","derivative":"saturation /ˌsætʃəˈreɪʃn/ n.饱和;饱和状态;饱和度"},{"id":367,"word":"saturation","pronunciation":"/ˌsætʃəˈreʃn/","meaning":"n.饱和；饱和状态；饱和度","unit":2,"lesson":2,"seq":0,"isStar":true},{"id":368,"word":"drain","pronunciation":"/dreɪn/","meaning":"n.排水；下水道；消耗 v.使排出；使耗尽","unit":2,"lesson":2,"seq":3,"isStar":false,"memo":"[对照] 他们把雨水(rain)倒进了下水道(drain)。","example":"We can drain the rivers today. 今天我们可以排干河水。","derivative":"drainage /ˈdreɪnɪdʒ/ n.排水;放水 v.使排出;使耗尽"},{"id":369,"word":"drainage","pronunciation":"/ˈdrenɪdʒ/","meaning":"n.排水；放水","unit":2,"lesson":2,"seq":0,"isStar":true},{"id":370,"word":"mud","pronunciation":"/mʌd/","meaning":"n.泥，淤泥","unit":2,"lesson":2,"seq":4,"isStar":false,"memo":"[联想] mu(联想“木”) + d(联想“的”) → 树木的根在“泥”土里。","example":"The car wheels got stuck in the mud. 汽车轮子陷到泥里去了。","derivative":"muddy /ˈmʌdi/ adj.多泥的,泥泞的"},{"id":371,"word":"muddy","pronunciation":"/ˈmʌdi/","meaning":"adj.多泥的，泥泞的","unit":2,"lesson":2,"seq":0,"isStar":true},{"id":372,"word":"dirt","pronunciation":"/dɜːt/","meaning":"n.污物；泥土；灰尘；丑闻","unit":2,"lesson":2,"seq":5,"isStar":false,"memo":"[联想] di(联想“敌”) + r(联想“人”) + t(联想“特”) → 敌人被我们打得满身“泥土”,特别狼狈。","example":"Dirt from the road made him cough. 路上的灰尘使他咳嗽起来。","derivative":"dirty /ˈdɜːrti/ adj.肮脏的;龊的;污秽的"},{"id":373,"word":"dirty","pronunciation":"/ˈdɜːti/","meaning":"adj.肮脏的；龌龊的；污秽的","unit":2,"lesson":2,"seq":0,"isStar":true},{"id":374,"word":"trench","pronunciation":"/trentʃ/","meaning":"n.沟，渠；战壕；海沟","unit":2,"lesson":2,"seq":6,"isStar":false,"memo":"[联想] tren(音似“蹭”) + ch(联想“吃”) → 骗子被踹到“沟”里,吃了一嘴泥。","example":"With virtual reality we’ll be able to put a surgeon in every trench. 有了虚拟现实技术,我们就可以在每条战壕里安插一名外科医生。"},{"id":375,"word":"renew","pronunciation":"/rɪnjuː/","meaning":"v.重新开始；延长期限；更新","unit":2,"lesson":2,"seq":7,"isStar":false,"memo":"构词 re-(重新) + new(新)→重新开始;更新","example":"The man is going to renew his membership in a fitness center. 这位男士打算续订他在健身中心的会员资格。","derivative":"renewable /rɪnjuːəbl/ n.可再生能源 adj.可更新的,可再生的\nrenewal /rɪnjuːəl/ n.恢复;更新;重新开始"},{"id":376,"word":"renewable","pronunciation":"/rɪˈnjuːəbl/","meaning":"n.可再生能源 adj.可更新的，可再生的","unit":2,"lesson":2,"seq":0,"isStar":true},{"id":377,"word":"renewal","pronunciation":"/rɪˈnjuːəl/","meaning":"n.恢复；更新；重新开始","unit":2,"lesson":2,"seq":0,"isStar":true},{"id":378,"word":"refresh","pronunciation":"/rɪ'freʃ/","meaning":"v.使恢复精力;使清凉;更新","unit":2,"lesson":2,"seq":8,"isStar":false,"memo":"构词 re-(重新) + fresh(精力充沛;凉爽的)→使恢复精力;使清凉","example":"The lotion cools and refreshes the skin. 这款润肤液使皮肤凉爽清新。","derivative":"refreshment /rˈfreʃmənt/ n.点心;恢复精力"},{"id":379,"word":"refreshment","pronunciation":"/rɪ'freʃmənt/","meaning":"n.点心;恢复精力","unit":2,"lesson":2,"seq":0,"isStar":true,"memo":"re-（再）+ fresh（新鲜）+ -ment → ‘再新鲜一下’！茶歇不是吃，是给脑子‘刷新缓存’。","example":"Students grabbed refreshments between exam sessions in the library lounge. 学生们在考试间隙到图书馆休息区取用茶点。","derivative":"refresh /rɪˈfreʃ/ v.使恢复精力；refreshing /rɪˈfreʃɪŋ/ adj.使人耳目一新的"},{"id":380,"word":"stale","pronunciation":"/steɪl/","meaning":"adj.不新鲜的;厌倦的;没有新意的","unit":2,"lesson":2,"seq":9,"isStar":false,"memo":"联想 s(联想“美女蛇”)+tale(故事)→关于美女蛇的故事太多了,没人想听这种“没有新意”的故事了。","example":"They prohibit the sale of foods that have gone stale. 他们禁止出售变质的食品。"},{"id":381,"word":"outdated","pronunciation":"/ˌaʊt'deɪtɪd/","meaning":"adj.过时的,陈旧的","unit":2,"lesson":2,"seq":10,"isStar":false,"memo":"对照 out of date 过时的;过期的 → outdated adj.","example":"This outdated equipment is dangerous. 这台过时的设备很危险。"},{"id":382,"word":"old-fashioned","pronunciation":"/ˌəʊld 'fæʃnd/","meaning":"adj.陈旧的,过时的;守旧的","unit":2,"lesson":2,"seq":11,"isStar":false},{"id":383,"word":"update","pronunciation":"/ˈʌpdeɪt/","meaning":"n.最新消息;更新 /ˌʌp'deɪt/ v.使现代化;更新","unit":2,"lesson":2,"seq":12,"isStar":false,"memo":"构词 up(往上) + date(日期)→更新\n对照 up to date 最新的,现代的→update n. & v.","example":"It's about time we updated our software. 是时候更新我们的软件了。"},{"id":384,"word":"upgrade","pronunciation":"/ˌʌp'greɪd/","meaning":"v.升级;提高;改进 /ˈʌpɡred/ n.升级","unit":2,"lesson":2,"seq":13,"isStar":false,"memo":"构词 up(往上) + grade(等级) → 升级","example":"We are constantly upgrading our software to meet customers’ needs. 我们不断升级软件，以满足用户的需要。","derivative":"/'ʌpgred/ n.升级"},{"id":385,"word":"recur","pronunciation":"/r'kɜː(r)/","meaning":"v.再发生;反复出现","unit":2,"lesson":2,"seq":14,"isStar":false,"memo":"构词 re-(再) + (oc)cur(发生) → 再发生","example":"Otherwise, the overtraining syndrome is likely to recur. 否则，过度训练综合征很可能会复发。","derivative":"recurrence /rɪ'kʌrəns/ n.重现；复发"},{"id":386,"word":"recurrence","pronunciation":"/rɪ'kʌrəns/","meaning":"n.重现;复发","unit":2,"lesson":2,"seq":0,"isStar":true},{"id":387,"word":"occur","pronunciation":"/ə'kɜː(r)/","meaning":"v.发生;出现","unit":2,"lesson":2,"seq":15,"isStar":false,"memo":"谐音 单词发音类似“我磕”→我磕到腿了，“发生”事故了。","example":"Improvement of an athlete’s performance occurs in the course of training. 运动员成绩的提高是在训练过程中出现的。","derivative":"occurrence /ə'krəns/ n.出现，发生"},{"id":388,"word":"occurrence","pronunciation":"/ə'kʌrəns/","meaning":"n.出现;发生","unit":2,"lesson":2,"seq":0,"isStar":true},{"id":389,"word":"curb","pronunciation":"/kɜːb/","meaning":"n. & v.控制,抑制;约束","unit":2,"lesson":2,"seq":16,"isStar":false,"memo":"联想 cur(联想 occur) + b(联想“不”) → 不让一件事情发生，我们就要“控制”它。","example":"High taxes on alcohol are meant to curb excessive drinking. 对酒征收高额税款旨在限制过度饮酒。"},{"id":390,"word":"incur","pronunciation":"/ɪn'kɜː(r)/","meaning":"v.招致;遭受;引起","unit":2,"lesson":2,"seq":17,"isStar":false,"memo":"联想 in(里面) + cur(联想 occur) → 家里面发生了事，可能会“引起”很大的麻烦。","example":"It incurs a high environmental price. 它会招致高昂的环境代价。"},{"id":391,"word":"resource","pronunciation":"/rɪ'sɔːs/","meaning":"n.资源;财力;资料;智谋","unit":2,"lesson":2,"seq":18,"isStar":false,"memo":"联想 re-(重复) + source(源头) → 想要重复找到金矿的源头，是需要很多“资源”和“财力”的。","example":"We are learning, that forest is a natural resource and must be protected by law. 我们认识到，森林是一种自然资源，必须受到法律保护。","derivative":"resourceful /rɪ'sɔːsfl/ adj.机敏的；足智多谋的"},{"id":392,"word":"resourceful","pronunciation":"/rɪ'sɔːsfl/","meaning":"adj.机敏的;足智多谋的","unit":2,"lesson":2,"seq":0,"isStar":true},{"id":393,"word":"recycle","pronunciation":"/ˌriː'saɪkl/","meaning":"v.回收,再循环","unit":2,"lesson":2,"seq":19,"isStar":false,"memo":"联想 re-(再，重复) + cycle(音似 circle) → 让事物再次循环转起来 → 回收，再循环","example":"We should try to recycle the waste to save resources. 为了节约资源，我们应该设法回收废物。"},{"id":394,"word":"recyclable","pronunciation":"/ˌriː'saɪkləbl/","meaning":"adj.可回收利用的,可再循环的","unit":2,"lesson":2,"seq":20,"isStar":false},{"id":395,"word":"triple","pronunciation":"/ˈtrɪpl/","meaning":"v.成为三倍,使增至三倍 adj.三倍的","unit":2,"lesson":2,"seq":21,"isStar":false,"memo":"构词 tri(三) + -ple(表示倍数) → 三倍的","example":"It expects its revenues almost to triple this year. 该公司预计今年的收入将增至三倍。","derivative":"adj.三倍的"},{"id":396,"word":"tribe","pronunciation":"/traɪb/","meaning":"n.部落;一大群人","unit":2,"lesson":2,"seq":22,"isStar":false,"memo":"联想 tri(三) + be(音似“部”) → 三个部 → 部落","example":"He wanted to amuse the people of the local tribes. 他想逗当地部落的人开心。","derivative":"tribal /'traɪbl/ n.部落成员 adj.部落的"},{"id":397,"word":"tribal","pronunciation":"/ˈtraɪbl/","meaning":"n.部落成员 adj.部落的","unit":2,"lesson":2,"seq":0,"isStar":true},{"id":398,"word":"trivial","pronunciation":"/ˈtrviəl/","meaning":"adj.不重要的,琐碎的,微不足道的","unit":2,"lesson":2,"seq":23,"isStar":false,"memo":"tri(三) + vi(形似罗马数字6) + al(联想all)→三姑六婆关心的通常都是些“琐碎的”事情。","example":"Yet that is a rather trivial aspect of the matter. 然而，那只是事情的一个相当微不足道的方面。"},{"id":399,"word":"via","pronunciation":"/ˈvaɪə; ˈviə/","meaning":"prep.经过;通过","unit":2,"lesson":2,"seq":24,"isStar":false,"memo":"vi(形似罗马数字6) + a(形似小乌龟) →兔子去河对岸吃草要“经过”六只小乌龟。","example":"The news programme came to us via satellite. 新闻节目通过卫星传送到我们这里来。"},{"id":400,"word":"virtue","pronunciation":"/'vɜːtʃuː/","meaning":"n.美德；优点","unit":2,"lesson":2,"seq":25,"isStar":false,"memo":"vi(形似罗马数字6) + r(形似花) + tue(音似true)→我们得到六朵小红花,说明我们的“优点”和“美德”真的多。","example":"Patience is a virtue. 耐心是一种美德。","derivative":"virtuous /'vɜːtʃuəs/ adj.品行端正的,有德行的"},{"id":401,"word":"navigate","pronunciation":"/'nævɪɡeɪt/","meaning":"v.导航；航行，航海","unit":2,"lesson":2,"seq":26,"isStar":false},{"id":402,"word":"deviate","pronunciation":"/'diːvɪeɪt/","meaning":"v.背离，偏离；违背","unit":2,"lesson":2,"seq":27,"isStar":false,"memo":"de(音似“弟”) + vi(形似罗马数字6) + -ate(动词后缀)→弟弟和他的六个小伙伴走散了,“偏离”了目的地。","example":"Each workday, the workers followed the same schedules and rarely deviated from this routine. 每个工作日,工人们都遵循着同样的时间表,很少偏离这种常规。","derivative":"deviation /ˌdiːvi'eɪʃn/ n.偏离,违背;偏差"},{"id":403,"word":"indispensable","pronunciation":"/ˌɪndɪ'spensəbl/","meaning":"adj.不可或缺的，必不可少的","unit":2,"lesson":2,"seq":28,"isStar":false,"memo":"in-(表否定) + dis-(表否定) + pens (钢笔) + -able(形容词后缀)→不能没有钢笔的→不可或缺的,必不可少的","example":"High-price drugs are indispensable in curing some chronic diseases. 高价药物对于治疗某些慢性疾病不可或缺。"},{"id":404,"word":"essence","pronunciation":"/'esns/","meaning":"n.本质；精髓；精华；精油","unit":2,"lesson":2,"seq":29,"isStar":false,"example":"His theory was not new in essence. 他的理论实..."},{"id":405,"word":"essential","pronunciation":"/ɪ'senʃl/","meaning":"n.必需品；必不可少的东西；要素，要点 adj.必不可少的；最基本的；本质的","unit":2,"lesson":2,"seq":30,"isStar":false,"example":"Pursuing a career is an essential part of adolescent development. 追求职业生涯是青少年发展的一个必不可少的部分。"},{"id":406,"word":"fundamental","pronunciation":"/fʌndə'mentl/","meaning":"adj.根本的；基本的；必不可少的 n.基本原理","unit":2,"lesson":2,"seq":31,"isStar":false,"memo":"联想 fund(资金)+a+mental(精神的)→物质和精神对人的发展都是“必不可少的”。","example":"Diversity, it seems, has not helped to address fundamental weaknesses in business leadership. 多元化似乎并没有帮助解决企业领导力的根本弱点。"},{"id":407,"word":"foundation","pronunciation":"/faʊn'deʃn/","meaning":"n.基础；根据；创办；基金会；地基","unit":2,"lesson":2,"seq":32,"isStar":false,"memo":"构词 found(建立)+-ation(名词后缀)→基础;创办;地基","example":"This provided a solid foundation for their marriage. 这为他们的婚姻提供了坚实的基础。"},{"id":408,"word":"cornerstone","pronunciation":"/'kɔːnəstəʊn/","meaning":"n.基石；基础","unit":2,"lesson":2,"seq":33,"isStar":false},{"id":409,"word":"milestone","pronunciation":"/'maɪlstəʊn/","meaning":"n.重要事件；里程碑","unit":2,"lesson":2,"seq":34,"isStar":false,"memo":"构词 mile(英里)+stone(石头)→每英里设置的界石,用来标记距离→里程碑","example":"It's one of the greatest milestones in my life. 这是我生命中的重要事件之一。"},{"id":410,"word":"landmark","pronunciation":"/'lændmɑːk/","meaning":"n.地标；里程碑","unit":2,"lesson":2,"seq":35,"isStar":false,"memo":"构词 land(陆地)+mark(标记)→地标;里程碑","example":"Streets, landmarks and places of interest are included. 街道、地标和名胜都被包括在内。"},{"id":411,"word":"crucial","pronunciation":"/'kruːl/","meaning":"adj.至关重要的，关键的","unit":2,"lesson":2,"seq":36,"isStar":false,"memo":"谐音 单词发音类似“可入手”→可以入手的东西是“至关重要的”。","example":"And with such purchases, price is only one of many crucial factors to consider. 对于这样的购买行为,价格只是需要考虑的众多关键因素之一。"},{"id":412,"word":"cardinal","pronunciation":"/'kɑːdɪnl/","meaning":"adj.最重要的；基本的 n.枢机主教；基数","unit":2,"lesson":2,"seq":37,"isStar":false,"memo":"联想 card(卡片)+in(在……里面)+al(联想 all)→这张卡是所有卡里“最重要的”。","example":"As a salesman, your cardinal rule is to do everything you can to satisfy a customer. 作为一名推销员,你的首要原则就是要尽你所能使客户满意。"},{"id":413,"word":"imperative","pronunciation":"/ɪm'perətv/","meaning":"adj.重要紧急的，迫切的 n.重要紧急的事","unit":2,"lesson":2,"seq":38,"isStar":false,"memo":"联想 i(我)+m(联想“妹”)+per(每)+ative(联想 active)→我妹妹每天都很积极、主动地工作,因为她在做“重要紧急的事”。","example":"It is most imperative to focus our efforts on the elimination of income inequality. 最重要的是,我们要集中力量消除收入不平等。"},{"id":414,"word":"necessary","pronunciation":"/'nesəsəri/","meaning":"adj.必需的，必要的","unit":2,"lesson":2,"seq":39,"isStar":false,"memo":"谐音 单词发音类似“奶是色弱”→奶奶色弱,帮她辨别颜色是“必要的”。","example":"Food is necessary for survival. 食物是生存所必需的。"},{"id":415,"word":"necessitate","pronunciation":"/nə'sesɪteɪt/","meaning":"v.使成为必要","unit":2,"lesson":2,"seq":40,"isStar":false},{"id":416,"word":"primary","pronunciation":"/'praɪməri/","meaning":"adj.主要的；最重要的；最初的 n.(美国)初选","unit":2,"lesson":2,"seq":41,"isStar":false,"memo":"对照 小学(primary school)教育是最初的(primary)教育。","example":"Primary care should be the backbone of any health care system. 初级保健应该成为任何卫生保健系统的支柱。","derivative":"primarily /ˈpraɪmerəli; ˈpraɪmərəli/ adv.主要地;根本地"},{"id":417,"word":"primarily","pronunciation":"/praɪˈmerəli;<br>ˈpraɪmərəli/","meaning":"adv.主要地;根本地","unit":2,"lesson":2,"seq":0,"isStar":true},{"id":418,"word":"secondary","pronunciation":"/ˈsekəndri/","meaning":"adj.次要的;从属的;中学的","unit":2,"lesson":2,"seq":42,"isStar":false,"memo":"构词 second(第二)+-ary(形容词后缀)→次要的","example":"Concepts and contextual implications are of secondary importance to journalistic interviewing. 对于新闻采访来说,概念和语境的暗示是次要的。"},{"id":419,"word":"primitive","pronunciation":"/ˈprɪmətɪv/","meaning":"adj.原始的;本能的","unit":2,"lesson":2,"seq":43,"isStar":false,"memo":"构词 prim(最初,原始)+-itive(形容词后缀)→原始的","example":"In primitive times, human beings did not travel for pleasure but to find a more favourable climate. 在原始时期,人类旅行不是为了乐趣,而是为了寻找更有利的气候环境。"},{"id":420,"word":"prime","pronunciation":"/praɪm/","meaning":"adj.最重要的,首要的;优质的 n.盛 年;鼎盛时期 v.使(某人)做好准备","unit":2,"lesson":2,"seq":44,"isStar":false,"memo":"联想 pri(第一,首要)+me(我)→我是“首要的”。","example":"The emotional and physical stress that occurs due to odd working hours is a prime reason for a large amount of career dissatisfaction. 由于不规律的工作时间产生的情绪和身体压力是造成大量职业不满的主要原因。"},{"id":421,"word":"prior","pronunciation":"/ˈpraə(r)/","meaning":"adj.先前的;较早的;优先的;在…… 前面的","unit":2,"lesson":2,"seq":45,"isStar":false,"memo":"联想 pri-(=pre-,前)+or(联想“表示人的后缀”)→先前的;较早的","example":"Please give us prior notice if you need an evening meal. 如果您需要用晚餐,请预先通知我们。"},{"id":422,"word":"priority","pronunciation":"/praɪˈɒrəti/","meaning":"n.优先事项,当务之急;优先权 adj.优先的","unit":2,"lesson":2,"seq":46,"isStar":false,"example":"Priority should be given to the economic needs of senior citizens. 应该优先考虑老年人的经济需求。"},{"id":423,"word":"spot","pronunciation":"/spɒt/","meaning":"n.斑点;污渍;场所 v.看见,注意到,发现","unit":2,"lesson":3,"seq":1,"isStar":false,"memo":"s(联想“美女”)+pot(音似“泡它”)→一个美女泡茶时把“污渍”弄到身上了。","example":"On a trip, a person can learn directly by visiting museums and historic spots. 在旅行中,一个人可以通过参观博物馆和历史景点直接学习。"},{"id":424,"word":"pottery","pronunciation":"/ˈpɒtəri/","meaning":"n.陶器;陶土;制陶手艺;制陶厂","unit":2,"lesson":3,"seq":2,"isStar":false},{"id":425,"word":"spotlight","pronunciation":"/ˈspɒtlat/","meaning":"n.聚光灯 v.使突出,使显眼","unit":2,"lesson":3,"seq":3,"isStar":false},{"id":426,"word":"potential","pronunciation":"/pətenʃl/","meaning":"n.潜能,潜力 adj.潜在的,可能的","unit":2,"lesson":3,"seq":4,"isStar":false,"memo":"单词发音类似“陪他瘦”→陪他一起瘦,我有这个“潜能”。","example":"As incomes rise among low-income consumers, the potential for further grain consumption is huge. 随着低收入消费者的收入增加,粮食消费进一步增加的潜力巨大。","derivative":"potentiality /pəˌteniˈæləti/ n.潜力;潜在的可能性"},{"id":427,"word":"potentiality","pronunciation":"/pəˌtenʃiˈæləti/","meaning":"n.潜力;潜在的可能性","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":428,"word":"permanent","pronunciation":"/ˈpɜːmənənt/","meaning":"adj.永久的,永恒的","unit":2,"lesson":3,"seq":5,"isStar":false,"memo":"per(每)+man(人)+ent(联想enter)→每个人都想进入这座房子,让它成为自己“永久的”住所。","example":"The only real solution appears to be to hand over the night shift to a number of permanent night workers. 唯一的真正解决方法似乎是将夜班交给一些长期的夜间工作者。","derivative":"permanence /ˈpɜːrmənəns/ n.永久;持久性"},{"id":429,"word":"permanence","pronunciation":"/ˈpɜːmənəns/","meaning":"n.永久;持久性","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":430,"word":"perpetual","pronunciation":"/pəˈpetʃuəl/","meaning":"adj.不间断的,持续的;永久的","unit":2,"lesson":3,"seq":6,"isStar":false,"memo":"per(每)+pet(宠物)+-ual(形容词后缀)→她每天喂养她的宠物,从不间断→不间断的","example":"Because of the perpetual noise of traffic, I couldn't get to sleep last night. 由于交通噪声不断,我昨晚无法入睡。","derivative":"perpetuate /pəpetʃueɪt/ v.使永久化;使持久化;使持续"},{"id":431,"word":"perpetuate","pronunciation":"/pəˈpetʃueɪt/","meaning":"v.使永久化;使持久化;使持续","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":432,"word":"eternal","pronunciation":"/ɪˈtɜːnl/","meaning":"adj.永恒的,永远的","unit":2,"lesson":3,"seq":7,"isStar":false,"memo":"联想 eter(音似“一特”) + n(形似门) + -al (形容词后缀) → 这一扇特色之门是城市“永恒 的”印记。","example":"A wedding ring is a symbol of eternal love. 结婚戒指是永恒爱情的象征。","derivative":"eternity /'tɜːrnəti/ n. 永恒；永生；不朽"},{"id":433,"word":"eternity","pronunciation":"/ɪtɜːnəti/","meaning":"n.永恒;永生;不朽","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":434,"word":"permeate","pronunciation":"/ˈpɜːmieɪt/","meaning":"v.弥漫,渗透;(观点、信念、感情等) 感染","unit":2,"lesson":3,"seq":8,"isStar":false,"memo":"联想 per(每) + meat(肉) + e(联想“鹅”) → 每次我在家炖鹅肉，香味都会“弥漫”于整个房间。","example":"Eventually, the water will permeate through the surrounding concrete. 最终，水会渗透进周围的混凝土中。","derivative":"permeation /ˌpɜrmieɪʃn/ n. 渗透"},{"id":435,"word":"permeation","pronunciation":"/ˌpɜːmiˈeɪʃn/","meaning":"n.渗透","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":436,"word":"blend","pronunciation":"/blend/","meaning":"v.使混合,融合 n.混合物","unit":2,"lesson":3,"seq":9,"isStar":false,"memo":"联想 b(联想“不”) + lend(借) → 不要把书借给他，因为他会把书弄混的 → 使混合","example":"It is a delicacy blended with bread. 这是一种与面包混合而成的美食。"},{"id":437,"word":"tangle","pronunciation":"/'tæŋɡl/","meaning":"n.乱糟糟的一堆;混乱;争吵 v.(使)缠结","unit":2,"lesson":3,"seq":10,"isStar":false,"memo":"谐音 单词发音类似“探戈”→很多人在一起跳探戈，场面有点“混乱”。","example":"Her hair tends to tangle. 她的头发易打结。"},{"id":438,"word":"mess","pronunciation":"/mes/","meaning":"n.肮脏;杂乱 v.弄乱","unit":2,"lesson":3,"seq":11,"isStar":false,"memo":"联想 me(我) + ss(音似“死”) → 回到家看到“杂乱”的一堆衣服，我烦得要死。","example":"The kids made a mess in the bathroom. 孩子们把浴室搞得一塌糊涂。","derivative":"messy /'mesi/ adj.肮脏的；凌乱的"},{"id":439,"word":"messy","pronunciation":"/'mesi/","meaning":"adj.肮脏的;凌乱的","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":440,"word":"chaos","pronunciation":"/'keɪɒs/","meaning":"n.混乱,杂乱","unit":2,"lesson":3,"seq":12,"isStar":false,"memo":"联想 chao(联想“吵”) + s(联想“死”) → 这条街上吵死了，场面很“混乱”。","example":"Heavy snow has caused total chaos on the roads. 大雪导致道路上交通一片混乱。","derivative":"chaotic /keɪ'ɑːtɪk/ adj.混乱的"},{"id":441,"word":"chaotic","pronunciation":"/keɪ'ɒtɪk/","meaning":"adj.混乱的","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":442,"word":"chore","pronunciation":"/tʃɔː(r)/","meaning":"n.日常事务;乏味无聊的工作","unit":2,"lesson":3,"seq":13,"isStar":false},{"id":443,"word":"disorder","pronunciation":"/dɪs'ɔdə(r)/","meaning":"n.混乱,骚乱;失调","unit":2,"lesson":3,"seq":14,"isStar":false,"memo":"【构词】dis-(否定前缀)+order(顺序)→没有顺序→混乱;失调","example":"This is a rare disorder of the liver. 这是一种罕见的肝功能紊乱。"},{"id":444,"word":"joint","pronunciation":"/dʒɔɪnt/","meaning":"adj.联合的,共同的 n.关节;接头;接合处","unit":2,"lesson":3,"seq":15,"isStar":false,"memo":"【对照】两根骨头连接(join)的地方就是关节(joint)。","example":"The report was a joint effort. 这个报告是大家共同努力的成果。"},{"id":445,"word":"adjacent","pronunciation":"/ə'dʒesnt/","meaning":"adj.毗连的,邻近的","unit":2,"lesson":3,"seq":16,"isStar":false,"memo":"【谐音】单词发音类似“爱近身的”→爱身边的人→邻近的","example":"This occurs almost exclusively between classes which are adjacent to each other. 这种情况几乎只发生在彼此相邻的类别之间。"},{"id":446,"word":"compound","pronunciation":"/'kɒmpaʊnd/","meaning":"n.混合物;化合物 adj.复合的 /kəm'paʊnd/ v.使恶化,加重","unit":2,"lesson":3,"seq":17,"isStar":false,"memo":"【联想】com-(所有的)+pound(音似“泡的”)→我们早晨吃泡的牛奶、坚果等“混合物”。","example":"A compound sentence contains two or more clauses. 复合句包含两个或两个以上从句。"},{"id":447,"word":"hybrid","pronunciation":"/'haɪbrɪd/","meaning":"n.杂种动物;杂交植物;(不同事物的) 混合物","unit":2,"lesson":3,"seq":18,"isStar":false},{"id":448,"word":"turbulent","pronunciation":"/'tɜːbjələnt/","meaning":"adj.动荡的,动乱的;汹涌的","unit":2,"lesson":3,"seq":19,"isStar":false,"memo":"【联想】tur(音似“他”)+bu(联想“不”)+lent(借)→在“动荡的”年代,他不愿意把自己的东西借出去,因为可能永远都要不回来了。","example":"Even during the turbulent years of last century, youth rebellion was often exaggerated in the media. 即使是在上个世纪的动荡年代,关于青少年叛逆的现象也经常被媒体夸大。","derivative":"turbulence /'tɜːbjələns/ n.骚乱;(空气或水的)湍流,紊流"},{"id":449,"word":"turbulence","pronunciation":"/'tɜːbjələns/","meaning":"n.骚乱;(空气或水的)湍流,紊流","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":450,"word":"turmoil","pronunciation":"/'tɜːmɔɪl/","meaning":"n.混乱;动乱;骚动;焦虑","unit":2,"lesson":3,"seq":20,"isStar":false},{"id":451,"word":"fluctuate","pronunciation":"/'flʌktʃueɪt/","meaning":"v.(大小、数量、质量等)波动,起伏","unit":2,"lesson":3,"seq":21,"isStar":false,"memo":"【联想】flu(感冒)+c(音似“咳”)+t(联想“他”)+uate→他感冒了,咳嗽得厉害,情绪“波动”也较大。","example":"The analysis reveals that intensity appears to fluctuate with a clear, well-defined rhythm. 分析表明,强度似乎以清晰、明确的节奏波动。","derivative":"fluctuation /ˌflʌktʃu'eɪʃn/ n.波动,起伏"},{"id":452,"word":"fluctuation","pronunciation":"/ˌflʌktu'eɪʃn/","meaning":"n.波动,起伏","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":453,"word":"stationary","pronunciation":"/'steʃənri/","meaning":"adj.不动的,静止的;固定的","unit":2,"lesson":3,"seq":22,"isStar":false,"memo":"【联想】sta(联想 stay)+-tion(名词后缀)+-ary(形容词后缀)→一个人一直待在一个地方,就是“不动的”。","example":"As an excellent shooter, Peter practised aiming at both stationary targets and moving targets. 作为一名出色的射手,彼得练习瞄准静止目标和移动目标。"},{"id":454,"word":"station","pronunciation":"/'steɪʃn/","meaning":"n.站;地位;身份;驻地 v.配置;驻扎;安置","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":455,"word":"static","pronunciation":"/'stætɪk/","meaning":"adj.静止的;停滞的 n.静电","unit":2,"lesson":3,"seq":23,"isStar":false,"memo":"联想 sta(联想 stay) + -tic → 有个人一直待在一个地方站着不动，像是“静止的”。","example":"Don't view things as static and isolated. 不要静止地、孤立地看待事物。"},{"id":456,"word":"statute","pronunciation":"/'stætjut/","meaning":"n.成文法;法规;章程,条例","unit":2,"lesson":3,"seq":24,"isStar":false,"memo":"联想 sta (联想 state) + tute (音似“突他”) → 国家要突击检查他，需要有“法规”的依据。","example":"Penalties are laid down in the statute. 法规中有关于惩罚措施的规定。"},{"id":457,"word":"statutory","pronunciation":"/'stætʃətri/","meaning":"adj.法定的;依法必须执行的","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":458,"word":"status","pronunciation":"/'steɪtəs/","meaning":"n.地位;身份;状况","unit":2,"lesson":3,"seq":25,"isStar":false,"memo":"联想 stat(联想 state) + us(我们) → 在我们国家，我们的“地位”都是平等的。","example":"People's earnings are closely related to people's social status. 人们的收入与其社会地位密切相关。"},{"id":459,"word":"statistic","pronunciation":"/stə'tɪstk/","meaning":"n.统计数字;统计资料;(一项)统计数据","unit":2,"lesson":3,"seq":26,"isStar":false},{"id":460,"word":"statistical","pronunciation":"/stə'tɪstɪkl/","meaning":"adj.统计的","unit":2,"lesson":3,"seq":0,"isStar":true},{"id":461,"word":"fierce","pronunciation":"/fiːs/","meaning":"adj.凶猛的;猛烈的,强烈的","unit":2,"lesson":3,"seq":27,"isStar":false,"memo":"谐音 单词发音类似“飞蛾死”→飞蛾扑火的劲头是“猛烈的”。","example":"It was one of the fiercest battles of the 19th century. 这是19世纪最激烈的战役之一。"},{"id":462,"word":"harsh","pronunciation":"/hɑːʃ/","meaning":"adj.残酷的;严厉的;恶劣的","unit":2,"lesson":3,"seq":28,"isStar":false,"memo":"联想 har(联想 hard) + sh(音似“事”) → 艰难的事 → 残酷的","example":"Some species develop a unique life pattern to survive in extremely harsh conditions. 一些物种发展出一种独特的生存模式，以在极端恶劣的条件下生存。"},{"id":463,"word":"rigorous","pronunciation":"/'rɡərəs/","meaning":"adj.密的;严酷的;严格的","unit":2,"lesson":3,"seq":29,"isStar":false,"memo":"联想 ri(联想“日”) + go(去) + rous → 日子一天天过去了，时间还是很“严酷的”。","example":"The rigorous requirements placed on the writing of poetry stimulate the poet's creativity. 对诗歌创作的严格要求激发了诗人的创造力。"},{"id":464,"word":"rigo(u)r","pronunciation":"/'rɪɡə(r)/","meaning":"n.严酷;缜密,严谨","unit":2,"lesson":3,"seq":30,"isStar":false},{"id":465,"word":"savage","pronunciation":"/'sævɪd/","meaning":"n.野蛮人 v.凶猛地攻击(或伤害);猛烈批评 adj.凶残的;野蛮的","unit":2,"lesson":3,"seq":31,"isStar":false,"memo":"联想 sav(联想 save) + age(年龄) → 他从那个“凶残的”人手上救出了年幼的孩子。","example":"She was savaged to death by a bear. 她遭熊袭击而丧命。"},{"id":466,"word":"bureau","pronunciation":"/'bjʊərəʊ/","meaning":"n.(美国政府部门的)局,处,科;办事处;机构","unit":2,"lesson":4,"seq":1,"isStar":false,"memo":"谐音 单词发音类似“不弱”→在“局”里办公的人,能力真不弱。","example":"The Census Bureau has estimated statistics similar to the administration's proposal. 人口普查局估计的统计数据与政府的提议类似。"},{"id":467,"word":"bureaucrat","pronunciation":"/'bjʊərəkræt/","meaning":"n.官僚主义者;官僚","unit":2,"lesson":4,"seq":2,"isStar":false},{"id":468,"word":"bureaucratic","pronunciation":"/ˌbjʊərə'krætɪk/","meaning":"adj.官僚的","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":469,"word":"bureaucracy","pronunciation":"/bjʊə'rɒkrəsi/","meaning":"n.官僚主义;官僚体制;官僚作风","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":470,"word":"headquarters","pronunciation":"/ˌhed'kwɔːtəz/","meaning":"n.总部,总公司;指挥部","unit":2,"lesson":4,"seq":3,"isStar":false,"memo":"联想 head(头部)+quarter(四分之一)+s →四分之一的人物在头部公司→总部,总公司","example":"Its headquarters houses some 3,000 works of art. 它的总部收藏了大约3,000件艺术品。"},{"id":471,"word":"council","pronunciation":"/'kaʊnsl/","meaning":"n.政务委员会;地方议会","unit":2,"lesson":4,"seq":4,"isStar":false,"memo":"联想 coun(联想 con-,都)+cil(音似“搜”) →每次去“地方议会”,都会被搜身。","example":"The city council has finally voted the funds to build a new high school. 市议会终于表决通过了建造一所新高中的拨款。","derivative":"councillor /'kaʊnsələ(r)/ n.市议员;政务委员会委员"},{"id":472,"word":"council(l)or","pronunciation":"/'kaʊnsələ(r)/","meaning":"n.市议员;政务委员会委员","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":473,"word":"institute","pronunciation":"/'ɪnstɪtjuːt/","meaning":"v.制定(体系;政策等);实行n.学院;研究所;机构","unit":2,"lesson":4,"seq":5,"isStar":false,"memo":"联想 in(里面)+stitute(=stand)→耸立在大学里的那个建筑物是他们“学院”的。","example":"The new management intends to institute a number of changes. 新的管理层打算实行一些改革。"},{"id":474,"word":"institution","pronunciation":"/ˌɪnstɪ'tjuːʃn/","meaning":"n.机构;制度","unit":2,"lesson":4,"seq":6,"isStar":false,"memo":"构词 institut(e)(机构)+-ion(名词后缀) →机构","example":"The region boasts several institutions of higher education. 该地区拥有几所高等教育机构。","derivative":"institutional /ˌɪnstɪ'tjuːʃənl/ adj.机构的;慈善机构的;惯例的"},{"id":475,"word":"institutional","pronunciation":"/ˌɪnstɪ'tjuːʃənl/","meaning":"adj.机构的;慈善机构的;惯例的","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":476,"word":"agent","pronunciation":"/'eɪdʒənt/","meaning":"n.代理人,经纪人","unit":2,"lesson":4,"seq":7,"isStar":false,"memo":"谐音+联想：'agent'→ '阿金特'——007代号？不，是'行动金特使'，代表别人干活的执行者！","example":"The university's career agent helps graduates find internships abroad. 学校的职业代理人为毕业生寻找海外实习机会。","derivative":"agency /ˈeɪdʒənsi/ n.代理机构；activate /ˈæktɪveɪt/ v.激活（同源act-）"},{"id":477,"word":"agency","pronunciation":"/'eɪdʒənsi/","meaning":"n.代理机构;(政府的)专门机构","unit":2,"lesson":4,"seq":8,"isStar":false,"memo":"[联想] agen(t)(代理人) + c + -y(名词后缀) → 代理机构","example":"Our agent in New York deals with all US sales. 我们在纽约的代理商经办在整个美国的销售。I just called the travel agency. It's all set. 我刚给旅行社打了电话。都安排好了。"},{"id":478,"word":"substitute","pronunciation":"/'sʌbstɪtjuːt/","meaning":"n.代替者,代替物 v.(以……)代替,取代","unit":2,"lesson":4,"seq":9,"isStar":false,"memo":"[构词] sub-(下面) + stitute(= stand)→站在下面→候补→代替者","example":"Multivitamins are no substitute for exercise and a balanced diet, of course. 当然,复合维生素不能代替运动和均衡的饮食。","derivative":"substitution /sʌbstɪˈtjuːʃn/ n.替代;代替物"},{"id":479,"word":"substitution","pronunciation":"/sʌbstɪ'tjuːʃn/","meaning":"n.替代;代替物","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":480,"word":"constitute","pronunciation":"/'kɒnstɪtjuːt/","meaning":"v.组成,构成;设立;被视为,被算作","unit":2,"lesson":4,"seq":10,"isStar":false,"memo":"[构词] con-(一起) + stitute( = stand)→站在一起→组成,构成","example":"Their behaviours do not constitute a warning signal. 他们的行为并不构成警告信号。","derivative":"constitution /ˌknstɪˈtjuʃn/ n.宪法;组成;结构 constitutional /ˌknstɪˈtjuʃənl/ adj.宪法的;体质的,体格"},{"id":481,"word":"constitution","pronunciation":"/ˌkɒnst'tjuːʃn/","meaning":"n.宪法;组成;结构","unit":2,"lesson":4,"seq":0,"isStar":true,"memo":"con（共同）+stitut（建立）+ion→大家共同建立的‘宪法’，就像班规是全班立的‘班级宪法’！","example":"The new constitution guarantees digital privacy rights. 新宪法保障数字隐私权。","derivative":"constitutional /ˌkɒnstɪ'tjuːʃ(ə)n(ə)l/ adj.宪法的；constitutionally /ˌkɒnstɪ'tjuːʃ(ə)nəli/ adv.合宪地"},{"id":482,"word":"constitutional","pronunciation":"/ˌkɒnstɪ'tjuːʃənl/","meaning":"adj.宪法的;体质的,体格的","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":483,"word":"constituent","pronunciation":"/kən'stɪtʃuənt/","meaning":"n.(选区的)选民;成分 adj.组成的,构成的","unit":2,"lesson":4,"seq":11,"isStar":false,"memo":"[构词] constitu(te)(组成) + -ent(后缀)→组成选举的人→选民;组成的","example":"She has the full support of her constituents. 她得到了她的选民们的全力支持。","derivative":"constituency /kənˈstɪtjuənsi/ n.选区;选区的选民;支持者"},{"id":484,"word":"constituency","pronunciation":"/kən'stɪtʃuənsi/","meaning":"n.选区;选区的选民;支持者","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":485,"word":"federal","pronunciation":"/'fedərəl/","meaning":"adj.联邦政府的","unit":2,"lesson":4,"seq":12,"isStar":false,"memo":"[构词] feder(联盟,同盟) + -al(形容词后缀)→联邦政府的","example":"However, federal rules forbid the practice of making ads louder than the programming. 然而,联邦法规禁止广告音量超过节目音量的做法。","derivative":"federation /ˌfedəˈreɪʃn/ n.联邦;联合会;联盟"},{"id":486,"word":"federation","pronunciation":"/ˌfedə'reɪʃn/","meaning":"n.联邦;联合会;联盟","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":487,"word":"commonwealth","pronunciation":"/'kmənwelθ/","meaning":"n.英联邦;联合体","unit":2,"lesson":4,"seq":13,"isStar":false,"memo":"[构词] common(共同的) + wealth(富裕)→所有地方都追求共同富裕→英联邦;联合体","example":"The Queen was the ceremonial head of the Commonwealth. 女王曾是英联邦的仪式性领袖。"},{"id":488,"word":"minister","pronunciation":"/'mɪnɪstə(r)/","meaning":"n.(英国及其他许多国家的)部长;外交使节;大臣","unit":2,"lesson":4,"seq":14,"isStar":false,"memo":"联想 mini(小的) + st(联想 stand) + -er(表示人的后缀) → 古代的“大臣”站在皇帝面前会自称“小人”。","example":"He has been successfully elected Prime Minister. 他已成功当选首相。","derivative":"ministerial /ˌmɪnɪ'stɪəriəl/ adj.部长的;大臣的"},{"id":489,"word":"ministerial","pronunciation":"/ˌmɪn'stɪəriəl/","meaning":"adj.部长的;大臣的","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":490,"word":"administer","pronunciation":"/əd'mɪnɪstə(r)/","meaning":"v.管理;治理;执行","unit":2,"lesson":4,"seq":15,"isStar":false,"memo":"构词 ad-(朝，向) + minister(部长) → 部长所为 → 管理","example":"The pension funds are administered by commercial banks. 养老基金由商业银行经营。","derivative":"administrative /əd'mɪnstrətɪv/ adj.管理的;行政的 administration /ədˌmɪnɪ'streʃn/ n.(企业、学校等的)管理部门,行政部门;行政"},{"id":491,"word":"administrative","pronunciation":"/əd'mnɪstrətɪv/","meaning":"adj.管理的;行政的","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":492,"word":"administration","pronunciation":"/ədˌmɪnɪ'streʃn/","meaning":"n.(企业、学校等的)管理部门,行政部门;行政","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":493,"word":"harness","pronunciation":"/'hɑːnɪs/","meaning":"v.控制;给(马等)上挽具 n.挽具,马具;系带","unit":2,"lesson":4,"seq":16,"isStar":false,"memo":"联想 harne(音似 honey) + ss(联想“蛇”) → 想吃蜂蜜的两条蛇被他“控制”了。","example":"The most promising strategy has become to harness one foe against the other. 最有希望的策略已经变成利用一个敌人来控制另一个敌人。"},{"id":494,"word":"ministry","pronunciation":"/'mɪnɪstri/","meaning":"n.(政府的)部;牧师","unit":2,"lesson":4,"seq":17,"isStar":false,"memo":"对照 部长(minister)努力工作的地方就是部(ministry)。","example":"They are responsible merely to their Ministry of Education. 他们只对他们的教育部负责。"},{"id":495,"word":"secretary","pronunciation":"/'sekrətri/","meaning":"n.秘书;干事,文书;部长","unit":2,"lesson":4,"seq":18,"isStar":false,"memo":"构词 secret(秘密) + -ary(表示人的后缀) → 秘书","example":"She can't do without a secretary. 她不能没有秘书。","derivative":"secretarial /sekrə'teəriəl/ adj.秘书的;文秘工作的"},{"id":496,"word":"secretarial","pronunciation":"/ˌsekrə'teəriəl/","meaning":"adj.秘书的;文秘工作的","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":497,"word":"mayor","pronunciation":"/meə(r)/","meaning":"n.市长","unit":2,"lesson":4,"seq":19,"isStar":false,"example":"The mayor was asked to condense his speech. 市长被要求精简他的讲话。"},{"id":498,"word":"official","pronunciation":"/ə'fɪʃl/","meaning":"adj.公务的,公职的;正式的,官方的 n.官员","unit":2,"lesson":4,"seq":20,"isStar":false,"example":"He was an official from the community. 他是社区的一名官员。"},{"id":499,"word":"casual","pronunciation":"/'kæuəl/","meaning":"adj.随意的,偶然的;非正式的","unit":2,"lesson":4,"seq":21,"isStar":false,"memo":"联想 casu(联想“卡苏”，人名) + -al(形容词后缀) → 卡苏穿得很随意 → 随意的 构词 cas(e)(特殊情况) + -ual(形容词后缀) → 发生特殊情况的 → 偶然的；随意的","example":"The author felt as a boy that his life in a separated neighbourhood was casual and cosy. 作者觉得，作为一个男孩，他在独立社区的生活是随意和舒适的。"},{"id":500,"word":"casualty","pronunciation":"/'kæuəlti/","meaning":"n.伤员;受害者;急诊室","unit":2,"lesson":4,"seq":22,"isStar":false,"memo":"构词 cas(e)(病例) + -ual(形容词后缀) + -ty(名词后缀) → 伤员","example":"Our primary objective is reducing road casualties. 我们的首要目标是减少交通事故伤亡。"},{"id":501,"word":"knight","pronunciation":"/naɪt/","meaning":"n.骑士;爵士 v.封(某人)为爵士","unit":2,"lesson":4,"seq":23,"isStar":false},{"id":502,"word":"delegate","pronunciation":"/'delɪɡət/","meaning":"n.代表;参会人员 /'delɪɡeɪt/ v.授权;委派","unit":2,"lesson":4,"seq":24,"isStar":false,"memo":"[联想] dele(联想 delete) + gate(门)→删除门,即清除壁垒→产生壁垒的时候,双方一般会派“代表”进行沟通。","example":"Many delegates were in favor of his proposal. 许多代表都赞成他的建议。","derivative":"delegation /ˌdelɪˈɡeɪʃn/ n.代表团;委托"},{"id":503,"word":"delegation","pronunciation":"/ˌdelɪ'ɡeɪʃn/","meaning":"n.代表团;委托","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":504,"word":"threshold","pronunciation":"/'θrehəʊld/","meaning":"n.门槛,门口;起点;开端","unit":2,"lesson":4,"seq":25,"isStar":false,"memo":"[构词] thres(h)(打→根) + hold(支撑)→支撑在门下的根→门槛→起点","example":"She felt as though she was on the threshold of a new life. 她觉得好像就要开始新生活了。"},{"id":505,"word":"propagate","pronunciation":"/'prɒpəɡeɪt/","meaning":"v.传播,宣传;繁殖","unit":2,"lesson":4,"seq":26,"isStar":false,"memo":"[联想] pro-(提前) + pa(联想“爸”) + gate(大门)→爸爸提前在大门口发传单,“宣传”垃圾分类。","example":"Plants won't propagate in these conditions. 植物在这些条件下不能繁殖。","derivative":"propagation /ˌprɒpəˈɡeɪʃn/ n.传播;繁殖"},{"id":506,"word":"propagation","pronunciation":"/prɒpə'ɡeɪʃn/","meaning":"n.传播;繁殖","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":507,"word":"propaganda","pronunciation":"/ˌprɒpə'ɡændə/","meaning":"n.宣传;鼓吹","unit":2,"lesson":4,"seq":27,"isStar":false,"memo":"[联想] pro-(提前) + pa(联想“爸”) + gan (联想“干”) + da(联想“大”)→爸爸提前说要干番大事业,还没行动就开始“鼓吹”了。","example":"The new indicator is a “propaganda device” to promote income redistribution. 这个新指标是一种“宣传手段”,能促进收入再分配。"},{"id":508,"word":"publicise/-ize","pronunciation":"/'pʌblɪsaɪz/","meaning":"v.宣传,推广","unit":2,"lesson":4,"seq":28,"isStar":false},{"id":509,"word":"public","pronunciation":"/'pʌblɪk/","meaning":"adj.大众的;公开的 n.百姓;公众","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":510,"word":"publicly","pronunciation":"/'pʌblɪkli/","meaning":"adv.公开地","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":511,"word":"publicity","pronunciation":"/pʌb'lɪsəti/","meaning":"n.(媒体的)关注,宣传,报道","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":512,"word":"vote","pronunciation":"/vəʊt/","meaning":"n.选票;投票权 v.选举,投票","unit":2,"lesson":4,"seq":29,"isStar":false,"memo":"[谐音] 单词发音类似“我他”→我为他“投票”。"},{"id":513,"word":"voter","pronunciation":"/'vəʊtə(r)/","meaning":"n.投票人,选举人","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":514,"word":"veto","pronunciation":"/'viːtəʊ/","meaning":"n.否决权 v.禁止;反对,否定","unit":2,"lesson":4,"seq":30,"isStar":false,"memo":"[谐音] 单词发音类似“未投”→未投票就是否决了→否决权;反对","example":"A girl may veto the spouse her parents have chosen. 一个女孩可以拒绝父母为她选择的对象。"},{"id":515,"word":"regime","pronunciation":"/reɪ'ʒiːm/","meaning":"n.政权;政体;制度","unit":2,"lesson":4,"seq":31,"isStar":false,"memo":"[谐音] 单词发音类似“叠积木”→建立“制度”也像搭建积木一样,要一层一层地建立起来。","example":"Changes to next year's funding regime are forcing universities to justify charging students up to £9,000 in fees. 明年经费制度的变化迫使大学证明向学生收取高达9,000英镑的费用是合理的。"},{"id":516,"word":"reign","pronunciation":"/reɪn/","meaning":"n.(君主)统治时期;任期   v.统治;当政","unit":2,"lesson":4,"seq":32,"isStar":false,"memo":"[对照] 同音词 rain→古时候人们认为龙王具有统治(reign)力和支配力,可以决定下雨(rain)与否。","example":"The house was built during the reign of Henry VIII. 那栋房子是亨利八世统治时期建造的。"},{"id":517,"word":"loyal","pronunciation":"/'lɔɪəl/","meaning":"adj.忠诚的,忠实的","unit":2,"lesson":4,"seq":33,"isStar":false,"memo":"[谐音] 单词发音类似“老友”→老友一般都是很“忠诚的”。","example":"The middle class used to be loyal to the free enterprise system. 中产阶级曾经忠于自由企业制度。","derivative":"loyalty /'lɔɪəlti/ n.忠诚,忠实"},{"id":518,"word":"loyalty","pronunciation":"/'lɔɪəlti/","meaning":"n.忠诚,忠实","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":519,"word":"royal","pronunciation":"/'rɔɪəl/","meaning":"n.王室成员 adj.王室的;皇家的","unit":2,"lesson":4,"seq":34,"isStar":false,"memo":"[谐音] 单词发音类似“荣耀”→荣耀的→王室的;皇家的","example":"She is from the royal family. 她来自皇室。","derivative":"royalty /'rɔɪəlti/ n.王室成员;版税"},{"id":520,"word":"royalty","pronunciation":"/'rɔɪəlti/","meaning":"n.王室成员;版税","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":521,"word":"salute","pronunciation":"/səˈluːt/","meaning":"v. & n.敬礼;致敬","unit":2,"lesson":4,"seq":35,"isStar":false,"memo":"[联想] sa(联想“啥”) + lu(联想“路”) + te(联想“他”)→为啥在路上见到他要“敬礼”?","example":"The sergeant stood to attention and saluted. 中士立正敬礼。","derivative":"salutation /ˌsælju'teɪʃn/ n.招呼;致意;打招呼;致意的动作"},{"id":522,"word":"salutation","pronunciation":"/sæljuˈteɪʃn/","meaning":"n.招呼;致意;打招呼;致意的动作","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":523,"word":"sovereign","pronunciation":"/sɒvrɪn/","meaning":"n.君主;元首 adj.有主权的;权力至高无上的","unit":2,"lesson":4,"seq":36,"isStar":false,"memo":"[构词] sover-( = super-, 在……上面) + reign(统治)→最上面的统治者→君主;元首","example":"Today, the European Union is creating a $580 billion fund to ward off sovereign collapse. 如今,欧盟正在创建一个5,800亿美元的基金,以防止主权崩溃。","derivative":"sovereignty /'sɒvrənti/ n.主权;最高统治权"},{"id":524,"word":"sovereignty","pronunciation":"/ˈsɒvrənti/","meaning":"n.主权;最高统治权","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":525,"word":"emperor","pronunciation":"/ˈempərə(r)/","meaning":"n.皇帝","unit":2,"lesson":4,"seq":37,"isStar":false,"memo":"[联想] em(联想“俺妹”) + per(联想“怕”) + -or(表示人的后缀)→俺妹怕的人是“皇帝”。","example":"It is the tomb of the first real emperor of China, Emperor Qin Shi Huang. 它是中国第一位真正的皇帝秦始皇的坟墓。","derivative":"empress /'empres/ n.女皇;皇后"},{"id":526,"word":"empress","pronunciation":"/ˈemprəs/","meaning":"n.女皇;皇后","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":527,"word":"imperial","pronunciation":"/ɪmˈpɪəriəl/","meaning":"adj.帝国的,皇帝的","unit":2,"lesson":4,"seq":38,"isStar":false,"example":"The Imperial Palace is a magnificent building with a long history. 故宫是一座有着悠久历史的宏伟建筑。"},{"id":528,"word":"imperialism","pronunciation":"/ɪmˈpɪəriəlzəm/","meaning":"n.帝国统治;帝国主义","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":529,"word":"imperialist","pronunciation":"/ɪmˈpɪəriəlɪst/","meaning":"n.帝国主义者;帝国统治拥护者","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":530,"word":"civil","pronunciation":"/ˈsɪvl/","meaning":"adj.国内的;公民的;平民的,民事的; 有礼貌的","unit":2,"lesson":4,"seq":39,"isStar":false,"memo":"[谐音] 单词发音类似“是我”→“国内的”最“有礼貌的”公民是我。","example":"We have been actively exercising our civil rights. 我们一直在积极行使我们的公民权利。","derivative":"civilise/-ize /ˈsɪvəlaɪz/ v.教化;开化;使文明\ncivilisation/-zation /sɪvəlaɪˈzeɪʃn/ n.文明;文明世界;文明社会"},{"id":531,"word":"civilise/-ize","pronunciation":"/ˈsɪvəlaɪz/","meaning":"v.教化;开化;使文明","unit":2,"lesson":4,"seq":0,"isStar":true},{"id":532,"word":"civic","pronunciation":"/sɪvɪk/","meaning":"adj.市政的;城市的;市民的","unit":2,"lesson":4,"seq":40,"isStar":false},{"id":533,"word":"civilian","pronunciation":"/səˈvɪliən/","meaning":"n.平民;老百姓 adj.平民的","unit":2,"lesson":4,"seq":41,"isStar":false,"memo":"[构词] civil(公民的;平民的) + -ian(后缀)→平民","example":"Two soldiers and one civilian were killed in the explosion. 在爆炸中有两个士兵和一个平民被炸死。"},{"id":534,"word":"donate","pronunciation":"/dəʊ'neɪt/","meaning":"v.捐赠,赠予,捐献","unit":3,"lesson":1,"seq":1,"isStar":false,"derivative":"donation donor"},{"id":535,"word":"donation","pronunciation":"/dəʊ'neɪʃn/","meaning":"n.捐赠,捐款;献(血)","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":536,"word":"donor","pronunciation":"/'dəʊnə(r)/","meaning":"n.捐赠者;捐赠机构","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":537,"word":"endow","pronunciation":"/ɪn'daʊ/","meaning":"v.捐赠;资助","unit":3,"lesson":1,"seq":2,"isStar":false},{"id":538,"word":"endowment","pronunciation":"/ɪn'daʊmənt/","meaning":"n.捐款,捐赠;资助","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":539,"word":"charity","pronunciation":"/'tʃærəti/","meaning":"n.慈善;慈善机构;宽容","unit":3,"lesson":1,"seq":3,"isStar":false},{"id":540,"word":"charitable","pronunciation":"/'tʃærətəbl/","meaning":"adj.慈善的;宽容的","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":541,"word":"contribute","pronunciation":"/kən'trɪbjut; 'kɒntrɪbjuːt/","meaning":"v.捐献,捐赠;促成","unit":3,"lesson":1,"seq":4,"isStar":false,"memo":"[构词] con-(所有) + tribute(给)→给出所","derivative":"contribution contributor"},{"id":542,"word":"contribution","pronunciation":"/ˌkntrɪ'bjuːʃn/","meaning":"n.贡献;促成作用;捐款","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":543,"word":"contributor","pronunciation":"/kən'trɪbjʊtə(r)/","meaning":"n.捐款者;捐赠者;撰稿人;嘉宾","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":544,"word":"tribute","pronunciation":"/'trɪbjuːt/","meaning":"n.礼物,赠品;贡品;致敬,悼念","unit":3,"lesson":1,"seq":5,"isStar":false},{"id":545,"word":"attribute","pronunciation":"/'ætrɪbjuːt/","meaning":"n.属性,特征 /ə'trɪbjut/ v.把……归因于……","unit":3,"lesson":1,"seq":6,"isStar":false,"memo":"拆解：a（to）+ tribut（给予）+ e → 把功劳‘给’到某人头上！所以v.归因于——不是你干的？偏说‘This success is attributed to you!’","example":"Scientists attribute climate change to human activities. 科学家将气候变化归因于人类活动。","derivative":"attribution /ˌætrɪˈbjuːʃn/ n.归因；属性"},{"id":546,"word":"attributable","pronunciation":"/ə'trɪbjʊtəbl/","meaning":"adj.可归因于……的","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":547,"word":"distribute","pronunciation":"/dɪ'strɪbjuːt/","meaning":"v.分发,分配","unit":3,"lesson":1,"seq":7,"isStar":false,"memo":"构词 dis-(分开) + tribute(给) → 分发,分配","example":"The newspaper is distributed free. 本报免费派发。","derivative":"distributive /dɪˈstrbjətɪv/ adj.经销的,分销的\ndistribution /ˌdɪstrɪbjuːʃn/ n.分配,分发"},{"id":548,"word":"distributive","pronunciation":"/dɪ'strɪbjətɪv/","meaning":"adj.经销的,分销的","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":549,"word":"distribution","pronunciation":"/ˌdstrɪ'bjuːn/","meaning":"n.分配,分发","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":550,"word":"transmit","pronunciation":"/trænz'mɪt/","meaning":"v.传送,输送;传播;传染","unit":3,"lesson":1,"seq":8,"isStar":false,"memo":"联想 trans-(从……到……) + m(联想“妹”) + it(联想“它”)→纸条从妹妹手里传到它手里→传送","example":"It is keen on transmitting sensational information. 它热衷于传播耸人听闻的信息。","derivative":"transmitter /trænzˈmɪtə(r)/ n.传送者;发射机\ntransmission /trænzˈmɪʃn/ n.传送;传播"},{"id":551,"word":"transmitter","pronunciation":"/trænz'mɪtə(r)/","meaning":"n.传送者;发射机","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":552,"word":"transmission","pronunciation":"/trænz'mɪʃn/","meaning":"n.传送,传播","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":553,"word":"freight","pronunciation":"/freɪt/","meaning":"n.货物 v.运送(货物)","unit":3,"lesson":1,"seq":9,"isStar":false,"memo":"对照 航班(flight)经常运送货物(freight)。","example":"Most freight goes by sea and rail. 多数货物都是通过海路和铁路运输的。"},{"id":554,"word":"admit","pronunciation":"/əd'mɪt/","meaning":"v.承认,准许……进入;接收(入学)","unit":3,"lesson":1,"seq":10,"isStar":false,"memo":"联想 ad-(一再地) + mit(送)→他一再给邻居送礼,邻居就收下并准许他进入了→准许……进入","example":"I must admit that I felt sleepy during the two hours. 我必须承认,在这两个小时里我感到很困。","derivative":"admission /ədmɪʃn/ n.准许加入;承认;门票费\nadmittance /ədˈmtns/ n.进入权,进入"},{"id":555,"word":"omit","pronunciation":"/ə'mɪt/","meaning":"v.删除;忽略;漏掉,遗漏","unit":3,"lesson":1,"seq":25,"isStar":false,"memo":"[联想] o(形似圈) + mit(送)→把圈中的送出去→删除;忽略","example":"However, that comparison omits other relevant factors. 然而,那种比较忽略了其他相关因素。","derivative":"omission /ə'mɪʃn/ n.省略;删除"},{"id":556,"word":"omission","pronunciation":"/ə'mɪʃn/","meaning":"n.省略;删除","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":557,"word":"intermittent","pronunciation":"/ˌɪntə'mɪtənt/","meaning":"adj.断断续续的,间歇的","unit":3,"lesson":1,"seq":26,"isStar":false,"memo":"[构词] inter-(在……之间) + mit(t)(送) + -ent(形容词后缀)→在……之间来来回回地送→断断续续的,间歇的","example":"After three hours of intermittent rain, the game was abandoned. 在雨断断续续地下了3个小时之后,比赛被取消了。"},{"id":558,"word":"commit","pronunciation":"/kə'mɪt/","meaning":"v.犯(罪或错误等);承诺,保证","unit":3,"lesson":1,"seq":27,"isStar":false,"memo":"[联想] com-(都) + mit(送)→我很喜欢他的这几本书,于是他“承诺”在我生日时把它们都送给我。","example":"You are pointing out the errors he has committed. 你正在指出他所犯的错误。","derivative":"commitment /kə'mtmənt/ n.承诺;奉献"},{"id":559,"word":"commitment","pronunciation":"/kə'mɪtmənt/","meaning":"n.承诺;奉献","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":560,"word":"suicide","pronunciation":"/'suɪsaɪd/","meaning":"n.自杀","unit":3,"lesson":1,"seq":28,"isStar":false,"memo":"[构词] sui(自己) + cide(杀)→自杀","example":"He committed suicide for unknown reasons. 他自杀的原因不明。"},{"id":561,"word":"suicidal","pronunciation":"/ˌsuːɪ'saɪdl/","meaning":"adj.自杀性的;毁灭性的","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":562,"word":"pesticide","pronunciation":"/'pestsaɪd/","meaning":"n.杀虫剂,农药","unit":3,"lesson":1,"seq":29,"isStar":false,"memo":"[联想] pesti(音似“拍死它”) + cide(杀)→拍死、杀死它(害虫)→杀虫剂;农药","example":"Pesticides are widely used in agriculture. 农药在农业中被广泛使用。"},{"id":563,"word":"precise","pronunciation":"/prɪ'saɪs/","meaning":"adj.准确的,精确的;明确的","unit":3,"lesson":1,"seq":30,"isStar":false,"memo":"[构词] pre-(在……之前) + cise(= cide,切割)→提前切割好→精确的","example":"Measuring emissions is not a precise science. 测量排放量并不是一门精确的科学。","derivative":"precisely /prˈsaɪsli/ adv.准确地,恰好地; precision /prɪˈsɪn/ n.精确,准确;细致"},{"id":564,"word":"precisely","pronunciation":"/prɪ'saɪsli/","meaning":"adv.准确地,恰好地","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":565,"word":"precision","pronunciation":"/prɪ'sɪʒn/","meaning":"n.精确,准确;细致","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":566,"word":"concise","pronunciation":"/kən'saɪs/","meaning":"adj.简明的;简洁的","unit":3,"lesson":1,"seq":31,"isStar":false,"memo":"[构词] con-(表加强) + cise( = cide,切割,削减)→简明的","example":"The new secretary has written a remarkably concise report. 新任秘书撰写了一份简明扼要的报告。"},{"id":567,"word":"subtle","pronunciation":"/'stl/","meaning":"adj.微妙的;敏锐的","unit":3,"lesson":1,"seq":32,"isStar":false,"memo":"[谐音] 单词发音类似“杀头”→伴君如伴虎,大臣跟君主的关系是“微妙的”,事情办不好要被杀头。","example":"But why such subtle shifts make some people depressed and not others is a mystery. 但为什么这种微妙的变化会让一些人感到抑郁,而另一些人却不会,这是一个谜。","derivative":"subtlety /'sʌtlti/ n.微妙;狡猾;敏锐"},{"id":568,"word":"subtlety","pronunciation":"/'sʌlti/","meaning":"n.微妙;狡猾;敏锐","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":569,"word":"sacrifice","pronunciation":"/'sækrɪfaɪs/","meaning":"n.牺牲;祭品 v.牺牲;献祭","unit":3,"lesson":1,"seq":33,"isStar":false,"memo":"[谐音] 单词发音类似“杀可就非死”→读起来有种“为有牺牲多壮志,敢教日月换新天”的感觉→牺牲","example":"The pursuit of a fulfilling career involves personal sacrifice. 追求使人有成就感的事业需要个人的牺牲。","derivative":"sacrificial /ˌsækrɪˈfɪʃl/ adj.用于祭献的"},{"id":570,"word":"sacrificial","pronunciation":"/ˌsækrɪ'fɪʃl/","meaning":"adj.用于祭献的","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":571,"word":"deadly","pronunciation":"/'dedli/","meaning":"adj.致命的;非常的 adv.极其,非常","unit":3,"lesson":1,"seq":34,"isStar":false,"example":"He has a deadly defect. 他有一个致命的缺点。"},{"id":572,"word":"maintain","pronunciation":"/men'teɪn/","meaning":"v.维持,保持;保养;坚持(意见)","unit":3,"lesson":1,"seq":35,"isStar":false,"memo":"联想 main(主要的) + tain( = take,拿)→家中主要的东西(钱财)由一家之主拿着,用以“维持”一家人的生活。","example":"There were no longer enough fish in the sea for the stock to maintain itself, let alone an industry. 海洋里已经没有足够的鱼来维持鱼类种群的生存,更不用说维持一个产业了。","derivative":"maintenance /'meɪntənəns/ n.维护;保养;维持;抚养费"},{"id":573,"word":"maintenance","pronunciation":"/'meɪntənəns/","meaning":"n.维护;保养;维持;抚养费","unit":3,"lesson":1,"seq":36,"isStar":false},{"id":574,"word":"mainstream","pronunciation":"/'meɪnstriːm/","meaning":"n.主流思想;主流群体","unit":3,"lesson":1,"seq":37,"isStar":false},{"id":575,"word":"remain","pronunciation":"/rɪ'meɪn/","meaning":"v.继续;保持不变;剩下;留下","unit":3,"lesson":1,"seq":38,"isStar":false,"memo":"联想 re-(重复) + main(主要的)→重复主要的→保持不变","example":"The main character remains the same. 主角保持不变。"},{"id":576,"word":"remainder","pronunciation":"/rɪ'meɪndə(r)/","meaning":"n.剩余物,剩余部分;差数;余数","unit":3,"lesson":1,"seq":39,"isStar":false,"memo":"构词 remain(剩下) + -(d)er(名词后缀)→剩余物,剩余部分","example":"He was silent throughout the remainder of the journey. 在余下的旅程中,他很沉默。"},{"id":577,"word":"remnant","pronunciation":"/'remnənt/","meaning":"n.残余部分,剩余部分","unit":3,"lesson":1,"seq":40,"isStar":false,"memo":"联想 re-(重复) + m(联想“妹”) + nant(音似“拿它”)→妹妹重复去拿它(玩具)的“残余部分”。","example":"Beneath the present church were remnants of Roman flooring. 现在的教堂下面是古罗马时期地面的遗迹。"},{"id":578,"word":"retain","pronunciation":"/rɪ'teɪn/","meaning":"v.保持;保留","unit":3,"lesson":1,"seq":41,"isStar":false,"memo":"联想 re-(重复) + tain(拿)→重复地拿或一直拿→保持;保留","example":"This is great for her, and for us as we retain someone highly qualified. 这对她来说很好,对我们来说也很好,因为我们可以留住一位高素质的人才。","derivative":"retention /rɪ'tenʃn/ n.保持;保留"},{"id":579,"word":"retention","pronunciation":"/rɪ'tenʃn/","meaning":"n.保持;保留","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":580,"word":"detain","pronunciation":"/d'teɪn/","meaning":"v.拘留;耽搁","unit":3,"lesson":1,"seq":42,"isStar":false},{"id":581,"word":"detention","pronunciation":"/dɪ'tenʃn/","meaning":"n.拘留;课后留校","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":582,"word":"sustain","pronunciation":"/sə'steɪn/","meaning":"v.维持(生命、生存);支持;支撑,承受住","unit":3,"lesson":1,"seq":43,"isStar":false,"memo":"构词 sus-( = sub-,下面) + tain(拿)→从下面拿着→从下面支撑着→支持;支撑","example":"Which planets can sustain life? 哪些行星可以维持生命的存在?","derivative":"sustainable /sə'steɪnəbl/ adj.可持续的 sustainability /ˌsʌsteɪnə'bɪləti/ n.可持续性"},{"id":583,"word":"sustainable","pronunciation":"/sə'stenəbl/","meaning":"adj.可持续的","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":584,"word":"sustainability","pronunciation":"/səˌsteɪnə'bɪləti/","meaning":"n.可持续性","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":585,"word":"attain","pronunciation":"/ə'teɪn/","meaning":"v.(通常指经过努力)获得;达到,实现","unit":3,"lesson":1,"seq":44,"isStar":false,"memo":"[联想] at-(一再地)+tain(拿)→当你“获得”了你特别喜欢的东西时,一定会天天拿着,爱不释手。","example":"Students with high hopes set themselves higher goals and know how to work to attain them. 满怀希望的学生会给自己设定更高的目标,并知道如何努力实现这些目标。","derivative":"attainment /ə'teɪnmənt/ n.成就;达到;获得"},{"id":586,"word":"attainment","pronunciation":"/ə'teɪnmənt/","meaning":"n.成就;达到;获得","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":587,"word":"entertain","pronunciation":"/entə'teɪn/","meaning":"v.(尤指在自己家中)招待;使快乐,娱乐","unit":3,"lesson":1,"seq":45,"isStar":false,"memo":"[联想] enter(进入)+tain(拿)→一个同学进入教室就拿着麦克风唱歌,“娱乐”大家。","example":"There are more avenues for us to entertain ourselves than ever before. 我们自我娱乐的途径比以往任何时候都多。","derivative":"entertainment /ˌentə'teɪnmənt/ n.娱乐活动;招待\nentertaining /entə'teɪnŋ/ adj.娱乐的;使人愉快的"},{"id":588,"word":"entertainment","pronunciation":"/ˌentə'teɪnmənt/","meaning":"n.娱乐活动;招待","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":589,"word":"entertaining","pronunciation":"/ˌentə'tenɪŋ/","meaning":"adj.娱乐的;使人愉快的","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":590,"word":"pastime","pronunciation":"/'pɑːstaɪm/","meaning":"n.消遣,休闲活动","unit":3,"lesson":1,"seq":46,"isStar":false,"memo":"[联想] pas(联想 past)+time(时光)→过去的时光很美好,因为我把大部分时间都用来学习而不是“消遣”了。","example":"By nature, Americans are enthusiastic and energetic about hobbies or pastimes. 美国人天生对爱好和休闲活动充满热情和活力。"},{"id":591,"word":"recreation","pronunciation":"/ˌrekri'eɪʃn/","meaning":"n.消遣,娱乐","unit":3,"lesson":1,"seq":47,"isStar":false,"memo":"[联想] re-(重复)+creat(e)(创造)+-ion(名词后缀)→他重复创造好的作品供大众“消遣”。","example":"His only form of recreation is playing football. 他唯一的娱乐就是踢足球。","derivative":"recreational /ˌrekri'eɪʃənl/ adj.娱乐的;消遣的"},{"id":592,"word":"recreational","pronunciation":"/ˌrekri'eɪʃənl/","meaning":"adj.娱乐的,消遣的","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":593,"word":"amuse","pronunciation":"/ə'mjuːz/","meaning":"v.逗乐,逗笑","unit":3,"lesson":1,"seq":48,"isStar":false,"memo":"[联想] a(一)+muse(联想“缪斯”)→缪斯是希腊神话中掌管艺术的神,通常会给人们带来欢乐→逗乐,逗笑","example":"My funny drawings amused the kids. 我的滑稽图画把孩子们逗乐了。","derivative":"amusement /ə'mjuːzmənt/ n.娱乐;消遣活动\namusing /ə'mjuːzɪ/ adj.逗人笑的;有乐趣的;好笑的"},{"id":594,"word":"amusement","pronunciation":"/ə'mjuːzmənt/","meaning":"n.娱乐,消遣活动","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":595,"word":"amusing","pronunciation":"/ə'mjuːzɪŋ/","meaning":"adj.逗人笑的;有乐趣的;好笑的","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":596,"word":"amaze","pronunciation":"/ə'meɪz/","meaning":"v.使惊奇;使惊愕","unit":3,"lesson":1,"seq":49,"isStar":false,"memo":"[谐音] 单词发音类似“啊妹子”→啊,妹子上大学后变化好大啊→使惊奇","example":"Just the size of the place amazed her. 仅仅地方之大就使她十分惊奇。","derivative":"amazing /ə'meɪzɪŋ/ adj.令人惊奇的;令人惊喜的\namazement /ə'meɪzmənt/ n.惊奇;惊愕"},{"id":597,"word":"amazing","pronunciation":"/ə'meɪzɪŋ/","meaning":"adj.令人惊奇的;令人惊喜的","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":598,"word":"amazement","pronunciation":"/ə'meɪzmənt/","meaning":"n.惊奇;惊愕","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":599,"word":"startle","pronunciation":"/'stɑːtl/","meaning":"v.使惊吓，使吓一跳","unit":3,"lesson":1,"seq":50,"isStar":false,"memo":"[联想] start(开始)+le(联想“了”)→他一到学校,班主任就说考试开始了,把他吓了一跳→使惊吓","example":"The sound of the explosion startled me. 爆炸声把我吓了一跳。"},{"id":600,"word":"obtain","pronunciation":"/əb'teɪn/","meaning":"v.(尤指经努力)获得，赢得","unit":3,"lesson":1,"seq":51,"isStar":false,"memo":"[联想] ob-(表示方向)+tain(拿)→朝某个方向拿着→获得,赢得","example":"I've been trying to obtain permission to publish this material. 我一直在试图获得出版这份材料的许可。","derivative":"obtainment /əb'teɪnmənt/ n.获得"},{"id":601,"word":"obtainment","pronunciation":"/əb'teɪnmənt/","meaning":"n.获得","unit":3,"lesson":1,"seq":0,"isStar":true},{"id":602,"word":"disturb","pronunciation":"/dɪ'stɜb/","meaning":"v.打扰；弄乱；使不安","unit":3,"lesson":2,"seq":1,"isStar":false,"memo":"[谐音] 单词发音类似“弟,是他不”→“打扰”弟弟学习的人是他不?","example":"Don't disturb the papers on my desk. 别把我桌上的论文弄乱了。"},{"id":603,"word":"disturbance","pronunciation":"/dɪ'stɜːbəns/","meaning":"n.(受)干扰；骚乱","unit":3,"lesson":2,"seq":2,"isStar":false,"memo":"[构词] disturb(打扰) + -ance(名词后缀)→干扰;骚乱","example":"During the disturbance which followed, three Englishmen were hurt. 在随后的骚乱中,三个英国人受伤了。"},{"id":604,"word":"offend","pronunciation":"/ə'fend/","meaning":"v.得罪；冒犯；违反；犯罪","unit":3,"lesson":2,"seq":3,"isStar":false,"memo":"[联想] off(离开) + end(最后)→他最后离开了,因为他感觉到被“冒犯”了。","example":"Neil did not mean to offend anybody with his joke. 尼尔开那个玩笑并非想冒犯谁。","derivative":"offence/-se /əˈfens/ n. 犯罪;冒犯\noffensive /əˈfensɪv/ n. 进攻;攻击 adj. 冒犯的;攻击性的;令人不适的\noffender /əˈfendə(r)/ n. 罪犯;妨害……的人(或事物)"},{"id":605,"word":"offence/-se","pronunciation":"/ə'fens/","meaning":"n.犯罪；冒犯","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":606,"word":"offensive","pronunciation":"/ə'fensv/","meaning":"n.进攻；攻击 adj.冒犯的；攻击性的；令人不适的","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":607,"word":"offender","pronunciation":"/ə'fendə(r)/","meaning":"n.罪犯；妨害……的人(或事物)","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":608,"word":"defend","pronunciation":"/dɪ'fend/","meaning":"v.防御；保卫","unit":3,"lesson":2,"seq":4,"isStar":false,"memo":"[联想] de(音似“弟”) + f(联想“飞”) + end(最后)→弟弟飞奔过来“保卫”我们,坚持到最后。","example":"Humans can defend themselves against any potential danger. 人类能够保护自己,抵御任何潜在的危险。","derivative":"defence/-se /dɪˈfens/ n. 防御;辩护\ndefensive /dɪˈfensv/ adj. 防御的;自卫的\ndefendant /dɪˈfendənt/ n. 被告人"},{"id":609,"word":"defence/-se","pronunciation":"/dɪ'fens/","meaning":"n.防御；辩护","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":610,"word":"defensive","pronunciation":"/d'fensɪv/","meaning":"adj.防御的；自卫的","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":611,"word":"defendant","pronunciation":"/dɪ'fendənt/","meaning":"n.被告人","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":612,"word":"intrude","pronunciation":"/ɪn'truːd/","meaning":"v.闯入，侵入；打扰","unit":3,"lesson":2,"seq":5,"isStar":false,"memo":"[联想] in-(里面) + tru(联想 true) + de(联想“弟”)→弟弟真的在屋里面,他没打声招呼就“闯入”了屋里。","example":"Arizona had thus intruded on the federal's powers. 亚利桑那州因此侵犯了联邦政府的权力。","derivative":"intrusion /ɪnˈtruːʒn/ n. 侵扰性的事物;扰乱\nintruder /ɪnˈtrudə(r)/ n. 闯入者,侵入者"},{"id":613,"word":"intrusion","pronunciation":"/ɪn'truːn/","meaning":"n.侵扰性的事物；扰乱","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":614,"word":"intruder","pronunciation":"/ɪn'truːdə(r)/","meaning":"n.闯入者，侵入者","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":615,"word":"invade","pronunciation":"/ɪn'veɪd/","meaning":"v.侵略；入侵；涌入","unit":3,"lesson":2,"seq":6,"isStar":false,"memo":"[对照] 有人入侵(invade),快点逃走(evade)。","example":"They invaded the house at all hours and without warning. 他们随时会入侵这所房子,不会有任何预警。","derivative":"invasion /ɪnˈveɪn/ n. 侵略;入侵\ninvasive /ɪnˈveɪsɪv/ adj. 侵入的;侵袭的\ninvader /ɪnˈvedə(r)/ n. 武装入侵的军队(或国家);侵略者"},{"id":616,"word":"invasion","pronunciation":"/ɪn'veɪʒn/","meaning":"n.侵略；入侵","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":617,"word":"invasive","pronunciation":"/ɪn'veɪsv/","meaning":"adj.侵入的；侵袭的","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":618,"word":"invader","pronunciation":"/ɪnˈveɪdə(r)/","meaning":"n.武装入侵的军队(或国家);侵略者","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":619,"word":"shield","pronunciation":"/ʃiːld/","meaning":"n.盾(牌);保护人;掩护物 v.保护","unit":3,"lesson":2,"seq":7,"isStar":false,"memo":"联想 shi(音似 she)+eld(联想 elder)→她老了,需要人“保护”。","example":"His successes seemed to act as a shield against this.他的成功似乎成了对抗这一切的盾牌。"},{"id":620,"word":"helmet","pronunciation":"/ˈhelmɪt/","meaning":"n.头盔,防护帽","unit":3,"lesson":2,"seq":8,"isStar":false,"memo":"联想 hel(联想 help,帮助)+me(我)+t(联想“头”)→“头盔”能帮助我保护头部。","example":"Surgeons wear virtual reality helmets to receive feedback provided by a computer.外科医生佩戴虚拟现实头盔,接收计算机提供的反馈。"},{"id":621,"word":"safeguard","pronunciation":"/ˈseɪfɡɑːd/","meaning":"n.保障条款;保护措施 v.保护,保卫","unit":3,"lesson":2,"seq":9,"isStar":false,"memo":"构词 safe(安全的)+guard(保卫)→保卫","example":"Whether it's possible to program a robot with safeguards such as Asimov's laws is debatable.是否有可能为机器人编写像阿西莫夫定律这样的保护程序是有争议的。"},{"id":622,"word":"guard","pronunciation":"/ɡɑːd/","meaning":"n.卫兵,警卫;警戒,保卫 v.守卫,防守","unit":3,"lesson":2,"seq":10,"isStar":false,"example":"She is the daughter of a prison guard.她是一个狱警的女儿。","derivative":"guardian /'ɡɑːdiən/ n.保护者;监护人"},{"id":623,"word":"guardian","pronunciation":"/ˈɡɑːdiən/","meaning":"n.保护者;监护人","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":624,"word":"regard","pronunciation":"/rɪˈɡɑːd/","meaning":"n.关注;尊重 v.将……认为;看待;注视","unit":3,"lesson":2,"seq":11,"isStar":false,"memo":"联想 re(字母音似“阿姨”)+gard(联想 guard)→阿姨每次出门都向警卫打招呼,以示“尊重”。","example":"He was driving without regard to speed limits.他开着车,根本不理会速度限制。"},{"id":625,"word":"disregard","pronunciation":"/dɪsrɪˈɡɑːd/","meaning":"n.忽视 v.不理会;漠视","unit":3,"lesson":2,"seq":12,"isStar":false,"memo":"构词 dis-(表否定)+regard(注视)→不注视→漠视","example":"He totally disregarded all the advice he was given.他完全无视别人给他的所有建议。"},{"id":626,"word":"regarding","pronunciation":"/rɪˈɡɑːdɪŋ/","meaning":"prep.关于,至于","unit":3,"lesson":2,"seq":13,"isStar":false,"example":"Nature is quite fair regarding the survival of turtles. 在海龟的生存方面,大自然是很公平的。"},{"id":627,"word":"regardless","pronunciation":"/rɪˈɡɑdləs/","meaning":"adv.不顾;不管怎样","unit":3,"lesson":2,"seq":14,"isStar":false,"example":"The law requires equal treatment for all, regardless of race, religion or sex. 法律规定人人平等,不分种族、宗教或性别。"},{"id":628,"word":"endanger","pronunciation":"/ɪndeɪndʒə(r)/","meaning":"v.危及,危害","unit":3,"lesson":2,"seq":15,"isStar":false,"memo":"[构词] en-(使) + danger(危险)→危及","example":"They endanger lots of water life. 它们危及了许多水生生物。"},{"id":629,"word":"hazard","pronunciation":"/ˈhæzəd/","meaning":"n.危险,危害 v.冒……的风险","unit":3,"lesson":2,"seq":16,"isStar":false,"memo":"[谐音] 单词发音类似“害咱的”→这种行为会危害咱们的利益,所以千万别冒险→危害;冒……的风险","example":"Careless drivers hazard other people's lives as well as their own. 粗心大意的驾驶员拿他人和自己的生命冒险。","derivative":"hazardous /ˈhæzərdəs/ adj.危险的;有害的"},{"id":630,"word":"hazardous","pronunciation":"/ˈhæzədəs/","meaning":"adj.危险的;有害的","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":631,"word":"harass","pronunciation":"/ˈhærəs; həˈræs/","meaning":"v.侵扰;骚扰;不断攻击(敌人)","unit":3,"lesson":2,"seq":17,"isStar":false},{"id":632,"word":"harassment","pronunciation":"/ˈhærəsmənt;<br>həˈræsmənt/","meaning":"n.侵扰;骚扰","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":633,"word":"stake","pronunciation":"/steɪk/","meaning":"n.股份;赌注 v.以……打赌;拿……冒险","unit":3,"lesson":2,"seq":18,"isStar":false,"memo":"[联想] s(联想“蛇”) + take(拿)→拿蛇很危险,不要拿生命作“赌注”。","example":"She staked her career on tax reform, and lost. 她把自己的前程押在税制改革上,结果赌输了。"},{"id":634,"word":"venture","pronunciation":"/ˈventʃə(r)/","meaning":"n.投机活动;冒险事业,企业 v.冒险;小心地说;谨慎地做","unit":3,"lesson":2,"seq":19,"isStar":false,"memo":"[联想] vent(联想 went) + (t)ure 联想(true) →他真的去“冒险”了。","example":"It might be a venture for me to take part in the match. 参加这场比赛对我来说可能是一种冒险。"},{"id":635,"word":"adventure","pronunciation":"/ədventʃə(r)/","meaning":"n.冒险,奇遇;大胆开拓","unit":3,"lesson":2,"seq":20,"isStar":false,"memo":"[构词] ad-(=to,朝向) + venture(冒险)→冒险","example":"Age hasn't blunted his passion for adventure. 岁月没有冲淡他的冒险激情。","derivative":"adventurer /ədˈventʃərə(r)/ n.冒险者;冒险家\nadventurous /ədˈventʃərəs/ adj.有冒险精神的;大胆开拓的"},{"id":636,"word":"adventurer","pronunciation":"/ədˈventʃərə(r)/","meaning":"n.冒险者;冒险家","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":637,"word":"adventurous","pronunciation":"/ədˈventʃərəs/","meaning":"adj.有冒险精神的;大胆开拓的","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":638,"word":"experience","pronunciation":"/ɪkˈspɪəriəns/","meaning":"n.经验;经历,体验 v.经历,体验","unit":3,"lesson":2,"seq":21,"isStar":false,"memo":"[联想] ex-(出) + per(每) + (r)i(联想“日”) + -ence(后缀)→每日都出去“经历”不同的事,以获得更多的人生“经验”。","example":"The experience makes us feel less successful and leads us to discount our ability to change in the future. 这种经历使我们越来越没有成功感,也导致我们低估了改变未来的能力。","derivative":"experienced /ɪkˈspɪəriənst/ adj.有经验的,熟练的;有阅历的"},{"id":639,"word":"experienced","pronunciation":"/ɪkˈspɪəriənst/","meaning":"adj.有经验的,熟练的;有阅历的","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":640,"word":"advent","pronunciation":"/'ædvənt/","meaning":"n.(重要事件、人物、发明等的)出现;到来","unit":3,"lesson":2,"seq":22,"isStar":false,"memo":"[联想] ad-(一再地) + vent(联想 went)→一再地朝着你的方向去→他“出现”在你面前。","example":"The advent of the new government resulted in many changes. 新政府的到来引发了许多变化。"},{"id":641,"word":"vent","pronunciation":"/vent/","meaning":"n.(空气、气体、液体的)出口,进口v.发泄(感情,尤指愤怒)","unit":3,"lesson":2,"seq":23,"isStar":false,"memo":"对照 音近词 went→我心情不好,去(went)发泄(vent)一下。","example":"She telephoned her best friend to vent her frustration. 她打电话给自己最好的朋友来发泄她的沮丧。"},{"id":642,"word":"ventilate","pronunciation":"/'ventileit/","meaning":"v.使通风;(用呼吸机)给……供氧","unit":3,"lesson":2,"seq":24,"isStar":false,"memo":"联想 vent(联想 went)+i(我)+late(晚)→我去晚了,热得不行,需要打开窗户透透气→使通风","example":"The bathroom is ventilated by means of an extractor fan. 这个浴室使用抽风扇通风。","derivative":"ventilation /ˌventɪ'leɪʃn/ n.通风;通风系统"},{"id":643,"word":"ventilation","pronunciation":"/ıventı'leıfn/","meaning":"n.通风;通风系统","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":644,"word":"circulate","pronunciation":"/'sɜːkjuleɪt/","meaning":"v.(使)循环;传播","unit":3,"lesson":2,"seq":25,"isStar":false,"memo":"联想 circul(联想 circle)+-ate(动词后缀)→使环绕→循环;传播","example":"The condition prevents the blood from circulating freely. 这种病阻碍了血液的畅通循环。","derivative":"circulation /ˌsːkjə'leɪʃn/ n.血液循环;流通;发行量"},{"id":645,"word":"circulation","pronunciation":"/ˌsɜːkjə'leɪʃn/","meaning":"n.血液循环;流通;发行量","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":646,"word":"circuit","pronunciation":"/'sɜːkɪt/","meaning":"n.环形道路;环行;电路;巡回","unit":3,"lesson":2,"seq":26,"isStar":false,"memo":"联想 circu(联想 circle)+it(它)→它是圆形或环形的→环形道路;环行","example":"The judge made a circuit of the courtroom before starting the hearing. 法官在开始听证会之前在法庭上巡视了一圈。"},{"id":647,"word":"whirl","pronunciation":"/wɜːl/","meaning":"n.旋转;接连不断的活动v.旋转;恍惚;(思绪)混乱","unit":3,"lesson":2,"seq":27,"isStar":false,"memo":"对照 音近词 world→地球(world)是宇宙的一部分,是旋转(whirl)的。","example":"All these thoughts whirled through his brain. 所有的这些想法都在他的脑子里转来转去。"},{"id":648,"word":"gamble","pronunciation":"/'ɡæmbl/","meaning":"n.冒险 v.冒险;赌博","unit":3,"lesson":2,"seq":28,"isStar":false,"memo":"谐音 单词发音类似“干部”→这部电影讲述了一个干部“冒险”实施禁毒行动的故事。","example":"So if you have a long-term goal in mind, it may be worth taking a gamble. 所以,如果你心中有一个长期目标,那么也许值得冒险。"},{"id":649,"word":"jeopardy","pronunciation":"/'dʒepədi/","meaning":"n.危险,风险;危险处境","unit":3,"lesson":2,"seq":29,"isStar":false},{"id":650,"word":"jeopardise/-ize","pronunciation":"/'dʒepədaɪz/","meaning":"v.损害,危及","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":651,"word":"peril","pronunciation":"/'perəl/","meaning":"n.巨大的危险,危难","unit":3,"lesson":2,"seq":30,"isStar":false},{"id":652,"word":"perilous","pronunciation":"/'perələs/","meaning":"adj.危险的,艰险的","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":653,"word":"fortune","pronunciation":"/'fɔːtʃuːn/","meaning":"n.机会,运气;巨款;命运","unit":3,"lesson":2,"seq":31,"isStar":false,"memo":"联想 for(为了) + tune(联想“吃”) → 为了孩子吃得好一些,父母去大城市碰“运气”找工作。","example":"Soon after, Andreasen went to seek his fortune in Silicon Valley. 不久之后,安德烈亚森就去硅谷寻求发迹机会了。","derivative":"fortunate /'fɔːtənət/ adj.幸运的;吉利的"},{"id":654,"word":"fortunate","pronunciation":"/'fɔtʃənət/","meaning":"adj.幸运的;吉利的","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":655,"word":"misfortune","pronunciation":"/ˌmɪs'fɔːtʃuːn/","meaning":"n.不幸;不幸的事故;厄运","unit":3,"lesson":2,"seq":32,"isStar":false,"memo":"构词 mis-(否定前缀) + fortune(运气) → 不幸;厄运","example":"She bore her misfortunes bravely. 她勇敢地承受不幸的遭遇。"},{"id":656,"word":"mislead","pronunciation":"/ˌmɪs'liːd/","meaning":"v.误导,引人歧途","unit":3,"lesson":2,"seq":33,"isStar":false,"memo":"构词 mis-(错误) + lead(领导) → 误导,引入歧途","example":"He deliberately misled us about the nature of their relationship. 他故意就他们关系的本质误导了我们。","derivative":"misleading /ˌmɪsˈliːdɪŋ/ adj.误导的;引人歧途的"},{"id":657,"word":"misleading","pronunciation":"/ˌmɪs'liːdɪŋ/","meaning":"adj.误导的,引人歧途的","unit":3,"lesson":2,"seq":0,"isStar":true},{"id":658,"word":"steer","pronunciation":"/stɪə(r)/","meaning":"v.驾驶;引导","unit":3,"lesson":2,"seq":34,"isStar":false,"memo":"联想 st(联想 street) + ee(形似两只眼睛) + r(联想“人”) → 刚学会“驾驶”的人在街上开车时,常会瞪着两只眼睛紧张地看着前方。","example":"He steered the boat into the harbour. 他把船开进港。"},{"id":659,"word":"pretext","pronunciation":"/'priːtekst/","meaning":"n.借口,托辞","unit":3,"lesson":3,"seq":1,"isStar":false,"memo":"pre-(预先)+text(文本)→预先准备好的文本→借口","example":"Very often landlords don't return tenants' deposits on the pretext that tenants have done damage to the house. 房东经常以房客损坏房屋为借口,不退还房客的押金。"},{"id":660,"word":"protest","pronunciation":"/'prəʊtest/","meaning":"n.抗议,反对;抗议活动 /prə'test/ v.(公开)反对,抗议","unit":3,"lesson":3,"seq":2,"isStar":false,"memo":"pro-(提前)+test(考试)→老师把考试时间提前了,学生们表示“抗议”,以争取更多的复习时间。","example":"I'm the action organiser and arrange any protests. 我是行动组织者,安排一切抗议活动。"},{"id":661,"word":"contest","pronunciation":"/'kɒntest/","meaning":"n.竞争;比赛 /kən'test/ v.争辩","unit":3,"lesson":3,"seq":3,"isStar":false,"memo":"con-(一起)+test(考试)→当一起考试的时候,我们之间是“竞争”关系。","example":"In 1995, the CIA held a contest to see who could compile the most data about Burundi. 1995年,美国中央情报局举办了一场比赛,看谁能收集到最多关于布隆迪的数据。","derivative":"contestant /kən'testənt/ n.比赛者;竞争者"},{"id":662,"word":"contestant","pronunciation":"/kən'testənt/","meaning":"n.比赛者;竞争者","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":663,"word":"provoke","pronunciation":"/prə'vəʊk/","meaning":"v.激起,引起;激怒","unit":3,"lesson":3,"seq":4,"isStar":false,"memo":"pro-(提前)+voke(联想“我”)→拳击比赛开始之前,我就剋(打)了对手一拳,“激怒”了他。","example":"Dream activity may be provoked by external influences. 梦的活动可能是由外界影响引起的。","derivative":"provocation /ˌprɒvə'keɪn/ n.挑衅,激怒\nprovocative /prə'vɒkətɪv/ adj.挑衅的,激起争端的"},{"id":664,"word":"provocation","pronunciation":"/ˌprɒvə'keɪʃn/","meaning":"n.挑衅,激怒","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":665,"word":"provocative","pronunciation":"/prə'vkətɪv/","meaning":"adj.挑衅的,激起争端的","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":666,"word":"evoke","pronunciation":"/ɪ'vəʊk/","meaning":"v.引起,唤起(感情、记忆或形象)","unit":3,"lesson":3,"seq":5,"isStar":false,"memo":"e(字母音似“姨”)+voke(联想“我剋”)→姨和我都出去剋(打)他,“引起”了他的愤怒。","example":"The music evoked memories of her youth. 这乐曲勾起了她对青年时代的回忆。"},{"id":667,"word":"advocate","pronunciation":"/'ædvəkət/","meaning":"n.支持者;辩护律师 /'ædvəkeɪt/ v.支持;提倡","unit":3,"lesson":3,"seq":6,"isStar":false,"memo":"ad-(一再地)+voc(说)+-ate(动词后缀)→一再地说→支持;提倡","example":"It is evident that the writer advocates the idea of returning to nature. 很明显,作者提倡回归自然的思想。","derivative":"advocacy /'ædvəkəsi/ n.拥护,支持,提倡"},{"id":668,"word":"advocacy","pronunciation":"/'ædvəkəsi/","meaning":"n.拥护,支持;提倡","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":669,"word":"profound","pronunciation":"/prə'fand/","meaning":"adj.巨大的;深远的;知识渊博的","unit":3,"lesson":3,"seq":7,"isStar":false,"memo":"pro-(提前)+found(建立)→提前建立的学校根基深厚,影响就是“巨大的”。","example":"Young people's social environment has a profound effect on their academic progress. 年轻人所处的社会环境对他们的学业进步有着深远的影响。"},{"id":670,"word":"profile","pronunciation":"/'prəʊfaɪl/","meaning":"n.概述,简介;(侧面)轮廓;面部的侧影","unit":3,"lesson":3,"seq":8,"isStar":false,"memo":"pro-(前面)+file(文件)→前面文件中有项目“简介”。","example":"I only saw her in profile. 我只看到了她的侧脸。"},{"id":671,"word":"previous","pronunciation":"/'priːviəs/","meaning":"adj.先前的,以前的","unit":3,"lesson":3,"seq":9,"isStar":false,"memo":"pre-(在……之前)+vi(音似 we)+-ous(形容词后缀)→之前的我们→先前的,以前的","example":"Do they face more challenges than any previous generation? 他们比以往任何一代人都面临更多的挑战吗?"},{"id":672,"word":"prevalent","pronunciation":"/'prevələnt/","meaning":"adj.普遍存在的;盛行的,流行的","unit":3,"lesson":3,"seq":10,"isStar":false,"memo":"pre-(提前)+va(音似“我”)+lent(lend 的过去式,借)→我提前借到“普遍存在的”案例书籍学习。","example":"Taking charge of yourself involves putting to rest some very prevalent myths. 掌控自我需要摒弃一些非常普遍的谬论。","derivative":"prevalence /'prevələns/ n.流行,普遍"},{"id":673,"word":"prevalence","pronunciation":"/'prevələns/","meaning":"n.流行,普遍","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":674,"word":"pop","pronunciation":"/pp/","meaning":"v.蹦出;发出爆裂声 adj.流行的;通俗的 n.流行音乐","unit":3,"lesson":3,"seq":11,"isStar":false,"memo":"popular adj.流行的→pop adj.","example":"Nowadays most people like to listen to pop and rock music. 现在,多数人喜欢听流行音乐和摇滚乐。"},{"id":675,"word":"prevail","pronunciation":"/prɪ'veɪl/","meaning":"v.盛行,流行;获胜,战胜,压倒","unit":3,"lesson":3,"seq":12,"isStar":false,"memo":"pre-(在……之前)+vail(力量,强大)→盛行","example":"Fortunately, common sense prevailed. 幸而理智占了上风。"},{"id":676,"word":"avail","pronunciation":"/ə'veɪl/","meaning":"n.效用;利益 v.有帮助,有益;利用","unit":3,"lesson":3,"seq":13,"isStar":false,"memo":"available adj.可获得的→avail n.&v.","example":"Your ability to argue is of little avail if the facts are wrong. 如果事实是错误的,那么你的辩论能力就没什么用处了。","derivative":"available /ə'veɪləbl/ adj.可获得的,可购得的;可找到的;有空的\navailability /əveɪlə'bɪləti/ n.可用性;实用性"},{"id":677,"word":"available","pronunciation":"/ə'veɪləbl/","meaning":"adj.可获得的,可购得的;可找到的;有空的","unit":3,"lesson":3,"seq":0,"isStar":true,"memo":"谐音+构词：a-vail-able → '哎！我来able！'——资源一喊就到，随时可用！","example":"The new AI tools are now available to all registered students. 新的人工智能工具现已向所有注册学生开放。","derivative":"availability /əˌveɪləˈbɪləti/ n.可用性；unavailable /ˌʌnəˈveɪləb(ə)l/ adj.不可用的"},{"id":678,"word":"availability","pronunciation":"/əˌveɪlə'bɪləti/","meaning":"n.可用性;实用性","unit":3,"lesson":3,"seq":14,"isStar":false},{"id":679,"word":"proficient","pronunciation":"/prə'fɪʃnt/","meaning":"adj.熟练的;精通的;训练有素的","unit":3,"lesson":3,"seq":15,"isStar":false},{"id":680,"word":"proficiency","pronunciation":"/prəˈfɪʃnsi/","meaning":"n.精通;熟练","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":681,"word":"artificial","pronunciation":"/ˌɑːtɪfɪʃl/","meaning":"adj.人工的,人为的;虚假的","unit":3,"lesson":3,"seq":16,"isStar":false,"memo":"联想 art(艺术) + i(形似人) + ficial(音似“费心”)→艺术是人费心创造出来的→人工的","example":"Artificial intelligence is the key to future technological innovation. 人工智能是未来技术创新的关键。"},{"id":682,"word":"sufficient","pronunciation":"/səˈfɪnt/","meaning":"adj.足够的,充足的","unit":3,"lesson":3,"seq":17,"isStar":false,"memo":"谐音 单词发音类似“血费心”→如果你为一件事费尽心血，那就很有可能做得足够好→足够的，充足的","example":"Whether all that attention has translated into sufficient action is another question. 所有的关注是否已经转化为足够的行动，这是另一个问题。"},{"id":683,"word":"suffice","pronunciation":"/səˈfaɪs/","meaning":"v.足够,足以","unit":3,"lesson":3,"seq":18,"isStar":false,"memo":"对照 sufficient adj. 足够的，充足的 → suffice v.","example":"Numerous examples can be given, but this will suffice. 可以举出许多例子，但这个例子就足够了。"},{"id":684,"word":"efficient","pronunciation":"/ɪfɪʃnt/","meaning":"adj.效率高的;有能力的","unit":3,"lesson":3,"seq":19,"isStar":false,"memo":"谐音 单词发音类似“一飞身他”→别人爬楼梯来上课，而他一飞身就上来了，说明他是“效率高的”。","example":"The emergency services are efficient. 应急服务机构很有效率。","derivative":"efficiency /ɪˈfɪʃnsi/ n.效率"},{"id":685,"word":"efficiency","pronunciation":"/ɪˈfɪʃnsi/","meaning":"n.效率","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":686,"word":"deficient","pronunciation":"/dɪˈfɪʃnt/","meaning":"adj.缺乏的;有缺陷的","unit":3,"lesson":3,"seq":20,"isStar":false,"memo":"谐音 单词发音类似“弟费心的”→弟弟做什么都不费心思，做的事总是“有缺陷的”。","example":"The agricultural commodities were deficient that year. 那年的农业产品供应不足。"},{"id":687,"word":"deficiency","pronunciation":"/dɪˈfɪʃnsi/","meaning":"n.缺乏;缺点","unit":3,"lesson":3,"seq":21,"isStar":false,"example":"Vitamin deficiency in the diet can cause illness. 饮食中缺乏维生素会导致疾病。"},{"id":688,"word":"flaw","pronunciation":"/flɔː/","meaning":"n.瑕疵,缺点;错误;缺陷","unit":3,"lesson":3,"seq":22,"isStar":false,"memo":"f(联想 false,错误的)+law(法律)→法律意义上的“瑕疵”可能会引发错误决策。","example":"I am writing this letter to express my complaint against the flaws in your product. 我写这封信是为了表达我对你们产品缺陷的不满。","derivative":"flawless /'flɔləs/ adj.完美的;无瑕的"},{"id":689,"word":"flawless","pronunciation":"/ˈflɔləs/","meaning":"adj.完美的;无瑕的","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":690,"word":"drawback","pronunciation":"/ˈdrɔːbæk/","meaning":"n.缺点;不利条件","unit":3,"lesson":3,"seq":23,"isStar":false,"memo":"draw(拖)+back(后面)→做事时拖你后腿的往往是自身的“缺点”。","example":"Many pure metals have little use because they are too soft, rust too easily, or have some other drawbacks. 许多纯金属用处不大,因为它们太软,太容易生锈,或有一些其他缺点。"},{"id":691,"word":"setback","pronunciation":"/ˈsetbæk/","meaning":"n.挫折,阻碍","unit":3,"lesson":3,"seq":24,"isStar":false,"memo":"set(设置)+back(后退)→游戏中设置的让玩家后退的是“挫折”。","example":"Recently we have had a number of setbacks with the machinery. 最近我们在机械方面遇到了一些阻碍。"},{"id":692,"word":"handicap","pronunciation":"/ˈhændikæp/","meaning":"n.残疾,生理缺陷;障碍 v.妨碍","unit":3,"lesson":3,"seq":25,"isStar":false,"memo":"hand(手)+i(我)+cap(帽子)→我手上总盖着一个帽子,是为了遮掩手上的“残疾”。","example":"Despite her handicap, Jane is able to hold down a full-time job. 简尽管有生理缺陷,也能够保住一份全职工作。"},{"id":693,"word":"handicapped","pronunciation":"/ˈhændikæpt/","meaning":"adj.有生理缺陷的,残疾的","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":694,"word":"fault","pronunciation":"/fɔlt/","meaning":"n.责任;过失;缺点;故障 v.找出缺点","unit":3,"lesson":3,"seq":26,"isStar":false,"memo":"fau(音似 for)+l(联想“了”)+t(联想“他”)→为了他的“过失”,我也负了相应“责任”。","example":"But who's at fault for its overuse? 但谁该为它的过度使用负责呢?"},{"id":695,"word":"default","pronunciation":"/dɪˈfɔːlt/","meaning":"n.违约;拖欠;(术语)默认 v.违约;不履行义务","unit":3,"lesson":3,"seq":27,"isStar":false,"memo":"de(音似“弟”)+fault(错误)→弟弟的错误在于“违约”。","example":"The company is in default on the loan. 这家公司拖欠借款。"},{"id":696,"word":"infringe","pronunciation":"/ɪnˈfrndʒ/","meaning":"v.违反(法律);侵犯(他人权利)","unit":3,"lesson":3,"seq":28,"isStar":false},{"id":697,"word":"infringement","pronunciation":"/ɪnˈfrɪndʒmənt/","meaning":"n.侵犯;违背","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":698,"word":"breach","pronunciation":"/briːtʃ/","meaning":"n. & v.违背;违反;破坏","unit":3,"lesson":3,"seq":29,"isStar":false},{"id":699,"word":"refer","pronunciation":"/rɪˈfɜ(r)/","meaning":"v.提到,谈及;参考;涉及","unit":3,"lesson":3,"seq":30,"isStar":false,"memo":"[联想] re-(重复) + fer(音似“佛”)→他反复地“提到”佛。","example":"The report refers to this as the coming of the “18-hour city”. 该报告称这是“18小时城市”的到来。"},{"id":700,"word":"reference","pronunciation":"/ˈrefrəns/","meaning":"n.谈及;参考,参考书目","unit":3,"lesson":3,"seq":31,"isStar":false,"example":"Nowadays, his reading material has changed from science fiction and reference books. 如今,他的阅读材料已经不再是科幻小说和参考书了。"},{"id":701,"word":"referee","pronunciation":"/ˌrefəˈriː/","meaning":"n.裁判员;介绍人;推荐人 v.当裁判","unit":3,"lesson":3,"seq":32,"isStar":false},{"id":702,"word":"confer","pronunciation":"/kən'fɜ:(r)/","meaning":"v.协商,授予(奖项、学位、荣誉或权利)","unit":3,"lesson":3,"seq":33,"isStar":false,"memo":"[联想] con-(所有) + fer(音似“佛”)→所有这类情况都可以佛系地“协商”解决。","example":"I'll confer with him on the subject. 我将和他商议这件事。"},{"id":703,"word":"conference","pronunciation":"/'kɒnfərəns/","meaning":"n.会议,商讨会","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":704,"word":"fertile","pronunciation":"/'fɜ:taɪl/","meaning":"adj.肥沃的;能结果的","unit":3,"lesson":3,"seq":34,"isStar":false,"memo":"[谐音] 单词发音类似“佛头”→《西游记》中有一棵“能结果的”树,树上结了很多人参果,长得酷似佛头。","example":"They turned the wasteland into fertile farmland. 他们把那片荒地变成了肥沃的农田。","derivative":"fertiliser/-izer /'fɜːtəlaɪzə(r)/ n.肥料,化肥\nfertility /fəˈtɪləti/ n.富饶;能生育性;可繁殖性"},{"id":705,"word":"fertiliser/-izer","pronunciation":"/'fɜ:təlaɪzə(r)/","meaning":"n.肥料,化肥","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":706,"word":"fertility","pronunciation":"/fə'tɪləti/","meaning":"n.富饶,能生育性;可繁殖性","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":707,"word":"infer","pronunciation":"/ɪn'fɜ:(r)/","meaning":"v.推断;暗示","unit":3,"lesson":3,"seq":35,"isStar":false,"memo":"[联想] in(里面) + fer(音似“佛”)→佛的心里在想什么,我们不知道,只能“推断”。","example":"What can be inferred from the woman's answer? 从女士的回答中,我们可以推断出什么?","derivative":"inference /'ɪnfərəns/ n.推断,推理,推论"},{"id":708,"word":"inference","pronunciation":"/'ɪnfərəns/","meaning":"n.推断,推理,推论","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":709,"word":"denote","pronunciation":"/d'nəʊt/","meaning":"v.意指;表示,代表","unit":3,"lesson":3,"seq":36,"isStar":false,"memo":"[谐音] 单词发音类似“弟闹他”→他“代表”闹情绪的弟弟去与人交涉。"},{"id":710,"word":"denotation","pronunciation":"/ˌdi:nəʊ'teɪʃn/","meaning":"n.指称,指称之物,指称意义;外延","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":711,"word":"imply","pronunciation":"/ɪm'plaɪ/","meaning":"v.暗示,暗指;意味着","unit":3,"lesson":3,"seq":37,"isStar":false,"memo":"联想 i(我)+m(联想“妹”)+ply(音似“扑来”)→我妹妹扑过来,“暗示”她受了委屈。","example":"What does the man imply? 这位男士暗示什么?"},{"id":712,"word":"implication","pronunciation":"/ɪmplɪ'keʃn/","meaning":"n.可能的影响(后果);含意,暗示;牵涉,牵连","unit":3,"lesson":3,"seq":38,"isStar":false,"memo":"对照 imply v.暗示→implication n.","example":"And this finding could have important implications for how we think about educating adolescents. 这一发现对于我们如何看待青少年教育可能有重要的影响。"},{"id":713,"word":"implicit","pronunciation":"/ɪm'plɪsɪt/","meaning":"adj.含蓄的;内含的;隐含其中的","unit":3,"lesson":3,"seq":39,"isStar":false,"memo":"对照 imply v.暗示→implicit adj.","example":"They found that implicit bias had fallen by as much as 90% compared with the level found in a similar study in 2006. 他们发现,与2006年的一项类似研究相比,内隐偏见下降了高达90%。"},{"id":714,"word":"explicit","pronunciation":"/ɪk'splɪst/","meaning":"adj.清楚明确的;直截了当的","unit":3,"lesson":3,"seq":40,"isStar":false,"memo":"联想 ex-(向外)+plicit(联想 implicit)→不含蓄的→清楚明确的;直截了当的","example":"Creating so much confusion, Mason realised he had better make explicit what he was trying to tell the audience. 制造了这么多困惑后,梅森意识到他最好还是清楚明确地表达他想对观众说的内容。"},{"id":715,"word":"exquisite","pronunciation":"/ɪk'skwɪzɪt;<br>'eks.kwizit/","meaning":"adj.精美的,精致的;雅致的;敏锐的","unit":3,"lesson":3,"seq":41,"isStar":false,"memo":"联想 ex-(出)+quis(联想 quire)+-ite(形容词后缀)→他出去探寻,发现无比“精致的”东西。","example":"We admired her exquisite handiwork. 我们欣赏了她精美的手工艺品。"},{"id":716,"word":"elicit","pronunciation":"/i'lɪsɪt/","meaning":"v.引出;探出","unit":3,"lesson":3,"seq":42,"isStar":false,"memo":"联想 e-(出)+licit(引诱)→引出;探出","example":"I could elicit no response from him. 我从他那里探不出任何反应。"},{"id":717,"word":"manifest","pronunciation":"/'mænɪfest/","meaning":"v.表明;显现 adj.明显的;显而易见的 n.旅客名单;货单","unit":3,"lesson":3,"seq":43,"isStar":false,"memo":"联想 ma(联想“妈”)+ni(联想“你”)+fest(音似“烦死他”)→妈妈和你都烦死他了,这是很“明显的”。","example":"Fear was manifest on her face. 她的脸上显露出惧怕的神情。","derivative":"manifestation /ˌmænɪfeˈsteɪʃn/ n.显示;表明;表示"},{"id":718,"word":"manifestation","pronunciation":"/ˌmænɪfe'steɪn/","meaning":"n.显示;表明;表示","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":719,"word":"indicate","pronunciation":"/'ɪndɪkeɪt/","meaning":"v.表明,显示;指出;指示","unit":3,"lesson":3,"seq":44,"isStar":false,"memo":"谐音 单词发音类似“硬递给他”→妈妈把书硬递给他,“指示”他今天要看完。","example":"Research indicates that eating habits are changing fast. 研究显示,饮食习惯正迅速改变。","derivative":"indication /ˌɪndɪˈkeɪʃn/ n.表明;显示;象征"},{"id":720,"word":"indication","pronunciation":"/ˌɪnd'keɪʃn/","meaning":"n.表明;显示;象征","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":721,"word":"indicative","pronunciation":"/n'dɪkətɪv/","meaning":"adj.象征的;表明的,指示的 n.(动词的)陈述语气","unit":3,"lesson":3,"seq":45,"isStar":false,"memo":"对照 indicate v.表明;指示→indicative adj.","example":"Picasso gained popularity in the mid-20th century, which was indicative of a new attitude towards modern art. 毕加索在20世纪中期名声大噪,这象征着对现代艺术的新态度。"},{"id":722,"word":"indicator","pronunciation":"/'ɪndɪkeɪtə(r)/","meaning":"n.指示物;指示者;指针;(汽车的)转向指示灯","unit":3,"lesson":3,"seq":46,"isStar":false},{"id":723,"word":"demonstrate","pronunciation":"/'demənstreɪt/","meaning":"v.证明,说明;演示;示威游行;表现","unit":3,"lesson":3,"seq":47,"isStar":false,"memo":"联想 demon(精力充沛的人)+st(联想 street)+rate(速度)→一群精力充沛的人在街上快速狂奔,“证明”自己的能力。","example":"They do not often demonstrate risky behaviours as their peers. 他们不像同龄人那样经常表现出危险行为。","derivative":"demonstration /ˌdemən'streɪʃn/ n.论证;示范;游行示威;表露\ndemonstrative /dɪ'mɒnstrətv/ adj.感情外露的;指示的 n.指示代词;限定词"},{"id":724,"word":"demonstration","pronunciation":"/ˌdemənˈstreɪʃn/","meaning":"n.论证;示范;游行示威;表露","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":725,"word":"demonstrative","pronunciation":"/dɪˈmɒnstrətɪv/","meaning":"adj.感情外露的;指示的 n.指示代词;限定词","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":726,"word":"illustrate","pronunciation":"/ˈləstreɪt/","meaning":"v.(用示例、图画等)说明,解释","unit":3,"lesson":3,"seq":48,"isStar":false,"memo":"联想 ill(有病的)+us(我们)+trate(音同 trait,特征)→他向我们举例“说明”有这种病的人的特征。","example":"Let me give an example to illustrate the point. 让我举个例子来说明这一点。","derivative":"illustration /ˌɪlə'streɪʃn/ n.图解;插图;示例\nillustrative /'ɪləstrətɪv/ adj.说明的;解释性的"},{"id":727,"word":"illustration","pronunciation":"/ɪləˈstreɪʃn/","meaning":"n.图解;插图;示例","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":728,"word":"illustrative","pronunciation":"/ˈɪləstrətɪv/","meaning":"adj.说明的;解释性的","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":729,"word":"deduce","pronunciation":"/dɪˈdjuːs/","meaning":"v.推论,推断;演绎","unit":3,"lesson":3,"seq":49,"isStar":false,"memo":"联想 de(音似“弟”)+du(联想“读”)+ce(音似“思”)→弟弟边读书边思考,最终“推断”出了问题的答案。","example":"We can deduce a lot from what people choose to buy. 从人们选购的东西中我们可以推断出很多信息。","derivative":"deducible /dɪ'djuːsəbl/ adj.可推论的"},{"id":730,"word":"deducible","pronunciation":"/dɪˈdjuːsəbl/","meaning":"adj.可推论的","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":731,"word":"introduce","pronunciation":"/ɪntrəˈdjuːs/","meaning":"v.介绍;采用;引进","unit":3,"lesson":3,"seq":50,"isStar":false,"memo":"构词 intro-(向内,进入)+duce(引导)→引导进入→介绍","example":"Before considering this question, it will be useful to introduce some related concepts. 在考虑这个问题之前,先介绍一些相关的概念是有益的。","derivative":"introduction /ˌɪntrə'dʌkʃn/ n.介绍;采用;引进"},{"id":732,"word":"introduction","pronunciation":"/ˌɪntrəˈdʌkʃn/","meaning":"n.介绍;采用;引进","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":733,"word":"deduct","pronunciation":"/dɪˈdʌkt/","meaning":"v.扣除,减去","unit":3,"lesson":3,"seq":51,"isStar":false},{"id":734,"word":"deduction","pronunciation":"/dɪdʌkʃn/","meaning":"n.演绎;推论,推理;扣除","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":735,"word":"deductive","pronunciation":"/dɪˈdʌktɪv/","meaning":"adj.演绎的;推论的,推理的","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":736,"word":"deductible","pronunciation":"/dɪˈdʌktəbl/","meaning":"adj.可扣除的,可减免的 n.免赔额;自负额","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":737,"word":"conduct","pronunciation":"/kənˈdʌkt/","meaning":"v.组织;实施;引导;举止;指挥 /ˈkɒndʌkt/ n.行为;经营方式;实施办法","unit":3,"lesson":3,"seq":52,"isStar":false,"memo":"联想 con-(所有) + duct(音似“打个他”) → 所有人都打他，这种“行为”是不对的，要加以“引导”。","example":"The sport has a strict code of conduct. 这种体育运动有严格的行为规范。","derivative":"conductor /kənˈdʌktə(r)/ n. (管弦乐队、合唱团等的) 指挥；列车长；售票员\nconducive /kənˈdjuːsɪv/ adj. 有助于……，有益于……"},{"id":738,"word":"conductor","pronunciation":"/kənˈdʌktə(r)/","meaning":"n.(管弦乐队、合唱队等的)指挥;列车长;售票员","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":739,"word":"conducive","pronunciation":"/kənˈdjuːsɪv/","meaning":"adj.有助于……,有益于……","unit":3,"lesson":3,"seq":53,"isStar":false,"memo":"con-（共同）+ duce（引导，词根duc=lead）+ -ive → 共同引向好结果！比如安静自习室就conducive to focus～","example":"A calm environment is conducive to deep thinking. 宁静的环境有助于深度思考。","derivative":"conduce /kənˈdjuːs/ v.有助于；促成"},{"id":740,"word":"induce","pronunciation":"/ɪnˈdjuːs/","meaning":"v.劝诱,诱使;引起","unit":3,"lesson":3,"seq":54,"isStar":false,"memo":"联想 in(里面) + du(联想“毒”) + ce(音似“死”) → 潘金莲被王婆“劝诱”，在家里毒死武大郎。","example":"People may be induced to eat more than is necessary. 人们可能会被诱导吃得比需要的多。","derivative":"inducement /ɪnˈdjuːsmənt/ n. 引诱；刺激；诱因"},{"id":741,"word":"inducement","pronunciation":"/ɪnˈdjuːsmənt/","meaning":"n.引诱;刺激;诱因","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":742,"word":"seduce","pronunciation":"/sɪˈdjus/","meaning":"v.引诱,诱惑;诱奸;勾引","unit":3,"lesson":3,"seq":55,"isStar":false},{"id":743,"word":"seduction","pronunciation":"/sɪdʌkʃn/","meaning":"n.诱奸;诱惑力,吸引力","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":744,"word":"seductive","pronunciation":"/sɪˈdʌktɪv/","meaning":"adj.诱人的,迷人的,有魅力的,有吸引力的","unit":3,"lesson":3,"seq":0,"isStar":true},{"id":745,"word":"tempt","pronunciation":"/tempt/","meaning":"v.引诱,诱惑;怂恿;利诱","unit":3,"lesson":3,"seq":57,"isStar":false,"memo":"谐音 单词发音类似“甜蜜扑他”→甜蜜的回忆扑向他，企图“引诱”他安于现状。","example":"People are unlikely to be tempted by such offers. 人们不太可能被这样的提议所诱惑。"},{"id":746,"word":"attempt","pronunciation":"/ə'tempt/","meaning":"n. & v.企图,试图,尝试","unit":3,"lesson":3,"seq":58,"isStar":false,"memo":"构词 at-(=to) + tempt(试探) → 企图，试图，尝试","example":"The problem with such a view is that some people actually attempt to live by it. 这种观点的问题是，有些人实际上试图按这种观点去生活。"},{"id":747,"word":"temptation","pronunciation":"/temp'teɪʃn/","meaning":"n.引诱,诱惑","unit":3,"lesson":3,"seq":59,"isStar":false,"memo":"构词 tempt(诱惑) + -ation(名词后缀) → 引诱，诱惑","example":"He can’t resist the temptation of TV either. 他也抵挡不住电视的诱惑。"},{"id":748,"word":"inject","pronunciation":"/ɪn'dʒekt/","meaning":"v.(给……)注射(药物等);(给……)投入(资金)","unit":3,"lesson":4,"seq":1,"isStar":false,"memo":"构词 in(里面)+ject(扔,投掷)→向里面扔→注射;投入","example":"The doctors injected the newly approved drug into the patient when he was critically ill. 医生在病人病情危重时给他注射了新获批的药物。","derivative":"injection /ɪn'dʒekʃn/ n.注射;(液体)注入"},{"id":749,"word":"injection","pronunciation":"/ɪn'dekʃn/","meaning":"n.注射;(液体)注入","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":750,"word":"project","pronunciation":"/'prɒdʒekt/","meaning":"n.项目;方案;工程;计划 /prə'dʒekt/ v.预计,推想;计划;表现(自己)","unit":3,"lesson":4,"seq":2,"isStar":false,"memo":"构词 pro-(前面)+ject(扔,投掷)→投掷到前面→方案;计划","example":"There are several projects underway to commercialise space travel. 目前有几个将太空旅行商业化的项目正在进行中。"},{"id":751,"word":"reject","pronunciation":"/rɪ'dʒekt/","meaning":"v.拒收;不录用;不予考虑,拒绝接受 /'riːdʒekt/ n.废品;不合格者,被拒收者","unit":3,"lesson":4,"seq":3,"isStar":false,"memo":"构词 re-(回)+ject(扔,投掷)→往回扔→拒绝接受;拒收","example":"Freedom of contract is possible only if both parties are free to accept and reject it. 合同自由只有在双方都能自由接受和拒绝的情况下才有可能实现。","derivative":"rejection /rɪ'dʒekʃn/ n.拒绝;不录用"},{"id":752,"word":"rejection","pronunciation":"/rɪ'dʒekʃn/","meaning":"n.拒绝;不录用","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":753,"word":"refusal","pronunciation":"/rɪ'fjuːzl/","meaning":"n.拒绝,回绝","unit":3,"lesson":4,"seq":4,"isStar":false,"memo":"对照 refuse v.拒绝,回绝→refusal n.","example":"Her answer amounted to a complete refusal. 她的答复等于完全拒绝。"},{"id":754,"word":"refuse","pronunciation":"/rɪ'fjuːz/","meaning":"n.废弃物,垃圾 v.拒绝,回绝","unit":3,"lesson":4,"seq":0,"isStar":true,"derivative":"refuse /'refjuːs/ n.废弃物,垃圾"},{"id":755,"word":"object","pronunciation":"/'ɒbdʒɪkt; 'ɒbdʒekt/","meaning":"n.物品,东西;对象;宾语 /əb'dʒekt/ v.反对","unit":3,"lesson":4,"seq":5,"isStar":false,"memo":"联想 ob-(表示方向)+ject(扔,投掷)→人们将“东西”扔向了自己“反对”的人。","example":"He objected to her proposal. 他反对她的提议。","derivative":"objective /əb'dʒektɪv/ n.目标,目的 adj.客观的,就事论事的;客观存在的,基于事实的"},{"id":756,"word":"objective","pronunciation":"/əb'dʒektv/","meaning":"n.目标,目的 adj.客观的,就事论事的;客观存在的,基于事实的","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":757,"word":"stuff","pronunciation":"/stf/","meaning":"n.东西,物品;事情 v.装满;给……装馅;吃撑","unit":3,"lesson":4,"seq":6,"isStar":false,"example":"Some animals shed tears to get rid of irritating stuff in their eyes. 一些动物会通过流泪来清除眼中的刺激物。","derivative":"stuffy /'stʌfi/ adj.闷热的;一本正经的,古板的\nstuffing /'stʌfɪŋ/ n.填料;填充物"},{"id":758,"word":"stuffy","pronunciation":"/'stʌfi/","meaning":"adj.闷热的;一本正经的,古板的","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":759,"word":"stuffing","pronunciation":"/'stʌfɪŋ/","meaning":"n.填料;填充物","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":760,"word":"staff","pronunciation":"/stɑːf/","meaning":"n.全体职员;拐杖","unit":3,"lesson":4,"seq":7,"isStar":false},{"id":761,"word":"personnel","pronunciation":"/ˌpɜːsə'nel/","meaning":"n.(组织或军队中的)人员,职员;人事部","unit":3,"lesson":4,"seq":8,"isStar":false},{"id":762,"word":"eject","pronunciation":"/ɪ'dekt/","meaning":"v.驱逐,逐出;喷射,射出","unit":3,"lesson":4,"seq":10,"isStar":false,"memo":"【构词】e-(出)+ject(扔,投掷)→扔出去→驱逐;射出","example":"He was ejected from a restaurant. 他被逐出餐厅。","derivative":"ejection /iˈdʒekʃn/ n.驱逐;喷射"},{"id":763,"word":"ejection","pronunciation":"/ɪ'dʒekʃn/","meaning":"n.驱逐;喷射","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":764,"word":"visual","pronunciation":"/'vɪʒuəl/","meaning":"adj.视力的,视觉的 n.视觉资料","unit":3,"lesson":4,"seq":11,"isStar":false,"memo":"【构词】vis(看)+-(u)al(形容词后缀)→视力的,视觉的","example":"He used striking visuals to get his point across. 他用醒目的视觉资料解释他的观点。"},{"id":765,"word":"devise","pronunciation":"/dɪ'vaɪz/","meaning":"v.设计,发明,想出","unit":3,"lesson":4,"seq":12,"isStar":false,"memo":"【联想】de-(往下)+vis(e)(看)→他只要低下头眼睛转一圈,就能“想出”一个点子。","example":"It was at that moment that I devised an idea to run away. 就在那一刻,我想出了一个逃跑的主意。"},{"id":766,"word":"device","pronunciation":"/dɪ'vaɪs/","meaning":"n.装置,仪器;手段","unit":3,"lesson":4,"seq":13,"isStar":false,"memo":"【联想】de(音似“弟”)+vi(形似罗马数字6)+ce(联想“车”)→弟弟用六辆车拉“仪器”。","example":"Sending advertising by email is very successful as a marketing device. 通过电子邮件发送广告是非常成功的营销手段。"},{"id":767,"word":"revise","pronunciation":"/rɪ'vaz/","meaning":"v.改变,修改;复习;修订(文稿)","unit":3,"lesson":4,"seq":14,"isStar":false,"example":"The country would need to revise its current economic policy. 该国需要修改其目前的经济政策。","derivative":"revision /rˈvɪʒn/ n. 修改, 修订; 复习"},{"id":768,"word":"revision","pronunciation":"/rɪ'vɪʒn/","meaning":"n.修改;修订;复习","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":769,"word":"visualise/-ize","pronunciation":"/'vɪʒuəlaɪz/","meaning":"v.想象,构思,设想","unit":3,"lesson":4,"seq":15,"isStar":false},{"id":770,"word":"envisage","pronunciation":"/ɪn'vɪzɪdʒ/","meaning":"v.设想,展望","unit":3,"lesson":4,"seq":16,"isStar":false,"memo":"[构词] en-(进入) + vis(看) + -age(后缀)→使进入看的状态→设想","example":"What level of profit do you envisage? 你预计会有什么样的利润水平?"},{"id":771,"word":"vision","pronunciation":"/'vʒn/","meaning":"n.视力;视野;想象,幻想;(电视)图像 n.有眼力的人,有远见卓识的人 | | | | | | | | |","unit":3,"lesson":4,"seq":17,"isStar":false,"memo":"[构词] vis(看) + -ion(名词后缀)→视力;幻想","example":"He had a vision of a world in which there would be no wars. 他幻想一个没有战争的世界。","derivative":"visionary /vɪʒənəri/ adj.有眼力的,有远见卓识的 n.有眼力的人,有远见卓识的人"},{"id":772,"word":"visible","pronunciation":"/'vzəbl/","meaning":"adj.看得见的,可见的;明显的","unit":3,"lesson":4,"seq":18,"isStar":false,"memo":"[构词] vis(看) + -ible(可以……的)→看得见的,可见的","example":"There is no visible evidence to support his idea. 没有明显的证据支持他的观点。","derivative":"visibility /ˌvɪzəˈbɪləti/ n. 可见度,能见度;可见性,明显性\ninvisible /ɪnˈvɪzəbl/ adj.看不见的;无形的"},{"id":773,"word":"visibility","pronunciation":"/ˌvɪzə'bɪləti/","meaning":"n.可见度,能见度;可见性;明显性","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":774,"word":"invisible","pronunciation":"/ɪn'vɪzəbl/","meaning":"adj.看不见的;无形的","unit":3,"lesson":4,"seq":0,"isStar":true,"memo":"构词：in-（不）+ vis-（看）+ -ible（能…的）→ 看不见的！哈利·波特披上斗篷秒变'in-see-bull'。","example":"Microplastics in drinking water are invisible but pose serious health risks. 饮用水中的微塑料肉眼不可见，却带来严重健康风险。","derivative":"visibility /ˌvɪzəˈbɪləti/ n.可见度；visibly /ˈvɪzəbli/ adv.明显地"},{"id":775,"word":"interview","pronunciation":"/'ɪntəvju:/","meaning":"n. & v.面试;采访;会见","unit":3,"lesson":4,"seq":19,"isStar":false,"memo":"[构词] inter-(相互) + view(看)→相互看→面试;采访","example":"I've got another job interview tomorrow. 我明天还有一个求职面试。","derivative":"interviewer /ˈntəvjuːə(r)/ n. 主持面试者;采访者\ninterviewee /ˌntəvjuːˈiː/ n. 参加面试者;被采访者"},{"id":776,"word":"interviewer","pronunciation":"/'ɪntəvju:ə(r)/","meaning":"n.主持面试者;采访者","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":777,"word":"interviewee","pronunciation":"/ˌɪntəvju:'i:/","meaning":"n.参加面试者;被采访者","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":778,"word":"preview","pronunciation":"/'pri:vju:/","meaning":"v.预演;预展;写预评 n.预映;预展","unit":3,"lesson":4,"seq":20,"isStar":false},{"id":779,"word":"interfere","pronunciation":"/ˌɪntə'fə(r)/","meaning":"v.干涉,干预","unit":3,"lesson":4,"seq":21,"isStar":false,"memo":"联想 inter-(在……中间) + fere(音似“飞”)→他学习时，有只苍蝇在中间来来回回地飞，它在“干预”他的学习。","example":"I try not to let work interfere with my personal life. 我尽量不让工作干扰我的私生活。","derivative":"interference /ˌntəˈfɪərəns/ n.干涉,干预,介入"},{"id":780,"word":"interference","pronunciation":"/ɪntə'fɪərəns/","meaning":"n.干涉,干预,介入","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":781,"word":"intervene","pronunciation":"/ˌɪntə'vi:n/","meaning":"v.干预,介入;打岔,插话;阻碍","unit":3,"lesson":4,"seq":22,"isStar":false,"memo":"构词 inter-(在……中间) + ven(e)(= to come)→来到两者之间→干预，介入","example":"The government intervened effectively. 政府进行了有效的干预。","derivative":"intervention /ˌɪntəˈvenʃn/ n.出面;干预;打断(别人的话)"},{"id":782,"word":"intervention","pronunciation":"/ˌntə'venʃn/","meaning":"n.出面;干预;打断(别人的话)","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":783,"word":"interact","pronunciation":"/ɪntərˈækt/","meaning":"v.交流;交往;相互影响;相互作用","unit":3,"lesson":4,"seq":23,"isStar":false,"memo":"构词 inter-(相互) + act(行动)→相互地行动→交流；相互影响","example":"Perfume interacts with the skin's natural chemicals. 香水和皮肤的天然化学物质相互作用。","derivative":"interactive /ˌɪntərˈæktɪv/ adj.交互的;合作的;相互影响的,互相配合的\ninteraction /ˌɪntərˈækʃn/ n.相互作用;交流;互动"},{"id":784,"word":"interactive","pronunciation":"/ɪntərˈæktɪv/","meaning":"adj.交互的;合作的;相互影响的,互相配合的","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":785,"word":"interaction","pronunciation":"/ɪntərækʃn/","meaning":"n.相互作用;交流;互动","unit":3,"lesson":4,"seq":24,"isStar":false,"memo":"inter-（互相）+ act（行动）+ -ion → 大家一起动起来！像宿舍里抢WiFi时你戳我、我戳你，纯纯的‘互动’现场。","example":"Online learning requires frequent student-teacher interaction. 在线学习需要师生频繁互动。","derivative":"interactive /ɪnˈterəktɪv/ adj.相互作用的；交互式的"},{"id":786,"word":"supervise","pronunciation":"/ˈsupəvaɪz/","meaning":"v.监督;管理;指导","unit":3,"lesson":4,"seq":25,"isStar":false,"memo":"构词 super-(在……上) + vise(看)→在上面看→监督","example":"She supervises a number of important projects. 她管理着许多重要的项目。","derivative":"supervision /ˌsupəˈvɪn/ n.监督;管理;指导"},{"id":787,"word":"supervision","pronunciation":"/ˌsupəˈvɪn/","meaning":"n.监督;管理;指导","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":788,"word":"supervisor","pronunciation":"/ˈsuːpəvaɪzə(r)/","meaning":"n.监督人;指导者;主管","unit":3,"lesson":4,"seq":26,"isStar":false},{"id":789,"word":"monitor","pronunciation":"/mɒnɪtə(r)/","meaning":"n.班长,监督员;显示器,监视器v.监视,监督;检查;监听","unit":3,"lesson":4,"seq":27,"isStar":false,"memo":"构词 monit(警告) + -or(后缀)→班长；监督员；监视器","example":"The government is monitoring the situation closely. 政府正密切关注着局势。"},{"id":790,"word":"superior","pronunciation":"/suˈpəriə(r)/","meaning":"adj.更好的;更强的;更高的n.级别更高的人;上级,上司","unit":3,"lesson":4,"seq":28,"isStar":false,"memo":"联想 super(在……上面) + i(我) + -or(后缀)→职级在我上面的人→上级，上司","example":"You should let your superiors know how good you are. 你应该让你的上级知道你有多优秀。","derivative":"superiority /ˌsupəriˈɒrəti/ n.优越;优势;优越感"},{"id":791,"word":"superiority","pronunciation":"/suˌpɪəriˈɒrəti/","meaning":"n.优越;优势;优越感","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":792,"word":"inferior","pronunciation":"/nˈfɪəriə(r)/","meaning":"adj.级别低的,下级的;较差的,次的n.(能力或地位)低于他人者;下属,下级","unit":3,"lesson":4,"seq":29,"isStar":false,"memo":"联想 in(里面) + fer(音似“废”) + i(我) + -or(后缀)→他一个人每天在家里荒废日子，沦为了“低于他人者”。","example":"It was a gentleman's duty always to be civil, even to his inferiors. 一个绅士的责任是一直保持彬彬有礼，即使是对比自己地位低的人。"},{"id":793,"word":"inferiority","pronunciation":"/ɪnˌfɪəriˈɒrəti/","meaning":"n.低等,劣等;劣势","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":794,"word":"superb","pronunciation":"/suˈpɜːb/","meaning":"adj.极佳的,卓越的,出色的","unit":3,"lesson":4,"seq":30,"isStar":false,"memo":"super（超越）+ b（联想“不”）→ 不能再超越的 → 极佳的","example":"His artistic taste is superb. 他的艺术品位极佳。"},{"id":795,"word":"supreme","pronunciation":"/suˈpriːm/","meaning":"adj.(权力、重要性或影响力)最高的,至高无上的;(程度)很大的","unit":3,"lesson":4,"seq":31,"isStar":false,"memo":"supre（联想 super，超越）+ me（我）→ 超越自我 → 最高的","example":"It required a supreme effort to stay awake. 要保持清醒需要极大的努力。","derivative":"supremacy /suːˈpreməsi/ n. 至高无上；最大权力；最高地位"},{"id":796,"word":"supremacy","pronunciation":"/supreməsi/","meaning":"n.至高无上;最大权力;最高地位","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":797,"word":"superstition","pronunciation":"/suːpəˈstɪʃn/","meaning":"n.迷信","unit":3,"lesson":4,"seq":32,"isStar":false,"memo":"super（在……上）+ stit（站）+ -ion（名词后缀）→ 站在我们理性之上的观念 → 迷信","example":"It's all superstition, and there's nothing to it. 这都是迷信，不是真的。","derivative":"superstitious /ˌsuːpəˈstʃəs/ adj. 迷信的"},{"id":798,"word":"superstitious","pronunciation":"/ˌsuːpəstɪʃəs/","meaning":"adj.迷信的","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":799,"word":"religion","pronunciation":"/rɪˈlɪdʒən/","meaning":"n.宗教,宗教信仰","unit":3,"lesson":4,"seq":33,"isStar":false,"memo":"re（字母音似“阿姨”）+ ligion（音似“历尽”）→ 阿姨历尽沧桑之后，开始研究“宗教”。","example":"Religion informs every aspect of their lives. 宗教影响着他们生活的各个方面。","derivative":"religious /rɪˈlɪdʒəs/ adj. 宗教的；虔诚的"},{"id":800,"word":"religious","pronunciation":"/rɪˈlɪdʒəs/","meaning":"adj.宗教的;虔诚的","unit":3,"lesson":4,"seq":0,"isStar":true},{"id":801,"word":"confess","pronunciation":"/kən'fes/","meaning":"v.供认;承认(错误或罪行);忏悔","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":802,"word":"seminar","pronunciation":"/'semna:(r)/","meaning":"n.(大学教师带领学生作专题讨论的)研讨课;研讨会","unit":4,"lesson":1,"seq":14,"isStar":false,"memo":"谐音 单词发音类似“私密呢”→他们正在“研讨会”上讨论一些私密的问题呢。","example":"He thinks the seminar won't be open to the public. 他认为研讨会不会向公众开放。"},{"id":803,"word":"workshop","pronunciation":"/'wɜːkʃɒp/","meaning":"n.研讨会;讲习班;车间,工场,作坊","unit":4,"lesson":1,"seq":15,"isStar":false,"memo":"构词 work(工作)+shop(工坊)→车间,工场","example":"The special workshop was presided over by a famous scientist. 那次专题研讨会是由一位著名的科学家主持的。"},{"id":804,"word":"forum","pronunciation":"/'fɔːrəm/","meaning":"n.论坛,讨论会","unit":4,"lesson":1,"seq":16,"isStar":false,"memo":"联想 fo(联想for)+rum(音似room)→他为了找个合适的房间备考,去学校“论坛”上浏览合租信息。","example":"The government should not brush aside ideas from the World Economic Forum. 政府不应无视世界经济论坛的观点。"},{"id":805,"word":"academic","pronunciation":"/ˌækə'demɪk/","meaning":"n.大学教师 adj.学术的,学业的","unit":4,"lesson":1,"seq":17,"isStar":false,"memo":"谐音 单词发音类似“挨个点名”→有的“大学教师”一上课先挨个点名。","example":"Maintaining high academic standards is the priority of the university. 维持高学术标准是该大学首先考虑的事情。","derivative":"academician n.院士;学会会员"},{"id":806,"word":"academician","pronunciation":"/ˌækə'demɪʃn/","meaning":"n.院士;学会会员","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":807,"word":"academy","pronunciation":"/ə'kædəmi/","meaning":"n.专科院校;(艺术、文学、科学等的)研究院;学会","unit":4,"lesson":1,"seq":18,"isStar":false,"memo":"联想 a(一)+cade(音似“开导”)+my(我的)→一个开导我的地方→研究院;学会","example":"She trained at the Royal Academy of Music. 她在皇家音乐学院培训过。"},{"id":808,"word":"epidemic","pronunciation":"/ˌepɪ'demɪk/","meaning":"n.传染病;(坏事)泛滥,蔓延 adj.流行的","unit":4,"lesson":1,"seq":19,"isStar":false,"memo":"联想 epi(音似“爱陪”)+demic(联想 academic)→很多学生爱陪同学搞学术研究,这是很“流行的”。","example":"That kind of epidemic disease has long been stamped out. 那种传染病早已根除。"},{"id":809,"word":"vaccine","pronunciation":"/'væksiːn/","meaning":"n.疫苗","unit":4,"lesson":1,"seq":20,"isStar":false,"memo":"谐音 单词发音类似“完可神”→打完“疫苗”就能预防疾病,可神了。","example":"The search for a new vaccine will take priority over all other medical research. 研制新的疫苗将排在其他一切医学研究之前。","derivative":"vaccinate v.给……接种疫苗\nvaccination n.疫苗接种"},{"id":810,"word":"vaccinate","pronunciation":"/'væksɪneɪt/","meaning":"v.给……接种疫苗","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":811,"word":"vaccination","pronunciation":"/ˌvæksɪ'neɪʃn/","meaning":"n.疫苗接种","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":812,"word":"immune","pronunciation":"/ɪ'mjuːn/","meaning":"adj.有免疫力的;不受影响的;豁免的","unit":4,"lesson":1,"seq":21,"isStar":false,"memo":"联想 i(我)+mmune(联想“木讷”)→我比较木讷,不易受外界影响→不受影响的","example":"You'll eventually become immune to criticism. 你终有一日会不再在意批评。","derivative":"immunity n.免疫力\nimmunise v.(尤指通过注射疫苗)使免疫"},{"id":813,"word":"immunity","pronunciation":"/ɪ'mjuːnəti/","meaning":"n.免疫力","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":814,"word":"immunise/-ize","pronunciation":"/'ɪmjunaɪz/","meaning":"v.(尤指通过注射疫苗)使免疫","unit":4,"lesson":1,"seq":22,"isStar":false},{"id":815,"word":"insulate","pronunciation":"/'ɪnsjuleɪt/","meaning":"v.使隔热;使隔音;使绝缘;使免受(不良影响);隔离","unit":4,"lesson":1,"seq":23,"isStar":false,"memo":"构词：in-（使进入）+ sula（=sulcus沟槽，引申为‘隔开’）+ -ate→往缝隙里填料‘使绝缘/隔音’，像给墙打‘胶’！","example":"New buildings must insulate walls to reduce energy consumption. 新建筑必须对墙体进行隔热处理以降低能耗。","derivative":"insulation /ˌɪnsjʊ'leɪʃ(ə)n/ n.绝缘；隔热"},{"id":816,"word":"insulation","pronunciation":"/ˌɪnsju'leɪʃn/","meaning":"n.隔绝;绝缘材料","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":817,"word":"insulator","pronunciation":"/'ɪnsjuleɪtə(r)/","meaning":"n.隔热(或绝缘、隔音等的)材料(或装置)","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":818,"word":"section","pronunciation":"/'sekʃn/","meaning":"n.部分;部门;(书、报等的)节 v.切开;做切片","unit":4,"lesson":1,"seq":24,"isStar":false,"memo":"构词 sect(切)+-ion(后缀)→分开的部分→部分;部门;节","example":"Business services are listed in a special section. 企业服务被列在一个特别的部分。"},{"id":819,"word":"sector","pronunciation":"/'sektə(r)/","meaning":"n.(尤指商业、贸易等的)部门;行业;区域","unit":4,"lesson":1,"seq":25,"isStar":false,"memo":"谐音 单词发音类似“塞个他”→领导把他塞到自己的“部门”。","example":"She works in the voluntary sector. 她在志愿部门工作。"},{"id":820,"word":"segment","pronunciation":"/'seɡmənt/","meaning":"n.部分;瓣;弓形 /seɡ'ment/ v.分割;划分","unit":4,"lesson":1,"seq":26,"isStar":false,"memo":"构词 seg(分开)+-ment(后缀)→部分;分割","example":"It displays only small segments of books that are in copyright. 它只展示了受版权保护的书籍的一小部分内容。","derivative":"segmental /segˈmentl/ adj.音段的"},{"id":821,"word":"segmental","pronunciation":"/seɡ'mentl/","meaning":"adj.音段的","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":822,"word":"senior","pronunciation":"/'siːniə(r)/","meaning":"adj.级别(或地位)高的;资深的;年长的 n.毕业班学生;老年人","unit":4,"lesson":1,"seq":27,"isStar":false,"memo":"谐音 单词发音类似“似泥人”→那个“毕业班学生”呆板得像泥人一样。","example":"They never lose time in upgrading products for seniors. 他们总是争分夺秒地为老年人升级产品。"},{"id":823,"word":"seniority","pronunciation":"/sɪˌnjɔːrəti/","meaning":"n.资历;年长;级别高","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":824,"word":"undergraduate","pronunciation":"/ˌʌndərˈɡrædʒuət/","meaning":"n.(在读的)大学本科生","unit":4,"lesson":1,"seq":28,"isStar":false,"memo":"构词 under(在……以下)+graduate(毕业)→没有毕业→(在读的)大学本科生","example":"Over a lecture course, the teacher showed undergraduates works of Impressionism. 在一次演讲中,老师向本科生展示了印象派作品。"},{"id":825,"word":"bachelor","pronunciation":"/bætʃələ(r)/","meaning":"n.未婚男子,单身汉;学士","unit":4,"lesson":1,"seq":29,"isStar":false,"memo":"联想 bache(联想“爸车”)+I(形似1)+-or(表示人的后缀)→爸爸车里坐着一个人,他是个“单身汉”。","example":"Students earn their Bachelor of Science in nursing in a year. 学生们在一年内获得护理学学士学位。"},{"id":826,"word":"master","pronunciation":"/ˈmɑːstə(r)/","meaning":"n.大师,能手;主人,雇主;硕士 v.精通;掌握;控制","unit":4,"lesson":1,"seq":30,"isStar":false,"example":"It was a skill that required lots of practice to master. 这是一项需要大量练习才能掌握的技能。","derivative":"mastery /ˈmɑːstəri/ n.精通;熟练掌握"},{"id":827,"word":"mastery","pronunciation":"/ˈmɑːstəri/","meaning":"n.精通;熟练掌握","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":828,"word":"masterpiece","pronunciation":"/ˈmɑːstəpiːs/","meaning":"n.代表作;杰作;名著","unit":4,"lesson":1,"seq":31,"isStar":false,"memo":"构词 master(大师)+piece(一件作品)→大师的一件作品→杰作","example":"They found inspiration in the greatest masterpieces. 他们从最伟大的杰作中找到了灵感。"},{"id":829,"word":"grasp","pronunciation":"/ɡrɑːsp/","meaning":"n.紧握;理解(力) v.抓紧;理解,领会","unit":4,"lesson":1,"seq":32,"isStar":false,"memo":"联想 gras(联想 grass)+p(联想“趴”)→小宝宝趴在地上,“抓紧”一撮草使劲拔。","example":"She felt a firm grasp on her arm. 她感到手臂被紧紧地抓住。"},{"id":830,"word":"adolescent","pronunciation":"/ˌædəˈlesnt/","meaning":"n.青少年","unit":4,"lesson":1,"seq":33,"isStar":false,"memo":"联想 ado(音似“爱逗”) + lescent(音似 lesson)→课后爱遛狗的是那个“青少年”。","example":"Many industries are going out of infancy and becoming adolescents. 许多行业正在走出婴儿期，步入青少年时期。"},{"id":831,"word":"adolescence","pronunciation":"/ˌædəˈlesns/","meaning":"n.青春期;青春","unit":4,"lesson":1,"seq":34,"isStar":false},{"id":832,"word":"idle","pronunciation":"/aɪdl/","meaning":"v.无所事事;(发动机)空转 adj.不工作的;空闲的;无所事事的","unit":4,"lesson":1,"seq":35,"isStar":false,"memo":"谐音 单词发音类似“爱逗”→在这儿逗留的是个“空闲的”人。","example":"She was bored with her idle life at home. 她对在家里无所事事的生活感到厌倦。","derivative":"idly /'aidli/ adv.毫无目的地;漫不经心地;闲散地"},{"id":833,"word":"idly","pronunciation":"/ˈaɪdli/","meaning":"adv.毫无目的地;漫不经心地;闲散地","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":834,"word":"private","pronunciation":"/ˈpraɪvət/","meaning":"adj.私有的;秘密的,私人的","unit":4,"lesson":1,"seq":36,"isStar":false,"example":"Private colleges and universities can offer smaller classes and more personal attention. 私立学院和大学能提供更小的班级和更多的个人关注。","derivative":"privacy /'praɪvəsi/ n.隐私;私密\nprivatise/-ize /'praɪvətaɪz/ v.使私有化;将……私营化\nprivatisation/-ization /'praɪvətaɪ'zeɪʃn/ n.私有化"},{"id":835,"word":"privacy","pronunciation":"/ˈprɪvəsi/","meaning":"n.隐私;私密","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":836,"word":"privatise/-ize","pronunciation":"/ˈpraɪvətaz/","meaning":"v.使私有化;将……私营化","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":837,"word":"whisper","pronunciation":"/ˈwɪspə(r)/","meaning":"n.耳语,低语;谣言 v.耳语,低语,小声说","unit":4,"lesson":1,"seq":37,"isStar":false,"memo":"联想 whi(音似 we) + sper(音似“撕破”)→“我们撕破脸了。”她在我耳边“小声说”。","example":"He whispered something in her ear. 他在她的耳边低声说了些什么。"},{"id":838,"word":"gossip","pronunciation":"/ˈɡɒsɪp/","meaning":"n.流言蜚语;闲聊;爱说长道短的人 v.说闲话","unit":4,"lesson":1,"seq":38,"isStar":false,"memo":"谐音 单词发音类似“搞事婆”→她像个搞事婆,喜欢在人背后“说闲话”。","example":"We must be willing to be the terminator of gossip. 我们必须愿意成为流言蜚语的终结者。"},{"id":839,"word":"mutter","pronunciation":"/ˈmʌtə(r)/","meaning":"n.嘀咕;低语声 v.嘀咕;(私下)抱怨,发牢骚","unit":4,"lesson":1,"seq":39,"isStar":false,"memo":"谐音 单词发音类似“妈特”→妈妈年龄大了,特别喜欢“嘀咕”。","example":"He just sat there muttering to himself. 他坐在那儿独自嘀嘀咕咕的。"},{"id":840,"word":"image","pronunciation":"/ɪmɪdʒ/","meaning":"n.图像,影像;形象,声誉","unit":4,"lesson":1,"seq":40,"isStar":false,"memo":"联想 i(我)+m(联想“妈”)+age(年龄)→我对妈妈年轻时在灯下补衣服的“形象”记忆犹新。","derivative":"imaging"},{"id":841,"word":"imaging","pronunciation":"/ˈɪmɪdɪŋ/","meaning":"n.成像","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":842,"word":"mature","pronunciation":"/məˈtjʊə(r);<br>məˈtʃʊə(r)/","meaning":"adj.成熟的;理智的,明白事理的;成 年的;老练的","unit":4,"lesson":1,"seq":41,"isStar":false,"memo":"联想 ma(联想“妈”) + ture(联想 true)→做了妈妈以后,她才真的成熟了→成熟的","example":"He has a mature and responsible attitude to work. 他对待工作的态度成熟,有责任心。","derivative":"maturity /mə'tʃʊərəti; mə'tjərəti/ n.成熟(期);到期(应付款)"},{"id":843,"word":"premature","pronunciation":"/'premətʃə(r)/","meaning":"adj.过早的;早产的;仓促的","unit":4,"lesson":1,"seq":42,"isStar":false,"memo":"构词 pre-(在前) + mature(成熟的)→在成熟之前的→过早的;早产的","example":"Because of injury, her playing career came to a premature end. 因为受伤,她的演奏生涯过早结束了。"},{"id":844,"word":"moral","pronunciation":"/'mɒrəl/","meaning":"n.道德准则(标准);寓意;教育意义 adj.道德(上)的;品行端正的","unit":4,"lesson":1,"seq":43,"isStar":false,"memo":"联想 m(联想“妈”) + oral(口头的)→妈妈口头上教育我们要遵守“道德准则”。"},{"id":845,"word":"morality","pronunciation":"/mə'ræləti/","meaning":"n.道德,道德观;道德规范","unit":4,"lesson":1,"seq":0,"isStar":true,"example":"The moral is that crime doesn’t pay. 寓意就是犯罪得不偿失。"},{"id":846,"word":"mortal","pronunciation":"/'mɔːtl/","meaning":"adj.凡人的;终有一死的;致命的 n.凡人,普通人","unit":4,"lesson":1,"seq":44,"isStar":false,"memo":"谐音 单词发音类似“没头”→干活没有头脑是他“致命的”缺点。","example":"Her reputation suffered a mortal blow as a result of the scandal. 由于丑闻,她的名誉受到了致命的打击。","derivative":"mortality /mɔː'tæləti/ n.死亡数量;死亡率"},{"id":847,"word":"mortality","pronunciation":"/mɔː'tæləti/","meaning":"n.死亡数量;死亡率","unit":4,"lesson":1,"seq":0,"isStar":true},{"id":848,"word":"campus","pronunciation":"/'kæmpəs/","meaning":"n.(大学、学院的)校园,校区","unit":4,"lesson":1,"seq":45,"isStar":false,"memo":"联想 camp(露营) + us(我们)→我们一起在“校园”里露营。","example":"The statue stands on the campus of the university. 这座雕像矗立在这所大学的校园里。"},{"id":849,"word":"campaign","pronunciation":"/kæm'peɪn/","meaning":"n.运动;战役 v.参加运动,领导运动","unit":4,"lesson":1,"seq":46,"isStar":false,"memo":"谐音 单词发音类似“肯拼”→在这场“战役”中,每个战士都肯为国拼命。","example":"They began a campaign to encourage people to shop locally. 他们开展运动,鼓励人们购买本地产品。"},{"id":850,"word":"scope","pronunciation":"/skəʊp/","meaning":"n.(活动、书籍等的)范围,领域;机会","unit":4,"lesson":2,"seq":1,"isStar":false,"memo":"对照:那个美女(s)能解决(cope)这个领域(scope)的问题。","example":"This question is outside the scope of scientific research. 这个问题不在科学研究的范围之内。"},{"id":851,"word":"terrain","pronunciation":"/tə'reɪn/","meaning":"n.地形,地势","unit":4,"lesson":2,"seq":2,"isStar":false,"memo":"联想:ter(音似“特”)+rain(雨)→一场特别大的雨改变了这里的“地形”。","example":"The terrain changed quickly from arable land to desert. 这处地形很快由耕地变成了沙漠。"},{"id":852,"word":"realm","pronunciation":"/relm/","meaning":"n.领域;王国","unit":4,"lesson":2,"seq":3,"isStar":false,"memo":"对照:他认为,真正的(real)男人(man)会在某个领域(realm)做出成绩。","example":"This idea belongs in the realm of science fiction. 这是属于科幻小说领域的构思。"},{"id":853,"word":"sphere","pronunciation":"/sfɪə(r)/","meaning":"n.球形;范围,领域","unit":4,"lesson":2,"seq":4,"isStar":false,"memo":"联想:s(联想“蛇”)+p(联想“趴”)+here(这儿)→那条蛇趴在这儿,宣告这是它的势力“范围”。","example":"Its principal advantage would be the improvement of freedom in every sphere of daily life. 它的主要优点是提高日常生活各个领域的自由度。"},{"id":854,"word":"spherical","pronunciation":"/'sferɪkl/","meaning":"adj.球形的;球状的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":855,"word":"domain","pronunciation":"/də'meɪn;<br>dəʊ'meɪn/","meaning":"n.(知识、活动的)领域,范围;领土","unit":4,"lesson":2,"seq":5,"isStar":false,"memo":"联想:do(做)+main(主要的)→我们的成绩主要是在这个“领域”内做出来的。","example":"It is important to realize that fashion covers a much wider domain. 重要的是要意识到时尚涵盖了一个更广泛的领域。"},{"id":856,"word":"hemisphere","pronunciation":"/'hemɪsfɪə(r)/","meaning":"n.(地球或大脑的)半球","unit":4,"lesson":2,"seq":6,"isStar":false,"memo":"构词:hemi-(半)+sphere(球)→半球","example":"In the northern hemisphere, December is a winter month. 在北半球,十二月是冬季。"},{"id":857,"word":"atmosphere","pronunciation":"/'ætməsfɪə(r)/","meaning":"n.大气层;气氛,氛围;气体","unit":4,"lesson":2,"seq":7,"isStar":false,"memo":"联想:atmo(联想“阿童木”)+sphere(领域)→他说阿童木的活动领域是整个“大气层”。","example":"It will take a bit longer to transform the atmosphere so that human beings could live there. 要转变大气层使人类能够在那里生活,还需要更久。","derivative":"atmospheric /ˌætməsˈferɪk/ adj.大气的,大气层的"},{"id":858,"word":"atmospheric","pronunciation":"/ˌætməs'ferɪk/","meaning":"adj.大气的,大气层的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":859,"word":"circumstance","pronunciation":"/'sɜːkəmstəns/","meaning":"n.环境;境遇;状况;命运;客观环境","unit":4,"lesson":2,"seq":8,"isStar":false,"memo":"联想 circum(联想 circle) + st(联想 stand) + -ance(名词后缀) → 周围站立的事物等 → 环境","example":"I know I can trust her in any circumstance. 我知道我在任何情况下都能信任她。"},{"id":860,"word":"surround","pronunciation":"/sə'raʊnd/","meaning":"v.围绕;围住","unit":4,"lesson":2,"seq":9,"isStar":false,"memo":"构词 sur-(上面) + round(环绕) → 从上面环绕着 → 围绕；围住","example":"The trees surround the lake. 环湖都是大树。","derivative":"surroundings /sə'raʊndɪŋz/ n.环境"},{"id":861,"word":"surroundings","pronunciation":"/sə'raʊndɪŋz/","meaning":"n.环境","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":862,"word":"mood","pronunciation":"/mu:d/","meaning":"n.情绪;气氛,氛围","unit":4,"lesson":2,"seq":10,"isStar":false,"memo":"对照 独(d)自坐着看月亮(moon)，是很有氛围(mood)的。","example":"The foggy weather has affected Mary's mood. 雾蒙蒙的天气影响了玛丽的情绪。","derivative":"moody /'mudi/ adj.情绪多变的，喜怒无常的"},{"id":863,"word":"moody","pronunciation":"/'mu:di/","meaning":"adj.情绪多变的,喜怒无常的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":864,"word":"climate","pronunciation":"/'klaɪmət/","meaning":"n.气候(区);环境气氛;风气,氛围","unit":4,"lesson":2,"seq":11,"isStar":false,"memo":"联想 c(形似半圆) + li(联想“立”) + mate(伙伴) → 伙伴们在我周围站立成了半圆，营造出节日的“氛围”。","example":"We need to adjust to this changing climate. 我们需要适应这种不断变化的气候。","derivative":"climatic /klaɪ'mætɪk/ adj.气候的"},{"id":865,"word":"climatic","pronunciation":"/klaɪ'mætɪk/","meaning":"adj.气候的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":866,"word":"universe","pronunciation":"/'ju:nɪvɜ:s/","meaning":"n.宇宙;天地万物,万象","unit":4,"lesson":2,"seq":12,"isStar":false,"example":"Could there be intelligent life elsewhere in the universe? 宇宙中别的地方还会有智慧生命吗？"},{"id":867,"word":"universal","pronunciation":"/ju:nɪ'vɜ:sl/","meaning":"adj.普遍的;全体的;全世界的","unit":4,"lesson":2,"seq":13,"isStar":false,"memo":"对照 universe n.宇宙 → universal adj.","example":"Agreement on this issue is almost universal. 这个问题几乎取得全体一致的意见。"},{"id":868,"word":"widespread","pronunciation":"/'waɪdspred/","meaning":"adj.分布广的;普遍的,广泛的","unit":4,"lesson":2,"seq":14,"isStar":false,"memo":"构词 wide(广) + spread(传播) → 分布广的；普遍的；广泛的","example":"There is widespread support for the new proposals. 这些新提案得到广泛的支持。"},{"id":869,"word":"anniversary","pronunciation":"/ˌænɪ'vɜ:səri/","meaning":"n.周年纪念日","unit":4,"lesson":2,"seq":15,"isStar":false,"memo":"构词：anni-（年，如annual）+ vers-（转，如reverse）+ -ary→一年‘转’一圈的纪念日！别记成‘爱人纪念日’——那是‘anniversary’不是‘anniversary’！","example":"The university celebrated its 100th anniversary with a global forum. 大学举办全球论坛庆祝建校百年。","derivative":"anniversarial /ˌænɪvɜː'seərɪəl/ adj.周年纪念的"},{"id":870,"word":"annual","pronunciation":"/'ænjuəl/","meaning":"adj.每年的,一年一次的 n.年刊;一年生植物","unit":4,"lesson":2,"seq":16,"isStar":false},{"id":871,"word":"diverse","pronunciation":"/daɪ'vɜ:s/","meaning":"adj.各种各样的,形形色色的","unit":4,"lesson":2,"seq":17,"isStar":false,"memo":"【构词】di-（分开）+ verse（转）→各转各的方向→千差万别！像食堂窗口：川菜、粤菜、轻食、甜品——diverse到选不过来。","example":"Our university welcomes diverse cultural backgrounds. 我校欢迎多元文化背景的学生。","derivative":"diversity /daɪˈvɜːsəti/ n.多样性"},{"id":872,"word":"diversify","pronunciation":"/daɪ'vɜːsɪfaɪ/","meaning":"v.(使)多样化,变化","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":873,"word":"diversity","pronunciation":"/daɪ'vɜ:səti/","meaning":"n.差异,不同;多样性","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":874,"word":"divert","pronunciation":"/daɪ'vɜ:t/","meaning":"v.使转向;使绕道;改变;转移(某人) 的注意力","unit":4,"lesson":2,"seq":18,"isStar":false,"memo":"【谐音+联想】‘迪维特’→ 迪士尼乐园游客太多，广播：‘Please divert to Exit B’（请转向B出口），路一转，方向就变！","example":"Traffic was diverted due to road construction near campus. 因校园附近道路施工，交通被临时改道。","derivative":"diversion /daɪˈvɜːʃ(ə)n/ n.转移；diverting /daɪˈvɜːtɪŋ/ adj.有趣的"},{"id":875,"word":"diversion","pronunciation":"/daɪ'vɜ:ʃn/","meaning":"n.转移,转向;消遣,娱乐;转移视线(或 注意力)的事物","unit":4,"lesson":2,"seq":19,"isStar":false},{"id":876,"word":"converse","pronunciation":"/kən'vɜ:s/","meaning":"v.交谈,谈话 /'knvɜ:s/ adj.相反的 n.相反的事物;反面","unit":4,"lesson":2,"seq":20,"isStar":false,"memo":"构词 con-(一起) + verse(转换)→一起互相转换思想→交谈","example":"The converse of this concern is that the prospects of becoming a multi-paycheck household could encourage marriages. 成为多薪家庭的前景可能会鼓励人们结婚。"},{"id":877,"word":"controversy","pronunciation":"/'kɒntrəvɜ:si;<br>kən'trɒvɜ:si/","meaning":"n.争议,论战;辩论","unit":4,"lesson":2,"seq":21,"isStar":false,"memo":"构词 contro-(相反) + vers(e)(转) + -y(名词后缀)→相反的观点来回转→争议;论战","example":"There is always controversy in educational circles. 教育界一直存在争议。","derivative":"controversial /ˌkɒntrəˈvːʃl/ adj.引起争论的,有争议的"},{"id":878,"word":"controversial","pronunciation":"/ˌkɒntrə'vɜ:l/","meaning":"adj.引起争论的,有争议的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":879,"word":"conversation","pronunciation":"/ˌkɒnvə'seɪʃn/","meaning":"n.(非正式的)交谈,谈话","unit":4,"lesson":2,"seq":22,"isStar":false,"memo":"联想 conver(音似“看我”) + sa(音似 say) + tion(音似“什”)→请先看看我说过什么,再和我“交谈”。","example":"None of that is the topic of conversation in the dining room. 那些都不是在该餐厅里讨论的话题。"},{"id":880,"word":"convert","pronunciation":"/kən'vɜ:t/","meaning":"v.(使)转变,转换;(使)改变 /'kɒnvɜ:t/ n.皈依者","unit":4,"lesson":2,"seq":23,"isStar":false,"memo":"构词 con-(一起,相互) + vert(= verse,转化)→转变","example":"You need to ensure that you've converted the data properly. 你需要确保已经正确转换了数据。","derivative":"conversion /kənˈvːʃn/ n.转变,转换;转化; convertible /kənˈvɜːtəbl/ adj.可改变的;可转换的"},{"id":881,"word":"conversion","pronunciation":"/kən'vɜ:n/","meaning":"n.转变,转换;转化","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":882,"word":"convertible","pronunciation":"/kən'vɜ:təbl/","meaning":"adj.可改变的;可转换的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":883,"word":"aversion","pronunciation":"/ə'vɜːʃn/","meaning":"n.厌恶,憎恶","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":884,"word":"invert","pronunciation":"/n'vɜːt/","meaning":"v.(使)倒转,颠倒,倒置","unit":4,"lesson":2,"seq":25,"isStar":false,"memo":"[构词] in-(表加强) + vert(转)→彻底改变→颠倒","example":"Place a plate over the cake tin and invert it. 在蛋糕烤模上盖一个盘子,然后将其翻过来。"},{"id":885,"word":"inversion","pronunciation":"/ɪn'vɜːʃn/","meaning":"n.倒置,颠倒,倒转","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":886,"word":"reverse","pronunciation":"/r'vɜːs/","meaning":"n.相反的情况(或事物);倒挡 v.彻底转变,使反转 adj.相反的","unit":4,"lesson":2,"seq":26,"isStar":false,"memo":"[构词] re-(回,反) + verse(转)→往回转→彻底转变,使反转","example":"This problem is the reverse of the previous one. 这个问题和上一个问题相反。"},{"id":887,"word":"reversal","pronunciation":"/rɪ'vɜːsl/","meaning":"n.颠倒;彻底转变;倒退","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":888,"word":"reversible","pronunciation":"/rɪ'vɜːsəbl/","meaning":"adj.可逆的;可翻转的;可两面穿的, 正反两用的","unit":4,"lesson":2,"seq":27,"isStar":false},{"id":889,"word":"adverse","pronunciation":"/'ædvɜːs; əd'vɜːs/","meaning":"adj.不利的;有害的;反面的","unit":4,"lesson":2,"seq":28,"isStar":false,"memo":"[联想] ad(一再地)+verse(转)→孩子叛逆,一再地把头转向一边,如果家长引导不好,会产生“不利的”影响。","example":"Their state of mind can have adverse effect on their judgment. 他们的心理状态可能会对他们的判断产生不利影响。"},{"id":890,"word":"adversity","pronunciation":"/əd'vɜːsəti/","meaning":"n.困境,逆境;不幸","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":891,"word":"adversary","pronunciation":"/'ædvəsəri/","meaning":"n.(辩论、战斗中的)敌手,对手","unit":4,"lesson":2,"seq":29,"isStar":false},{"id":892,"word":"versatile","pronunciation":"/'vɜːsətaɪl/","meaning":"adj.多才多艺的;多功能的","unit":4,"lesson":2,"seq":30,"isStar":false,"memo":"[联想] vers(转) + atile→能转得开的→多才多艺的","example":"He is a very versatile person. 他多才多艺。"},{"id":893,"word":"verse","pronunciation":"/vɜːs/","meaning":"n.诗,诗节;韵文;歌曲的段落","unit":4,"lesson":2,"seq":31,"isStar":false,"memo":"[谐音] 单词发音类似“我诗”→诗;诗节","example":"She has written enough poetry to put together a slender book of verse. 她写的诗足够编成一本薄薄的诗集了。"},{"id":894,"word":"verbal","pronunciation":"/'vɜːbl/","meaning":"adj.口头的,言语的","unit":4,"lesson":2,"seq":32,"isStar":false,"memo":"[谐音] 单词发音类似“我不”→这个小男孩不想做妈妈安排的事情时,常说“我不”→口头的","example":"These can be verbal cues or even body language. 这些可以是口头上的提示,甚至是肢体语言。"},{"id":895,"word":"vocal","pronunciation":"/'vəʊkl/","meaning":"adj.嗓音的;发声的;歌唱的;直言不 讳的","unit":4,"lesson":2,"seq":33,"isStar":false,"memo":"[联想] voc(联想 voice) + -al(形容词后缀)→嗓音的","example":"If a singer coughs, this can result in the bruising of the vocal chords. 歌手如果咳嗽,可能会导致声带损伤。"},{"id":896,"word":"innovate","pronunciation":"/'nəveɪt/","meaning":"v.创新;改革","unit":4,"lesson":2,"seq":34,"isStar":false,"memo":"in-(入) + nov(新) + -ate(动词后缀)→使新事物进入→创新,改革","example":"He called on graduates to innovate in his commencement address. 他在他的毕业典礼演讲中呼吁毕业生们创新。","derivative":"innovation /ɪnəˈveʃn/ n.创造,创新,改革; innovative /ˈnəveɪtɪv; ˈɪnəvətɪv/ adj.革新的;创新的"},{"id":897,"word":"innovation","pronunciation":"/ˌɪnə'veɪʃn/","meaning":"n.创造,创新;改革","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":898,"word":"innovative","pronunciation":"/'ɪnəveɪtɪv;<br>'ɪnəvətɪv/","meaning":"adj.革新的;创新的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":899,"word":"legend","pronunciation":"/'ledʒənd/","meaning":"n.传说,传奇故事;传奇人物","unit":4,"lesson":2,"seq":35,"isStar":false,"example":"What made him the legend he still is today? 是什么让他成为今天依旧传奇的人物呢?","derivative":"legendary /ˈledʒəndri/ adj.传奇的;传说的"},{"id":900,"word":"legendary","pronunciation":"/'ledəndri/","meaning":"adj.传奇的;传说的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":901,"word":"renovate","pronunciation":"/'renəveɪt/","meaning":"v.修复;翻新;重新粉刷","unit":4,"lesson":2,"seq":36,"isStar":false,"memo":"re-(再) + nov(新) + -ate(动词后缀)→使再次变新→翻新","example":"They spent the summer renovating the farmhouse. 他们花了一个夏天翻新农舍。","derivative":"renovation /ˌrenəˈveɪʃn/ n.修复;翻新;重新粉刷"},{"id":902,"word":"renovation","pronunciation":"/ˌrenə'veɪʃn/","meaning":"n.修复;翻新;重新粉刷","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":903,"word":"evolve","pronunciation":"/ɪ'vlv/","meaning":"v.进化;逐步发展;逐渐演变","unit":4,"lesson":2,"seq":37,"isStar":false,"memo":"e-(向外) + volve(转)→向外回转→螺旋式上升→进化;逐步发展","example":"The company has evolved into a major chemical manufacture. 这家公司已逐步发展成一个主要的化工厂。","derivative":"evolution /ˌiːvəˈluːʃn; ˌevəˈluʃn/ n.进化,演变;发展; evolutionary /ˌiːvəˈluːʃənri; ˌevəˈluːʃənri/ adj.进化的;逐渐发展的"},{"id":904,"word":"evolution","pronunciation":"/ˌiːvə'luːʃn;<br>ˌevə'luːʃn/","meaning":"n.进化;演变;发展","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":905,"word":"evolutionary","pronunciation":"/ˌiːvəˈluːʃənri;<br>evəˈluːənri/","meaning":"adj.进化的;逐渐发展的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":906,"word":"involve","pronunciation":"/ɪnˈvɒlv/","meaning":"v.涉及;包含;需要;参与","unit":4,"lesson":2,"seq":38,"isStar":false,"memo":"in-(= in) + volve (转) →转入→涉及;包含","example":"It has to involve spending a lot of money and time. 这需要花费大量的金钱和时间。","derivative":"involvement /nˈvɒlvmənt/ n.参与,加入;插手; involved /ɪnˈvɒld/ adj.卷入的,有关的;复杂的"},{"id":907,"word":"involvement","pronunciation":"/ɪnˈvlvmənt/","meaning":"n.参与,加入;插手","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":908,"word":"involved","pronunciation":"/ɪnˈvɒlvd/","meaning":"adj.卷入的,有关的;复杂的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":909,"word":"revolve","pronunciation":"/rɪvɒlv/","meaning":"v.旋转;环绕","unit":4,"lesson":2,"seq":39,"isStar":false,"memo":"[对照] revolve v.旋转→revolution n.","example":"Contrast this with farming since the start of the industrial revolution. 将这与工业革命开始以来的农业对比一下。","derivative":"revolution n."},{"id":910,"word":"revolution","pronunciation":"/ˌrevəˈluːʃn/","meaning":"n.革命,巨变;大变革","unit":4,"lesson":2,"seq":40,"isStar":false},{"id":911,"word":"revolutionary","pronunciation":"/ˌrevəluːʃənəri/","meaning":"adj.革命的 n.改革者;革命者","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":912,"word":"revolt","pronunciation":"/rˈvəʊlt/","meaning":"n.反抗;起义;造反 v.叛逆;反抗,反叛","unit":4,"lesson":2,"seq":41,"isStar":false,"memo":"[构词] re-(回)+volt(转)→往回转,反转过来(对抗自己人)→反抗,反叛","example":"The people revolted against foreign rule. 人们起来反抗外来统治。"},{"id":913,"word":"renaissance","pronunciation":"/rɪneɪsns/","meaning":"n.(尤指某种艺术形式、音乐形式等 的)复兴","unit":4,"lesson":2,"seq":42,"isStar":false,"memo":"[联想] re(字母音似“阿姨”)+nai(联想“奶”)+ssance(音似“神似”)→阿姨和奶奶年轻时候的穿着神似,说明了中式审美的“复兴”。","example":"Hawaiian culture is a living culture undergoing a renaissance today. 夏威夷文化是一种蓬勃复兴的活态文明。"},{"id":914,"word":"revive","pronunciation":"/rɪˈvaɪv/","meaning":"v.(使)苏醒,使复苏;重新上演","unit":4,"lesson":2,"seq":43,"isStar":false,"memo":"[构词] re-(重新)+vive(=live)→重新活过来→(使)苏醒;使复苏","example":"Robots help companies to revive. 机器人帮助企业复苏。","derivative":"revival /rɪˈvaɪvl/ n.复兴;复苏;再流行;重演"},{"id":915,"word":"revival","pronunciation":"/rɪˈvaɪvl/","meaning":"n.复兴;复苏;再流行;重演","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":916,"word":"vivid","pronunciation":"/ˈvvɪd/","meaning":"adj.生动的,逼真的;鲜艳的","unit":4,"lesson":2,"seq":44,"isStar":false,"memo":"[谐音] 单词发音类似“娓娓的”→娓娓动听的→生动的","example":"This doesn't make my emotions any more vivid. 这并未让我的情感体验变得更加鲜活。"},{"id":917,"word":"survive","pronunciation":"/səˈvaɪv/","meaning":"v.生存,幸存,生还","unit":4,"lesson":2,"seq":45,"isStar":false,"memo":"[构词] sur-(超过)+vive(=live)→超过(困境)生存下来→幸存","example":"They can only survive in parts of the Americas. 他们只能在美洲部分地区生存。","derivative":"survivor /səˈvaɪvə(r)/ n.生还者,幸存者 survival /səˈvaɪvl/ n.幸存;存活;残存物"},{"id":918,"word":"survivor","pronunciation":"/səˈvaɪvə(r)/","meaning":"n.生还者,幸存者","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":919,"word":"survival","pronunciation":"/səˈvaɪvl/","meaning":"n.幸存,存活;残存物","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":920,"word":"reform","pronunciation":"/rɪˈfɔːm/","meaning":"n.改革,改良 v.改革,改进;改造(行为)","unit":4,"lesson":2,"seq":46,"isStar":false,"memo":"[构词] re-(再)+form(形成)→再形成一种形态→改革,改进","example":"The law needs to be reformed. 法律需要进行改革。","derivative":"reformation /refəˈmeɪn/ n.改革,改进 reformist /rɪˈfːmɪst/ n.改良者,改革者 adj.主张改革的,改革派的;改良主义的"},{"id":921,"word":"reformation","pronunciation":"/ˌrefəˈmeɪʃn/","meaning":"n.改革,改进","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":922,"word":"reformist","pronunciation":"/rɪˈfɔːmɪst/","meaning":"n.改良者,改革者 adj.主张改革的, 改革派的;改良主义的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":923,"word":"conform","pronunciation":"/kənˈfɔːm/","meaning":"v.遵守,遵从;相一致,相吻合","unit":4,"lesson":2,"seq":47,"isStar":false,"memo":"[构词] con-(共同) + form(形式)→使形式统一→相一致","example":"We must conform to the rules. 我们必须遵守规定。","derivative":"conformity /kənˈfɔːməti/ n.(对社会规则的)遵从，遵守"},{"id":924,"word":"conformity","pronunciation":"/kənˈfɔːməti/","meaning":"n.(对社会规则的)遵从,遵守","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":925,"word":"uniform","pronunciation":"/ˈjuːnɪfɔːm/","meaning":"n.校服;制服","unit":4,"lesson":2,"seq":48,"isStar":false,"memo":"[构词] uni-(单一，统一) + form(形式)→校服；制服","example":"He quickly put on his uniform. 他迅速穿上制服。","derivative":"uniformity /ˌjuːnɪˈfɔməti/ n.一致；统一"},{"id":926,"word":"uniformity","pronunciation":"/ˌjuːnɪ'fɔːməti/","meaning":"n.一致,统一","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":927,"word":"platform","pronunciation":"/'plætfɔm/","meaning":"n.站台;讲台;舞台;平台","unit":4,"lesson":2,"seq":49,"isStar":false,"memo":"[构词] plat(平坦的) + form(形式)→平台","example":"What platform does it go from? 它从哪个站台发车？"},{"id":928,"word":"formula","pronunciation":"/'fɔmjələ/","meaning":"n.公式;配方","unit":4,"lesson":2,"seq":50,"isStar":false,"example":"This formula is used to calculate the area of a circle. 这个公式用于计算圆的面积。"},{"id":929,"word":"formulate","pronunciation":"/'fɔːmjuleɪt/","meaning":"v.制定;规划;构想;确切表达","unit":4,"lesson":2,"seq":51,"isStar":false,"memo":"[联想] for(音似 four) + mu(联想“母”) + late(晚)→开家长会时，四个妈妈迟到了，她们“确切表达”了理由。","example":"Governments need to formulate energy policies. 各国政府需要制定能源政策。","derivative":"formulation /ˌfɔːmjuˈleɪʃn/ n.制定；规划；构想；确切表达"},{"id":930,"word":"formulation","pronunciation":"/ˌfɔːmju'leɪn/","meaning":"n.制定;规划;构想;确切表达","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":931,"word":"formal","pronunciation":"/'fɔːml/","meaning":"adj.正规的,正式的;形式上的;整齐的","unit":4,"lesson":2,"seq":52,"isStar":false,"memo":"[构词] form(形式) + -al(形容词后缀)→正式的；形式上的","example":"He kept the tone of the letter formal and businesslike. 他使这封信保持正式公文的语气。","derivative":"formality /fɔːˈmæləti/ n.正式手续；例行公事"},{"id":932,"word":"formality","pronunciation":"/fɔ'mæləti/","meaning":"n.正式手续;例行公事","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":933,"word":"inform","pronunciation":"/ɪn'fɔːm/","meaning":"v.通知,通告;了解,熟悉","unit":4,"lesson":2,"seq":53,"isStar":false,"memo":"[对照] information n.信息→inform v.","example":"Please inform us of any changes of address. 地址若有变动，请通知我们。","derivative":"information /ˌɪnfəˈmeɪʃn/ n.信息，消息，情报；资料\ninformative /ɪnˈfːmətɪv/ adj.提供有用信息的；给予知识的\ninformant /ɪnˈfɔːrmənt/ n.告密者；合作者"},{"id":934,"word":"information","pronunciation":"/ˌɪnfə'meɪn/","meaning":"n.信息,消息,情报;资料","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":935,"word":"informative","pronunciation":"/ɪn'fɔːmətɪv/","meaning":"adj.提供有用信息的;给予知识的","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":936,"word":"informant","pronunciation":"/ɪn'fɔːmənt/","meaning":"n.告密者;合作者","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":937,"word":"perform","pronunciation":"/pə'fɔːm/","meaning":"v.演出,表演;做;执行;工作,运转","unit":4,"lesson":2,"seq":54,"isStar":false},{"id":938,"word":"performance","pronunciation":"/pə'fɔːməns/","meaning":"n.表演,演出;表现;业绩","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":939,"word":"performer","pronunciation":"/pə'fɔːmə(r)/","meaning":"n.表演者,演出者","unit":4,"lesson":2,"seq":0,"isStar":true},{"id":940,"word":"inspect","pronunciation":"/ɪn'spekt/","meaning":"v.仔细检查,检验;视察","unit":4,"lesson":3,"seq":1,"isStar":false,"memo":"[构词] in-(入) + spect(看)→看入内部→仔细检查;视察","example":"The police will inspect the venue for safety. 警察将仔细检查会场是否安全。","derivative":"inspection /nˈspekʃn/ n.视察;检查"},{"id":941,"word":"inspection","pronunciation":"/ɪn'spekʃn/","meaning":"n.视察;检查","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":942,"word":"inspector","pronunciation":"/ɪn'spektə(r)/","meaning":"n.检查员;视察员,巡视员;(警察)巡官","unit":4,"lesson":3,"seq":2,"isStar":false},{"id":943,"word":"expect","pronunciation":"/ɪk'spekt/","meaning":"v.预期;期待;要求,期望;猜想","unit":4,"lesson":3,"seq":3,"isStar":false,"example":"Its results were just as expected. 结果正如预期的那样。","derivative":"expectation /ˌekspekˈteɪʃn/ n.预料;预期;期望"},{"id":944,"word":"expectation","pronunciation":"/ˌekspek'teɪʃn/","meaning":"n.预料;预期;期望","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":945,"word":"expectancy","pronunciation":"/ɪk'spektənsi/","meaning":"n.预期;期待;期望","unit":4,"lesson":3,"seq":4,"isStar":false},{"id":946,"word":"longevity","pronunciation":"/lɒnˈdʒevəti/","meaning":"n.长寿;持续时间","unit":4,"lesson":3,"seq":5,"isStar":false},{"id":947,"word":"prolong","pronunciation":"/prəlɒŋ/","meaning":"v.延长","unit":4,"lesson":3,"seq":6,"isStar":false,"memo":"[构词] pro-(往前) + long(长)→往前变长→延长","example":"Surgery for cancer may cure or prolong someone's life. 癌症手术可能会治愈疾病或延长某人的生命。"},{"id":948,"word":"lengthy","pronunciation":"/ˈleŋθi/","meaning":"adj.长时间的;冗长的","unit":4,"lesson":3,"seq":7,"isStar":false},{"id":949,"word":"aspect","pronunciation":"/æspekt/","meaning":"n.方面;方位;外观,外表","unit":4,"lesson":3,"seq":8,"isStar":false,"memo":"[联想] a(一) + spect(看) → 看一眼,只能了解事物的一个“方面”。","example":"Every aspect of our lives will be transformed. 我们生活的方方面面都将被改变。"},{"id":950,"word":"suspect","pronunciation":"/ˈsʌspekt/","meaning":"n.犯罪嫌疑人 adj.可疑的 /səˈspekt/ v.猜想;怀疑","unit":4,"lesson":3,"seq":9,"isStar":false,"memo":"[构词] sus-(在下) + spect(看) → 在下面看→暗暗打量→怀疑;犯罪嫌疑人","example":"He is suspected of having slipped something in her bag. 他涉嫌在她的包里塞了什么东西。","derivative":"suspicion /sə'spɪʃn/ n.怀疑,嫌疑"},{"id":951,"word":"suspicion","pronunciation":"/səˈspɪʃn/","meaning":"n.怀疑,嫌疑","unit":4,"lesson":3,"seq":10,"isStar":false,"memo":"[谐音] 单词发音类似“瑟斯陪审”→这个人有“嫌疑”,瑟斯在陪审。","example":"They drove away slowly to avoid arousing suspicion. 他们驾车缓缓离去,以免引起怀疑。","derivative":"suspicious /sə'spɪʃəs/ adj.怀疑的;可疑的"},{"id":952,"word":"suspicious","pronunciation":"/səˈspɪəs/","meaning":"adj.怀疑的;可疑的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":953,"word":"susceptible","pronunciation":"/səˈseptəbl/","meaning":"adj.易受影响的;易得病的","unit":4,"lesson":3,"seq":11,"isStar":false,"memo":"[构词] sus-(在下) + cept(拿) + -ible(能……的) → 能被拿下的→易受影响的","example":"Some of these plants are more susceptible to frost damage than others. 其中的一些植物比其他植物更容易受到霜冻损害。"},{"id":954,"word":"spectator","pronunciation":"/spekˈteɪtə(r)/","meaning":"n.观看者,观众","unit":4,"lesson":3,"seq":12,"isStar":false,"memo":"[联想] spect(看) + at(在) + -or(表示人的后缀) → 在看比赛的人→观看者,观众","example":"They try hard to meet the spectators' expectations. 他们努力满足观众的期望。"},{"id":955,"word":"respect","pronunciation":"/rɪˈspekt/","meaning":"n.尊敬;方面 v.尊敬;遵守","unit":4,"lesson":3,"seq":13,"isStar":false,"memo":"[构词] re-(再;反复) + spect(看) → 反复看(对方)→尊敬","example":"He should show respect for the interviewer. 他应该尊重面试官。","derivative":"respectable /rɪ'spektəbl/ adj.体面的;值得尊敬的 respectful /rɪ'spektfl/ adj.有礼貌的,尊敬的 respective /rɪ'spektv/ adj.分别的,各自的 respectively /rɪ'spektɪvli/ adv.各自,分别;依次为;顺序为"},{"id":956,"word":"respectable","pronunciation":"/rɪˈspektəbl/","meaning":"adj.体面的;值得尊敬的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":957,"word":"respectful","pronunciation":"/rɪˈspektfl/","meaning":"adj.有礼貌的,尊敬的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":958,"word":"respective","pronunciation":"/rˈspektɪv/","meaning":"adj.分别的,各自的","unit":4,"lesson":3,"seq":14,"isStar":false,"memo":"【构词】re-（回）+ spec（看）+ -ive→各自回头‘看’自己的那份→各自的！小组汇报时：A讲方法，B讲数据，C讲结论——respectively对应。","example":"The three departments submitted their reports respectively. 三个部门分别提交了各自的报告。","derivative":"respectively /rɪˈspek.tɪv.li/ adv.分别地；各自地"},{"id":959,"word":"respectively","pronunciation":"/rɪspektɪvli/","meaning":"adv.各自,分别;依次为;顺序为","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":960,"word":"spectacular","pronunciation":"/spekˈtækjələ(r)/","meaning":"adj.壮观的;令人惊叹的 n.壮观的场面;精彩的表演","unit":4,"lesson":3,"seq":15,"isStar":false,"memo":"[联想] spec(t)(看) + tacular(音似“太酷了”) → 看起来太酷了→壮观的;令人惊叹的","example":"With creativity, even old-fashioned instruments may produce spectacular sound effects. 有了创造力,即使是老式乐器也可能产生令人惊叹的音效。","derivative":"spectacle /'spektəkl/ n.壮观的场面(景象)"},{"id":961,"word":"spectacle","pronunciation":"/ˈspektəkl/","meaning":"n.壮观的场面(景象)","unit":4,"lesson":3,"seq":16,"isStar":false,"memo":"[联想] spec(t)(看) + tacle(音似“特酷”) → 我们看到“壮观的场面”会觉得特别酷。","example":"It was a spectacle not to be missed. 这是一个不可错过的奇观。"},{"id":962,"word":"prosperity","pronunciation":"/prɒˈsperəti/","meaning":"n.兴旺,繁荣,昌盛","unit":4,"lesson":3,"seq":17,"isStar":false},{"id":963,"word":"prosper","pronunciation":"/ˈprɒspə(r)/","meaning":"v.繁荣,兴旺,发达","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":964,"word":"prosperous","pronunciation":"/ˈprɒspərəs/","meaning":"adj.繁荣的,兴旺的,发达的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":965,"word":"spectrum","pronunciation":"/ˈspektrəm/","meaning":"n.(观点、人、情况等的)范围,幅度;光谱,频谱","unit":4,"lesson":3,"seq":18,"isStar":false,"memo":"联想 spec(t)(看)+trum(音似“戳目”)→这部分“光谱”的光会看得戳目(刺眼)。","example":"The colours of the spectrum can be seen in a rainbow. 光谱中的颜色都可以在彩虹中见到。"},{"id":966,"word":"conspicuous","pronunciation":"/kənˈspkjuəs/","meaning":"adj.明显的,引人注目的","unit":4,"lesson":3,"seq":19,"isStar":false,"memo":"构词 con-(一起)+spic(=spect,看)+(u)ous(形容词后缀)→有目共睹的→明显的,引人注目的","example":"A visitor to a museum today would notice conspicuous changes in the way museums are operated. 今天参观博物馆的游客会注意到博物馆运作方式的明显变化。"},{"id":967,"word":"despise","pronunciation":"/dɪ'spaɪz/","meaning":"v.鄙视,蔑视","unit":4,"lesson":3,"seq":20,"isStar":false,"memo":"构词 de-(向下)+spise(=spect,看)→向下看→鄙视,蔑视","example":"I despise such people; they've no character. 我藐视这种人;他们没骨气。"},{"id":968,"word":"scorn","pronunciation":"/skɔːn/","meaning":"n. & v.轻视,鄙视,蔑视","unit":4,"lesson":3,"seq":21,"isStar":false,"memo":"对照 吃着人家的玉米(corn)还鄙视(scorn)人家,这是不对的。","example":"The man looked at him with scorn. 那人轻蔑地看着他。","derivative":"scornful /'skɔːrnfl/ adj.轻蔑的,鄙视的"},{"id":969,"word":"scornful","pronunciation":"/'skɔːnfʊl/","meaning":"adj.轻蔑的,鄙视的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":970,"word":"perspective","pronunciation":"/pə'spektɪv/","meaning":"n.角度,观点,看法;透视法;景观","unit":4,"lesson":3,"seq":22,"isStar":false,"memo":"构词 per(透过)+spect(看)+-ive(名词后缀)→看透了→观点,看法","example":"It inspired them to view things from broader perspectives. 这激励他们从更广阔的角度看待事物。"},{"id":971,"word":"stance","pronunciation":"/stæns; stɑːns/","meaning":"n.(公开表明的)观点,立场,看法;站姿","unit":4,"lesson":3,"seq":23,"isStar":false,"memo":"对照 思想上站(stand)的那个点,就是我们的观点(stance)。","example":"An open-science stance can also add complexity to a collaboration. 开放科学的立场也会增加合作的复杂性。"},{"id":972,"word":"standpoint","pronunciation":"/'stændpɔnt/","meaning":"n.立场,观点","unit":4,"lesson":3,"seq":24,"isStar":false,"memo":"[构词] stand(站) + point(点)→立场,观点","example":"We must approach the problem from a different standpoint. 我们必须换一种角度来处理这个问题。"},{"id":973,"word":"substance","pronunciation":"/'sʌbstəns/","meaning":"n.物质;主旨;实质","unit":4,"lesson":3,"seq":25,"isStar":false,"memo":"[构词] sub-(在下) + stance(观点)→站在(观点等的)下面→物质;主旨","example":"Some brand-name coffees contain harmful substances. 一些名牌咖啡含有有害物质。","derivative":"substantial /səbˈstænʃl/ adj.大量的;重大的"},{"id":974,"word":"substantial","pronunciation":"/səb'stænʃl/","meaning":"adj.大量的;重大的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":975,"word":"stereotype","pronunciation":"/'steriətap/","meaning":"n.刻板印象,老一套 v.对……形成模式化(或类型化)的看法","unit":4,"lesson":3,"seq":26,"isStar":false,"memo":"[联想] ste(音似“死呆”) + reo(音似 real) + type(类型)→如果认为他真的是死呆类型的人,那就是“刻板印象”了。","example":"A stereotype is a simplistic or exaggerated image that human carries in their minds about groups of people. 刻板印象是人们头脑中对一群人持有的一种简单化或夸张的印象。","derivative":"v.对……形成模式化(或类型化)的看法"},{"id":976,"word":"prototype","pronunciation":"/'prəʊtətaɪp/","meaning":"n.原型,雏形","unit":4,"lesson":3,"seq":27,"isStar":false,"memo":"[构词] proto-(最初的,原始的) + type(类型)→原型,雏形","example":"The prototype is athletic and super smart. 这个原型体格健壮、非常聪明。"},{"id":977,"word":"speculate","pronunciation":"/'spekjuleɪt/","meaning":"v.猜测,推测;投机","unit":4,"lesson":3,"seq":28,"isStar":false,"memo":"[联想] spec(联想 spect,看) + u(联想 you) + late(迟)→他看完你的信迟迟未动,开始“推测”后面的事。","example":"It is useless to speculate why he did it. 对他为什么这么做妄加猜测毫无用处。","derivative":"speculation /ˌspekjuˈleɪʃn/ n.猜测;投机买卖\nspeculative /spekjələtɪv/ adj.猜测的;投机的"},{"id":978,"word":"speculation","pronunciation":"/ˌspekju'leɪʃn/","meaning":"n.猜测;投机买卖","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":979,"word":"speculative","pronunciation":"/'spekjələtɪv/","meaning":"adj.猜测的;投机的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":980,"word":"articulate","pronunciation":"/ɑː'tɪkjuleɪt/","meaning":"v.清楚地表达;口齿清楚地讲 /ɑː'tɪkjələt/ adj.能说会道的;清楚的","unit":4,"lesson":3,"seq":29,"isStar":false,"memo":"[联想] art(艺术) + i(我) + culate→我能用艺术性的语言把事物表达出来,他说我是“能说会道的”。","example":"He was too drunk to articulate properly. 他醉得连话都说不清楚。","derivative":"/ɑːˈtkjələt/ adj.能说会道的;清楚的\narticulation /ɑˌtɪkjuleɪʃn/ n.表达;说话;发音;清晰"},{"id":981,"word":"articulation","pronunciation":"/ɑːˌtɪkju'leɪʃn/","meaning":"n.表达;说话;发音;清晰","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":982,"word":"prospect","pronunciation":"/'prɒspekt/","meaning":"n.前景,展望;希望;可能性 /prə'spekt/ v.勘探;寻找(商业机会)","unit":4,"lesson":3,"seq":30,"isStar":false,"memo":"[构词] pro-(往前) + spect(看)→前景,展望","example":"I'm very excited at the prospect of joining the team. 我对加入这个团队的前景感到非常兴奋。","derivative":"/prəˈspekt/ v.勘探;寻找(商业机会)"},{"id":983,"word":"prospective","pronunciation":"/prə'spektɪv/","meaning":"adj.有望的;预期的;潜在的","unit":4,"lesson":3,"seq":31,"isStar":false,"memo":"[构词] prospect(展望) + -ive(形容词后缀)→有望的;潜在的","example":"I had a phone call from a prospective client today. 我今天接到一个潜在客户打来的电话。"},{"id":984,"word":"retrospect","pronunciation":"/'retrəspekt/","meaning":"n.回顾,回想,追溯往事","unit":4,"lesson":3,"seq":32,"isStar":false,"memo":"[构词] retro-(向后) + spect(看)→回顾","example":"In retrospect, I think that I was wrong. 回首往事,我觉得当时我错了。","derivative":"retrospective /ˌretrəˈspektɪv/ adj.回顾的;有追溯效力的"},{"id":985,"word":"retrospective","pronunciation":"/ˌretrə'spektɪv/","meaning":"adj.回顾的;有追溯效力的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":986,"word":"portray","pronunciation":"/pɔː'treɪ/","meaning":"v.描写,描绘;画(人物、景象等);扮演(角色)","unit":4,"lesson":3,"seq":33,"isStar":false,"memo":"por(音似“破”)+tray(音似tree)→他能把一棵残破的树“描绘”得活灵活现。","example":"It portrayed western train trips as wonderful adventures. 它把西部的火车旅行描绘成美妙的冒险。","derivative":"portrait /'pɔːtreɪt/ n.(人的)肖像,画像;(对事物的)描绘\nportrayal /pɔː'treɪəl/ n.描绘;描写"},{"id":987,"word":"portrait","pronunciation":"/'pɔːtrət/","meaning":"n.(人的)肖像,画像;(对事物的)描绘","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":988,"word":"portrayal","pronunciation":"/pɔː'treɪəl/","meaning":"n.描绘,描写","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":989,"word":"sculpture","pronunciation":"/'skʌlptʃə(r)/","meaning":"n.雕像;雕塑品","unit":4,"lesson":3,"seq":34,"isStar":false,"memo":"sculp(音似“思刻”)+ture(名词后缀)→他思考片刻后雕刻出来一个“雕像”。","example":"She has learned to appreciate sculptures. 她已学会欣赏雕塑。"},{"id":990,"word":"carve","pronunciation":"/kɑːv/","meaning":"v.雕,刻","unit":4,"lesson":3,"seq":35,"isStar":false,"memo":"他在山洞(cave)的壁上雕刻(carve)了一朵花。","example":"The statue was carved out of a single piece of stone. 这座雕像是用整块石料雕成的。","derivative":"carving /'kɑːvɪŋ/ n.雕刻品;雕刻图案;雕像"},{"id":991,"word":"carving","pronunciation":"/'kɑːvɪŋ/","meaning":"n.雕刻品;雕刻图案;雕像","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":992,"word":"describe","pronunciation":"/dɪ'skraɪb/","meaning":"v.描述,形容;描写","unit":4,"lesson":3,"seq":36,"isStar":false,"memo":"de-(往下)+scribe(写)→写下来→描述","example":"Reporters gathered in the hall to hear her describe the plan. 记者聚集在大厅里,听她描述这一计划。","derivative":"description /dɪ'skrɪpʃn/ n.描写(文字);形容;说明;类型\ndescriptive /dɪ'skrɪptɪv/ adj.描写的;叙述的;说明的"},{"id":993,"word":"description","pronunciation":"/dɪ'skrɪpʃn/","meaning":"n.描写(文字);形容;说明;类型","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":994,"word":"descriptive","pronunciation":"/dɪ'skrɪptɪv/","meaning":"adj.描写的;叙述的;说明的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":995,"word":"depict","pronunciation":"/dɪ'pɪkt/","meaning":"v.描绘;描写,描述,刻画","unit":4,"lesson":3,"seq":37,"isStar":false,"memo":"de-(表加强)+pict(联想picture)→这是一幅“描绘”乡村美景的画。","example":"The novel depicts French society in the 1930s. 这部小说描述了20世纪30年代的法国社会。"},{"id":996,"word":"ascribe","pronunciation":"/ə'skraɪb/","meaning":"v.把……归因于","unit":4,"lesson":3,"seq":38,"isStar":false,"memo":"a-(=to)+scribe(写,记)→把……记在某人头上→把……归因于","example":"The famous scientist ascribed his success to hard work. 这位著名的科学家把他的成功归功于努力工作。"},{"id":997,"word":"prescribe","pronunciation":"/prɪ'skraɪb/","meaning":"v.给……开药(开处方);规定","unit":4,"lesson":3,"seq":39,"isStar":false,"memo":"pre-(在前)+scribe(写)→拿药前,(请医生)提前写好处方→给……开药(开处方)","example":"We should all do as the law prescribes. 我们都应该依法办事。","derivative":"prescription /prɪ'skrɪpʃn/ n.处方,药方;(医生开的)处方药"},{"id":998,"word":"prescription","pronunciation":"/prɪ'skrɪpʃn/","meaning":"n.处方,药方;(医生开的)处方药","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":999,"word":"subscribe","pronunciation":"/səb'skraɪb/","meaning":"v.订购;订阅;申请;报名;认购(股份)","unit":4,"lesson":3,"seq":40,"isStar":false,"derivative":"subscriber\nsubscription"},{"id":1000,"word":"subscriber","pronunciation":"/səb'skrabə(r)/","meaning":"n.订阅人;消费者;用户","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":1001,"word":"subscription","pronunciation":"/səb'skrɪpʃn/","meaning":"n.(报刊等的)订阅费;订阅;捐助","unit":4,"lesson":3,"seq":41,"isStar":false},{"id":1002,"word":"script","pronunciation":"/skrɪpt/","meaning":"n.剧本,讲稿;笔迹,手迹 v.写剧本","unit":4,"lesson":3,"seq":42,"isStar":false,"memo":"构词 sub-(下面)+scribe(写)→在下面写(名字、地址)→订购；订阅；报名","example":"We're currently working on a script. 我们目前正在写剧本。"},{"id":1003,"word":"scripture","pronunciation":"/'skrɪptʃə(r)/","meaning":"n.(某宗教的)经文,经籍;《圣经》","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":1004,"word":"manuscript","pronunciation":"/'mænju skrɪpt/","meaning":"n.手稿,原稿;手抄本","unit":4,"lesson":3,"seq":43,"isStar":false,"memo":"构词 manu (= hand) + script (讲稿) → 手写的讲稿 → 手稿，原稿","example":"I read her poems in manuscript. 我读过她的诗作的手稿。"},{"id":1005,"word":"transcript","pronunciation":"/'trænskrɪpt/","meaning":"n.抄本;眷本","unit":4,"lesson":3,"seq":44,"isStar":false},{"id":1006,"word":"manual","pronunciation":"/'mænjuəl/","meaning":"adj.手工的;手动的;体力的 n.说明书,使用手册","unit":4,"lesson":3,"seq":45,"isStar":false,"memo":"构词 manu(手)+-al(后缀)→手工的","example":"They can avoid doing much of the manual labor. 他们可以避免做大量的体力劳动。"},{"id":1007,"word":"manufacture","pronunciation":"/ˌmænju'fæktʃə(r)/","meaning":"v.(用机器)大量生产,成批制造 n.大量制造,批量生产","unit":4,"lesson":3,"seq":46,"isStar":false,"memo":"构词 manu(手)+fact(做)+-ure(后缀)→手工制作→大量生产；成批制造","example":"This company manufactures the equipment used to make contact lenses. 这家公司生产用以制造隐形眼镜片的设备。"},{"id":1008,"word":"manufacturer","pronunciation":"/mænju'fæktərə(r)/","meaning":"n.生产者,制造者,生产商","unit":4,"lesson":3,"seq":47,"isStar":false,"memo":"构词 manufacture(大量生产)+-(e)r(表示人的后缀)→生产者","example":"One British manufacturer accepted this suggestion. 一家英国的制造商接受了这一建议。"},{"id":1009,"word":"mandate","pronunciation":"/'mændet/","meaning":"v.强制执行;授权 n.授权;(政府的)任期;委托书","unit":4,"lesson":3,"seq":48,"isStar":false,"memo":"联想 man(联想“慢”) + date(日期) → 虽然很慢，但他们最终确定了“授权”的日期。","example":"The law mandates that imported goods be identified as such. 法律规定，进口货物必须如实标明。","derivative":"mandatory /'mændətɔːri; mæn'deɪtəri/ adj.强制的；法定的；义务的"},{"id":1010,"word":"mandatory","pronunciation":"/'mændətəri;<br>mæn'deɪtəri/","meaning":"adj.强制的;法定的;义务的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":1011,"word":"emancipate","pronunciation":"/ɪ'mænsɪpeɪt/","meaning":"v.解放;使不受(法律、政治或社会的)束缚","unit":4,"lesson":3,"seq":49,"isStar":false},{"id":1012,"word":"emancipation","pronunciation":"/ɪmænsɪ'peɪʃn/","meaning":"n.解放","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":1013,"word":"manoeuvre/maneuver","pronunciation":"/mə'nuːvə(r)/","meaning":"n.机动动作;策略,手段 v.操纵,控制","unit":4,"lesson":3,"seq":50,"isStar":false},{"id":1014,"word":"affection","pronunciation":"/ə'fekʃn/","meaning":"n.感情;喜爱;爱情","unit":4,"lesson":3,"seq":51,"isStar":false,"memo":"构词 af-(=to) + fect(做) + -ion(名词后缀) → 做某事可能会对其产生“感情”。","example":"People of different ages and genders show affection in different ways. 不同年龄和性别的人表达爱意的方式不同。","derivative":"affectionate /əˈfekʃənət/ adj.表示关爱的"},{"id":1015,"word":"affectionate","pronunciation":"/ə'fekʃənət/","meaning":"adj.表示关爱的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":1016,"word":"facility","pronunciation":"/fə'sɪləti/","meaning":"n.设备,设施;天赋,才能","unit":4,"lesson":3,"seq":52,"isStar":false,"memo":"构词 facil(e)(容易的) + -ity(名词后缀) → 做事容易的能力 → 天赋，才能","example":"Facilities management has greatly improved in recent years. 近年来，设施管理有了很大改善。","derivative":"facilitate /fəˈsɪlɪteɪt/ v.促进，促使；使便利 facilitation /fəˌsɪlɪteɪʃn/ n.促进"},{"id":1017,"word":"facilitate","pronunciation":"/fə'sɪlɪteɪt/","meaning":"v.促进,促使;使便利","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":1018,"word":"facilitation","pronunciation":"/fəsɪlɪ'teɪʃn/","meaning":"n.促进","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":1019,"word":"infect","pronunciation":"/ɪn'fekt/","meaning":"v.传染;影响","unit":4,"lesson":3,"seq":53,"isStar":false,"memo":"构词 in-(入) + fect(做→起作用) → 进入（肌体）起作用 → 传染","example":"Once infected, one will become immune to Ebola. 一旦感染，人们就会对埃博拉病毒产生免疫。","derivative":"infection /ɪnˈfekʃn/ n.传染；（身体某部位的）感染 infectious /ɪnˈfekəs/ adj.传染性的；感染的"},{"id":1020,"word":"infection","pronunciation":"/ɪn'fekʃn/","meaning":"n.传染;(身体某部位的)感染","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":1021,"word":"infectious","pronunciation":"/ɪn'fekʃəs/","meaning":"adj.传染性的;感染的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":1022,"word":"defect","pronunciation":"/'diːfekt/","meaning":"n.缺点,缺陷 /dɪ'fekt/ v.背叛,叛变","unit":4,"lesson":3,"seq":54,"isStar":false,"memo":"联想 de(音似“弟”) + fect(做) → 弟弟年轻，做事不周到，有“缺陷”。","example":"She suffers from a sight defect. 她的视力有缺陷。","derivative":"defective /dɪˈfektɪv/ adj.有缺点的；有缺陷的；有毛病的"},{"id":1023,"word":"defective","pronunciation":"/dɪ'fektv/","meaning":"adj.有缺点的,有缺陷的,有毛病的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":1024,"word":"effect","pronunciation":"/ɪ'fekt/","meaning":"n.生效;效果 v.实现;引起","unit":4,"lesson":3,"seq":55,"isStar":false,"memo":"构词 ef-(出) + fect(做) → 做出来 → 生效；实现","example":"I can certainly feel the effects of too many late nights. 我当然能感觉到熬夜太多产生的影响。","derivative":"effective /ˈfektɪv/ adj.有效的；产生预期效果的"},{"id":1025,"word":"effective","pronunciation":"/ɪ'fektɪv/","meaning":"adj.有效的;产生预期效果的","unit":4,"lesson":3,"seq":0,"isStar":true},{"id":1026,"word":"void","pronunciation":"/vɪd/","meaning":"adj.无效的;缺乏……的 n.空虚感;空白 v.使无效","unit":4,"lesson":3,"seq":56,"isStar":false,"memo":"联想 vo(音似“我”) + id(联想“身份”) → 我的身份是“无效的”，这让我有一种“空虚感”。","example":"The agreement was declared void. 该协议被宣布无效。"},{"id":1027,"word":"fake","pronunciation":"/fek/","meaning":"n.假货;骗子 adj.假的 v.伪造","unit":4,"lesson":4,"seq":1,"isStar":false,"example":"All the paintings proved to be fakes. 所有这些画结果证实都是品。"},{"id":1028,"word":"deceive","pronunciation":"/dɪ'siːv/","meaning":"v.欺骗,误导","unit":4,"lesson":4,"seq":2,"isStar":false,"memo":"[谐音]单词发音类似“弟媳妇”→这部电影里,主角的弟媳妇是个骗子,“欺骗”了弟弟。","example":"If he deceives the world, the world often deceives him. 如果他欺骗世人,那世人往往也会欺骗他。","derivative":"deceit /dˈsiːt/ n.欺骗,欺诈\ndeception /dɪˈsepʃn/ n.欺骗(行为)\ndeceptive /dɪˈseptɪv/ adj.欺骗性的;误导的"},{"id":1029,"word":"deceit","pronunciation":"/dɪ'siːt/","meaning":"n.欺骗,欺诈","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1030,"word":"deception","pronunciation":"/dɪ'sepʃn/","meaning":"n.欺骗(行为)","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1031,"word":"deceptive","pronunciation":"/dɪ'septɪv/","meaning":"adj.欺骗性的;误导的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1032,"word":"perceive","pronunciation":"/pə'si:v/","meaning":"v.看待;察觉,发觉","unit":4,"lesson":4,"seq":3,"isStar":false,"memo":"[谐音]单词发音类似“破媳妇”→他想破坏媳妇的计划,被媳妇“察觉”到了。","example":"I perceived a change in his behaviour. 我注意到他的举止有些改变。","derivative":"perception /pəˈsepʃn/ n.知觉;感知;洞察力;认识,看法\nperceptive /pəˈseptɪv/ adj.理解力强的;有洞察力的;思维敏捷的"},{"id":1033,"word":"perception","pronunciation":"/pə'sepʃn/","meaning":"n.知觉;感知;洞察力;认识,看法","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1034,"word":"perceptive","pronunciation":"/pə'septɪv/","meaning":"adj.理解力强的;有洞察力的;思维敏捷的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1035,"word":"conceive","pronunciation":"/kən'si:v/","meaning":"v.设想,构思;怀孕","unit":4,"lesson":4,"seq":4,"isStar":false,"memo":"[联想] con-(一起) + ceive(音似“媳妇”)→他和媳妇一起“设想”着“怀孕”生子的美好生活。","example":"I cannot conceive what it must be like. 我设想不出它会是什么样子。"},{"id":1036,"word":"conception","pronunciation":"/kən'sepʃn/","meaning":"n.构思,设想;概念","unit":4,"lesson":4,"seq":5,"isStar":false,"memo":"[对照] conceive v.设想→conception n.","example":"I had to reassess my conception that she was basically an honest person. 我不得不重新评估我的想法,她基本上是一个诚实的人。"},{"id":1037,"word":"detect","pronunciation":"/dɪ'tekt/","meaning":"v.发现;查明;侦察出","unit":4,"lesson":4,"seq":6,"isStar":false,"memo":"[联想] de-(往下) + tect(音似“探个它”)→向地下钻孔勘探是为了“查明”地层构造。","example":"The tests are designed to detect the disease early. 这些检查旨在早查出疾病。","derivative":"detection /dɪtekʃn/ n.探测;察觉;发现\ndetective /dɪˈtektɪv/ n.侦探;警探;私人侦探"},{"id":1038,"word":"detection","pronunciation":"/dɪ'tekʃn/","meaning":"n.探测;察觉;发现","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1039,"word":"detective","pronunciation":"/d'tektɪv/","meaning":"n.侦探;警探;私人侦探","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1040,"word":"scout","pronunciation":"/skaʊt/","meaning":"n.侦察员;侦察机(舰) v.搜索,侦察","unit":4,"lesson":4,"seq":7,"isStar":false,"memo":"[联想] sc(联想“死看”) + out(出去)→侦察","example":"Scouts are trained to navigate through the forest. 侦察员被训练穿越森林。"},{"id":1041,"word":"appeal","pronunciation":"/ə'pi:l/","meaning":"n.呼吁,恳求;上诉 v.有吸引力;呼吁;上诉","unit":4,"lesson":4,"seq":8,"isStar":false,"memo":"[联想] ap-(= to) + peal(音同 peel,剥皮)→古代有些贪官污吏被抓起来后，百姓会“恳求”官府将之剥皮。","example":"An appeal is being made for help for those who lost their homes in the earthquake. 人们正在呼吁大家援助那些在地震中失去家园的人。","derivative":"appealing /əpiːlɪŋ/ adj.有吸引力的；令人感兴趣的；恳求的"},{"id":1042,"word":"appealing","pronunciation":"/ə'pi:lŋ/","meaning":"adj.有吸引力的;令人感兴趣的;恳求的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1043,"word":"appal(l)","pronunciation":"/ə'pɔ:l/","meaning":"v.使大为震惊,使惊骇","unit":4,"lesson":4,"seq":9,"isStar":false},{"id":1044,"word":"appalling","pronunciation":"/ə'pɔ:lɪŋ/","meaning":"adj.令人震惊的;极为恶劣的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1045,"word":"accuse","pronunciation":"/ə'kju:z/","meaning":"v.控告,控诉;谴责","unit":4,"lesson":4,"seq":10,"isStar":false,"memo":"[联想] ac-(一再地) + cuse(联想 curse,诅咒)→一再地诅咒他人这种行为应受“谴责”。","example":"He was accused of family violence. 他被指控家庭暴力。","derivative":"accusation /ˌækjuˈzeɪʃn/ n.控告，起诉；告发；谴责"},{"id":1046,"word":"accusation","pronunciation":"/ˌækju'zeɪʃn/","meaning":"n.控告,起诉;告发;谴责","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1047,"word":"blame","pronunciation":"/bleɪm/","meaning":"v.责备,责怪;把……归于 n.责备;(坏事或错事的)责任","unit":4,"lesson":4,"seq":11,"isStar":false,"memo":"[联想] b(音似“不”) + la(联想“拉”) + me(我)→一旦弟弟在马路上乱跑，不想拉着我，我就会“责备”他。","example":"Police are blaming the accident on dangerous driving. 警方把事故原因归咎于危险驾驶。"},{"id":1048,"word":"verdict","pronunciation":"/'vɜ:dkt/","meaning":"n.(法庭作出的)裁定,裁决;决定;意见","unit":4,"lesson":4,"seq":12,"isStar":false,"memo":"[谐音] 单词发音类似“我抵抗它”→我对“裁决”不服，想提起诉讼进行抵抗。","example":"The jury’s verdict went against him. 陪审团的裁决对他不利。"},{"id":1049,"word":"convict","pronunciation":"/kən'vɪkt/","meaning":"v.定罪,证明……有罪 /'kɒnvɪkt/ n.已决犯,服刑囚犯","unit":4,"lesson":4,"seq":13,"isStar":false,"memo":"[联想] con-(共同) + vi(形似罗马数字 6) + ct(联想“剋他”)→六个人都剋(打)了他，证明这六个人都有罪→证明……有罪","example":"He was convicted of fraud. 他被判定犯有诈骗罪。","derivative":"conviction /kənˈvɪkʃn/ n.判罪；坚定的信念\nconvict /ˈkɒnvɪkt/ n.已决犯，服刑囚犯"},{"id":1050,"word":"conviction","pronunciation":"/kən'vɪkn/","meaning":"n.判罪;坚定的信念","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1051,"word":"indict","pronunciation":"/ɪn'daɪt/","meaning":"v.控告,起诉","unit":4,"lesson":4,"seq":14,"isStar":false,"memo":"in(里面)+dict(说)→咱们进法庭里说,我要“控告”你。","example":"They were indicted on a number of corruption charges. 他们被控多项贪腐罪名。","derivative":"indictment /nˈdaɪtmənt/ n.控告;衰败迹象"},{"id":1052,"word":"indictment","pronunciation":"/ɪnˈdaɪtmənt/","meaning":"n.控告;衰败迹象","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1053,"word":"guilt","pronunciation":"/ɡɪlt/","meaning":"n.内疚;犯罪,罪行","unit":4,"lesson":4,"seq":15,"isStar":false},{"id":1054,"word":"guilty","pronunciation":"/ˈɡɪlti/","meaning":"adj.内疚的;有罪责的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1055,"word":"crime","pronunciation":"/kraɪm/","meaning":"n.犯罪,犯罪行为","unit":4,"lesson":4,"seq":16,"isStar":false,"memo":"cri(音同 cry)+me(我)→那个罪犯被审判的时候向我痛哭流涕,悔恨他的“犯罪行为”。","example":"Stores spend more and more on crime prevention. 商店在防止犯罪方面的花费越来越多。","derivative":"criminal /'krɪmɪnl/ n.罪犯,犯罪者 adj.犯罪的,犯法的"},{"id":1056,"word":"criminal","pronunciation":"/ˈkrɪmɪnl/","meaning":"n.罪犯,犯罪者 adj.犯罪的,犯法的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1057,"word":"discriminate","pronunciation":"/dɪˈskrɪmɪneɪt/","meaning":"v.区分,辨别;歧视;偏袒","unit":4,"lesson":4,"seq":17,"isStar":false,"memo":"dis-(分开)+crimin(区别)+-ate(动词后缀)→区分,辨别","example":"Newborn babies can discriminate between a man's and a woman's voice. 新生儿能辨别男人和女人的声音。","derivative":"discrimination /dɪˌskrɪmɪ'neʃn/ n.区别对待;歧视;辨别力\ndiscriminatory /dɪ'skrɪmɪnətəri/ adj.区别对待的;不公正的;歧视的"},{"id":1058,"word":"discrimination","pronunciation":"/dˌskrɪmɪˈneɪʃn/","meaning":"n.区别对待;歧视;辨别力","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1059,"word":"discriminatory","pronunciation":"/dɪˈskrɪmnətəri/","meaning":"adj.区别对待的;不公正的;歧视的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1060,"word":"prison","pronunciation":"/ˈprɪzn/","meaning":"n.监狱,牢笼;监禁","unit":4,"lesson":4,"seq":18,"isStar":false,"example":"He was sent to prison for five years. 他被关押了五年。","derivative":"prisoner /'prɪznə(r)/ n.囚犯,犯人;羁押候审者"},{"id":1061,"word":"prisoner","pronunciation":"/ˈprɪznə(r)/","meaning":"n.囚犯,犯人;羁押候审者","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1062,"word":"imprison","pronunciation":"/ɪmˈprɪzn/","meaning":"v.监禁,关押;束缚","unit":4,"lesson":4,"seq":19,"isStar":false,"memo":"im-(= in,入)+prison(监狱)→监禁;关押","example":"He was wrongly imprisoned. 他被判入狱是冤枉的。","derivative":"imprisonment /ɪm'prɪznmənt/ n.监禁"},{"id":1063,"word":"imprisonment","pronunciation":"/ɪmˈprɪznmənt/","meaning":"n.监禁","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1064,"word":"blackmail","pronunciation":"/ˈblækmeɪl/","meaning":"n. & v.勒索,敲诈;胁迫","unit":4,"lesson":4,"seq":20,"isStar":false,"memo":"black(黑色的)+mail(邮件)→黑色的邮件不要打开,可能被“敲诈”。","example":"She says she was virtually blackmailed into giving up her claim to the property. 她说自己实际上是受人胁迫而放弃了财产所有权。"},{"id":1065,"word":"kidnap","pronunciation":"/ˈkɪdnæp/","meaning":"v. & n.劫持;绑架","unit":4,"lesson":4,"seq":21,"isStar":false},{"id":1066,"word":"hijack","pronunciation":"/ˈhadʒæk/","meaning":"v.劫持;操纵","unit":4,"lesson":4,"seq":22,"isStar":false,"example":"The airliner was hijacked by a group of terrorists. 该客机被一帮恐怖分子劫持。"},{"id":1067,"word":"hack","pronunciation":"/hæk/","meaning":"n.砍,劈;入侵 v.砍,劈;非法侵入(他人的计算机系统)","unit":4,"lesson":4,"seq":23,"isStar":false,"memo":"谐音 单词发音类似“黑客”→电脑黑客就是“非法侵入”他人计算机系统的人。","example":"The order essentially asks Apple to hack its own devices. 该命令本质上是要求苹果公司入侵自己的设备。","derivative":"hacker /ˈhækə(r)/ n.黑客\ndatabase /ˈdeɪtəbes/ n.(储存在计算机中的)数据库"},{"id":1068,"word":"hacker","pronunciation":"/ˈhækə(r)/","meaning":"n.黑客","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1069,"word":"database","pronunciation":"/ˈdeɪtəbes/","meaning":"n.(储存在计算机中的)数据库","unit":4,"lesson":4,"seq":24,"isStar":false},{"id":1070,"word":"smuggle","pronunciation":"/ˈsmʌɡl/","meaning":"v.走私,偷运","unit":4,"lesson":4,"seq":25,"isStar":false,"memo":"谐音 单词发音类似“私马哥”→“走私”马匹的哥哥被逮捕了。","example":"He was caught smuggling diamonds into the country. 他走私钻石入境时被发现了。","derivative":"smuggler /smʌɡlə(r)/ n.走私者\nsmuggling /ˈsmʌɡlɪŋ/ n.走私(罪)"},{"id":1071,"word":"smuggler","pronunciation":"/ˈsmʌɡlə(r)/","meaning":"n.走私者","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1072,"word":"smuggling","pronunciation":"/ˈsmʌɡlɪŋ/","meaning":"n.走私(罪)","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1073,"word":"rob","pronunciation":"/rɒb/","meaning":"v.抢劫,掠夺;盗取","unit":4,"lesson":4,"seq":26,"isStar":false,"memo":"谐音 单词发音类似“弱不”→弱不禁风的她遭到了“抢劫”。","example":"The tomb has been robbed of its treasures. 这座坟墓里的财宝早已被盗。","derivative":"robbery /ˈrɒbəri/ n.盗窃;抢劫,掠夺"},{"id":1074,"word":"robbery","pronunciation":"/'rɒbəri/","meaning":"n.盗窃;抢劫,掠夺","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1075,"word":"grab","pronunciation":"/græb/","meaning":"n.抓取;抢夺 v.抓住;攫取","unit":4,"lesson":4,"seq":27,"isStar":false,"memo":"联想 g(联想“哥”) + rab(联想 rob) → 抢劫哥哥的人被“抓住”了。","example":"You should grab this chance. 你应该抓住这次机会。"},{"id":1076,"word":"snatch","pronunciation":"/snætʃ/","meaning":"n.抓;抢夺 v.一把抓起;一下夺过","unit":4,"lesson":4,"seq":28,"isStar":false,"memo":"谐音 单词发音类似“死拿吃”→拼死也要拿来吃→抢夺","example":"She managed to snatch the gun from his hand. 她设法从他手里夺过了枪。"},{"id":1077,"word":"snap","pronunciation":"/snæp/","meaning":"n.(尤指关上或断裂的声音)啪嗒声,咔嚓声 v.拍照;(使)断裂 adj.仓促的","unit":4,"lesson":4,"seq":29,"isStar":false,"memo":"谐音 单词发音类似“四男扑”→四个小男孩突然扑过去抢木棍,把木棍弄断了→仓促的;使断裂","example":"After she snapped a photo and started using her phone, he asked her a serious question. 在她拍了一张照片并开始看手机后,他问了她一个严肃的问题。"},{"id":1078,"word":"penalty","pronunciation":"/'penəlti/","meaning":"n.惩罚,处罚;害处","unit":4,"lesson":4,"seq":30,"isStar":false,"memo":"联想 pena (音似“拍那”) + l + ty (音似“提”) → 这架飞机上是不允许拍这拍那的,经提醒后不改的乘客会受到“处罚”。","example":"The penalty for travelling without a ticket is £200. 无票乘车的罚款为 200 英镑。","derivative":"penalise/-ize /ˈpiːnəlaɪz/ v.惩罚,(体育运动中的)判罚"},{"id":1079,"word":"penalise/-ize","pronunciation":"/'piːnəlaɪz/","meaning":"v.惩罚,(体育运动中的)判罚","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1080,"word":"sue","pronunciation":"/suː/","meaning":"v.控告;提起诉讼","unit":4,"lesson":4,"seq":31,"isStar":false,"memo":"谐音 单词发音类似“诉”→提起诉讼","example":"These injured workers could sue for damages in a court of law. 这些受伤的工人可以在法庭上提起赔偿诉讼。"},{"id":1081,"word":"ensue","pronunciation":"/n'sjuː/","meaning":"v.接着发生;因而产生","unit":4,"lesson":4,"seq":32,"isStar":false,"memo":"联想 en-(使)+sue(提起诉讼)→他提起诉讼后,“接着发生”了很多事情。","example":"An argument ensued. 紧接着的是一场争论。"},{"id":1082,"word":"lawsuit","pronunciation":"/'lɔːsuːt/","meaning":"n.诉讼,起诉","unit":4,"lesson":4,"seq":33,"isStar":false,"example":"His lawyer filed a lawsuit against the airline. 他的律师对该航空公司提起了诉讼。"},{"id":1083,"word":"prove","pronunciation":"/pruːv/","meaning":"v.证明,证实;显示","unit":4,"lesson":4,"seq":34,"isStar":false,"memo":"联想 pro-(向前)+ve(音似“五”)→要向前推进这件事,需要先“证实”这五点。","example":"What are you trying to prove? 你想证明什么?"},{"id":1084,"word":"proof","pronunciation":"/pruːf/","meaning":"n.证据;证明 adj.能抵御的,能防范的 v.把(某材料)作防水(油)处理","unit":4,"lesson":4,"seq":35,"isStar":false,"memo":"对照 prove v.证明→proof n.&adj.&v.","example":"So far, there is little proof one way or the other."},{"id":1085,"word":"approve","pronunciation":"/ə'pruːv/","meaning":"v.赞成,同意;批准","unit":4,"lesson":4,"seq":36,"isStar":false,"memo":"构词 ap-(=to)+prove(证明)→对……出具证明→赞成,批准","example":"Do you approve of my idea? 你赞成我的想法吗?","derivative":"approval /əˈpruːvl/ n.赞成;同意;批准"},{"id":1086,"word":"approval","pronunciation":"/ə'pruvl/","meaning":"n.赞成,同意;批准","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1087,"word":"sanction","pronunciation":"/'sæŋkn/","meaning":"n.批准,同意;制裁 v.批准,同意","unit":4,"lesson":4,"seq":37,"isStar":false,"memo":"联想 sanc(音似“赛课”)+tion(名词后缀)→学校里开展课程比赛要经过校领导的“批准”。","example":"The economic sanctions have been lifted. 经济制裁已被解除。"},{"id":1088,"word":"testimony","pronunciation":"/'testɪməni/","meaning":"n.证据;(尤指法庭上的)证词","unit":4,"lesson":4,"seq":38,"isStar":false,"memo":"联想 test(检验)+i+mony(音似“摸你”)→我摸你的衣兜是为了检验他的“证词”是否正确。","example":"This increase in exports bears testimony to the successes of industry. 出口增长证明了产业的成功。"},{"id":1089,"word":"testify","pronunciation":"/'testɪfaɪ/","meaning":"v.(尤指出庭)作证,证明","unit":4,"lesson":4,"seq":39,"isStar":false,"memo":"testi（test测试/证据）+fy（使…）→‘使成证据’！法庭上举手说‘I swear to tell the truth’就是在用生命‘作证’，test=试真伪，fy=搞定。","example":"She testified that she saw the suspect near the scene. 她作证称曾在案发现场附近看到嫌疑人。","derivative":"testimony /ˈtestɪmənɪ/ n. 证词；证据"},{"id":1090,"word":"witness","pronunciation":"/'wɪtnəs/","meaning":"n.证人,目击者;证据 v.目击;为……作证","unit":4,"lesson":4,"seq":40,"isStar":false,"memo":"对照:证人(witness)需要有一定的智力(wit)水平。","example":"Many factors influence the accuracy of witness testimony. 许多因素影响目击者证词的准确性。"},{"id":1091,"word":"evidence","pronunciation":"/'evɪdəns/","meaning":"n.证据;迹象","unit":4,"lesson":4,"seq":41,"isStar":false,"memo":"构词:e-(出)+vid(看)+-ence(名词后缀)→(从……中)看得出来的东西→证据;迹象","example":"Have you any evidence to support this allegation? 你有证据支持这种说法吗?","derivative":"evident /'evɪdənt/ adj.明显的,显然的"},{"id":1092,"word":"evident","pronunciation":"/'evdənt/","meaning":"adj.明显的,显然的","unit":4,"lesson":4,"seq":0,"isStar":true,"memo":"构词：e-（出）+ vid-（看，如video）+ -ent→一眼‘看出’来的东西，就是‘明显的’！Evident=eye-vident！","example":"It is evident that climate change affects agricultural output. 显然，气候变化影响农业产量。","derivative":"evidence /'evɪd(ə)ns/ n.证据"},{"id":1093,"word":"rebel","pronunciation":"/'rebl/","meaning":"n.反叛者 /rɪ'bel/ v.造反;反抗;背叛","unit":4,"lesson":4,"seq":42,"isStar":false,"memo":"联想:re-(再次)+bel(联想bell)→警铃再次响了,警察抓到了反复闹事的“反叛者”。","example":"The teenager finds something to rebel against. 那个青少年有反抗意识。","derivative":"rebellion /rɪ'beljən/ n.叛乱;反抗 rebellious /rɪ'beljəs/ adj.反叛的;叛逆的;桀骜不驯的"},{"id":1094,"word":"rebellion","pronunciation":"/rɪ'beljən/","meaning":"n.叛乱;反抗","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1095,"word":"rebellious","pronunciation":"/rɪ'beljəs/","meaning":"adj.反叛的;叛逆的;骜不驯的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1096,"word":"valid","pronunciation":"/'vælıd/","meaning":"adj.有效的;合理的,正当的","unit":4,"lesson":4,"seq":43,"isStar":false,"memo":"谐音:单词发音类似“玩累的”→娃玩了一整天累了,休息一下是“合理的”。","example":"Some of the answers to the questionnaire were not valid. 问卷中的一些答案是无效的。","derivative":"validity /və'lɪdəti/ n.有效;合法性;(正式的)认可 validate /'vældeɪt/ v.证实;使生效;使合法化;使得到认同"},{"id":1097,"word":"validity","pronunciation":"/və'lıdətı/","meaning":"n.有效;合法性;(正式的)认可","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1098,"word":"validate","pronunciation":"/'vælıdeıt/","meaning":"v.证实;使生效;使合法化;使得认同","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1099,"word":"invalid","pronunciation":"/ın'vælıd/","meaning":"adj.无效的;站不住脚的 /'ınvəlɪd/ n.病弱者","unit":4,"lesson":4,"seq":44,"isStar":false,"memo":"构词:in-(否定前缀)+valid(有效的)→无效的","example":"The trial was stopped and the results declared invalid. 审判被终止了,其结果被宣布无效。"},{"id":1100,"word":"legal","pronunciation":"/'li:gl/","meaning":"adj.与法律有关的;合法的","unit":4,"lesson":4,"seq":45,"isStar":false,"memo":"单词发音类似“立个”→立个法律→与法律有关的：合法的","example":"They emphasise parents’ legal responsibilities. 他们强调父母的法律责任。","derivative":"legalise/-ize /'liːɡəlaz/ v.使合法化"},{"id":1101,"word":"legalise/-ize","pronunciation":"/'li:gəlaız/","meaning":"v.使合法化","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1102,"word":"illegal","pronunciation":"/ı'li:gl/","meaning":"adj.不合法的,非法的n.非法移民;非法劳工","unit":4,"lesson":4,"seq":46,"isStar":false,"memo":"il-(否定前缀) + legal(合法的) → 不合法的；非法的","example":"The deal may be ruled illegal. 这笔交易可能会被判定为非法。"},{"id":1103,"word":"legitimate","pronunciation":"/lı'dʒıtımeıt/","meaning":"adj.正当合理的;合法的","unit":4,"lesson":4,"seq":47,"isStar":false,"memo":"leg (= law) + iti + mate(伙伴) → 他学法律的伙伴教育他要做“合法的”事。","example":"It seemed a perfectly legitimate question. 这似乎是完全合乎情理的问题。","derivative":"legitimacy /lɪ'dʒɪtɪməsi/ n.合法性"},{"id":1104,"word":"legitimacy","pronunciation":"/lı'dʒıtıməsi/","meaning":"n.合法性","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1105,"word":"legislate","pronunciation":"/'ledʒısleıt/","meaning":"v.制定法律,立法","unit":4,"lesson":4,"seq":48,"isStar":false},{"id":1106,"word":"legislation","pronunciation":"/ledʒıs'leın/","meaning":"n.法律;立法","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1107,"word":"legislator","pronunciation":"/'ledʒısleıtə(r)/","meaning":"n.立法委员","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1108,"word":"legislative","pronunciation":"/'ledʒıslətıv/","meaning":"adj.立法的,制定法律的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1109,"word":"enact","pronunciation":"/ı'nækt/","meaning":"v.扮演;通过(法律);实施","unit":4,"lesson":4,"seq":49,"isStar":false},{"id":1110,"word":"enactment","pronunciation":"/ı'næktmənt/","meaning":"n.(法律的)制定,颁布;法律","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1111,"word":"execute","pronunciation":"/'eksıkju:t/","meaning":"v.(尤指依法)处决;执行","unit":4,"lesson":4,"seq":50,"isStar":false,"memo":"ex-(往外) + e + cute(可爱的) → 这个看似可爱的人实际上是个罪犯，大家要求把他拉出去“处决”。","example":"Check whether the computer has executed your commands. 检查一下计算机是否已执行你的指令。","derivative":"execution /ˌeksɪ'kjuːʃn/ n.处决；实施"},{"id":1112,"word":"execution","pronunciation":"/ˌeksı'kju:ʃn/","meaning":"n.处决;实施","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1113,"word":"executive","pronunciation":"/ıg'zekjətıv/","meaning":"n.经理,主管;行政领导adj.行政的,管理的","unit":4,"lesson":4,"seq":51,"isStar":false,"memo":"execute v.(尤指依法)处决；执行 → executive n. & adj.","example":"The chief executive officer of a corporation is held responsible for the mistake made by its subsidiaries. 公司的首席执行官要为其子公司所犯的错误负责。"},{"id":1114,"word":"persecute","pronunciation":"/'pɜ:sıkju:t/","meaning":"v.迫害,残害;骚扰","unit":4,"lesson":4,"seq":52,"isStar":false,"memo":"per-(始终，完全) + secute(跟随) → 始终跟随(并加以伤害) → 迫害，残害；骚扰","example":"Vic was persecuted by the media. 维克受到媒体的纠缠。","derivative":"persecution /pɜːsɪ'kjuːʃn/ n.迫害，残害；骚扰"},{"id":1115,"word":"persecution","pronunciation":"/ˌpɜ:sı'kju:ʃn/","meaning":"n.迫害,残害;骚扰","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1116,"word":"prosecute","pronunciation":"/'prsıkju:t/","meaning":"v.起诉,控告;检举","unit":4,"lesson":4,"seq":53,"isStar":false},{"id":1117,"word":"prosecution","pronunciation":"/ˌprɒsı'kju:ʃn/","meaning":"n.(被)起诉,检举,诉讼;原告","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1118,"word":"sequence","pronunciation":"/'si:kwəns/","meaning":"n.一系列;顺序,次序 v.按顺序排列","unit":4,"lesson":4,"seq":54,"isStar":false,"memo":"联想 set(联想 see) + quen(联想 queen) + ce(走)→他看见女王后面的人在有“顺序”地排队往前走。","example":"Spider-Man is a sequence of stories.《蜘蛛侠》是系列故事。","derivative":"sequential /sɪˈkwnʃl/ adj.按次序的;顺序的;序列的"},{"id":1119,"word":"sequential","pronunciation":"/sɪ'kwenʃl/","meaning":"adj.按次序的,顺序的;序列的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1120,"word":"consequence","pronunciation":"/'kɒnsɪkwəns/","meaning":"n.结果,后果;重要性","unit":4,"lesson":4,"seq":55,"isStar":false,"memo":"构词 con-(一起) + sequence(连续)→一起连续发生的事→结果","example":"Focusing on output alone can have unintended consequences. 只关注产出可能会产生意想不到的后果。","derivative":"consequent /'kɒnskwənt/ adj.随之发生的;作为结果的\nconsequently /'kɒnsɪkwəntli/ adv.因此;所以"},{"id":1121,"word":"consequent","pronunciation":"/'kɒnsɪkwənt/","meaning":"adj.随之发生的;作为结果的","unit":4,"lesson":4,"seq":0,"isStar":true,"memo":"【构词】con-(一起)+sequ-(跟随)+ent→事情一跟到底→自然随之而来的结果。","example":"Heavy rainfall was a consequent cause of the widespread flooding. 大雨是此次大面积洪涝的直接原因。","derivative":"consequently /kənˈsekventli/ adv.因此；所以"},{"id":1122,"word":"consequently","pronunciation":"/'kɒnsɪkwəntli/","meaning":"adv.因此,所以","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1123,"word":"subsequent","pronunciation":"/'sʌbsɪkwənt/","meaning":"adj.随后的;后来的","unit":4,"lesson":4,"seq":56,"isStar":false,"memo":"构词 sub-(下面) + sequent(连续的)→下面连续的→随后的;后来的","example":"More on this study will appear in a subsequent post. 关于这项研究的更多信息将出现在随后的帖子中。"},{"id":1124,"word":"judge","pronunciation":"/dʌdʒ/","meaning":"n.法官;裁判员;鉴定人 v.判断,断定","unit":4,"lesson":4,"seq":57,"isStar":false,"example":"The judge reversed his original decision. 法官推翻了他原来的判决。","derivative":"judg(e)ment /'dʌdʒmənt/ n.判断力;看法;裁决"},{"id":1125,"word":"judg(e)ment","pronunciation":"/'dʌdʒmənt/","meaning":"n.判断力;看法;裁决","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1126,"word":"judicial","pronunciation":"/dʒu:'dɪl/","meaning":"adj.审判的;法庭的,法官的;司法的","unit":4,"lesson":4,"seq":58,"isStar":false},{"id":1127,"word":"justice","pronunciation":"/'dʒʌstɪs/","meaning":"n.公平;正义;司法制度;审判","unit":4,"lesson":4,"seq":59,"isStar":false,"memo":"构词 just(公正的) + -ice(名词后缀)→公平;正义","example":"Children often have a highly developed sense of justice. 孩子们通常有高度发达的正义感。"},{"id":1128,"word":"justify","pronunciation":"/'dʒʌstɪfaɪ/","meaning":"v.证明……是正当的;为……辩护","unit":4,"lesson":4,"seq":60,"isStar":false,"memo":"构词 just(公正的) + -ify(动词后缀)→使公正→证明……是正当的","example":"He must justify the arrests he makes of criminals. 他必须证明他逮捕罪犯是正当的。"},{"id":1129,"word":"justification","pronunciation":"/dʒʌstɪfɪ'keɪʃn/","meaning":"n.正当理由","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1130,"word":"adjust","pronunciation":"/ə'dʌst/","meaning":"v.适应;调整,调节;(使)习惯","unit":4,"lesson":4,"seq":61,"isStar":false,"memo":"构词 ad-(= to) + just (正好) → 使……达到正好→调整","example":"America is a competitive society; the kids need to adjust to that. 美国是一个竞争激烈的社会；孩子们需要适应这一点。","derivative":"adjustment n. 调整，调节；适应"},{"id":1131,"word":"adjustment","pronunciation":"/ə'dʌstmənt/","meaning":"n.调整,调节;适应","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1132,"word":"court","pronunciation":"/kɔ:t/","meaning":"n.法院,法庭;球场 v.讨好,争取;招致;恋爱","unit":4,"lesson":4,"seq":62,"isStar":false,"example":"Some witnesses failed to appear in court. 一些证人未能出庭。"},{"id":1133,"word":"courtesy","pronunciation":"/'kɜ:təsi/","meaning":"n.礼貌,彬彬有礼 adj.(公司)免费提供的;礼节性的","unit":4,"lesson":4,"seq":63,"isStar":false,"memo":"联想 court(法庭) + (e)sy(音似 say) → 他在法庭上讲话时很有“礼貌”。","example":"My job title made people treat me with courtesy. 我的职位头衔让人们对我以礼相待。","derivative":"adj.(公司)免费提供的；礼节性的"},{"id":1134,"word":"jury","pronunciation":"/'dʒʊəri/","meaning":"n.陪审团","unit":4,"lesson":4,"seq":64,"isStar":false,"example":"The defending lawyer made a great impression on the jury. 辩护律师给陪审团留下了深刻的印象。","derivative":"juror n.陪审团成员；陪审员"},{"id":1135,"word":"juror","pronunciation":"/'dʒərə(r)/","meaning":"n.陪审团成员;陪审员","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1136,"word":"judiciary","pronunciation":"/dʒu:'dʃəri/","meaning":"n.审判人员;司法部门;司法系统","unit":4,"lesson":4,"seq":65,"isStar":false},{"id":1137,"word":"jurisdiction","pronunciation":"/ˌdʒʊərɪs'dɪkʃn/","meaning":"n.司法权,审判权;管辖权;管辖范围","unit":4,"lesson":4,"seq":66,"isStar":false},{"id":1138,"word":"outlaw","pronunciation":"/'aʊtlɔ:/","meaning":"v.宣布……不合法,使……成为非法 n.亡命徒,逃犯","unit":4,"lesson":4,"seq":67,"isStar":false},{"id":1139,"word":"attorney","pronunciation":"/ə'tɜːni/","meaning":"n.律师;代理人","unit":4,"lesson":4,"seq":68,"isStar":false,"memo":"谐音 单词发音类似“额托你”→在遇到法律难题时，他着急地对一位“律师”说：“额（我）把这件事托付给你了。”","example":"Acting on the advice of his attorney, he remained silent. 按照律师的建议，他保持了沉默。"},{"id":1140,"word":"entrust","pronunciation":"/ɪn'trʌst/","meaning":"v.委托，托付","unit":4,"lesson":4,"seq":69,"isStar":false},{"id":1141,"word":"trial","pronunciation":"/'traɪəl/","meaning":"n.审判；试验，试用 v.测试，试验","unit":4,"lesson":4,"seq":70,"isStar":false,"memo":"对照 审判(trial)就是在试图(try)确定被告人有罪。","example":"We learn, in a sense, by trial and error. 从某种意义上说，我们是通过反复实验来学习的。","derivative":"v.测试，试验"},{"id":1142,"word":"condemn","pronunciation":"/kən'dem/","meaning":"v.谴责；宣判；证明……有罪","unit":4,"lesson":4,"seq":71,"isStar":false,"memo":"联想 con-(所有的) + demn(音似 damn,骂)→所有人都骂他,“谴责”他。","example":"The president condemns their greed. 总统谴责了他们的贪婪。","derivative":"condemnation /ˌkɒndemˈneɪʃn/ n.谴责;指责"},{"id":1143,"word":"condemnation","pronunciation":"/kɒndem'neʃn/","meaning":"n.谴责；指责","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1144,"word":"warrant","pronunciation":"/'wɒrənt/","meaning":"n.授权令；许可；正当理由 v.需要；值得；保证（某物是真的）","unit":4,"lesson":4,"seq":72,"isStar":false,"memo":"联想 war(战争) + r + ant(蚂蚁)→动物大战中,蚂蚁有“授权令”。","example":"Further investigation is clearly warranted. 进一步调查显然是必要的。","derivative":"warranty /ˈwɒrənti/ n.(商品)保用卡,保修单"},{"id":1145,"word":"warranty","pronunciation":"/'wɒrənti/","meaning":"n.（商品）保用卡，保修单","unit":4,"lesson":4,"seq":73,"isStar":false,"memo":"谐音：'沃兰蒂'→'我烂了？它保你！' 保修单就是厂家拍胸脯说'我烂了？它保你！'的契约小纸条。","example":"The laptop comes with a two-year manufacturer's warranty. 这台笔记本附带厂商提供的两年保修服务。","derivative":"warrant /'wɒr(ə)nt/ v.保证；授权"},{"id":1146,"word":"tenant","pronunciation":"/'tenənt/","meaning":"n.房客；租户；佃户","unit":4,"lesson":4,"seq":74,"isStar":false,"memo":"联想 ten(十) + ant(蚂蚁)→十个像蚂蚁一样生活忙碌的低收入者是他的“租户”。","example":"The decorating was done by a previous tenant. 装修是一位前房客搞的。"},{"id":1147,"word":"abundant","pronunciation":"/ə'bʌndənt/","meaning":"adj.大量的，充裕的","unit":4,"lesson":4,"seq":75,"isStar":false,"memo":"联想 a(一) + bund(音似“帮的”) + ant(蚂蚁)→一大帮蚂蚁→大量的","example":"It filled its stores with abundant supply of merchandise. 它商店的商品备货充足。","derivative":"abundance /əbʌndəns/ n.大量,充裕"},{"id":1148,"word":"abundance","pronunciation":"/ə'bʌndəns/","meaning":"n.大量，充裕","unit":4,"lesson":4,"seq":76,"isStar":false},{"id":1149,"word":"ample","pronunciation":"/'æmpl/","meaning":"adj.足够的，丰裕的；硕大的","unit":4,"lesson":4,"seq":77,"isStar":false,"memo":"对照 苹果(apple)在这里并不是稀有水果,大众吃是足够的(ample)。","example":"Let's produce ample food and clothing with our own hands. 让我们用自己的双手生产出足够多的食物和衣服。"},{"id":1150,"word":"sample","pronunciation":"/'sɑːmpl/","meaning":"n.样本，样品 v.抽样检验；取样；尝试，体验","unit":4,"lesson":4,"seq":78,"isStar":false,"memo":"联想 我们要简单(simple)测试一下这批机器的样品(sample)。","example":"Women in our sample tend to over-perceive their weight. 我们样本中的女性往往会过度关注自己的体重。"},{"id":1151,"word":"scarce","pronunciation":"/skeəs/","meaning":"adj.缺乏的，稀少的","unit":4,"lesson":4,"seq":79,"isStar":false,"example":"Details of the accident are scarce. 事故的详细情况了解不多。","derivative":"scarcely /'skeəsli/ adv.勉强;刚;几乎不;简直不\nscarcity /'skeəsəti/ n.缺乏,稀少"},{"id":1152,"word":"scarcely","pronunciation":"/'skeəslɪ/","meaning":"adv.勉强；刚；几乎不；简直不","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1153,"word":"scarcity","pronunciation":"/'skeəsətɪ/","meaning":"n.缺乏，稀少","unit":4,"lesson":4,"seq":80,"isStar":false},{"id":1154,"word":"carton","pronunciation":"/'kɑtn/","meaning":"n.（尤指装食品或液体的）硬纸盒，塑料罐；硬纸盒（或塑料盒）所装物品","unit":4,"lesson":4,"seq":81,"isStar":false},{"id":1155,"word":"scar","pronunciation":"/skɑː(r)/","meaning":"n.伤疤，伤痕 v.在……上结疤","unit":4,"lesson":4,"seq":82,"isStar":false,"memo":"联想 s(联想“死”)+car(车)→他从车下死里逃生,但是留下了“伤疤”。","example":"Will the operation leave a scar? 手术会不会留下疤痕?"},{"id":1156,"word":"quantity","pronunciation":"/'kwɒntətɪ/","meaning":"n.数量；众多","unit":4,"lesson":4,"seq":83,"isStar":false,"example":"African or small island states produce a very small quantity of emissions. 非洲或小岛屿国家产生的排放量非常少。","derivative":"quantitative /'kwntɪtətɪv/ adj.数量的;量化的;定量的"},{"id":1157,"word":"quantitative","pronunciation":"/'kwɒntɪtətɪv/","meaning":"adj.数量的；量化的；定量的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1158,"word":"quality","pronunciation":"/'kwɒlətɪ/","meaning":"n.质量，品质","unit":4,"lesson":4,"seq":84,"isStar":false,"example":"The quality of air will surely change for the better. 空气质量肯定会变得更好。","derivative":"qualitative /'kwɒlɪtətɪv/ adj.质量的;定性的;性质的"},{"id":1159,"word":"qualitative","pronunciation":"/'kwɒlɪtətɪv/","meaning":"adj.质量的；定性的，性质的","unit":4,"lesson":4,"seq":0,"isStar":true},{"id":1160,"word":"ascertain","pronunciation":"/ˌæsə'teɪn/","meaning":"v.查明,弄清","unit":5,"lesson":1,"seq":1,"isStar":false,"memo":"[构词] as-(一再地) + certain(确定)→一再地确定某件事→查明，弄清","example":"We shall probably never be able to ascertain the exact nature of it. 我们可能永远无法弄清它的确切性质。"},{"id":1161,"word":"certify","pronunciation":"/'sɜːtɪfaɪ/","meaning":"v.(尤指书面)证明,证实","unit":5,"lesson":1,"seq":2,"isStar":false,"memo":"[联想] cert(联想certain) + -ify(动词后缀) →使确定→证明，证实","example":"The plants must be certified to be virus free. 这些植物必须具备无病毒证明。"},{"id":1162,"word":"certificate","pronunciation":"/sə'tɪfɪkət/","meaning":"n.证明(书);(毕业)文凭;合格证书","unit":5,"lesson":1,"seq":3,"isStar":false,"memo":"[对照] 合格证书(certificate)是能证明(certify)一个人部分能力的东西。","example":"They're in preparation for exams like the Cambridge Certificates. 他们在为剑桥证书等考试做准备。","derivative":"certification /ˌsɜːrtɪfɪˈkeɪʃn/ n.证明;鉴定"},{"id":1163,"word":"certification","pronunciation":"/ˌsɜːtfɪ'keɪn/","meaning":"n.证明;鉴定","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1164,"word":"diploma","pronunciation":"/dɪ'pləʊmə/","meaning":"n.文凭课程;毕业文凭","unit":5,"lesson":1,"seq":4,"isStar":false,"example":"She is taking a diploma in management studies. 她在攻读管理学文凭课程。","derivative":"diplomat /ˈdɪpləmæt/ n.外交官;善于交际的人,圆通的人\ndiplomatic /ˌdɪpləˈmætɪk/ adj.外交的;有手腕的;圆通的\ndiplomacy /dˈploʊməsi/ n.外交;外交技巧;外交手腕"},{"id":1165,"word":"thesis","pronunciation":"/'θiːsɪs/","meaning":"n.论文,毕业论文;论题","unit":5,"lesson":1,"seq":5,"isStar":false,"memo":"[联想] the(这,那) + s(联想“蛇”) + i(形似一个人) + s(联想“蛇”)→那个学生写了一篇人与蛇的“论文”。","example":"The basic thesis of the book is fairly simple. 这本书的基本论题相当简单。"},{"id":1166,"word":"diplomat","pronunciation":"/'dɪpləmæt/","meaning":"n.外交官;善于交际的人,圆通的人","unit":5,"lesson":1,"seq":6,"isStar":false},{"id":1167,"word":"diplomatic","pronunciation":"/ˌdɪplə'mætɪk/","meaning":"adj.外交的;有手腕的;圆通的","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1168,"word":"diplomacy","pronunciation":"/d'pləʊməsi/","meaning":"n.外交;外交技巧;外交手腕","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1169,"word":"verify","pronunciation":"/'verɪfaɪ/","meaning":"v.核实,证实,证明","unit":5,"lesson":1,"seq":7,"isStar":false,"memo":"联想 veri(联想 very,恰好的) + fy(联想“反应”)→恰好他反应快,“证明”了自己。","example":"They need the facts to verify the existence of a black hole. 他们需要证实黑洞存在的事实。","derivative":"verification /ˌverɪfɪ'keɪʃn/ n.核实;查对;核准"},{"id":1170,"word":"verification","pronunciation":"/ˌverɪfɪ'keɪʃn/","meaning":"n.核实;查对;核准","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1171,"word":"rectify","pronunciation":"/'rektɪfaɪ/","meaning":"v.矫正,纠正,改正","unit":5,"lesson":1,"seq":8,"isStar":false,"memo":"联想 rect(联想 correct) + -ify(动词后缀)→使正确→矫正,纠正","example":"I hope that everyone in this class should rectify their errors before it is too late. 我希望这个班上的每个人都能趁早改正他们的错误。","derivative":"rectification /ˌrektɪfɪ'keɪʃn/ n.纠正"},{"id":1172,"word":"rectification","pronunciation":"/ˌrektɪf'keɪʃn/","meaning":"n.纠正","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1173,"word":"simplify","pronunciation":"/'sɪmplɪfaɪ/","meaning":"v.使简化","unit":5,"lesson":1,"seq":9,"isStar":false,"memo":"构词 simpl(e)(简单的) + -ify(动词后缀)→使简化","example":"He tried to simplify the story. 他试图简化这个故事。","derivative":"simplicity /sɪm'plɪsəti/ n.简单;淳朴\nsimply /'sɪmpli/ adv.仅仅,只不过;简单地"},{"id":1174,"word":"simplicity","pronunciation":"/sɪm'plɪsəti/","meaning":"n.简单;淳朴","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1175,"word":"simply","pronunciation":"/'sɪmpli/","meaning":"adv.仅仅,只,不过;简单地","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1176,"word":"purify","pronunciation":"/'pjʊərɪfaɪ/","meaning":"v.使(某物)洁净,净化","unit":5,"lesson":1,"seq":10,"isStar":false,"memo":"构词 pur(e)(纯净的) + -ify(动词后缀)→净化","example":"We use filters to purify the water. 我们用过滤器净化水。","derivative":"pure /pjʊə(r)/ adj.纯的;纯净的;完全的\npurity /'pjʊərəti/ n.纯洁;纯净;纯粹"},{"id":1177,"word":"pure","pronunciation":"/pjʊə(r)/","meaning":"adj.纯的;纯净的;完全的","unit":5,"lesson":1,"seq":0,"isStar":true,"memo":"【谐音】‘扑儿’→扑向纯净水！喝一口‘扑儿’——纯得没杂质，连气泡都害羞！","example":"The lab requires pure water for preparing sensitive chemical solutions. 实验室配制敏感化学溶液需用纯水。","derivative":"purity /'pjʊərəti/ n.纯净；纯粹"},{"id":1178,"word":"purity","pronunciation":"/'pjʊərəti/","meaning":"n.纯洁;纯净;纯粹","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1179,"word":"crystal","pronunciation":"/'krɪstl/","meaning":"n.水晶;结晶体 adj.清澈透明的","unit":5,"lesson":1,"seq":11,"isStar":false,"memo":"联想 cry(哭) + st(联想 street) + al→那个女孩在街上哭了,眼泪变成了“水晶”。","example":"She wore a delicate crystal necklace. 她戴着一条精致的水晶项链。"},{"id":1180,"word":"clarify","pronunciation":"/'klærəfaɪ/","meaning":"v.澄清,阐明","unit":5,"lesson":1,"seq":12,"isStar":false,"memo":"构词 clar(= clear) + -ify(动词后缀)→使清楚→澄清,阐明","example":"Its meaning was finally clarified. 它的意义最终得到了澄清。","derivative":"clarification /ˌklærəfɪ'keɪʃn/ n.澄清,阐明\nclarity /'klærəti/ n.清晰,清楚,明确"},{"id":1181,"word":"clarification","pronunciation":"/ˌklærɪfɪˈkeɪn/","meaning":"n.澄清,阐明","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1182,"word":"clarity","pronunciation":"/ˈklærəti/","meaning":"n.清晰,清楚,明确","unit":5,"lesson":1,"seq":0,"isStar":true,"memo":"clari（clear清晰）+ty（状态）→‘清啦！’一声，雾散光来！就像戴眼镜前揉眼喊‘擦亮！’，立马世界高清。","example":"His explanation brought clarity to a complex theory. 他的解释让一个复杂理论变得清晰明了。","derivative":"clarify /ˈklærɪfaɪ/ v. 澄清；阐明"},{"id":1183,"word":"classify","pronunciation":"/ˈklæsfaɪ/","meaning":"v.将……分类,将……归入一类(一个等级)","unit":5,"lesson":1,"seq":13,"isStar":false,"memo":"构词 class(种类,等级) + -ify(动词后缀)→使分类,使等级化→将……归入一类(一个等级)","example":"He objected to classifying parenting as a personal choice. 他反对将养育子女归为个人选择。","derivative":"classified /'klæsɪfad/ adj.分类的,归类的;(资料、文件等)机密的"},{"id":1184,"word":"classified","pronunciation":"/ˈklæsɪfaɪd/","meaning":"adj.分类的,归类的;(资料、文件等)机密的","unit":5,"lesson":1,"seq":14,"isStar":false},{"id":1185,"word":"classic","pronunciation":"/ˈklæsɪk/","meaning":"adj.最优秀的,第一流的;典型的 n.经典作品,名著,杰作","unit":5,"lesson":1,"seq":15,"isStar":false},{"id":1186,"word":"classical","pronunciation":"/ˈklæsɪkl/","meaning":"adj.古典的;经典的;传统的","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1187,"word":"grade","pronunciation":"/ɡreɪd/","meaning":"n.品级;级别;成绩;年级 v.将……分等级;给……评分","unit":5,"lesson":1,"seq":16,"isStar":false},{"id":1188,"word":"ratify","pronunciation":"/ˈrætɪfa/","meaning":"v.正式批准;使正式生效","unit":5,"lesson":1,"seq":17,"isStar":false},{"id":1189,"word":"ratification","pronunciation":"/ˌrætɪfˈkeɪʃn/","meaning":"n.正式批准;正式生效","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1190,"word":"rating","pronunciation":"/ˈreɪtɪ/","meaning":"n.等级;评分;收视率","unit":5,"lesson":1,"seq":18,"isStar":false},{"id":1191,"word":"ratio","pronunciation":"/ˈreɪʃiəʊ/","meaning":"n.比率;比例","unit":5,"lesson":1,"seq":19,"isStar":false,"memo":"谐音‘瑞求’→你求神拜佛都想‘瑞’（好）运，但命运得看‘比率’！拉丁词根rat-（计算）+ -io（名词后缀），算出来的数就是比例。","example":"The student-to-teacher ratio in this lab is 12 to 1. 这间实验室的师生比为12比1。","derivative":"rational /ˈræʃ(ə)n(ə)l/ adj. 理性的；合理的"},{"id":1192,"word":"ration","pronunciation":"/ˈræʃn/","meaning":"n.配给量;正常量 v.定量供应;配给","unit":5,"lesson":1,"seq":20,"isStar":false},{"id":1193,"word":"modify","pronunciation":"/ˈmɒdɪfaɪ/","meaning":"v.更改,改进;修改","unit":5,"lesson":1,"seq":21,"isStar":false,"memo":"【构词】mod-（模式，方式）+ -ify（使…化）→ 使方式‘变样’→修改；谐音‘摸迪飞’——摸着迪斯科节奏边跳边改PPT！","example":"The software automatically modifies font size to fit different screen resolutions. 该软件会自动调整字体大小以适配不同屏幕分辨率。","derivative":"modification /ˌmɒdɪfɪ'keɪʃ(ə)n/ n.修改；改动"},{"id":1194,"word":"modification","pronunciation":"/ˌmɒdɪfɪˈkeɪʃn/","meaning":"n.修改;改进;改变","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1195,"word":"alter","pronunciation":"/ɔːltə(r)/","meaning":"v.(使)改变,更改","unit":5,"lesson":1,"seq":22,"isStar":false,"memo":"【谐音】‘噢特儿’→噢，这事儿得特儿改！v.改变。","example":"The committee voted to alter the original proposal after receiving expert feedback. 委员会收到专家反馈后投票修改原提案。","derivative":"alteration /ˌɔːltə'reɪʃən/ n.变更；alterable /'ɔːltərəbəl/ adj.可改变的"},{"id":1196,"word":"alteration","pronunciation":"/ˌːltəˈreʃn/","meaning":"n.改变;变化","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1197,"word":"alternative","pronunciation":"/ɔːlˈtɜːnətɪv/","meaning":"n.可供选择的事物 adj.可替代的","unit":5,"lesson":1,"seq":0,"isStar":true,"memo":"谐音‘奥特人替他’——超人不在时，奥特人替他上！指可替代的选项。","example":"Students should consider alternative energy sources for their research projects. 学生应在研究项目中考虑替代能源。","derivative":"alternatively /ˌɔːlˈtɜːnətɪvli/ adv. 作为替代地"},{"id":1198,"word":"alternatively","pronunciation":"/ɔːl'tɜːnətɪvli/","meaning":"adv.要不,或者","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1199,"word":"alternation","pronunciation":"/ˌːltəˈneʃn/","meaning":"n.交替;轮流","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1200,"word":"alternately","pronunciation":"/ɔːlˈtɜːnətli/","meaning":"adv.交替出现","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1201,"word":"variable","pronunciation":"/'veəriəbl/","meaning":"n.变量,可变因素 adj.可变的;易变的,多变的","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1202,"word":"variant","pronunciation":"/'veəriənt/","meaning":"n.变种;变体;变形 adj.不同的;变异的","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1203,"word":"variation","pronunciation":"/ˌveəri'eɪʃn/","meaning":"n.差异;变化;变更","unit":5,"lesson":1,"seq":25,"isStar":false},{"id":1204,"word":"shift","pronunciation":"/ʃɪft/","meaning":"v.转移,转变 n.转变;(轮或换)班","unit":5,"lesson":1,"seq":26,"isStar":false},{"id":1205,"word":"draft","pronunciation":"/drɑːft/","meaning":"n.草稿,草案,草图 v.起草,草拟","unit":5,"lesson":1,"seq":27,"isStar":false},{"id":1206,"word":"bill","pronunciation":"/bɪl/","meaning":"n.账单;议案,法案;票据","unit":5,"lesson":1,"seq":28,"isStar":false},{"id":1207,"word":"mend","pronunciation":"/mend/","meaning":"v.修理,缝补","unit":5,"lesson":1,"seq":29,"isStar":false},{"id":1208,"word":"amend","pronunciation":"/ə'mend/","meaning":"v.修正,修订(法律文件、声明等)","unit":5,"lesson":1,"seq":30,"isStar":false,"memo":"a-men-d：‘阿门，得改！’——祈祷后立刻修订错误，超有画面感！","example":"The committee voted to amend the outdated regulation. 委员会投票修改了过时的规定。","derivative":"amendment /əˈmɛndmənt/ n. 修正案；修订"},{"id":1209,"word":"amendment","pronunciation":"/ə'mendmənt/","meaning":"n.(法律、文件的)改动,修正,修订","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1210,"word":"commend","pronunciation":"/kə'mend/","meaning":"v.(尤指公开地)赞扬,表扬;推荐,举荐","unit":5,"lesson":1,"seq":31,"isStar":false,"memo":"【构词】com-（一起）+ mend-（思考，源自mind）→ ‘用心一起想’谁值得夸→赞扬；谐音‘肯门德’——肯德基门德老师，超赞！","example":"The dean commended the student for her outstanding contribution to campus sustainability. 校长表扬该生为校园可持续发展作出的杰出贡献。","derivative":"commendation /ˌkɒmɛn'deɪʃ(ə)n/ n.表扬；推荐信"},{"id":1211,"word":"commendation","pronunciation":"/ˌkɒmen'deɪn/","meaning":"n.赞扬,称赞;奖励","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1212,"word":"recommend","pronunciation":"/ˌrekə'mend/","meaning":"v.推荐,举荐;建议,劝告","unit":5,"lesson":1,"seq":32,"isStar":false,"memo":"【谐音+构词】‘瑞可门德’——瑞（re-再）+可（com-一起）+门德（mend=建议），再一起给建议，就是推荐！","example":"The professor recommended this textbook for advanced linguistics. 教授为高级语言学课程推荐了这本教材。","derivative":"recommendation /ˌrekəmenˈdeɪʃn/ n.推荐；推荐信"},{"id":1213,"word":"recommendation","pronunciation":"/ˌrekəmen'deʃn/","meaning":"n.正式建议,提议;推荐,介绍","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1214,"word":"amplify","pronunciation":"/'æmplɪfaɪ/","meaning":"v.放大,增强(声音等);充实(故事、事情、陈述等)","unit":5,"lesson":1,"seq":33,"isStar":false},{"id":1215,"word":"amplification","pronunciation":"/ˌæmplɪfɪ'keɪʃn/","meaning":"n.扩大;充实","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1216,"word":"qualify","pronunciation":"/'kwɒlfaɪ/","meaning":"v.取得资格(或学历);使合格;使具备资格","unit":5,"lesson":1,"seq":34,"isStar":false},{"id":1217,"word":"qualification","pronunciation":"/ˌkwɒlɪfɪ'keɪʃn/","meaning":"n.资格;资历;合格","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1218,"word":"quantify","pronunciation":"/'kwɒntɪfa/","meaning":"v.量化","unit":5,"lesson":1,"seq":35,"isStar":false},{"id":1219,"word":"quantification","pronunciation":"/ˌkwntɪfɪ'keɪʃn/","meaning":"n.量化","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1220,"word":"unify","pronunciation":"/'juːnɪfaɪ/","meaning":"v.统一;使成一体","unit":5,"lesson":1,"seq":36,"isStar":false},{"id":1221,"word":"unification","pronunciation":"/ˌjuːnɪfɪ'keɪʃn/","meaning":"n.统一;联合","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1222,"word":"unite","pronunciation":"/ju'naɪt/","meaning":"v.联合,联手;联结,统一","unit":5,"lesson":1,"seq":37,"isStar":false},{"id":1223,"word":"unity","pronunciation":"/'ju:nəti/","meaning":"n.团结一致;联合;统一","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1224,"word":"reunite","pronunciation":"/ˌri:ju:'naɪt/","meaning":"v.(使)再结合,再联合;(使)重逢","unit":5,"lesson":1,"seq":38,"isStar":false},{"id":1225,"word":"reunification","pronunciation":"/ˌri:ju:nɪfɪ'keɪʃn/","meaning":"n.重新统一","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1226,"word":"reunion","pronunciation":"/ˌri:'ju:niən/","meaning":"n.重逢;团聚;聚会","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1227,"word":"specify","pronunciation":"/'spesɪfaɪ/","meaning":"v.具体说明;明确规定;详述","unit":5,"lesson":1,"seq":39,"isStar":false,"memo":"speci（看）+fy（使…）→‘让你盯准一点看’！比如老师说‘Specify your sources’=别写‘网上查的’，要‘指定’哪篇论文第几页。","example":"Please specify the date and location for the meeting. 请注明会议的日期和地点。","derivative":"specific /spəˈsɪfɪk/ adj. 明确的；特定的"},{"id":1228,"word":"specification","pronunciation":"/ˌspesɪfɪ'keɪʃn/","meaning":"n.规格;规范;明细单;说明书","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1229,"word":"specific","pronunciation":"/spə'sɪfɪk/","meaning":"adj.特定的;明确的;具体的;特有的","unit":5,"lesson":1,"seq":40,"isStar":false,"memo":"拆解：speci（看）+ fic（做）→ 看准了再做！所以‘具体的、特定的’——不是瞎蒙，是盯着目标精准打击！","example":"The professor gave us specific instructions for the lab experiment. 教授给了我们实验的具体操作指示。","derivative":"specify /ˈspesɪfaɪ/ v.明确说明；specification /ˌspesɪfɪˈkeɪʃn/ n.规范；明细"},{"id":1230,"word":"specifically","pronunciation":"/spə'sɪfɪkli/","meaning":"adv.特意;专门地;明确地;具体地","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1231,"word":"special","pronunciation":"/'speʃl/","meaning":"adj.特殊的,特别的;不寻常的","unit":5,"lesson":1,"seq":41,"isStar":false},{"id":1232,"word":"specialise/-ize","pronunciation":"/'speʃəlaɪz/","meaning":"v.专门研究;专攻","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1233,"word":"specialisation/-zation","pronunciation":"/ˌspeʃəla'zeɪʃn/","meaning":"n.特别化;专门化","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1234,"word":"specialist","pronunciation":"/'speəlɪst/","meaning":"n.专家;专科医生","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1235,"word":"speciality","pronunciation":"/ˌspei'æləti/","meaning":"n.特产;专业;专长","unit":5,"lesson":1,"seq":42,"isStar":false},{"id":1236,"word":"especially","pronunciation":"/ɪ'speʃəli/","meaning":"adv.尤其;特别;专门;非常","unit":5,"lesson":1,"seq":43,"isStar":false},{"id":1237,"word":"specimen","pronunciation":"/'spesɪmən/","meaning":"n.样品;样本,标本","unit":5,"lesson":1,"seq":44,"isStar":false,"memo":"谐音+联想：‘四皮门’——解剖课上老师掀开盖子喊‘四皮门！标本来了！’；词根spec（看）+imen→让你盯着看的东西。","example":"Students observed a preserved frog specimen under the dissecting microscope. 学生们在解剖显微镜下观察了一只保存完好的青蛙标本。","derivative":"speciminate /spəˈsɪmɪneɪt/ v.采样；制作标本"},{"id":1238,"word":"bust","pronunciation":"/bʌst/","meaning":"n.半身像;突击检查 v.打破,摔碎;突击搜查 adj.破产的;破的","unit":5,"lesson":1,"seq":45,"isStar":false},{"id":1239,"word":"burst","pronunciation":"/bɜːst/","meaning":"v.爆炸,爆裂;突然发生 n.爆炸;突发","unit":5,"lesson":1,"seq":46,"isStar":false},{"id":1240,"word":"robust","pronunciation":"/rəʊ'bʌst/","meaning":"adj.强健的,强壮的,结实的;坚定的;稳固的","unit":5,"lesson":1,"seq":47,"isStar":false,"memo":"【谐音】‘肉不瘦’——肌肉结实、身体壮实；【构词】robust ← Latin robur（橡树，象征坚固）→像橡树一样结实。","example":"A robust immune system helps students resist seasonal flu during exams. 强健的免疫系统有助于学生在考试期间抵御季节性流感。","derivative":"robustness /rə(ʊ)'bʌstnəs/ n.强健；稳健性"},{"id":1241,"word":"blast","pronunciation":"/blɑ:st/","meaning":"n.一阵疾风;爆炸;响亮的声音 v.炸毁;爆破;突然发出巨响;抨击","unit":5,"lesson":1,"seq":48,"isStar":false,"memo":"谐音‘爆死’——爆炸当然让人想‘爆死’！b+last（最后），爆炸后啥都没了，只剩‘最后’。","example":"The demolition team set off a controlled blast to clear the old building. 拆除队引爆定向爆破来清理旧楼。","derivative":"blasting /ˈblɑːstɪŋ/ n.爆破；blastoff /ˈblɑːstɒf/ n.火箭升空"},{"id":1242,"word":"plastic","pronunciation":"/'plæstɪk/","meaning":"n.塑料 adj.塑料制的;可塑的","unit":5,"lesson":1,"seq":49,"isStar":false,"memo":"【谐音】‘拍死踢’→塑料袋一拍就瘪、一踢就飞，n./adj.塑料（的）。","example":"Many campuses have banned single-use plastic bottles to reduce environmental impact. 许多校园已禁用一次性塑料瓶以减轻环境影响。","derivative":"plasticity /plæ'stɪsəti/ n.可塑性"},{"id":1243,"word":"elastic","pronunciation":"/ɪ'læstk/","meaning":"adj.有弹性的;灵活的 n.橡皮圈","unit":5,"lesson":1,"seq":50,"isStar":false},{"id":1244,"word":"elasticity","pronunciation":"/ˌɪlæ'stɪsəti/","meaning":"n.弹性;弹力","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1245,"word":"flexible","pronunciation":"/'fleksəbl/","meaning":"adj.柔韧的,易弯曲的;灵活的,可通融的","unit":5,"lesson":1,"seq":51,"isStar":false,"memo":"谐音+联想：'flexi-布勒'——布勒（布料）能弯能折，身体软、计划软、思维也软！","example":"A flexible schedule helps students balance part-time jobs and coursework. 灵活的时间安排有助于学生兼顾兼职工作与课程学习。","derivative":"flexibility /ˌfleksəˈbɪləti/ n.灵活性；inflexible /ɪnˈfleksəb(ə)l/ adj.僵硬的"},{"id":1246,"word":"flexibility","pronunciation":"/ˌfleksə'bɪləti/","meaning":"n.灵活性;弹性,柔韧","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1247,"word":"reflect","pronunciation":"/rɪ'flekt/","meaning":"v.反射;反映;反省","unit":5,"lesson":1,"seq":52,"isStar":false},{"id":1248,"word":"reflection","pronunciation":"/rɪ'flekʃn/","meaning":"n.反射;反映;影像","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1249,"word":"reflective","pronunciation":"/r'flektɪv/","meaning":"adj.沉思的,深思的;反射热的,反光的;典型的,代表性的","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1250,"word":"distort","pronunciation":"/dɪ'stɔːt/","meaning":"v.使变形,扭曲;歪曲,曲解","unit":5,"lesson":1,"seq":53,"isStar":false,"memo":"dis-（歪）+tort（扭曲，同torture）→歪着折磨，不就是‘歪曲’真相嘛！","example":"Sensational headlines often distort the facts. 耸人听闻的标题常常歪曲事实。","derivative":"distortion /dɪˈstɔːrʃən/ n. 扭曲；失真"},{"id":1251,"word":"distorted","pronunciation":"/dɪ'stɔːtɪd/","meaning":"adj.扭曲的","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1252,"word":"distortion","pronunciation":"/dɪ'stɔːʃn/","meaning":"n.歪曲;变形,扭曲","unit":5,"lesson":1,"seq":0,"isStar":true},{"id":1253,"word":"retort","pronunciation":"/rɪ'tɔːt/","meaning":"v.反驳,回嘴 n.回应,反驳","unit":5,"lesson":1,"seq":54,"isStar":false},{"id":1254,"word":"torture","pronunciation":"/'tɔtʃə(r)/","meaning":"n.拷打,拷问;折磨 v.拷打,拷问;使痛苦","unit":5,"lesson":1,"seq":55,"isStar":false},{"id":1255,"word":"breakdown","pronunciation":"/'brekdaʊn/","meaning":"n.(汽车或机器的)故障,损坏;(关系的)破裂;失败","unit":5,"lesson":2,"seq":1,"isStar":false,"memo":"【构词】break（坏掉）+ down（垮下）→‘啪嗒垮掉’→机器故障、情绪崩溃都用它！修车师傅最爱说breakdown～","example":"The server breakdown delayed online registration for over two hours. 服务器故障导致在线报名延迟超两小时。"},{"id":1256,"word":"bankrupt","pronunciation":"/'bæŋkrʌpt/","meaning":"n.破产者 v.使破产 adj.破产的,倒闭的","unit":5,"lesson":2,"seq":2,"isStar":false},{"id":1257,"word":"bankruptcy","pronunciation":"/'bæŋkrʌptsi/","meaning":"n.破产,倒闭;(名誉等的)彻底消失","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1258,"word":"deficit","pronunciation":"/'defɪsɪt/","meaning":"n.赤字,亏损,逆差","unit":5,"lesson":2,"seq":3,"isStar":false,"memo":"de-（向下）+fic（做）+it→钱‘做’少了，账上亏空啦！","example":"The national budget deficit reached record levels last year. 去年国家财政赤字达到历史最高水平。","derivative":"deficitary /ˈdefɪsətri/ adj. 赤字的"},{"id":1259,"word":"interrupt","pronunciation":"/ɪntə'rʌpt/","meaning":"v.打断(某人的)讲话;打扰;使中断","unit":5,"lesson":2,"seq":4,"isStar":false,"memo":"in-ter-rupt：‘in’冲进去+‘ter’（=terr-恐）+‘rupt’（破）→硬闯+吓人+撕裂对话！","example":"Please don’t interrupt the speaker during the Q&A session. 问答环节请勿打断发言者。","derivative":"interruption /ˌɪntə'rʌpʃn/ n.打断；interrupter /ˌɪntə'rʌptə/ n.打断者"},{"id":1260,"word":"interruption","pronunciation":"/ɪntə'rʌpʃn/","meaning":"n.打扰;插嘴;阻断物;中断时间","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1261,"word":"erupt","pronunciation":"/ɪ'rʌpt/","meaning":"v.突然发生;爆发;喷发;迸发","unit":5,"lesson":2,"seq":5,"isStar":false},{"id":1262,"word":"eruption","pronunciation":"/ɪ'rʌpʃn/","meaning":"n.突然发生;爆发;喷发","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1263,"word":"disrupt","pronunciation":"/dɪs'rʌpt/","meaning":"v.扰乱,使混乱,打乱","unit":5,"lesson":2,"seq":6,"isStar":false,"memo":"dis-（分开）+rupt（破裂，如erupt）→啪一下撕裂流程，‘扰乱’没商量！","example":"A cyberattack disrupted the hospital's booking system. 一次网络攻击扰乱了医院预约系统。","derivative":"disruption /dɪsˈrʌpʃən/ n. 中断；扰乱"},{"id":1264,"word":"disruptive","pronunciation":"/dsˈrʌptv/","meaning":"adj.引起混乱的;扰乱性的;破坏性的","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1265,"word":"disruption","pronunciation":"/dɪsrʌpʃn/","meaning":"n.中断,分裂,破坏","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1266,"word":"abrupt","pronunciation":"/əˈbrʌpt/","meaning":"adj.突然的,意外的;粗鲁的,生硬的","unit":5,"lesson":2,"seq":7,"isStar":false,"memo":"a-b-rupt（‘啊！不rupt？’）→ 突然中断！rupt=break（断裂），前缀ab-=away，一断就‘away’消失，毫无预兆！","example":"His abrupt departure left the team unprepared for the deadline. 他突然离职，导致团队无法按时完成任务。","derivative":"abruptly /ə'brʌptli/ adv. 突然地"},{"id":1267,"word":"corrupt","pronunciation":"/kəˈrpt/","meaning":"v.使腐化;破坏 adj.腐败的;不道德的","unit":5,"lesson":2,"seq":8,"isStar":false},{"id":1268,"word":"corruption","pronunciation":"/kəˈrʌpʃn/","meaning":"n.腐败;受贿;堕落","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1269,"word":"rot","pronunciation":"/rɒt/","meaning":"n.腐烂;腐败 v.(使)腐烂,(使)腐败","unit":5,"lesson":2,"seq":9,"isStar":false},{"id":1270,"word":"rotten","pronunciation":"/ˈrɒtn/","meaning":"adj.腐烂的,腐败的","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1271,"word":"rotate","pronunciation":"/rəʊˈteɪt/","meaning":"v.(使)旋转,(使)转动;由……轮值","unit":5,"lesson":2,"seq":10,"isStar":false},{"id":1272,"word":"rotation","pronunciation":"/rəˈteɪʃn/","meaning":"n.旋转,转动;轮换","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1273,"word":"erode","pronunciation":"/ɪˈrəʊd/","meaning":"v.腐蚀;风化;逐渐毁坏;削弱","unit":5,"lesson":2,"seq":11,"isStar":false,"memo":"【构词】e-（出）+ rode（路？错！实为rod-根，同corrode）→水把石头‘啃出来’→侵蚀！浪花天天舔崖壁，崖就悄悄erode。","example":"Coastal erosion threatens many seaside villages. 海岸侵蚀正威胁许多海滨村庄。","derivative":"erosion /ɪˈrəʊ.ʒən/ n.侵蚀；腐蚀"},{"id":1274,"word":"decay","pronunciation":"/dɪˈkeɪ/","meaning":"v.(力量、影响等)衰弱,衰退;(使)腐烂,腐朽","unit":5,"lesson":2,"seq":12,"isStar":false},{"id":1275,"word":"bribe","pronunciation":"/braɪb/","meaning":"n.贿赂 v.贿赂,收买","unit":5,"lesson":2,"seq":13,"isStar":false},{"id":1276,"word":"bribery","pronunciation":"/braɪbəri/","meaning":"n.贿赂","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1277,"word":"debt","pronunciation":"/det/","meaning":"n.借款,欠款,债务","unit":5,"lesson":2,"seq":14,"isStar":false,"memo":"【谐音】'贷'它→你找银行'贷'款，结果背上'债'（debt）！d-e-b-t，四个字母像四张欠条。","example":"Student debt in the US has exceeded one trillion dollars. 美国学生债务已超一万亿美元。","derivative":"debtor /ˈdetər/ n.债务人"},{"id":1278,"word":"debtor","pronunciation":"/ˈdetə(r)/","meaning":"n.债务人;借方","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1279,"word":"indebted","pronunciation":"/ɪndetɪd/","meaning":"adj.负债的;感激的,蒙恩的","unit":5,"lesson":2,"seq":15,"isStar":false,"memo":"【构词】in-（进入）+debt（债务）+ed→‘陷进债务里’→负债；引申为‘情感上陷进感激里’→感激不尽！","example":"She felt deeply indebted to her mentor for career guidance. 她深深感激导师的职业指导。","derivative":"indebtedness /ɪn'detɪdnəs/ n.负债；感激之情"},{"id":1280,"word":"levy","pronunciation":"/ˈlevi/","meaning":"n.征收额;税款 v.征收,征(税)","unit":5,"lesson":2,"seq":16,"isStar":false,"memo":"【谐音】'来税'——税务局一来，税就来了！v.征税，n.税款，和'levitate'（升空）同源，本义‘抬起来’→把钱抬走。","example":"The government plans to levy a new carbon tax on heavy industries. 政府计划对重工业征收新的碳税。"},{"id":1281,"word":"lever","pronunciation":"/ˈliːvə(r)/","meaning":"n.操纵杆,杠杆;方法,手段 v.(用杠杆)撬动","unit":5,"lesson":2,"seq":17,"isStar":false},{"id":1282,"word":"leverage","pronunciation":"/ˈliːvərdʒ/","meaning":"n.影响力;杠杆作用 v.充分利用","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1283,"word":"inflate","pronunciation":"/ɪnˈfleɪt/","meaning":"v.使充气,膨胀","unit":5,"lesson":2,"seq":18,"isStar":false},{"id":1284,"word":"inflation","pronunciation":"/ɪnˈfleɪʃn/","meaning":"n.通货膨胀;充气","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1285,"word":"shrink","pronunciation":"/ʃrɪk/","meaning":"v.(使)缩水,(使)缩小,(使)收缩;减少;退缩","unit":5,"lesson":2,"seq":19,"isStar":false,"memo":"【谐音+联想】‘神缩水’——毛衣洗完‘神缩水’，衣服小一圈，人也想‘缩’着躲尴尬！","example":"Many small businesses have shrunk or closed due to rising operational costs. 许多小微企业因运营成本上升而缩减规模或倒闭。","derivative":"shrinkage /ˈʃrɪŋkɪdʒ/ n.收缩；损耗"},{"id":1286,"word":"fade","pronunciation":"/feɪd/","meaning":"v.褪色;逐渐消失,淡出","unit":5,"lesson":2,"seq":20,"isStar":false},{"id":1287,"word":"shred","pronunciation":"/ʃred/","meaning":"n.细条,碎片;一丁点 v.把……撕成碎片;把(文件)放进碎纸机粉碎","unit":5,"lesson":2,"seq":21,"isStar":false},{"id":1288,"word":"sheet","pronunciation":"/ʃit/","meaning":"n.床单,被单;纸张;薄片,一片","unit":5,"lesson":2,"seq":22,"isStar":false},{"id":1289,"word":"shell","pronunciation":"/ʃel/","meaning":"n.壳;贝壳;炮弹","unit":5,"lesson":2,"seq":23,"isStar":false},{"id":1290,"word":"coast","pronunciation":"/kəʊst/","meaning":"n.海岸,海滨","unit":5,"lesson":2,"seq":24,"isStar":false},{"id":1291,"word":"coastal","pronunciation":"/'kəʊstl/","meaning":"adj.沿海的;靠近海岸的","unit":5,"lesson":2,"seq":0,"isStar":true,"memo":"coast（海岸）+ -al（形容词后缀）→字面就是‘海岸的’！记成‘靠死它’——海边房子太抢手，靠海就得拼命抢！","example":"Coastal communities face increasing risks from sea-level rise. 沿海社区正面临日益加剧的海平面上升风险。","derivative":"coastline /ˈkəʊstlaɪn/ n.海岸线；coastward /ˈkəʊstwəd/ adv.向海岸"},{"id":1292,"word":"deposit","pronunciation":"/dɪ'pɒzɪt/","meaning":"n.押金,订金;存款;沉积物v.使沉积;将(钱)存入(银行)","unit":5,"lesson":2,"seq":25,"isStar":false,"memo":"de-（下）+posit（放，=put）→把钱‘往下放’进银行是定金，泥沙‘往下放’堆成沉积物。","example":"Scientists analyzed sediment deposits to reconstruct ancient climate patterns. 科学家分析沉积物以重建古代气候模式。","derivative":"depositary /dɪˈpɒzɪtərɪ/ n. 保管人；deposition /ˌdepəˈzɪʃn/ n. 沉积作用"},{"id":1293,"word":"compose","pronunciation":"/kəm'pəʊz/","meaning":"v.组成,构成;作曲,创作","unit":5,"lesson":2,"seq":26,"isStar":false,"memo":"【构词】com-（一起）+ pose（放）→把东西放在一起→组成；写歌也是把音符‘放一起’！","example":"The composer will compose a new symphony for the university's centennial. 这位作曲家将为大学百年校庆创作一部新交响曲。","derivative":"composer /kəmˈpəʊzə/ n.作曲家"},{"id":1294,"word":"composition","pronunciation":"/ˌkɒmpə'zɪʃn/","meaning":"n.成分,构成;作品,作曲","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1295,"word":"composer","pronunciation":"/kəm'pəʊzə(r)/","meaning":"n.作曲家","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1296,"word":"composite","pronunciation":"/'kɒmpəzɪt/","meaning":"n.合成物,混合物;复合材料adj.合成的","unit":5,"lesson":2,"seq":27,"isStar":false,"memo":"com-（一起）+ posite（放）→ ‘一起放’的东西就是合成物！像奶茶加珍珠+布丁+芋圆，复合式快乐～","example":"Engineers used a lightweight composite material for the drone’s frame. 工程师为无人机机架采用了轻质复合材料。","derivative":"composition /ˌkɒmpə'zɪʃn/ n. 组成；作文"},{"id":1297,"word":"compile","pronunciation":"/kəm'paɪl/","meaning":"v.编写,编纂;汇编;编译","unit":5,"lesson":2,"seq":28,"isStar":false,"memo":"谐音+构词：‘康破了’——程序员编译代码时电脑卡到崩溃！com-（一起）+pile（堆）→把零散资料堆成一本手册。","example":"The team compiled survey data into a comprehensive report for the university. 团队将调查数据汇编成一份供大学使用的综合报告。","derivative":"compilation /ˌkɒmpɪ'leɪʃ(ə)n/ n.汇编；选集"},{"id":1298,"word":"compilation","pronunciation":"/ˌkɒmpɪ'leɪʃn/","meaning":"n.收集;编纂,编写","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1299,"word":"pile","pronunciation":"/paɪl/","meaning":"n.摞,堆;成堆的东西 v.堆放,叠放","unit":5,"lesson":2,"seq":29,"isStar":false,"memo":"谐音‘派尔’——派你去堆‘尔’（一堆）书！pil-（= pile 堆，同源pill 原义‘小块’）+ -e，摞起来像小山包。","example":"Students piled textbooks on the desk before the final exam. 考前学生们把教科书堆在课桌上。","derivative":"piling /'paɪlɪŋ/ n.堆叠；桩基工程"},{"id":1300,"word":"file","pronunciation":"/fal/","meaning":"n.文件夹;卷宗;档案 v.(把文件等)归档;提起(诉讼);提出(申请)","unit":5,"lesson":2,"seq":30,"isStar":false},{"id":1301,"word":"posture","pronunciation":"/'pɒstʃə(r)/","meaning":"n.(坐、立的)姿势;态度,立场v.故作姿态","unit":5,"lesson":2,"seq":31,"isStar":false},{"id":1302,"word":"pose","pronunciation":"/pəʊz/","meaning":"n.(为画像、拍照等摆的)姿势v.造成(威胁、问题等),引起,产生","unit":5,"lesson":2,"seq":0,"isStar":true,"memo":"【构词】po-（=put, 放）+ -se → 把身体‘放’成某个样子→姿势；引申为‘放’个难题给你→造成（麻烦）。","example":"The rapid AI development poses serious ethical questions for educators. 人工智能的快速发展给教育工作者提出了严峻的伦理问题。","derivative":"poser /'pəʊzə/ n.摆姿势者；故作姿态者"},{"id":1303,"word":"propose","pronunciation":"/prə'pəʊz/","meaning":"v.提议,建议;打算;求婚","unit":5,"lesson":2,"seq":32,"isStar":false,"memo":"pro（向前）+pose（放）→‘把方案往前一放’=提议！求婚也是‘把戒指往前一放’，同源！","example":"He proposed a novel framework for cross-disciplinary research. 他提出了一种跨学科研究的新框架。","derivative":"proposal /prə'pəʊz(ə)l/ n.提案；proposer /prə'pəʊzə/ n.提议者"},{"id":1304,"word":"proposal","pronunciation":"/prə'pəʊzl/","meaning":"n.提议,建议;求婚","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1305,"word":"proposition","pronunciation":"/prɒpə'zʃn/","meaning":"n.提议,建议;(美国)法律修正议案;观点","unit":5,"lesson":2,"seq":33,"isStar":false},{"id":1306,"word":"position","pronunciation":"/pə'zɪʃn/","meaning":"n.观点,立场;位置,地方;职务","unit":5,"lesson":2,"seq":34,"isStar":false},{"id":1307,"word":"expose","pronunciation":"/ɪk'spəʊz/","meaning":"v.使接触;暴露;揭露","unit":5,"lesson":2,"seq":35,"isStar":false,"memo":"【构词】ex-（外）+ pose（放）→ 把东西‘放出来’让人看见→暴露；谐音‘一克死泡丝’——曝光后病毒一克就死！","example":"Investigative journalists exposed corruption in the city's public housing system. 调查记者揭发了该市公共住房系统的腐败问题。","derivative":"exposure /ɪk'spəʊʒə/ n.暴露；曝光；接触"},{"id":1308,"word":"exposure","pronunciation":"/ɪkˈspəʊʒə(r)/","meaning":"n.暴露,曝光;接触;揭露","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1309,"word":"exposition","pronunciation":"/ˌeks pəˈzɪʃn/","meaning":"n.解释,说明,阐述;商品交易会,产品博览会","unit":5,"lesson":2,"seq":36,"isStar":false},{"id":1310,"word":"dispose","pronunciation":"/dɪspəʊz/","meaning":"v.使倾向于;布置,安排;处理,扔掉","unit":5,"lesson":2,"seq":37,"isStar":false,"memo":"【构词】dis-（分开）+ pose（放）→ 把东西‘分开放好’→ 布置安排！就像宿舍长dispose床位：上铺A，下铺B，井井有条～","example":"The lab director disposed equipment neatly across three workbenches. 实验室主任将设备整齐布置在三张工作台上。","derivative":"disposal /dɪˈspəʊzl/ n.处理；布置"},{"id":1311,"word":"disposition","pronunciation":"/ˌdɪspəˈzɪʃn/","meaning":"n.性格,性情;倾向,意向","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1312,"word":"disposal","pronunciation":"/dɪˈspəʊzl/","meaning":"n.清除;处理;(企业、财产等的)变卖","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1313,"word":"impose","pronunciation":"/ɪmˈpəʊz/","meaning":"v.推行,采用;强制实行,把……强加于","unit":5,"lesson":2,"seq":38,"isStar":false,"memo":"【构词】im-（in-, 进入）+ pose（放）→ 把规则‘放进去’你生活里→强加；联想‘俺怕死’——领导 impose 加班，俺怕死也得干！","example":"The government imposed strict data privacy regulations on tech firms. 政府对科技公司施加了严格的数据隐私监管。","derivative":"imposition /ɪm'pəʊzɪʃ(ə)n/ n.强加；强加的事物"},{"id":1314,"word":"imposition","pronunciation":"/ˌɪmpəˈzɪʃn/","meaning":"n.颁布,实施;征收","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1315,"word":"imposing","pronunciation":"/ɪmˈpəʊzɪŋ/","meaning":"adj.壮观的;使人印象深刻的","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1316,"word":"oppose","pronunciation":"/əˈpəʊz/","meaning":"v.反对,对抗;与……角逐","unit":5,"lesson":2,"seq":39,"isStar":false,"memo":"op-pose：‘op-’（against）+‘pose’（摆姿势）→面对面‘摆pose’对峙！反对就是站对面凹造型。","example":"Many citizens oppose the new policy on data privacy. 许多市民反对这项新的数据隐私政策。","derivative":"opposition /ˌɒpə'zɪʃn/ n.反对；opponent /ə'pəʊnənt/ n.反对者"},{"id":1317,"word":"opposition","pronunciation":"/ˌɒpəˈzɪʃn/","meaning":"n.(强烈的)反对,反抗,对抗","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1318,"word":"opposite","pronunciation":"/ˈɒpəzɪt/","meaning":"adj.对面的,相反的 n.对立面,反面","unit":5,"lesson":2,"seq":40,"isStar":false,"memo":"【构词】op-（反）+ posite（放）→反着放→相反的！就像你妈让你往东，你偏往西，纯纯反向操作。","example":"The opposite of 'optimistic' is 'pessimistic'. '乐观'的反义词是'悲观'。","derivative":"opposition /ˌɒpəˈzɪʃ(ə)n/ n.反对；对立"},{"id":1319,"word":"opponent","pronunciation":"/əˈpənənt/","meaning":"n.对手,竞争者;反对者","unit":5,"lesson":2,"seq":41,"isStar":false},{"id":1320,"word":"component","pronunciation":"/kəmpəʊnənt/","meaning":"n.组成部分;成分,部件","unit":5,"lesson":2,"seq":42,"isStar":false,"memo":"com（一起）+ pon（放）+ ent → ‘放在一起的东西’！机器零件、课程模块、性格要素…全是被‘放进来’的组成分子～","example":"Each component of the software must be tested before integration. 软件每个组件集成前都必须经过测试。","derivative":"comprise /kəmˈpraɪz/ v.包含；constituent /kənˈstɪtʃuənt/ n.组成部分"},{"id":1321,"word":"exponent","pronunciation":"/kˈspəʊnənt/","meaning":"n.拥护者,倡导者;能手,大师;指数","unit":5,"lesson":2,"seq":43,"isStar":false},{"id":1322,"word":"rival","pronunciation":"/raɪvl/","meaning":"n.竞争对手 v.与……相匹敌,比得上","unit":5,"lesson":2,"seq":44,"isStar":false,"memo":"拆成 rive（撕裂）+ al（人）→ 把对手‘撕裂’成平手？不，是旗鼓相当的对手！","example":"Two tech giants are fierce rivals in the AI research field. 两家科技巨头在人工智能研究领域是激烈的竞争对手。","derivative":"rivalry /'raɪvəlri/ n.竞争；对抗"},{"id":1323,"word":"rivalry","pronunciation":"/ˈraɪvlri/","meaning":"n.竞争,竞赛,较量","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1324,"word":"positive","pronunciation":"/ˈpɒzətɪv/","meaning":"adj.赞同的;积极乐观的,有信心的;积极的","unit":5,"lesson":2,"seq":45,"isStar":false},{"id":1325,"word":"negative","pronunciation":"/ˈneɡətɪv/","meaning":"adj.有害的,消极的,负面的;否定的","unit":5,"lesson":2,"seq":46,"isStar":false},{"id":1326,"word":"optimistic","pronunciation":"/ˌɒptɪmɪstɪk/","meaning":"adj.乐观的,乐观主义的","unit":5,"lesson":2,"seq":47,"isStar":false},{"id":1327,"word":"optimism","pronunciation":"/ˈptɪmɪzəm/","meaning":"n.乐观;乐观主义","unit":5,"lesson":2,"seq":0,"isStar":true,"memo":"【谐音+联想】‘噢！提我ism’——乐观主义就是总喊‘噢！提我一把吧！’还坚信能行！","example":"His optimism helped the team stay motivated during the tough project. 他的乐观主义帮助团队在艰难项目中保持动力。","derivative":"optimist /'ɒptɪmɪst/ n.乐观主义者；optimistic /ˌɒptɪ'mɪstɪk/ adj.乐观的"},{"id":1328,"word":"optimist","pronunciation":"/ˈɒptɪmɪst/","meaning":"n.乐观的人;乐天派","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1329,"word":"passive","pronunciation":"/ˈpæsɪv/","meaning":"adj.被动的,消极的","unit":5,"lesson":2,"seq":48,"isStar":false},{"id":1330,"word":"reluctant","pronunciation":"/rɪ'lʌktənt/","meaning":"adj.不情愿的","unit":5,"lesson":2,"seq":49,"isStar":false,"memo":"re-（反）+ luc-（光，引申为‘显露意愿’）+ -tant → 反光不愿露脸？其实是‘不情愿的’——像早八课赖床的你！","example":"Many faculty members remain reluctant to adopt AI grading tools. 许多教师仍不愿采用人工智能评分工具。","derivative":"reluctance /'relʌktəns/ n.不情愿；勉强"},{"id":1331,"word":"reluctance","pronunciation":"/rɪ'lʌktəns/","meaning":"n.勉强,不情愿","unit":5,"lesson":2,"seq":0,"isStar":true},{"id":1332,"word":"attitude","pronunciation":"/'ætɪtjuːd/","meaning":"n.态度,看法;姿势","unit":5,"lesson":2,"seq":50,"isStar":false,"memo":"谐音+联想：'爱踢图度'→爱踢足球的人态度超硬核！at-（表强调）+titude（=tude，姿态）→内心姿态即态度。","example":"Her positive attitude toward feedback greatly impressed the thesis advisor. 她对反馈所持的积极态度给论文导师留下深刻印象。","derivative":"attitudinal /ˌætɪ'tjuːdɪn(ə)l/ adj.态度上的；attitude test /'ætɪtjuːd tɛst/ n.态度量表"},{"id":1333,"word":"latitude","pronunciation":"/'lætɪtjuːd/","meaning":"n.纬度;选择(做什么事或做事方式)的自由","unit":5,"lesson":2,"seq":51,"isStar":false},{"id":1334,"word":"aptitude","pronunciation":"/'æptɪtjuːd/","meaning":"n.天资,天赋","unit":5,"lesson":2,"seq":52,"isStar":false,"memo":"拆成a-pti-tude：'a'像‘啊’，‘pti’谐音‘体’，‘tude’像‘天赋’——一看到它就‘啊！这身体自带天赋！’","example":"Her aptitude for coding became obvious during the AI club hackathon. 她在AI社团编程马拉松中展现出惊人的编程天赋。","derivative":"apt /æpt/ adj.恰当的；有天赋的"},{"id":1335,"word":"exportation","pronunciation":"/ˌeks pɔː'teɪn/","meaning":"n.出口,输出","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1336,"word":"importation","pronunciation":"/ˌɪm pɔː'teɪʃn/","meaning":"n.进口,输入,引进","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1337,"word":"porter","pronunciation":"/'pɔtə(r)/","meaning":"n.行李员,搬运工;护工;门卫","unit":5,"lesson":3,"seq":3,"isStar":false},{"id":1338,"word":"deport","pronunciation":"/dɪ'pɔːt/","meaning":"v.驱逐出境,递解出境","unit":5,"lesson":3,"seq":4,"isStar":false},{"id":1339,"word":"deportation","pronunciation":"/diː pɔː'teɪʃn/","meaning":"n.驱逐出境;放逐","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1340,"word":"support","pronunciation":"/sə'pɔt/","meaning":"n.支持,拥护;支撑物 v.支持;支撑;养活","unit":5,"lesson":3,"seq":5,"isStar":false},{"id":1341,"word":"supportive","pronunciation":"/sə'pɔːtɪv/","meaning":"adj.给予帮助的;支持的;鼓励的;同情的","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1342,"word":"supporter","pronunciation":"/sə'pɔːtə(r)/","meaning":"n.支持者,拥护者","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1343,"word":"endorse","pronunciation":"/ɪn'dɔːs/","meaning":"v.(公开)赞同,支持,认可","unit":5,"lesson":3,"seq":6,"isStar":false,"memo":"en-（使）+ dors（背，后背）+ -e → 在文件背面‘签’字支持！背书= endorse～","example":"The professor publicly endorsed the student-led climate initiative. 教授公开支持了由学生发起的气候倡议。","derivative":"endorsement /ɪn'dɔːsmənt/ n.支持；认可；背书"},{"id":1344,"word":"endorsement","pronunciation":"/ɪn'dɔːsmənt/","meaning":"n.支持,认可","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1345,"word":"transportation","pronunciation":"/ˌtræn spɔː'teɪʃn/","meaning":"n.交通运输系统","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1346,"word":"portion","pronunciation":"/'pɔːʃn/","meaning":"n.部分;(食物的)一份","unit":5,"lesson":3,"seq":8,"isStar":false},{"id":1347,"word":"proportion","pronunciation":"/prə'pɔːʃn/","meaning":"n.比例;部分,份额","unit":5,"lesson":3,"seq":9,"isStar":false,"memo":"pro-（向前）+ port（搬运，词根port=carry）+ -ion → 把‘比例’像快递一样精准‘搬运’进数据图里！饼图切几块？看proportion！","example":"The proportion of remote workers has increased sharply. 远程工作者的比例已急剧上升。","derivative":"proportional /prəˈpɔːʃ(ə)n(ə)l/ adj.成比例的；相称的"},{"id":1348,"word":"proportional","pronunciation":"/prə'pɔːʃənl/","meaning":"adj.成比例的;相称的","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1349,"word":"opportunity","pronunciation":"/ˌɒpə'tjuːnəti/","meaning":"n.机会;时机","unit":5,"lesson":3,"seq":10,"isStar":false},{"id":1350,"word":"porch","pronunciation":"/pɔːtʃ/","meaning":"n.门廊,走廊","unit":5,"lesson":3,"seq":11,"isStar":false},{"id":1351,"word":"portfolio","pronunciation":"/pɔːt'fəʊliəʊ/","meaning":"n.文件夹;公文包;投资组合;作品集","unit":5,"lesson":3,"seq":12,"isStar":false},{"id":1352,"word":"deem","pronunciation":"/dim/","meaning":"v.认为,相信","unit":5,"lesson":3,"seq":13,"isStar":false},{"id":1353,"word":"assert","pronunciation":"/ə'sɜːt/","meaning":"v.(坚决)主张;断言","unit":5,"lesson":3,"seq":14,"isStar":false,"memo":"as-sert → ‘啊嘶特！’（拍桌起身状）——不是生气，是理直气壮把观点‘坚称’出来，自带BGM！","example":"She asserted her right to speak at the meeting. 她坚称自己有权在会上发言。","derivative":"assertion /əˈsɜːʃ(ə)n/ n.断言；主张"},{"id":1354,"word":"assertive","pronunciation":"/ə'sɜːtɪv/","meaning":"adj.果断的,自信的","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1355,"word":"assertion","pronunciation":"/ə'sɜːʃn/","meaning":"n.主张,断言,声明","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1356,"word":"insert","pronunciation":"/ɪn'sɜːt/","meaning":"v.插入,放进;(在文件或文稿中)加入 /'nsɜːt/ n.(夹在报刊中的)插页广告;插入物","unit":5,"lesson":3,"seq":15,"isStar":false},{"id":1357,"word":"insertion","pronunciation":"/ɪn'sɜʃn/","meaning":"n.放入,插入;插入物","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1358,"word":"claim","pronunciation":"/kleɪm/","meaning":"n.声明,宣称;索赔 v.宣称,声称;断言","unit":5,"lesson":3,"seq":16,"isStar":false,"memo":"【谐音】‘克雷姆’→ 你抢（claim）走我的奶茶？我立刻‘克雷姆’（claim）索赔！声调上扬像抗议。","example":"The researcher claimed priority in discovering the new enzyme. 研究员声称自己最先发现这种新酶。","derivative":"claimant /'kleɪmənt/ n.索赔人; reclaim /rɪ'kleɪm/ v.收回，改造"},{"id":1359,"word":"exclaim","pronunciation":"/ɪk'skleɪm/","meaning":"v.(尤因强烈的情感或痛苦而)惊叫, 呼喊","unit":5,"lesson":3,"seq":17,"isStar":false,"memo":"【构词】ex-（出）+ claim（喊，同claim‘宣称’）→ 声音‘喊出来’！不是慢慢说，是突然‘啊！’一声蹦出口～","example":"She exclaimed in surprise when she saw the unexpected gift. 她看到意外礼物时惊叫起来。","derivative":"exclamation /ˌekskləˈmeɪʃn/ n.惊叫；感叹词"},{"id":1360,"word":"exclamation","pronunciation":"/eksklə'meɪn/","meaning":"n.感叹;感叹词","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1361,"word":"exclamatory","pronunciation":"/ɪk'sklæmətri/","meaning":"adj.表示感叹的;惊叹的","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1362,"word":"acclaim","pronunciation":"/ə'kleɪm/","meaning":"v.称赞,为……喝彩;推崇","unit":5,"lesson":3,"seq":18,"isStar":false},{"id":1363,"word":"proclaim","pronunciation":"/prə'kleɪm/","meaning":"v.宣布,宣告;声明","unit":5,"lesson":3,"seq":19,"isStar":false,"memo":"【构词】pro-（向前）+ claim（喊叫）→往前一喊，全城都听见！就像校长站主席台大喇叭宣布放假。","example":"The government proclaimed a state of emergency after the earthquake. 地震后，政府宣布进入紧急状态。","derivative":"proclamation /ˌprəʊklaˈmeɪʃ(ə)n/ n.宣告；公告"},{"id":1364,"word":"proclamation","pronunciation":"/ˌprɒklə'meɪʃn/","meaning":"n.宣言;公告;声明","unit":5,"lesson":3,"seq":20,"isStar":false},{"id":1365,"word":"declare","pronunciation":"/dɪ'kleə(r)/","meaning":"v.公布,宣布,宣告","unit":5,"lesson":3,"seq":21,"isStar":false,"memo":"de-（完全）+clare（清晰，词根clara=clear）→把事情‘彻底说清’，就是宣布！","example":"The government declared a state of emergency after the severe flood. 政府在严重洪灾后宣布进入紧急状态。","derivative":"declaration /ˌdek ləˈreɪʃn/ n. 宣布；declarative /dɪˈklærətɪv/ adj. 陈述的"},{"id":1366,"word":"declaration","pronunciation":"/deklə'reɪʃn/","meaning":"n.公告;宣言","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1367,"word":"declarative","pronunciation":"/d'klærətɪv/","meaning":"adj.陈述的","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1368,"word":"allege","pronunciation":"/əledʒ/","meaning":"v.(未经证实的)宣称,指控","unit":5,"lesson":3,"seq":22,"isStar":false,"memo":"【构词】al-（加强）+ leg（法律，词根leg-表‘说’）→‘正式开口说’，但没证据！就像同学说‘我看见他抄答案’——allege，不等于 proven！","example":"The report alleges serious misconduct by senior management. 报告指控高级管理层存在严重失当行为。","derivative":"allegation /ˌæləˈɡeɪʃ(ə)n/ n.断言；指控"},{"id":1369,"word":"allegation","pronunciation":"/æləˈɡeɪʃn/","meaning":"n.(无证据的)说法,指控","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1370,"word":"alleged","pronunciation":"/əledʒd/","meaning":"adj.被指称的,涉嫌的","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1371,"word":"allegedly","pronunciation":"/əˈledʒɪdli/","meaning":"adv.据说","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1372,"word":"pledge","pronunciation":"/pledʒ/","meaning":"v.作保证,发誓 n.保证,诺言","unit":5,"lesson":3,"seq":23,"isStar":false,"memo":"ple-（please请）+ dge（像‘姐’）→‘请姐’作证！拉钩发誓，郑重承诺！","example":"The company pledged to reduce its carbon emissions by 2030. 该公司承诺于2030年前降低碳排放量。"},{"id":1373,"word":"swear","pronunciation":"/sweə(r)/","meaning":"v.发誓,宣誓;诅咒","unit":5,"lesson":3,"seq":24,"isStar":false},{"id":1374,"word":"vow","pronunciation":"/vaʊ/","meaning":"n.誓言;誓约 v.发誓,立誓","unit":5,"lesson":3,"seq":25,"isStar":false},{"id":1375,"word":"assure","pronunciation":"/əˈʊə(r); əˈʃɔː(r)/","meaning":"v.使确信,向……保证;确保","unit":5,"lesson":3,"seq":26,"isStar":false,"memo":"【构词】a（加强）+ sure（确定）→ 双sure！向你打包票‘sure sure’，保证没跑儿～","example":"The manager assured employees that layoffs would not affect their departments. 经理向员工保证裁员不会影响他们的部门。","derivative":"assurance /ə'ʃʊərəns/ n.保证; reassuring /ˌreə'ʃʊərɪŋ/ adj.使人安心的"},{"id":1376,"word":"assurance","pronunciation":"/əˈʃərəns; əˈʃɔːrəns/","meaning":"n.保证,确信","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1377,"word":"reassure","pronunciation":"/ˌriːəˈʊə(r); ˌriːəˈʃː(r)/","meaning":"v.使……安心;打消……的疑虑","unit":5,"lesson":3,"seq":27,"isStar":false,"memo":"re-（再）+assure（确保）→‘再保你稳’！就像妈拍拍你肩：‘别慌，妈在！’——双重保险，焦虑秒变安心。","example":"The doctor reassured her that the test results were normal. 医生让她放心，检查结果正常。","derivative":"reassurance /riːəˈʃʊərəns/ n. 安慰；放心"},{"id":1378,"word":"reassurance","pronunciation":"/ˌriːəˈʃʊərəns; riːəˈʃɔːrəns/","meaning":"n.(能消除疑虑等的)肯定,保证","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1379,"word":"ensure","pronunciation":"/ɪnʃʊə(r); ɪnˈʃɔː(r)/","meaning":"v.保证,确保","unit":5,"lesson":3,"seq":28,"isStar":false,"memo":"en-（使）+ sure（确定）→ 让某事‘sure’起来！不是‘insure’（投保），别被‘保险’带跑偏～","example":"The university uses AI tools to ensure exam fairness and prevent cheating. 该校使用人工智能工具确保考试公平并防止作弊。","derivative":"assurance /ə'ʃʊərəns/ n.保证；确信"},{"id":1380,"word":"insure","pronunciation":"/ɪnʃʊə(r); ɪnˈʃɔː(r)/","meaning":"v.投保,给……保险;接受投保,承保","unit":5,"lesson":3,"seq":29,"isStar":false,"memo":"in（进入）+ sure（稳）→ 让风险‘进’来变‘稳’！投保险就是花钱买心安——sure不等于sure，但insure之后，sure多了！","example":"Students are advised to insure their laptops against accidental damage. 学生被建议为笔记本电脑投保意外损坏险。","derivative":"insurance /ɪnˈʃʊərəns/ n.保险；insurer /ɪnˈʃʊərə/ n.保险公司"},{"id":1381,"word":"insurance","pronunciation":"/ɪnˈʃərəns; ɪnʃɔːrəns/","meaning":"n.保险;保险费","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1382,"word":"guarantee","pronunciation":"/ˌɡærəntiː/","meaning":"n.保证;担保;保证金;抵押品 v.保证;担保","unit":5,"lesson":3,"seq":30,"isStar":false,"memo":"guar-（=war，战争）+ -antee（保证人）→战前签‘保命协议’！v./n.保证，带法律效力的‘不翻车承诺’。","example":"The warranty guarantees repair service for three years. 保修期保证三年内提供维修服务。","derivative":"guarantor /gær(ə)n'tɔːr/ n. 担保人"},{"id":1383,"word":"persuade","pronunciation":"/pəˈsweɪd/","meaning":"v.劝说,说服;使信服","unit":5,"lesson":3,"seq":31,"isStar":false,"memo":"per-（彻底）+ suade（劝→拉丁suadere）→‘彻底劝到服’！记成‘怕说服’——怕你嘴太强，一说我就缴械投降。","example":"She persuaded the committee to fund the environmental project. 她说服委员会为环保项目提供资金。","derivative":"persuasion /pəˈsweɪʒn/ n.说服；persuasive /pəˈsweɪsɪv/ adj.有说服力的"},{"id":1384,"word":"persuasion","pronunciation":"/pəˈsweɪʒn/","meaning":"n.说服;劝说","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1385,"word":"persuasive","pronunciation":"/pəˈsweɪsɪv/","meaning":"adj.有说服力的","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1386,"word":"promise","pronunciation":"/prɒmɪs/","meaning":"n.保证;诺言,承诺;迹象 v.承诺;答应;保证;预示……可能发生","unit":5,"lesson":3,"seq":32,"isStar":false},{"id":1387,"word":"promising","pronunciation":"/ˈprɒmɪsɪŋ/","meaning":"adj.大有希望的,很有前途的","unit":5,"lesson":3,"seq":33,"isStar":false},{"id":1388,"word":"premise","pronunciation":"/ˈpremɪs/","meaning":"n.前提","unit":5,"lesson":3,"seq":34,"isStar":false},{"id":1389,"word":"compromise","pronunciation":"/ˈkɒmprəmaɪz/","meaning":"n.妥协,折中,折中办法(协议) v.妥协,让步;放弃(原则)","unit":5,"lesson":3,"seq":35,"isStar":false},{"id":1390,"word":"infinite","pronunciation":"/'ɪnfɪnət/","meaning":"adj.无限的,无穷的","unit":5,"lesson":3,"seq":36,"isStar":false},{"id":1391,"word":"infinity","pronunciation":"/ɪn'fɪnəti/","meaning":"n.无限,无穷","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1392,"word":"infinitive","pronunciation":"/ɪn'fɪnətɪv/","meaning":"n.不定式","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1393,"word":"finite","pronunciation":"/'faɪnaɪt/","meaning":"adj.有限制的,有限的;限定的","unit":5,"lesson":3,"seq":37,"isStar":false},{"id":1394,"word":"define","pronunciation":"/dɪ'faɪn/","meaning":"v.解释,说明;给……下定义;阐明,界定","unit":5,"lesson":3,"seq":38,"isStar":false,"memo":"de-（完全）+fine（界限）→给概念划出‘完全清晰的界限’，就是下定义！","example":"Philosophers continue to define what constitutes genuine artificial intelligence. 哲学家们仍在界定何为真正的人工智能。","derivative":"definition /ˌdefɪˈnɪʃn/ n. 定义；definitive /dɪˈfɪnətɪv/ adj. 最权威的"},{"id":1395,"word":"definite","pronunciation":"/'defɪnət/","meaning":"adj.肯定的,确定的;明显的,清楚的","unit":5,"lesson":3,"seq":39,"isStar":false},{"id":1396,"word":"definitely","pronunciation":"/'defɪnətlɪ/","meaning":"adv.确切地;明确地;清楚地","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1397,"word":"definition","pronunciation":"/ˌdefɪ'nɪʃn/","meaning":"n.解释;定义","unit":5,"lesson":3,"seq":40,"isStar":false},{"id":1398,"word":"indefinite","pronunciation":"/ɪn'defɪnət/","meaning":"adj.模糊不清的,不明确的;无限期的","unit":5,"lesson":3,"seq":41,"isStar":false},{"id":1399,"word":"refine","pronunciation":"/rɪ'faɪn/","meaning":"v.精炼,提炼;改进","unit":5,"lesson":3,"seq":42,"isStar":false,"memo":"拆解：re-（再次）+ fine（精细）→ 再次弄‘精细’！谐音‘瑞饭’——米其林大厨瑞饭（再饭）？不，是再‘炼’饭（精炼食材）！","example":"Engineers continue to refine the algorithm for better accuracy. 工程师持续优化算法以提高准确性。","derivative":"refinement /rɪ'faɪnmənt/ n.改进；精炼"},{"id":1400,"word":"refinement","pronunciation":"/rɪ'faɪnmənt/","meaning":"n.精炼,提炼,提纯;改进,改善","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1401,"word":"refinery","pronunciation":"/rɪ'faɪnər/","meaning":"n.炼油厂,提炼厂,精炼厂,精制厂","unit":5,"lesson":3,"seq":43,"isStar":false},{"id":1402,"word":"distil(l)","pronunciation":"/dɪ'stɪl/","meaning":"v.蒸馏;用蒸馏法提取;提炼;浓缩","unit":5,"lesson":3,"seq":44,"isStar":false},{"id":1403,"word":"confine","pronunciation":"/kən'faɪn/","meaning":"v.约束,限定,限制;使离不开","unit":5,"lesson":3,"seq":45,"isStar":false,"memo":"【谐音+构词】'康芬'→康师傅方便面被‘限定口味’！con-（共同）+ fine（界限）→一起划条线，把你框住。","example":"Remote learning should not confine students' creativity to digital platforms. 远程学习不应将学生的创造力局限在数字平台上。","derivative":"confinement /kənˈfaɪnmənt/ n.限制；confined /kənˈfaɪnd/ adj.受限的"},{"id":1404,"word":"confinement","pronunciation":"/kən'fanmənt/","meaning":"n.禁闭,监禁,关押","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1405,"word":"restrain","pronunciation":"/r'streɪn/","meaning":"v.阻止,制止,约束","unit":5,"lesson":3,"seq":46,"isStar":false,"memo":"【构词】re-(再)+strain(拉紧)→反复勒紧缰绳→抑制冲动，像拽住狂奔的马！","example":"Judges must restrain personal bias when evaluating evidence. 法官在评估证据时必须克制个人偏见。","derivative":"restraint /rɪˈstreɪnt/ n.抑制；约束"},{"id":1406,"word":"restraint","pronunciation":"/rɪ'streɪnt/","meaning":"n.约束力;限制,克制","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1407,"word":"constrain","pronunciation":"/kən'stren/","meaning":"v.阻止;限制","unit":5,"lesson":3,"seq":47,"isStar":false},{"id":1408,"word":"constraint","pronunciation":"/kən'streɪnt/","meaning":"n.限制,限定,约束","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1409,"word":"stifle","pronunciation":"/'stafl/","meaning":"v.阻止,抑制,压抑(感情);(使)感到窒息","unit":5,"lesson":3,"seq":48,"isStar":false},{"id":1410,"word":"strain","pronunciation":"/streɪn/","meaning":"n.焦虑,紧张;负担;拉力 v.拉伤;竭力;用力推(或拉),拉紧;使过劳","unit":5,"lesson":3,"seq":49,"isStar":false,"memo":"st(联想 street)+rain(雨)→雨后街上变冷,我“拉紧”了衣服领子。","example":"The woman may be suffering from repetitive strain injury. 这位女士可能患有重复性劳损。"},{"id":1411,"word":"chill","pronunciation":"/tʃɪl/","meaning":"adj.寒冷的,冷飕飕的 n.寒冷;寒意","unit":5,"lesson":3,"seq":50,"isStar":false,"memo":"chi(联想“吃”)+ll(形似两支冰棍)→数九寒天,我吃了两支冰棍,“寒冷的”感觉直冲心底。","example":"A small fire was burning to take the chill off the room. 房间里生着一个小火炉驱寒。"},{"id":1412,"word":"chilly","pronunciation":"/'tʃɪli/","meaning":"adj.寒冷的;阴冷的","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1413,"word":"thermal","pronunciation":"/'θɜml/","meaning":"adj.热的,保暖的,温暖的","unit":5,"lesson":3,"seq":51,"isStar":false,"memo":"单词发音类似“塞毛”→天冷了,往衣服里面塞些毛可起到“保暖的”作用。","example":"The thermal springs are popular tourist attractions. 温泉是受欢迎的旅游景点。"},{"id":1414,"word":"cosy/cozy","pronunciation":"/'kəzi/","meaning":"adj.暖和舒适的;密切的,亲密无间的;轻易得到的,轻松的","unit":5,"lesson":3,"seq":52,"isStar":false},{"id":1415,"word":"cosily/cozily","pronunciation":"/'kəʊzɪli/","meaning":"adv.温暖舒适地;密切地","unit":5,"lesson":3,"seq":0,"isStar":true},{"id":1416,"word":"block","pronunciation":"/blɒk/","meaning":"n.大块;街区;大楼;阻碍物 v.阻碍;堵塞","unit":5,"lesson":4,"seq":1,"isStar":false,"memo":"谐音 单词发音类似“不唠嗑”→他俩不唠嗑了,因为有人“阻碍”了他们的交流。","example":"After today's heavy snow, many roads are still blocked. 今天下过大雪,很多道路仍然堵塞。"},{"id":1417,"word":"bloc","pronunciation":"/blɒk/","meaning":"n.集团,阵营","unit":5,"lesson":4,"seq":2,"isStar":false},{"id":1418,"word":"company","pronunciation":"/'kʌmpəni/","meaning":"n.公司;陪伴;剧团;同伴","unit":5,"lesson":4,"seq":3,"isStar":false,"example":"She'll have been with the company for 25 years next week. 到下周,她就在公司工作25年了。"},{"id":1419,"word":"accompany","pronunciation":"/ə'kʌmpəni/","meaning":"v.陪伴;伴随;为……伴奏","unit":5,"lesson":4,"seq":4,"isStar":false,"memo":"构词 ac-(=to)+company(陪伴)→陪伴(……去)→陪伴;伴随","example":"Bad weather is accompanied by strong winds. 坏天气伴有强风。"},{"id":1420,"word":"companion","pronunciation":"/kəm'pænjən/","meaning":"n.伴侣,同伴;陪伴","unit":5,"lesson":4,"seq":5,"isStar":false,"memo":"对照 公司(company)的陪伴(companion)使我梦想渐近,未来可期。","example":"He was my companion on the journey. 他是我旅途中的伙伴。","derivative":"companionship /kəmˈpænjənʃp/ n.友情,交谊"},{"id":1421,"word":"companionship","pronunciation":"/kəm'pænjənɪp/","meaning":"n.友情,交谊","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1422,"word":"multiply","pronunciation":"/'mʌltplaɪ/","meaning":"v.乘;(使)成倍增加;(使)大大增加; 繁殖","unit":5,"lesson":4,"seq":6,"isStar":false,"memo":"联想 multi-(多)+ply(音似“扑来”)→多地扑来→繁殖","example":"A species must be able to multiply quickly in order to survive. 一个物种必须能够迅速繁殖才能生存。"},{"id":1423,"word":"multiplication","pronunciation":"/ˌmʌltɪplɪ'keɪʃn/","meaning":"n.乘;相乘;增加","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1424,"word":"multiple","pronunciation":"/'mʌltɪpl/","meaning":"adj.数量多的;多种的 n.倍数","unit":5,"lesson":4,"seq":7,"isStar":false,"example":"The shape appears multiple times within each painting.该形状在每幅画中出现多次。"},{"id":1425,"word":"multitude","pronunciation":"/'mltɪtjuːd/","meaning":"n.众多,大量;群众,民众","unit":5,"lesson":4,"seq":8,"isStar":false,"example":"The English language contains a multitude of words which are seldom used in ordinary conversation.英语中有大量在普通对话中很少使用的词汇。"},{"id":1426,"word":"affiliate","pronunciation":"/ə'fɪliet/","meaning":"n.附属机构,分公司 /ə'fɪlieɪt/ v.使隶属,使并入","unit":5,"lesson":4,"seq":9,"isStar":false,"memo":"联想 af-(=to)+fili(联想“费力”)+-ate(后缀)→使费力地依附到→附属机构;使隶属","example":"The World Chess Federation has affiliates in around 120 countries.世界国际象棋联合会在大约120个国家拥有附属机构。","derivative":"affiliation /əˌfɪli'eɪʃn/ n.隶属关系;隶属,从属"},{"id":1427,"word":"affiliation","pronunciation":"/əˌfli'eɪʃn/","meaning":"n.隶属关系;隶属,从属","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1428,"word":"auxiliary","pronunciation":"/ɔːg'zliəri/","meaning":"adj.辅助的;备用的 n.助动词;辅助人员","unit":5,"lesson":4,"seq":10,"isStar":false,"memo":"联想 aux(联想“奥克斯”)+i(我)+li(音似“里”)+-ary(后缀)→奥克斯空调在我屋里起到“辅助的”降温作用。","example":"Nursing auxiliaries provide basic care, but are not qualified nurses.助理护士提供基本护理,但不具备护士资格。"},{"id":1429,"word":"affix","pronunciation":"/ə'fɪks/","meaning":"n.词缀 v.粘上,贴上;附上","unit":5,"lesson":4,"seq":11,"isStar":false},{"id":1430,"word":"firm","pronunciation":"/fɜːm/","meaning":"n.商行,公司 adj.牢固的,坚固的; 坚定的,坚决的","unit":5,"lesson":4,"seq":12,"isStar":false,"memo":"对照 公司(firm)需要形成(form)一个牢固的(firm)支撑体系。","example":"I know that your firm has a very good reputation.我知道贵公司声誉很好。"},{"id":1431,"word":"affirm","pronunciation":"/əˈfɜːm/","meaning":"v.肯定属实;申明;断言","unit":5,"lesson":4,"seq":13,"isStar":false,"memo":"构词 af-(=to)+firm(坚定的)→对……是肯定的→肯定属实;断言","example":"Both sides affirmed their commitment to the ceasefire.双方均申明答应停火。","derivative":"affirmation /ˌæfə'meɪʃn/ n.断言;肯定\naffirmative /ə'fɜːmətɪv/ n.肯定;同意 adj.肯定的;同意的"},{"id":1432,"word":"affirmation","pronunciation":"/æfəˈmeɪʃn/","meaning":"n.断言;肯定","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1433,"word":"affirmative","pronunciation":"/əˈfɜːmətɪv/","meaning":"n.肯定;同意 adj.肯定的;同意的","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1434,"word":"enterprise","pronunciation":"/entəpraɪz/","meaning":"n.公司,企业","unit":5,"lesson":4,"seq":14,"isStar":false,"memo":"联想 enter(进来)+prise(联想 praise)→“公司”的老板一进来就表扬他。","example":"The middle class used to be loyal to the free enterprise system.中产阶级曾经对自由企业制度忠心耿耿。","derivative":"enterprising /'entəpraɪzɪŋ/ adj.有事业心的;有进取心的;有创业精神的\nentrepreneur /ˌɒntrəprə'nɜ(r)/ n.创业者,企业家\nentrepreneurial /ˌɒntrəprə'nɜːriəl/ adj.创业的;企业家的"},{"id":1435,"word":"enterprising","pronunciation":"/ˈentəpraɪzɪŋ/","meaning":"adj.有事业心的;有进取心的;有创 业精神的","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1436,"word":"entrepreneur","pronunciation":"/ˌntrəprəˈnɜː(r)/","meaning":"n.创业者,企业家","unit":5,"lesson":4,"seq":15,"isStar":false},{"id":1437,"word":"entrepreneurial","pronunciation":"/ˌɒntrəprəˈnɜːriəl/","meaning":"adj.创业的;企业家的","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1438,"word":"commerce","pronunciation":"/ˈkɒmɜs/","meaning":"n.商业,贸易","unit":5,"lesson":4,"seq":16,"isStar":false,"memo":"[联想] com-(都) + merce(音似“没死”)→商场如大海,一旦翻船就都会被淹没→商业,贸易","example":"During this decade new forms of commerce became commonplace in the US. 在这十年中,新的商业形式在美国变得司空见惯。","derivative":"commercial /kə'mɜːʃl/ n. 商业广告 adj. 商业的,贸易的\ncommercialise/-ize /kə'mɜːʃəlaɪz/ v.利用……牟利;商业化"},{"id":1439,"word":"commercial","pronunciation":"/kəˈmɜːʃl/","meaning":"n.商业广告 adj.商业的,贸易的","unit":5,"lesson":4,"seq":0,"isStar":true,"memo":"【谐音】‘康麦休尔’→超市里卖康师傅、麦当劳、休眠熊（？）→全是商业品牌！广告也叫commercial～","example":"The TV channel interrupted the documentary with three commercial breaks. 电视频道插播了三次广告打断了纪录片。","derivative":"commercialize /kəˈmɜːʃəlaɪz/ v.使商业化"},{"id":1440,"word":"commodity","pronunciation":"/kəmɒdəti/","meaning":"n.商品;有用的东西,有使用价值的 事物","unit":5,"lesson":4,"seq":17,"isStar":false,"example":"Money as a tangible commodity has largely been replaced by credit. 货币作为一种有形的商品在很大程度上已被信贷取代。"},{"id":1441,"word":"merchant","pronunciation":"/ˈmɜːtʃənt/","meaning":"n.商人,批发商","unit":5,"lesson":4,"seq":18,"isStar":false,"memo":"[谐音] 单词发音类似“摸钱他”→他是个“商人”,每天攒钱,和钱打交道。","example":"Venice was once a city of rich merchants. 威尼斯曾是富商云集的城市。","derivative":"merchandise /'mɜːtʃəndaɪs; 'mːtʃəndaz/ n. 商品,货品"},{"id":1442,"word":"merchandise","pronunciation":"/ˈmɜːtʃəndaɪs; ˈmɜtʃəndaɪz/","meaning":"n.商品,货品","unit":5,"lesson":4,"seq":19,"isStar":false,"memo":"merch（=market市场）+andise→市场上卖的东西！谐音‘卖钱的易死’——商品太卷，不卖钱就易死。","example":"Online platforms revolutionize how we browse merchandise. 在线平台彻底改变了我们浏览商品的方式。","derivative":"merchant /'mɜːtʃənt/ n.商人；零售商"},{"id":1443,"word":"sale","pronunciation":"/sel/","meaning":"n.出售,销售;销售量;特价销售","unit":5,"lesson":4,"seq":20,"isStar":false,"memo":"[对照] sell v.出售,售卖→sale n.","example":"Its production and sales reached record levels. 它的生产和销售量达到了创纪录的水平。"},{"id":1444,"word":"wholesale","pronunciation":"/ˈhəʊlseɪl/","meaning":"n.批发 adj.大规模的;批发的 adv.批量地","unit":5,"lesson":4,"seq":21,"isStar":false},{"id":1445,"word":"retail","pronunciation":"/ˈriːteɪl/","meaning":"n.零售 v.零售 adv.以零售方式","unit":5,"lesson":4,"seq":22,"isStar":false,"memo":"[构词] re-(再,重复) + tail(= cut,切,割)→重复切割单卖→零售","example":"It poses a potential threat to the retail business in the US. 这对美国的零售业务构成了潜在威胁。","derivative":"retailer /'riːteɪlə(r)/ n.零售商"},{"id":1446,"word":"retailer","pronunciation":"/ˈriteɪlə(r)/","meaning":"n.零售商","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1447,"word":"entail","pronunciation":"/ɪnˈtel/","meaning":"v.牵涉;需要,使必要","unit":5,"lesson":4,"seq":23,"isStar":false,"memo":"[联想] en-(使) + tail(切)→使切分成……的一部分→牵涉;使必要"},{"id":1448,"word":"afford","pronunciation":"/ə'fɔːd/","meaning":"v.买得起;(有时间)做;承担得起(后 果)","unit":5,"lesson":4,"seq":24,"isStar":false,"memo":"联想 af-(一再地)+ford(音似“福特”)→他一再地提福特车是因为“买得起”它。","example":"She can't afford the time for the trip. 她抽不出时间去旅行。","derivative":"affordable /əˈfɔːdəbl/ adj.便宜的；负担得起的 affordability /əfɔːrdəbɪləti/ n.负担能力"},{"id":1449,"word":"affordable","pronunciation":"/əˈfɔdəbl/","meaning":"adj.便宜的;负担得起的","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1450,"word":"affordability","pronunciation":"/əˌfɔːrdəˈbɪləti/","meaning":"n.负担能力","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1451,"word":"purchase","pronunciation":"/'pɜːtʃəs/","meaning":"n.买;购买的物品 v.买,购买","unit":5,"lesson":4,"seq":25,"isStar":false,"memo":"谐音 单词发音类似“破车子”→既然车子破旧了，那就“买”辆新的吧。","example":"The tickets can only be purchased in advance from our website. 门票只能在我们的网站上提前购买。"},{"id":1452,"word":"board","pronunciation":"/bɔːd/","meaning":"n.板,木板;董事会 v.登上(公共汽车,飞机等)","unit":5,"lesson":4,"seq":26,"isStar":false,"memo":"对照 黑板(blackboard)就是黑色的板(board)。","example":"He's on the board of directors. 他是董事会成员。","derivative":"corporate /ˈkɔːrpərət/ adj.公司的；团体的；全体的"},{"id":1453,"word":"corporation","pronunciation":"/ˌkɔpə'reɪʃn/","meaning":"n.(大)公司,企业","unit":5,"lesson":4,"seq":27,"isStar":false,"memo":"联想 cor-(联想 con-，一起)+por(音似“破”)+-ation(名词后缀)→“公司”领导要求大家一起攻破难关。","example":"The corporation is rejecting more and more candidates applying for jobs. 公司正在拒绝越来越多的求职者。"},{"id":1454,"word":"corporate","pronunciation":"/'kɔːpərət/","meaning":"adj.公司的;团体的;全体的","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1455,"word":"incorporate","pronunciation":"/n'kɔːpəreɪt/","meaning":"v.将……并入,包含","unit":5,"lesson":4,"seq":28,"isStar":false,"memo":"联想 in(入)+corporate(公司的)→使进入公司的里面→将……并入","example":"Many of your suggestions have been incorporated in the plan. 你的很多建议已被纳入计划中。","derivative":"incorporation /ɪnˌkɔːrpəˈreɪʃn/ n.纳入，合并；公司，团体组织"},{"id":1456,"word":"incorporation","pronunciation":"/ɪnˌkɔːpə'reɪʃn/","meaning":"n.纳入,合并;公司;团体组织","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1457,"word":"compete","pronunciation":"/kəm'piːt/","meaning":"v.参加比赛;竞争","unit":5,"lesson":4,"seq":29,"isStar":false,"memo":"联想 com(联想 company)+pete(联想 pk)→公司之间pk，就是“竞争”。","derivative":"competitor competition competitive competent competence versus cooperate cooperation cooperative collaborate elaborate elaboration operate operative operation operational operator incorporate incorporation corporate corporation board"},{"id":1458,"word":"competitor","pronunciation":"/kəm'petɪtə(r)/","meaning":"n.竞争者","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1459,"word":"competition","pronunciation":"/ˌkɒmpə'tɪʃn/","meaning":"n.竞争;比赛","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1460,"word":"competitive","pronunciation":"/kəm'petətɪv/","meaning":"adj.竞争的;有竞争力的;好胜的","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1461,"word":"competent","pronunciation":"/'kɒmptənt/","meaning":"adj.有能力的,能胜任的","unit":5,"lesson":4,"seq":30,"isStar":false,"memo":"com-（一起）+pet（寻求，如petition）+ent→大家一起‘求’出来的能力？不！其实是com（完全）+pet（追求）+ent→追求到位=胜任！","example":"A competent engineer must balance theory and practice. 合格的工程师必须兼顾理论与实践。","derivative":"competence /'kɒmpɪtəns/ n.能力；胜任"},{"id":1462,"word":"competence","pronunciation":"/'kɒmpɪtəns/","meaning":"n.能力;技能","unit":5,"lesson":4,"seq":31,"isStar":false},{"id":1463,"word":"versus","pronunciation":"/'vɜːsəs/","meaning":"prep.(比赛或诉讼中)……对……","unit":5,"lesson":4,"seq":32,"isStar":false},{"id":1464,"word":"operate","pronunciation":"/'ɒpəreɪt/","meaning":"v.经营,营业;操作;动手术","unit":5,"lesson":4,"seq":33,"isStar":false},{"id":1465,"word":"operative","pronunciation":"/'ɒpərətɪv/","meaning":"n.工人,(尤指)技术工人;特工 adj.运作中的;可使用的","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1466,"word":"operation","pronunciation":"/ˌɒpə'reɪʃn/","meaning":"n.手术;(有组织的)活动,行动;企业,公司","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1467,"word":"operational","pronunciation":"/ˌɒpə'reɪʃənl/","meaning":"adj.操作的,运转的,运营的;业务的","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1468,"word":"operator","pronunciation":"/'ɒpəreɪtə(r)/","meaning":"n.操作人员","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1469,"word":"cooperate","pronunciation":"/kəʊ'ɒpəret/","meaning":"v.合作,协作","unit":5,"lesson":4,"seq":34,"isStar":false,"memo":"构词 co-(一起)+operate(经营)→合作","example":"We must cooperate and work toward common goals. 我们必须合作,朝着共同的目标努力。","derivative":"cooperation /kəʊˌɒpəˈreɪʃn/ n.合作,协作\ncooperative /kəˈɒpərətv/ n.合作企业;合作性组织 adj.合作的,同心协力的;协助的,配合的"},{"id":1470,"word":"cooperation","pronunciation":"/kəʊˌpə'reɪʃn/","meaning":"n.合作,协作","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1471,"word":"cooperative","pronunciation":"/kəʊ'ɒpərətɪv/","meaning":"n.合作企业;合作性组织 adj.合作的,同心协力的;协助的,配合的","unit":5,"lesson":4,"seq":35,"isStar":false,"memo":"构词 co-(一起)+operat(e)(经营)+-ive (后缀)→一起经营的→合作的(企业)","example":"The local fishing cooperative decided to reduce its catch. 当地渔业合作社决定减少捕鱼量。"},{"id":1472,"word":"collaborate","pronunciation":"/kə'læbəreɪt/","meaning":"v.合作,协作","unit":5,"lesson":4,"seq":36,"isStar":false,"memo":"构词 col-(=con-,一起)+labor(劳动)+ -ate(动词后缀)→一起劳动→合作,协作","example":"We have collaborated on many projects over the years. 这些年来我们合作搞了许多项目。","derivative":"collaboration /kəˌlæbəˈreʃn/ n.合作,协作\ncollaborative /kəˈlæbərətɪv/ adj.合作的,协作的,协力的"},{"id":1473,"word":"collaboration","pronunciation":"/kəˌlæbəˈreɪʃn/","meaning":"n.合作,协作","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1474,"word":"collaborative","pronunciation":"/kəˈlæbərətɪv/","meaning":"adj.合作的,协作的,协力的","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1475,"word":"elaborate","pronunciation":"/ˈlæbərət/","meaning":"adj.精心制作的;详细的 /ɪˈlæbəreɪt/ v.详细描述;精心制作","unit":5,"lesson":4,"seq":37,"isStar":false,"memo":"联想 e-(出)+labor(劳动)+-ate(后缀)→辛苦做出(的)→精心制作(的)","example":"The elaborate patterns were believed to offer protection against evil. 人们相信这些精心制作的图案可以保护人们对抗邪恶。","derivative":"elaboration /ɪˌlæbəˈreʃn/ n.精心制作(或计划);精致;详尽阐述"},{"id":1476,"word":"elaboration","pronunciation":"/ɪˌlæbəˈreɪʃn/","meaning":"n.精心制作(或计划);精致;详尽阐述","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1477,"word":"subsidy","pronunciation":"/ˈsʌbsədi/","meaning":"n.补贴,补助金,津贴","unit":5,"lesson":4,"seq":38,"isStar":false,"memo":"联想 sub(联想“叔伯”) + si(联想“死”) + dy→叔伯在战争中牺牲，国家给家属发放了一些“补贴”。","example":"Renewable energy deserves a subsidy. 可再生能源应该得到补贴。","derivative":"subsidise/-ize /'sʌbsdaɪz/ v.资助,补助,给……发津贴"},{"id":1478,"word":"subsidise/-ize","pronunciation":"/ˈsʌbsɪdaɪz/","meaning":"v.资助,补助,给……发津贴","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1479,"word":"allowance","pronunciation":"/əˈlaʊəns/","meaning":"n.津贴,补贴;零用钱","unit":5,"lesson":4,"seq":39,"isStar":false,"memo":"联想 allow(允许) + an(一) + ce(联想“侧”) →领导允许员工在办公室一侧领“津贴”。","example":"The job-seekers’ allowance has met their actual needs. 求职者津贴满足了他们的实际需要。"},{"id":1480,"word":"bonus","pronunciation":"/ˈbəʊnəs/","meaning":"n.奖金,红利;意外收获,额外的好处","unit":5,"lesson":4,"seq":40,"isStar":false,"memo":"联想 bo(形似 60) + nus(联想 nuts)→公司发了 60 包坚果作为大家的年终“奖金”。","example":"The firm recognised his outstanding work by giving him a bonus. 公司通过给他发放一笔奖金来认可他出色的工作表现。"},{"id":1481,"word":"dole","pronunciation":"/dəʊl/","meaning":"n.失业救济金 v.(~out)发放,发给;施舍","unit":5,"lesson":4,"seq":41,"isStar":false},{"id":1482,"word":"dividend","pronunciation":"/ˈdɪvɪdend/","meaning":"n.红利;股息,股利","unit":5,"lesson":4,"seq":42,"isStar":false},{"id":1483,"word":"privilege","pronunciation":"/ˈprɪvəlɪdʒ/","meaning":"n.特殊待遇;权势 v.给予特权;特别优待","unit":5,"lesson":4,"seq":43,"isStar":false,"memo":"联想 pri-(联想 pre-,提前) + vi(音似“为”) + le(联想“了”) + ge(联想“哥”)→为了让哥哥满意，提前给他“特殊待遇”。","example":"The prisoner has been deprived of many privileges that average citizens enjoy. 这个囚犯被剥夺了普通公民享有的许多优待。"},{"id":1484,"word":"privileged","pronunciation":"/ˈprɪvəlɪdʒd/","meaning":"adj.有特权的,受特别优待的;荣幸的","unit":5,"lesson":4,"seq":44,"isStar":false},{"id":1485,"word":"avenue","pronunciation":"/ˈævənju:/","meaning":"n.大街;林荫道","unit":5,"lesson":4,"seq":45,"isStar":false,"memo":"a(一个)+venue(联想 venus,维纳斯)→我今天在“大街”上遇见了一个像维纳斯一样美丽的人。","example":"He walked up Fifth Avenue to clear his head. 他沿着第五大道走了走,好让大脑清醒清醒。"},{"id":1486,"word":"revenue","pronunciation":"/revənju:/","meaning":"n.税收收入;收入,收益","unit":5,"lesson":4,"seq":46,"isStar":false,"memo":"re(字母音似“阿姨”)+venue(联想 venus,维纳斯)→阿姨想变成像维纳斯一样美丽的女人,于是利用“收入”提升自己的形象。","example":"Financial incentives ensure companies meet specific revenue goals. 财务激励措施确保公司实现特定的收入目标。"},{"id":1487,"word":"inventory","pronunciation":"/ˈɪnvəntri/","meaning":"n.清单;存货,库存   v.开列清单","unit":5,"lesson":4,"seq":47,"isStar":false,"memo":"invent(发明)+-ory(表示场所的后缀)→他发明了一个放“存货”的智能仓库。","example":"The inventory will be disposed of over the next twelve weeks. 在未来的十二个星期中将进行清库存处理。"},{"id":1488,"word":"revenge","pronunciation":"/rˈvendʒ/","meaning":"n.报复,报仇   v.报复,为……报仇","unit":5,"lesson":4,"seq":48,"isStar":false,"memo":"re-(回)+venge(音似“文姬”,人名)→文姬被伤害了,多年后回来“报仇”。","example":"In the face of resentment, it is human to revenge. 面对怨恨,想要报复是人之常情。","derivative":"revengeful /rɪ'vendʒfʊl/ adj.渴望复仇的,一心报复的"},{"id":1489,"word":"revengeful","pronunciation":"/rɪˈvendʒfl/","meaning":"adj.渴望复仇的,一心报复的","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1490,"word":"bypass","pronunciation":"/ˈbaɪpɑ:s/","meaning":"n.旁路   v.避开,绕……而行;绕过(规定、制度或某个官员)","unit":5,"lesson":4,"seq":49,"isStar":false,"memo":"by-(在旁边)+pass(通过)→在旁边通过→避开;绕过","example":"More roads were built to bypass the heavy traffic. 为了避开繁忙的交通,修建了更多的道路。"},{"id":1491,"word":"whereby","pronunciation":"/weəbaɪ/","meaning":"adv.凭此,借以,由于","unit":5,"lesson":4,"seq":50,"isStar":false,"example":"He gave me a pass whereby I would be allowed into the conference. 他给了我一张通行证,我可以凭此参加这场会议。"},{"id":1492,"word":"underlying","pronunciation":"/ˌʌndəˈlaɪŋ/","meaning":"adj.根本的;潜在的,隐含的","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1493,"word":"underline","pronunciation":"/ˌʌndəˈlaɪn/","meaning":"v.在(词语等下)画线;强调,使突出","unit":5,"lesson":4,"seq":54,"isStar":false,"example":"It underlines just how much things have changed in the last generation. 这突显了上一代人的生活发生了多么大的变化。"},{"id":1494,"word":"undermine","pronunciation":"/ˌʌndəmaɪn/","meaning":"v.逐渐削弱;从根基处破坏","unit":5,"lesson":4,"seq":55,"isStar":false,"memo":"（构词）under(在……下面) + mine(挖掘) → 在下方挖掘 → 从根基处破坏","example":"In fact, they do much to undermine the teaching. 事实上，他们做了很多损害教学的事情。"},{"id":1495,"word":"undergo","pronunciation":"/ˌʌndəˈɡə/","meaning":"v.经历,遭受","unit":5,"lesson":4,"seq":56,"isStar":false,"memo":"（构词）under(在……下面) + go(走) → 在下面走过 → 经历，遭受","example":"Some children undergo a complete transformation when they become teenagers. 一些儿童进入青春期会完全变成另一个人。"},{"id":1496,"word":"undertake","pronunciation":"/ʌndəˈtek/","meaning":"v.承担,担任;从事;答应","unit":5,"lesson":4,"seq":57,"isStar":false,"memo":"（构词）under(在……下面) + take(拿着) → 在下边拿着 → 承担","example":"The directors of the company refused to undertake such a risky venture. 公司董事拒绝承担这样一个高风险的经营项目。"},{"id":1497,"word":"deadline","pronunciation":"/ˈdedlan/","meaning":"n.截止日期,最后期限","unit":5,"lesson":4,"seq":58,"isStar":false,"memo":"（构词）dead(死) + line(线) → 死亡的线，禁止越过 → 截止日期","example":"This deadline will be extended only in exceptional circumstances. 只有在特殊情况下才会延长最后期限。"},{"id":1498,"word":"guideline","pronunciation":"/ˈɡaɪdlaɪn/","meaning":"n.指导方针,指导原则,行动纲领,准则","unit":5,"lesson":4,"seq":59,"isStar":false,"memo":"（构词）guide(指导) + line(线) → 指导原则，准则","example":"Those guidelines are outdated and extremely inadequate. 那些指导方针已经过时，而且极不充分。"},{"id":1499,"word":"skyline","pronunciation":"/skaɪlaɪn/","meaning":"n.轮廓线,天际线","unit":5,"lesson":4,"seq":60,"isStar":false},{"id":1500,"word":"streamline","pronunciation":"/striːmlaɪn/","meaning":"v.使成流线型;使(系统、机构等)效率更高;精简","unit":5,"lesson":4,"seq":61,"isStar":false,"memo":"（构词）stream(流) + line(线) → 使成流线型","example":"We need to streamline the production process. 我们需要简化生产流程。"},{"id":1501,"word":"align","pronunciation":"/əˈlaɪn/","meaning":"v.(尤指)成一直线;使一致;与……结盟","unit":5,"lesson":4,"seq":62,"isStar":false,"memo":"（联想）a-(表示强调) + lign(联想 line, 线) → 成一直线；使一致","example":"The house is aligned along an east-west axis. 这幢房屋沿东西轴线成一直线。","derivative":"alignment /əlaɪnmənt/ n. 排成直线；结盟"},{"id":1502,"word":"alignment","pronunciation":"/əlaɪnmənt/","meaning":"n.排成直线;结盟","unit":5,"lesson":4,"seq":0,"isStar":true},{"id":1503,"word":"recipe","pronunciation":"/'resəpi/","meaning":"n.烹饪法,食谱;秘诀","unit":6,"lesson":1,"seq":1,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + ci(联想“此”) + pe(音似“批”) → 此批菜是新上的，阿姨的“食谱”上没有。","example":"What's her recipe for success? 她成功的秘诀是什么？","derivative":"形近 reciprocal"},{"id":1504,"word":"reciprocal","pronunciation":"/rɪ'sɪprəkəl/","meaning":"adj.互惠的,相互的","unit":6,"lesson":1,"seq":2,"isStar":false,"memo":"对照 美食社区里，大家本着互惠的(reciprocal)精神分享食谱(recipe)。","example":"The two colleges have a reciprocal arrangement. 两所学院有一项互惠协定。"},{"id":1505,"word":"edible","pronunciation":"/'edəbl/","meaning":"adj.可以食用的","unit":6,"lesson":1,"seq":3,"isStar":false,"memo":"谐音 单词发音类似“俺爹饱”→俺爹食用了太多食物，吃饱了→可以食用的","example":"It is said seaweed is edible. 据说，海藻是可以吃的。"},{"id":1506,"word":"poison","pronunciation":"/'pɔɪzn/","meaning":"n.毒药,毒素 v.毒害,下毒","unit":6,"lesson":1,"seq":4,"isStar":false,"memo":"谐音 单词发音类似“泼一身”→他被泼了一身的“毒药”。","derivative":"扩 poisonous; 近义 toxic"},{"id":1507,"word":"poisonous","pronunciation":"/'pɔzənəs/","meaning":"adj.有毒的","unit":6,"lesson":1,"seq":0,"isStar":true,"example":"These mushrooms contain a deadly poison. 这些蘑菇含有效命毒素。"},{"id":1508,"word":"toxic","pronunciation":"/'tɒksɪk/","meaning":"adj.有毒的,引起中毒的","unit":6,"lesson":1,"seq":5,"isStar":false,"memo":"谐音 单词发音类似“逃课 seek”→他逃课去寻找一种“有毒的”奇异植物。","example":"This chemical is toxic to many forms of life. 这种化学品对很多生物都有毒害。"},{"id":1509,"word":"dioxide","pronunciation":"/daɪ'ɒksad/","meaning":"n.二氧化物","unit":6,"lesson":1,"seq":6,"isStar":false},{"id":1510,"word":"cocaine","pronunciation":"/kəʊ'keɪn/","meaning":"n.可卡因","unit":6,"lesson":1,"seq":7,"isStar":false},{"id":1511,"word":"fibre/-ber","pronunciation":"/'faɪbə(r)/","meaning":"n.(食物的)纤维素;(布绳的)纤维","unit":6,"lesson":1,"seq":8,"isStar":false},{"id":1512,"word":"vitamin","pronunciation":"/'vɪtəmɪn/","meaning":"n.维生素","unit":6,"lesson":1,"seq":9,"isStar":false,"example":"Even a modest vitamin shortfall can be harmful to your health. 即使是少量的维生素缺乏,也会对你的健康有害。"},{"id":1513,"word":"well-being","pronunciation":"/'wel biːɪŋ/","meaning":"n.健康,舒适,幸福;(国家的)繁荣","unit":6,"lesson":1,"seq":10,"isStar":false},{"id":1514,"word":"diet","pronunciation":"/'daɪət/","meaning":"n.日常饮食,日常食物 v.节食","unit":6,"lesson":1,"seq":11,"isStar":false,"example":"She's always dieting but she never seems to lose any weight. 她总是在节食,但她的体重好像并未减少。","derivative":"v.节食; dietary /'daɪətəri/ adj.饮食的"},{"id":1515,"word":"dietary","pronunciation":"/'daɪətəri/","meaning":"adj.饮食的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1516,"word":"calorie","pronunciation":"/'kæləri/","meaning":"n.卡路里,热量","unit":6,"lesson":1,"seq":12,"isStar":false},{"id":1517,"word":"nutrition","pronunciation":"/nju'trɪʃn/","meaning":"n.营养,滋养;营养学","unit":6,"lesson":1,"seq":13,"isStar":false,"memo":"单词发音类似“牛吹神”→“营养”品再牛也不能被吹成神药。","example":"Nutrition information is now provided on the back of most food products. 现在大多数食物产品的背面都附有营养信息。","derivative":"nutrient /'njutriənt/ n.营养素,营养物"},{"id":1518,"word":"nutrient","pronunciation":"/'njuːtriənt/","meaning":"n.营养素,营养物","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1519,"word":"nurture","pronunciation":"/'nɜːtʃə(r)/","meaning":"v.养育,培育,培养(感情等);帮助","unit":6,"lesson":1,"seq":14,"isStar":false,"example":"It's important to nurture a good working relationship. 培养良好的工作关系非常重要。"},{"id":1520,"word":"nourish","pronunciation":"/'nrɪʃ/","meaning":"v.滋养;培养(感情、观念或信念);保持,怀有","unit":6,"lesson":1,"seq":15,"isStar":false,"memo":"护士(nurse)对待病人像滋养(nourish)花一样。","example":"By investing in education, we nourish the talents of our children. 我们通过教育投资来培养孩子们的才能。","derivative":"nourishment /'nʌrɪʃmənt/ n.营养;营养品"},{"id":1521,"word":"nourishment","pronunciation":"/'nʌrɪʃmənt/","meaning":"n.滋养;营养品","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1522,"word":"foster","pronunciation":"/'fɒstə(r)/","meaning":"v.促进,培养;抚育,照料","unit":6,"lesson":1,"seq":16,"isStar":false,"memo":"fo(音似 four) + ster(联想 sister)→爸爸妈妈把四个姐妹“培养”得很好。","example":"They have fostered over 60 children during the past ten years. 在过去10年间,他们抚育了60多个孩子。"},{"id":1523,"word":"rear","pronunciation":"/rɪə(r)/","meaning":"v.抚养,培养 adj.后面的 n.后面","unit":6,"lesson":1,"seq":17,"isStar":false,"memo":"rea(联想 real) + r(形似花)→他衣服的“后面”真的有朵花。","derivative":"adj.后面的 n.后面"},{"id":1524,"word":"cultivate","pronunciation":"/'kʌltiveɪt/","meaning":"v.耕作;培育,培养","unit":6,"lesson":1,"seq":18,"isStar":false,"memo":"[对照] 为了使孩子们有文化(culture),家长和老师都需要用心培养(cultivate)他们。","example":"Humanistic thinking helps cultivate students' creativity. 人文思维有助于培养学生的创造力。","derivative":"cultivation /ˌkʌltɪˈveɪʃn/ n.耕种,种植;(品质或技巧的)培养"},{"id":1525,"word":"cultivation","pronunciation":"/ˌkʌltɪ'veɪʃn/","meaning":"n.耕种,种植;(品质或技巧的)培养","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1526,"word":"breed","pronunciation":"/briːd/","meaning":"v.饲养,培育;孕育","unit":6,"lesson":1,"seq":19,"isStar":false,"memo":"[谐音] 单词发音类似“哺育的”→饲养,培育;孕育","example":"The rabbits are bred for their long coats. 饲养兔子是为了获取它们的长毛。"},{"id":1527,"word":"pasta","pronunciation":"/'pæstə/","meaning":"n.意大利面食","unit":6,"lesson":1,"seq":20,"isStar":false},{"id":1528,"word":"pastry","pronunciation":"/'peɪstri/","meaning":"n.油酥面团;油酥糕点","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1529,"word":"beverage","pronunciation":"/'bevərɪdʒ/","meaning":"n.(除水以外的)饮料","unit":6,"lesson":1,"seq":21,"isStar":false,"memo":"[联想] be(是)+ver(音似“我”)+age(年龄)→这种“饮料”是我这个年龄可以喝的。","example":"Beer is a beverage of the remotest time. 啤酒是一种最古老的饮料。"},{"id":1530,"word":"cocktail","pronunciation":"/'kɒkteɪl/","meaning":"n.鸡尾酒","unit":6,"lesson":1,"seq":22,"isStar":false},{"id":1531,"word":"cafeteria","pronunciation":"/ˌkæfə'tɪəriə/","meaning":"n.自助餐厅,自助食堂","unit":6,"lesson":1,"seq":23,"isStar":false,"example":"The food served in the cafeteria usually lacks variety. 自助餐厅供应的食物通常缺乏多样性。"},{"id":1532,"word":"relish","pronunciation":"/'relʃ/","meaning":"n.享受,乐趣;调味汁 v.喜爱,喜欢","unit":6,"lesson":1,"seq":24,"isStar":false,"memo":"[联想] re(字母音似“阿姨”)+li(联想“立”)+sh(音似“试”)→阿姨一看到这件衣服立刻来试穿,说明她很“喜欢”这件衣服。","example":"The three men ate with relish. 这三个人吃得津津有味。"},{"id":1533,"word":"scent","pronunciation":"/sent/","meaning":"n.香味;臭气,气味 v.闻到;预感","unit":6,"lesson":1,"seq":25,"isStar":false,"memo":"[对照] 他按下香薰机开关,香味(scent)便向四周发送(sent)。","example":"The dog scented a rabbit. 狗闻到了兔子的气味。"},{"id":1534,"word":"perfume","pronunciation":"/'pɜːfjuːm/","meaning":"n.香水;芳香;香料","unit":6,"lesson":1,"seq":26,"isStar":false,"memo":"[联想] per(每一)+fu(联想“服”)+me(我)→每一次为客户服务,我都向他们推荐这款“香水”。","example":"She always puts a bit of perfume behind her ears in the morning. 早上她总是在耳后擦点香水。"},{"id":1535,"word":"fragrant","pronunciation":"/'freɪɡrənt/","meaning":"adj.香的,芳香的","unit":6,"lesson":1,"seq":27,"isStar":false},{"id":1536,"word":"fragrance","pronunciation":"/'freɪɡrəns/","meaning":"n.香气;香味","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1537,"word":"odo(u)r","pronunciation":"/'əʊdə(r)/","meaning":"n.(尤指难闻的)气味;臭味","unit":6,"lesson":1,"seq":28,"isStar":false},{"id":1538,"word":"odorous","pronunciation":"/'əʊdərəs/","meaning":"adj.有气味的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1539,"word":"territory","pronunciation":"/'terətri/","meaning":"n.领土;地盘","unit":6,"lesson":1,"seq":29,"isStar":false,"memo":"[联想] te(联想“特”)+(r)ri(联想“日”)+t(联想“提”)+-ory(表示地方的后缀)→特别的日子里提到的地方是自己的“领土”。","example":"If you go into a shark's territory and threaten it, it might bite you. 如果你进入鲨鱼的领地并威胁到它,它可能会咬你。","derivative":"territorial /ˌterə'tɔːriəl/ adj.领土的;领域性的"},{"id":1540,"word":"territorial","pronunciation":"/ˌterə'tɔːriəl/","meaning":"adj.领土的;领域性的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1541,"word":"dormitory","pronunciation":"/'dɔːmətri/","meaning":"n.集体宿舍;学生宿舍","unit":6,"lesson":1,"seq":30,"isStar":false,"memo":"[联想] dor(音似“捣”)+m(联想“门”)+it+-ory(表示地方的后缀)→晚上宿管阿姨把门锁了,学生回“集体宿舍”要捣(敲)门。","example":"The dormitory for the soldiers is well-organised and clean. 士兵们的集体宿舍井井有条且干净。"},{"id":1542,"word":"lavatory","pronunciation":"/'lævətri/","meaning":"n.洗手间,厕所","unit":6,"lesson":1,"seq":31,"isStar":false,"memo":"[联想] la(联想“拉”)+va(音似“我”)+t(联想“吐”)+-ory(表示地方的后缀)→我吃坏东西拉肚子,还一直呕吐,赶紧跑去“洗手间”。","example":"The nearest public lavatory is at the station. 最近的公共厕所在车站。"},{"id":1543,"word":"gallery","pronunciation":"/'ɡæləri/","meaning":"n.画廊;走廊","unit":6,"lesson":1,"seq":32,"isStar":false,"memo":"[联想] gall(音似“盖了”)+-ery(表示地方的后缀)→他盖了很长的一个地方,用作“画廊”。","example":"He declined a job offer from the gallery. 他拒绝了画廊的工作邀请。"},{"id":1544,"word":"grocery","pronunciation":"/'ɡrəʊsəri/","meaning":"n.食品杂货店","unit":6,"lesson":1,"seq":33,"isStar":false,"memo":"[联想] gro(音似“割肉”)+c(联想“车”)+-ery(表示地方的后缀)→我开车去“食品杂货店”割一些肉。","example":"Every weekend, he goes to the grocery to buy some meat. 每个周末,他都会去食品杂货店买一些肉。","derivative":"grocer /'grəʊsə(r)/ n.食物杂货商;食物杂货店"},{"id":1545,"word":"grocer","pronunciation":"/'ɡrəʊsə(r)/","meaning":"n.食物杂货商;食物杂货店","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1546,"word":"scenery","pronunciation":"/'sinəri/","meaning":"n.风景,景色;舞台布景","unit":6,"lesson":1,"seq":34,"isStar":false,"example":"He doesn't know how to describe the beautiful country scenery. 他不知道如何形容那美丽的乡村风景。"},{"id":1547,"word":"nursery","pronunciation":"/'nɜːsəri/","meaning":"n.托儿所,幼儿园;儿童房","unit":6,"lesson":1,"seq":35,"isStar":false,"memo":"[构词] nurs(e)(看护)+-ery(表示地方的后缀)→看护的地方→托儿所","example":"They'll need help getting up out of those little chairs in nursery school. 他们需要人帮忙才能从幼儿园的那些小椅子上站起来。"},{"id":1548,"word":"local","pronunciation":"/'ləʊkl/","meaning":"n.本地人 adj.当地的","unit":6,"lesson":1,"seq":36,"isStar":false,"memo":"谐音：单词发音类似“唠嗑”→我在外地想找个唠嗑的人，一问都是“本地人”。","example":"Television gave another push to the local economy. 电视又一次推动了当地的经济。","derivative":"locality /ləʊ'kæləti/ n.地区;地方,地点"},{"id":1549,"word":"locality","pronunciation":"/lə'kæləti/","meaning":"n.地区;地方,地点","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1550,"word":"locate","pronunciation":"/ləʊ'keɪt/","meaning":"v.找出……的具体位置;把……设置在;位于","unit":6,"lesson":1,"seq":37,"isStar":false,"memo":"谐音：单词发音类似“姥剋他”→姥姥剋(打)他,要先找到他→找出……的具体位置","example":"It is located in the eastern part of China. 它位于中国的东部。","derivative":"location /ləʊ'keɪʃn/ n.位置,地点;定位"},{"id":1551,"word":"location","pronunciation":"/ləʊ'keɪʃn/","meaning":"n.位置,地点;定位","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1552,"word":"allocate","pronunciation":"/'æləkeɪt/","meaning":"v.分配,调拨","unit":6,"lesson":1,"seq":38,"isStar":false,"memo":"联想:all(所有)+(l)ocate(找出……的具体位置)→找出所有人的位置,再确定把东西“分配”给谁。","example":"More resources are being allocated to the project. 更多的资源正在被分配给这个项目。","derivative":"allocation /ˌælə'keɪn/ n.分配;配置"},{"id":1553,"word":"allocation","pronunciation":"/ˌælə'keɪʃn/","meaning":"n.分配;配置","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1554,"word":"situate","pronunciation":"/'sɪtʃueɪt/","meaning":"v.使位于……;把……跟……联系起来考虑","unit":6,"lesson":1,"seq":39,"isStar":false},{"id":1555,"word":"situation","pronunciation":"/ˌstʃu'eɪn/","meaning":"n.情况,状况;位置","unit":6,"lesson":1,"seq":40,"isStar":false,"memo":"构词:situat(e)(使位于……)+-ion(名词后缀)→位置","example":"These questions can predict how people actually behave in social situations. 这些问题可以预测人们在社交场合的实际行为。"},{"id":1556,"word":"urban","pronunciation":"/'ːbən/","meaning":"adj.城市的;都市的;城镇的","unit":6,"lesson":1,"seq":41,"isStar":false},{"id":1557,"word":"urbanise/-ize","pronunciation":"/'ɜːbənaɪz/","meaning":"v.使都市化","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1558,"word":"urbanisation/-zation","pronunciation":"/ɜːbənaɪ'zeɪʃn/","meaning":"n.城市化","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1559,"word":"suburb","pronunciation":"/'sʌbɜːb/","meaning":"n.市郊,郊区","unit":6,"lesson":1,"seq":42,"isStar":false,"memo":"构词:sub-(=near)+urb(=city)→在城市附近→郊区"},{"id":1560,"word":"suburban","pronunciation":"/sə'bɜːbən/","meaning":"adj.郊区的;平庸的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1561,"word":"downtown","pronunciation":"/ˌdaʊn'taʊn/","meaning":"adv.在市中心 adj.市中心的","unit":6,"lesson":1,"seq":43,"isStar":false},{"id":1562,"word":"metropolitan","pronunciation":"/ˌmetrə'pɒlɪtən/","meaning":"adj.大城市的,大都会的;本土的","unit":6,"lesson":1,"seq":44,"isStar":false,"memo":"联想 me(我) + tro + polit(联想 politics) + -an(形容词后缀) → 身在“大城市的”我常关注政治事务。","example":"It is highly important to expand the metropolitan areas. 扩大都市圈是非常重要的。"},{"id":1563,"word":"continent","pronunciation":"/'kɒntɪnənt/","meaning":"n.大陆;洲","unit":6,"lesson":1,"seq":45,"isStar":false,"memo":"联想 con-(所有) + tin(音似“听”) + ent (联想 enter) → 把所有听装的罐头都搬进这块“大陆”。","example":"The World Cup is called that because teams from every continent have played in it. 世界杯之所以被这么称呼，是因为每个洲的球队都参加过比赛。","derivative":"continental /ˌkɒntɪˈnentl/ adj.大陆的；大洲的"},{"id":1564,"word":"continental","pronunciation":"/ˌkɒntɪ'nentl/","meaning":"adj.大陆的;大洲的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1565,"word":"current","pronunciation":"/'kʌrənt/","meaning":"adj.当前的;流行的 n.(海洋或江河的)水流;电流","unit":6,"lesson":1,"seq":46,"isStar":false,"memo":"联想 cur(联想 care) + rent(租房) → 他关心“当前的”租房价格。","example":"Oil prices are expected to remain at current levels. 油价预计将保持在当前水平。","derivative":"currently /ˈkʌrəntli/ adv.目前，当前"},{"id":1566,"word":"currently","pronunciation":"/'kʌrəntli/","meaning":"adv.目前,当前","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1567,"word":"currency","pronunciation":"/'kʌrənsi/","meaning":"n.流行;通货;货币","unit":6,"lesson":1,"seq":47,"isStar":false,"memo":"构词 curren(t)(流行的) + -cy(名词后缀) → 流行","example":"Their currency has slumped. 他们的货币已经贬值。"},{"id":1568,"word":"monetary","pronunciation":"/'mʌntri/","meaning":"adj.货币的,钱的(尤指一国的货币)","unit":6,"lesson":1,"seq":48,"isStar":false},{"id":1569,"word":"money","pronunciation":"/'mni/","meaning":"n.钱;薪水;收入","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1570,"word":"harmony","pronunciation":"/'hɑːməni/","meaning":"n.融洽,和谐","unit":6,"lesson":1,"seq":49,"isStar":false,"example":"All life seemed to live in harmony with its surroundings there. 那里所有的生命似乎都与周围的环境和谐相处。","derivative":"harmonious /hɑː'məʊniəs/ adj.和谐的,协调的"},{"id":1571,"word":"harmonious","pronunciation":"/hɑ'məʊniəs/","meaning":"adj.和谐的,协调的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1572,"word":"loan","pronunciation":"/ləʊn/","meaning":"n.贷款","unit":6,"lesson":1,"seq":50,"isStar":false,"memo":"谐音 单词发音类似“楼”→一般人买楼房需要“贷款”。","example":"They are not eligible for a student loan. 他们没有资格申请学生贷款。"},{"id":1573,"word":"landlord","pronunciation":"/'lændlɔːd/","meaning":"n.地主;房东;店主","unit":6,"lesson":1,"seq":51,"isStar":false,"memo":"谐音 单词发音类似“懒得劳动”→有些“地主”只收租金,懒得去劳动。","example":"The landlord gave notice of the termination of tenancy. 房东给了租期终止的通知。"},{"id":1574,"word":"estate","pronunciation":"/ɪ'steɪt/","meaning":"n.住宅区;工业区;(通常指农村的)大片私有土地;个人财产(尤指遗产)","unit":6,"lesson":1,"seq":52,"isStar":false,"memo":"谐音 单词发音类似“爱死它的”→有些人最爱的是自己的“个人财产”。","example":"These 18-hour cities are beginning to make waves in real estate rankings. 这些“18小时城市”开始在房地产排行榜上掀起波澜。"},{"id":1575,"word":"wealth","pronunciation":"/welθ/","meaning":"n.财产,财富;大量","unit":6,"lesson":1,"seq":53,"isStar":false,"memo":"谐音 单词发音类似“威尔士”→威尔士这个国家有“大量”的城堡,“财产”丰富。","example":"It is widely accepted that everybody has the right to share in the wealth of the country. 人们普遍认为,每个人都有分享国家财富的权利。","derivative":"wealthy /'welði/ adj.富有的,富裕的"},{"id":1576,"word":"wealthy","pronunciation":"/'welθi/","meaning":"adj.富有的,富裕的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1577,"word":"treasure","pronunciation":"/'treə(r)/","meaning":"n.珠宝;财富 v.珍视;珍藏","unit":6,"lesson":1,"seq":54,"isStar":false,"memo":"谐音 单词发音类似“揣着”→他揣着掖着,不想让外人看见他珍爱的财宝→财富;珍视","example":"They were digging for buried treasure. 他们在挖掘埋在地下的宝藏。"},{"id":1578,"word":"enrich","pronunciation":"/ɪn'rɪtʃ/","meaning":"v.充实,使丰富;使富有","unit":6,"lesson":1,"seq":55,"isStar":false,"example":"He used the knowledge to enrich himself. 他利用知识来丰富自己。"},{"id":1579,"word":"incentive","pronunciation":"/ɪn'sentɪv/","meaning":"n.激励;刺激;动力","unit":6,"lesson":1,"seq":56,"isStar":false,"memo":"联想 in(里面)+cent(分)+-ive(名词后缀)→家里穷到只剩一分钱了,这“激励”他奋发图强。","example":"There needs to be strong economic incentives for companies to locate here. 需要有强有力的经济激励措施来鼓励企业在这里落户。"},{"id":1580,"word":"decent","pronunciation":"/'diːsnt/","meaning":"adj.体面的;像样的;正派的","unit":6,"lesson":1,"seq":57,"isStar":false,"memo":"联想 de(音似“弟”)+cent(分)→弟弟捡到一分钱,把它交给警察,这是很“正派的”行为。","example":"They have a harder time getting a job with decent pay. 他们很难找到一份薪水可观的工作。"},{"id":1581,"word":"accent","pronunciation":"/'æksent/","meaning":"n.口音;重音;强调;特点 v.强调;重读;带……口音讲话","unit":6,"lesson":1,"seq":58,"isStar":false,"example":"His Chinese accent was quite pure. 他的中国口音很纯正。"},{"id":1582,"word":"property","pronunciation":"/'prɒpəti/","meaning":"n.所有物;财产;不动产,房地产","unit":6,"lesson":1,"seq":59,"isStar":false,"memo":"联想 proper(合适的)+-ty(名词后缀)→有些人觉得“财产”多的人才是合适的朋友。","example":"The chief duty of every government is to protect persons and property. 每个政府的首要职责都是保护人民和国家财产。"},{"id":1583,"word":"proper","pronunciation":"/'prɒpə(r)/","meaning":"adj.正确的;恰当的;符合规则的","unit":6,"lesson":1,"seq":0,"isStar":true,"memo":"构词：pro-（向前）+ per（尝试、通过）→ 向前走对路→恰当的！像穿西装打领带进校长办公室。","example":"Students must use proper citations when quoting academic sources. 学生引用学术资料时必须使用恰当的引注格式。","derivative":"improper /ɪmˈprɒpə(r)/ adj.不适当的；properly /ˈprɒpəli/ adv.恰当地"},{"id":1584,"word":"appropriate","pronunciation":"/ə'prəʊpriət/","meaning":"adj.适当的,合适的","unit":6,"lesson":1,"seq":60,"isStar":false,"memo":"构词 ap-(一再地)+propri(=proper)+-ate(形容词后缀)→适当的,合适的","example":"Appropriate arrangements will be made for their work and livelihood. 他们的工作和生活会得到妥善的安排。"},{"id":1585,"word":"suitable","pronunciation":"/'suːtəbl/","meaning":"adj.合适的,适宜的","unit":6,"lesson":1,"seq":61,"isStar":false,"memo":"构词 suit(适合)+-able(形容词后缀)→合适的,适宜的","example":"They know best which universities are most suitable for their children. 他们最清楚哪些大学最适合自己的孩子。"},{"id":1586,"word":"suit","pronunciation":"/suːt/","meaning":"n.套装;西服;诉讼 v.适合;合(某人)心意","unit":6,"lesson":1,"seq":62,"isStar":false,"example":"Products must be designed to suit the taste of the consumer. 产品设计必须符合消费者的口味。"},{"id":1587,"word":"outfit","pronunciation":"/'aʊtfɪt/","meaning":"n.全套服装;全套装备 v.装备;供给服装","unit":6,"lesson":1,"seq":63,"isStar":false},{"id":1588,"word":"suite","pronunciation":"/swiːt/","meaning":"n.套房(尤指酒店的豪华套房);一套家具;一批随员","unit":6,"lesson":1,"seq":64,"isStar":false,"memo":"联想 suit(套装)+e→套房;一套家具","example":"I suggest we fit you up with an office suite. 我建议我们为你配备一间办公套房。"},{"id":1589,"word":"possess","pronunciation":"/pə'zes/","meaning":"v.拥有,具有","unit":6,"lesson":1,"seq":65,"isStar":false,"memo":"联想 po(联想“魄”)+ss(联想“美女”)+e+ss(联想“美女”)→即使陷入落魄的困境,这些美女内心仍“拥有”希望。","example":"I'm afraid this is the only suitcase I possess. 恐怕我只有这一个箱子。","derivative":"possession /pə'zen/ n.拥有;财产\npossessive /pə'zesv/ adj.要求悉心关爱的;占有欲强的"},{"id":1590,"word":"possession","pronunciation":"/pə'zeʃn/","meaning":"n.拥有;财产","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1591,"word":"possessive","pronunciation":"/pə'zesɪv/","meaning":"adj.要求悉心关爱的;占有欲强的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1592,"word":"fund","pronunciation":"/fʌnd/","meaning":"n.基金;资金 v.为……提供资金","unit":6,"lesson":1,"seq":66,"isStar":false,"memo":"对照 他发现了(found)很多资金(fund)。","example":"This school is funded by both the local and state governments. 该学校由当地政府和州政府共同资助。","derivative":"funding /'fʌndŋ/ n.专款,拨款"},{"id":1593,"word":"funding","pronunciation":"/'fʌndŋ/","meaning":"n.专款,拨款","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1594,"word":"refund","pronunciation":"/rɪ'fʌnd/","meaning":"n.退款,返还款 v.退还,退(款)","unit":6,"lesson":1,"seq":67,"isStar":false,"memo":"构词 re-(回)+fund(资金)→退还,退(款)","example":"Ask for a refund if the goods are faulty. 商品如有缺陷,可要求退款。"},{"id":1595,"word":"finance","pronunciation":"/'faɪnæns/","meaning":"n.资金;金融;财务 v.提供资金","unit":6,"lesson":1,"seq":68,"isStar":false,"memo":"谐音 单词发音类似“犯难死”→没有足够的“资金”维持公司的运营,这让他犯了难。","example":"She felt that she should contribute to the household finances. 她觉得她应该为家庭财务做出贡献。","derivative":"financial /faɪ'nænʃl/ adj.财务的;金融的"},{"id":1596,"word":"financial","pronunciation":"/faɪ'nænʃl/","meaning":"adj.财务的;金融的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1597,"word":"crisis","pronunciation":"/'kraɪsɪs/","meaning":"n.危机,危急关头","unit":6,"lesson":1,"seq":69,"isStar":false,"memo":"联想 cri(联想 cry)+sis(联想“死”)→他遇到了“危机”,要哭死了。","example":"At times of crisis, grain is the food of life. 在危机时期,谷物是生命之食物。"},{"id":1598,"word":"budget","pronunciation":"/'bʌdʒɪt/","meaning":"n.预算 v.编入预算","unit":6,"lesson":1,"seq":70,"isStar":false,"memo":"联想 bu(音似“爸”)+d+get(得到)→爸爸得到了很多“预算”。","example":"Many families struggle to balance the household budget. 许多家庭努力平衡家庭预算。","derivative":"budgetary /'bʌdʒɪtəri/ adj.预算的"},{"id":1599,"word":"budgetary","pronunciation":"/'bʌdɪtəri/","meaning":"adj.预算的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1600,"word":"target","pronunciation":"/'tɑːɡt/","meaning":"n.对象,目标","unit":6,"lesson":1,"seq":71,"isStar":false,"memo":"联想 ta(联想“他”)+r(联想“人”)+get(达到)→他达到了“目标”,令人刮目相看。","example":"Set yourself targets that you can reasonably hope to achieve. 给自己设定合理的有望达到的目标。"},{"id":1601,"word":"mortgage","pronunciation":"/'mɔːɡɪdʒ/","meaning":"n.按揭(由银行等提供房产抵押借款); 按揭贷款 v.(向银行等)抵押(房产)","unit":6,"lesson":1,"seq":72,"isStar":false,"memo":"联想 mortga(音似“摩给”)+ge(联想“哥”)→我把最爱的摩托给哥哥,当作“抵押”。","example":"Mortgage lenders are now careful about borrowers' qualifications. 现在抵押贷款机构对借款人的资格非常谨慎。"},{"id":1602,"word":"profit","pronunciation":"/'prɒfɪt/","meaning":"n.利润;好处 v.获益,得到好处","unit":6,"lesson":1,"seq":73,"isStar":false,"memo":"联想 pro-(提前)+fi(音似“肥”)+t(联想“他”)→他提前比别人肥(胖)了,大概是因为他得到了很多“好处”。","example":"They want to return to the past and to invest money for profit. 他们想回到过去,投资赚钱。","derivative":"profitable /'prɒfɪtəbl/ adj.有利润的;有益的"},{"id":1603,"word":"profitable","pronunciation":"/'prfɪtəbl/","meaning":"adj.有利润的;有益的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1604,"word":"benefit","pronunciation":"/'benɪfɪt/","meaning":"n.优势;益处 v.使受益","unit":6,"lesson":1,"seq":74,"isStar":false,"memo":"谐音 单词发音类似“比你肥”→他找了份比你的工作肥(好处多)的工作,说明他有“优势”。","example":"It generates huge social benefits. 它产生巨大的社会效益。","derivative":"beneficial /benɪ'fɪl/ adj.有利的 beneficiary /benɪ'fɪəri/ n.受益者;遗产继承人"},{"id":1605,"word":"beneficial","pronunciation":"/ˌbenɪ'fɪʃl/","meaning":"adj.有利的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1606,"word":"beneficiary","pronunciation":"/ˌbenɪ'fɪʃəri/","meaning":"n.受益者;遗产继承人","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1607,"word":"pension","pronunciation":"/'penn/","meaning":"n.养老金,退休金","unit":6,"lesson":1,"seq":75,"isStar":false,"memo":"谐音‘盆盛’——退休后靠‘盆’里盛的养老金过日子！pen-（关押→引申为‘积蓄’）+sion。","example":"Most citizens rely on state pension after retirement. 大多数公民退休后依赖国家养老金。","derivative":"pensioner /'penʃ(ə)nə/ n.领养老金者"},{"id":1608,"word":"pensioner","pronunciation":"/'penʃənə(r)/","meaning":"n.领养老金(或退休金、抚恤金)者","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1609,"word":"premium","pronunciation":"/'priːmiəm/","meaning":"n.保险费;额外费用","unit":6,"lesson":1,"seq":76,"isStar":false,"memo":"联想 pre-(提前) + m(联想“妹”) + i(我) + u(字母音似 you) + m(联想“妈”)→妹妹、我、你和妈妈都提前交了“保险费”。","example":"Premiums are guaranteed throughout the term of the policy. 在保单的有效期内,所缴纳的保险费是有保障的。"},{"id":1610,"word":"expense","pronunciation":"/k'spens/","meaning":"n.费用,花费","unit":6,"lesson":1,"seq":77,"isStar":false,"memo":"对照 expensive adj.昂贵的;花钱多的→expense n.","example":"Living expenses there are comparatively low. 那里的生活费用相对较低。","derivative":"expensive /ɪk'spensɪv/ adj.昂贵的,花钱多的,价格高的"},{"id":1611,"word":"expensive","pronunciation":"/ɪk'spensɪv/","meaning":"adj.昂贵的,花钱多的,价格高的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1612,"word":"dispense","pronunciation":"/dɪ'spens/","meaning":"v.分配,分发;提供","unit":6,"lesson":1,"seq":78,"isStar":false,"memo":"联想 dis-(分开) + pens(钢笔) + e→分开给钢笔→分配,分发","example":"The machine dispenses a range of drinks and snacks. 这台机器发售各种饮料和小吃。"},{"id":1613,"word":"expenditure","pronunciation":"/k'spendɪtʃə(r)/","meaning":"n.花费,开支;耗费","unit":6,"lesson":1,"seq":79,"isStar":false,"memo":"构词 expend(花费) + -iture(名词后缀)→花费,开支;耗费","example":"This study represents a major expenditure of time and effort. 这项研究意味着要耗费大量的时间和精力。"},{"id":1614,"word":"monopoly","pronunciation":"/mə'nɒpəli/","meaning":"n.垄断;垄断者;垄断商品","unit":6,"lesson":1,"seq":80,"isStar":false,"memo":"联想 mon(音似“莫”) + no(没有) + poly (音似“魄力”)→想把事业做大,形成“垄断”地位,就不能没有魄力。","example":"The company holds a monopoly of the market. 这家公司在市场上处于垄断地位。","derivative":"monopolise/-ize /mə'nɒpəlaɪz/ v.独占,垄断"},{"id":1615,"word":"monopolise/-ize","pronunciation":"/mə'nɒpəlaɪz/","meaning":"v.独占,垄断","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1616,"word":"policy","pronunciation":"/'pɒləsi/","meaning":"n.政策,方针;原则","unit":6,"lesson":1,"seq":81,"isStar":false,"example":"They defended the new policy. 他们维护新政策。"},{"id":1617,"word":"stock","pronunciation":"/stɒk/","meaning":"n.(商店的)现货,存货;股票;家畜 v.储存","unit":6,"lesson":1,"seq":82,"isStar":false,"memo":"[对照] 商店(store)储存(stock)了很多现货(stock)。","example":"We stock a wide range of kitchen equipment. 我们备有各种厨房用品。"},{"id":1618,"word":"livestock","pronunciation":"/'laɪvstɒk/","meaning":"n.牲畜,家畜","unit":6,"lesson":1,"seq":83,"isStar":false,"memo":"[构词] live(活着的)+stock(家畜)→牲畜,家畜","example":"The robots are not limited to herding and monitoring livestock. 机器人并不局限于放牧和监控牲畜。"},{"id":1619,"word":"stack","pronunciation":"/stæk/","meaning":"n.一叠;大量 v.(使)放成整齐的一叠(或一、一堆)","unit":6,"lesson":1,"seq":84,"isStar":false,"memo":"[联想] s(联想“美女”)+tack(音似“待客”)→美女结婚时要招待“大量”客人。","example":"The floor was stacked with boxes. 地板上码放着一摞摞箱子。"},{"id":1620,"word":"valuable","pronunciation":"/'væljuəbl/","meaning":"adj.宝贵的;贵重的","unit":6,"lesson":1,"seq":85,"isStar":false,"example":"They missed lots of valuable information. 他们错过了很多有价值的信息。","derivative":"value /'vælju:/ n.价值;价值观"},{"id":1621,"word":"value","pronunciation":"/'vælju:/","meaning":"n.价值;价值观","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1622,"word":"evaluate","pronunciation":"/ɪ'vælju:eɪt/","meaning":"v.评价,评估","unit":6,"lesson":1,"seq":86,"isStar":false,"memo":"[构词] e-(出)+valu(e)(价值)+-ate(动词后缀)→说出物品的价值→评价,评估","example":"We need to learn how to evaluate them properly. 我们需要学习如何正确评估它们。","derivative":"evaluation /ɪˌvælju'eɪʃn/ n.估计;评价,评估"},{"id":1623,"word":"evaluation","pronunciation":"/ɪvælju'eɪʃn/","meaning":"n.估计;评价,评估","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1624,"word":"emphasis","pronunciation":"/'emfəsɪs/","meaning":"n.强调;重视;重要性","unit":6,"lesson":1,"seq":87,"isStar":false,"memo":"[对照] emphasise v.强调;重视→emphasis n.","example":"For the traditional home, there is too much emphasis on family continuity and stability. 传统家庭过分强调家庭的延续性和稳定性。","derivative":"emphasise/-ize /'emfəsaz/ v.强调;重视\nemphatic /ɪm'fætɪk/ adj.强调的;有力的"},{"id":1625,"word":"emphasise/-ize","pronunciation":"/'emfəsaɪz/","meaning":"v.强调;重视","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1626,"word":"emphatic","pronunciation":"/ɪm'fætɪk/","meaning":"adj.强调的;有力的","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1627,"word":"synthesis","pronunciation":"/'sɪnθəsɪs/","meaning":"n.综合;结合,合成","unit":6,"lesson":1,"seq":88,"isStar":false,"memo":"[联想] syn(音似“神”)+the(那)+sis(联想sister)→神和那个姐姐“结合”在一起,打败了坏人。","example":"It is a synthesis of art with everyday life. 它是艺术与日常生活的结合。","derivative":"synthetic /sɪn'θetɪk/ adj.人造的;合成的;综合的 n.合成物;合成剂\nsynthesise/-ize /'sɪnθəsaɪz/ v.合成;综合"},{"id":1628,"word":"synthetic","pronunciation":"/sɪn'θetɪk/","meaning":"adj.人造的;合成的;综合的 n.合成物;合成剂","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1629,"word":"synthesise/-ize","pronunciation":"/'snθəsaɪz/","meaning":"v.合成;综合","unit":6,"lesson":1,"seq":0,"isStar":true},{"id":1630,"word":"highlight","pronunciation":"/'halaɪt/","meaning":"n.最突出(或最精彩、最激动人心)的部分 v.突出;强调","unit":6,"lesson":1,"seq":89,"isStar":false,"memo":"[构词] high(高)+light(光)→突出","example":"The highlights of the match will be shown later this evening. 本场比赛最精彩的片段将于今晚晚些时候播出。"},{"id":1631,"word":"limelight","pronunciation":"/'laɪmlaɪt/","meaning":"n.公众关注的焦点","unit":6,"lesson":1,"seq":90,"isStar":false},{"id":1632,"word":"grave","pronunciation":"/ɡreɪv/","meaning":"n.坟墓 adj.严重的;严肃的","unit":6,"lesson":2,"seq":1,"isStar":false,"memo":"gr(联想“官人”) + ave(音似“爱我”) → 官人爱我终生→“生同衾,死同穴”→坟墓","example":"The leakage of a state secret is a grave crime. 泄露国家机密是严重的罪行。","derivative":"gravity /'ɡrævəti/ n.重力;严重性;庄严"},{"id":1633,"word":"gravity","pronunciation":"/'ɡrævəti/","meaning":"n.重力;严重性;庄严","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1634,"word":"aggravate","pronunciation":"/'æɡrəvet/","meaning":"v.使严重,使恶化;激怒","unit":6,"lesson":2,"seq":2,"isStar":false,"memo":"ag-(一再地) + grav(e)(严重的) + -ate(动词后缀)→使严重","example":"The financial problem of this company is further aggravated by the rise in interest rates. 利率上升使这家公司的财务问题进一步恶化。","derivative":"aggravation /ˌæɡrə'veʃn/ n.恶化;加剧"},{"id":1635,"word":"aggravation","pronunciation":"/æɡrə'veɪn/","meaning":"n.恶化;加剧","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1636,"word":"grant","pronunciation":"/ɡrɑːnt/","meaning":"n.拨款,补助金 v.给予;准予;承认","unit":6,"lesson":2,"seq":3,"isStar":false,"memo":"gr(联想“官人”) + ant(蚂蚁)→大雨来临,官人打开门,“准予”蚂蚁进来躲雨。","example":"He has been awarded a research grant. 他得到一笔研究经费。","derivative":"granted /'ɡrɑːntɪd/ adv.的确,诚然"},{"id":1637,"word":"granted","pronunciation":"/'ɡrɑːntɪd/","meaning":"adv.的确,诚然","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1638,"word":"grind","pronunciation":"/ɡraɪnd/","meaning":"v.磨碎;使锋利 n.刺耳的摩擦声;苦差事","unit":6,"lesson":2,"seq":4,"isStar":false,"memo":"gr(联想“官人”) + in(里面) + d(联想“刀”)→官人在家里磨刀→磨碎;使锋利","example":"The grind of heavy machines could get on their nerves. 重型机器的摩擦声让他们心烦意乱。"},{"id":1639,"word":"grid","pronunciation":"/ɡrɪd/","meaning":"n.网格;输电网","unit":6,"lesson":2,"seq":5,"isStar":false},{"id":1640,"word":"grieve","pronunciation":"/ɡriːv/","meaning":"v.悲伤,悲痛;使伤心","unit":6,"lesson":2,"seq":6,"isStar":false,"memo":"gr(联想“官人”) + i(字母音似“爱”) + eve(联想 Eve,“夏娃”)→凡间的官人爱上了夏娃,这使亚当和夏娃都很“悲伤”。","example":"He grieved to death over the loss of his wife. 他因失去妻子而悲痛欲绝。","derivative":"grief /ɡriːf/ n.悲伤,悲痛"},{"id":1641,"word":"grief","pronunciation":"/ɡriːf/","meaning":"n.悲伤,悲痛","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1642,"word":"grievous","pronunciation":"/'ɡriːvəs/","meaning":"adj.极严重的;使人痛苦的;令人伤心的","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1643,"word":"relieve","pronunciation":"/r'liːv/","meaning":"v.减轻,缓和(不快或痛苦)","unit":6,"lesson":2,"seq":7,"isStar":false,"memo":"联想 re(字母音似“阿姨”)+li(联想“立”)+eve(联想 Eve,“夏娃”)→阿姨看到夏娃很难过,就站立在夏娃身边安慰她,“缓和”她的痛苦。","example":"The new secretary will relieve us of some of the paperwork. 新来的秘书会减轻我们的一些文书工作。","derivative":"relief /rɪ'lif/ n.宽慰;救济;(焦虑、痛苦等的)减轻,消除"},{"id":1644,"word":"relief","pronunciation":"/rɪ'liːf/","meaning":"n.宽慰;救济;(焦虑、痛苦等的)减轻,消除","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1645,"word":"alleviate","pronunciation":"/ə'liːvieɪt/","meaning":"v.减轻,缓解","unit":6,"lesson":2,"seq":8,"isStar":false,"memo":"联想 al-(= to) + levi (联想时装品牌 Levi's,李维斯) +-ate(动词后缀)→他因考试成绩不理想很烦恼,妈妈给他买新衣服,以“缓解”他的不良情绪。","example":"Cutting trees to grow more food can hardly alleviate the shortage of food. 砍伐树木来种植更多的粮食几乎无法缓解粮食短缺问题。","derivative":"alleviation /əˌliːvi'eɪʃn/ n.减轻,缓解"},{"id":1646,"word":"alleviation","pronunciation":"/əˌliːvi'eɪʃn/","meaning":"n.减轻,缓解","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1647,"word":"calculate","pronunciation":"/'kælkjulet/","meaning":"v.计算,核算;估计,推测","unit":6,"lesson":2,"seq":9,"isStar":false,"memo":"联想 calcu(音似“开口”)+late(晚的)→他开口晚是因为把时间“计算”错了。","example":"Mothers' devotion to children can hardly be calculated. 母亲对孩子的奉献难以计算。","derivative":"calculator /'kælkjuleɪtə(r)/ n.计算机,计算器\ncalculation /ˌkælkju'leɪʃn/ n.计算\ncalculating /'kælkjuleɪtɪŋ/ adj.精明的"},{"id":1648,"word":"calculator","pronunciation":"/'kælkjuleɪtə(r)/","meaning":"n.计算机,计算器","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1649,"word":"calculation","pronunciation":"/kælkju'leɪʃn/","meaning":"n.计算","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1650,"word":"calculating","pronunciation":"/'kælkjuleɪtɪŋ/","meaning":"adj.精明的","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1651,"word":"counter","pronunciation":"/'kantə(r)/","meaning":"n.(商店、银行等的)柜台;计算器 v.反驳 adv.相反地,反对地","unit":6,"lesson":2,"seq":10,"isStar":false,"example":"There aren't enough staff on duty at all the service counters. 所有服务柜台都没有足够的值班人员。","derivative":"counterpart\ncounterfeit\ncounteraction\ncounteract\nboycott\nencounter\nconfront\nconfrontation"},{"id":1652,"word":"account","pronunciation":"/ə'kaʊnt/","meaning":"n.账户;账目;说明 v.认为是,把……视为","unit":6,"lesson":2,"seq":11,"isStar":false,"example":"I paid the cheque into my savings account. 我把支票存入我的储蓄账户。","derivative":"accounting /ə'kaʊntɪŋ/ n.会计\naccountant /ə'kaʊntənt/ n.会计,会计师\naccountable\naccountancy\naccountability"},{"id":1653,"word":"accounting","pronunciation":"/ə'kaʊntɪŋ/","meaning":"n.会计","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1654,"word":"accountant","pronunciation":"/ə'kaʊntənt/","meaning":"n.会计,会计师","unit":6,"lesson":2,"seq":12,"isStar":false},{"id":1655,"word":"accountancy","pronunciation":"/ə'kaʊntənsi/","meaning":"n.会计工作;会计职业","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1656,"word":"accountable","pronunciation":"/ə'kaʊntəbl/","meaning":"adj.负有责任的","unit":6,"lesson":2,"seq":13,"isStar":false,"memo":"对照 他对此事是负有责任的(accountable)，所以需要解释(account for)一下。","example":"Politicians are ultimately accountable to the voters. 从政者最终向选民负责。","derivative":"accountability /əˌkaʊntəˈbɪləti/ n.负有责任"},{"id":1657,"word":"accountability","pronunciation":"/əˌkaʊntə'bɪləti/","meaning":"n.负有责任","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1658,"word":"discount","pronunciation":"/'dɪskaʊnt/","meaning":"n.折扣 v.打折,打折出售","unit":6,"lesson":2,"seq":14,"isStar":false,"memo":"构词 dis-(否定前缀) + count(计算)→没有计算在内的→打折","example":"They were selling everything at a discount. 他们销售的所有商品都打折。"},{"id":1659,"word":"counterpart","pronunciation":"/'kaʊntəpɑːt/","meaning":"n.职位(或作用)相当的人;对应的事物","unit":6,"lesson":2,"seq":15,"isStar":false,"memo":"构词 counter(相对) + part(部分)→对应的事物","example":"On average, US students study more topics within science and math than their international counterparts do. 平均而言，美国学生比他们的国际同学习更多关于科学和数学的主题。"},{"id":1660,"word":"counterfeit","pronunciation":"/'kantəfɪt/","meaning":"v.伪造;仿造 n.仿造品 adj.伪造的","unit":6,"lesson":2,"seq":16,"isStar":false},{"id":1661,"word":"counteract","pronunciation":"/ˌkaʊntər'ækt/","meaning":"v.抵制;抵消;抵抗","unit":6,"lesson":2,"seq":17,"isStar":false,"memo":"构词 counter(相反) + act(行动，动作)→相反地行动→抵制；抵抗","example":"These exercises aim to counteract the effects of stress and tension. 这些训练动作旨在缓解压力与紧张。","derivative":"counteraction /kaʊntərˈækʃən/ n.抵制；抵消；抵抗"},{"id":1662,"word":"counteraction","pronunciation":"/ˌkaʊntər'ækʃən/","meaning":"n.抵制;抵消;抵抗","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1663,"word":"boycott","pronunciation":"/'bɔɪkɒt/","meaning":"n.抵制行动 v.拒绝购买;抵制","unit":6,"lesson":2,"seq":18,"isStar":false,"memo":"联想 boy(男孩) + cott(音似“可他”)→姐姐对这个男孩很好，可他还是“抵制”跟她一起回家。","example":"They decide to boycott the products of the fashion industry. 他们决定抵制时尚行业的产品。"},{"id":1664,"word":"encounter","pronunciation":"/ɪn'kaʊntə(r)/","meaning":"v.遭遇;偶然碰到 n.相遇,邂逅;遭遇","unit":6,"lesson":2,"seq":19,"isStar":false,"memo":"构词 en-(使) + counter(相对)→使相对→相遇","example":"It has encountered increasingly tougher challenges. 它遇到了越来越严峻的挑战。"},{"id":1665,"word":"confront","pronunciation":"/kən'frʌnt/","meaning":"v.面对;对抗","unit":6,"lesson":2,"seq":20,"isStar":false,"memo":"构词 con-(共同) + front(前面，面向)→面对；对抗","example":"They are unaware of the potential risks they are confronting. 他们并没有察觉到自己正面临的潜在风险。","derivative":"confrontation /ˌkɒnfrʌnˈteɪʃn/ n.对抗；冲突"},{"id":1666,"word":"confrontation","pronunciation":"/ˌkɒnfrən'teɪʃn/","meaning":"n.对抗;冲突","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1667,"word":"transaction","pronunciation":"/træn'zækʃn/","meaning":"n.交易","unit":6,"lesson":2,"seq":21,"isStar":false,"memo":"构词 trans-(从……到……) + act(行动) + -ion(名词后缀)→交易","example":"Using the internet can significantly reduce transaction costs. 因特网的使用可以大大减少交易成本。"},{"id":1668,"word":"transit","pronunciation":"/'trænzɪt/","meaning":"n.运输,运送","unit":6,"lesson":2,"seq":22,"isStar":false,"memo":"联想 trans-(从……到……) + it(它)→把它从这儿弄到那儿→运输,运送","example":"The goods were damaged in transit. 货物在运输中损坏了。","derivative":"transition /trænˈzɪn/ n.过渡;变迁\ntransitional /trænˈzʃənl/ adj.变迁的,过渡期的"},{"id":1669,"word":"transition","pronunciation":"/træn'zɪn/","meaning":"n.过渡;变迁","unit":6,"lesson":2,"seq":0,"isStar":true,"memo":"【构词】trans-（跨）+ it-（走）+ -ion → ‘跨步走’→从一状态走到另一状态→过渡；联想‘转神’——考研失败后转神般进入职场。","example":"The transition from high school to university requires strong time-management skills. 从高中到大学的过渡需要强大的时间管理能力。","derivative":"transitional /træn'zɪʃən(ə)l/ adj.过渡的；转变期的"},{"id":1670,"word":"transitional","pronunciation":"/træn'zɪʃənl/","meaning":"adj.变迁的;过渡期的","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1671,"word":"transform","pronunciation":"/træns'fɔːm/","meaning":"v.使改变形态","unit":6,"lesson":2,"seq":23,"isStar":false,"memo":"构词 trans-(从……到……) + form(形式)→从这种形式到那种形式→使改变形态","example":"Every aspect of our lives will be transformed. 我们生活的方方面面都将被改变。","derivative":"transformation /ˌtrænsfəˈmeɪn/ n.变化,改革"},{"id":1672,"word":"transformation","pronunciation":"/ˌtrænsfə'meɪʃn/","meaning":"n.变化,改革","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1673,"word":"transplantation","pronunciation":"/trænsplæn'teʃn/","meaning":"n.移栽,移种,移植","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1674,"word":"transfer","pronunciation":"/træns'fɜ:(r)/","meaning":"v.(使)转移;搬迁;调动 /'trænsfɜ:(r)/ n.转移;搬迁;调动","unit":6,"lesson":2,"seq":25,"isStar":false,"memo":"联想 trans-(从……到……) + fer(音似“佛”)→唐僧师徒把佛经从西天取回了大唐→转移;搬迁","example":"The patient was transferred to another hospital. 患者被转送到了另一家医院。","derivative":"transference /ˈtrænsfərəns/ n.转移;调动"},{"id":1675,"word":"transference","pronunciation":"/'trænsfərəns/","meaning":"n.转移;调动","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1676,"word":"transient","pronunciation":"/'trænziənt/","meaning":"adj.短暂的;临时的 n.过往旅客;临时工","unit":6,"lesson":2,"seq":26,"isStar":false,"memo":"联想 trans-(从……到……) + i(我) + ent (联想 enter)→我从这儿进来后很快便出去了→短暂的;临时的","example":"Money seemed to do little more than buy transient relief from their terrible moans. 金钱似乎只是暂时缓解了他们可怕的抱怨。"},{"id":1677,"word":"transparent","pronunciation":"/træns'pærənt/","meaning":"adj.透明的;易懂的","unit":6,"lesson":2,"seq":27,"isStar":false,"memo":"对照:父母(parent)对彼此很了解,信息是透明的(transparent)。","example":"The insect's wings are almost transparent. 这种昆虫的翅膀几乎是透明的。","derivative":"transparency /trænsˈpærənsi/ n.透明;易懂"},{"id":1678,"word":"transparency","pronunciation":"/træns'pærənsi/","meaning":"n.透明;易懂","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1679,"word":"apparent","pronunciation":"/ə'pærənt/","meaning":"adj.明显的;显而易见的","unit":6,"lesson":2,"seq":28,"isStar":false,"memo":"联想:ap(联想“安排”)+parent(父母)→父母安排他做家务,显然是想锻炼他→明显的","example":"More apparent reasonableness followed. 接下来还有一些更显而易见的合理性。","derivative":"apparently /əˈpærəntli/ adv.可见;看来;显然地"},{"id":1680,"word":"apparently","pronunciation":"/ə'pærəntli/","meaning":"adv.可见;看来;显然地","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1681,"word":"opaque","pronunciation":"/əʊ'pek/","meaning":"adj.不透明的;难理解的","unit":6,"lesson":2,"seq":29,"isStar":false,"memo":"谐音:单词发音类似“欧佩克”→OPEC,石油输出国组织→石油的价格是“不透明的”。","example":"You can use opaque glass if you need to block a street view. 如果你需要挡住外面的街景,你可以使用不透明玻璃。"},{"id":1682,"word":"consume","pronunciation":"/kən'sju:m/","meaning":"v.消耗,耗费","unit":6,"lesson":2,"seq":30,"isStar":false,"memo":"联想:con-(所有)+sume(音似“输me”)→游戏最后所有人都输了,只有我凭“消耗”策略胜出。","example":"A grown lion can easily consume 60 pounds of meat at a single feeding. 一头成年狮子单次进食就能轻松吃掉60磅肉。","derivative":"consumer /kənˈsjuːmə(r)/ n.消费者\nconsumption /kənˈsmpʃn/ n.消费;消耗量"},{"id":1683,"word":"consumer","pronunciation":"/kən'sju:mə(r)/","meaning":"n.消费者","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1684,"word":"consumption","pronunciation":"/kən'sʌmpʃn/","meaning":"n.消费;消耗量","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1685,"word":"resume","pronunciation":"/rɪ'zju:m/","meaning":"v.重新开始;继续","unit":6,"lesson":2,"seq":31,"isStar":false,"memo":"联想:re(字母音似“阿姨”)+sume(音似“输me”)→阿姨输给了我,然后她“重新开始”向我发起挑战。","example":"He got back in the car and resumed driving. 他回到车上,继续开车。","derivative":"resumption /rɪˈzʌmpʃn/ n.重新开始;恢复\nrésumé /ˈrezjumeɪ/ n.摘要;个人简历"},{"id":1686,"word":"resumption","pronunciation":"/rɪ'zʌmpʃn/","meaning":"n.重新开始;恢复","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1687,"word":"presume","pronunciation":"/prɪ'zju:m/","meaning":"v.假设,假定;设想","unit":6,"lesson":2,"seq":32,"isStar":false,"memo":"pre-(提前) + su(联想“输”) + me(我)→比赛提前开始，他“假设”你会输给我。","example":"A great many people presume upon a reward when doing a good deed. 许多人在做善事时都设想得到回报。","derivative":"presumption /prɪˈzʌmpn/ n. 推测，假定\npresumably /prɪˈzjuːməbli/ adv. 很可能，大概"},{"id":1688,"word":"presumption","pronunciation":"/pr'zʌmpʃn/","meaning":"n.推测,假定","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1689,"word":"presumably","pronunciation":"/prɪ'zju:məbli/","meaning":"adv.很可能,大概","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1690,"word":"hypothesis","pronunciation":"/haɪ'pɒθəsɪs/","meaning":"n.假说,假设;猜想","unit":6,"lesson":2,"seq":33,"isStar":false,"memo":"hypo(音似“害怕”) + the(那) + sis(联想 sister)→姐姐害怕那个“假说”。","example":"He confirmed the hypothesis. 他证实了那个假设。"},{"id":1691,"word":"assume","pronunciation":"/ə'sju:m/","meaning":"v.假定,认为;承担;就职","unit":6,"lesson":2,"seq":34,"isStar":false,"memo":"as-(一再地) + su(联想“输”) + me(我)→每个人都有优缺点，对手不可能一再地输给我，这只是一种“假定”。","example":"They eat much less than people assume. 他们吃得比人们认为的要少得多。","derivative":"assumption /əsʌmpʃn/ n. 假设；承担；担任"},{"id":1692,"word":"assumption","pronunciation":"/ə'sʌmpʃn/","meaning":"n.假设;承担;担任","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1693,"word":"resemble","pronunciation":"/rɪ'zembl/","meaning":"v.看起来像,与……相似","unit":6,"lesson":2,"seq":35,"isStar":false,"memo":"re-(重复) + sem(音似 same) + ble→与……相似","example":"He grew up to resemble his father. 他长大了，很像他父亲。","derivative":"resemblance /rɪˈzembləns/ n. 相似，相像"},{"id":1694,"word":"assemble","pronunciation":"/ə'sembl/","meaning":"v.聚集;组装","unit":6,"lesson":2,"seq":36,"isStar":false,"example":"We were requested to assemble in the lobby. 我们被要求在大厅集合。","derivative":"assembly /əˈsembli/ n. 装配；立法机构；议会"},{"id":1695,"word":"assembly","pronunciation":"/ə'sembli/","meaning":"n.装配;立法机构;议会","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1696,"word":"similar","pronunciation":"/'smələ(r)/","meaning":"adj.相像的,相仿的,类似的","unit":6,"lesson":2,"seq":37,"isStar":false,"example":"There was a similar accident on the same stretch of track four years ago. 四年前，在同一段轨道上也发生过类似的事故。"},{"id":1697,"word":"similarity","pronunciation":"/sɪmə'lærəti/","meaning":"n.相像性,相似点","unit":6,"lesson":2,"seq":38,"isStar":false},{"id":1698,"word":"assimilate","pronunciation":"/ə'sɪməlet/","meaning":"v.透彻理解;吸收;(使)同化","unit":6,"lesson":2,"seq":39,"isStar":false,"memo":"as-(一再地) + simil(联想 similar) + -ate(动词后缀)→一再地相似→吸收；(使)同化","example":"You have to assimilate the facts, not just remember them. 你需要透彻理解这些事实，而不仅仅是记住它们。","derivative":"assimilation /əˌsɪməˈleɪn/ n. 吸收；接受"},{"id":1699,"word":"assimilation","pronunciation":"/əˌsɪmə'leɪʃn/","meaning":"n.吸收;接受","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1700,"word":"absorb","pronunciation":"/əb'zɔːb/","meaning":"v.吸收;理解;使全神贯注","unit":6,"lesson":2,"seq":40,"isStar":false,"example":"They are more absorbed in what catches their eyes. 他们更专注于吸引他们目光的东西。","derivative":"absorption /əbˈzɔpʃn/ n. 吸收；并入；同化；专注"},{"id":1701,"word":"absorption","pronunciation":"/əb'zɔːpʃn/","meaning":"n.吸收;并入;同化;专注","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1702,"word":"absurd","pronunciation":"/əb'sɜːd/","meaning":"adj.可笑的,荒谬的","unit":6,"lesson":2,"seq":41,"isStar":false,"memo":"ab-(一再地) + surd(音似“笑”)→可笑的，荒谬的","example":"That's an absurd idea. 那是一个荒谬的想法。","derivative":"absurdity /əbˈsɜːdəti/ n. 荒唐"},{"id":1703,"word":"absurdity","pronunciation":"/əb'sɜːdəti/","meaning":"n.荒唐","unit":6,"lesson":2,"seq":0,"isStar":true},{"id":1704,"word":"appease","pronunciation":"/ə'piːz/","meaning":"v.安抚,抚慰","unit":6,"lesson":3,"seq":1,"isStar":false,"memo":"构词 ap-(一再地) + peas(和平) + e → 使平静 → 安抚，抚慰","example":"The move was widely seen as an attempt to appease critics of the regime. 普遍认为，这一举措是试图安抚批评政权的人。","derivative":"appeasement /əˈpiːzmənt/ n.安抚，抚慰"},{"id":1705,"word":"appeasement","pronunciation":"/ə'piːzmənt/","meaning":"n.安抚,抚慰","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1706,"word":"console","pronunciation":"/kən'səʊl/","meaning":"v.安慰,慰藉 /'kɒnsəʊl/ n.操纵台,仪表板","unit":6,"lesson":3,"seq":2,"isStar":false,"memo":"联想 con-(都) + sole(联想“馊了”) → 母亲留给我的好吃的都馊了，我满心愧疚地“安慰”失望的母亲。","example":"He wanted to console the two families. 他想安慰这两个家庭。","derivative":"consolation /ˌknsəˈleɪn/ n.安慰，慰藉\nn.操纵台，仪表板"},{"id":1707,"word":"consolation","pronunciation":"/ˌkɒnsə'leɪn/","meaning":"n.安慰,慰藉","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1708,"word":"sole","pronunciation":"/səʊl/","meaning":"adj.唯一的;独占的,专有的","unit":6,"lesson":3,"seq":3,"isStar":false,"memo":"谐音 单词发音类似“馊”→他的东西馊了也不给别人吃，他要独占→独占的，专有的","example":"She has sole responsibility for the project. 这个项目由她一人负责。","derivative":"solely /ˈsəʊlli/ adv.仅，只；单独地"},{"id":1709,"word":"solely","pronunciation":"/'səlli/","meaning":"adv.仅,只;单独地","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1710,"word":"solemn","pronunciation":"/'sɒləm/","meaning":"adj.冷峻的,表情严肃的;庄重的","unit":6,"lesson":3,"seq":4,"isStar":false,"memo":"联想 so(如此) + lemn(音似“冷漠”)→他的表情如此冷漠→冷峻的，表情严肃的","example":"She was solemn, pulling at her blonde curls. 她表情严肃，拉扯着自己金黄色的卷发。","derivative":"solemnity /səˈlemnəti/ n.庄严；庄重"},{"id":1711,"word":"solemnity","pronunciation":"/sə'lemnəti/","meaning":"n.庄严;庄重","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1712,"word":"solitary","pronunciation":"/'sɒlətri/","meaning":"adj.唯一的;单独的;孤单的","unit":6,"lesson":3,"seq":5,"isStar":false,"memo":"联想 so(如此) + li(音似“累”) + tary→爬山竟如此累，我想一个人休息会儿→单独的","example":"Cultivating positive interpersonal relationships helped him expel solitary feelings. 建立积极的人际关系有助于他排解孤独感。","derivative":"solitude /ˈslɪtjuːd/ n.独处；独居"},{"id":1713,"word":"solitude","pronunciation":"/'sɒltjuːd/","meaning":"n.独处;独居","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1714,"word":"solo","pronunciation":"/'sələʊ/","meaning":"n.独唱;独奏;单人表演 adj.独自的;独唱的","unit":6,"lesson":3,"seq":6,"isStar":false,"example":"The original version featured a guitar solo. 原版以吉他独奏为特色。"},{"id":1715,"word":"silence","pronunciation":"/'saɪləns/","meaning":"n.寂静;沉默 v.使安静;压制","unit":6,"lesson":3,"seq":7,"isStar":false,"memo":"对照 silent adj.沉默的；安静的→silence n.&v.","example":"It's an attempt to silence the opposition. 这是一次压制反对派的尝试。","derivative":"silent /ˈsaɪlənt/ adj.沉默的；安静的"},{"id":1716,"word":"silent","pronunciation":"/'salənt/","meaning":"adj.沉默的;安静的","unit":6,"lesson":3,"seq":0,"isStar":true,"memo":"【构词】sil-（安静，如silo静音仓）+ -ent → 像按下静音键的手机，sil-ent！","example":"The library requires silent study areas where even whispering is discouraged. 图书馆要求安静自习区，连耳语都不鼓励。","derivative":"silence /'saɪləns/ n.沉默；silently /'saɪləntli/ adv.默默地"},{"id":1717,"word":"mute","pronunciation":"/mjuːt/","meaning":"v.消音;减音 adj.沉默的;无声的 n.静音","unit":6,"lesson":3,"seq":8,"isStar":false},{"id":1718,"word":"assist","pronunciation":"/ə'sɪst/","meaning":"n.助攻 v.帮助,协助","unit":6,"lesson":3,"seq":9,"isStar":false,"memo":"【构词】as-(= ad-,朝向) + sist(站)→站在旁边,提供支持→帮助","example":"We'll do all we can to assist you. 我们会尽量帮你。","derivative":"assistant /ə'sɪstənt/ n.助手 adj.助理的;副的\nassistance /ə'sɪstəns/ n.帮助;援助;支持"},{"id":1719,"word":"assistant","pronunciation":"/ə'sɪstənt/","meaning":"n.助手 adj.助理的;副的","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1720,"word":"assistance","pronunciation":"/ə'sɪstəns/","meaning":"n.帮助;援助;支持","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1721,"word":"persist","pronunciation":"/pə'sɪst/","meaning":"v.坚持;维持;保持;持续存在","unit":6,"lesson":3,"seq":10,"isStar":false},{"id":1722,"word":"persistence","pronunciation":"/pə'sɪstəns/","meaning":"n.坚持;锲而不舍","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1723,"word":"persistent","pronunciation":"/pə'sɪstənt/","meaning":"adj.坚持不懈的;执着的","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1724,"word":"insist","pronunciation":"/ɪn'sɪst/","meaning":"v.坚持;强调","unit":6,"lesson":3,"seq":11,"isStar":false,"memo":"【联想】in(在……里) + sist(联想 sister)→几个姐妹中,妹妹一直“坚持”自己的梦想。","example":"She insisted on his wearing a suit. 她坚持要他穿西装。","derivative":"insistence /ɪn'sɪstəns/ n.坚决要求;坚持\ninsistent /ɪn'sɪstənt/ adj.坚持的"},{"id":1725,"word":"insistence","pronunciation":"/n'sɪstəns/","meaning":"n.坚决要求;坚持","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1726,"word":"insistent","pronunciation":"/ɪn'sɪstənt/","meaning":"adj.坚持的","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1727,"word":"consist","pronunciation":"/kən'sɪst/","meaning":"v.由……组成(或构成)","unit":6,"lesson":3,"seq":12,"isStar":false,"memo":"【构词】con-(一起) + sist(站)→站到一起→由……组成","example":"Its teaching staff consists of women only. 它的教师队伍全部由女性组成。"},{"id":1728,"word":"resist","pronunciation":"/rɪ'zɪst/","meaning":"v.抵制;阻挡;反抗,抵抗","unit":6,"lesson":3,"seq":13,"isStar":false,"memo":"【构词】re-(相反) + sist(站)→站在相反的位置→抵制;阻挡","example":"She finds it difficult to resist the temptation of ice cream. 她发现很难抵抗冰激凌的诱惑。","derivative":"resistant /rɪ'zɪstənt/ adj.有抵抗力的\nresistance /rɪ'zɪstəns/ n.抵制;抵抗"},{"id":1729,"word":"resistant","pronunciation":"/rɪ'zɪstənt/","meaning":"adj.有抵抗力的","unit":6,"lesson":3,"seq":0,"isStar":true,"memo":"【构词】re-（反）+ sist（站立，如 resist）+ -ant（形容词）→ ‘反着站住不动’，就是抵抗！细菌对药‘resistant’，药打不动它～","example":"Some bacteria have become resistant to common antibiotics. 某些细菌已对常用抗生素产生耐药性。","derivative":"resistance /rɪˈzɪstəns/ n.抵抗力；resist /rɪˈzɪst/ v.抵抗"},{"id":1730,"word":"resistance","pronunciation":"/r'zɪstəns/","meaning":"n.抵制;抵抗","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1731,"word":"consistent","pronunciation":"/kən'sɪstənt/","meaning":"adj.连续的;一贯的;一致的","unit":6,"lesson":3,"seq":14,"isStar":false,"memo":"【构词】con-(共同) + sist(站) + -ent(形容词后缀)→共同站在一起的→连续的;一致的","example":"They lack consistent support from peers. 他们缺乏同行的持续支持。","derivative":"consistency /kən'sɪstənsi/ n.一致性,连贯性"},{"id":1732,"word":"consistency","pronunciation":"/kən'sɪstənsi/","meaning":"n.一致性,连贯性","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1733,"word":"subsistence","pronunciation":"/səb'sstəns/","meaning":"n.勉强维持生活","unit":6,"lesson":3,"seq":15,"isStar":false},{"id":1734,"word":"transistor","pronunciation":"/træn'zɪstə(r)/","meaning":"n.晶体管","unit":6,"lesson":3,"seq":16,"isStar":false,"example":"Some want to work with digital computers and transistors. 有些人想要研究数字计算机和晶体管。"},{"id":1735,"word":"constant","pronunciation":"/'kɒnstənt/","meaning":"adj.持续不断的;始终如一的 n.常量","unit":6,"lesson":3,"seq":17,"isStar":false,"memo":"联想 con-(共同)+stant(联想 stand)→交警每天都站在马路上指挥交通,从不间断→持续不断的","example":"This entrance is in constant use. 此入口经常使用。"},{"id":1736,"word":"instant","pronunciation":"/'ɪnstənt/","meaning":"adj.立即的,立刻的;即食的 n.瞬间","unit":6,"lesson":3,"seq":18,"isStar":false,"example":"For an instant, he was tempted to flee. 有一瞬间,他很想逃走。"},{"id":1737,"word":"instantaneous","pronunciation":"/ɪnstən'teɪniəs/","meaning":"adj.立刻的,立即的","unit":6,"lesson":3,"seq":19,"isStar":false,"memo":"构词 instant(瞬间)+-aneous(形容词后缀)→立刻的,立即的","example":"TV has conditioned us to expect instantaneous answers to difficult questions. 电视使我们习惯于期待难题的即时答案。"},{"id":1738,"word":"immediate","pronunciation":"/ɪ'miːdiət/","meaning":"adj.立即的,立刻的;目前的;迫切的","unit":6,"lesson":3,"seq":20,"isStar":false,"memo":"构词 im-(否定前缀)+medi(中间的)+-ate(形容词后缀)→没有中间的(环节),直接的→立即的,立刻的","example":"Most of us find it hard to focus on our immediate tasks because of Internet distractions. 由于网络的干扰,我们大多数人发现很难专注于眼前的任务。"},{"id":1739,"word":"immediately","pronunciation":"/ɪ'midiətli/","meaning":"adv.立即;马上","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1740,"word":"mediate","pronunciation":"/'miːdiet/","meaning":"v.调停;调解;找到方法","unit":6,"lesson":3,"seq":21,"isStar":false,"memo":"对照 媒介(media)就是在两个事物之间进行调解(mediate)的。","example":"He was the one who mediated in the dispute. 他是调解这场纷争的人。","derivative":"mediator /ˈmiːdieɪtə(r)/ n.调停者; mediation /ˌmiːdieɪʃn/ n.调停;调解"},{"id":1741,"word":"mediator","pronunciation":"/'miːdieɪtə(r)/","meaning":"n.调停者","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1742,"word":"mediation","pronunciation":"/miːdi'eɪn/","meaning":"n.调停;调解","unit":6,"lesson":3,"seq":0,"isStar":true},{"id":1743,"word":"medium","pronunciation":"/'miːdiəm/","meaning":"adj.中等的 n.媒介;手段,方法","unit":6,"lesson":3,"seq":22,"isStar":false,"memo":"联想 mediu(音似“媒体”)+m→媒体是信息的传播“媒介”。","example":"The state subsidises small and medium enterprises. 国家对中小企业进行补贴。"},{"id":1744,"word":"amid","pronunciation":"/ə'mɪd/","meaning":"prep.在……过程中;在……中","unit":6,"lesson":3,"seq":23,"isStar":false},{"id":1745,"word":"midst","pronunciation":"/mɪdst/","meaning":"n.中部;中间","unit":6,"lesson":3,"seq":24,"isStar":false,"memo":"[联想] mid(中间) + st(联想 sit)→在“中间”坐。","example":"He finished his speech amid tremendous applause. 他在雷鸣般的掌声中结束了演讲。\nWe are in the midst of a fundamental change in the field of medicine. 我们正处于医学领域的根本变革之中。"},{"id":1746,"word":"medieval","pronunciation":"/ˌmedi'iːvl/","meaning":"adj.中世纪的;古老的","unit":6,"lesson":3,"seq":25,"isStar":false,"example":"He began studying medieval history. 他开始学习中世纪史。"},{"id":1747,"word":"middle-class","pronunciation":"/ˌmɪdl 'klɑːs/","meaning":"adj.中产阶级的 n.中产阶级","unit":6,"lesson":3,"seq":26,"isStar":false},{"id":1748,"word":"midday","pronunciation":"/ˈmɪddeɪ/","meaning":"n.中午;正午","unit":6,"lesson":3,"seq":27,"isStar":false,"memo":"[构词] mid(中间) + day(一天)→一天的中间(时刻)→中午;正午","example":"The train arrives at midday. 列车正午到达。"},{"id":1749,"word":"midwife","pronunciation":"/'mɪdwaɪf/","meaning":"n.助产士;接生员;产婆","unit":6,"lesson":3,"seq":28,"isStar":false},{"id":1750,"word":"intermediate","pronunciation":"/ˌɪntə'mdiət/","meaning":"adj.中间的;中等的 n.中级学生","unit":6,"lesson":3,"seq":29,"isStar":false,"memo":"[联想] inter-(在……中间) + media(媒体) + te(联想“特”)→位于中间的媒体特色不鲜明,属于“中等的”媒体。","example":"Fewer than half of Americans say they cook at an intermediate level. 不到一半的美国人说他们的烹饪水平是中等的。"},{"id":1751,"word":"intermediary","pronunciation":"/ˌntə'mɪdiəri/","meaning":"n.中间人;调解人","unit":6,"lesson":3,"seq":30,"isStar":false},{"id":1752,"word":"overtime","pronunciation":"/'əʊvətaɪm/","meaning":"n.加班(时间);加班费;加时","unit":6,"lesson":3,"seq":31,"isStar":false,"memo":"构词 over(超过)+time(时间)→超过工作时间→加班(时间);加班费;加时","example":"He does mind all the overtime. 他确实介意所有加班。"},{"id":1753,"word":"overtake","pronunciation":"/ˌəvə'teɪk/","meaning":"v.超过,赶上;突然发生","unit":6,"lesson":3,"seq":32,"isStar":false,"memo":"构词 over(在上面,超过)+take(拿)→“超过”对方才能从上方拿取。","example":"Some Asian countries have overtaken America in basic sciences. 一些亚洲国家在基础科学方面已经超过了美国。"},{"id":1754,"word":"overthrow","pronunciation":"/ˌəʊvə'θrəʊ/","meaning":"v.推翻,打倒 /'əʊvəθrə/ n.推翻,打倒","unit":6,"lesson":3,"seq":33,"isStar":false,"memo":"构词 over(在上面,翻转)+throw(扔)→推翻,打倒","example":"The rebellious officers broadcast the news of the overthrow of the monarchy. 反叛的军官们播报了推翻君主制的消息。"},{"id":1755,"word":"overflow","pronunciation":"/ˌəʊvə'fləʊ/","meaning":"v.漫出,溢出;挤满了人","unit":6,"lesson":3,"seq":34,"isStar":false,"memo":"构词 over(过度)+flow(流)→漫出,溢出","example":"The streets were overflowing with the crowds. 街上到处挤满了人。"},{"id":1756,"word":"overall","pronunciation":"/ˌəʊvər'ɔːl/","meaning":"adj.全面的,综合的 adv.全部,总计;总体上","unit":6,"lesson":3,"seq":35,"isStar":false,"memo":"构词 over(覆盖)+all(全部)→全部覆盖→全面的,综合的","example":"Overall I was disappointed. 总的来说,我感到失望。"},{"id":1757,"word":"oversee","pronunciation":"/ˌəvəˈsiː/","meaning":"v.监督;监视","unit":6,"lesson":3,"seq":36,"isStar":false},{"id":1758,"word":"overhaul","pronunciation":"/ˌəʊvəˈhɔːl/","meaning":"n.检修;改造 v.彻底检修;超过","unit":6,"lesson":3,"seq":37,"isStar":false,"memo":"构词 over(在上面)+haul(拉)→从上面拉出来,从根本上改变→检修;改造","example":"The plan was completely overhauled. 这一计划已全面修订。"},{"id":1759,"word":"overcome","pronunciation":"/ˌəʊvəˈkʌm/","meaning":"v.克服;解决;战胜","unit":6,"lesson":3,"seq":38,"isStar":false,"memo":"构词 over(越过,超过)+come(来)→越过(困难)而来→克服;战胜","example":"He finally managed to overcome his fear of flying. 他终于克服了对飞行的恐惧。"},{"id":1760,"word":"overhear","pronunciation":"/ˌəʊvəˈhə(r)/","meaning":"v.偶然听到;无意中听到","unit":6,"lesson":3,"seq":39,"isStar":false,"memo":"构词 over(在上面,超过)+hear(听见)→超出预期范围听见→无意中听到","example":"The patient overheard the news that he was seriously ill. 病人无意中听到了他病情严重的消息。"},{"id":1761,"word":"overseas","pronunciation":"/ˌəʊvəˈsiːz/","meaning":"adj.外国的;海外的 adv.在国外","unit":6,"lesson":3,"seq":40,"isStar":false,"memo":"构词 over(越过)+seas(海)→越过海洋→外国的;海外的","example":"They suspend import of necessities from overseas. 他们暂停从海外进口必需品。"},{"id":1762,"word":"override","pronunciation":"/ˌəʊvəraɪd/","meaning":"v.否决,推翻;比……更重要;凌驾于","unit":6,"lesson":3,"seq":41,"isStar":false},{"id":1763,"word":"overdue","pronunciation":"/ˌəʊvəˈdjuː/","meaning":"adj.延误的;(到期)未付的,未做的;过期的","unit":6,"lesson":3,"seq":42,"isStar":false},{"id":1764,"word":"comprehension","pronunciation":"/ˌkɒmprɪˈhenn/","meaning":"n.理解(力);理解测试","unit":6,"lesson":3,"seq":43,"isStar":false,"example":"This was utterly beyond her comprehension. 这完全超出了她的理解能力。","derivative":"comprehend /ˌkɒmprɪˈhend/ v.理解，领悟"},{"id":1765,"word":"comprehend","pronunciation":"/ˌkɒmprɪˈhend/","meaning":"v.理解,领悟","unit":6,"lesson":3,"seq":0,"isStar":true,"memo":"【构词】com-（一起）+ prehend（抓，拉丁词根）→ 把信息‘一把抓’进脑子 → 理解！就像抢答时手速快才抓得住知识点～","example":"Students must comprehend complex scientific concepts before the exam. 考试前学生必须理解复杂的科学概念。","derivative":"comprehension /kɒmprɪˈhenʃn/ n.理解；领悟"},{"id":1766,"word":"comprehensive","pronunciation":"/ˌkɒmprɪˈhensɪv/","meaning":"adj.综合的,全面的;详尽的","unit":6,"lesson":3,"seq":44,"isStar":false,"memo":"对照 阅读理解(comprehension)考查学生的英语综合(comprehensive)运用能力。","example":"The idea was to create a comprehensive road map of the Web. 这个想法是为万维网做一个全面详细的指南。"},{"id":1767,"word":"overnight","pronunciation":"/ˌəʊvəˈnaɪt/","meaning":"adv.在夜间;一夜之间,突然 /ˌəʊvənaɪt/ adj.突然的,一夜之间的","unit":6,"lesson":3,"seq":45,"isStar":false,"example":"The play was an overnight success. 这部剧一夜成名。"},{"id":1768,"word":"overturn","pronunciation":"/ˌəʊvəˈtɜːn/","meaning":"v.倾倒,倾覆;推翻","unit":6,"lesson":3,"seq":46,"isStar":false},{"id":1769,"word":"turnover","pronunciation":"/ˈtɜːnəʊvə(r)/","meaning":"n.营业额,成交量;人事变更率;人员流动率","unit":6,"lesson":3,"seq":47,"isStar":false,"memo":"联想 turn(转变) + over(超过) → 他转变商业模式，超过了同行，“营业额”大涨。","example":"The city has a rapid population turnover. 这个城市的人口流动很快。"},{"id":1770,"word":"plunge","pronunciation":"/plʌnd/","meaning":"v.使突然前冲(或下落),震荡;骤降;投入 n.突然跌落,暴跌;卷入","unit":6,"lesson":3,"seq":48,"isStar":false,"memo":"谐音 单词发音类似“扑浪激”→他把球扑通一声“投入”水中，激起浪花。","example":"Her car plunged off the cliff. 她的车突然冲下了悬崖。"},{"id":1771,"word":"slump","pronunciation":"/slʌmp/","meaning":"n.骤降,猛跌;萧条 v.倒下;骤降","unit":6,"lesson":3,"seq":49,"isStar":false},{"id":1772,"word":"lump","pronunciation":"/lʌmp/","meaning":"n.块;肿块;隆起 v.把……归并在一起","unit":6,"lesson":3,"seq":50,"isStar":false,"memo":"联想 lu(音似“拉”) + mp(联想“妹扑”)→他拉着妹妹扑过去，结果头上撞了个“肿块”。","example":"I've got a lump on my shoulder. 我的肩膀上有个肿块。"},{"id":1773,"word":"bump","pronunciation":"/bmp/","meaning":"n.碰撞(声);肿块 v.碰撞;颠簸而行","unit":6,"lesson":3,"seq":51,"isStar":false,"memo":"谐音 单词发音类似“梆”→他倒在桌子上，发出“梆”的“碰撞声”，头上出现了一个“肿块”。","example":"They bumped into each other over a swimming pool. 他们在游泳池上空撞到了一起。"},{"id":1774,"word":"dump","pronunciation":"/dʌmp/","meaning":"n.垃圾场 v.丢弃,倾倒","unit":6,"lesson":3,"seq":52,"isStar":false,"memo":"对照 车辆在垃圾场(dump)旁相撞(bump)。","example":"Something which goes into the dumps would be made into something useful. 进入垃圾场的一些东西会被做成有用的东西。"},{"id":1775,"word":"slash","pronunciation":"/slæʃ/","meaning":"v.砍,劈;大幅削减 n.砍,劈;伤口","unit":6,"lesson":3,"seq":53,"isStar":false},{"id":1776,"word":"assign","pronunciation":"/ə'saɪn/","meaning":"v.委派,指派;分配","unit":6,"lesson":4,"seq":1,"isStar":false,"memo":"联想 as-(一再地)+sign(签字)→老板一再签字,“委派”人员去执行任务。","example":"The company assigned her to an agricultural project. 公司把她委派到一个农业项目。","derivative":"assignment /əˈsaɪnmənt/ n.任务,分配"},{"id":1777,"word":"assignment","pronunciation":"/ə'saɪnmənt/","meaning":"n.任务;分配","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1778,"word":"signify","pronunciation":"/'sɪɡnɪfa/","meaning":"v.代表;表示;象征;要紧","unit":6,"lesson":4,"seq":2,"isStar":false,"memo":"构词 sign(标记)+-ify(动词后缀)→使……标记化→代表;表示;象征","example":"Diplomas and certificates still weigh heavily in terms of signifying one's ability. 文凭和证书在表明一个人的能力方面仍然很重要。"},{"id":1779,"word":"significant","pronunciation":"/sɡ'nɪfɪkənt/","meaning":"adj.重大的,重要的;显著的","unit":6,"lesson":4,"seq":3,"isStar":false,"memo":"联想 sig(n)(签字)+nifi(音似“你非”)+c+-ant(形容词后缀)→这是件“重要的”的事,你非签字不可。","example":"There is a significant increase of opportunities. 机会显著增加。","derivative":"significance /sɪɡˈnɪfɪkəns/ n.意义,重要性"},{"id":1780,"word":"significance","pronunciation":"/sɪɡ'nɪfɪkəns/","meaning":"n.意义,重要性","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1781,"word":"resign","pronunciation":"/rɪ'zaɪn/","meaning":"v.辞职,辞去","unit":6,"lesson":4,"seq":4,"isStar":false,"memo":"联想 re-(=off,离去)+sign(签字)→签字后离去→辞职,辞去","example":"She has made up her mind to resign. 她已下定决心辞职。","derivative":"resignation /ˌrezɪɡneɪʃn/ n.辞职;辞职信"},{"id":1782,"word":"resignation","pronunciation":"/ˌrezɪɡ'neʃn/","meaning":"n.辞职;辞职信","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1783,"word":"appoint","pronunciation":"/ə'pɔɪnt/","meaning":"v.任命,委任,安排;确定","unit":6,"lesson":4,"seq":5,"isStar":false,"memo":"联想 ap-(一再地)+point(指向)→老板一再指向他,“任命”他做某事,是在给他“安排”工作。","example":"They appointed a new manager to coordinate the work of the team. 为协调这个团队的工作,他们任用了一位新经理。","derivative":"appointment /əˈpɪntmənt/ n.约会;预约;约定"},{"id":1784,"word":"appointment","pronunciation":"/ə'pɔɪntmənt/","meaning":"n.约会;预约;约定","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1785,"word":"designate","pronunciation":"/'dezɡneɪt/","meaning":"v.指派;指定;标明","unit":6,"lesson":4,"seq":6,"isStar":false,"memo":"构词 nomin(= name) + -ate(动词后缀)→使名字出现→提名","example":"The school has been designated a specialist science academy. 这所学校被指定为专门的科学院。","derivative":"designation /ˌdezɪɡˈneɪʃn/ n.选定;委任;名称"},{"id":1786,"word":"designation","pronunciation":"/dezɪɡ'neɪʃn/","meaning":"n.选定;委任;名称","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1787,"word":"nominate","pronunciation":"/'nɒmɪneɪt/","meaning":"v.提名;任命,指派","unit":6,"lesson":4,"seq":7,"isStar":false,"example":"He is eager to be nominated as the new editor. 他渴望被提名为新编辑。","derivative":"nominee /ˌnɒmɪˈniː/ n.被任命者\nnomination /ˌnɒmɪneɪʃn/ n.提名;任命;指派"},{"id":1788,"word":"nominee","pronunciation":"/ˌnɒm'niː/","meaning":"n.被任命者","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1789,"word":"nomination","pronunciation":"/ˌnmɪ'neɪn/","meaning":"n.提名;任命,指派","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1790,"word":"nominal","pronunciation":"/'nmɪnl/","meaning":"adj.名义上的;有名无实的;很小的","unit":6,"lesson":4,"seq":8,"isStar":false,"example":"He remained in nominal control of the business for another ten years. 他名义上又掌管了这家公司十年。"},{"id":1791,"word":"culminate","pronunciation":"/'kʌlmɪneɪt/","meaning":"v.告终,结束","unit":6,"lesson":4,"seq":9,"isStar":false,"memo":"联想 cul(音似“卡了”) + minate(联想 nominate)→他被卡在了提名环节,意味着竞选之路“结束”了。","example":"He is desperate because all his efforts culminated in failure. 他很绝望,因为他所有的努力都以失败告终。"},{"id":1792,"word":"namely","pronunciation":"/'neɪmli/","meaning":"adv.即,也就是","unit":6,"lesson":4,"seq":10,"isStar":false,"example":"In the past, electric vehicles have their problems, namely, a limited driving range. 在过去,电动汽车也有它们存在的问题,即行驶里程有限。"},{"id":1793,"word":"nickname","pronunciation":"/'nɪkneɪm/","meaning":"n.绰号,外号 v.给……起绰号","unit":6,"lesson":4,"seq":11,"isStar":false},{"id":1794,"word":"patch","pronunciation":"/pætʃ/","meaning":"n.斑;小块;补丁","unit":6,"lesson":4,"seq":13,"isStar":false},{"id":1795,"word":"abuse","pronunciation":"/ə'bjuːs/","meaning":"n.滥用;虐待 /ə'bjuːz/ v.滥用;虐待","unit":6,"lesson":4,"seq":14,"isStar":false,"memo":"构词 ab-(否定前缀) + use(使用)→不好好使用→滥用;虐待","example":"Abuse of medicines should be resolutely resisted. 滥用药物应当坚决抵制。","derivative":"abusive /əˈbjuːsɪv/ adj.辱骂的;虐待的"},{"id":1796,"word":"abusive","pronunciation":"/ə'bju:sɪv/","meaning":"adj.辱骂的;虐待的","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1797,"word":"abolish","pronunciation":"/ə'bɒlɪ/","meaning":"v.废除,废止","unit":6,"lesson":4,"seq":15,"isStar":false,"example":"The government was planning to abolish subsidies to farmers. 政府正在计划取消对农民的补贴。","derivative":"abolition /əˈbɒlɪʃn/ n.废除,废止"},{"id":1798,"word":"abolition","pronunciation":"/ˌæbə'lɪʃn/","meaning":"n.废除,废止","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1799,"word":"abnormal","pronunciation":"/æb'nɔːml/","meaning":"adj.反常的;变态的;畸形的","unit":6,"lesson":4,"seq":16,"isStar":false,"memo":"ab-(否定前缀) + normal(正常的)→反常的","example":"Abnormal human behaviour may be caused by eating some substances. 人类异常行为可能是由摄入的某些物质造成的。"},{"id":1800,"word":"abort","pronunciation":"/ə'bɔ:t/","meaning":"v.(使)流产;(使)夭折;中止","unit":6,"lesson":4,"seq":17,"isStar":false},{"id":1801,"word":"abortion","pronunciation":"/ə'bɔːʃn/","meaning":"n.堕胎,人工流产","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1802,"word":"inborn","pronunciation":"/'ɪnbɔ:n/","meaning":"adj.天生的,先天的","unit":6,"lesson":4,"seq":18,"isStar":false},{"id":1803,"word":"appreciate","pronunciation":"/ə'pri:ʃieɪt/","meaning":"v.欣赏;理解;感激","unit":6,"lesson":4,"seq":19,"isStar":false,"memo":"ap-(一再地) + preci(联想 precious) + -ate(动词后缀)→一再说一个人珍贵,就是表达“欣赏”之情。","example":"He appreciates the sacrifice his friends have made for him. 他感激朋友们为他所做的牺牲。","derivative":"appreciation /əˌpriːʃiˈeɪn/ n.欣赏;理解;感激"},{"id":1804,"word":"appreciation","pronunciation":"/əˌpri:ʃi'eɪʃn/","meaning":"n.欣赏;理解;感激","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1805,"word":"depreciate","pronunciation":"/dɪ'pri:ʃiet/","meaning":"v.贬值;贬低;轻视","unit":6,"lesson":4,"seq":20,"isStar":false},{"id":1806,"word":"depreciation","pronunciation":"/dɪˌpri:i'eɪʃn/","meaning":"n.贬值;贬低;轻视","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1807,"word":"approach","pronunciation":"/ə'prəʊtʃ/","meaning":"n.方式,方法;接近 v.接近;对付","unit":6,"lesson":4,"seq":21,"isStar":false,"memo":"单词发音类似“饿扑肉吃”→老虎饿了想扑倒猎物吃肉,首先得“接近”猎物。"},{"id":1808,"word":"attach","pronunciation":"/ə'tæt/","meaning":"v.系;贴;绑;固定;附","unit":6,"lesson":4,"seq":22,"isStar":false,"memo":"联想 at-(一再地)+tach(音似touch)→一再地触摸,是为了把它“系”紧。","example":"I attached a copy of my notes for your information. 我附上一份笔记供你参考。","derivative":"attachment /ə'tætmənt/ n.附件;附属物;连接;依恋"},{"id":1809,"word":"attachment","pronunciation":"/ə'tætʃmənt/","meaning":"n.附件;附属物;连接;依恋","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1810,"word":"detach","pronunciation":"/dɪ'tætʃ/","meaning":"v.拆卸;分开,脱离","unit":6,"lesson":4,"seq":23,"isStar":false,"memo":"联想 de-(否定前缀)+tach(音似touch)→不触摸→分开","example":"The skis should detach from the boot if you fall. 要是你跌倒了,滑雪板就会脱离靴子。","derivative":"detached /di'tættʃt/ adj.单独的;冷漠的 detachment /di'tætʃmənt/ n.分离;超然;冷漠"},{"id":1811,"word":"detached","pronunciation":"/dɪ'tætʃt/","meaning":"adj.单独的;冷漠的","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1812,"word":"detachment","pronunciation":"/dɪ'tætʃmənt/","meaning":"n.分离;超然;冷漠","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1813,"word":"tangible","pronunciation":"/'tændʒəbl/","meaning":"adj.有形的;可触摸的","unit":6,"lesson":4,"seq":24,"isStar":false,"example":"Money as a tangible commodity has largely been replaced by credit. 货币作为一种有形的商品在很大程度上已被信用卡取代。"},{"id":1814,"word":"intangible","pronunciation":"/ɪn'tændʒəbl/","meaning":"adj.无形的;难以形容(或理解、度量)的","unit":6,"lesson":4,"seq":25,"isStar":false,"memo":"构词 in-(否定前缀)+tangible(有形的)→无形的","example":"The benefits are intangible. 好处是难以计算的。"},{"id":1815,"word":"stick","pronunciation":"/stɪk/","meaning":"v.粘贴;粘住;卡住;将……刺入;容忍 n.枝条","unit":6,"lesson":4,"seq":26,"isStar":false,"memo":"谐音 单词发音类似“死提个”→他一直提着个棍子,就像被棍子“粘住”了一样。","example":"I stuck the photos into an album. 我把照片贴到相册上。","derivative":"n.枝条"},{"id":1816,"word":"sticky","pronunciation":"/'stɪki/","meaning":"adj.黏(性)的","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1817,"word":"strike","pronunciation":"/straɪk/","meaning":"v.击,撞;罢工;突然想到 n.罢工;袭击;击打","unit":6,"lesson":4,"seq":27,"isStar":false,"memo":"联想 st(联想street)+rike(联想rock)→摇滚乐队的鼓手在街上“击”鼓。","example":"A strike has shut the factory. 罢工使工厂停业。","derivative":"n.罢工;袭击;击打"},{"id":1818,"word":"adhere","pronunciation":"/əd'hɪə(r)/","meaning":"v.黏附;附着;坚持;遵守","unit":6,"lesson":4,"seq":28,"isStar":false,"memo":"联想 ad-(一再地)+here(这里)→这里一再地有油渍黏附→黏附;坚持","example":"The bank adheres to all rules regarding the opening and closing of accounts. 该银行遵守所有关于开设和关闭账户的规定。","derivative":"adherence /əd'hɪərəns/ n.坚持;遵守"},{"id":1819,"word":"adherence","pronunciation":"/əd'hɪərəns/","meaning":"n.坚持;遵守","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1820,"word":"cling","pronunciation":"/klɪ/","meaning":"v.抓紧,紧抱;粘住,附着;依恋","unit":6,"lesson":4,"seq":29,"isStar":false,"memo":"谐音 单词发音类似“可怜”→那个可怜的孩子“紧抱”着母亲,一刻都不肯放开。","example":"Other birds unknowingly carry seeds that cling to them for the ride. 其他鸟类在不知不觉中携带了附着在它们身上的种子,让种子搭便车。"},{"id":1821,"word":"abide","pronunciation":"/ə'baɪd/","meaning":"v.遵守;容忍","unit":6,"lesson":4,"seq":30,"isStar":false,"memo":"联想 ab-(一再地)+i(我)+de(联想“的”)→我一再强调我会遵纪守法的→遵守","example":"We have got to abide by the rules. 我们必须遵守规则。"},{"id":1822,"word":"comply","pronunciation":"/kəm'pla/","meaning":"v.遵守;服从,顺从","unit":6,"lesson":4,"seq":31,"isStar":false,"memo":"联想 com-(都)+p(联想“趴”)+ly(音似lie,躺)→他们都趴在国王的王座下或躺在他的脚下,以示“服从”他。","example":"People who refuse to comply with the law will be punished. 拒绝遵守法律的人将受到惩罚。"},{"id":1823,"word":"compliance","pronunciation":"/kəm'plaɪəns/","meaning":"n.服从;遵从","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1824,"word":"obedient","pronunciation":"/ə'biːdiənt/","meaning":"adj.顺从的,服从的","unit":6,"lesson":4,"seq":32,"isStar":false,"memo":"谐音：单词发音类似“我必等他”→我服从安排，必须等他→服从的","example":"He was always obedient to his father’s wishes. 他一向顺从父亲的意愿。","derivative":"obedience /əˈbiːdiəns/ n. 顺从，服从"},{"id":1825,"word":"obedience","pronunciation":"/ə'biːdiəns/","meaning":"n.顺从,服从","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1826,"word":"acupuncture","pronunciation":"/'ækjupʌŋktʃə(r)/","meaning":"n.针刺疗法,针灸","unit":6,"lesson":4,"seq":33,"isStar":false,"memo":"联想：ac-(一再) + u(字母音似“有”) + puncture(小孔)→我一再发现他身上有小孔，推测他刚做完“针灸”。","example":"Acupuncture techniques have been perfected. 针灸技术已经完善。"},{"id":1827,"word":"accord","pronunciation":"/ə'kɔːd/","meaning":"n.符合;协议;正式协议 v.给予;(与……)一致,相符","unit":6,"lesson":4,"seq":34,"isStar":false,"memo":"对照：according to 根据，按照→accord n. & v.","example":"The accord underlined Italy’s global reputation. 该协议突显了意大利在全球的声誉。","derivative":"accordance /əˈkɔːdəns/ n. 依照，依据"},{"id":1828,"word":"accordance","pronunciation":"/ə'kɔːdns/","meaning":"n.依照,依据","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1829,"word":"accordingly","pronunciation":"/ə'kɔːdŋli/","meaning":"adv.相应地;因此,从而","unit":6,"lesson":4,"seq":35,"isStar":false,"memo":"构词：accord(相符) + -ing(动名词后缀) + -ly(副词后缀)→相应地","example":"Accordingly, they should not be put into jobs that are inconsistent with their needs. 因此，他们不应该从事与他们的需求不一致的工作。"},{"id":1830,"word":"discord","pronunciation":"/'dskɔːd/","meaning":"n.不一致;不和,纷争","unit":6,"lesson":4,"seq":36,"isStar":false},{"id":1831,"word":"record","pronunciation":"/'rekɔːd/","meaning":"n.记录;记载 /rɪ'kɔd/ v.记录;录制","unit":6,"lesson":4,"seq":37,"isStar":false,"example":"You should keep a record of your expenses. 你应该记下你的各项开支。","derivative":"recording /rɪˈkɔdɪŋ/ n. 录制，音像制品\nrecorder /rɪˈkɔdə(r)/ n. 记录员；录音机"},{"id":1832,"word":"recording","pronunciation":"/rɪ'kɔːdɪŋ/","meaning":"n.录制,音像制品","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1833,"word":"recorder","pronunciation":"/rɪ'kɔːdə(r)/","meaning":"n.记录员;录音机","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1834,"word":"document","pronunciation":"/'dɒkjumənt/","meaning":"n.文件,公文;文档 /'dɒkjument/ v.记录,记载","unit":6,"lesson":4,"seq":38,"isStar":false,"memo":"联想：do(音似“捣”) + cu(联想“促”) + -ment(名词后缀)→他在房间里捣鼓一上午了，被领导催促整理“文件”。","example":"I didn’t take those important documents with me. 我没把那些重要文件带走。","derivative":"documentary /ˌdɒkjuˈmentri/ n. 纪录片 adj. 纪实的；文件的；文献的"},{"id":1835,"word":"documentary","pronunciation":"/ˌdɒkju'mentri/","meaning":"n.纪录片 adj.纪实的;文件的;文献的","unit":6,"lesson":4,"seq":0,"isStar":true},{"id":1836,"word":"accommodate","pronunciation":"/əˈkɒmədeɪt/","meaning":"v.为(某人)提供住宿;容纳;适应","unit":7,"lesson":1,"seq":1,"isStar":false,"memo":"联想: ac-(一再地)+commo(联想come)+date(约会)→他一再地来跟我约会,帮我“适应”了周围环境。","example":"The new apartments can accommodate 500 students. 新公寓可容纳500名学生。","derivative":"accommodation /əˌkɒməˈdeɪʃn/ n.住处;办公处;住宿;和解"},{"id":1837,"word":"accommodation","pronunciation":"/əˌkɒməˈdeɪʃn/","meaning":"n.住处;办公处;住宿;和解","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1838,"word":"adapt","pronunciation":"/əˈdæpt/","meaning":"v.使适应,使适合;改造;改编","unit":7,"lesson":1,"seq":2,"isStar":false,"memo":"联想: ad(联想“阿弟”)+a(一)+pt(联想“普通”)→阿弟适应了做一个普通人→使适应","example":"It takes them longer to adapt to the high beach temperature. 它们需要更长的时间来适应较高的海滩温度。","derivative":"adaptation /ˌædæpˈteɪʃn/ n.适应;改编本; adaptive /əˈdæptɪv/ adj.适应的;有适应能力的"},{"id":1839,"word":"adaptation","pronunciation":"/ˌædæpˈteɪʃn/","meaning":"n.适应;改编本","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1840,"word":"adaptive","pronunciation":"/əˈdæptɪv/","meaning":"adj.适应的;有适应能力的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1841,"word":"adopt","pronunciation":"/əˈdpt/","meaning":"v.收养;采用;采取,采纳","unit":7,"lesson":1,"seq":3,"isStar":false,"memo":"联想: ad(联想“阿弟”)+o(形似洞)+pt(联想“葡萄”)→阿弟发现一个小孩在山洞外吃葡萄,便“采纳”同村人的意见“收养”了他。","example":"Karen was adopted by the couple. 凯伦被这对夫妻收养了。","derivative":"adoption /əˈdɒpʃn/ n.收养;采用;推选"},{"id":1842,"word":"adoption","pronunciation":"/əˈdɒpʃn/","meaning":"n.收养;采用;推选","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1843,"word":"accustom","pronunciation":"/əˈkstəm/","meaning":"v.使习惯;使适应","unit":7,"lesson":1,"seq":4,"isStar":false,"memo":"联想: ac-(一再地)+custom(风俗)→一再地在一个风俗里面→使习惯;使适应","example":"You must accustom yourself to feeling more at ease when you are with strangers. 你必须使自己习惯和陌生人在一起时更加自在。","derivative":"accustomed /əˈkʌstəmd/ adj.惯常的;习惯的"},{"id":1844,"word":"accustomed","pronunciation":"/əˈkʌstəmd/","meaning":"adj.惯常的;习惯的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1845,"word":"custom","pronunciation":"/ˈkʌstəm/","meaning":"n.习惯;习俗,风俗;光顾","unit":7,"lesson":1,"seq":5,"isStar":false,"memo":"谐音: 单词发音类似“卡死他们”→他们被旧社会的“习俗”给卡(限制)住了。","example":"It’s a local custom to eat eggs during the Dragon Boat Festival. 端午节吃鸡蛋是当地的风俗。","derivative":"customary /ˈkʌstəmeri/ adj.习俗的;习惯的"},{"id":1846,"word":"customary","pronunciation":"/ˈkʌstəməri/","meaning":"adj.习俗的;习惯的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1847,"word":"customs","pronunciation":"/ˈkʌstəmz/","meaning":"n.海关;关税","unit":7,"lesson":1,"seq":6,"isStar":false,"memo":"对照 设置海关(customs)是多数国家的习惯(custom)。","example":"You must pay customs on all imports of alcohol. 你必须为所有进口的酒缴纳关税。"},{"id":1848,"word":"customer","pronunciation":"/ˈkʌstəmə(r)/","meaning":"n.顾客,客户,消费者","unit":7,"lesson":1,"seq":7,"isStar":false,"memo":"构词 custom(光顾)+-er(表示人的后缀)→光顾的人→消费者","example":"The ability to guard customer data is the key to market value. 保护消费者信息的能力是市场价值的关键因素。"},{"id":1849,"word":"client","pronunciation":"/ˈklaɪənt/","meaning":"n.顾客,客户","unit":7,"lesson":1,"seq":8,"isStar":false,"memo":"谐音 单词发音类似“可来他”→“顾客”可来了,他终于开张了。","example":"I have scheduled an appointment with a client at dinner time. 我已经约了一位客户在晚餐时间见面。"},{"id":1850,"word":"patron","pronunciation":"/ˈpeɪtrən/","meaning":"n.赞助人,赞助商;顾客","unit":7,"lesson":1,"seq":9,"isStar":false},{"id":1851,"word":"patronise/-ize","pronunciation":"/ˈpætrənaɪz/","meaning":"v.赞助;光顾","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1852,"word":"patronage","pronunciation":"/ˈpætrənɪdʒ;<br>ˈpetrənɪdʒ/","meaning":"n.赞助;惠顾","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1853,"word":"sponsor","pronunciation":"/ˈspɒnsə(r)/","meaning":"n.赞助者,赞助商;倡议者 v.赞助,资助;提交(法案等)","unit":7,"lesson":1,"seq":10,"isStar":false,"memo":"联想 spon(音似“死帮”)+sor(音似sir)→作为先生的“赞助者”,他努力帮助先生。","example":"The race organizers are trying to attract sponsors. 这次比赛的组织者在想方设法吸引赞助商。","derivative":"sponsorship /'spɒnsəʃɪp/ n.资助;倡议"},{"id":1854,"word":"sponsorship","pronunciation":"/ˈspɒnsəʃɪp/","meaning":"n.资助;倡议","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1855,"word":"spontaneous","pronunciation":"/spɒnˈteniəs/","meaning":"adj.自发的;自然的","unit":7,"lesson":1,"seq":11,"isStar":false,"memo":"联想 sponta(音似“死帮他”)+neous→他努力帮助那位先生的行为是“自发的”。","example":"Creativity is spontaneous inspiration. 创造力是自发产生的灵感。","derivative":"spontaneity /ˌspɒntə'neɪəti/ n.自发性;自然"},{"id":1856,"word":"spontaneity","pronunciation":"/ˌspɒntəˈneɪəti/","meaning":"n.自发性;自然","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1857,"word":"exhaust","pronunciation":"/ɪɡˈzɔːst/","meaning":"v.使筋疲力尽;用完,耗尽","unit":7,"lesson":1,"seq":12,"isStar":false,"memo":"谐音 单词发音类似“一个早死的”→如果一个人死得早,那有可能是因为他的体力早早地“耗尽”了。","example":"A full day's work exhausted him. 一天的工作令他精疲力竭。","derivative":"exhaustion /ɪɡzɔːstʃən/ n.耗尽;筋疲力尽\nexhaustive /ɪɡzɔːstɪv/ adj.详尽的;彻底的;全面的"},{"id":1858,"word":"exhaustion","pronunciation":"/ɪɡˈzɔːstən/","meaning":"n.耗尽;筋疲力尽","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1859,"word":"exhaustive","pronunciation":"/ɪɡˈzɔstɪv/","meaning":"adj.详尽的;彻底的;全面的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1860,"word":"weary","pronunciation":"/ˈwɪəri/","meaning":"adj.疲劳的,疲倦的,疲惫的","unit":7,"lesson":1,"seq":13,"isStar":false,"memo":"对照 他穿上(wear)衣服,拖着疲惫的(weary)身躯出门了。","example":"Rachel looked pale and weary. 雷切尔看起来脸色苍白,疲惫不堪。","derivative":"weariness /'wɪərɪnəs/ n.疲倦"},{"id":1861,"word":"weariness","pronunciation":"/ˈwərɪnəs/","meaning":"n.疲倦","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1862,"word":"labo(u)r","pronunciation":"/ˈlebə(r)/","meaning":"n.劳动;劳动力","unit":7,"lesson":1,"seq":14,"isStar":false},{"id":1863,"word":"laborious","pronunciation":"/ləˈbɔːriəs/","meaning":"adj.耗时费力的;辛苦的","unit":7,"lesson":1,"seq":0,"isStar":true,"memo":"【构词】labor（劳动）+ -ious（充满…的）→‘充满劳作的’！不是‘拉伯瑞厄斯’，是‘lab-or-i-ous’，每音节都像在搬砖。","example":"Translating ancient texts is a laborious but rewarding academic task. 翻译古籍是一项费力但富有回报的学术任务。","derivative":"labor /ˈleɪbər/ n.劳动；laboriously /ləˈbɔːriəsli/ adv.费力地"},{"id":1864,"word":"leisure","pronunciation":"/ˈleʒə(r)/","meaning":"n.空闲,闲暇","unit":7,"lesson":1,"seq":15,"isStar":false,"memo":"联想 lei(联想“累”)+sure(的确)→他的确累了,想找个“空闲”时间放松一下。","example":"These days we have increased opportunities for leisure. 如今,我们有了更多的休闲机会。","derivative":"leisurely /'leʒəli/ adj.慢悠悠的 adv.从容地"},{"id":1865,"word":"leisurely","pronunciation":"/ˈleəli/","meaning":"adj.慢悠悠的 adv.从容地","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1866,"word":"fatigue","pronunciation":"/fəˈtiːɡ/","meaning":"n.疲乏,疲劳,劳累","unit":7,"lesson":1,"seq":16,"isStar":false,"memo":"联想 fat(胖的)+i(我)+gue(音似“哥”)→我哥哥很胖,容易“疲劳”。","example":"Fatigue results from lack of sleep. 缺乏睡眠会导致疲劳。"},{"id":1867,"word":"obese","pronunciation":"/əʊbiːs/","meaning":"adj.臃肿的,虚胖的,病态肥胖的","unit":7,"lesson":1,"seq":17,"isStar":false},{"id":1868,"word":"obesity","pronunciation":"/əʊˈbisəti/","meaning":"n.肥胖","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1869,"word":"feasible","pronunciation":"/ˈfiːzəbl/","meaning":"adj.可行的,行得通的","unit":7,"lesson":1,"seq":18,"isStar":false,"memo":"联想 fea(音似“肥”)+si(联想“四”)+(i)ble(形容词后缀)→减肥四斤的计划是“可行的”。","example":"I would argue that this is a perfectly feasible solution. 我认为这是一个完全可行的解决方案。","derivative":"feasibility /ˌfiːzə'bɪləti/ n.可行性,可能性"},{"id":1870,"word":"feasibility","pronunciation":"/fiːzəˈbɪləti/","meaning":"n.可行性,可能性","unit":7,"lesson":1,"seq":19,"isStar":false},{"id":1871,"word":"ponder","pronunciation":"/ˈpɒndə(r)/","meaning":"v.沉思,考虑,琢磨","unit":7,"lesson":1,"seq":20,"isStar":false,"memo":"联想 pond(音似“胖的”)+er(表示人的后缀)→有的胖人经常“沉思”该怎么减肥。","example":"The professor found himself constantly pondering the question. 这位教授发现自己经常在思考这个问题。"},{"id":1872,"word":"response","pronunciation":"/rɪˈspɒns/","meaning":"n.回答,答复;反应,响应","unit":7,"lesson":1,"seq":21,"isStar":false,"memo":"联想 re(字母音似“阿姨”)+spon(音似“是棒”)+se→阿姨“反应”很快,是很棒的。","example":"One of the examples of how the mind can alter the immune response was discovered by chance. 关于大脑如何改变免疫反应的一个例子是偶然被发现的。","derivative":"respond /rɪ'spɒnd/ v.回答,回应;作出反应"},{"id":1873,"word":"respond","pronunciation":"/rɪˈspɒnd/","meaning":"v.回答,回应;作出反应","unit":7,"lesson":1,"seq":0,"isStar":true,"memo":"【构词】re-（回）+ spond（承诺，如 sponsor=担保人），一诺千金→有回应就是守诺，所以‘回复/反应’！","example":"Students must respond promptly to the online survey about teaching quality. 学生须及时回复关于教学质量的在线问卷。","derivative":"response /rɪˈspɒns/ n.回应；反应"},{"id":1874,"word":"respondent","pronunciation":"/rɪˈspɒndənt/","meaning":"n.回答问题的人;(尤指)调查对象","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1875,"word":"responsive","pronunciation":"/rɪspɒnsɪv/","meaning":"adj.反应快的,灵敏的,积极(回应)的","unit":7,"lesson":1,"seq":22,"isStar":false},{"id":1876,"word":"feedback","pronunciation":"/ˈfidbæk/","meaning":"n.反馈意见(或信息)","unit":7,"lesson":1,"seq":23,"isStar":false,"memo":"feed(喂) + back(回来) → 我喂你一口，你再喂我一口，这就是对我的行为给予的反馈→反馈意见","example":"There is a huge value in learning with instant feedback. 即时反馈在学习中有着巨大的价值。"},{"id":1877,"word":"echo","pronunciation":"/ˈekəʊ/","meaning":"v. & n.回声;反响;共鸣","unit":7,"lesson":1,"seq":24,"isStar":false,"memo":"单词发音类似“隘口”→站在狭隘的洞口大喊会有“回声”。","example":"Her footsteps echoed in the empty room. 她的脚步声在空荡荡的屋子里回响。"},{"id":1878,"word":"correspond","pronunciation":"/ˌkɒrəˈspɒnd/","meaning":"v.相一致,符合,类似于……;通信","unit":7,"lesson":1,"seq":25,"isStar":false,"memo":"cor-(一起，都) + respond(回应) → 一起回应，异口同声→相一致，符合","example":"We haven't corresponded for a long time. 我们好久没有通信了。","derivative":"correspondence /kɒrəˈspɒndəns/ n.相关；通信\n correspondent /ˌkrəˈspɒndənt/ n.记者；通讯员；通信者\n corresponding /ˌkrəˈspɒndɪŋ/ adj.符合的；相应的；相关的"},{"id":1879,"word":"correspondence","pronunciation":"/ˌkɒrəˈspɒndəns/","meaning":"n.相关;通信","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1880,"word":"correspondent","pronunciation":"/ˌkrəˈspɒndənt/","meaning":"n.记者;通讯员;通信者","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1881,"word":"corresponding","pronunciation":"/ˌkɒrəspɒndɪŋ/","meaning":"adj.符合的;相应的;相关的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1882,"word":"restore","pronunciation":"/rɪˈstɔː(r)/","meaning":"v.恢复;修复;重新采用;归还","unit":7,"lesson":1,"seq":26,"isStar":false,"memo":"re-(再，重新) + store(储存) → 文物有了损伤，要先“修复”好才能重新储存。","example":"It should be our goal to restore as much of the original beauty of nature as we can. 我们的目标应该是尽可能多地恢复大自然的原始之美。","derivative":"restoration /ˌrestəˈreɪʃn/ n.恢复；修复；归还"},{"id":1883,"word":"restoration","pronunciation":"/ˌrestəreɪʃn/","meaning":"n.恢复;修复;归还","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1884,"word":"lounge","pronunciation":"/landʒ/","meaning":"n.(机场等的)等候室;公共休息室;起居室 v.懒洋洋地站(或坐、躺)着","unit":7,"lesson":1,"seq":27,"isStar":false,"memo":"loun(音似“劳”) + ge(联想“哥”) → 哥哥很劳累，正在“公共休息室”休息。","example":"The lounge is not a place for him to study in. 休息室不是他学习的地方。"},{"id":1885,"word":"shelter","pronunciation":"/ˈʃeltə(r)/","meaning":"n.遮蔽,庇护;庇护所;避难所v.为……提供庇护所;收容;躲避","unit":7,"lesson":1,"seq":28,"isStar":false,"memo":"单词发音类似“歇了他”→他实在太累了，在“避难所”歇息了一下。","example":"The homeless man sought shelter from the rain under a bridge. 那个无家可归的人在桥下躲避雨水。"},{"id":1886,"word":"haven","pronunciation":"/ˈheɪvn/","meaning":"n.安全的地方;避难所","unit":7,"lesson":1,"seq":29,"isStar":false},{"id":1887,"word":"harbo(u)r","pronunciation":"/ˈhɑːbə(r)/","meaning":"n.海港,港口 v.庇护;怀有","unit":7,"lesson":1,"seq":30,"isStar":false},{"id":1888,"word":"slum","pronunciation":"/slʌm/","meaning":"n.贫民窟,贫民区;非常脏乱的地方","unit":7,"lesson":1,"seq":31,"isStar":false,"memo":"slu(音似“死拉”) + m(联想“妹”) → 他拼命地拉着妹妹离开“贫民窟”。","example":"She was brought up in the slums of Leeds. 她是在利兹的贫民区长大的。"},{"id":1889,"word":"tend","pronunciation":"/tend/","meaning":"v.往往会;趋于,倾向;照管,护理","unit":7,"lesson":1,"seq":32,"isStar":false,"memo":"联想 ten(十)+d(音似“的”)→人是不可能十全十美的,只能“趋于”完美。","example":"Women tend to live longer than men. 女性往往比男性长寿。","derivative":"tendency /'tendənsi/ n.倾向,趋势"},{"id":1890,"word":"tendency","pronunciation":"/ˈtendənsi/","meaning":"n.倾向,趋势","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1891,"word":"attend","pronunciation":"/ətend/","meaning":"v.出席,参加;照顾","unit":7,"lesson":1,"seq":33,"isStar":false,"memo":"联想 at-(一再地)+tend(趋于→延伸)→课堂上他一再地延伸手臂(举手),积极“参加”课堂活动。","example":"The woman doesn't want to attend the lecture. 这位女士不想参加讲座。","derivative":"attendance /ə'tendəns/ n.出席,参加;上学\nattendant /ə'tendənt/ n.服务员;随从;护理者"},{"id":1892,"word":"attendance","pronunciation":"/əˈtendəns/","meaning":"n.出席,参加;上学","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1893,"word":"attendant","pronunciation":"/əˈtendənt/","meaning":"n.服务员;随从;护理者","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1894,"word":"contend","pronunciation":"/kənˈtend/","meaning":"v.主张,认为;竞争,争夺","unit":7,"lesson":1,"seq":34,"isStar":false,"memo":"联想 con-(所有)+tend(延伸)→课堂上所有的同学都伸手表述自己“主张”的观点,同学之间的关系就是“竞争”。","example":"He contends that the ruling could have profound effects on other industries. 他认为,这项裁决可能对其他行业产生深远的影响。"},{"id":1895,"word":"contention","pronunciation":"/kənˈtenʃn/","meaning":"n.争吵,争执;看法,观点","unit":7,"lesson":1,"seq":35,"isStar":false},{"id":1896,"word":"contentious","pronunciation":"/kənˈtenəs/","meaning":"adj.引起争论的;爱争论的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1897,"word":"intend","pronunciation":"/ɪnˈtend/","meaning":"v.打算,计划,想要;意指","unit":7,"lesson":1,"seq":36,"isStar":false,"memo":"构词 in(里面)+tend(延伸)→(想法)在里面(内心)延伸→打算","example":"She was intending to work part time. 她打算做兼职工作。"},{"id":1898,"word":"intent","pronunciation":"/ɪnˈtent/","meaning":"n.意图,目的 adj.热切的;专注的","unit":7,"lesson":1,"seq":37,"isStar":false,"example":"She denies possessing the drug with intent to supply. 她否认拥有毒品是为了提供给别人。"},{"id":1899,"word":"intention","pronunciation":"/ɪnˈtenʃn/","meaning":"n.打算;意图,目的","unit":7,"lesson":1,"seq":38,"isStar":false,"memo":"对照 intend v.打算→intention n.","example":"Her intentions in making this proposal are clear. 她提出这个建议的意图很明显。"},{"id":1900,"word":"intentional","pronunciation":"/ɪnˈtenʃənl/","meaning":"adj.故意的,存心的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1901,"word":"extend","pronunciation":"/ɪk'stend/","meaning":"v.延伸;延长;扩展","unit":7,"lesson":1,"seq":39,"isStar":false,"memo":"构词 ex-(向外)+tend(延伸)→延伸","example":"Careful maintenance can extend the life of your car. 精心保养可延长你的汽车寿命。","derivative":"extended /ɪkˈstendd/ adj.延长了的;扩展了的\nextension /ɪkstenʃn/ n.扩大;延伸\nextensive /ɪkˈstensɪv/ adj.广阔的;大量的;广泛的"},{"id":1902,"word":"extended","pronunciation":"/ɪk'stendɪd/","meaning":"adj.延长了的;扩展了的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1903,"word":"extension","pronunciation":"/ɪk'stenʃn/","meaning":"n.扩大;延伸","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1904,"word":"extensive","pronunciation":"/ɪk'stensɪv/","meaning":"adj.广阔的;大量的;广泛的","unit":7,"lesson":1,"seq":40,"isStar":false},{"id":1905,"word":"stretch","pronunciation":"/stretʃ/","meaning":"v.伸展,舒展;拉紧;拉长 n.一片;(连续的)一段时间;伸展","unit":7,"lesson":1,"seq":41,"isStar":false,"memo":"谐音 单词发音类似“死拽扯”→他伸出手臂拼命地拽我,拉我→伸展","example":"The exercises are designed to stretch your leg muscles. 这些活动的目的在于伸展你的腿部肌肉。"},{"id":1906,"word":"space","pronunciation":"/speɪs/","meaning":"n.外层空间;太空;空间","unit":7,"lesson":1,"seq":42,"isStar":false,"example":"I'll clear a space for your books. 我会腾出一块空间好放你的书。","derivative":"spacious /ˈspeɪʃəs/ adj.宽敞的\nspatial /ˈspeɪʃl/ adj.空间的"},{"id":1907,"word":"spacious","pronunciation":"/'speɪʃəs/","meaning":"adj.宽敞的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1908,"word":"spatial","pronunciation":"/'speɪʃl/","meaning":"adj.空间的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1909,"word":"extent","pronunciation":"/ɪk'stent/","meaning":"n.程度;大小;范围","unit":7,"lesson":1,"seq":43,"isStar":false,"example":"To some extent what she argues is true. 她的论证在某种程度上是符合事实的。"},{"id":1910,"word":"scale","pronunciation":"/skeɪl/","meaning":"n.规模,程度;等级 v.攀登,到达……顶点","unit":7,"lesson":1,"seq":44,"isStar":false,"example":"They entertain friends on a large scale. 他们举行大规模的宴会招待朋友。"},{"id":1911,"word":"pattern","pronunciation":"/'pætn/","meaning":"n.模式,方式;榜样;图案,花样;模型","unit":7,"lesson":1,"seq":45,"isStar":false,"memo":"谐音 单词发音类似“怕疼”→怕疼就不要再往身上文“图案”了。","example":"This system sets the pattern for others to follow. 这个系统是他人仿效的典范。"},{"id":1912,"word":"dimension","pronunciation":"/daɪ'menʃn;<br>dɪ'menʃn/","meaning":"n.维(构成空间的因素);尺寸;规模; 范围;方面","unit":7,"lesson":1,"seq":46,"isStar":false,"memo":"联想 di-(两个,双)+mension(音似“门神”)→贴在门上的两个门神的“尺寸”要一样大。","example":"Our study shows that, for women, well-being has two dimensions. 我们的研究表明,对女性来说,幸福有两个维度。","derivative":"dimensional /daɪmenʃənl/ adj.尺寸的;维度的"},{"id":1913,"word":"dimensional","pronunciation":"/daɪ'menʃənl/","meaning":"adj.尺寸的;维度的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1914,"word":"mention","pronunciation":"/'menʃn/","meaning":"v.提到;写到;说到 n.提及;说起","unit":7,"lesson":1,"seq":47,"isStar":false,"memo":"谐音 单词发音类似“门神”→过年时,人们常会“提到”贴门神。","example":"He made no mention of her work. 他根本没提她的工作。"},{"id":1915,"word":"measure","pronunciation":"/'meʒə(r)/","meaning":"n.措施,方法;程度;判断;衡量 v.测量;估量,判定","unit":7,"lesson":1,"seq":48,"isStar":false,"example":"The scientists should take effective measures to protect themselves. 科学家们应该采取有效措施保护自己。","derivative":"measurement /ˈmeʒərmənt/ n.测量;度量\nmeasurable /meʒərəbl/ adj.可测量的;显著的"},{"id":1916,"word":"measurement","pronunciation":"/'meʒəmənt/","meaning":"n.测量;度量","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1917,"word":"measurable","pronunciation":"/'meʒərəbl/","meaning":"adj.可测量的;显著的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1918,"word":"apt","pronunciation":"/æpt/","meaning":"adj.恰当的;易于……,有……倾向的","unit":7,"lesson":1,"seq":49,"isStar":false,"memo":"谐音：单词发音类似“爱扑它”→爱扑它就是倾向于靠近某物→有……倾向的","example":"The words of this report are apt. 这份报告的措辞很恰当。"},{"id":1919,"word":"opt","pronunciation":"/ɒpt/","meaning":"v.选择,挑选","unit":7,"lesson":1,"seq":50,"isStar":false,"memo":"联想：op-(表示方向)+t(联想“它”)→有多个物品摆在他面前,他朝其中一个走去,“选择”了它。","example":"He notified the administration of his decision to opt out. 他通知了政府,决定选择退出。"},{"id":1920,"word":"option","pronunciation":"/'ɒpʃn/","meaning":"n.选择;可选择的东西;选项","unit":7,"lesson":1,"seq":0,"isStar":true,"derivative":"optional /'ɒpʃənl/ adj.可选择的,非强制的\n构词：option(选择)+-al(形容词后缀)→可选择的"},{"id":1921,"word":"optional","pronunciation":"/'ɒpʃənl/","meaning":"adj.可选择的,非强制的","unit":7,"lesson":1,"seq":51,"isStar":false},{"id":1922,"word":"optical","pronunciation":"/'ɒptɪkl/","meaning":"adj.视力的;视觉的;光学的;有助于视力的","unit":7,"lesson":1,"seq":52,"isStar":false,"memo":"联想：op-(表示方向)+ti(联想“踢”)+-(i)cal(形容词后缀)→他朝着某个方向踢到了别人,因为他视力不好→视力的","example":"The optical image is very clear. 这个视觉图像非常清晰。","derivative":"optic /'ɒptɪk/ adj.眼的;视觉的"},{"id":1923,"word":"optic","pronunciation":"/'ɒptɪk/","meaning":"adj.眼的;视觉的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1924,"word":"optimal","pronunciation":"/'ɒptɪməl/","meaning":"adj.最佳的;最适宜的","unit":7,"lesson":1,"seq":53,"isStar":false},{"id":1925,"word":"optimum","pronunciation":"/'ptɪməm/","meaning":"adj.最佳的;最适宜的","unit":7,"lesson":1,"seq":54,"isStar":false,"memo":"构词：optim(最好的)+-um(后缀)→最佳的;最适宜的","example":"What are the optimum conditions for economic growth? 经济增长的最佳条件是什么?"},{"id":1926,"word":"compulsory","pronunciation":"/kəm'pʌlsəri/","meaning":"adj.强制的,强迫的","unit":7,"lesson":1,"seq":55,"isStar":false,"memo":"联想：com-(所有)+pul(音似“趴”)+sory(联想 sorry)→所有护卫被迫趴在那里,跟国王说对不起→强制的,强迫的","example":"There are two main arguments for compulsory quotas. 关于强制配额有两种主要观点。"},{"id":1927,"word":"discipline","pronunciation":"/'dɪsəplɪn/","meaning":"n.训练,管教;纪律;学科,科目 v.训练;管教","unit":7,"lesson":1,"seq":56,"isStar":false,"derivative":"v.训练;管教"},{"id":1928,"word":"disciplined","pronunciation":"/'dɪsəplɪnd/","meaning":"adj.受过训练的;遵守纪律的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1929,"word":"disciplinary","pronunciation":"/ˌdɪsə'plɪnəri/","meaning":"adj.有关纪律的;惩戒性的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1930,"word":"punctual","pronunciation":"/'pʌŋktuəl/","meaning":"adj.准时的,守时的","unit":7,"lesson":1,"seq":57,"isStar":false,"memo":"联想 punct(音似“胖克他”)+-ual(形容词后缀)→他很胖,努力克服困难,每天准时锻炼→准时的","example":"He is always punctual for his class. 他总是准时上课。","derivative":"punctuality /ˌpʌŋktu'æləti/ n.准时"},{"id":1931,"word":"punctuality","pronunciation":"/ˌpʌŋktʃu'æləti/","meaning":"n.准时","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1932,"word":"principle","pronunciation":"/'prɪnsəpl/","meaning":"n.法则,原则;行为准则","unit":7,"lesson":1,"seq":58,"isStar":false,"memo":"联想 prin(联想 prince)+cip(抓)+le→王子都得抓住(遵守)“法则”。","example":"In principle, I agree with the idea. 我大体上赞成这个想法。"},{"id":1933,"word":"principal","pronunciation":"/'prɪnsəpl/","meaning":"n.校长;首长 adj.最重要的,主要的","unit":7,"lesson":1,"seq":59,"isStar":false,"memo":"联想 princi(联想 prince)+pal(联想“怕了”)→这个连王子都怕了的人是“首长”。","example":"We provide teachers and principals the support they need. 我们为老师和校长提供他们需要的支持。"},{"id":1934,"word":"methodology","pronunciation":"/ˌmeθə'dɒlədʒi/","meaning":"n.方法,原则","unit":7,"lesson":1,"seq":60,"isStar":false},{"id":1935,"word":"method","pronunciation":"/'meθəd/","meaning":"n.方法;措施;条理","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1936,"word":"methodical","pronunciation":"/mə'θɒdɪkl/","meaning":"adj.有条理的;有条不紊的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1937,"word":"ideal","pronunciation":"/a'diːəl/","meaning":"adj.完美的;理想的;最合适的","unit":7,"lesson":1,"seq":61,"isStar":false,"memo":"对照 一个理想的(ideal)人是有思想(idea)的。","example":"This beach is ideal for children. 这个海滩是孩子的理想去处。","derivative":"idealism /aɪ'dɪəlɪzəm/ n.理想主义;唯心主义\nidealistic /ˌaɪdiə'lɪstɪk/ adj.理想主义的;空想的"},{"id":1938,"word":"idealism","pronunciation":"/aɪ'diːəlɪzəm/","meaning":"n.理想主义;唯心主义","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1939,"word":"idealistic","pronunciation":"/ˌaɪdiə'lstɪk/","meaning":"adj.理想主义的;空想的","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1940,"word":"doctrine","pronunciation":"/'dɒktrɪn/","meaning":"n.教义,主义;学说,信条","unit":7,"lesson":1,"seq":62,"isStar":false,"memo":"联想 doc(联想 doctor)+trine(音似“纯”)→医生要遵守的“信条”就是“救死扶伤”,动机纯粹。","example":"He was deeply committed to political doctrines of social equality. 他深深致力于社会平等的政治学说。"},{"id":1941,"word":"dogma","pronunciation":"/'dɒɡmə/","meaning":"n.教义;信条;教条","unit":7,"lesson":1,"seq":63,"isStar":false},{"id":1942,"word":"hospitable","pronunciation":"/hɒ'spɪtəbl/","meaning":"adj.好客的,热情的","unit":7,"lesson":1,"seq":64,"isStar":false},{"id":1943,"word":"hospitality","pronunciation":"/ˌhɒspɪ'tæləti/","meaning":"n.好客,殷勤","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1944,"word":"cordial","pronunciation":"/'kɔːdiəl/","meaning":"adj.热情友好的 n.果汁","unit":7,"lesson":1,"seq":65,"isStar":false,"memo":"联想 cor(音似“靠”)+dial(音似 dear)→靠着昂贵的消费,他获得了“热情友好的”服务。","example":"I am very grateful to you for the cordial hospitality you accorded me. 承蒙你的热情招待,我十分感激。","derivative":"cordiality /ˌkɔːdi'æləti/ n.令人愉快和友好的品质"},{"id":1945,"word":"cordiality","pronunciation":"/ˌkɔdiˈæləti/","meaning":"n.令人愉快和友好的品质","unit":7,"lesson":1,"seq":0,"isStar":true},{"id":1946,"word":"acquire","pronunciation":"/əˈkwaɪə(r)/","meaning":"v.获得,得到","unit":7,"lesson":2,"seq":1,"isStar":false,"memo":"联想 ac-(一再地) + quire(询问) → 一再地询问，终会“得到”答案。","example":"Automation will help workers acquire new skills. 自动化将帮助工人获得新技能。"},{"id":1947,"word":"acquisition","pronunciation":"/ˌækwɪˈzɪʃn/","meaning":"n.获得,习得;购得物;购置","unit":7,"lesson":2,"seq":2,"isStar":false,"memo":"对照 acquire v.获得，得到 → acquisition n.","example":"Indeed, ease of acquisition is the problem. 确实，容易获得才是问题所在。"},{"id":1948,"word":"inquisitive","pronunciation":"/ɪnkwɪzətɪv/","meaning":"adj.过分好奇的;爱打听的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1949,"word":"require","pronunciation":"/rɪˈkwaɪə(r)/","meaning":"v.需要;要求","unit":7,"lesson":2,"seq":4,"isStar":false,"memo":"构词 re-(重复) + quire(询问) → 重复地询问，因为“需要”准确的信息。","example":"Breeding a wild plant into a major food crop requires much research time. 将一种野生植物培育成主要粮食作物，需要大量的研究时间。"},{"id":1950,"word":"requirement","pronunciation":"/rɪˈkwaɪərmənt/","meaning":"n.所需的东西;规定,要求","unit":7,"lesson":2,"seq":0,"isStar":true,"derivative":"requisite /ˈrekwɪzɪt/ adj.必需的 n.必需的事物"},{"id":1951,"word":"requisite","pronunciation":"/ˈrekwɪzɪt/","meaning":"adj.必需的 n.必需的事物","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1952,"word":"prerequisite","pronunciation":"/ˌpriːˈrekwɪzɪt/","meaning":"n.先决条件,前提,必备条件","unit":7,"lesson":2,"seq":5,"isStar":false,"memo":"构词 pre-(提前) + requisite(必需的事物) → 提前就需要的事物 → 先决条件，前提","example":"A degree is an essential prerequisite for employment at this level. 学位是做这级工作必备的先决条件。"},{"id":1953,"word":"plea","pronunciation":"/pliː/","meaning":"n.恳求;辩解;借口","unit":7,"lesson":2,"seq":6,"isStar":false,"memo":"对照 请(please)不要再恳求(plea)他了，他不会答应的。","example":"Hospital visiting hours were extended in response to pleas from patients. 应病人的恳求，医院延长了探视时间。","derivative":"plead /plid/ v.恳求；为……辩护"},{"id":1954,"word":"plead","pronunciation":"/pliːd/","meaning":"v.恳求;为……辩护","unit":7,"lesson":2,"seq":0,"isStar":true,"memo":"【谐音】‘ pleaded ’读如‘ pleading ’——‘求得’！跪求法官‘please, I plead!’；【构词】plea（恳求）+ -d，法律场景中‘认罪/辩护’都是求的态度。","example":"The defendant chose to plead not guilty in court. 被告选择在法庭上作无罪辩护。","derivative":"plea /pliː/ n.恳求；pleading /'pliːdɪŋ/ n.恳求；辩护"},{"id":1955,"word":"request","pronunciation":"/rɪˈkwest/","meaning":"v. & n.请求,要求","unit":7,"lesson":2,"seq":7,"isStar":false,"memo":"构词 re-(重复) + quest(寻找，追求) → 重复地寻找或追求 → 请求，要求"},{"id":1956,"word":"quest","pronunciation":"/kwest/","meaning":"n.探索;寻找;追求(幸福等) v.探索;探求","unit":7,"lesson":2,"seq":8,"isStar":false,"example":"They went in quest of gold. 他们去寻找黄金了。","derivative":"v.探索;探求"},{"id":1957,"word":"questionnaire","pronunciation":"/ˌkwestəˈneə(r)/","meaning":"n.调查表,调查问卷,问卷","unit":7,"lesson":2,"seq":9,"isStar":false,"memo":"[联想] question(问题) + naire(联想“奶”) + re (字母音似“阿姨”) → 奶奶和阿姨经常填写带有很多问题的“调查问卷”。","example":"We were asked to fill in a questionnaire. 我们被要求填写一张调查表。"},{"id":1958,"word":"pursue","pronunciation":"/pəˈsjuː/","meaning":"v.追求;致力于;追捕","unit":7,"lesson":2,"seq":10,"isStar":false,"memo":"[谐音] 单词发音类似“破书”→为了“追求”真理,他把书都翻破了。","example":"Make a commitment to pursue those things that you love most. 致力于追求那些你最热爱的事情。","derivative":"pursuit /pəˈsjut/ n.追求;追赶"},{"id":1959,"word":"pursuit","pronunciation":"/pəˈsjuːt/","meaning":"n.追求;追赶","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1960,"word":"power","pronunciation":"/ˈpaʊə(r)/","meaning":"n.权力,权势,职权;力量,动力;电力 v.驱动,推动;(使)迅猛移动","unit":7,"lesson":2,"seq":11,"isStar":false,"memo":"[谐音] 单词发音类似“怕我”→他怕我是因为我有“权势”。","example":"The powers of the police must be clearly defined. 警察的职权必须明确界定。","derivative":"v.驱动,推动;(使)迅猛移动\npowerful /ˈpaʊəfl/ adj.有权势的;力量大的"},{"id":1961,"word":"powerful","pronunciation":"/ˈpaʊəfl/","meaning":"adj.有权势的;力量大的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1962,"word":"willpower","pronunciation":"/'wlpaʊə(r)/","meaning":"n.意志力","unit":7,"lesson":2,"seq":12,"isStar":false},{"id":1963,"word":"force","pronunciation":"/fɔːs/","meaning":"n.力量;武力;影响力;部队 v.强迫;使发生","unit":7,"lesson":2,"seq":13,"isStar":false,"example":"If properly handled, it may become a driving force. 若处理得当,这也有可能转化为一种推动力。","derivative":"v.强迫;使发生\nforceful /ˈfɔsfl/ adj.强有力的;有说服力的;坚强的"},{"id":1964,"word":"forceful","pronunciation":"/'fɔːsfʊl/","meaning":"adj.强有力的;有说服力的;坚强的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1965,"word":"enforce","pronunciation":"/ɪn'fɔːs/","meaning":"v.强制执行,强行实施(法律或规定)","unit":7,"lesson":2,"seq":14,"isStar":false,"memo":"[构词] en-(使……) + force(强迫) → 使强迫发生 → 强制执行,强行实施","example":"It's the job of the police to enforce the law. 警察的工作就是执法。","derivative":"enforcement /ɪnˈfːsmənt/ n.执行"},{"id":1966,"word":"enforcement","pronunciation":"/ɪn'fɔːsmənt/","meaning":"n.执行","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1967,"word":"oblige","pronunciation":"/ə'bladʒ/","meaning":"v.迫使,强制;帮忙","unit":7,"lesson":2,"seq":15,"isStar":false,"memo":"单词发音类似“我不来挤”→我不来挤也逃不掉,因为这是我的责任和义务→迫使,强制","example":"The law obliges parents to send their children to school. 法律强制要求父母送子女上学。","derivative":"obligation /ɒblɪˈɡeɪʃn/ n.义务,职责\nobliged /əblaɪdʒd/ adj.感激的;有责任的\nobligatory /əˈblɪɡətəri/ adj.(按法律、规定等)必须的,强制的"},{"id":1968,"word":"obligation","pronunciation":"/ˌɒblɪ'geɪʃn/","meaning":"n.义务,职责","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1969,"word":"obliged","pronunciation":"/ə'blaɪdʒd/","meaning":"adj.感激的;有责任的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1970,"word":"obligatory","pronunciation":"/ə'blɪgətri/","meaning":"adj.(按法律、规定等)必须的,强 制的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1971,"word":"reinforce","pronunciation":"/ˌriːɪn'fɔːs/","meaning":"v.加强,强化;加固","unit":7,"lesson":2,"seq":16,"isStar":false,"memo":"re-(重复)+in(里面)+force(力量)→重复往里增加力量→加强;加固","example":"This conclusion was reinforced by another finding. 另一项发现强化了这一结论。","derivative":"reinforcement /ˌriːɪnˈfɔːsmənt/ n.巩固,加强;援军"},{"id":1972,"word":"reinforcement","pronunciation":"/ˌriːɪn'fɔːsmənt/","meaning":"n.巩固,加强;援军","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1973,"word":"enhance","pronunciation":"/ɪn'hɑːns/","meaning":"v.提高;增强;增进","unit":7,"lesson":2,"seq":17,"isStar":false,"memo":"en-(使)+hance(音似“汉斯”,人名)→汉斯是我的学生,我要帮他“提高”成绩。","example":"A woman's well-being is enhanced when she takes on multiple roles. 当女性扮演多重角色时,她的幸福感会增强。","derivative":"enhancement /nˈhɑːnsmənt/ n.提高,增加,增强"},{"id":1974,"word":"enhancement","pronunciation":"/n'hɑːnsmənt/","meaning":"n.提高,增加;增强","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1975,"word":"advance","pronunciation":"/əd'vɑːns/","meaning":"n.进展,进步;前进;上涨,提高 v.前 进,向前移动;进步,发展;促进;提前","unit":7,"lesson":2,"seq":18,"isStar":false,"memo":"ad-(一再地)+vance(联想“万斯”,人名)→挫折一再地使万斯“进步”。","example":"His advance in computers should be appreciated by us. 他在计算机上的进步值得我们赞赏。","derivative":"advanced /ədˈvɑːnst/ adj.先进的;高级的\nadvancement /ədˈvɑnsmənt/ n.促进;发展;前进"},{"id":1976,"word":"advanced","pronunciation":"/əd'vɑːnst/","meaning":"adj.先进的;高级的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1977,"word":"advancement","pronunciation":"/əd'vɑnsmənt/","meaning":"n.促进;发展;前进","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1978,"word":"underdeveloped","pronunciation":"/ˌʌndədɪ'veləpt/","meaning":"adj.不发达的,欠发达的;发育不 全的","unit":7,"lesson":2,"seq":19,"isStar":false},{"id":1979,"word":"boost","pronunciation":"/buːst/","meaning":"n.帮助;激励;提高 v.使增长,使兴旺","unit":7,"lesson":2,"seq":20,"isStar":false,"memo":"booT形似600)+st(联想street)→修600条街道助力农村经济增长→使增长","example":"The new policy gave a boost to the local tourism industry. 新政策激励了当地旅游业的发展。"},{"id":1980,"word":"boast","pronunciation":"/bəʊst/","meaning":"n.引以为豪的事物,感到骄傲的事物 v.自夸,自吹自擂","unit":7,"lesson":2,"seq":21,"isStar":false,"memo":"他在海岸(coast)吃烧烤(roast),一边和朋友干杯(toast),一边自夸(boast)。","example":"\"I wouldn't be afraid,\" she boasted. “我才不怕呢。”她吹嘘道。","derivative":"boastful /bəʊstfl/ adj.自吹自擂的,自夸的"},{"id":1981,"word":"boastful","pronunciation":"/'bəʊstfl/","meaning":"adj.自吹自擂的,自夸的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1982,"word":"exaggerate","pronunciation":"/ɪg'zædʒəreɪt/","meaning":"v.夸张,夸大,言过其实","unit":7,"lesson":2,"seq":22,"isStar":false,"memo":"ex-(向外)+agg(e)(联想egg)+rate(速度)→这只鸡向外下蛋的速度真“夸张”。","example":"Most studies exaggerate the effect of media violence on the viewers. 大多数研究夸大了媒体暴力对观众的影响。"},{"id":1983,"word":"overstate","pronunciation":"/ˌəʊvə'steɪt/","meaning":"v.夸大,夸张,言过其实","unit":7,"lesson":2,"seq":23,"isStar":false,"memo":"over(过度)+state(陈述)→夸大","example":"They overstate the government's interference with the food industry. 他们夸大了政府对食品行业的干预。"},{"id":1984,"word":"state","pronunciation":"/stet/","meaning":"n.状态;国家;政府;州 v.陈述,说明;声明 adj.国家[……]的","unit":7,"lesson":2,"seq":24,"isStar":false,"memo":"对照 他对个人财产(estate)的归属作了简单陈述(state)。","example":"Your physical state and build can also affect which jobs you can do. 你的身体状况和体格也会影响你能做什么工作。","derivative":"statement /'stetmənt/ n.声明;观点"},{"id":1985,"word":"statement","pronunciation":"/ˈsteɪtmənt/","meaning":"n.声明;观点","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1986,"word":"memory","pronunciation":"/ˈmeməri/","meaning":"n.回忆,记忆;记忆力;存储器","unit":7,"lesson":2,"seq":25,"isStar":false,"example":"He has a poor memory. 他记忆力不好。"},{"id":1987,"word":"memorise/-ize","pronunciation":"/ˈmeməraɪz/","meaning":"v.记住,熟记","unit":7,"lesson":2,"seq":26,"isStar":false},{"id":1988,"word":"memo","pronunciation":"/ˈmeməʊ/","meaning":"n.备忘录","unit":7,"lesson":2,"seq":27,"isStar":false},{"id":1989,"word":"commemorate","pronunciation":"/kəˈmeməreɪt/","meaning":"v.纪念;庆祝,为……举行纪念活动","unit":7,"lesson":2,"seq":28,"isStar":false,"memo":"构词 com-(共同)+memor(=memory)+-ate(动词后缀)→共同记忆→纪念","example":"To commemorate important dates in history, countries create special holidays. 为纪念历史上重要的日子,各国设立了特别的节假日。","derivative":"commemoration /kəmemə'reɪʃn/ n.纪念;纪念仪式"},{"id":1990,"word":"commemoration","pronunciation":"/kəˌmeməˈreʃn/","meaning":"n.纪念;纪念仪式","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1991,"word":"memorial","pronunciation":"/məˈmɔːriəl/","meaning":"n.纪念碑;纪念物;纪念品 adj.纪念的;悼念的","unit":7,"lesson":2,"seq":29,"isStar":false,"memo":"构词 memor(y)(记忆)+-ial(后缀)→纪念碑;纪念的","example":"The town raised a memorial to them. 这座小镇为他们建立了一座纪念碑。"},{"id":1992,"word":"monument","pronunciation":"/ˈmɒnjumənt/","meaning":"n.纪念碑;遗址,遗迹;名胜古迹","unit":7,"lesson":2,"seq":30,"isStar":false,"memo":"联想 monu(音似“牦牛”)+-ment(名词后缀)→人们修建了一座牦牛的“纪念碑”来纪念他。","example":"It is a historical monument. 它是一座历史纪念碑。","derivative":"monumental /ˌmnju'mentl/ adj.重要的;意义深远的;不朽的"},{"id":1993,"word":"monumental","pronunciation":"/ˌmɒnjuˈmentl/","meaning":"adj.重要的;意义深远的;不朽的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":1994,"word":"recall","pronunciation":"/rɪˈkɔːl/","meaning":"n.记忆力;召回 v.回忆起,回想起;召回","unit":7,"lesson":2,"seq":31,"isStar":false,"memo":"联想 re-(再) + call(打电话)→再次打电话，把他叫回来→召回","example":"A few people with remarkable memories are said to have “total recall”. 据说，少数记性极好的人具有“完全记忆”的能力。"},{"id":1995,"word":"remind","pronunciation":"/rɪˈmaɪnd/","meaning":"v.提醒;使想起","unit":7,"lesson":2,"seq":32,"isStar":false,"memo":"构词 re-(再) + mind(头脑)→使再回到头脑中→提醒；使想起","example":"We would do well to remind ourselves that technology is a human creation. 我们最好提醒自己，技术是人类的创造。"},{"id":1996,"word":"reminder","pronunciation":"/rɪmaɪndə(r)/","meaning":"n.勾起回忆的事物,起提醒作用的事物;提示单,通知单","unit":7,"lesson":2,"seq":33,"isStar":false},{"id":1997,"word":"mindset","pronunciation":"/ˈmaɪndset/","meaning":"n.观念模式;思维倾向","unit":7,"lesson":2,"seq":34,"isStar":false},{"id":1998,"word":"represent","pronunciation":"/ˌreprˈzent/","meaning":"v.代表;相当于;描述","unit":7,"lesson":2,"seq":35,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + present(出席)→阿姨“代表”妈妈出席我的家长会。","example":"It represented our team. 这代表了我们团队。","derivative":"representation /ˌreprzenˈteɪʃn/ n.代理,代表;描绘,表现 representative /ˌreprɪˈzentətɪv/ n.代表,代理人 adj.典型的,有代表性的"},{"id":1999,"word":"representation","pronunciation":"/ˌreprɪzenteɪʃn/","meaning":"n.代理,代表;描绘,表现","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2000,"word":"representative","pronunciation":"/ˌreprɪˈzentətɪv/","meaning":"n.代表,代理人 adj.典型的,有代表性的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2001,"word":"replace","pronunciation":"/rɪpleɪs/","meaning":"v.代替,取代;以……替换,更换","unit":7,"lesson":2,"seq":36,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + place(位置)→阿姨在他的位置上，因为阿姨“取代”了他。","example":"It is hard for robots to replace humans in highly professional work. 在高度专业化的工作中，机器人很难取代人类。","derivative":"replacement /rɪˈpleɪsmənt/ n.更换,替换;替代的人或物 irreplaceable /ˌɪrˈpleɪsəbl/ adj.不可替代的,独一无二的"},{"id":2002,"word":"replacement","pronunciation":"/rˈpleɪsmənt/","meaning":"n.更换,替换;替代的人或物","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2003,"word":"irreplaceable","pronunciation":"/ˌɪrˈpleɪsəbl/","meaning":"adj.不可替代的,独一无二的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2004,"word":"displace","pronunciation":"/dɪsˈpleɪs/","meaning":"v.取代,替代;移动,挪开;撤职,免职","unit":7,"lesson":2,"seq":37,"isStar":false,"memo":"构词 dis-(离开) + place(位置)→离开原来的位置→取代","example":"Several chemicals have displaced the oxygen. 有几种化学物质取代了氧气。","derivative":"displacement /dɪsˈpleɪsmənt/ n.取代;替代;移位;免职"},{"id":2005,"word":"displacement","pronunciation":"/dɪsˈpleɪsmənt/","meaning":"n.取代,替代;移位;免职","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2006,"word":"servant","pronunciation":"/'sɜːvənt/","meaning":"n.仆人;(公司或机构的)雇员,职员","unit":7,"lesson":2,"seq":38,"isStar":false,"memo":"构词 serv(e)(服务)+-ant(表示人的后缀)→服务的人→仆人;雇员","example":"A king's servant might not be the best one to write a biography of that king. 国王的仆人可能不是为国王写传记的最佳人选。"},{"id":2007,"word":"observe","pronunciation":"/əb'zɜːv/","meaning":"v.注意到;观察;遵守","unit":7,"lesson":2,"seq":39,"isStar":false,"memo":"联想 ob-(表方向)+serve(服务)→为我服务,要朝着我的方向,“观察”我的需求,“遵守”我的要求。","example":"Some change has been observed in today's young people. 在当今的年轻人身上观察到了一些变化。","derivative":"observer /əb'zɜːrvə(r)/ n.观察者;目击者\nobservation /ɒbzə'veɪn/ n.观察;观测;监视;评论\nobservant /əb'zɜːrvənt/ adj.善于观察的;观察力敏锐的"},{"id":2008,"word":"observer","pronunciation":"/əb'zɜvə(r)/","meaning":"n.观察者;目击者","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2009,"word":"observation","pronunciation":"/ˌɒbzə'veʃn/","meaning":"n.观察;观测;监视;评论","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2010,"word":"observant","pronunciation":"/əb'zɜːvənt/","meaning":"adj.善于观察的;观察力敏锐的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2011,"word":"reserve","pronunciation":"/rɪ'zɜv/","meaning":"n.储备(量);(动植物)保护区 v.预订;保留","unit":7,"lesson":2,"seq":40,"isStar":false,"memo":"联想 re-(重复,再)+serve(服务)→你想重复接受服务,就需要再次“预订”服务。","example":"The law requires listed firms to reserve 40% of board seats for women. 这项法规要求,上市公司必须为女性保留40%的董事会席位。","derivative":"reserved /rɪ'zɜːrvd/ adj.内向的;持的\nreservation /ˌrezə'veɪʃn/ n.预订,预约;保留意见\nreservoir /'rezəvwɑː(r)/ n.水库,蓄水池;储备"},{"id":2012,"word":"reserved","pronunciation":"/rɪ'zɜːvd/","meaning":"adj.内向的;持的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2013,"word":"reservation","pronunciation":"/ˌrezə'veɪn/","meaning":"n.预订,预约;保留意见","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2014,"word":"reservoir","pronunciation":"/'rezəvwɑː(r)/","meaning":"n.水库,蓄水池;储备","unit":7,"lesson":2,"seq":0,"isStar":true,"memo":"谐音+联想：‘瑞瑟瓦’→水库像‘瑞气储蓄罐’，存住雨水，关键时刻‘哗’地释放好运（和水）！","example":"Drought has lowered water levels in the main reservoir supplying the metropolitan area. 干旱已导致供应大都市区的主要蓄水池水位下降。"},{"id":2015,"word":"conserve","pronunciation":"/kən'sɜːv/","meaning":"v.节约;保护;保存,保留 /'kɒnsɜːv/ n.果酱;蜜饯","unit":7,"lesson":2,"seq":41,"isStar":false,"memo":"联想 con-(一起)+serve(服务)→我邀请朋友一起来家里做客,我会为大家服务,并提前“保存”一些食物。","example":"What is said to be the best way to conserve energy nowadays? 现在节约能源最好的方法是什么?","derivative":"conservation /ˌknsə'veɪʃn/ n.保护;保存;节约"},{"id":2016,"word":"conservation","pronunciation":"/ˌkɒnsə'veɪn/","meaning":"n.保护;保存;节约","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2017,"word":"conservative","pronunciation":"/kən'sɜːvətɪv/","meaning":"n.保守党党员;保守党支持者 adj.保守的;守旧的;保守党的","unit":7,"lesson":2,"seq":42,"isStar":false,"memo":"构词 conserv(e)(保存)+-ative(后缀)→保存原样的→保守的","example":"The campaign struck terror into many local conservative parties. 这场运动让许多地方的保守党感到害怕。"},{"id":2018,"word":"deserve","pronunciation":"/dɪ'zɜv/","meaning":"v.值得;应得,应受","unit":7,"lesson":2,"seq":43,"isStar":false,"memo":"联想 de(音似“弟”)+serve(服务)→弟弟觉得为家人服务是应该的→值得;应得","example":"He usually doesn't get the reward he deserves. 他通常得不到应有的奖励。"},{"id":2019,"word":"preserve","pronunciation":"/prɪ'zɜːv/","meaning":"v.保护,保存 n.专门领域;果酱;腌菜","unit":7,"lesson":2,"seq":44,"isStar":false,"memo":"联想 pre-(提前)+serve(服务)→为了服务好所有人,我要提前“保存”一些食物。","example":"The ham is covered in salt to dry and preserve it. 火腿上覆盖一层盐,晾干保存。","derivative":"preservation /ˌprezə'veɪʃn/ n.保护;保存;保留;保持\npreservative /prɪ'zɜːrvətɪv/ adj.保护的,保存的\nn.防腐剂;保护剂"},{"id":2020,"word":"preservation","pronunciation":"/ˌprezə'veɪʃn/","meaning":"n.保护;保存;保留;保持","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2021,"word":"preservative","pronunciation":"/prɪ'zɜːvətv/","meaning":"adj.保护的;保存的 n.防腐剂;保护剂","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2022,"word":"partner","pronunciation":"/'pɑːtnə(r)/","meaning":"n.配偶;搭档;合伙人;同伴 v.(在 跳舞、游戏等中)结成伙伴,做搭档","unit":7,"lesson":2,"seq":45,"isStar":false},{"id":2023,"word":"partnership","pronunciation":"/'pɑtnəʃɪp/","meaning":"n.伙伴关系","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2024,"word":"mate","pronunciation":"/meɪt/","meaning":"n.朋友,伙伴;伴侣","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2025,"word":"estimate","pronunciation":"/'estmeɪt/","meaning":"n.估计,估算;估价 /'estɪmeɪt/ v.估算,估计","unit":7,"lesson":2,"seq":46,"isStar":false,"memo":"联想 est(联想 best)+i(我)+mate(伙伴)→我“估算”一下最好的伙伴有多少。","example":"Give an estimate of how long it will stay in space. 估计一下它将在太空中停留多久。","derivative":"estimation /ˌest'meɪʃn/ n.估计;判断;评价"},{"id":2026,"word":"estimation","pronunciation":"/ˌest'meɪʃn/","meaning":"n.估计;判断;评价","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2027,"word":"reckon","pronunciation":"/'rekən/","meaning":"v.估算,计算;想,认为","unit":7,"lesson":2,"seq":48,"isStar":false,"memo":"联想 re(字母音似“阿姨”)+ck(联想“CK品牌”)+on→阿姨在“估算”CK的这件衣服值多少钱。","example":"They reckon that their profits are down by at least 20%. 他们估算利润至少下降了20%。"},{"id":2028,"word":"reckless","pronunciation":"/'rekləs/","meaning":"adj.鲁莽的,不顾后果的,轻率的","unit":7,"lesson":2,"seq":49,"isStar":false,"memo":"对照 没有(less表否定)估算(reckon)的行动通常是鲁莽的(reckless)。","example":"Reckless development are plotting against the rainforest. 不顾后果的开发正在图谋破坏雨林。"},{"id":2029,"word":"intimacy","pronunciation":"/'ɪntməsi/","meaning":"n.亲密;密切","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2030,"word":"inmate","pronunciation":"/'ɪnmeɪt/","meaning":"n.(监狱或精神病院等的)同住者;同狱犯人","unit":7,"lesson":2,"seq":51,"isStar":false},{"id":2031,"word":"approximately","pronunciation":"/ə'prɒksɪmətli/","meaning":"adv.大概,大约","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2032,"word":"approximation","pronunciation":"/əˌprɒksɪ'meɪʃn/","meaning":"n.近似值;粗略估算;类似事物","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2033,"word":"proximity","pronunciation":"/prɒk'sɪməti/","meaning":"n.(时间或空间)接近,邻近,靠近","unit":7,"lesson":2,"seq":53,"isStar":false,"memo":"[联想] pro-(往前)+xi(联想“西”)+mi(联想“米”)+-ty(名词后缀)→他往西前行数百米就能“接近”目的地。","example":"The area has many schools in close proximity to each other. 这个地区有许多学校比邻而立。","derivative":"proximate /'prɒksɪmət/ adj.(时间、顺序等)最接近的,最邻近的"},{"id":2034,"word":"proximate","pronunciation":"/'prɒksɪmət/","meaning":"adj.(时间、顺序等)最接近的,最邻近的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2035,"word":"ultimate","pronunciation":"/'ʌltɪmət/","meaning":"n.最好的事物,极品,精华 adj.最后的,最终的;根本的","unit":7,"lesson":2,"seq":54,"isStar":false,"memo":"[联想] ulti-(最后)+mate(伙伴)→留到“最后的”伙伴,一定是最好的。","example":"We will accept ultimate responsibility for whatever happens. 无论发生什么,我们都会承担最终的责任。","derivative":"ultimately /'ltɪmətli/ adv.最终;最后;根本上"},{"id":2036,"word":"ultimately","pronunciation":"/'ʌltmətli/","meaning":"adv.最终;最后;根本上","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2037,"word":"imitate","pronunciation":"/'ɪmɪteɪt/","meaning":"v.模仿,仿效","unit":7,"lesson":2,"seq":55,"isStar":false,"memo":"[联想] i(我)+m(联想“门”)+it(它)+ate(eat 的过去式)→我在门口“模仿”它(小狗)吃东西。","example":"Computers can imitate life. 计算机可以模拟生活。","derivative":"imitation /ˌɪmɪ'teɪʃn/ n.模仿;仿制品 imitative /'ɪmtətɪv/ adj.模仿的;仿制的"},{"id":2038,"word":"imitation","pronunciation":"/ˌɪmɪ'teɪʃn/","meaning":"n.模仿;仿制品","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2039,"word":"imitative","pronunciation":"/'ɪmɪtətv/","meaning":"adj.模仿的;仿制的","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2040,"word":"simulate","pronunciation":"/'smjuleɪt/","meaning":"v.假装,装作;模仿;模拟","unit":7,"lesson":2,"seq":56,"isStar":false,"memo":"[联想] simu(联想“四目”)+late(迟到)→他“假装”有四只眼睛,能抓住从各个方向跑来的迟到者。","example":"I tried to simulate surprise at the news. 听到这个消息后,我竭力装出一副吃惊的样子。","derivative":"simulation /ˌsɪmju'leɪʃn/ n.模拟;假装;冒充"},{"id":2041,"word":"simulation","pronunciation":"/ˌsɪmju'leɪʃn/","meaning":"n.模拟;假装;冒充","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2042,"word":"stimulate","pronunciation":"/'stɪmjuleɪt/","meaning":"v.促进;激发,激励;刺激","unit":7,"lesson":2,"seq":57,"isStar":false,"memo":"[对照] 同桌一个劲地模仿(simulate)他,他就受刺激(stimulate)了。","example":"A person who is unable to stimulate his curiosity may appear somewhat boring. 一个人如果不能激发自己的好奇心,那么他可能就会显得有些无聊。"},{"id":2043,"word":"simultaneous","pronunciation":"/ˌsɪml'teɪniəs/","meaning":"adj.同时发生(或进行)的,同步的","unit":7,"lesson":2,"seq":58,"isStar":false,"memo":"[联想] simul(音似“四目”)+ta(联想“他”)+ne(音似“你”)+-ous(形容词后缀)→他和你四目相对,同时行动→同时发生的","example":"With simultaneous interpreting, you start translating almost as soon as the other person starts speaking. 对于同声传译来说,你几乎需要在另一个人开始讲话时就开始翻译。","derivative":"simultaneously /ˌsɪml'teɪniəsli/ adv.同时发生(或进行)地;同步地"},{"id":2044,"word":"simultaneously","pronunciation":"/sɪml'teɪniəsli/","meaning":"adv.同时发生(或进行)地;同步地","unit":7,"lesson":2,"seq":0,"isStar":true},{"id":2045,"word":"flap","pronunciation":"/flæp/","meaning":"n.拍打,振(翅) v.拍击,摆动;振(翅)","unit":7,"lesson":3,"seq":1,"isStar":false,"memo":"联想 f(联想“飞”) + la(音似“来”) + p(联想“拍”)→蝴蝶“拍打”着翅膀飞来了。","example":"With a flap of its wings, the bird was gone. 鸟振翅飞走了。"},{"id":2046,"word":"flip","pronunciation":"/flɪp/","meaning":"v.使快速翻转;抛掷;浏览 n.轻抛;筋斗,空翻;浏览 adj.轻率的;轻浮的","unit":7,"lesson":3,"seq":2,"isStar":false},{"id":2047,"word":"grip","pronunciation":"/ɡrɪp/","meaning":"n.紧握;影响力;理解 v.紧握;使感兴趣;对……有强烈影响","unit":7,"lesson":3,"seq":3,"isStar":false,"memo":"联想 g(联想“哥”) + rip(撕)→哥哥要撕扯包装袋,首先得“紧握”包装袋。","example":"Bruce gripped the steering wheel hard. 布鲁斯紧紧地抓住方向盘。"},{"id":2048,"word":"grope","pronunciation":"/ɡrəʊp/","meaning":"v.摸索;搜索 n.摸","unit":7,"lesson":3,"seq":4,"isStar":false,"memo":"联想 g(联想“哥”) + rope(绳子)→哥哥晚上伸手够绳子,需要“摸索”一番。","example":"He groped around in the dark for his other sock. 他在黑暗中到处摸索着寻找另一只袜子。"},{"id":2049,"word":"rope","pronunciation":"/rəʊp/","meaning":"n.粗绳,绳索 v.用绳子捆","unit":7,"lesson":3,"seq":5,"isStar":false,"memo":"谐音 单词发音类似“肉铺”→肉铺会把肉一片片地用“绳索”穿起来挂着。","example":"His hands were tied together with rope. 他的手被绳子绑在一起。"},{"id":2050,"word":"groan","pronunciation":"/ɡrəʊn/","meaning":"n.呻吟声;哼哼声 v.呻吟;抱怨,发牢骚","unit":7,"lesson":3,"seq":6,"isStar":false,"memo":"谐音 单词发音类似“割肉嗯”→被割肉时会发出“嗯嗯”的“呻吟声”。","example":"Casey let out a groan of protest. 凯西哼了一声表示抗议。"},{"id":2051,"word":"moan","pronunciation":"/mən/","meaning":"n.呻吟声;抱怨 v.呻吟;抱怨","unit":7,"lesson":3,"seq":7,"isStar":false,"memo":"谐音 单词发音类似“哞(牛的叫声)”→呻吟声","example":"The money seemed to do little more than buy relief from the moans of their children. 金钱似乎只是缓解了他们的孩子们的抱怨。"},{"id":2052,"word":"complain","pronunciation":"/kəmpleɪn/","meaning":"v.抱怨,埋怨;投诉","unit":7,"lesson":3,"seq":8,"isStar":false,"memo":"联想 com-(所有) + plain(音似“扑累”)→所有人都扑过来,不停地“抱怨”累。","example":"They have been complaining of labor shortages for several years. 他们这些年一直在抱怨劳动力不足。","derivative":"complaint /kəmˈplent/ n.抱怨;投诉"},{"id":2053,"word":"complaint","pronunciation":"/kəmˈplent/","meaning":"n.抱怨;投诉","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2054,"word":"glance","pronunciation":"/ɡlɑːns/","meaning":"n.一瞥;扫视 v.瞥一眼;扫视;浏览","unit":7,"lesson":3,"seq":9,"isStar":false,"memo":"单词发音类似“哥懒死”→哥哥很懒，无论让他看什么，他都是“一瞥”了事。","example":"She glanced at her watch. 她瞥了一眼表。"},{"id":2055,"word":"peep","pronunciation":"/pip/","meaning":"n.偷偷一瞥 v.窥视,偷看","unit":7,"lesson":3,"seq":10,"isStar":false},{"id":2056,"word":"glitter","pronunciation":"/ˈɡlɪtə(r)/","meaning":"v.闪烁,闪光 n.闪烁,闪耀","unit":7,"lesson":3,"seq":11,"isStar":false,"memo":"g(联想“哥”) + litter(垃圾)→哥哥看见垃圾就想进行分类,两眼“闪光”。","example":"There was a triumphant glitter in his eyes. 他的眼睛里闪烁着胜利的光芒。","derivative":"glittering /ˈɡlɪtərɪŋ/ adj.辉煌的;闪闪发光的"},{"id":2057,"word":"glittering","pronunciation":"/ˈɡlɪtərŋ/","meaning":"adj.辉煌的;闪闪发光的","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2058,"word":"litter","pronunciation":"/ˈlɪtə(r)/","meaning":"v.使凌乱;乱扔 n.垃圾;废弃物;杂物","unit":7,"lesson":3,"seq":12,"isStar":false,"memo":"小的(little)垃圾(litter)也要分类。","example":"There will be fines for people who drop litter. 乱扔垃圾的人将被罚款。"},{"id":2059,"word":"gaze","pronunciation":"/ɡeɪz/","meaning":"n.凝视,注视 v.盯着看,凝视","unit":7,"lesson":3,"seq":13,"isStar":false,"example":"She felt increasingly uncomfortable under the woman's gaze. 在那位女士的注视下,她觉得愈发不自在了。"},{"id":2060,"word":"blush","pronunciation":"/blʌʃ/","meaning":"n.脸红 v.(因难为情而)脸红;感到羞愧","unit":7,"lesson":3,"seq":14,"isStar":false,"memo":"他因为错拿了别人的刷子(brush)而脸红(blush)了。","example":"Poor Anne could only blush horribly. 可怜的安妮只能羞怯得满脸通红。"},{"id":2061,"word":"flush","pronunciation":"/flʌ/","meaning":"n.脸红;潮红;冲(抽水马桶) v.发红;脸红;冲洗","unit":7,"lesson":3,"seq":15,"isStar":false,"memo":"单词发音类似“服了师”→他上课乱说话,被老师批评了一顿,服了老师,并且羞愧得“脸红”了。","example":"His face flushed as he came in after running all the way from school. 他从学校一路跑回来,脸都红了。"},{"id":2062,"word":"splash","pronunciation":"/splæ/","meaning":"n.落水声;溅洒后留下的污渍 v.把(水、泥等)泼在……上,溅在……上","unit":7,"lesson":3,"seq":16,"isStar":false,"memo":"电影 Splash 中美人鱼扑通一声跳进海里,海水飞溅→落水声;溅在……上","example":"We heard the splash when she fell into the pool. 当她掉入泳池时,我们听到了落水声。"},{"id":2063,"word":"glare","pronunciation":"/ɡleə(r)/","meaning":"n.刺眼的强光;怒视 v.怒目而视;发出刺眼的强光","unit":7,"lesson":3,"seq":17,"isStar":false,"memo":"[联想] g(联想“哥”) + la(联想“拉”) + re(字母音似“阿姨”) → 哥哥在街上拉住一个阿姨,阿姨“怒视”了他一下。","example":"He didn't shout: he just glared at me silently. 他没有喊叫,他只是默默地怒视着我。"},{"id":2064,"word":"glimpse","pronunciation":"/ɡlɪmps/","meaning":"n.一瞥,飞快的一看;短暂的感受(或体验、体会) v.瞥见,看一眼;开始理解","unit":7,"lesson":3,"seq":18,"isStar":false,"memo":"[联想] gli(联想“哥立”) + m(联想“美”) + p(联想“瞥”) + se(联想“涩”) → 哥哥站立在美女旁边,羞涩地“一瞥”。","example":"She glimpsed a group of people standing on the bank of a river. 她瞥见一群人站在河岸上。"},{"id":2065,"word":"stare","pronunciation":"/steə(r)/","meaning":"n. & v.盯着看;凝视;注视","unit":7,"lesson":3,"seq":19,"isStar":false,"memo":"[联想] st(联想 street) + a(一) + re(字母音似“阿姨”) → 她在街上盯着一个阿姨看 → 盯着看","example":"She gave him a long, cold stare. 她冷冷地盯着他看了很久。"},{"id":2066,"word":"scan","pronunciation":"/skæn/","meaning":"n.扫描检查;浏览 v.细看,审视;浏览;扫描","unit":7,"lesson":3,"seq":20,"isStar":false,"memo":"[谐音] 单词发音类似“死看” → 当你死死盯着一个人看的时候,你就是在“细看”。","example":"We quickly scanned the menu. 我们快速浏览了一下菜单。","derivative":"scanner /'skænə(r)/ n.扫描仪"},{"id":2067,"word":"scanner","pronunciation":"/'skænə(r)/","meaning":"n.扫描仪","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2068,"word":"scandal","pronunciation":"/'skændl/","meaning":"n.丑行,丑闻,可耻的行为","unit":7,"lesson":3,"seq":21,"isStar":false,"memo":"[谐音] 单词发音类似“死看都” → 所有人都死死地盯着他看,因为他有一桩“丑闻”。","example":"The scandal will soon blow over. 丑闻很快就会烟消云散的。","derivative":"scandalous /'skændələs/ adj.可耻的;不可原谅的"},{"id":2069,"word":"scandalous","pronunciation":"/'skændələs/","meaning":"adj.可耻的;不可原谅的","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2070,"word":"dazzle","pronunciation":"/'dæzl/","meaning":"n.耀眼眩目 v.使目眩,使眼花;(美貌、技能等)使倾倒","unit":7,"lesson":3,"seq":22,"isStar":false,"memo":"[谐音] 单词发音类似“带走” → 这颗钻石“耀眼眩目”,大家都想带走它。","example":"I was dazzled by the car's headlights. 我被汽车前灯照得眼花。","derivative":"dazzling /'dæzlɪŋ/ adj.炫目的;令人眼花缭乱的"},{"id":2071,"word":"dazzling","pronunciation":"/'dæzlɪ/","meaning":"adj.炫目的;令人眼花缭乱的","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2072,"word":"scratch","pronunciation":"/skrætʃ/","meaning":"n.划痕;刮(或擦、抓)的刺耳声;挠痒 v.挠,搔;抓破,抓伤(皮肤)","unit":7,"lesson":3,"seq":23,"isStar":false,"memo":"联想 sc(音似“四个”)+rat(老鼠)+ch(音似“吃”)→四个(只)老鼠吃东西时边“挠”边吃。","example":"He scratched his head. 他时不时地挠挠头。"},{"id":2073,"word":"scrape","pronunciation":"/skreɪp/","meaning":"n.刮,铲;刮擦声;擦伤,擦痕 v.刮掉,削去;擦伤,蹭破","unit":7,"lesson":3,"seq":24,"isStar":false,"memo":"联想 sc(音似“四个”)+rape(联想reap“收割”)→这四个人用镰刀收割庄稼,很容易“擦伤”。","example":"We tried to scrape the paper off all four walls. 我们试图把纸从四面墙上刮下来了。"},{"id":2074,"word":"scrap","pronunciation":"/skræp/","meaning":"n.碎片;一点点;废品,废弃材料;争吵 v.放弃;抛弃;报废;打架","unit":7,"lesson":3,"seq":25,"isStar":false,"example":"Waterbirds can get cut by scrap metal. 水鸟可能会被废金属割伤。"},{"id":2075,"word":"scrub","pronunciation":"/skrʌb/","meaning":"v.擦洗;刷洗 n.擦洗,刷洗;木丛;矮树丛","unit":7,"lesson":3,"seq":26,"isStar":false},{"id":2076,"word":"democratic","pronunciation":"/ˌdemə'krætɪk/","meaning":"adj.民主的,民主政体的;民主制的; 平等的","unit":7,"lesson":3,"seq":27,"isStar":false,"memo":"联想 democ(音似“戴帽可”)+rat(老鼠)+ic(联想“IC卡”)→戴帽子的老鼠可以坐公交车并刷IC卡,这真是个“民主的”社会。","example":"Education is the basis of a democratic society. 教育是民主社会的基础。"},{"id":2077,"word":"democrat","pronunciation":"/'deməkræt/","meaning":"n.(美国)民主党党员,民主党人,民主党支持者","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2078,"word":"democracy","pronunciation":"/dɪ'mɒkrəsi/","meaning":"n.民主;民主政体;民主制度","unit":7,"lesson":3,"seq":28,"isStar":false,"example":"The government will uphold the principles of democracy. 政府将坚持民主的原则。"},{"id":2079,"word":"category","pronunciation":"/'kætəgəri/","meaning":"n.种类,范畴","unit":7,"lesson":3,"seq":29,"isStar":false,"memo":"联想 cat(猫)+e(联想“鹅”)+g(联想“鸽”)+ory(名词后缀)→猫、鹅、鸽子属于不同的动物“种类”。","example":"He competed in the youngest age category. 他参加了最小年龄组的比赛。"},{"id":2080,"word":"cater","pronunciation":"/'keɪtə(r)/","meaning":"v.提供饮食;满足,迎合","unit":7,"lesson":3,"seq":30,"isStar":false,"memo":"联想 cat(猫)+er(表示人的后缀)→有些人像猫一样喜欢“迎合”别人。","example":"They only publish novels which cater to the mass market. 他们只出版迎合大众市场的小说。"},{"id":2081,"word":"delicate","pronunciation":"/'delɪkət/","meaning":"adj.易碎的,脆弱的;精巧的,精致的","unit":7,"lesson":3,"seq":31,"isStar":false,"memo":"联想 deli(联想“得力”,文具品牌)+cat(e)(猫)→得力文具上刻有一只“精致的”猫。","example":"Most of them are extremely delicate. 它们大多数都特别脆弱。"},{"id":2082,"word":"dedicate","pronunciation":"/'dedɪkeɪt/","meaning":"v.致力于,献身于;献给","unit":7,"lesson":3,"seq":32,"isStar":false,"memo":"联想 dedi(音似 daddy)+cate(音似“剋他”)→坏人欺负他了,爸爸就去剋(打)坏人,爸爸总是“致力于”保护他。","example":"They have dedicated their lives to protecting the environment. 他们为保护环境而奉献自己的一生。","derivative":"dedication /ˌdedɪˈkeɪʃn/ n.热忧,奉献"},{"id":2083,"word":"dedication","pronunciation":"/ˌdedɪ'keɪʃn/","meaning":"n.热忱,奉献","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2084,"word":"catalog(ue)","pronunciation":"/'kætəlɒg/","meaning":"n.目录 v.列入目录,编目录","unit":7,"lesson":3,"seq":33,"isStar":false},{"id":2085,"word":"index","pronunciation":"/'ɪndeks/","meaning":"n.索引;卡片目录;指数;标志;指标 v.为……编索引","unit":7,"lesson":3,"seq":34,"isStar":false,"memo":"联想 in(在……里面)+dex(音似“德克士”)→他在德克士里看到菜单上有“索引”和卡路里“指标”。","example":"Body mass index may be related to wages and income. 体重指数可能与工资和收入有关。"},{"id":2086,"word":"appetite","pronunciation":"/'æpɪtaɪt/","meaning":"n.胃口;爱好","unit":7,"lesson":3,"seq":35,"isStar":false,"memo":"联想 ap-(一再地)+pet(宠物)+-ite(后缀)→他一再地提到家里的宠物,说明很喜爱它→爱好","example":"Our short-term memory may play a role in appetite. 我们的短期记忆可能会影响胃口。"},{"id":2087,"word":"petition","pronunciation":"/pə'tɪʃn/","meaning":"n.请愿(书);正式请求,祈求 v.祈求,请求;请愿","unit":7,"lesson":3,"seq":36,"isStar":false,"memo":"联想 pet(宠物)+it(它)+-ion(后缀)→宠物通常会“祈求”人们喜爱它。","example":"I signed a petition against experiments on animals. 我在一份反对用动物做实验的请愿书上签了名。","derivative":"petitioner /pə'tɪʃənə(r)/ n.请愿者;请求者"},{"id":2088,"word":"petitioner","pronunciation":"/pəˈtɪʃənə(r)/","meaning":"n.请愿者;请求者","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2089,"word":"frustrate","pronunciation":"/frʌstreɪt/","meaning":"v.使懊恼;使沮丧;使挫败;阻止","unit":7,"lesson":3,"seq":37,"isStar":false,"memo":"联想 fru(联想“妇孺”)+st(联想 street)+rat(e)(老鼠)→一群妇孺在街上追老鼠,追不上时感觉很沮丧→使沮丧","example":"The rescue attempt was frustrated by bad weather. 营救行动因天气恶劣受阻。","derivative":"frustrating /frʌ'streɪtɪŋ/ adj.令人懊恼的;令人沮丧的\nfrustration /frʌ'streɪʃn/ n.懊恼;沮丧;挫败"},{"id":2090,"word":"frustrating","pronunciation":"/frʌˈstreɪtɪŋ/","meaning":"adj.令人懊恼的;令人沮丧的","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2091,"word":"frustration","pronunciation":"/frʌˈstreɪʃn/","meaning":"n.懊恼;沮丧;挫败","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2092,"word":"accomplish","pronunciation":"/əˈkʌmplʃ/","meaning":"v.完成;实现(尤指通过努力)","unit":7,"lesson":3,"seq":38,"isStar":false,"memo":"联想 ac-(表强调)+complish(音似“看破历史”)→一再地看破历史的时候,人生就算圆满了→完成;实现","example":"Curiosity is one of the tools humans have found to accomplish that gigantic task. 好奇心是人类发现的完成那一庞大工作的工具之一。","derivative":"accomplishment /ə'kʌmplʃmənt/ n.成就,成绩"},{"id":2093,"word":"accomplishment","pronunciation":"/əˈkʌmplɪʃmənt/","meaning":"n.成就,成绩","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2094,"word":"achieve","pronunciation":"/ətʃiːv/","meaning":"v.(凭长期努力)达到(某目标、地位、标准);成功;完成","unit":7,"lesson":3,"seq":39,"isStar":false,"memo":"a-(到) + chieve(= chief 首领,头)→到头的位置→达到;成功","example":"Technologies like this have helped achieve a 31% drop in vehicle-related crime. 此类技术已经帮助将与车辆相关的犯罪率下降了31%。","derivative":"achievement /ə'tʃi:vmənt/ n.成就;完成"},{"id":2095,"word":"achievement","pronunciation":"/əˈtʃiːvmənt/","meaning":"n.成就;完成","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2096,"word":"fulfil(l)","pronunciation":"/fʊlˈfɪl/","meaning":"v.实现;履行,执行","unit":7,"lesson":3,"seq":40,"isStar":false},{"id":2097,"word":"fulfil(l)ment","pronunciation":"/fʊlfɪlmənt/","meaning":"n.满足感;实现","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2098,"word":"victory","pronunciation":"/ˈvɪktəri/","meaning":"n.胜利,成功","unit":7,"lesson":3,"seq":41,"isStar":false,"memo":"vict(征服) + -ory(名词后缀)→胜利,成功","example":"The ruling is a victory for big chains with a presence in many states. 那项裁决对于在许多州都有实体店的大型连锁店来说是一次胜利。","derivative":"victorious /vɪktɔːriəs/ adj.胜利的;获胜的"},{"id":2099,"word":"victorious","pronunciation":"/vɪkˈtɔːriəs/","meaning":"adj.胜利的;获胜的","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2100,"word":"triumph","pronunciation":"/ˈtraɪmf/","meaning":"n.胜利;喜悦 v.打败,战胜,成功","unit":7,"lesson":3,"seq":42,"isStar":false,"memo":"单词发音类似“川姆屠”→他用实力“战胜”川姆,川姆输得心服口服。","example":"As is usual in this kind of movie, good triumphs over evil in the end. 像这类电影的一贯结局一样,善良最终战胜了邪恶。","derivative":"triumphant /traɪˈʌmfənt/ adj.欢欣鼓舞的;耀武扬威的;大获全胜的"},{"id":2101,"word":"triumphant","pronunciation":"/traɪˈʌmfənt/","meaning":"adj.欢欣鼓舞的;耀武扬威的;大获全胜的","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2102,"word":"tournament","pronunciation":"/tʊənəmənt/","meaning":"n.锦标赛;联赛","unit":7,"lesson":3,"seq":43,"isStar":false},{"id":2103,"word":"champion","pronunciation":"/ˈtʃæmpiən/","meaning":"n.冠军;第一名;优胜者","unit":7,"lesson":3,"seq":44,"isStar":false,"example":"She is a former Olympic skating champion. 她是前奥运会滑冰冠军。","derivative":"championship /ˈtʃæmpiənʃɪp/ n.锦标赛;冠军地位"},{"id":2104,"word":"championship","pronunciation":"/ˈtʃæmpiənʃɪp/","meaning":"n.锦标赛;冠军地位","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2105,"word":"feat","pronunciation":"/fit/","meaning":"n.业绩,功绩;壮举","unit":7,"lesson":3,"seq":45,"isStar":false},{"id":2106,"word":"defeat","pronunciation":"/dɪˈfiːt/","meaning":"n.失败;战胜,击败 v.打败,战胜","unit":7,"lesson":3,"seq":46,"isStar":false,"memo":"de(音似“弟”) + feat(功绩)→弟弟的功绩是“打败”了他。","example":"The use of the Internet isn’t the only way to defeat poverty. 使用互联网并不是战胜贫困的唯一方法。"},{"id":2107,"word":"punch","pronunciation":"/pʌntʃ/","meaning":"n.重拳击打;打孔机 v.用拳猛击;(用打孔器等)打孔;按(键),压(按钮)","unit":7,"lesson":3,"seq":47,"isStar":false,"memo":"单词发音类似“重拳击打”在很软的东西上发出的声音“乓”。","example":"She landed a punch on his chin. 她一拳打在了他的下巴上。"},{"id":2108,"word":"technique","pronunciation":"/tekˈniːk/","meaning":"n.技术;技巧;技艺;工艺","unit":7,"lesson":3,"seq":48,"isStar":false,"memo":"单词发音类似“泰克尼克”→泰克认为泰坦尼克号出事故的原因之一可能是“技术”有问题。"},{"id":2109,"word":"technical","pronunciation":"/ˈteknɪkl/","meaning":"adj.技术的;技巧的;工艺的","unit":7,"lesson":3,"seq":49,"isStar":false,"memo":"对照 technique n.技术;技巧;工艺→ technical adj.","example":"All the technical problems can be solved. 所有的技术问题都能得到解决。","derivative":"technician /tek'nɪʃn/ n.技术员;技师"},{"id":2110,"word":"technician","pronunciation":"/tek'nɪʃn/","meaning":"n.技术员;技师","unit":7,"lesson":3,"seq":0,"isStar":true},{"id":2111,"word":"craft","pronunciation":"/krɑːft/","meaning":"n.手艺;工艺 v.精心制作","unit":7,"lesson":3,"seq":50,"isStar":false,"memo":"对照 工艺(craft)决定了航空器(aircraft)在空(air)中的飞行安全。","example":"Children often sell candy and crafts in the streets. 孩子们经常在街上卖糖果和工艺品。"},{"id":2112,"word":"handicraft","pronunciation":"/'hændikrɑːft/","meaning":"n.手工艺;手工艺品","unit":7,"lesson":3,"seq":51,"isStar":false,"memo":"对照 手工艺(handicraft)指以手(hand)工劳动进行制作的工艺(craft)。","example":"Her job involves buying handicrafts from all over the world. 她的工作包括从世界各地购买手工艺品。"},{"id":2113,"word":"artifact","pronunciation":"/'ɑːtɪfækt/","meaning":"n.人工制品,手工艺品","unit":7,"lesson":3,"seq":52,"isStar":false},{"id":2114,"word":"jet","pronunciation":"/dʒet/","meaning":"n.喷气式飞机;喷嘴","unit":7,"lesson":3,"seq":53,"isStar":false,"memo":"谐音 单词发音类似“截他”→我们开着“喷气式飞机”去拦截他。","example":"The giant jet will be forced to land. 这架巨型喷气式飞机将被迫降落。"},{"id":2115,"word":"jerk","pronunciation":"/dʒɜːk/","meaning":"v. & n.急拉;猛推;猝然一动","unit":7,"lesson":3,"seq":54,"isStar":false,"memo":"谐音 单词发音类似“杰克”→电影《泰坦尼克号》中的船进水时,男主人公杰克赶忙把露丝拉到自己身边→急拉","example":"She sat up with a jerk. 她猛地坐了起来。"},{"id":2116,"word":"aviation","pronunciation":"/ˌeɪvi'eɪʃn/","meaning":"n.航空(学);飞机制造业","unit":7,"lesson":3,"seq":55,"isStar":false,"memo":"联想 a(-)+vi(形似罗马数字6)+-ation(名词后缀)→他研究“航空学”,一天进行6次测试。","example":"It uses the latest aviation technology. 它采用最新的航空技术。"},{"id":2117,"word":"preside","pronunciation":"/prɪ'zaɪd/","meaning":"v.主持(会议、仪式等);担任(会议)主席","unit":7,"lesson":4,"seq":1,"isStar":false,"memo":"对照 president n.总统；国家主席；会长→ preside v.","example":"Although it was his first experience as chairman, he presided over the meeting with great skill. 虽然这是他第一次担任主席，但他熟练地主持了会议。","derivative":"president /'prezɪdənt/ n.总统；国家主席；会长；总裁\npresidential /ˌprez'denʃl/ adj.总统的；国家主席的\npresidency /'prezɪdənsi/ n.总统（或主席）的职位；任期"},{"id":2118,"word":"president","pronunciation":"/'prezɪdənt/","meaning":"n.总统;国家主席;会长;总裁","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2119,"word":"presidential","pronunciation":"/ˌprezɪ'denʃl/","meaning":"adj.总统的;国家主席的","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2120,"word":"presidency","pronunciation":"/'prezɪdənsi/","meaning":"n.总统(或主席)的职位;任期","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2121,"word":"reside","pronunciation":"/rɪ'zaɪd/","meaning":"v.居住,定居","unit":7,"lesson":4,"seq":2,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + side(面) → 阿姨“居住”在马路对面。","example":"I reside at the end of the street. 我住在这条街的尽头。","derivative":"resident /'rezɪdənt/ n.居民；住户 adj.居住的，居留的\nresidential /ˌrez'denʃl/ adj.住宅的"},{"id":2122,"word":"resident","pronunciation":"/'rezɪdənt/","meaning":"n.居民;住户 adj.居住的,居留的","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2123,"word":"residential","pronunciation":"/ˌrezɪ'denʃl/","meaning":"adj.住宅的","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2124,"word":"residence","pronunciation":"/'rezɪdəns/","meaning":"n.住所;居住;定居;(在他国的)居住权","unit":7,"lesson":4,"seq":3,"isStar":false,"memo":"构词 reside(居住) + -(e)nce(名词后缀) → 住所；居住","example":"Please state your occupation and place of residence. 请说明你的职业和住所。"},{"id":2125,"word":"dwell","pronunciation":"/dwel/","meaning":"v.定居;居住;(~on)老是想着(详述,唠叨)","unit":7,"lesson":4,"seq":4,"isStar":false,"memo":"联想 d(联想“定”) + well(很好地) → 很好地安定了下来 → 定居；居住","example":"He dwelt in a cottage on the hillside. 他住在山坡上的一座农舍里。","derivative":"dweller /'dwelə(r)/ n.居民，居住者\ndwelling /'dwelɪŋ/ n.住宅，住所"},{"id":2126,"word":"dweller","pronunciation":"/'dwelə(r)/","meaning":"n.居民,居住者","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2127,"word":"dwelling","pronunciation":"/'dwelɪŋ/","meaning":"n.住宅,住所","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2128,"word":"inhabit","pronunciation":"/ɪn'hæbɪt/","meaning":"v.居住在……;栖居于……","unit":7,"lesson":4,"seq":5,"isStar":false,"memo":"联想 in(在里面) + habit(习惯) → 在家里面住得习惯了 → 居住在……","example":"Many old houses are not inhabited. 许多老房子无人居住。","derivative":"inhabitant /ɪn'hæbɪtənt/ n.居民，居住者"},{"id":2129,"word":"inhabitant","pronunciation":"/ɪn'hæbɪtənt/","meaning":"n.居民,居住者","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2130,"word":"habitat","pronunciation":"/'hæbɪtæt/","meaning":"n.(动植物的)生活环境;(动物的)栖息地","unit":7,"lesson":4,"seq":6,"isStar":false,"memo":"habitat ≈ ‘哈！比它（住）’→动物喊‘哈！这地儿比它适合我住！’指生物‘户口所在地’。","example":"Deforestation threatens the natural habitat of endangered primates. 森林砍伐威胁着濒危灵长类动物的自然栖息地。"},{"id":2131,"word":"settle","pronunciation":"/'setl/","meaning":"v.安顿,定居;解决","unit":7,"lesson":4,"seq":7,"isStar":false,"memo":"联想 set(t)(放置)+le(联想“了”)→把自己放下来了,不再漂泊,就是“定居”;把问题放下来了,就是把问题给“解决”。","example":"It's time you settled your differences with your father. 现在你该解决同你父亲之间的分歧了。","derivative":"settlement /'setlmənt/ n.解决,处理;协议"},{"id":2132,"word":"settlement","pronunciation":"/'setlmənt/","meaning":"n.解决,处理;协议","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2133,"word":"address","pronunciation":"/ə'dres/","meaning":"n.住址;演讲 v.演说;解决,处理","unit":7,"lesson":4,"seq":8,"isStar":false,"memo":"联想 ad-(一再地)+dress(裙子)→她一再地在网上买裙子,需要填写邮寄“地址”。","example":"He will give an address to the nation. 他将向全国发表演讲。"},{"id":2134,"word":"tackle","pronunciation":"/'tækl/","meaning":"v.应付,解决(难题或局面);与……交涉 n.(足球等中的)抢断球","unit":7,"lesson":4,"seq":9,"isStar":false,"memo":"谐音 单词发音类似“太抠”→“应付”那个太抠门的人很难。","example":"Nobody is willing to sacrifice their own interests to tackle the problem. 没有人愿意牺牲自己的利益来解决这个问题。"},{"id":2135,"word":"cope","pronunciation":"/kəʊp/","meaning":"v.应付,处理","unit":7,"lesson":4,"seq":10,"isStar":false,"memo":"谐音 单词发音类似“抠破”→伤口被抠破了,得“处理”一下。","example":"They are able to cope with the global climate change. 他们能够应对全球气候变化。"},{"id":2136,"word":"solve","pronunciation":"/sɒlv/","meaning":"v.解决,处理","unit":7,"lesson":4,"seq":11,"isStar":false,"example":"Attempts are being made to solve the problem of waste disposal. 正在想办法解决废物处理的问题。","derivative":"solution /sə'luːʃn/ n.解决办法;处理手段;答案;溶液\nsolvent /'sɒlvənt/ n.溶剂 adj.可溶解的;有偿付能力的"},{"id":2137,"word":"solution","pronunciation":"/sə'luːʃn/","meaning":"n.解决办法;处理手段;答案;溶液","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2138,"word":"solvent","pronunciation":"/'sɒlvənt/","meaning":"n.溶剂 adj.可溶解的;有偿付能力的","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2139,"word":"resolve","pronunciation":"/rɪ'zɒlv/","meaning":"n.决心 v.解决(问题或困难);下决心,决定","unit":7,"lesson":4,"seq":12,"isStar":false,"memo":"构词 re-(表加强)+solve(解决)→必须解决→解决;下决心","example":"Different people resolve conflicts in different ways. 不同的人用不同的方式解决冲突。","derivative":"resolution /ˌrezə'luːʃn/ n.决心;解决\nresolute /'rezəluːt/ adj.坚决的;有决心的"},{"id":2140,"word":"resolution","pronunciation":"/ˌrezə'luːʃn/","meaning":"n.决心;解决","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2141,"word":"resolute","pronunciation":"/'rezəluːt/","meaning":"adj.坚决的;有决心的","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2142,"word":"dissolve","pronunciation":"/dɪ'zɒlv/","meaning":"v.(使)溶解,解除;(使)消失","unit":7,"lesson":4,"seq":13,"isStar":false,"memo":"构词 dis-(=away)+solve(解决)→解决掉→(使)溶解;解除","example":"Sugar dissolves in water. 糖溶解于水。"},{"id":2143,"word":"soluble","pronunciation":"/'sɒljəbl/","meaning":"adj.可溶的,易溶解的;可解决的","unit":7,"lesson":4,"seq":14,"isStar":false,"memo":"构词 solu(=solve,解决)+-ble(形容词后缀)→可解决的","example":"Vitamin C is water soluble. 维生素C可溶于水。"},{"id":2144,"word":"trace","pronunciation":"/treɪs/","meaning":"n.踪迹,痕迹;遗迹 v.追溯;(通过调查)找到,发现","unit":7,"lesson":4,"seq":15,"isStar":false,"memo":"联想 t(联想“他”)+race(比赛)→我和他比赛查找钱包的“踪迹”,最终“找到”了。","example":"It's exciting for him to discover traces of his missing dog. 当他发现走失的狗的踪迹时,他很兴奋。"},{"id":2145,"word":"track","pronunciation":"/træk/","meaning":"n.足迹;小道;轨道;跑道 v.追踪,跟踪(进展情况)","unit":7,"lesson":4,"seq":16,"isStar":false,"memo":"谐音 单词发音类似“踹开”→他把玩具小火车从“轨道”上开了。"},{"id":2146,"word":"rail","pronunciation":"/reɪl/","meaning":"n.栏杆;铁轨,轨道,铁路","unit":7,"lesson":4,"seq":17,"isStar":false,"memo":"对照 railway station 火车站→rail n.","example":"We crossed the rail track. 我们穿过了铁轨轨道。"},{"id":2147,"word":"trail","pronunciation":"/treɪl/","meaning":"n.踪迹,痕迹;(乡间的)小路 v.跟踪,追踪;拖,拉","unit":7,"lesson":4,"seq":18,"isStar":false,"memo":"联想 t(联想“他”)+rail(铁轨)→他沿着铁轨走,留下了“踪迹”。","example":"The police trailed Dale for days. 警方跟踪了戴尔多日。","derivative":"trailer /'treɪlə(r)/ n.拖车;活动房屋"},{"id":2148,"word":"trailer","pronunciation":"/'treɪlə(r)/","meaning":"n.拖车;活动房屋","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2149,"word":"derail","pronunciation":"/dɪ'reɪl/","meaning":"v.(使)脱轨,出轨;阻挠,破坏","unit":7,"lesson":4,"seq":19,"isStar":false,"memo":"构词 de-(分开)+rail(轨道)→不在铁轨上了→脱轨","example":"Policymakers should not allow low energy prices to derail the clean energy transition. 政策制定者们不应让较低的能源价格破坏清洁能源的转型。","derivative":"derailment /dɪ'reɪlmənt/ n.脱轨"},{"id":2150,"word":"derailment","pronunciation":"/dɪ'reɪlmənt/","meaning":"n.脱轨","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2151,"word":"logic","pronunciation":"/'lɒdʒɪk/","meaning":"n.思维方式;解释方法;逻辑","unit":7,"lesson":4,"seq":20,"isStar":false,"memo":"谐音 单词发音类似“逻辑”。","example":"I fail to see the logic behind his argument. 我不明白他的论点背后的逻辑。","derivative":"logical /'ldʒɪkl/ adj.合乎情理的;符合逻辑的"},{"id":2152,"word":"logical","pronunciation":"/'lɒdʒɪkl/","meaning":"adj.合乎情理的;符合逻辑的","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2153,"word":"analogy","pronunciation":"/ə'nælədʒi/","meaning":"n.类比;比拟","unit":7,"lesson":4,"seq":21,"isStar":false,"memo":"联想 a(形似乌龟)+n(形似门)+a(形似乌龟)+logy(音似“逻辑”)→门的两边各有一只小乌龟,从逻辑上讲,它俩的特征应该差不多→类比","example":"To help students understand how we see, teachers often draw an analogy between an eye and a camera. 老师经常把眼睛比作照相机,来帮助学生理解我们是怎样看东西的。","derivative":"analog(ue) /'ænəlɒg/ adj.模拟的 n.相似物\nanalogous /ə'næləgəs/ adj.相似的;类似的"},{"id":2154,"word":"analog(ue)","pronunciation":"/'ænəlg/","meaning":"adj.模拟的 n.相似物","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2155,"word":"analogous","pronunciation":"/ə'næləgəs/","meaning":"adj.相似的;类似的","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2156,"word":"analyse/-yze","pronunciation":"/'ænəlaɪz/","meaning":"v.分析","unit":7,"lesson":4,"seq":22,"isStar":false},{"id":2157,"word":"analysis","pronunciation":"/ə'næləsɪs/","meaning":"n.分析;分析结果","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2158,"word":"analytical","pronunciation":"/ˌænə'lɪtɪkl/","meaning":"adj.分析的;解析的","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2159,"word":"analyst","pronunciation":"/'ænəlɪst/","meaning":"n.分析者;化验员","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2160,"word":"dialog(ue)","pronunciation":"/'daɪəlɒg/","meaning":"n.对话,对白","unit":7,"lesson":4,"seq":23,"isStar":false},{"id":2161,"word":"ideology","pronunciation":"/ˌaɪdiˈɒlədʒi/","meaning":"n.思想(体系);思想意识","unit":7,"lesson":4,"seq":24,"isStar":false,"memo":"联想 ideo(=idea,思想)+logy(音似“逻辑”)→思想逻辑→思想(体系);思想意识","example":"These businesses have a core ideology of which profit is but one ideal. 这些公司的核心理念是:利润是唯一的理想。","derivative":"ideological /ˌadiəˈlɒdʒɪkl/ adj.思想体系的;意识形态的"},{"id":2162,"word":"ideological","pronunciation":"/ˌaɪdiəˈlɒdʒɪkl/","meaning":"adj.思想体系的;意识形态的","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2163,"word":"spirit","pronunciation":"/'spɪrɪt/","meaning":"n.精神,心灵;情绪,兴致","unit":7,"lesson":4,"seq":25,"isStar":false,"memo":"联想 他喝完雪碧(Sprite)后瞬间有了精神(spirit)。[呼吸赋予人以精神,因此词根spir意为“呼吸”。]","example":"Paired learning cultivates the spirit of cooperation. 结对学习培养合作精神。","derivative":"spiritual /ˈspɪrtʃuəl/ adj.精神的,心灵的"},{"id":2164,"word":"spiritual","pronunciation":"/'spɪrɪtʃuəl/","meaning":"adj.精神的,心灵的","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2165,"word":"inspire","pronunciation":"/ɪn'spaɪə(r)/","meaning":"v.激励,鼓励;激起,唤起","unit":7,"lesson":4,"seq":26,"isStar":false,"memo":"构词 in(里面)+spir(呼吸)+e→注入生气,赋予精神力量→激励,鼓励","example":"The television repairman who wears a uniform tends to inspire more trust than one who appears in civilian clothes. 穿着制服的电视维修工往往比穿着便服的维修工更能激起信任。"},{"id":2166,"word":"inspiration","pronunciation":"/ˌnspə'reɪʃn/","meaning":"n.灵感","unit":7,"lesson":4,"seq":27,"isStar":false,"memo":"联想 in(里面)+spir(呼吸)+-ation(名词后缀)→我使劲吸一口气,“灵感”就来了。","example":"Music gives me inspiration. 音乐给我灵感。","derivative":"inspirational /ˌɪnspəˈreɪənl/ adj.启发灵感的;鼓舞人心的"},{"id":2167,"word":"inspirational","pronunciation":"/ɪnspə'reɪʃənl/","meaning":"adj.启发灵感的;鼓舞人心的","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2168,"word":"aspire","pronunciation":"/ə'spaɪə(r)/","meaning":"v.追求,渴望;有志于","unit":7,"lesson":4,"seq":28,"isStar":false,"memo":"构词 a-(表加强)+spir(呼吸)+e→因某事而呼吸急促→渴望","example":"They aspire to managerial positions. 他们渴望管理职位。","derivative":"aspiration /ˌæspəˈreɪʃn/ n.渴望;抱负,志向"},{"id":2169,"word":"aspiration","pronunciation":"/ˌæspə'reɪʃn/","meaning":"n.渴望;抱负,志向","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2170,"word":"conspire","pronunciation":"/kən'spaɪə(r)/","meaning":"v.共谋;密谋","unit":7,"lesson":4,"seq":29,"isStar":false,"memo":"构词 con-(共同)+spir(呼吸)+e→同呼吸,共存亡→共谋","example":"There are four parties conspiring to keep you connected: the tech, your boss, your friends and you. 有四方合谋让你保持在线:科技、你的老板、你的朋友和你自己。"},{"id":2171,"word":"expire","pronunciation":"/ɪk'spaɪə(r)/","meaning":"v.到期,过期,失效;(任期)届满;死亡","unit":7,"lesson":4,"seq":30,"isStar":false,"memo":"构词 ex-(向外)+(s)pir(呼吸)+e→向外呼出最后一口气→死亡","example":"Mike just discovered that his passport had expired three months ago. 迈克刚发现他的护照三个月前就过期了。","derivative":"expiration /ˌekspəreɪʃn/ n.(文件、协议等的)满期,到期"},{"id":2172,"word":"expiration","pronunciation":"/ˌekspə'reɪʃn/","meaning":"n.(文件、协议等的)满期,到期","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2173,"word":"gasp","pronunciation":"/ɡɑːsp/","meaning":"n.喘息,倒抽气 v.喘息;气吁吁地说","unit":7,"lesson":4,"seq":31,"isStar":false,"memo":"联想 gas(汽油)+p(联想“趴”)→他趴在汽油旁,闻到了刺鼻的汽油味,发出“喘息”声。","example":"The cold made her gasp. 寒冷使她倒抽了一口凉气。"},{"id":2174,"word":"cease","pronunciation":"/siːs/","meaning":"v.停止,终止,终了","unit":7,"lesson":4,"seq":32,"isStar":false,"memo":"谐音 单词发音类似“谁死”→停止,终止","example":"Welfare payments cease as soon as an individual starts a job. 一旦就业,即停发福利救济。"},{"id":2175,"word":"suspend","pronunciation":"/sə'spend/","meaning":"v.悬,挂;暂停,中止","unit":7,"lesson":4,"seq":33,"isStar":false,"memo":"联想 sus-(往下) + pen(钢笔) + d(音似“的”)→过去有钢笔的人往往会把钢笔朝下“挂”在口袋上。","example":"A lamp was suspended from the ceiling. 一盏灯悬挂在天花板上。","derivative":"suspense /səˈspens/ n.担心；焦虑；兴奋；悬念；suspension /səˈspenʃn/ n.暂令停职（或停学、停赛等）；暂缓；推迟"},{"id":2176,"word":"suspense","pronunciation":"/sə'spens/","meaning":"n.担心;焦虑;兴奋;悬念","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2177,"word":"suspension","pronunciation":"/sə'spenʃn/","meaning":"n.暂令停职(或停学、停赛等);暂缓;推迟","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2178,"word":"pendulum","pronunciation":"/'pendʒələm/","meaning":"n.钟摆;(主张、信念等的)摇摆不定","unit":7,"lesson":4,"seq":34,"isStar":false,"memo":"联想 pend(悬挂) + ulum→“钟摆”挂在墙上，左右摇摆。","example":"Its tail swung back and forth like the pendulum of a clock. 它的尾巴像钟摆一样来回摆动。"},{"id":2179,"word":"appendix","pronunciation":"/ə'pendɪks/","meaning":"n.阑尾;(书末的)附录","unit":7,"lesson":4,"seq":35,"isStar":false,"memo":"联想 ap-(一再地) + pend(悬挂) + ix→书后面挂的东西是“附录”。","example":"We are not certain whether the appendix had already burst or not. 我们不能确定阑尾破了没有。"},{"id":2180,"word":"postpone","pronunciation":"/pə'spəʊn/","meaning":"v.延迟,延期","unit":7,"lesson":4,"seq":36,"isStar":false,"memo":"联想 post(邮寄) + pone(联想 phone,手机)→邮寄手机的过程中遇到问题了，所以要“延期”派送。","example":"The game has already been postponed three times. 这场比赛已经三度延期了。","derivative":"postponement /pəʊstˈpəʊnmənt/ n.推迟"},{"id":2181,"word":"postponement","pronunciation":"/pə'spəʊnmənt/","meaning":"n.推迟","unit":7,"lesson":4,"seq":0,"isStar":true},{"id":2182,"word":"symphony","pronunciation":"/'simfəni/","meaning":"n.交响乐，交响曲","unit":7,"lesson":4,"seq":37,"isStar":false,"memo":"联想 sym(音似 same) + phon(声音) + y→不同声音的乐器同时演奏同一首乐曲→交响乐","example":"It's the first performance of the States Symphony Orchestra in our city. 这是国家交响乐团在我们这个城市的首次演出。"},{"id":2183,"word":"melody","pronunciation":"/'melədi/","meaning":"n.旋律，曲调，悦耳的音乐","unit":7,"lesson":4,"seq":38,"isStar":false,"memo":"谐音 单词发音类似“买了笛”→他买了一支笛子，吹奏出美妙的“旋律”。","example":"The melody of this song is really beautiful. 这首歌的旋律非常优美。","derivative":"melodious /məˈləʊdiəs/ adj.悦耳的；优美动听的"},{"id":2184,"word":"symptom","pronunciation":"/'sɪmptəm/","meaning":"n.征兆；症状","unit":7,"lesson":4,"seq":39,"isStar":false,"memo":"联想 sym(音似 same) + p + tom(音似“童木”)→他和阿童木长得一样,有同样的特征→症状","example":"Flu symptoms include fever and chills. 流感症状包括发烧和寒战。"},{"id":2185,"word":"symposium","pronunciation":"/sɪm'pəʊziəm/","meaning":"n.专题讨论会；研讨会","unit":7,"lesson":4,"seq":40,"isStar":false,"memo":"联想 sym(音似 same) + pos(联想 pose,提出) + -ium(名词后缀)→一群相同身份的人聚在一起提出各种观点的场合→研讨会","example":"He will take part in an international symposium on population. 他将参加一个有关人口的国际研讨会。"},{"id":2186,"word":"sympathy","pronunciation":"/'sɪmpəθi/","meaning":"n.同情；赞同；支持","unit":7,"lesson":4,"seq":41,"isStar":false,"memo":"联想 sym(音似 same) + path(道路) + y→同道中人最能相互“同情”。","example":"He didn't get much sympathy from anyone. 他没有从别人那里得到多少同情。","derivative":"sympathise/-ize /'sɪmpəθaɪz/ v.同情;赞同,支持"},{"id":2187,"word":"sympathetic","pronunciation":"/ˌsɪmpə'θetɪk/","meaning":"adj.同情的，有同情心的；赞同的","unit":7,"lesson":4,"seq":42,"isStar":false,"memo":"对照 sympathy n.同情;赞同→sympathetic adj.","example":"They felt sympathetic to the other child. 他们很同情另一个孩子。"},{"id":2188,"word":"mercy","pronunciation":"/'mɜːsi/","meaning":"n.仁慈，宽容；幸运，恩惠","unit":7,"lesson":4,"seq":43,"isStar":false,"memo":"联想 me(我) + rcy(联想 cry)→“仁慈”的我特别容易被感动哭。","example":"Virtue, mercy and justice are taken as the skills of successful leaders. 美德、仁慈和正义被认为是成功领导者的技能。","derivative":"merciful /'mɜːsfl/ adj.仁慈的,宽大的"},{"id":2189,"word":"pathetic","pronunciation":"/'pæ'θetɪk/","meaning":"adj.可怜的，可悲的，令人怜惜的","unit":7,"lesson":4,"seq":44,"isStar":false,"memo":"对照 那些可怜的(pathetic)人让她产生了同情的(sympathetic)心理。","example":"People were saddened when they watched the pathetic sight on TV. 当人们在电视上看到这可悲的场景时,他们都很难过。"},{"id":2190,"word":"naive","pronunciation":"/naɪ'ɪv/","meaning":"adj.幼稚的，轻信的，天真的，率直的","unit":7,"lesson":4,"seq":45,"isStar":false,"memo":"联想 nai(联想“奶”) + ve(联想“喂”)→还在被喂奶的孩子的特点是“幼稚的”。","example":"I can't believe you were so naive as to trust him! 真是难以相信,你会幼稚到信任他!","derivative":"naivety /naɪ'iːvəti/ n.天真,幼稚"},{"id":2191,"word":"innocent","pronunciation":"/'ɪnəsnt/","meaning":"adj.清白的，无罪的，天真的，无知的","unit":7,"lesson":4,"seq":46,"isStar":false,"memo":"联想 in(里面) + no(没有) + cent(分币)→“天真的”小孩口袋里没有一分钱。","example":"I am convinced that she is innocent of any crime. 我坚信她是清白无罪的。","derivative":"innocence /'nəsns/ n.清白;天真"},{"id":2192,"word":"fold","pronunciation":"/fəuld/","meaning":"v.折叠，对折；包，裹 n.褶，褶痕；折叠部分","unit":8,"lesson":1,"seq":1,"isStar":false,"memo":"联想 f(联想“父”)+old(年老的)→父亲老了,脸上有了“褶”。","example":"It has wings that can fold. 它有可以折叠的翅膀。"},{"id":2193,"word":"unfold","pronunciation":"/ʌn'fəuld/","meaning":"v.(使)展开，打开；展示，发生，发展","unit":8,"lesson":1,"seq":2,"isStar":false,"memo":"构词 un-(否定前缀)+fold(折叠;包,裹)→(使)展开,打开","example":"The most remarkable part of the story unfolded only last week. 这个故事最引人注目的部分在上周刚刚展开。"},{"id":2194,"word":"undo","pronunciation":"/ʌn'du:/","meaning":"v.打开；消除，取消，废止；打败","unit":8,"lesson":1,"seq":3,"isStar":false,"example":"I undid the package and took out the books. 我打开包裹取出书来。"},{"id":2195,"word":"wrinkle","pronunciation":"/'rɪŋkl/","meaning":"n.皱纹；褶皱，皱痕 v.(使脸上)起皱纹，皱起；(使)起褶皱","unit":8,"lesson":1,"seq":4,"isStar":false,"memo":"联想 wr(联想 write)+ink(墨水)+le(联想“了”)→他用墨水写写画画,给画中人画了很多“皱纹”。","example":"Her face was a mass of wrinkles. 她的脸上布满了皱纹。"},{"id":2196,"word":"zigzag","pronunciation":"/'zɪgzæg/","meaning":"n.锯齿形线条(或形状)；之字形 v.曲折前进","unit":8,"lesson":1,"seq":5,"isStar":false},{"id":2197,"word":"overlap","pronunciation":"/ˌəʊvə'læp/","meaning":"v.部分重叠，交叠","unit":8,"lesson":1,"seq":6,"isStar":false,"memo":"联想 over(在……上面)+lap(音似“来扑”)→一群小孩玩叠罗汉游戏,接连扑来趴在上面→部分重叠","example":"There is considerable overlap between the girls’ and boys’ test results. 女孩和男孩的测试结果有相当多的重叠。"},{"id":2198,"word":"lay","pronunciation":"/leɪ/","meaning":"v.安放，放置；下(蛋)，产(卵)；提出，提交  adj.外行的，非专业的；世俗的","unit":8,"lesson":1,"seq":7,"isStar":false,"memo":"谐音 单词发音类似“累”→如果你累了,可以把头靠在我的肩膀上→安放,放置","example":"Fishes are caught when they are on the way upstream to lay eggs. 鱼类在去上游产卵时被捕获。"},{"id":2199,"word":"lay-off","pronunciation":"/'leɪ ɒf/","meaning":"n.解雇，裁员","unit":8,"lesson":1,"seq":8,"isStar":false},{"id":2200,"word":"layer","pronunciation":"/'leɪə(r)/","meaning":"n.层，表层；层次，阶层  v.把……分层堆放；铺一层……；把(头发)分层剪短","unit":8,"lesson":1,"seq":9,"isStar":false,"example":"Ducks have a thick layer of fat to keep them warm. 鸭子有一层厚厚的脂肪来保暖。"},{"id":2201,"word":"layman","pronunciation":"/'leɪmən/","meaning":"n.非专业人员，门外汉，外行人","unit":8,"lesson":1,"seq":10,"isStar":false,"memo":"联想 lay(lie“躺”的过去式)+man(人)→躺平的人不可能成为行业的精英，也就是个“外行人”。","example":"Where the law is concerned, I am only a layman. 谈到法律，我不过是个门外汉。"},{"id":2202,"word":"amateur","pronunciation":"/'æmətə(r)/","meaning":"n.业余爱好者，外行  adj.业余的","unit":8,"lesson":1,"seq":11,"isStar":false,"memo":"联想 ama(音似“爱莫”)+t(联想“他”)+eur→他爱莫能助，因为他是“外行”，水平不够。","example":"She is an amateur photographer. 她是一名业余摄影师。"},{"id":2203,"word":"veteran","pronunciation":"/'vetərən/","meaning":"n.老兵，退伍军人；经验丰富的人，老手","unit":8,"lesson":1,"seq":12,"isStar":false,"memo":"联想 v(形似罗马数字5)+cte(形似人脸)+ran(run的过去式)→战争期间，五个“老兵”跑去了前线。","example":"He is a seasoned veteran of the political establishment. 他是位经验丰富的政坛老手。"},{"id":2204,"word":"sophisticated","pronunciation":"/sə'fɪstɪkeɪtɪd/","meaning":"adj.见多识广的；老练的；复杂的，精密的，先进的","unit":8,"lesson":1,"seq":13,"isStar":false,"memo":"联想 so(非常)+phisticated(音似“费时啃它”)→这是个“复杂”的问题，攻克它非常费时。","example":"He is a smart and sophisticated young man. 他是一个聪明、老练的年轻人。","derivative":"sophistication /sɒfɪst'keɪʃn/ n.老练，世故；复杂巧妙；高水平"},{"id":2205,"word":"layout","pronunciation":"/'leɪaʊt/","meaning":"n.布局；设计；版面编排，版面设计","unit":8,"lesson":1,"seq":14,"isStar":false,"memo":"构词 lay(放置)+out(出去)→布局","example":"The woman would like to help with the exhibition layout. 这位女士想帮忙布置展览。"},{"id":2206,"word":"relay","pronunciation":"/'riːleɪ/","meaning":"n.轮班，轮换；接力赛；转播设备","unit":8,"lesson":1,"seq":15,"isStar":false,"memo":"联想 re(字母音似“阿姨”)+lay(lie“躺”的过去式)→阿姨作为“轮班”人员，累得躺下了。","example":"They raced to a thrilling victory in the relay. 他们在接力赛中奋力冲刺，取得了激动人心的胜利。"},{"id":2207,"word":"delay","pronunciation":"/dɪ'leɪ/","meaning":"n.延期，耽搁，延误，延迟(或耽搁、拖延)的时间  v.延迟，延期，推迟","unit":8,"lesson":1,"seq":16,"isStar":false,"memo":"构词 de-(向下)+lay(放置)→往下面放→延期，推迟","example":"It's also a good idea to delay the conversation if you are in a meeting. 如果你在开会，推迟谈话也是个好主意。"},{"id":2208,"word":"deputy","pronunciation":"/'deputi/","meaning":"n.副手，副职，代理","unit":8,"lesson":1,"seq":17,"isStar":false},{"id":2209,"word":"vice","pronunciation":"/vaɪs/","meaning":"adj.代理的；副的 n.罪行，邪恶行径，恶习，恶行","unit":8,"lesson":1,"seq":18,"isStar":false,"example":"Greed is a terrible vice.贪婪是一种可怕的恶习。"},{"id":2210,"word":"outline","pronunciation":"/'aʊtlain/","meaning":"n.提纲，纲要；梗概；轮廓  v.概述，提出……的纲要；画……的轮廓","unit":8,"lesson":1,"seq":19,"isStar":false,"memo":"(构词) out(外面)+line(线)→外部线条→轮廓","example":"The outline of the changes needed is clear.变更所需要的提纲是很清晰的。"},{"id":2211,"word":"outlook","pronunciation":"/'aʊtlʊk/","meaning":"n.景色；前景；观点；世界观；人生观","unit":8,"lesson":1,"seq":20,"isStar":false,"memo":"(构词) out(往外)+look(看)→往外看到的是“景色”。","example":"The outlook for jobs is pretty bright.就业市场前景十分光明。"},{"id":2212,"word":"outlet","pronunciation":"/'aʊtlət/","meaning":"n.专营店，经销店；折扣店；出路，表现机会；出口","unit":8,"lesson":1,"seq":21,"isStar":false,"memo":"(构词) out(出去)+let(让)→让……出去→出口","example":"The business has 34 retail outlets in this state alone.那家公司仅在这个州就有34个零售店。"},{"id":2213,"word":"inner","pronunciation":"/'ɪnə(r)/","meaning":"adj.里面的，向内的，内部的，接近中心的；内心的，未表达出来的","unit":8,"lesson":1,"seq":22,"isStar":false,"example":"She doesn't reveal much of her inner self.她不大流露她内心的自我。"},{"id":2214,"word":"outer","pronunciation":"/'aʊtə(r)/","meaning":"adj.外表的，外边的，外部的","unit":8,"lesson":1,"seq":23,"isStar":false,"memo":"(构词) out(外面)+-er(后缀)→外边的,外部的","example":"It consists of an inner and an outer tent.它包括里外两个帐篷。"},{"id":2215,"word":"indoor","pronunciation":"/'ɪndɔ:(r)/","meaning":"adj.室内的；在户内进行的，在室内用的","unit":8,"lesson":1,"seq":24,"isStar":false},{"id":2216,"word":"outdoor","pronunciation":"/'aʊtdɔ:(r)/","meaning":"adj.户外的，室外的 n.野外，旷野，郊外","unit":8,"lesson":1,"seq":25,"isStar":false,"memo":"(构词) out(在……外面)+door(门)→在门外面→户外的,室外的","example":"They sell camping equipment, hiking gear and outdoor clothing.他们出售露营装备、徒步旅行装备和户外服装。","derivative":"outdoors /'aʊt'dɔːz/ adv.在户外,在野外 n.野外,旷野,郊外"},{"id":2217,"word":"turnout","pronunciation":"/'taːnʌt/","meaning":"n.出席人数，到场人数；投票人数","unit":8,"lesson":1,"seq":26,"isStar":false},{"id":2218,"word":"inward","pronunciation":"/'ɪnwəd/","meaning":"adj.内心的，精神的；向内的 adv.向内；向中心","unit":8,"lesson":1,"seq":27,"isStar":false,"memo":"构词：in(里面) + -ward(向……的)→内心的;向内(的)","example":"The door opens inward.门向里开。"},{"id":2219,"word":"outward","pronunciation":"/'aʊtwəd/","meaning":"adj.表面的，外表的；外出的；向外的 adv.朝外面，向外","unit":8,"lesson":1,"seq":28,"isStar":false,"memo":"构词：out(外面) + -ward(向……的)→外表的;向外(的)","example":"The top door opened outward.最上面的门向外开着。"},{"id":2220,"word":"interior","pronunciation":"/ɪn'tɪəriə(r)/","meaning":"n.内部 adj.内部的，里面的","unit":8,"lesson":1,"seq":29,"isStar":false,"memo":"构词：inter(内部) + -ior(后缀)→内部的,里面的","example":"The original interior of the hotel has been replaced.旅馆原来的内部装潢已被更换掉了。"},{"id":2221,"word":"exterior","pronunciation":"/ɪk'stɪəriə(r)/","meaning":"n.(尤指建筑物的)外部，外观 adj.外面的，外部的","unit":8,"lesson":1,"seq":30,"isStar":false,"memo":"对照：这栋建筑的外部(exterior)设计得很低调,内部(interior)装修得很豪华。","example":"The exterior lights of the house came on as I approached the door.当我走近门的时候,房子外面的灯亮了。"},{"id":2222,"word":"internal","pronunciation":"/ɪn'tɜːnl/","meaning":"adj.内部的；内政的；国内的","unit":8,"lesson":1,"seq":31,"isStar":false,"memo":"构词：inter-(内部) + n + -al(形容词后缀)→内部的","example":"She was on an internal flight from London to Manchester.她在从伦敦到曼彻斯特的国内航班上。"},{"id":2223,"word":"external","pronunciation":"/ɪk'stɜːnl/","meaning":"adj.外部的，外界的，外来的；对外的","unit":8,"lesson":1,"seq":32,"isStar":false,"example":"What is the response of many educators to external rewards for their students?许多教育工作者对学生获得外部奖励的反应是什么?"},{"id":2224,"word":"outcome","pronunciation":"/'aʊtkʌm/","meaning":"n.结果，成果","unit":8,"lesson":1,"seq":33,"isStar":false,"memo":"构词：out(往外) + come(来)→往外出来→结果,成果","example":"Consider the person that you're dealing with in advance and what will get you to your desired outcome.事先考虑一下你要与之打交道的人,以及什么会让你达到你想要的结果。"},{"id":2225,"word":"outbreak","pronunciation":"/'aʊtbreɪk/","meaning":"n.(暴力、疾病等坏事的)爆发，突然发生","unit":8,"lesson":1,"seq":34,"isStar":false},{"id":2226,"word":"output","pronunciation":"/'aʊtpʊt/","meaning":"n.(人、机器、机构的)产量，输出量 v.输出","unit":8,"lesson":1,"seq":35,"isStar":false,"memo":"构词：out(往外) + put(放)→输出","example":"In order to maximize profit, the firm would seek to maximize output.为了获得最大利润,这家公司会把产量增至最大。"},{"id":2227,"word":"input","pronunciation":"/'ɪnpʊt/","meaning":"n.投入资源(指时间、知识、思想等)；投入，输入 v.输入(信息)","unit":8,"lesson":1,"seq":36,"isStar":false,"memo":"in（进）+ put（放）→‘放进去’！键盘敲字是输入信息，熬夜赶PPT也是‘put time in’——双关秒懂！","example":"Teachers’ feedback is a crucial input for curriculum redesign. 教师的反馈是课程重新设计的关键投入。"},{"id":2228,"word":"yield","pronunciation":"/jiːld/","meaning":"n.产量，利润 v.出产；产生，屈服","unit":8,"lesson":1,"seq":37,"isStar":false,"memo":"联想 yi(联想“一”)+eld(联想 old)→有一个爷爷年纪很大,但仍然关心粮食“产量”。","example":"What does it yield? 它会产生什么?"},{"id":2229,"word":"vacant","pronunciation":"/'veɪkənt/","meaning":"adj.空着的，未被占用的；(职位)空缺的","unit":8,"lesson":1,"seq":38,"isStar":false,"memo":"谐音 单词发音类似“未垦的”→一片土地尚未被开垦→空着的,未被占用的","example":"Only a few apartments were still vacant. 只有几套公寓仍然空着。","derivative":"vacancy /'veɪkənsi/ n.空缺,空额;空房间;空虚"},{"id":2230,"word":"blank","pronunciation":"/blæŋk/","meaning":"adj.空白的，空的；没有表情的 n.空白处，空格 v.突然记不起，不理睬","unit":8,"lesson":1,"seq":39,"isStar":false,"memo":"谐音 单词发音类似“不来客”→那家面馆晚上不来客人,总是“空的”。","example":"Leave the last page blank. 最后一页空着。"},{"id":2231,"word":"vacuum","pronunciation":"/'vækjuːm/","meaning":"n.真空；（用真空吸尘器所做的）清洁；空白；空虚","unit":8,"lesson":1,"seq":40,"isStar":false,"memo":"构词 vac(空,无)+u+-um(名词后缀)→真空;空白","example":"His resignation has created a vacuum which cannot easily be filled. 他的辞职造成了难以填补的空白。"},{"id":2232,"word":"evacuate","pronunciation":"/ɪ'vækjuːeɪt/","meaning":"v.（把人从危险的地方）疏散，转移，撤离；排泄","unit":8,"lesson":1,"seq":41,"isStar":false,"memo":"构词 e-(出,向外)+vac(空,无)+u+-ate(动词后缀)→使……向外变空→撤离;排泄","example":"All the sick and wounded were evacuated. 所有生病和受伤的人员都被疏散了。","derivative":"evacuation /ɪˌvækju'eɪʃn/ n.疏散,撤离;排泄"},{"id":2233,"word":"vacation","pronunciation":"/və'keɪʃn; veɪ'keɪʃn/","meaning":"n.假期，休假 v.度假，休假","unit":8,"lesson":1,"seq":42,"isStar":false,"memo":"谐音 单词发音类似“我开心”→“假期”的时候我很开心。","example":"A vacation will be affordable if one saves 20 dollars a week. 如果一个人每周存 20 美元,就可以负担得起一次度假。"},{"id":2234,"word":"vocation","pronunciation":"/'vəʊ'keɪʃn/","meaning":"n.工作，职业；使命感；天职","unit":8,"lesson":1,"seq":43,"isStar":false,"memo":"对照 在假期(vacation)不要提工作(vocation)。","example":"He argued that attaining a vocation is one of the best ways to mature. 他认为,获得一份职业是走向成熟的最佳途径之一。","derivative":"vocational /vəʊ'keɪʃənl/ adj.职业的"},{"id":2235,"word":"excursion","pronunciation":"/ɪk'skɜːʃn/","meaning":"n.（尤指集体度假时的）远足，短途旅行","unit":8,"lesson":1,"seq":44,"isStar":false,"memo":"联想 ex-(出去)+cursion(音似“开心”)→出去“远足”会使人开心。"},{"id":2236,"word":"expedition","pronunciation":"/ɪkspə'dɪʃn/","meaning":"n.远征，探险；考察队，探险队；短途出行","unit":8,"lesson":1,"seq":45,"isStar":false,"memo":"联想 ex-(往外)+pedi(音似“盆地”)+-tion (名词后缀)→我外出去塔里木盆地“探险”。","example":"Our expedition included many highly successful people. 我们的探险队中有许多非常成功的人。"},{"id":2237,"word":"commute","pronunciation":"/kə'mjuːt/","meaning":"n.上下班的路程，通勤 v.上下班往返，通勤；减刑","unit":8,"lesson":1,"seq":46,"isStar":false,"memo":"对照 交流(communicate)有来有往,通勤(commute)也是有去有回。","example":"If you are attending a local college, you'll probably live at home and commute to classes. 如果你要上当地的大学,你可能会住在家里,通勤去上课。","derivative":"commuter /kəˈmjutə(r)/ n.长途上下班往返的人,通勤者"},{"id":2238,"word":"shuttle","pronunciation":"/'ʃʌtl/","meaning":"v.穿梭，往返运送 n.来往于两地之间的航班（或班车、火车）","unit":8,"lesson":1,"seq":47,"isStar":false,"memo":"联想 shut(关闭)+t+le(联想“了”)→车门关闭了,他在车站来回“穿梭”,等下一班车。","example":"A bus shuttles passengers back and forth from the station to the terminal. 一辆公共汽车在火车站和航站楼之间往返运送旅客。"},{"id":2239,"word":"trek","pronunciation":"/trek/","meaning":"n.艰苦长途旅行；（显得很漫长的）一段路程 v.徒步旅行，远足；艰苦跋涉","unit":8,"lesson":1,"seq":48,"isStar":false},{"id":2240,"word":"wreck","pronunciation":"/rek/","meaning":"n.沉船，失事船；遭严重损毁的车辆 v.破坏，糟蹋；使毁坏；（船只）失事","unit":8,"lesson":1,"seq":49,"isStar":false,"memo":"联想 w(联想“我”)+reck(联想 neck)→我遭遇了“沉船”事故,现场“破坏”严重,我的脖子也受伤了。","example":"The wreck is lying at the bottom of the sea. 这艘失事船沉在海底。","derivative":"wreckage /'rekɪdʒ/ n.残骸;残余"},{"id":2241,"word":"voyage","pronunciation":"/'vɒɪdʒ/","meaning":"n.航行；（尤指）航海，航天 v.航行，远行；（尤指）远航","unit":8,"lesson":1,"seq":50,"isStar":false,"memo":"联想 vo(音似“我”)+yage(联想 yoga)→我练瑜伽时会冥想,就像思想在“航行”。","example":"He saw life as a voyage of discovery. 他把生活看作是一场发现之旅。"},{"id":2242,"word":"yoga","pronunciation":"/'jɔːɡə/","meaning":"n.瑜伽","unit":8,"lesson":1,"seq":51,"isStar":false},{"id":2243,"word":"tread","pronunciation":"/tred/","meaning":"n.步态，脚步声 v.踩，踏；行走","unit":8,"lesson":1,"seq":52,"isStar":false},{"id":2244,"word":"wander","pronunciation":"/'wɒndə(r)/","meaning":"v.徘徊，闲逛，漫步；走神；（河流、道路等）蜿蜒曲折","unit":8,"lesson":1,"seq":53,"isStar":false,"memo":"谐音：单词发音类似“玩的”→不知道去哪里玩的人，可以去街上“闲逛”。","example":"My thought started to wander. 我开始走神。"},{"id":2245,"word":"linger","pronunciation":"/'lɪŋɡə(r)/","meaning":"v.继续存留，逗留，徘徊，拖延，磨蹭","unit":8,"lesson":1,"seq":54,"isStar":false,"example":"Elisabeth did not enter the museum at once, but lingered in the courtyard. 伊丽莎白没有马上进博物馆，而是在院子里徘徊。"},{"id":2246,"word":"stroll","pronunciation":"/strəʊl/","meaning":"n. & v.散步，闲逛，溜达","unit":8,"lesson":1,"seq":55,"isStar":false},{"id":2247,"word":"dart","pronunciation":"/dɑːt/","meaning":"v.猛冲，突进，飞奔；瞥一眼 n.镖，飞镖；猛冲，突进，飞奔","unit":8,"lesson":1,"seq":56,"isStar":false},{"id":2248,"word":"sneak","pronunciation":"/snɪk/","meaning":"v.偷偷地走，溜；偷偷地做","unit":8,"lesson":1,"seq":57,"isStar":false},{"id":2249,"word":"crawl","pronunciation":"/kroːl/","meaning":"n.缓慢移动，徐行；自由泳，爬泳 v.爬，爬行；（车辆）缓慢行进","unit":8,"lesson":1,"seq":58,"isStar":false,"memo":"谐音：单词发音类似“可弱”→他身体可弱了，走路只能“缓慢移动”。","example":"Our baby is just starting to crawl. 我们的宝宝刚开始会爬。"},{"id":2250,"word":"creep","pronunciation":"/kriːp/","meaning":"v.蹑手蹑脚地移动；匍匐行进，爬行；蔓延","unit":8,"lesson":1,"seq":59,"isStar":false,"memo":"联想：cr(联想“超人”) + ee(形似两只眼睛) + p(联想“趴”)→超人瞪着两只眼睛，趴在地上“爬行”。","example":"I saw a shadow creep across the floor. 我看见一个影子在地板上悄悄移动。"},{"id":2251,"word":"cripple","pronunciation":"/ˈkrɪpl/","meaning":"v.使残废；使成瘸子；严重毁坏 n.残疾人；瘸子","unit":8,"lesson":1,"seq":60,"isStar":false,"memo":"对照：一场意外让他差点成了瘸子（cripple），康复初期只能爬行（creep）。","example":"He was crippled by polio as a child. 他幼年患过小儿麻痹症，结果腿就瘸了。"},{"id":2252,"word":"climb","pronunciation":"/klaɪm/","meaning":"v.攀登；上升  n.攀登；增值","unit":8,"lesson":1,"seq":61,"isStar":false,"memo":"联想：c(音似“可”) + limb(肢)→“攀登”可要靠四肢发力。","example":"She climbed up the stairs. 她爬上了楼梯。"},{"id":2253,"word":"chase","pronunciation":"/tʃeɪs/","meaning":"v. & n.努力获取；追赶；追求","unit":8,"lesson":1,"seq":62,"isStar":false,"memo":"联想：cha(联想“叉”) + se(音似“死”)→他在“追赶”一个臭虫，试图用叉子扎死它。"},{"id":2254,"word":"prey","pronunciation":"/preɪ/","meaning":"n.猎物；受害者  v.捕食；欺凌；坑骗","unit":8,"lesson":1,"seq":63,"isStar":false,"memo":"[谐音] 单词发音类似“扑弱”→动物界中的强者在“捕食”时会扑咬弱者,弱者通常被称为“猎物”。","example":"They have fallen prey to wolves. 它们成了狼的猎物。"},{"id":2255,"word":"predator","pronunciation":"/ˈpredətə(r)/","meaning":"n.捕食性动物；掠夺者；弱肉强食者","unit":8,"lesson":1,"seq":64,"isStar":false,"example":"Animals protect themselves against predators. 动物保护自己不受捕食者的伤害。","derivative":"predatory /'predətri/ adj.捕食性的;欺负弱小的"},{"id":2256,"word":"stumble","pronunciation":"/ˈstʌmbl/","meaning":"v.跌跌撞撞地走，蹒跚而行；绊脚；（不顺畅地）说，读，演奏","unit":8,"lesson":1,"seq":65,"isStar":false,"memo":"[联想] stu(音似“厮打”) + m(联想“妹”) + ble→妹妹与他厮打时崴到了脚,现在只能“蹒跚而行”。","example":"We were stumbling around in the dark looking for a candle. 黑暗中,我们东跌西撞地找蜡烛。"},{"id":2257,"word":"stump","pronunciation":"/stʌmp/","meaning":"n.树桩；残根，残段","unit":8,"lesson":1,"seq":66,"isStar":false,"memo":"[联想] stu(音似“厮打”) + m(联想“妹”) + p(联想“扑”)→妹妹与他厮打时不慎扑到了“树桩”上。","example":"The rock could almost be mistaken for the stump of an enormous tree. 这块石头差点被误认为是一棵大树的树桩。"},{"id":2258,"word":"stun","pronunciation":"/stʌn/","meaning":"v.使昏迷；使震惊","unit":8,"lesson":1,"seq":67,"isStar":false},{"id":2259,"word":"supply","pronunciation":"/səˈplaɪ/","meaning":"n.供应，供给  v.供应","unit":8,"lesson":2,"seq":1,"isStar":false,"example":"The abundant food supply is not expected to last.充足的粮食供应预计不会持续下去。","derivative":"supplier /səˈplaɪə(r)/ n.供应者;供货商"},{"id":2260,"word":"supplement","pronunciation":"/ˈsʌplɪment/","meaning":"n.增补物，补充物；附录；增刊","unit":8,"lesson":2,"seq":2,"isStar":false,"memo":"联想 supple(联想 supply)+-ment(后缀)→这是我们提供给他的“补充物”。","example":"He supplements his income by giving private lessons.他通过教授私人课程来补充收入。","derivative":"supplementary /ˌsʌplɪˈmentri/ adj.增补的,附加的"},{"id":2261,"word":"complement","pronunciation":"/ˈkɒmplɪment/","meaning":"n.补充物；补充","unit":8,"lesson":2,"seq":3,"isStar":false,"memo":"构词 com-(共同)+ple(填满)+-ment(后缀)→共同填满→补充","example":"The green wallpaper is the perfect complement to the old pine of the dresser.绿色墙纸与旧松木梳妆台完美互补。"},{"id":2262,"word":"implement","pronunciation":"/ˈɪmplɪment/","meaning":"v.执行，贯彻，实施","unit":8,"lesson":2,"seq":4,"isStar":false,"memo":"构词 im-(进入)+ple(填满)+-ment(后缀)→使某事进入填满(完善)状态的手段→执行,贯彻,实施","example":"Universal health care is to be implemented throughout the country.全民医保将在全国范围内实施。","derivative":"implementation /ˌmplɪmen'teɪʃn/ n.实施,履行"},{"id":2263,"word":"compensate","pronunciation":"/'kompenseɪt/","meaning":"v.偿还，补偿","unit":8,"lesson":2,"seq":5,"isStar":false,"memo":"联想 com-(所有)+pens(钢笔)+-ate(动词后缀)→他把我的所有钢笔都弄坏了,我要求“补偿”。","example":"To compensate for the fast-shrinking labour force, the country would need large numbers of immigrants from overseas.为了弥补劳动力的快速萎缩,该国需要大量的海外移民。","derivative":"compensation /ˌkmpen'seɪʃn/ n.补偿物;赔偿金 compensatory /ˌkɒmpen'seɪtəri/ adj.补偿性的"},{"id":2264,"word":"addict","pronunciation":"/'ædɪkt/","meaning":"n.吸毒成瘾的人；对……着迷的人","unit":8,"lesson":2,"seq":6,"isStar":false},{"id":2265,"word":"indulge","pronunciation":"/ɪn'dʌldʒ/","meaning":"v.(使)沉溺于，放纵；参与","unit":8,"lesson":2,"seq":7,"isStar":false,"memo":"联想 in(里面)+dul(联想“读了”)+ge(联想“哥”)→哥哥每天在家里“沉溺于”读书。","example":"He has indulged in fake listening many times. 他已经有很多次沉溺于假装倾听的经历。","derivative":"indulgence /n'dʌldʒəns/ n.沉溺,放纵 indulgent /ɪn'dʌldʒənt/ adj.纵容的,放纵的"},{"id":2266,"word":"obsess","pronunciation":"/əb'ses/","meaning":"v.使痴迷；使……心神不宁；对……过分担心 n.强迫症患者","unit":8,"lesson":2,"seq":8,"isStar":false,"memo":"联想 ob-(表方向)+se(联想“色”)+ss(联想“美女”)→人们都朝着一个方向看那位出色的女性,她让人着迷→使痴迷","example":"Don't obsess about your weight. 不要过分担心你的体重。","derivative":"obsession /əb'seʃn/ n.痴迷;困扰 obsessive /əb'sesɪv/ adj.着迷的;难以释怀的 n.强迫症患者"},{"id":2267,"word":"predict","pronunciation":"/prɪ'dɪkt/","meaning":"v.预言，预测","unit":8,"lesson":2,"seq":9,"isStar":false,"memo":"构词 pre-(在……之前)+dict(说)→提前说→预言,预测","example":"Nobody could predict the outcome. 谁也无法预测结果如何。","derivative":"prediction /prɪ'dɪkʃn/ n.预言,预测 predictable /prɪ'dɪktəbl/ adj.可预见的"},{"id":2268,"word":"dictate","pronunciation":"/'dɪkteɪt/","meaning":"n.命令，规定","unit":8,"lesson":2,"seq":10,"isStar":false,"memo":"构词 dict(说)+-ate(后缀)→命令;口述","example":"I've got a long report I must dictate. 我有一个很长的报告,必须口述。","derivative":"dictation /dɪk'teɪʃn/ n.口述;听写 dictator /dɪk'teɪtə(r)/ n.独裁者;霸道的人"},{"id":2269,"word":"dictator","pronunciation":"/dɪk'teɪtə(r)/","meaning":"n.独裁者；霸道的人","unit":8,"lesson":2,"seq":11,"isStar":false},{"id":2270,"word":"contradict","pronunciation":"/,kɒntrə'dɪkt/","meaning":"v.反驳，驳斥；与……矛盾","unit":8,"lesson":2,"seq":12,"isStar":false,"memo":"构词 contra-(反对)+dict(说)→反驳"},{"id":2271,"word":"contradiction","pronunciation":"/,kɒntrə'dɪkʃn/","meaning":"n.矛盾，不一致；反驳","unit":8,"lesson":2,"seq":13,"isStar":false,"memo":"构词 contradict(与……矛盾;反驳) + -ion (名词后缀)→矛盾;反驳","example":"The evidence contradicts the claim that we're mainly suffering from structural unemployment. 证据与我们主要遭受结构性失业的说法相矛盾。"},{"id":2272,"word":"contrary","pronunciation":"/'kɒntrəri/","meaning":"n.相反，对立面 adj.相反的，相对的 v.对比，对照","unit":8,"lesson":2,"seq":14,"isStar":false,"example":"I don't find him funny at all. Quite the contrary. 正相反,我觉得他一点儿也不有趣。"},{"id":2273,"word":"deny","pronunciation":"/dɪ'naɪ/","meaning":"v.否认；拒绝","unit":8,"lesson":2,"seq":16,"isStar":false,"memo":"谐音 单词发音类似“抵赖”→抵赖可以引申为“否认”。","derivative":"denial /dɪˈnaɪəl/ n.否认;拒绝给予"},{"id":2274,"word":"defy","pronunciation":"/dɪ'faɪ/","meaning":"v.违抗（法律或规则）","unit":8,"lesson":2,"seq":17,"isStar":false,"memo":"谐音 单词发音类似“抵罚”→一个人闯红灯后抵抗罚款,就是“违抗”法律。","example":"You shouldn't openly defy the law. 你不应该公然违抗法律。","derivative":"defiance /dɪˈfaɪəns/ n.违抗,拒绝服从\ndefiant /dˈfaɪənt/ adj.公然违抗的,反抗的;挑衅的"},{"id":2275,"word":"envy","pronunciation":"/'envi/","meaning":"v. & n.忌妒；羡慕","unit":8,"lesson":2,"seq":18,"isStar":false,"memo":"谐音 单词发音类似“恩威”→他“羡慕”领导管理有方,恩威并施。","example":"The man's unique talents are the envy of many people. 这个人的独特才能令许多人羡慕。","derivative":"envious /ˈenviəs/ adj.羡慕的;忌妒的"},{"id":2276,"word":"jealous","pronunciation":"/'dʒeləs/","meaning":"adj.妒羡的，忌妒的，珍惜的","unit":8,"lesson":2,"seq":19,"isStar":false,"memo":"谐音 单词发音类似“姐乐死”→姐姐说太快乐时不能公开,以免让他人忌妒→忌妒的","example":"He's only talking to her to make you jealous. 他跟她讲话只是让你忌妒。","derivative":"jealousy /ˈdʒeləsi/ n.忌妒;羡慕"},{"id":2277,"word":"resent","pronunciation":"/rɪ'zent/","meaning":"v.对……感到愤恨（不满）","unit":8,"lesson":2,"seq":20,"isStar":false,"memo":"[联想] re-(重复) + sent(send 的过去式)→他重复把一些玩具送出去,说明不喜欢这些玩具→对……感到愤恨(不满)","example":"It is only natural that he should resent you. 他会怨恨你是很自然的。","derivative":"resentment /rɪˈzentmənt/ n.愤恨,怨恨,不满"},{"id":2278,"word":"consent","pronunciation":"/kən'sent/","meaning":"v. & n.同意，准许","unit":8,"lesson":2,"seq":21,"isStar":false,"memo":"[联想] con-(都) + sent(send 的过去式)→我问他能不能把玩具都送给我,他“同意”了。","example":"The written consent of a parent is required. 要求有家长的书面同意。"},{"id":2279,"word":"recognise","pronunciation":"/-ize/","meaning":"'rekəgnaɪz/ v.认识；辨别出；承认；意识到","unit":8,"lesson":2,"seq":22,"isStar":false},{"id":2280,"word":"cognitive","pronunciation":"/'kɒgnɪtɪv/","meaning":"adj.认知的；感知的","unit":8,"lesson":2,"seq":23,"isStar":false,"memo":"cogn（知道，词根）+ -itive（形容词）→‘能知道的’→认知的！联想‘考你five’：考试考你五感+脑子怎么认东西。","example":"Cognitive development is crucial during early childhood education. 认知发展对早期教育至关重要。","derivative":"cognition /kɒɡˈnɪʃn/ n.认知；cognize /ˈkɒɡnaɪz/ v.认识"},{"id":2281,"word":"aware","pronunciation":"/ə'weə(r)/","meaning":"adj.意识到的，察觉到的","unit":8,"lesson":2,"seq":24,"isStar":false,"memo":"[联想] a(一) + war(战争) + e(字母音似“姨”)→一场战争让阿姨意识到了和平是多么重要→意识到的","example":"Parents should be aware of children’s health hazards. 父母应该意识到孩子们的健康隐患。","derivative":"awareness /əˈweənəs/ n.认识,意识"},{"id":2282,"word":"beware","pronunciation":"/bɪ'weə(r)/","meaning":"v.当心，注意，谨防","unit":8,"lesson":2,"seq":25,"isStar":false},{"id":2283,"word":"conscious","pronunciation":"/'kɒnʃəs/","meaning":"adj.意识到的，注意到的，清醒的","unit":8,"lesson":2,"seq":26,"isStar":false,"memo":"[谐音] 单词发音类似“靠心思”→靠(用)心思考就能意识到事物变化→意识到的","example":"We must be conscious of how technology is changing us. 我们要意识到技术正在如何改变我们。","derivative":"consciousness /ˈkɒnəsnəs/ n.神志清醒;意识"},{"id":2284,"word":"identify","pronunciation":"/aɪ'dentɪfaɪ/","meaning":"v.认出，识别，确定，表明身份","unit":8,"lesson":2,"seq":27,"isStar":false,"example":"Identify how your skills can apply to your desired occupation. 确定一下如何将你的技能应用于你期望的职业中。","derivative":"identification /aˌdentɪfɪˈkeɪʃn/ n.鉴定,识别;身份证明(文件)"},{"id":2285,"word":"identity","pronunciation":"/aɪ'dentɪtɪ/","meaning":"n.身份，特性，一致，相同","unit":8,"lesson":2,"seq":28,"isStar":false,"example":"He meant that we gain personal identity as we communicate with others. 他的意思是,我们在与他人交流的过程中获得个人身份。"},{"id":2286,"word":"identical","pronunciation":"/aɪ'dentɪkl/","meaning":"adj.完全相同的","unit":8,"lesson":2,"seq":29,"isStar":false,"memo":"[联想] ident(联想 identity) + -ical(形容词后缀)→完全相同的","example":"It is nearly identical to our own planet. 它与我们的地球几乎完全相同。"},{"id":2287,"word":"journal","pronunciation":"/'dʒɜːnl/","meaning":"n.期刊，日报，日记","unit":8,"lesson":2,"seq":30,"isStar":false,"memo":"谐音：单词发音类似“窝心”→这个“版本”的电视剧看得我很窝心。","example":"This journal is available in paper and electronic form. 这份期刊有印刷版本和电子版本。","derivative":"journalist /'dʒːnəlɪst/ n.新闻记者,新闻工作者"},{"id":2288,"word":"journalism","pronunciation":"/'dʒɜːnəlɪzəm/","meaning":"n.新闻业；新闻工作","unit":8,"lesson":2,"seq":31,"isStar":false,"memo":"构词：journal(期刊) + -ism(主义,思想) → 新闻业;新闻工作","example":"Science journalism is the main channel for the popularization of scientific information among the public. 科学新闻是向公众普及科学信息的主要渠道。"},{"id":2289,"word":"coverage","pronunciation":"/'kʌvərɪdʒ/","meaning":"n.新闻报道；覆盖范围","unit":8,"lesson":2,"seq":32,"isStar":false},{"id":2290,"word":"edit","pronunciation":"/'edɪt/","meaning":"n.编辑 v.编辑，校订","unit":8,"lesson":2,"seq":33,"isStar":false,"example":"I had time to do a quick edit of my essay before handing it in. 我呈交论文之前有点时间,很快地校订了一遍。","derivative":"editor /'edɪtə(r)/ n.主编;编辑\neditorial /ˌedɪ'tɔriəl/ adj.编辑的 n.(报刊的)社论\nedition /ɪ'dɪʃn/ n.版本"},{"id":2291,"word":"version","pronunciation":"/'vɜːʃn/","meaning":"n.样式，版本，说法","unit":8,"lesson":2,"seq":34,"isStar":false,"example":"I don't accept his version of events. 我不相信他对事件的说法。"},{"id":2292,"word":"novel","pronunciation":"/'nɒvl/","meaning":"adj.新颖的；与众不同的 n.(长篇)小说","unit":8,"lesson":2,"seq":35,"isStar":false,"memo":"对照：小说(novel)更新需要创新(innovation)。","example":"The always-on Internet devices raise some novel possibilities. 这种永远在线的互联网设备带来了一些新奇的可能性。","derivative":"novelty /'nvlti/ n.新奇,新颖\nnovelist /'nɒvəlɪst/ n.小说家"},{"id":2293,"word":"fiction","pronunciation":"/'fɪkʃn/","meaning":"n.小说；虚构的事","unit":8,"lesson":2,"seq":36,"isStar":false,"memo":"谐音：单词发音类似“飞可神”→科幻“小说”里的人物可以飞来飞去,可神奇了。","example":"I read everything from fiction to history. 我从小说到历史,什么书都读。","derivative":"fictional /'fɪkənl/ adj.虚构的;小说(中)的"},{"id":2294,"word":"episode","pronunciation":"/'epɪsəʊd/","meaning":"n.插曲，一段情节，一集","unit":8,"lesson":2,"seq":37,"isStar":false,"memo":"联想：epi(音似“爱陪”) + sode → 家人爱陪着他看“一集”连续剧。","example":"The pre-release images are a hint to the next episode. 预告片是下一集的一个线索。"},{"id":2295,"word":"literary","pronunciation":"/'lɪtərəri/","meaning":"adj.文学的；适于文学作品的","unit":8,"lesson":2,"seq":38,"isStar":false,"memo":"[构词] liter(文字,字母)+-ary(形容词后缀)→文学的","example":"It was Chaucer who really turned English into a literary language. 正是乔叟使英语真正地变成了一门文学语言。","derivative":"literature /'lɪtərətʃə/ n.文学,文学作品;文献\nliterate /'lɪtərət/ adj.有读写能力的;有文化的"},{"id":2296,"word":"literal","pronunciation":"/'lɪtərəl/","meaning":"adj.字面意义的；完全按原文的；缺乏想象力的","unit":8,"lesson":2,"seq":39,"isStar":false,"memo":"[谐音] 单词发音类似“李特弱”→李同学的英语基础特别弱,只能按字面意思翻译→字面意义的","example":"This idiom also has a literal meaning. 这个习语还有字面意思。","derivative":"literally /'ltərəli/ adv.字面上;确实地;简直"},{"id":2297,"word":"press","pronunciation":"/pres/","meaning":"n.出版社；印刷（机）；新闻界 v.压，挤，推；督促","unit":8,"lesson":2,"seq":40,"isStar":false,"example":"For two weeks they evaded the press. 他们两周以来一直对新闻媒体避而不见。","derivative":"pressure /'preʃə(r)/ n.压力;紧张;催促\npressing /'presɪŋ/ adj.紧急的,急迫的"},{"id":2298,"word":"oppress","pronunciation":"/ə'pres/","meaning":"v.压迫，压制；使烦恼，压抑","unit":8,"lesson":2,"seq":41,"isStar":false,"memo":"[构词] op-(表方向)+press(压)→朝着某个方向压某人或某物→压迫,压制","example":"The gloomy atmosphere in the office oppressed her. 办公室低沉的气氛使她感到压抑。","derivative":"oppression /ə'preʃn/ n.压迫;压制;镇压\noppressive /ə'presɪv/ adj.压迫的;压制的"},{"id":2299,"word":"impress","pronunciation":"/ɪm'pres/","meaning":"v.使钦佩，使敬仰；给……留下深刻印象","unit":8,"lesson":2,"seq":42,"isStar":false,"memo":"[构词] im-(入,里面)+press(压)→压进脑海去→给……留下深刻印象","example":"I was so impressed by how selfless she was. 她的无私给我留下了深刻的印象。","derivative":"impressive /ɪm'presɪv/ adj.给人深刻印象的\nimpression /ɪm'preʃn/ n.印象"},{"id":2300,"word":"repress","pronunciation":"/rɪ'pres/","meaning":"v.克制，抑制，压制，镇压","unit":8,"lesson":2,"seq":43,"isStar":false},{"id":2301,"word":"depress","pronunciation":"/dɪ'pres/","meaning":"v.使沮丧；使萧条；按下；降低","unit":8,"lesson":2,"seq":44,"isStar":false,"memo":"构词 de-(往下) + press(压)→使沮丧；降低","example":"High interest rates are continuing to depress the economy. 高利率正在继续抑制经济。","derivative":"depression /dɪ'preʃn/ n.沮丧；抑郁症；萧条期"},{"id":2302,"word":"suppress","pronunciation":"/sə'pres/","meaning":"v.镇压，压制；抑制","unit":8,"lesson":2,"seq":45,"isStar":false,"memo":"构词 sup-(=sub-,往下) + press(压)→镇压","example":"Men who suppress their emotions may develop stress-related disorders. 压抑自己情绪的人可能会发展出与压力有关的疾病。","derivative":"suppression /sə'preʃn/ n.镇压，压制，抑制\nsuppressive /sə'presɪv/ adj.抑制的；镇压的"},{"id":2303,"word":"distress","pronunciation":"/dɪ'stres/","meaning":"n.悲痛，痛苦；忧虑；困苦 v.使痛苦，使忧虑","unit":8,"lesson":2,"seq":46,"isStar":false,"memo":"联想 di-(两个) + stress(压力)→一种压力是压力，两种压力就会变成“痛苦”。","example":"To her distress, she found that her prayers did not calm her excitement. 令她痛苦的是，她发现她的祈祷并没有平复她的激动情绪。","derivative":"distressful /dɪ'stresfəl/ adj.苦恼的；不幸的"},{"id":2304,"word":"agony","pronunciation":"/'æɡəni/","meaning":"n.极大的痛苦；苦难","unit":8,"lesson":2,"seq":47,"isStar":false,"memo":"谐音 单词发音类似“爱割你”→把爱好割舍掉，对你来说是“极大的痛苦”。","example":"He was screaming in agony from the severe stomach pain. 他因剧烈的腹痛而痛苦地尖叫。"},{"id":2305,"word":"misery","pronunciation":"/'mɪzəri/","meaning":"n.痛苦；悲惨；穷困","unit":8,"lesson":2,"seq":48,"isStar":false,"memo":"联想 mis(联想 miss) + ery(联想 very)→非常想念一个人却见不到，一定很“痛苦”。","example":"Fame brought her nothing but misery. 名声只给她带来了痛苦。","derivative":"miserable /'mɪzərəbl/ adj.痛苦的；可怜的；令人不快的"},{"id":2306,"word":"withstand","pronunciation":"/wɪð'stænd/","meaning":"v.承受，经受住；抵挡","unit":8,"lesson":2,"seq":49,"isStar":false,"memo":"构词 with(反对) + stand(站)→经受住；抵挡","example":"The flooring needs to be tough enough to withstand wear. 地板要坚固耐磨。"},{"id":2307,"word":"notwithstanding","pronunciation":"/nɒtwɪθ'stændɪŋ/","meaning":"prep.尽管 adv. & conj.尽管如此","unit":8,"lesson":2,"seq":50,"isStar":false,"memo":"联想 not(没有) + withstand(经受住) + -ing(后缀)→“尽管”你没有取胜，但你经受住了考验。","example":"He was found guilty, notwithstanding that the evidence was very weak. 尽管证据很薄弱，他还是被判有罪。"},{"id":2308,"word":"withdraw","pronunciation":"/wɪð'droʊ/","meaning":"v.(使)退出；取消；撤回；提取(存款)","unit":8,"lesson":2,"seq":51,"isStar":false,"memo":"构词 with(向后) + draw(拉)→向后拉→撤回","example":"Many multinational enterprises are withdrawing from this country. 许多跨国企业正在从该国撤出。","derivative":"withdrawal /wɪð'drɔːl/ n.提款；撤走；收回"},{"id":2309,"word":"withhold","pronunciation":"/wɪð'həʊld/","meaning":"v.拒绝给；隐瞒；抑制","unit":8,"lesson":2,"seq":52,"isStar":false,"memo":"构词 with(向后) + hold(拿着)→拒绝给；抑制","example":"The government was threatening to withhold future financial aid. 政府在威胁停止未来的财政援助。"},{"id":2310,"word":"rim","pronunciation":"/rɪm/","meaning":"n.(圆形物的)边沿；眼镜框 v.环绕……的边缘","unit":8,"lesson":3,"seq":1,"isStar":false,"memo":"对照 戒指(ring)放在盘子边沿(rim)。","example":"He looked at them over the rim of his glass. 他从杯子的边沿看着他们。"},{"id":2311,"word":"grim","pronunciation":"/ɡrɪm/","meaning":"adj.严肃的；令人沮丧的","unit":8,"lesson":3,"seq":2,"isStar":false,"memo":"联想 g(联想“哥”) + rim(边沿)→在边沿(疆)的哥哥守卫国家,是很“严肃的”。","example":"She looked grim. 她表情严肃。"},{"id":2312,"word":"trim","pronunciation":"/trɪm/","meaning":"adj.整齐的；苗条的 v.修剪；修饰 n.修剪；饰物","unit":8,"lesson":3,"seq":3,"isStar":false,"memo":"联想 t(联想 take) + rim(边沿)→拿掉纸张边沿,就是把参差不齐的部分“修剪”整齐。","example":"I trimmed two centimetres off the skirt. 我把裙子剪短了两厘米。"},{"id":2313,"word":"mow","pronunciation":"/moʊ/","meaning":"v.割；修剪","unit":8,"lesson":3,"seq":4,"isStar":false},{"id":2314,"word":"clip","pronunciation":"/klɪp/","meaning":"n.夹子；回形针；片段；修剪 v.夹住；修剪；碰撞","unit":8,"lesson":3,"seq":5,"isStar":false,"memo":"联想 c(形似夹子) + lip(嘴唇)→他的嘴唇被“夹子”给“夹住”了。","example":"He fastened the papers together with a paper clip. 他用回形针把文件固定在一起。"},{"id":2315,"word":"chop","pronunciation":"/tʃɒp/","meaning":"v.切碎；砍；劈；削减；取消 n.猪(或羊等)排；砍；劈","unit":8,"lesson":3,"seq":6,"isStar":false,"memo":"谐音 单词发音类似“敲破”→买的大骨头要使劲“砍”,用力敲破。","example":"He was chopping logs for firewood. 他在把原木劈成柴火。"},{"id":2316,"word":"boundary","pronunciation":"/'baʊndri/","meaning":"n.边界；分界线；界限","unit":8,"lesson":3,"seq":7,"isStar":false,"memo":"联想 bound(音似“邦德”) + -ary(名词后缀)→电影《007》里的詹姆斯·邦德是很有“边界”感的人。","example":"The river is the boundary between the two countries. 这条河是两国的分界线。"},{"id":2317,"word":"margin","pronunciation":"/'mɑːdʒɪn/","meaning":"n.页边空白；利润；差额；余地","unit":8,"lesson":3,"seq":8,"isStar":false,"memo":"谐音 单词发音类似“码近”→临近页码的地方就是“页边空白”。","example":"Margins are low and many companies are struggling. 利润很少,很多公司在苦苦挣扎。"},{"id":2318,"word":"edge","pronunciation":"/edʒ/","meaning":"n.边缘；刀刃；(微弱的)优势","unit":8,"lesson":3,"seq":9,"isStar":false,"memo":"单词发音类似“挨挤”→大海“边缘”有很多人都挨着挤在一起。","example":"It is going to lose its competitive edge in higher education. 它将在高等教育中失去其竞争优势。"},{"id":2319,"word":"verge","pronunciation":"/vɜːdʒ/","meaning":"n.路缘；濒于 v.接近；濒于","unit":8,"lesson":3,"seq":10,"isStar":false,"memo":"单词发音类似“我急”→“接近”迟到时，我很着急。","example":"They were on the verge of breaking up. 他们处于分手的边缘。"},{"id":2320,"word":"average","pronunciation":"/'ævərɪdʒ/","meaning":"n.平均水平；平均数 adj.平均(数)的；平常的\tv.平均为","unit":8,"lesson":3,"seq":11,"isStar":false,"example":"The average temperature in summer here is very high. 这里夏天的平均气温很高。"},{"id":2321,"word":"bound","pronunciation":"/'baʊnd/","meaning":"n.界限，限度；跳跃\tadj.肯定的；有责任的\tv.跳跃着跑；以某物为界","unit":8,"lesson":3,"seq":12,"isStar":false,"memo":"单词发音类似“蹦跶”→你可以在我忙的时候到处蹦跶，但是不能超过我容忍的“限度”。","example":"There are no bounds to his ambition. 他的野心没有止境。"},{"id":2322,"word":"prejudice","pronunciation":"/'predʒədis/","meaning":"n.偏见，成见，歧视\tv.使有偏见；损害","unit":8,"lesson":3,"seq":13,"isStar":false,"memo":"pre-(预先) + judi(联想 Judy，人名) + ce → 这个人在见到朱迪之前，就对她存有“偏见”。","example":"Their decision was based on ignorance and prejudice. 他们的决定是基于无知和偏见。"},{"id":2323,"word":"bias","pronunciation":"/'baɪəs/","meaning":"n.偏心，偏见，偏爱\tv.使有偏见","unit":8,"lesson":3,"seq":14,"isStar":false,"memo":"bi-(两个) + as(音似“儿子”) → 他有两个儿子，从不“偏心”。","example":"The article examines gender bias in our schools. 这篇文章调查了我们学校的性别偏见。"},{"id":2324,"word":"ambiguous","pronunciation":"/æm'bigjuəs/","meaning":"adj.模棱两可的，不明确的","unit":8,"lesson":3,"seq":15,"isStar":false,"memo":"am(是) + bi-(两个) + gu(联想“姑”) + -ous(形容词后缀) → 这是两个姑姑的东西，但究竟归谁仍是“模棱两可的”。","example":"You need to rewrite this sentence because it is ambiguous. 你需要重写一下这个句子，因为它不明确。","derivative":"ambiguity /ˌæmbɪ'ɡjuːəti/ n.模棱两可，不明确"},{"id":2325,"word":"equity","pronunciation":"/'ekwəti/","meaning":"n.公平，公正；股票；资产净值","unit":8,"lesson":3,"seq":16,"isStar":false},{"id":2326,"word":"equate","pronunciation":"/'ɪ'kweɪt/","meaning":"v.等同","unit":8,"lesson":3,"seq":17,"isStar":false},{"id":2327,"word":"adequate","pronunciation":"/'ædɪkwət/","meaning":"adj.足够的，充分的；合乎需要的","unit":8,"lesson":3,"seq":18,"isStar":false,"memo":"联想 ad-(一再地) + equate(等同)→如果一个人的英语水平一再地等同于老师的水平,那么他很可能拥有“足够的”英语知识储备。","example":"It is under adequate control. 它得到了充分的控制。"},{"id":2328,"word":"equivalent","pronunciation":"/'ɪ'kwɪvələnt/","meaning":"adj.等值的；等同的 n.等同物；等价物","unit":8,"lesson":3,"seq":19,"isStar":false,"memo":"构词 equi (= equal) + val (ue) (价值) + -ent(后缀)→具有相等的价值→等值的","example":"I'll be getting the equivalent of about 22,000 pounds a year there. 我将在那里获得的年薪相当于2.2万英镑。"},{"id":2329,"word":"equation","pronunciation":"/'ɪ'kweɪʒn/","meaning":"n.方程式，等式；相等","unit":8,"lesson":3,"seq":20,"isStar":false,"memo":"构词 equa(= equal) + -tion(名词后缀)→相等→等式","example":"The other side of that equation is that the US needs to save more. 等式的另一边则是美国需要增加储蓄。"},{"id":2330,"word":"arrogant","pronunciation":"/'ærəɡənt/","meaning":"adj.傲慢的，自大的","unit":8,"lesson":3,"seq":21,"isStar":false},{"id":2331,"word":"eloquent","pronunciation":"/'eləkwənt/","meaning":"adj.雄辩的，能言善辩的","unit":8,"lesson":3,"seq":22,"isStar":false,"memo":"谐音 单词发音类似“爱唠嗑的”→爱唠嗑的人一般都很能说→雄辩的","example":"They are smart and eloquent. 他们聪明、能言善辩。","derivative":"eloquence /ˈeləkwəns/ n.雄辩;口才"},{"id":2332,"word":"hostile","pronunciation":"/'hɒstail/","meaning":"adj.敌意的，敌视的","unit":8,"lesson":3,"seq":23,"isStar":false,"example":"The boy feels hostile towards his father. 那个男孩对父亲怀有敌意。","derivative":"hostility /hˈstɪləti/ n.敌意,对抗"},{"id":2333,"word":"anxious","pronunciation":"/'æŋkʃəs/","meaning":"adj.焦虑的；渴望的","unit":8,"lesson":3,"seq":24,"isStar":false,"example":"Many of us are weighed down by the past or anxious about the future. 我们中的许多人都被过去压得喘不过气来,或者对未来感到焦虑。","derivative":"anxiety /æŋˈzaɪəti/ n.忧虑,担忧;渴望"},{"id":2334,"word":"dreadful","pronunciation":"/'dredfl/","meaning":"adj.可怕的，令人畏惧的","unit":8,"lesson":3,"seq":25,"isStar":false},{"id":2335,"word":"dread","pronunciation":"/dred/","meaning":"v.非常害怕；极为担心 n.恐惧 adj.可怕的","unit":8,"lesson":3,"seq":26,"isStar":false,"example":"She has an irrational dread of hospitals. 她对医院有莫名的恐惧。"},{"id":2336,"word":"shrewd","pronunciation":"/ʃruːd/","meaning":"adj.善于判断的；敏锐的，精明的","unit":8,"lesson":3,"seq":27,"isStar":false,"memo":"谐音 单词发音类似“洗褥的”→这个洗褥子的人是很“精明的”,他知道怎么洗省时省力。","example":"It was a shrewd move to buy your house just before property prices started to rise. 你正好在房价开始上涨之前买房子,真是精明之举。"},{"id":2337,"word":"critic","pronunciation":"/'kritis/","meaning":"n.批评家，评论家","unit":8,"lesson":3,"seq":28,"isStar":false,"example":"He was knighted in 1967, the first music critic to be so honored. 他于1967年被授予爵士头衔,是第一位获得如此殊荣的音乐评论家。"},{"id":2338,"word":"criterion","pronunciation":"/kraɪ'tɪəriən/","meaning":"n.(批评判断的)标准，准则","unit":8,"lesson":3,"seq":29,"isStar":false,"memo":"联想 crit(联想 criticise) + er(联想“表示人的后缀”) +-ion(名词后缀)→批评别人时需要参照特定的“标准”。","example":"Practice is the sole criterion for testing truth. 实践是检验真理的唯一标准。"},{"id":2339,"word":"confident","pronunciation":"/'kɒnfidənt/","meaning":"adj.自信的；有把握的","unit":8,"lesson":3,"seq":30,"isStar":false,"example":"They will feel more confident in competing with their rivals. 他们在与对手竞争时会感到更有自信。","derivative":"confidence /ˈkɒnfɪdəns/ n.信心,自信"},{"id":2340,"word":"cynical","pronunciation":"/'sɪnɪkl/","meaning":"adj.愤世嫉俗的；悲观的；怀疑的","unit":8,"lesson":3,"seq":31,"isStar":false,"memo":"对照 有些人看待问题是悲观的(cynical),认为生活就是简单的循环(cycle),悲剧不断上演。","example":"I've always been cynical about politicians. 我对政客们总是持怀疑态度。","derivative":"cynicism /ˈsɪnɪsɪzəm/ n.愤世嫉俗;犬儒主义"},{"id":2341,"word":"confidential","pronunciation":"/ˌkɒnfɪ'denʃl/","meaning":"adj.机密的，保密的；神秘的，隐秘的","unit":8,"lesson":3,"seq":32,"isStar":false,"memo":"联想 confident(自信的)+-ial(形容词后缀)→枪打出头鸟,即使自信,也要隐秘一些→隐秘的","example":"Companies need to impose restrictions on confidential information. 公司需要对机密信息施加限制。"},{"id":2342,"word":"courageous","pronunciation":"/kə'reɪdʒəs/","meaning":"adj.勇敢的，有胆量的","unit":8,"lesson":3,"seq":33,"isStar":false},{"id":2343,"word":"encourage","pronunciation":"/ɪn'kʌrɪdʒ/","meaning":"v.支持；鼓励，激励","unit":8,"lesson":3,"seq":34,"isStar":false,"memo":"构词 en-(使) + courage(勇气) → 使有勇气 → 鼓励","example":"She encouraged many young writers and artists. 她鼓励了许多年轻的作家和艺术家。","derivative":"encouragement /ɪnkʌrɪdmənt/ n.鼓舞，鼓励\nencouraging /ɪnkʌrɪdɪŋ/ adj.鼓励的，激励的"},{"id":2344,"word":"discourage","pronunciation":"/dis'kʌrɪdʒ/","meaning":"v.使气馁，使灰心；阻止","unit":8,"lesson":3,"seq":35,"isStar":false,"memo":"构词 dis-(否定前缀) + courage(勇气) → 使没有勇气 → 使气馁","example":"His parents tried to discourage him from being a singer. 他的父母试图阻止他去当歌星。","derivative":"discouraged /dsˈkʌrdʒd/ adj.气馁的，灰心的"},{"id":2345,"word":"coward","pronunciation":"/'kauəd/","meaning":"n.懦夫，胆怯者","unit":8,"lesson":3,"seq":36,"isStar":false,"memo":"谐音 单词发音类似“靠我的”→他是个“懦夫”，遇到事情只能靠我。","example":"My husband is really a coward. 我的丈夫真是一个懦夫。","derivative":"cowardly /ˈkaʊərdli/ adj.胆小的\ncowardice /ˈkaʊərdɪs/ n.胆小，懦弱"},{"id":2346,"word":"timid","pronunciation":"/'tɪmɪd/","meaning":"adj.胆小的，羞怯的","unit":8,"lesson":3,"seq":37,"isStar":false,"memo":"联想 ti(联想“提”) + mi(联想 me) + d(联想“的”) → 他是个“胆小的人”，不敢提到我。","example":"Deer are naturally timid creatures. 鹿是生性胆小的动物。"},{"id":2347,"word":"intimidate","pronunciation":"/ɪnˈtɪmɪdeɪt/","meaning":"v.恐吓；威胁；使害怕，使失去信心","unit":8,"lesson":3,"seq":38,"isStar":false,"example":"They tried to intimidate the young people into voting for them. 他们试图胁迫年轻人投票给他们。","derivative":"intimidation /ɪnˌtɪmɪˈdeɪʃn/ n.威胁；恐吓"},{"id":2348,"word":"threat","pronunciation":"/θret/","meaning":"n.威胁，恐吓；凶兆","unit":8,"lesson":3,"seq":39,"isStar":false,"example":"Drugs pose a major threat to our society. 毒品对社会构成重大威胁。","derivative":"threaten /ˈθretn/ v.恐吓；预示凶兆；危及"},{"id":2349,"word":"elegant","pronunciation":"/ˈelɪɡənt/","meaning":"adj.优美的，高雅的；巧妙的","unit":8,"lesson":3,"seq":40,"isStar":false,"memo":"联想 e-(出)+leg(腿)+ant(蚂蚁)→蚂蚁露出大腿,动作非常优雅→优美的,高雅的","example":"A child may grow up elegant due to his/her name. 一个孩子可能会因为他/她的名字而优雅地成长。","derivative":"elegance /'elɪɡəns/ n.优雅,雅致"},{"id":2350,"word":"grace","pronunciation":"/ɡreɪs/","meaning":"n.优雅，体面；宽限期；恩宠 v.为……增色，美化","unit":8,"lesson":3,"seq":41,"isStar":false,"memo":"联想 g(联想“哥”)+race(比赛)→哥哥比赛时的动作真“优雅”。","example":"It is wise to take such gifts with gratitude and grace. 心怀感激地大方接受这些礼物才是明智的。","derivative":"graceful /'ɡresfʊl/ adj.优美的;得体的\ngracious /'ɡreɪʃəs/ adj.和蔼的,慈祥的,有礼貌的"},{"id":2351,"word":"luxury","pronunciation":"/ˈlʌkʃəri/","meaning":"n.奢华，奢侈；奢侈品","unit":8,"lesson":3,"seq":42,"isStar":false,"memo":"对照 汽车品牌雷克萨斯(Lexus)以奢华(luxury)为特点。","example":"Some critics say it is a luxury and shouldn't be free to families able to pay. 一些批评人士说,这是一种奢侈品,对有支付能力的家庭不应免费。"},{"id":2352,"word":"extravagant","pronunciation":"/ɪkˈstrævəɡənt/","meaning":"adj.奢侈的；挥霍的；过度的","unit":8,"lesson":3,"seq":43,"isStar":false,"memo":"联想 ex-(往外)+trav(联想 travel)+agan(联想 again)+t(联想“他”)→他外出旅游,去了一次又一次,是很“奢侈的”。","example":"I could not have imagined how fabulous and extravagant a real Chinese banquet could be. 我没想到一场真正的中式宴会能如此的美妙和奢华。","derivative":"extravagance /ɪk'strævəɡəns/ n.奢侈;挥霍,铺张浪费"},{"id":2353,"word":"reliable","pronunciation":"/rɪˈlaɪəbl/","meaning":"adj.可靠的，可信赖的","unit":8,"lesson":3,"seq":44,"isStar":false,"memo":"构词 reli(=rely,依靠)+-able(形容词后缀)→可靠的","example":"We are looking for someone who is reliable and hard-working. 我们在物色可靠而又勤奋的人。","derivative":"reliance /rɪ'laɪəns/ n.依靠,依赖"},{"id":2354,"word":"liable","pronunciation":"/ˈlaɪəbl/","meaning":"adj.可能（易于）……的；负有偿付责任的","unit":8,"lesson":3,"seq":45,"isStar":false,"memo":"联想 li(音似 lie,躺)+able(音似“饿饱”)→我半夜饿了时,继续躺一会儿可能就不饿了→可能……的","example":"Being a human creation, technology is liable to"},{"id":2355,"word":"credible","pronunciation":"/ˈkredəbl/","meaning":"adj.可信的，可靠的","unit":8,"lesson":3,"seq":46,"isStar":false,"memo":"cred(联想 credit,相信)+-ible(形容词后缀)→可信的,可靠的","example":"The results are hardly credible.这些结果几乎不可信。","derivative":"credibility /ˌkredəˈbɪləti/ n.可信性,可靠性\nincredible /ɪnˈkredəbl/ adj.难以置信的;极好的;极大的"},{"id":2356,"word":"skeptical","pronunciation":"/sceptical/","meaning":"ˈskeptɪkl/ adj.表示怀疑的；不相信的","unit":8,"lesson":3,"seq":47,"isStar":false},{"id":2357,"word":"dubious","pronunciation":"/'djuːbiəs/","meaning":"adj.怀疑的；无把握的；拿不准的；可疑的\t\t\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]","unit":8,"lesson":3,"seq":48,"isStar":false,"memo":"dubi(联想“独臂”)+-ous(形容词后缀)→失去一条手臂的他对未来充满怀疑→怀疑的","example":"I was rather dubious about the whole idea.我对这整个想法持怀疑态度。"},{"id":2358,"word":"decide","pronunciation":"/dɪ'saɪd/","meaning":"v.决定；选定\t\t\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]","unit":8,"lesson":3,"seq":49,"isStar":false,"example":"It's up to you to decide.这事由你来决定吧。","derivative":"decisive /dɪˈsasɪv/ adj.决定性的,关键的;果断的\ndecision /dɪˈsʒn/ n.决定;果断"},{"id":2359,"word":"vain","pronunciation":"/veɪn/","meaning":"adj.徒劳的；自负的\t\t\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]","unit":8,"lesson":3,"seq":50,"isStar":false,"memo":"单词发音类似“问”→问他也是白问,都是“徒劳的”。","example":"I knocked loudly in the vain hope that someone might answer.我大声敲门,徒劳地希望有人应答。","derivative":"vanity /ˈvænəti/ n.自负;虚荣"},{"id":2360,"word":"vicious","pronunciation":"/'vɪʃəs/","meaning":"adj.凶险的；恶毒的；恶劣的\t\t\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]","unit":8,"lesson":3,"seq":51,"isStar":false,"memo":"vic(e)(恶行)+-ious(形容词后缀)→凶险的;恶毒的","example":"Quotas will break this vicious cycle by putting lots of women at the top.定额制将通过把许多女性放到高层来打破这一恶性循环。"},{"id":2361,"word":"coarse","pronunciation":"/koʊs/","meaning":"adj.粗糙的；大颗粒的；粗鲁无礼的\t\t\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]","unit":8,"lesson":3,"seq":52,"isStar":false,"memo":"单词发音类似“烤死”→烈日快把人烤死了,皮肤也因此变得粗糙→粗糙的","example":"Her coarse hands are the result of years of hard work.她粗糙的双手是常年艰辛劳作的结果。"},{"id":2362,"word":"slip","pronunciation":"/slɪp/","meaning":"v.滑（倒）；溜走；下降 n.滑倒；差错；疏漏；纸条\t\t\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]","unit":8,"lesson":3,"seq":53,"isStar":false,"derivative":"n.滑倒;差错,疏漏;纸条"},{"id":2363,"word":"rough","pronunciation":"/rʌf/","meaning":"adj.粗糙的，粗略的；粗野的；艰难的\t\t\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]","unit":8,"lesson":3,"seq":54,"isStar":false,"example":"By rough computation, he estimated that the repairs on the house would cost him a thousand dollars. 粗略计算之后,他估计修缮这座房子会花掉他一千美元。","derivative":"roughly /'rʌfli/ adv.大约,大致"},{"id":2364,"word":"tough","pronunciation":"/tʌf/","meaning":"adj.坚强的；艰苦的；艰难的；严厉的；强硬的\t\t\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]","unit":8,"lesson":3,"seq":55,"isStar":false,"memo":"谐音 单词发音类似“他服”→“坚强的”他勇于直面困难,令人佩服。","example":"Sometimes it is easy to feel bad because you are going through tough times. 有时你很容易感到难过,因为你正在经历艰难的时刻。"},{"id":2365,"word":"ordeal","pronunciation":"/'ɔːdɪl, 'oːdɪl/","meaning":"n.磨难，折磨；煎熬\t\t\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]","unit":8,"lesson":3,"seq":56,"isStar":false},{"id":2366,"word":"ridiculous","pronunciation":"/rɪ'dɪkjələs/","meaning":"adj.可笑的；荒谬的\t\t\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]\t[不清]","unit":8,"lesson":3,"seq":57,"isStar":false,"memo":"谐音 单词发音类似“瑞迪可乐死”→瑞迪一说话,可乐死我了→可笑的","example":"I look ridiculous in this hat. 我戴这顶帽子看上去很可笑。"},{"id":2367,"word":"restless","pronunciation":"/'restləs/","meaning":"adj.坐立不安的；待不住的；不耐烦的\t\t\t[不清]\t[不清]\t[不清]\t[","unit":8,"lesson":3,"seq":58,"isStar":false,"memo":"构词 rest(休息;静止) + -less(无;没有) → 没有休息;不静止→坐立不安的,待不住的;不耐烦的","example":"The audience was becoming restless. 观众开始不耐烦了。"},{"id":2368,"word":"radiate","pronunciation":"/'reɪdɪeɪt/","meaning":"v.(使热、光、能量)辐射，放射；散发","unit":8,"lesson":4,"seq":1,"isStar":false,"memo":"[对照] 雷达(radar)工作的时候会放射(radiate)电磁波。","example":"The metal plate behind my head radiated heat. 我脑后的金属盘散发出热量。"},{"id":2369,"word":"radiant","pronunciation":"/'reɪdɪənt/","meaning":"adj.喜气洋洋的，容光焕发的；灿烂的；辐射的","unit":8,"lesson":4,"seq":2,"isStar":false,"example":"On her wedding day the bride looked truly radiant. 在她婚礼那天,新娘看起来真的是容光焕发。"},{"id":2370,"word":"radioactive","pronunciation":"/ˌreɪdɪəʊ'æktɪv/","meaning":"adj.放射性的，有辐射的","unit":8,"lesson":4,"seq":3,"isStar":false,"example":"The nuclear waste is highly radioactive. 这些核废料具有高度放射性。","derivative":"radioactivity /ˌreɪdiəʊæk'tɪvəti/ n.放射性"},{"id":2371,"word":"silicon","pronunciation":"/'sɪlɪkən/","meaning":"n.硅","unit":8,"lesson":4,"seq":4,"isStar":false,"example":"The new kind of intelligent life is more likely to be made of silicon. 这种新型智能生命更有可能是由硅制成的。"},{"id":2372,"word":"spark","pronunciation":"/spɑːk/","meaning":"n.火花，火星；一丁点\tv.引发，触发","unit":8,"lesson":4,"seq":5,"isStar":false,"memo":"[联想] s(音似“嘶”)+park(公园)→有人在公园里放烟花,“火花”发出嘶嘶声。","example":"This spark is the strength of conviction. 这个火花就是信念的力量。"},{"id":2373,"word":"sparkle","pronunciation":"/'spɑːkl/","meaning":"n.闪烁的光；亮点\tv.闪烁；生气勃勃","unit":8,"lesson":4,"seq":6,"isStar":false,"memo":"[谐音] 单词发音类似“四百颗”→四百颗星星在“闪烁”。","example":"There was a sparkle of excitement in her eyes. 她眼里闪烁着激动的光芒。"},{"id":2374,"word":"gleam","pronunciation":"/glɪːm/","meaning":"n.微光；少量 v.发微光，闪烁；流露出","unit":8,"lesson":4,"seq":7,"isStar":false,"memo":"[联想] glea(音似“隔离”)+m(联想“门”)→我路过隔离门的时候,发现门缝中透出一点儿“微光”。","example":"A few gleams of sunshine lit up the gloomy afternoon. 几缕阳光使阴暗的下午明亮起来。"},{"id":2375,"word":"polish","pronunciation":"/'pɒlɪʃ/","meaning":"n.亮光剂；擦亮，磨光 v.擦亮，抛光，修改，润色","unit":8,"lesson":4,"seq":8,"isStar":false,"memo":"[联想] pol(音似“抛”)+-ish(后缀)→抛光就是“擦亮”。","example":"I give it a polish yesterday. 昨天我把它抛光了。"},{"id":2376,"word":"enlighten","pronunciation":"/ɪn'laɪtn/","meaning":"v.启发，开导；阐明","unit":8,"lesson":4,"seq":9,"isStar":false,"memo":"[构词] en-(使) + light(光) + -en(动词后缀)→使有光→启发，开导","example":"It was an elite that believed its task was to enlighten the multitude. 精英人物都会认为自己的职责就是启迪民众。","derivative":"enlightenment /ɪnˈlatnmənt/ n.启迪，启发；开导\nenlightening /ɪnˈlaɪtnɪŋ/ adj.有启迪的，使人感悟的"},{"id":2377,"word":"delight","pronunciation":"/dɪ'laɪt/","meaning":"n.高兴\tv.(使)高兴；使愉快","unit":8,"lesson":4,"seq":10,"isStar":false,"memo":"[联想] de(音似“弟”) + light(光)→弟弟在黑暗中突然看到一束光，非常“高兴”。","example":"He looked up at his father, his features overflowing with energy and delight. 他抬头看着父亲，脸上洋溢着活力和喜悦。","derivative":"delightful /dɪlaɪtfʊl/ adj.使人快乐的，令人愉快的；宜人的"},{"id":2378,"word":"plight","pronunciation":"/plaɪt/","meaning":"n.苦难，困境","unit":8,"lesson":4,"seq":11,"isStar":false},{"id":2379,"word":"dilemma","pronunciation":"/dɪ'lemə/","meaning":"n.(进退两难的)窘境，困境","unit":8,"lesson":4,"seq":12,"isStar":false,"memo":"[谐音] 单词发音类似“弟来吗”→弟弟也不知道来不来→(进退两难的)窘境","example":"I could see no way of resolving this moral dilemma. 我想不出解决这一道德困境的办法。"},{"id":2380,"word":"trap","pronunciation":"/træp/","meaning":"v.使陷入困境 n.陷阱，圈套；诡计；困境","unit":8,"lesson":4,"seq":13,"isStar":false,"memo":"[谐音] 单词发音类似“踹扑”→他被人踹了一脚，扑到“陷阱”里了。\n[对照] 他们去山区旅行(trip)，结果因为大雪陷入困境(trap)之中了。","example":"We became trapped by the rising floodwater. 我们被上涨的洪水困住了。"},{"id":2381,"word":"strap","pronunciation":"/stræp/","meaning":"n.带子\tv.用带子系(或捆、扎、扣)好","unit":8,"lesson":4,"seq":14,"isStar":false,"memo":"[联想] s(联想“美女”) + trap(陷阱)→一个美女不慎落入陷阱，被人用“带子”救上来了。","example":"The bag comes with removable straps. 这种包有可拆卸的带子。"},{"id":2382,"word":"strop","pronunciation":"/strɪp/","meaning":"v.脱去衣服；除去，剥去 n.(纸、金属、织物等)条，带","unit":8,"lesson":4,"seq":15,"isStar":false},{"id":2383,"word":"stripe","pronunciation":"/strai̯p/","meaning":"n.条纹；线条","unit":8,"lesson":4,"seq":16,"isStar":false,"memo":"[联想] st(联想 street) + rip(撕扯) + e(字母音似“衣”)→她在大街上撕扯一件“条纹”衣服。","example":"The butterfly is black and white with a blue stripe running down each wing. 这蝴蝶黑白相间，每只翅膀纵贯着一道蓝色条纹。"},{"id":2384,"word":"ignite","pronunciation":"/'aɪɡˈnaɪt/","meaning":"v.点燃，（使）燃烧，着火","unit":8,"lesson":4,"seq":17,"isStar":false,"memo":"[联想] ig(音似“一个”) + nite(联想 night)→在一个没有电的夜晚，我“点燃”了一根蜡烛。","example":"The fuel of the continental missile is supposed to be ignited by this device. 这枚洲际导弹的燃料应该由这个装置点燃。"},{"id":2385,"word":"illuminate","pronunciation":"/ɪˈluːmɪneɪt/","meaning":"v.照明，照亮；阐明，解释","unit":8,"lesson":4,"seq":18,"isStar":false,"memo":"谐音 单词发音类似“一路明你的”→如果你的前方一路都是明亮的,说明有人在默默地给你“照亮”前路。","example":"The Earth is illuminated by the sun. 太阳照亮地球。","derivative":"illumination /ɪˌluːmˈneɪʃn/ n.启示;阐明;照明"},{"id":2386,"word":"illusion","pronunciation":"/ɪˈluːʒn/","meaning":"n.幻想，错觉","unit":8,"lesson":4,"seq":19,"isStar":false,"memo":"谐音 单词发音类似“一路引”→想要人生一直有人引路,只能是“幻想”。","example":"Mirrors in a room often give an illusion of space. 房间里的镜子经常给人一种空间增大的错觉。","derivative":"illusory /ɪˈluːsəri/ adj.虚假的,幻觉的"},{"id":2387,"word":"fantasy","pronunciation":"/ˈfæntəsi/","meaning":"n.幻想，想象","unit":8,"lesson":4,"seq":20,"isStar":false,"memo":"谐音 单词发音类似“范特西”→范特西是一个爱“幻想”的人。","example":"Children use fantasy to explore worrying aspects of real life. 孩子们用幻想来探索实际生活中令人不安的各种事情。"},{"id":2388,"word":"fantastic","pronunciation":"/fænˈtæstɪk/","meaning":"adj.极好的，了不起的；不切实际的","unit":8,"lesson":4,"seq":21,"isStar":false,"example":"This was a fantastic opportunity for students. 这对学生来说是一个极好的机会。"},{"id":2389,"word":"fancy","pronunciation":"/ˈfænsi/","meaning":"v.认为，想象，想要；自负 adj.异常复杂的；精致的 n.想象（力）；爱好","unit":8,"lesson":4,"seq":22,"isStar":false,"memo":"谐音 单词发音类似“烦死”→一个人在很烦的时候可以“想象”一些美好的场景。","example":"Do you fancy going out this evening? 今晚你想不想出去?","derivative":"adj.异常复杂的;精致的;绚丽的 n.想象(力);爱好"},{"id":2390,"word":"consider","pronunciation":"/kənˈsɪdə(r)/","meaning":"v.仔细考虑；认为","unit":8,"lesson":4,"seq":23,"isStar":false,"example":"I did briefly consider going on my own. 我确实短暂考虑过自己去。","derivative":"considering /kənˈsɪdərɪŋ/ prep. & conj.考虑到;就……而言;鉴于\nconsideration /kənˌsɪdəˈreɪʃn/ n.仔细考虑"},{"id":2391,"word":"considerate","pronunciation":"/kənˈsɪdərət/","meaning":"adj.体贴的，体谅的，考虑周到的","unit":8,"lesson":4,"seq":24,"isStar":false,"memo":"联想 consider(考虑) + ate(eat 的过去式)→连吃都考虑到了→考虑周到的","example":"She is always polite and considerate towards her employees. 她对待雇员总是客客气气,关心体谅。"},{"id":2392,"word":"considerable","pronunciation":"/kənˈsɪdərəbl/","meaning":"adj.相当大（或多、重要等）的","unit":8,"lesson":4,"seq":25,"isStar":false,"memo":"联想 consider(考虑) + able(能够)→当回报足够多时,条件也是能够考虑的→相当大(或多、重要等)的","example":"Growing grass require considerable amounts of water. 牧草生长需要大量的水。"},{"id":2393,"word":"negotiate","pronunciation":"/nɪˈɡəʊʃieɪt/","meaning":"v.谈判，协商；达成（协议）","unit":8,"lesson":4,"seq":26,"isStar":false,"memo":"ne(音似“你”) + go(去) + ti(联想“提”) + ate(eat的过去式) → 如果你想就吃什么提建议，需要跟食堂负责人“谈判”。","example":"It is easier to negotiate initial salary requirement. 协商初始的工资要求更容易。","derivative":"negotiable /nɪˈɡəʊʃiəbl/ adj.可协商的，可讨论的；negotiation /nɪˌɡəʊʃiˈeʃn/ n.谈判，磋商，协商"},{"id":2394,"word":"hesitate","pronunciation":"/ˈhezɪteɪt/","meaning":"v.犹豫；顾虑，疑虑","unit":8,"lesson":4,"seq":27,"isStar":false,"memo":"he(他) + sit(坐) + ate(eat的过去式) → 他坐在餐桌旁，“犹豫”要不要吃点东西。","example":"He was still hesitating over whether to leave or not. 他还在犹豫要不要离开。","derivative":"hesitation /ˌhezɪteɪʃn/ n.犹豫，迟疑不决；hesitant /ˈhezɪtənt/ adj.犹豫的，踌躇的"},{"id":2395,"word":"tentative","pronunciation":"/ˈtentətɪv/","meaning":"adj.试探性的；犹豫不决的，不确定的；暂定的","unit":8,"lesson":4,"seq":28,"isStar":false,"memo":"tent(帐篷) + (t)a(联想“他”) + ti(联想“踢”) + ve(音似“我”) → 我和同学露营时住在帐篷里，晚上他踢我，试探我睡着了没有 → 试探性的","example":"We made a tentative arrangement to meet on Friday. 我们暂定星期五见面。"},{"id":2396,"word":"raw","pronunciation":"/rɔː/","meaning":"adj.生的，未烹制的；原始的；不熟练的","unit":8,"lesson":4,"seq":29,"isStar":false,"memo":"单词发音类似“肉”→肉在最开始都是“生的”。","example":"These fish are often eaten raw. 这些鱼常常被生吃。"},{"id":2397,"word":"crude","pronunciation":"/kruːd/","meaning":"adj.粗略的；粗鲁的；粗俗的；天然的","unit":8,"lesson":4,"seq":30,"isStar":false,"memo":"单词发音类似“可辱德”→他“粗鲁的”行为可真是有辱品德。","example":"Crude oil is the world’s most important commodity. 原油是世界上最重要的商品。"},{"id":2398,"word":"virgin","pronunciation":"/'vɜːdʒɪn/","meaning":"n.处女；童男；新手 adj.未开发的，原始状态的；贞洁的","unit":8,"lesson":4,"seq":31,"isStar":false,"memo":"单词发音类似“我进”→我进入了一个“未开发的”原始森林。","example":"This is a virgin forest. 这是一片原始森林。","derivative":"virginity /vɜːˈdʒɪnəti/ n.处女状态；童贞；原始状态"},{"id":2399,"word":"desire","pronunciation":"/dɪ'zaɪə(r)/","meaning":"n.愿望；欲望；渴望 v.渴望，期望","unit":8,"lesson":4,"seq":32,"isStar":false,"memo":"de(音似“弟”) + sir(先生) + e(联想“鹅”) → 弟弟“渴望”先生讲鹅的故事。","example":"The flower scent stimulated people’s desire to buy. 花香激发了人们的购买欲。","derivative":"desirous /dɪˈzaɪərəs/ adj.渴望的，希望的；desirable /dɪˈzaərəbl/ adj.理想的；值得拥有的；值得做的"},{"id":2400,"word":"desirable","pronunciation":"/dɪ'zaɪərəbl/","meaning":"adj.理想的；值得拥有的；值得做的","unit":8,"lesson":4,"seq":33,"isStar":false},{"id":2401,"word":"radical","pronunciation":"/'rædɪkl/","meaning":"n.激进分子 adj.激进的；根本的，彻底的","unit":8,"lesson":4,"seq":34,"isStar":false,"memo":"ra(联想“让”)+di(联想“弟”)+cal (音似“扣”)→弟弟那么小,你就让他学扣篮,这是一种“激进的”做法。","example":"College education should be improved through radical measures. 大学教育应该通过根本性的措施来改善。"},{"id":2402,"word":"extreme","pronunciation":"/ɪk'striːm/","meaning":"adj.极度的，极端的；严重的 n.极端，极度","unit":8,"lesson":4,"seq":35,"isStar":false,"memo":"ex-(往外)+tre(音似“锤”)+me (我)→他挥舞着大锤把我往外轰,这种行为是很“严重的”,太过“极端”。","example":"They were reduced to extreme poverty. 他们沦落到极度贫困的地步。","derivative":"extremity /ɪkˈstreməti/ n.极端,末端;尽头"},{"id":2403,"word":"despair","pronunciation":"/dɪ'speə(r)/","meaning":"n.绝望 v.绝望，感到无望","unit":8,"lesson":4,"seq":36,"isStar":false,"memo":"de(音似“弟”)+s(联想“失”)+pair (一双)→弟弟丢失了一双限量款鞋子,他快“绝望”了。","example":"I looked at my boss in despair. 我绝望地看着我的老板。"},{"id":2404,"word":"impair","pronunciation":"/ɪm'peə(r)/","meaning":"v.损害；削弱","unit":8,"lesson":4,"seq":37,"isStar":false,"memo":"i(我)+m(联想“妹”)+pair(一双)→我妹妹长期看手机,一双眼睛都受到了“损害”。","example":"It's well known that obesity impairs sleep. 众所周知,肥胖会损害睡眠。"},{"id":2405,"word":"dismay","pronunciation":"/dɪs'meɪ/","meaning":"n.灰心，丧气；惊愕 v.使失望，使惊愕","unit":8,"lesson":4,"seq":38,"isStar":false,"memo":"di(联想“弟”)+s(联想“似”)+may (音似“妹”)→弟弟听说他和妹妹很相似,十分“惊愕”。","example":"To her dismay, her name was not on the list. 令她惊愕的是,名单上没有她的名字。"},{"id":2406,"word":"diminish","pronunciation":"/dɪ'mɪnɪʃ/","meaning":"v.减少，（使）减弱，降低；贬低","unit":8,"lesson":4,"seq":39,"isStar":false,"memo":"di(联想“弟”)+mi(音似“妹”)+ni (联想“你”)+sh(音似“失”)→有了弟弟妹妹的陪伴,你的烦恼“减少”,痛苦消失。","example":"The world's resources are rapidly diminishing. 世界资源正在迅速减少。"},{"id":2407,"word":"desperate","pronunciation":"/'despərət/","meaning":"adj.拼命的；绝望的；非常需要的；危急的","unit":8,"lesson":4,"seq":40,"isStar":false,"example":"I was lucky that my last desperate attempt led to a job. 很幸运,最后一次绝望的尝试让我找到了一份工作。"},{"id":2408,"word":"discrepancy","pronunciation":"/dɪ'skrepansi/","meaning":"n.差异；不符合，不一致","unit":8,"lesson":4,"seq":41,"isStar":false,"example":"Why is there such a discrepancy between the ideal and the reality? 为什么理想与现实之间存在如此大的差异呢?"},{"id":2409,"word":"destiny","pronunciation":"/'destəni/","meaning":"n.命运，天命，天数","unit":8,"lesson":4,"seq":42,"isStar":false,"memo":"de(联想“的”)+s(形似弯曲的路)+tiny(小的)→走的每条弯路,做的每个微小选择,共同构成了一个人的“命运”。","example":"It was extremely important to the destiny of humankind. 这对人类的命运至关重要。","derivative":"destined /destɪnd/ adj.预定;注定的"},{"id":2410,"word":"destined","pronunciation":"/'destɪnd/","meaning":"adj.预定；注定的","unit":8,"lesson":4,"seq":43,"isStar":false},{"id":2411,"word":"deliberate","pronunciation":"/dɪ'lɪbərət/","meaning":"adj.故意的，蓄意的；从容不迫的","unit":8,"lesson":4,"seq":44,"isStar":false,"memo":"de(音似“弟”)+liberate(解放,使自由)→弟弟能不能零食自由需要妈妈“仔细考虑”。","example":"Witnesses said the firing was deliberate and sustained.目击者说枪击是蓄意的,而且持续了很长时间。","derivative":"deliberation /dɪˌlɪbəˈreɪʃn/ n.审议,考虑;审慎"},{"id":2412,"word":"liberate","pronunciation":"/'lɪbəreɪt/","meaning":"v.解放；使自由；使摆脱约束（或限制）","unit":8,"lesson":4,"seq":45,"isStar":false,"memo":"liber(音似“隶搏”)+-ate(动词后缀)→奴隶努力拼搏来争取自由→解放;使自由","example":"Their mission was to liberate the thousands who had been enslaved.他们的任务是解放成千上万被奴役的人。","derivative":"liberal /ˈlɪbərəl/ adj.开明的;自由的,开放的\nliberty /ˈlɪbəti/ n.自由\nliberation /ˌlɪbəˈreɪʃn/ n.解放"},{"id":2413,"word":"statue","pronunciation":"/'stætʃuː/","meaning":"n.雕塑，雕像","unit":8,"lesson":4,"seq":46,"isStar":false,"memo":"sta(联想 stand)+tue(音似“矗”)→站立、矗立的建筑物→雕像","example":"He illuminated the Statue of Liberty.他点亮了自由女神像。"},{"id":2414,"word":"contemplate","pronunciation":"/'kɒntəmpleɪt/","meaning":"v.考虑；沉思；深思熟虑","unit":8,"lesson":4,"seq":47,"isStar":false,"memo":"con-(所有)+templ(联想 temple)+ate→听闻这一切,寺庙里的所有人都陷入了“沉思”。","example":"The government has contemplated reforming the entire tax system.政府已经考虑改革整个税收制度。","derivative":"contemplation /ˌkɒntəmˈpleʃn/ n.深思,沉思,冥想;默默注视\ncontemplative /kənˈtemplətv/ adj.深思熟虑的;冥想的"},{"id":2415,"word":"digest","pronunciation":"/'daɪdʒest/","meaning":"n.文摘，摘要","unit":8,"lesson":4,"seq":48,"isStar":false,"memo":"di-(两个)+ge(联想“哥”)+st(联想 street)→两个哥哥吃了太多,要去街上散步,“消化”一下。","example":"The child can't digest complex information yet.这个孩子还不能领悟复杂的信息。","derivative":"digestion /daɪˈdʒestʃən/ n.消化,消化能力\ndigestive /daɪˈdʒestɪv/ adj.消化的,和消化有关的"},{"id":2416,"word":"vulgar","pronunciation":"/'vʌlɡə(r)/","meaning":"adj.粗俗的；粗野的；庸俗的","unit":9,"lesson":1,"seq":1,"isStar":false,"memo":"谐音：单词发音类似“哇哥”→哥哥穿了一件没有品位的衣服，我大吃一惊，觉得他是“庸俗的”。","example":"They told some vulgar jokes. 他们讲了一些低俗的笑话。"},{"id":2417,"word":"garment","pronunciation":"/'ɡɑːmənt/","meaning":"n.(一件)衣服","unit":9,"lesson":1,"seq":2,"isStar":false,"memo":"联想：gar(音似“尬”) + m(联想“妹”) + ent →妹妹的“衣服”破了，很尴尬。","example":"He hired a garment. 他租了一件衣服。"},{"id":2418,"word":"glory","pronunciation":"/'ɡlɔːri/","meaning":"n.荣誉；赞美；辉煌","unit":9,"lesson":1,"seq":3,"isStar":false,"memo":"谐音：单词发音类似“哥捞日”→哥哥要是能把太阳打捞上来，那可是无上的“荣誉”。","example":"The brave soldiers earned everlasting glory. 英勇的战士们赢得了永恒的荣誉。"},{"id":2419,"word":"glorious","pronunciation":"/'ɡlɔːriəs/","meaning":"adj.光荣的；辉煌的；壮丽的","unit":9,"lesson":1,"seq":4,"isStar":false,"example":"Human civilization remains glorious, though it is affected by climate change. 人类文明虽然受到气候变化的影响，但依然辉煌。"},{"id":2420,"word":"hono(u)r","pronunciation":"/'hɒnə(r)/","meaning":"n.尊敬；荣幸；荣誉 v.尊重(某人)；给予表扬(或奖励、头衔、称号)","unit":9,"lesson":1,"seq":5,"isStar":false},{"id":2421,"word":"challenge","pronunciation":"/'tʃælɪndʒ/","meaning":"v.挑战；对……怀疑(或质疑) n.挑战；质疑","unit":9,"lesson":1,"seq":6,"isStar":false,"memo":"联想：cha(联想“叉”) + lle(联想“了”) + n(联想“牛”) + ge(联想“哥”) →弟弟吃饭时用叉子叉了哥哥的牛排，这是在“挑战”他的耐心。","example":"Its validity was challenged by many communities. 它的有效性受到了许多社区的质疑。","derivative":"challenging /tʃælɪndɪŋ/ adj. 挑战性的"},{"id":2422,"word":"trigger","pronunciation":"/'trɪɡə(r)/","meaning":"v.引发；引起；触发 n.扳机；起因；诱因","unit":9,"lesson":1,"seq":7,"isStar":false,"memo":"谐音 单词发音类似“捶哥”→他捶了哥哥，“引发”了矛盾。","example":"Even a tiny amount of food may trigger an allergic reaction. 即使是极少量的食物也可能引发过敏反应。"},{"id":2423,"word":"lag","pronunciation":"/læɡ/","meaning":"v.发展缓慢；滞后；落后于","unit":9,"lesson":1,"seq":8,"isStar":false,"memo":"谐音 单词发音类似“拉哥”→哥哥落后了，需要我拉着他跑→落后于","example":"She did well in her first year at school but then started to lag behind. 她在校第一年成绩很好,但后来就开始落后了。"},{"id":2424,"word":"lame","pronunciation":"/leɪm/","meaning":"adj.跛的；没有说服力的","unit":9,"lesson":1,"seq":9,"isStar":false,"memo":"联想 la(联想“拉”) + me(我)→你需要拉我一下,因为我有点跛足→跛的","example":"He didn't agree with her lame arguments. 他不同意她蹩脚的观点。"},{"id":2425,"word":"tame","pronunciation":"/teɪm/","meaning":"adj.(动物)驯服的；温顺的 v.驯服；制服","unit":9,"lesson":1,"seq":10,"isStar":false,"memo":"联想 ta(联想“她”) + me(我)→她“制服”了顽劣的我,并帮助我变得更好。","example":"Asian elephants are easier to tame than African elephants. 亚洲象比非洲象更容易驯服。"},{"id":2426,"word":"melt","pronunciation":"/melt/","meaning":"v.(使)融化；(使)熔化","unit":9,"lesson":1,"seq":11,"isStar":false,"memo":"联想 me(我) + l(联想“了”) + t(联想“他”)→我“融化”了他内心的坚冰。","example":"The sun melted the snow. 阳光融化了积雪。"},{"id":2427,"word":"range","pronunciation":"/reɪndʒ/","meaning":"n.一系列；范围；种类；山脉 v.(在一定范围内)变化","unit":9,"lesson":1,"seq":12,"isStar":false,"memo":"联想 ran(run 的过去式) + ge(联想“哥”)→哥哥一般在一定的“范围”内跑步。","example":"The average age range is between 35 and 55. 平均年龄范围是35岁至55岁。"},{"id":2428,"word":"arrange","pronunciation":"/ə'reɪndʒ/","meaning":"v.安排；整理；排列","unit":9,"lesson":1,"seq":13,"isStar":false,"memo":"联想 ar-(一再地) + range(范围)→我们的能力都是有限的,只能在一定的范围内“安排”事情。","example":"She helped him arrange the furniture. 她帮他整理家具。","derivative":"arrangement /ə'rendʒmənt/ n.安排;整理;约定"},{"id":2429,"word":"engage","pronunciation":"/ɪn'ɡeɪdʒ/","meaning":"v.参加；吸引(某人的兴趣)；雇用；聘用","unit":9,"lesson":1,"seq":14,"isStar":false,"example":"It is a movie that engages both the mind and the eye. 这是一部令人赏心悦目的影片。","derivative":"engagement /ɪn'ɡeɪdʒmənt/ n.订婚;约定"},{"id":2430,"word":"pregnant","pronunciation":"/'pregnənt/","meaning":"adj.怀孕的；意味深长的","unit":9,"lesson":1,"seq":15,"isStar":false,"example":"My sister is pregnant with twins. 我妹妹怀了一对双胞胎。","derivative":"pregnancy /'preɡnənsi/ n.妊娠,怀孕"},{"id":2431,"word":"divorce","pronunciation":"/dɪ'vɔːs/","meaning":"n. & v.离婚；分离","unit":9,"lesson":1,"seq":16,"isStar":false,"memo":"谐音 单词发音类似“敌我死”→他们视对方如仇敌,每天斗个你死我活,最后“离婚”了。\n联想 di-(分开) + vorce(音似 voice)→夫妻双方经常表达两种声音,这可能会导致“离婚”。","example":"Financial stress is a chief reason for divorce. 经济压力是离婚的一个首要原因。"},{"id":2432,"word":"single","pronunciation":"/'sɪŋgl/","meaning":"adj.单一的，单人的，单身的 n.单程票，单身者，单曲","unit":9,"lesson":1,"seq":17,"isStar":false},{"id":2433,"word":"dual","pronunciation":"/'djuːəl/","meaning":"adj.双重的，两部分的","unit":9,"lesson":1,"seq":18,"isStar":false,"example":"The piece of furniture serves a dual purpose as a cupboard and as a table. 这件家具有两个用途，既作橱柜，也作饭桌。"},{"id":2434,"word":"duplicate","pronunciation":"/'djuːplɪkeɪt/","meaning":"v.复制，复印","unit":9,"lesson":1,"seq":19,"isStar":false,"memo":"对照：复印（duplicate）可实现一份变双（double）份。","example":"Is this a duplicate or the original? 这是副本还是正本？","derivative":"duplication /ˌdjuːplˈkeɪʃn/ n.复制;重复"},{"id":2435,"word":"reproduce","pronunciation":"/rɪ'prə'djuːs/","meaning":"v.复制；再生产；再现；繁殖","unit":9,"lesson":1,"seq":20,"isStar":false,"example":"There was no method to reproduce the results. 过去没有能够再现成果的方法。","derivative":"reproduction /riːprəˈdʌkʃn/ n.生殖,繁殖;复制\nreproductive /ˌriːprəˈdʌktɪv/ adj.生殖的,繁殖的"},{"id":2436,"word":"couple","pronunciation":"/'kʌpl/","meaning":"n.两人；一对，夫妇；几个 v.连接，结合","unit":9,"lesson":1,"seq":21,"isStar":false,"memo":"谐音：单词发音类似“靠谱”→她认为，只有“两人”都觉得对方靠谱，他们才有可能结为“夫妇”。","example":"They are a couple in the real world as well as in the movie. 他们在电影和现实生活中都是一对夫妇。"},{"id":2437,"word":"coupon","pronunciation":"/'kuːpɒn/","meaning":"n.优惠券","unit":9,"lesson":1,"seq":22,"isStar":false},{"id":2438,"word":"prestige","pronunciation":"/pre'stiːʒ/","meaning":"n.威望，声望","unit":9,"lesson":1,"seq":23,"isStar":false,"memo":"联想：pre-(……前的，预先) + s(联想“死”) + ti(联想“提”) + ge(联想“哥”) → 在我们见面前，他死(一直)提自己的哥哥，是因为他哥哥有“声望”。","example":"He was admitted to a university of high prestige. 他被一所声望很高的大学录取了。","derivative":"prestigious /ˌpre'stɪdʒəs/ adj.有威望的;声誉高的"},{"id":2439,"word":"reputation","pronunciation":"/repju'teɪʃn/","meaning":"n.名声，名誉","unit":9,"lesson":1,"seq":24,"isStar":false,"memo":"联想：re-(重复) + put(放) + -ation(名词后缀) → 反复把他的名字放到最前面，说明他的“名声”最大。"},{"id":2440,"word":"renown","pronunciation":"/rɪ'naʊn/","meaning":"n.名誉，声誉","unit":9,"lesson":1,"seq":25,"isStar":false,"memo":"[联想] re-(重复) + nown(联想 known)→重复地被知道，表明这个人很有“声誉”。","example":"He won renown as a fair judge. 他赢得了公正裁判的荣誉。","derivative":"renowned /rɪˈnaʊnd/ adj.有名望的，著名的"},{"id":2441,"word":"notable","pronunciation":"/'nəʊtəbl/","meaning":"adj.值得注意的，显著的，显要的","unit":9,"lesson":1,"seq":26,"isStar":false,"memo":"[构词] not(e)(注意) + -able(形容词后缀)→值得注意的；显著的，显要的","example":"It cannot be said that the dinner was a notable success socially. 不能说那次晚宴在社交方面取得了显著的成功。","derivative":"notation /nəʊˈteʃn/ n.符号，记号"},{"id":2442,"word":"noteworthy","pronunciation":"/'nəʊtwɜːði/","meaning":"adj.值得注意的，显著的，重要的","unit":9,"lesson":1,"seq":27,"isStar":false,"memo":"[构词] note(注意) + worthy(值得的)→值得注意的","example":"The bridge is noteworthy for its sheer size. 这座桥以宏伟闻名。"},{"id":2443,"word":"anonymous","pronunciation":"/ə'nɒnɪməs/","meaning":"adj.匿名的，不知姓名的，无特色的","unit":9,"lesson":1,"seq":28,"isStar":false,"memo":"[联想] a-(一个) + no(没有) + nym(音似 name) + -ous(形容词后缀)→一个没有名字的→匿名的","example":"The money was donated by a local businessman who wishes to remain anonymous. 这笔款项是当地一位不愿透露姓名的企业家捐赠的。","derivative":"anonymity /ˌænəˈnɪməti/ n.匿名；无特色"},{"id":2444,"word":"notorious","pronunciation":"/nəu'tɔːriəs/","meaning":"adj.声名狼藉的，臭名昭著的","unit":9,"lesson":1,"seq":29,"isStar":false,"example":"The country is notorious for its appalling prison conditions. 这个国家因监狱状况恶劣而臭名远扬。","derivative":"notoriety /ˌnəʊtəˈraɪəti/ n.恶名，坏名声"},{"id":2445,"word":"esteem","pronunciation":"/ɪ'stiːm/","meaning":"n. & v. 尊重；敬重","unit":9,"lesson":1,"seq":30,"isStar":false},{"id":2446,"word":"dignity","pronunciation":"/'dɪgnəti/","meaning":"n. 尊严，庄重，体面；自尊心","unit":9,"lesson":1,"seq":31,"isStar":false,"memo":"[联想] dig(挖) + nity(联想“泥土”)→想赢得“尊严”，最好从底层干起，就像盖房子要先从挖泥土开始一样，一步步走向成功。","example":"Workers should be treated with dignity. 工人应该受到有尊严的对待。","derivative":"dignify /ˈdɡnɪfaɪ/ v.使有尊严；使崇高"},{"id":2447,"word":"indignant","pronunciation":"/ɪn'dɪgnənt/","meaning":"adj. 愤怒的，愤愤不平的","unit":9,"lesson":1,"seq":32,"isStar":false,"memo":"[联想] in-(否定前缀) + dign(联想 dignity) + -ant(形容词后缀)→别人让我们没有尊严的时候，我们往往是“愤怒的”。","example":"He became very indignant when his son made a mistake. 当儿子犯错时，他变得非常气愤。","derivative":"indignation /ˌɪndɪɡˈneɪn/ n.愤慨，愤怒"},{"id":2448,"word":"indigenous","pronunciation":"/ɪn'dɪdʒənəs/","meaning":"adj. 土生土长的，本地的","unit":9,"lesson":1,"seq":33,"isStar":false,"memo":"[联想] in(里面) + dig(挖) + enous→能在这座山里挖东西的人，大概率是“本地的”居民。","example":"Are blueberries indigenous to America? 蓝莓原产于美国吗？"},{"id":2449,"word":"reveal","pronunciation":"/rɪ'viːl/","meaning":"v. 揭示；透露，展现，显露","unit":9,"lesson":1,"seq":34,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + veal(音似“围殴”)→阿姨报警说一群人在围殴一个老人,并帮警察揭开了那群人的真面目→揭示","example":"He revealed that the man who saved him was a stranger. 他透露,救他的人是一个陌生人。"},{"id":2450,"word":"revelation","pronunciation":"/rɪveɪ'leɪʃn/","meaning":"n. 被揭露的真相；披露，揭露","unit":9,"lesson":1,"seq":35,"isStar":false,"memo":"构词 reve(a) l(揭示;透露) + -ation(名词后缀)→披露,揭露","example":"He feared the revelation of the truth. 他害怕真相被披露。"},{"id":2451,"word":"release","pronunciation":"/rɪ'liːs/","meaning":"v. & n. 释放；发布，发行","unit":9,"lesson":1,"seq":36,"isStar":false,"memo":"联想 re-(再) + lease(音似“立誓”)→他再次立誓要减肥,并“发布”了这一消息。","example":"The police arrested several men, who were released later. 警察逮捕了几个人,他们后来被释放了。"},{"id":2452,"word":"veil","pronunciation":"/veɪl/","meaning":"n. 面纱，薄薄的遮盖层 v. 戴面纱；遮掩","unit":9,"lesson":1,"seq":37,"isStar":false,"example":"As the mountains were covered with a veil of cloud, we couldn't see their tops. 因为群山被一层云覆盖,所以我们看不见山顶。","derivative":"v.戴面纱;遮掩"},{"id":2453,"word":"unveil","pronunciation":"/ʌn'veɪl/","meaning":"v. 为……揭幕；将……公之于众，展示","unit":9,"lesson":1,"seq":38,"isStar":false},{"id":2454,"word":"mask","pronunciation":"/mæsk/","meaning":"n. 面具，伪装，掩饰 v. 掩饰，遮盖","unit":9,"lesson":1,"seq":39,"isStar":false,"memo":"联想 m(联想“妹”) + ask(问)→妹妹很害羞,问问题总是遮遮掩掩→掩饰,遮盖","example":"She masked her anger with a smile. 她用微笑掩饰愤怒。","derivative":"v.掩饰,遮盖"},{"id":2455,"word":"disclose","pronunciation":"/dɪs'klaʊz/","meaning":"v. 揭露，透露，泄露","unit":9,"lesson":1,"seq":40,"isStar":false,"memo":"构词 dis-(否定前缀) + close(关闭) → 揭露，透露，泄露","example":"Neither side would disclose details of the transaction. 双方都不会透露交易的细节。","derivative":"disclosure /dɪsˈkləʊʒə(r)/ n.揭露，透露，公开"},{"id":2456,"word":"enclose","pronunciation":"/ɪn'kloʊz/","meaning":"v. 把……围起来；随信附上","unit":9,"lesson":1,"seq":41,"isStar":false,"memo":"构词 en-(使……) + close(关闭) → 使关上 → 把……围起来","example":"Seconds later, the car was enclosed in flames. 几秒钟后，汽车被火焰包围。","derivative":"enclosure /ɪnˈkləʒə(r)/ n.围场；(信中的)附件"},{"id":2457,"word":"closet","pronunciation":"/'klōzɪt/","meaning":"n. 壁橱 adj. 隐藏（身份等）的 v. 把……关在房间里","unit":9,"lesson":1,"seq":42,"isStar":false,"memo":"联想 close(关闭) + t(联想“它”) → 关闭“壁橱”的门。","example":"In department stores and closets all over the world, they are waiting. 在世界各地的百货商店以及壁橱里，它们一直在等待。"},{"id":2458,"word":"conceal","pronunciation":"/kən'siːl/","meaning":"v. 隐藏，隐瞒；掩盖","unit":9,"lesson":1,"seq":43,"isStar":false,"memo":"联想 con-(都) + ceal(联想 seal,封上) → 都封上了 → 隐藏，隐瞒；掩盖","example":"He wanted to conceal something from his parents. 他想对父母隐瞒一些事情。","derivative":"concealment /kənˈsiːlmənt/ n.隐藏，隐瞒；掩盖"},{"id":2459,"word":"disguise","pronunciation":"/dɪs'gaɪz/","meaning":"v. 伪装，掩饰 n. 伪装物","unit":9,"lesson":1,"seq":44,"isStar":false,"memo":"联想 dis-(音似“弟似”) + gui(联想“鬼”) + se→万圣节晚上，弟弟把自己装扮成鬼的样子→伪装","example":"It's an obligation disguised as an option. 它是伪"},{"id":2460,"word":"fabricate","pronunciation":"/'fæbriket/","meaning":"v. 编造，捏造；制造","unit":9,"lesson":1,"seq":45,"isStar":false,"memo":"联想 fabri(联想“发布日”) + cate(音似“剋他”)→在他的新专辑发布日，会有一群人去现场剋(打)他，这是有人“捏造”的谣言。","example":"It angers me that people would fabricate a story like that. 人们会编造这样的故事，这让我感到愤怒。","derivative":"fabrication /ˌfæbrɪˈkeʃn/ n.捏造的信息"},{"id":2461,"word":"fabric","pronunciation":"/'fæbrik/","meaning":"n.织物；布料；（社会、机构、建筑物等的）结构","unit":9,"lesson":1,"seq":46,"isStar":false,"example":"Individual sins affect the entire fabric of society. 个人的罪行影响整个社会的结构。"},{"id":2462,"word":"texture","pronunciation":"/'tekstʃə(r)/","meaning":"n.质地；手感；口感","unit":9,"lesson":1,"seq":47,"isStar":false,"memo":"联想 text(课本) + (t)ure(联想 true)→课本的“质地”真的很好。","example":"They would not be able to tell the texture of objects. 他们将无法分辨物体的质地。"},{"id":2463,"word":"lubricate","pronunciation":"/'luːbrɪkeɪt/","meaning":"v.给……上润滑油；使润滑","unit":9,"lesson":1,"seq":48,"isStar":false,"memo":"对照 lube n.润滑油→lubricate v.","example":"Training can make muscles stronger and keep joints lubricated. 训练可以使肌肉更强壮并保持关节的润滑。","derivative":"lubrication /ˌluːbrɪˈkeɪʃn/ n.润滑"},{"id":2464,"word":"grease","pronunciation":"/griːs/","meaning":"n.油脂 v.给……加润滑油；在……上涂油","unit":9,"lesson":1,"seq":49,"isStar":false,"memo":"联想 gr(联想“官人”) + ease(放松)→官人要去做推拿放松一下，做之前在身上涂“油脂”。","example":"Her hands were covered with oil and grease. 她满手油垢。","derivative":"greasy /ɡriːsi/ adj.多油的；油污的，沾油脂的"},{"id":2465,"word":"temporary","pronunciation":"/'temprəri/","meaning":"adj.暂时的；临时的；短暂的","unit":9,"lesson":1,"seq":50,"isStar":false,"memo":"[构词] tempor(时间)+-ary(后缀)→暂时的,临时的","example":"The woman needs a temporary replacement for her assistant. 这位女士需要一个临时工代替她的助理。","derivative":"temporarily /'temprərəli/ adv.临时地;短暂地"},{"id":2466,"word":"contemporary","pronunciation":"/kən'tempərəri/","meaning":"n.同代人；同龄人 adj.同时代的；当代的","unit":9,"lesson":1,"seq":51,"isStar":false,"memo":"[联想] con-(所有的)+temporary(暂时的)→所有人只能暂时跟上“当代的”节奏。","example":"He was a contemporary of Freud. 他是弗洛伊德的同代人。"},{"id":2467,"word":"temporal","pronunciation":"/'tempərəl/","meaning":"adj.时间的；短暂的；世俗的","unit":9,"lesson":1,"seq":52,"isStar":false},{"id":2468,"word":"occasion","pronunciation":"/ə'keɪʒn/","meaning":"n.特殊场合；时机","unit":9,"lesson":1,"seq":53,"isStar":false,"example":"It is natural to desire to do so for special occasions. 在特殊场合想这样做是很正常的。","derivative":"occasional /ə'keɪʒənl/ adj.偶尔的;临时的\noccasionally /ə'keɪʒənəli/ adv.偶然,偶尔,有时候"},{"id":2469,"word":"coincide","pronunciation":"/ɪkəʊɪn'saɪd/","meaning":"v.同时发生；相符，一致","unit":9,"lesson":1,"seq":54,"isStar":false,"example":"Let the time for learning coincide with the time when your memory is at its best. 要让学习的时间与你记忆力最好的时间相吻合。"},{"id":2470,"word":"coincidence","pronunciation":"/kəu'ɪnsɪdəns/","meaning":"n.巧合；同时发生","unit":9,"lesson":1,"seq":55,"isStar":false,"memo":"[联想] coin(硬币)+cide(联想 side)+nce→抛硬币连续多次出现正面,这是“巧合”。","example":"It was such a coincidence when Pat and Mike met each other in Tokyo. 帕特和迈克在东京相遇,真是太巧了。"},{"id":2471,"word":"incidence","pronunciation":"/'ɪnsɪdəns/","meaning":"n.发生率","unit":9,"lesson":1,"seq":56,"isStar":false,"example":"It helps reduce the incidence of heart disease. 它有助于减少心脏病的发病率。"},{"id":2472,"word":"incident","pronunciation":"/'ɪnsɪdənt/","meaning":"n.事件；（两国间的）冲突","unit":9,"lesson":1,"seq":57,"isStar":false,"example":"Similar incidents have occurred before. 类似的事件以前也发生过。"},{"id":2473,"word":"incidental","pronunciation":"/ɪnsɪ'dentl/","meaning":"adj.附带发生的，次要的；非有意的 n.附带事件","unit":9,"lesson":1,"seq":58,"isStar":false},{"id":2474,"word":"complex","pronunciation":"/'kɒmpleks/","meaning":"adj.复杂的；难以理解的 n.(类型相似的)建筑群","unit":9,"lesson":2,"seq":1,"isStar":false,"example":"The causes of real-world violence are complex. 现实世界存在暴力的原因是复杂的。","derivative":"complexity /kəmˈpleksəti/ n.复杂性；复杂之处"},{"id":2475,"word":"complexion","pronunciation":"/kəm'plekʃn/","meaning":"n.面色，气色","unit":9,"lesson":2,"seq":2,"isStar":false},{"id":2476,"word":"perplex","pronunciation":"/pə'pleks/","meaning":"v.使困惑，使费解","unit":9,"lesson":2,"seq":3,"isStar":false,"memo":"联想 per(每) + plex(联想 complex) → 每个问题都很复杂，这使我很困惑→使困惑","example":"It perplexed him because he was tackling the problem the wrong way. 这令他困惑，因为他解决问题的方式是错误的。","derivative":"perplexity /pəˈpleksəti/ n.困惑；迷惘"},{"id":2477,"word":"complicate","pronunciation":"/'kɒmplɪkeɪt/","meaning":"v.使复杂化","unit":9,"lesson":2,"seq":4,"isStar":false,"memo":"联想 complic(联想 complex) + -ate(动词后缀) → 使复杂化","example":"Don't complicate your life. 不要让你的生活变得复杂。","derivative":"complicated /ˈkɒmplɪkeɪtɪd/ adj.复杂的；难懂的 complication /ˌkɒmplɪˈkeɪʃn/ n.使复杂化的问题（情况）；并发症"},{"id":2478,"word":"intricate","pronunciation":"/'ɪntrɪkət/","meaning":"adj.错综复杂的；难理解的","unit":9,"lesson":2,"seq":5,"isStar":false,"memo":"联想 in(里面) + tri(音似“纯”) + cate(音似“剋他”) → 内心纯洁的那个人竟然要去他，这是让人“难理解的”。","example":"You develop in-depth knowledge of the intricate structure of the language. 你对该语言错综复杂的结构有了深入的了解。"},{"id":2479,"word":"intrinsic","pronunciation":"/ɪn'trɪnzɪk/","meaning":"adj.固有的，内在的，本质的","unit":9,"lesson":2,"seq":6,"isStar":false,"example":"It is crucial to recognize the intrinsic value of education. 认识到教育的固有价值至关重要。","derivative":"intrinsically /ɪn'trɪnzɪkli/ adv. 本质上"},{"id":2480,"word":"instinct","pronunciation":"/'ɪnstɪŋkt/","meaning":"n.本能，天性；直觉","unit":9,"lesson":2,"seq":7,"isStar":false,"memo":"[谐音] 单词发音类似“鹰死盯着它”→老鹰死盯着猎物是一种“本能”。","example":"Their instincts warned them something was wrong. 他们的本能提醒他们有些事情不对劲。"},{"id":2481,"word":"distinguish","pronunciation":"/dɪ'stɪŋgwɪʃ/","meaning":"v.区分；使出众","unit":9,"lesson":2,"seq":8,"isStar":false,"memo":"[谐音] 单词发音类似“弟似听故事”→弟弟似乎在努力地听老师讲故事，试图“区分”故事里的好人和坏人。","example":"Culture is still used as a mark to distinguish one social class from another. 文化仍被用作区分不同社会阶层的标志。","derivative":"distinguishable /dɪ'stɪɡwɪʃəbl/ adj. 可区分的，可辨认的"},{"id":2482,"word":"distinction","pronunciation":"/dɪ'stɪŋkʃn/","meaning":"n.差别，区别，特点，特质，不同凡响","unit":9,"lesson":2,"seq":9,"isStar":false,"example":"We need to draw a distinction between the two events. 我们得把两起事件区别开来。"},{"id":2483,"word":"distinct","pronunciation":"/dɪ'stɪŋkt/","meaning":"adj.清晰的，明白的；截然不同的","unit":9,"lesson":2,"seq":10,"isStar":false,"example":"The results of the survey fell into two distinct groups. 调查结果分为截然不同的两组。"},{"id":2484,"word":"distinctive","pronunciation":"/dɪ'stɪŋktɪv/","meaning":"adj.独特的，有特色的","unit":9,"lesson":2,"seq":11,"isStar":false},{"id":2485,"word":"extinguish","pronunciation":"/ɪk'stɪŋgwɪʃ/","meaning":"v.熄灭，扑灭；使破灭","unit":9,"lesson":2,"seq":12,"isStar":false,"example":"Smoking is forbidden. Please extinguish your cigarettes. 禁止吸烟。请熄灭你们的烟。"},{"id":2486,"word":"extinct","pronunciation":"/ɪk'stɪŋkt/","meaning":"adj.不再存在的，绝种的，绝迹的","unit":9,"lesson":2,"seq":13,"isStar":false,"example":"A species once extinct is gone forever. 一个物种一旦灭绝就永远消失了。","derivative":"extinction /k'stɪŋkʃn/ n. 灭绝，消亡"},{"id":2487,"word":"bewilder","pronunciation":"/bɪ'wɪldə(r)/","meaning":"v.使糊涂，使迷惑","unit":9,"lesson":2,"seq":14,"isStar":false,"memo":"[联想] be-（使处于某种状态）+ wild（野外）+ er → 使你在野外迷路 → 使糊涂，使迷惑","example":"She was totally bewildered by his sudden change of mood. 他的情绪突变搞得她全然不知所措。","derivative":"bewilderment /b'wɪldəmənt/ n. 迷惘；困惑"},{"id":2488,"word":"baffle","pronunciation":"/'bæfl/","meaning":"v.使困惑；难住","unit":9,"lesson":2,"seq":15,"isStar":false,"memo":"[谐音] 单词发音类似“拜佛”→孙悟空遇到困惑后，偶尔会找佛祖指点迷津→使困惑","example":"One of the examination questions baffled me completely. 有一道考题完全把我难住了。"},{"id":2489,"word":"confuse","pronunciation":"/kən'fjuːz/","meaning":"v.使糊涂，使迷惑；（将……）混淆","unit":9,"lesson":2,"seq":16,"isStar":false,"memo":"[构词] con-（一起）+ fuse（流）→ 流到一起 → 混合，混淆 → 使迷惑","example":"They were confused by the infinite options their money presented them with. 他们被金钱所提供的无穷无尽的选择迷惑了。","derivative":"confusion /kən'fjuʒn/ n. 困惑；混淆"},{"id":2490,"word":"fuse","pronunciation":"/fjuːz/","meaning":"n.保险丝；导火线 v.(使)融合；(使)熔化","unit":9,"lesson":2,"seq":17,"isStar":false,"example":"Our different ideas fused into a plan. 我们不同的想法融合成一项计划。","derivative":"v. (使) 融合；(使) 熔化; fusion /'fjuːʒn/ n. 融合；核聚变，热核反应"},{"id":2491,"word":"diffuse","pronunciation":"/dɪ'fjuːz/","meaning":"v.普及；散布；渗透","unit":9,"lesson":2,"seq":18,"isStar":false,"memo":"构词 dif-(分开) + fuse(流)→散布","example":"The pollutants diffuse into the soil. 污染物渗进土壤中。","derivative":"diffusion /dɪˈfjuːn/ n.传播,散布"},{"id":2492,"word":"refute","pronunciation":"/rɪ'fjuːt/","meaning":"v.驳斥；反驳，否认","unit":9,"lesson":2,"seq":19,"isStar":false,"memo":"构词 re-(往回) + fute ( = beat, 击) → 回击→反驳,否认","example":"This can be refuted by scholarly research. 学术研究结果可以反驳这种说法。","derivative":"refutation /ˌrefjuˈteɪʃn/ n.反驳"},{"id":2493,"word":"disperse","pronunciation":"/dɪ'spɜːs/","meaning":"v.(使)分散；传播，散布","unit":9,"lesson":2,"seq":20,"isStar":false,"memo":"联想 dis-(否定前缀) + perse(音似“婆撕”)→不要到处“传播”她和她的婆婆撕破脸的虚假消息。","example":"The seeds are dispersed by the wind. 种子是通过风传播的。"},{"id":2494,"word":"authority","pronunciation":"/ɔː'θɒrɪti/","meaning":"n.权威；权力；批准","unit":9,"lesson":2,"seq":21,"isStar":false,"memo":"联想 author(作者) + -ity(名词后缀)→作者是写作领域的“权威”。","example":"Don't raise the stakes by challenging her authority. 不要通过挑战她的权威来增加风险。","derivative":"authoritative /ːˈθɒrətətɪv/ adj.命令式的;权威性的"},{"id":2495,"word":"authorise","pronunciation":"/-ize/","meaning":"'ɔːθəraɪz/ v.批准；授权","unit":9,"lesson":2,"seq":22,"isStar":false},{"id":2496,"word":"copyright","pronunciation":"/'kɒpɪrət/","meaning":"n.版权；著作权","unit":9,"lesson":2,"seq":23,"isStar":false},{"id":2497,"word":"authentic","pronunciation":"/ɔː'θentɪk/","meaning":"adj.真正的；真实的；逼真的","unit":9,"lesson":2,"seq":24,"isStar":false,"memo":"联想 authen(联想 author) + -tic(形容词后缀)→作者的思想通常是“真实的”。","example":"They claim that their account is the “authentic” one. 他们声称他们的叙述是“真实的”。","derivative":"authenticity /ˌɔːθenˈtɪsəti/ n.真实性;确实性"},{"id":2498,"word":"entitle","pronunciation":"/ɪn'taɪtl/","meaning":"v.使……有权利或资格","unit":9,"lesson":2,"seq":25,"isStar":false,"memo":"构词 en-(使) + title(标题;头衔)→使……有权利或资格","example":"Everyone is entitled to their own opinion. 每个人都有权发表自己的意见。"},{"id":2499,"word":"virtual","pronunciation":"/'vɜːtʃuəl/","meaning":"adj.事实上的；虚拟的","unit":9,"lesson":2,"seq":26,"isStar":false,"memo":"谐音 单词发音类似“龌”→他看起来很龌龊,但实际上很正经→事实上的","example":"Those products can also do well in the virtual environment. 那些产品在虚拟环境中也能有不错的销量。","derivative":"virtually /'vɜːtuəli/ adv.虚拟地;实际上,几乎"},{"id":2500,"word":"absolute","pronunciation":"/'æbsəljuːt/","meaning":"adj.完全的；绝对的","unit":9,"lesson":2,"seq":27,"isStar":false,"memo":"联想 ab-(一再地)+so(如此)+lute(联想late)→一再地如此晚→完全晚了→完全的","example":"If you love your mate, you need absolute confidence and trust in him/her. 如果你爱你的配偶,你就需要完全地信任他/她。"},{"id":2501,"word":"sheer","pronunciation":"/ʃiː(r)/","meaning":"adj.完全的，纯粹的；陡峭的 adv.垂直地；陡峭地","unit":9,"lesson":2,"seq":28,"isStar":false,"memo":"联想 she(她)+er(表示人的后缀)→她是个“纯粹”人。","example":"It can't be solved by the sheer force of activity. 它无法单凭行动就能得到解决。"},{"id":2502,"word":"complete","pronunciation":"/kəm'pliːt/","meaning":"adj.完全的，彻底的，完整的 v.完成；填写（表格）","unit":9,"lesson":2,"seq":29,"isStar":false,"memo":"构词 com-(完全)+plete(填满)→完全填满了→完全的,彻底的","example":"We were in complete agreement. 我们意见完全一致。"},{"id":2503,"word":"practicable","pronunciation":"/'præktɪkəbl/","meaning":"adj.可行的，行得通的","unit":9,"lesson":2,"seq":30,"isStar":false,"memo":"构词 practic(e)(实践)+-able(形容词后缀)→可行的,行得通的","example":"It offers practicable advice to businessmen. 它为商人提供了切实可行的建议。"},{"id":2504,"word":"malpractice","pronunciation":"/'mæl'præktɪs/","meaning":"n.渎职，玩忽职守","unit":9,"lesson":2,"seq":31,"isStar":false,"memo":"构词 mal-(不良)+practice(实践;行为)→不良的行为→渎职,玩忽职守","example":"He was unable to alert his students to corporate malpractice. 他未能向他的学生警示公司的违规行为。"},{"id":2505,"word":"practical","pronunciation":"/'præktɪkl/","meaning":"adj.实际的；实用的   n.实践课","unit":9,"lesson":2,"seq":32,"isStar":false,"memo":"对照 多做练习(practice)就会积累更多实用的(practical)经验。","example":"This is a practical little car, ideal for the city. 这是一款实用的小汽车,非常适合在城市中使用。","derivative":"practicality /ˌpræktɪ'kæləti/ n.可行性"},{"id":2506,"word":"genuine","pronunciation":"/'dʒenjuɪn/","meaning":"adj.真的；真诚的","unit":9,"lesson":2,"seq":33,"isStar":false,"memo":"谐音 单词发音类似“真牛”→姐姐“真的”很牛,是个强者。"},{"id":2507,"word":"generous","pronunciation":"/'dʒenərəs/","meaning":"adj.慷慨的，大方的；宽宏大量的","unit":9,"lesson":2,"seq":34,"isStar":false,"memo":"谐音：单词发音类似“真弄肉丝”→“慷慨的”姐姐真给我弄了一大盘肉丝。","example":"She is a generous woman by nature. 她天生就是个慷慨的女人。"},{"id":2508,"word":"genius","pronunciation":"/'dʒɪniəs/","meaning":"n.天才；天资","unit":9,"lesson":2,"seq":35,"isStar":false,"memo":"联想：ge(联想“哥”) + nius(音似“牛死”) → 哥哥牛死了，是个“天才”。","example":"It's undoubtedly a work of genius. 这无疑是一部天才之作。"},{"id":2509,"word":"elite","pronunciation":"/eɪ'liːt; ɪ'liːt/","meaning":"n.社会精英   adj.精英的","unit":9,"lesson":2,"seq":36,"isStar":false,"memo":"联想：e(字母音似“姨”) + li(联想“离”) + te(音似“他”) → 阿姨离开他后成了“社会精英”。","example":"A new managerial elite was replacing the old aristocracy. 新的管理精英阶层正在取代旧的贵族阶层。"},{"id":2510,"word":"ingenious","pronunciation":"/ɪn'dʒɪniəs/","meaning":"adj.巧妙的；心灵手巧的；善于创造发明的","unit":9,"lesson":2,"seq":37,"isStar":false,"memo":"联想：in(里面) + genious(联想 genius) → 天才的内心→心灵手巧的","example":"He is an ingenious cook. 他是一名心灵手巧的厨师。","derivative":"ingenuity /ˌɪndʒəˈnjuːəti/ n.独创力；聪明才智；心灵手巧"},{"id":2511,"word":"nuisance","pronunciation":"/'njuːsns/","meaning":"n.令人讨厌的人或事物","unit":9,"lesson":2,"seq":38,"isStar":false,"memo":"谐音：单词发音类似“牛绅士”→他老是感觉自己很牛，装成个绅士，令人讨厌→令人讨厌的人或事物","example":"I hope you're not making a nuisance of yourself. 我希望你没有讨人嫌。"},{"id":2512,"word":"intelligent","pronunciation":"/ɪn'telɪdʒənt/","meaning":"adj.聪明的；智能的","unit":9,"lesson":2,"seq":39,"isStar":false,"memo":"联想：intel(联想 Internet) + lig + ent(联想 enter) → 能进入因特网行业的人是“聪明的”。","example":"Black-haired women were judged to be intelligent. 黑发女性被认为是聪明的。"},{"id":2513,"word":"intellect","pronunciation":"/'ɪntəlekt/","meaning":"n.智力高的人；（尤指高等的）智力 adj.智力的，有才智的","unit":9,"lesson":2,"seq":40,"isStar":false,"example":"Einstein was one of the greatest intellects of his time. 爱因斯坦是他的时代里最有才智的人之一。","derivative":"intellectual /ˌɪntəˈlektʃuəl/ n.知识分子；脑力劳动者 adj.智力的；有才智的"},{"id":2514,"word":"intelligence","pronunciation":"/ɪn'telɪdʒəns/","meaning":"n.智力；情报","unit":9,"lesson":2,"seq":41,"isStar":false,"example":"Artificial intelligence is key to future technological innovations. 人工智能是未来技术创新的关键。"},{"id":2515,"word":"intelligible","pronunciation":"/ɪn'telɪdʒəbl/","meaning":"adj.易懂的，容易理解的","unit":9,"lesson":2,"seq":42,"isStar":false,"memo":"[联想] in-(否定前缀) + tell(说) + igible→不用说就能让人明白→易懂的","example":"His lecture was readily intelligible to all the students. 学生们都能轻松地听懂他的讲座。"},{"id":2516,"word":"sharp","pronunciation":"/ʃɑːp/","meaning":"adj.锋利的；清晰的；敏锐的","unit":9,"lesson":2,"seq":43,"isStar":false,"memo":"[对照] 鲨鱼(shark)的牙齿是锋利的(sharp)。","example":"His mind is as sharp as ever. 他思维敏锐，一如既往。","derivative":"sharpen /'ʃɑːpən/ v.(使)变锋利"},{"id":2517,"word":"blunt","pronunciation":"/blʌnt/","meaning":"adj.不锋利的，钝的；直言不讳的","unit":9,"lesson":2,"seq":44,"isStar":false,"memo":"[谐音] 单词发音类似“不烂它”→拿刀切了半天肉也切不烂它，因为刀子是“不锋利的”。","example":"Sharpen all your blunt knives. 把你所有的钝刀都磨一磨。"},{"id":2518,"word":"blunder","pronunciation":"/'blʌndə(r)/","meaning":"n.愚蠢的错误 v.犯愚蠢的错误","unit":9,"lesson":2,"seq":45,"isStar":false,"memo":"[对照] 直言不讳的(blunt)人可能会犯愚蠢的错误(blunder)。","example":"It was really a blunder to lay him off. 当时开除他真是一个愚蠢的错误。"},{"id":2519,"word":"straightforward","pronunciation":"/streɪt'fɔːwəd/","meaning":"adj.简单的；坦率的；诚实的","unit":9,"lesson":2,"seq":46,"isStar":false,"memo":"[构词] straight(直的) + forward(向前)→坦率的","example":"He presents his arguments in a straightforward way. 他以直截了当的方式提出了他的论点。"},{"id":2520,"word":"giant","pronunciation":"/'dʒaɪənt/","meaning":"adj.巨大的；伟大的 n.巨人；大公司","unit":9,"lesson":2,"seq":47,"isStar":false,"memo":"[联想] GIANT 是自行车品牌捷安特的英文名称→捷安特想做自行车行业的“巨人”。","example":"Today it is a giant advertising company. 如今，它是一家巨型广告公司。"},{"id":2521,"word":"gigantic","pronunciation":"/dʒaɪ'gæntɪk/","meaning":"adj.巨大的，庞大的","unit":9,"lesson":2,"seq":48,"isStar":false,"example":"The gigantic natural harbour is a haven for boats. 这个巨大的天然海港是船舶的避风港。"},{"id":2522,"word":"immense","pronunciation":"/ɪ'mens/","meaning":"adj.极大的，巨大的","unit":9,"lesson":2,"seq":49,"isStar":false,"memo":"[联想] i(我) + mmense(音似“闷死”)→天热得像一个“巨大的”火炉，简直要把我闷死了。","example":"They are often admired for their immense enjoyment of the arts. 他们对艺术的无限热爱常...","derivative":"immensely, immensity, immerse, immersion, commence, commencement"},{"id":2523,"word":"immerse","pronunciation":"/ɪ'mɜːs/","meaning":"v.(使)深陷于；沉浸在","unit":9,"lesson":2,"seq":50,"isStar":false,"memo":"联想 i(我)+mmerse(音似“没死”)→我被淹没了→(使)深陷于,沉浸在","example":"Some netizens are immersed in the virtual world. 一些网民沉浸在虚拟世界。","derivative":"immersion /ɪˈmɜːʃn/ n.沉浸;专心;陷入"},{"id":2524,"word":"commence","pronunciation":"/kə'mens/","meaning":"v.开始；着手","unit":9,"lesson":2,"seq":51,"isStar":false,"memo":"联想 com-(都)+mence(音似“闷死”)→他的鸡鸭都因闷热窒息而死,他得重新“开始”养。","example":"If everyone has arrived, we may now commence the meeting. 如果大家都到齐了,我们现在就开始会议了。","derivative":"commencement /kəmensmənt/ n.开始;开端"},{"id":2525,"word":"enormous","pronunciation":"/ɪ'nɔːməs/","meaning":"adj.巨大的，庞大的","unit":9,"lesson":2,"seq":52,"isStar":false,"memo":"构词 e-(往外)+norm(规范)+-ous(形容词后缀)→超出规范的→巨大的","example":"He is under enormous pressure. 他面临着巨大的压力。"},{"id":2526,"word":"mighty","pronunciation":"/'maɪti/","meaning":"adj.强而有力的；巨大的 adv.非常","unit":9,"lesson":2,"seq":53,"isStar":false},{"id":2527,"word":"almighty","pronunciation":"/'ɔːl'maɪti/","meaning":"adj.全能的；极大的；全能者","unit":9,"lesson":2,"seq":54,"isStar":false},{"id":2528,"word":"lofty","pronunciation":"/'lɒfti/","meaning":"adj.巍峨的；崇高的；高尚的","unit":9,"lesson":2,"seq":55,"isStar":false,"memo":"谐音 单词发音类似“老夫式”→他自称老夫,觉得自己太高尚了→崇高的,高尚的","example":"The company likes to present itself as having lofty, utopian aspirations. 该公司喜欢将自己描绘成拥有崇高的、乌托邦式追求的企业。"},{"id":2529,"word":"fragment","pronunciation":"/'fræɡmənt/","meaning":"n.碎片；片段","unit":9,"lesson":3,"seq":1,"isStar":false,"memo":"fr(联想“芙蓉”)+ag(联想“阿哥”)+m(联想“门”)+ent→芙蓉把阿哥赶出了门,阿哥的心变成了“碎片”。","example":"The wood was so rotten that, when we pulled, it broke up into fragments.这块木头已经腐朽不堪,我们一拉,它就碎成了片。","derivative":"fragmentary /'frægməntri/ adj.残缺不全的,不完整的\nfragmentation /frægmən'teɪʃn/ n.分裂,破裂"},{"id":2530,"word":"fragile","pronunciation":"/'frædʒaɪl/","meaning":"adj.脆弱的，易碎的；虚弱的","unit":9,"lesson":3,"seq":2,"isStar":false,"memo":"frag(打碎,破碎)+-ile(形容词后缀)→易碎的","example":"Her father is now 86 and in fragile health.她的父亲现在86岁,身体虚弱。"},{"id":2531,"word":"frantic","pronunciation":"/'frentɪk/","meaning":"adj.紧张忙乱的，手忙脚乱的；发狂似的","unit":9,"lesson":3,"seq":3,"isStar":false},{"id":2532,"word":"fraction","pronunciation":"/'frækʃn/","meaning":"n.小部分；少量","unit":9,"lesson":3,"seq":4,"isStar":false,"memo":"fr(联想“芙蓉”)+action(行为)→芙蓉的行为只有“小部分”人可以接受。","example":"She paused for a fraction of a second.她略微停顿了一下。"},{"id":2533,"word":"fracture","pronunciation":"/'fræktʃə(r)/","meaning":"v.折断，破裂 n.骨折，断裂","unit":9,"lesson":3,"seq":5,"isStar":false,"memo":"fr(联想“芙蓉”)+acture(联想structure)→芙蓉的骨骼结构比较脆弱,有“骨折”的风险。","example":"Old people's bones are more prone to fracture.老人更易骨折。"},{"id":2534,"word":"frame","pronunciation":"/freɪm/","meaning":"n.框架；骨架 v.(给)装框架；制定","unit":9,"lesson":3,"seq":6,"isStar":false,"example":"The frame is made of wood.框架是用木头做的。"},{"id":2535,"word":"framework","pronunciation":"/'freɪmwɜːk/","meaning":"n.构架，框架","unit":9,"lesson":3,"seq":7,"isStar":false},{"id":2536,"word":"flame","pronunciation":"/fleɪm/","meaning":"n.火焰 v.燃烧；(因强烈情绪而)变红","unit":9,"lesson":3,"seq":8,"isStar":false},{"id":2537,"word":"flare","pronunciation":"/fleə(r)/","meaning":"n.(短暂的)旺火；闪光 v.燃烧；闪耀，闪光","unit":9,"lesson":3,"seq":9,"isStar":false},{"id":2538,"word":"fluid","pronunciation":"/'fluːɪd/","meaning":"n.液体，流体 adj.流动的","unit":9,"lesson":3,"seq":10,"isStar":false},{"id":2539,"word":"solid","pronunciation":"/'sɒlɪd/","meaning":"adj.固体的；结实的，坚实的 n.固体","unit":9,"lesson":3,"seq":11,"isStar":false},{"id":2540,"word":"watertight","pronunciation":"/'wɔːtətaɪt/","meaning":"adj.防水的；无懈可击的","unit":9,"lesson":3,"seq":12,"isStar":false},{"id":2541,"word":"consolidate","pronunciation":"/kən'sɒlɪdeɪt/","meaning":"v.使加强，使巩固；合并","unit":9,"lesson":3,"seq":13,"isStar":false,"memo":"con-（一起）+ solid（坚固）+ -ate → 把散沙捏成solid砖！复习三遍=知识 consolidate，牢得像水泥～","example":"The company consolidated its overseas offices to cut costs. 公司整合海外办事处以降低成本。","derivative":"consolidation /kənˌsɒlɪ'deɪʃn/ n. 巩固；合并"},{"id":2542,"word":"solidarity","pronunciation":"/sɒlɪ'dærətɪ/","meaning":"n.团结","unit":9,"lesson":3,"seq":14,"isStar":false},{"id":2543,"word":"flatter","pronunciation":"/'flætə(r)/","meaning":"v.讨好，奉承","unit":9,"lesson":3,"seq":15,"isStar":false},{"id":2544,"word":"flutter","pronunciation":"/'flʌtə(r)/","meaning":"v. & n.飘动；挥动","unit":9,"lesson":3,"seq":16,"isStar":false},{"id":2545,"word":"fluent","pronunciation":"/'fluːənt/","meaning":"adj.流利的，熟练的，流畅的","unit":9,"lesson":3,"seq":17,"isStar":false},{"id":2546,"word":"affluent","pronunciation":"/'æfluənt/","meaning":"adj.富裕的","unit":9,"lesson":3,"seq":18,"isStar":false,"memo":"谐音+构词：'a-fluent'→ '啊！流金'！钱像河水哗哗流，富裕得自带BGM～","example":"Affluent families often invest heavily in private education for their children. 富裕家庭通常会大力投资子女的私立教育。","derivative":"affluence /ˈæfluəns/ n.富裕；affluently /ˈæfluəntli/ adv.富裕地"},{"id":2547,"word":"original","pronunciation":"/ə'ridʒənl/","meaning":"adj.起初的；首创的 n.原件","unit":9,"lesson":3,"seq":19,"isStar":false},{"id":2548,"word":"originate","pronunciation":"/ə'ridʒineɪt/","meaning":"v.起源，发源，创立","unit":9,"lesson":3,"seq":20,"isStar":false,"memo":"构词：ori-（升起，如orient东方即太阳升起处）+ -gin-（开始）+ -ate（动词）→'日出之地开始'！万物皆从'起源'那一刻冉冉升起～","example":"The tradition originates from a 19th-century rural festival. 这一传统起源于19世纪的一场乡村节日。","derivative":"origin /'ɒrɪdʒɪn/ n.起源；original /ə'rɪdʒɪn(ə)l/ adj.原始的"},{"id":2549,"word":"region","pronunciation":"/'riːdʒən/","meaning":"n.地区，区域","unit":9,"lesson":3,"seq":21,"isStar":false},{"id":2550,"word":"sacred","pronunciation":"/'seɪkrɪd/","meaning":"adj.神圣的","unit":9,"lesson":3,"seq":22,"isStar":false,"memo":"谐音+联想：‘赛克瑞德’→‘赛’场上最‘克’制的‘瑞’士钟表匠，把每秒都当‘神圣’仪式来做！sacr-（神圣）+ -ed→被神化的。","example":"Mountains are sacred sites for many indigenous communities. 对许多原住民社群而言，山脉是神圣场所。","derivative":"sacredness /'seɪkrɪdnəs/ n.神圣性"},{"id":2551,"word":"worship","pronunciation":"/'wɜːʃɪp/","meaning":"n. & v.崇拜；爱慕","unit":9,"lesson":3,"seq":23,"isStar":false,"memo":"拆解：wor-（= worth 值得）+ -ship（状态）→ 值得你‘跪着送ship’（送礼/敬意）的状态！本义就是‘敬拜’。","example":"Many students worship tech entrepreneurs as modern-day heroes. 许多学生将科技企业家奉为当代英雄。","derivative":"worshipper /'wɜːʃɪpər/ n.崇拜者；信徒"},{"id":2552,"word":"cult","pronunciation":"/kʌlt/","meaning":"n.狂热，风尚，热潮，异教团体 adj.受到狂热崇拜的","unit":9,"lesson":3,"seq":24,"isStar":false},{"id":2553,"word":"idol","pronunciation":"/'aɪdl/","meaning":"n.偶像","unit":9,"lesson":3,"seq":25,"isStar":false},{"id":2554,"word":"athlete","pronunciation":"/'æθliːt/","meaning":"n.运动员","unit":9,"lesson":3,"seq":26,"isStar":false},{"id":2555,"word":"derive","pronunciation":"/dɪ'raɪv/","meaning":"v.起源于；来自","unit":9,"lesson":3,"seq":27,"isStar":false,"memo":"de-（下）+ riv（拉丁‘rivus’溪流）+ -e → ‘从溪流源头往下引水’，引申为‘从某处源头获得’，知识如活水，得‘溯流而上’才能derive！","example":"Scientists derive new hypotheses from unexpected experimental data. 科学家从意外的实验数据中提出新假设。","derivative":"derivation /ˌderɪˈveɪʃ(ə)n/ n.推导；derivative /dɪˈrɪvətɪv/ adj.派生的"},{"id":2556,"word":"deprive","pronunciation":"/dɪ'praɪv/","meaning":"v.剥夺，使丧失","unit":9,"lesson":3,"seq":28,"isStar":false,"memo":"【构词】de-(去掉)+priv(e)-(私有，源自拉丁privare)→硬把你的‘私有’拿走→剥夺。","example":"Children deprived of adequate sleep often struggle academically. 睡眠不足的儿童常在学业上表现吃力。","derivative":"deprivation /ˌdɛprɪˈveɪʃən/ n.剥夺；匮乏"},{"id":2557,"word":"strive","pronunciation":"/straɪv/","meaning":"v.努力，奋斗；力求","unit":9,"lesson":3,"seq":29,"isStar":false,"memo":"【谐音】'死追'——拼了命也要追上目标！striv(e) 和 strive 同源，过去式strove/striken，像‘strive to survive’（为活命而搏）。","example":"Students must strive for excellence while balancing mental health. 学生必须在追求卓越的同时兼顾心理健康。","derivative":"striving /ˈstraɪvɪŋ/ n.努力；adj.奋斗的"},{"id":2558,"word":"thrive","pronunciation":"/θraɪv/","meaning":"v.兴旺发达，繁荣；茁壮成长","unit":9,"lesson":3,"seq":30,"isStar":false,"memo":"谐音‘三活’——活三次？不，是‘三’倍努力后终于 thrive（茁壮成长）！","example":"Remote students thrive when given flexible deadlines and clear feedback. 当获得弹性截止时间和清晰反馈时，在线学生蓬勃发展。","derivative":"thriving /'θraɪvɪŋ/ adj.繁荣的；兴旺的"},{"id":2559,"word":"contrive","pronunciation":"/kən'traɪv/","meaning":"v.设法做到；策划；发明，设计","unit":9,"lesson":3,"seq":31,"isStar":false,"memo":"【构词】con-（共同）+ triv（转，拉丁trivere）→ 暗中‘转着圈儿想办法’！不是直球解决，是绞尽脑汁‘搞出个法子’，比如用回形针修耳机～","example":"Engineers contrived an ingenious solution to reduce energy consumption. 工程师设计出一种巧妙方案以降低能耗。","derivative":"contrivance /kənˈtraɪvəns/ n.巧计；巧妙的装置"},{"id":2560,"word":"retrieve","pronunciation":"/rɪ'triːv/","meaning":"v.取回；挽回；检索（储存于计算机的信息）","unit":9,"lesson":3,"seq":32,"isStar":false,"memo":"【构词】re-（回）+ triev(e)（=try尝试，古义‘寻找’），拼命往回找→取回、找回！像狗叼回飞盘一样精准。","example":"IT staff retrieved the lost data from backup servers within two hours. 技术人员两小时内从备份服务器中找回了丢失的数据。","derivative":"retrieval /rɪˈtriːv(ə)l/ n.检索；取回"},{"id":2561,"word":"peculiar","pronunciation":"/pɪ'kjʊljə(r)/","meaning":"adj.怪异的，奇怪的；特殊的","unit":9,"lesson":3,"seq":33,"isStar":false,"memo":"【构词】peculi-（私有，拉丁语peculium=私产）+ -ar →‘只属于你的怪癖’！比如室友坚持用Excel记奶茶订单，peculiar but harmless～","example":"The professor has a peculiar habit of quoting Shakespeare during physics lectures. 教授有个怪癖：物理课上动不动引用莎士比亚。","derivative":"peculiarity /pɪˌkjuːliˈærəti/ n.怪癖；特性"},{"id":2562,"word":"exotic","pronunciation":"/ɪɡˈzɒtɪk/","meaning":"adj.异国情调的；奇异的","unit":9,"lesson":3,"seq":34,"isStar":false,"memo":"【谐音】‘一个锁踢’——外国货被锁在海关踢来踢去，太‘异域’啦！【构词】ex-（外）+ otic（=otic, 来自希腊语‘外来’）→外来的。","example":"Students showed great curiosity about exotic plants in the botanical garden. 学生们对植物园里的异域植物表现出极大好奇。","derivative":"exotica /ɪg'zɒtɪkə/ n.异国风情事物总称"},{"id":2563,"word":"weird","pronunciation":"/wɪəd/","meaning":"adj.怪异的","unit":9,"lesson":3,"seq":35,"isStar":false,"memo":"谐音‘畏惧’——见到‘奇怪’东西，本能‘畏惧’！w+eird= weird，eird像‘eerie’（怪异的）","example":"It feels weird to take online exams without proctors. 没有监考员进行线上考试，感觉很奇怪。","derivative":"weirdness /ˈwɪədnəs/ n.怪异；反常"},{"id":2564,"word":"acquaint","pronunciation":"/əˈkweɪnt/","meaning":"v.使熟悉，使了解","unit":9,"lesson":3,"seq":36,"isStar":false},{"id":2565,"word":"alien","pronunciation":"/ˈeɪliən/","meaning":"n.外星人；外国人 adj.陌生的；外国的","unit":9,"lesson":3,"seq":37,"isStar":false,"memo":"【谐音+联想】'额里恩'→‘额头上长外星触角’！ali-（其他）+ -en（形容词），本义‘他者’，引申为‘陌生的/外国的’。","example":"The sudden policy shift made the regulatory environment feel alien to small businesses. 突然的政策转向让监管环境对小企业而言变得陌生。","derivative":"alienate /ˈeɪlɪəneɪt/ v.使疏远；alienation /ˌeɪliəˈneɪʃən/ n.疏离感"},{"id":2566,"word":"isolate","pronunciation":"/ˈaɪsəleɪt/","meaning":"v.(使)隔离，孤立","unit":9,"lesson":3,"seq":38,"isStar":false,"memo":"谐音+对照：‘爱锁来特’→病毒来了，医生立刻‘爱’上你、‘锁’进单间、‘来特’（let）你独处！和insulate比：isolate重人，insulate重物。","example":"Hospitals isolate patients with contagious diseases immediately. 医院立即隔离传染病患者。","derivative":"isolation /ˌaɪsə'leɪʃ(ə)n/ n.隔离；孤立"},{"id":2567,"word":"drama","pronunciation":"/ˈdrɑːmə/","meaning":"n.戏剧；戏剧性事件","unit":9,"lesson":3,"seq":39,"isStar":false},{"id":2568,"word":"comedy","pronunciation":"/ˈkɒmədi/","meaning":"n.喜剧；幽默","unit":9,"lesson":3,"seq":40,"isStar":false},{"id":2569,"word":"tragedy","pronunciation":"/ˈtrædʒədi/","meaning":"n.悲惨的事；悲剧","unit":9,"lesson":3,"seq":41,"isStar":false,"memo":"tra-（穿越）+ gedy（≈‘give it up’谐音梗）→ 穿越过去想拯救结局，结果还是‘悲剧’降临…莎士比亚式叹气。","example":"The oil spill was an environmental tragedy. 这起漏油事件是一场生态悲剧。","derivative":"tragic /ˈtrædʒɪk/ adj.悲剧的；悲惨的"},{"id":2570,"word":"disaster","pronunciation":"/dɪˈzæstə(r)/","meaning":"n.灾难；不幸","unit":9,"lesson":3,"seq":42,"isStar":false,"memo":"谐音+构词：'弟砸他'→弟弟一砸，灾难来了！di-（否定）+aster（星，古指吉星）→凶星降临即灾难。","example":"The software bug caused a major disaster in the university's registration system. 这个软件漏洞导致学校选课系统严重瘫痪。","derivative":"disastrous /dɪ'zɑːstrəs/ adj.灾难性的；disastrously /dɪ'zɑːstrəslɪ/ adv.灾难性地"},{"id":2571,"word":"feeble","pronunciation":"/ˈfiːbl/","meaning":"adj.虚弱的，衰弱的","unit":9,"lesson":3,"seq":43,"isStar":false,"memo":"fee（费）+ble（能）→‘缴费都费劲’？太虚弱啦！谐音‘废脖’→脖子都废了，站都站不稳～","example":"His feeble voice barely carried across the lecture hall. 他虚弱的声音几乎传不到讲堂对面。","derivative":"feebly /'fiːbli/ adv.虚弱地；feebleness /'fiːb(ə)lnəs/ n.虚弱"},{"id":2572,"word":"lean","pronunciation":"/liːn/","meaning":"v.倾斜；倚靠  adj.瘦且健康的","unit":9,"lesson":3,"seq":44,"isStar":false,"memo":"谐音‘临’——你靠墙‘临’着站，就是lean！v.倚靠；adj.瘦得只剩骨架，像‘临’风而立的竹子。","example":"She leaned against the lab bench while reviewing the data. 她靠在实验台边审阅数据。","derivative":"leanness /'liːnɪs/ n.清瘦；leaner /'liːnə/ n.较瘦者"},{"id":2573,"word":"shiver","pronunciation":"/ˈʃɪvə(r)/","meaning":"v. & n.(因寒冷、恐惧、激动等)颤抖，哆嗦","unit":9,"lesson":3,"seq":45,"isStar":false},{"id":2574,"word":"tremble","pronunciation":"/'trembl/","meaning":"v. & n.(因紧张、激动、惊慌等)颤抖，哆嗦；极担心","unit":9,"lesson":3,"seq":46,"isStar":false},{"id":2575,"word":"tender","pronunciation":"/'tenda(r)/","meaning":"adj.温柔的；(食物)嫩的；脆弱的","unit":9,"lesson":3,"seq":47,"isStar":false},{"id":2576,"word":"vulnerable","pronunciation":"/'vʌlnərəbl/","meaning":"adj.脆弱的；易受……伤害的","unit":9,"lesson":3,"seq":48,"isStar":false,"memo":"构词：vulner-（伤口）+ -able（能…的）→ 能被划伤的→脆弱的。像没穿铠甲的脆皮战士。","example":"Children are especially vulnerable to online misinformation. 儿童尤其容易受到网络虚假信息的伤害。","derivative":"vulnerability /ˌvʌlnərəˈbɪləti/ n.脆弱性；vulnerable /'vʌln(ə)rəb(ə)l/ adj.易受伤害的"},{"id":2577,"word":"feature","pronunciation":"/'fiːtʃə(r)/","meaning":"n.特色，特点，特征 v.以……为特色","unit":9,"lesson":3,"seq":49,"isStar":false},{"id":2578,"word":"trait","pronunciation":"/treɪt/","meaning":"n.(人的个性的)特征，特点","unit":9,"lesson":3,"seq":50,"isStar":false,"memo":"trait ≈ ‘trace’（痕迹）→ 一个人身上留下的性格‘特征’，比如爱拖延、爱记笔记、爱偷偷改PPT配色…都是trait！","example":"Patience is a key trait for effective teachers. 耐心是优秀教师的关键特质。"},{"id":2579,"word":"bacteria","pronunciation":"/bæk'tɪəriə/","meaning":"n.细菌","unit":9,"lesson":4,"seq":1,"isStar":false,"memo":"拆成 bac-（棒）+teria（小东西）→显微镜下像小棒子的细菌，谐音‘罢课它’——细菌一闹，全班罢课！","example":"Proper handwashing helps prevent the spread of bacteria in schools. 正确洗手有助于防止细菌在校园传播。","derivative":"bacterial /bækˈtɪərɪəl/ adj. 细菌的"},{"id":2580,"word":"virus","pronunciation":"/'vaɪrəs/","meaning":"n.病毒","unit":9,"lesson":4,"seq":2,"isStar":false,"memo":"【联想】‘Virus = Virus（维若斯）→维系网络的‘若斯’（罗斯）？错！它是偷偷‘维’护自己、‘若’无其事搞破坏的数字病毒！","example":"The IT department isolated the infected computer to prevent the virus from spreading across the network. IT部门隔离了受感染电脑以防病毒在网络中蔓延。","derivative":"viruses /'vaɪraɪz/ n.病毒（复数）"},{"id":2581,"word":"germ","pronunciation":"/dʒɜːm/","meaning":"n.细菌，微生物，病菌","unit":9,"lesson":4,"seq":3,"isStar":false},{"id":2582,"word":"allergic","pronunciation":"/ə'lɜːdʒɪk/","meaning":"adj.过敏的","unit":9,"lesson":4,"seq":4,"isStar":false,"memo":"谐音‘哦乐鸡’——‘哦！乐鸡（过敏）’！看到鸡毛就喊哦乐鸡！/ 构词：allerg(y)（过敏）+ -ic（形容词）。","example":"Many students are allergic to peanuts in the cafeteria. 许多学生对食堂的花生过敏。","derivative":"allergy /'ælədʒi/ n.过敏；过敏症"},{"id":2583,"word":"chemical","pronunciation":"/'kemɪkl/","meaning":"n.化学品 adj.化学的","unit":9,"lesson":4,"seq":5,"isStar":false},{"id":2584,"word":"initiate","pronunciation":"/ɪ'nɪʃieɪt/","meaning":"v.开始，发起，创始；使了解","unit":9,"lesson":4,"seq":6,"isStar":false,"memo":"构词：in-（入）+ iti（走，如exit）+ -ate→‘走进’一件事开头，即‘发起’！Initiate = in + it + i + ate（吃进去？不，是‘踏进去’！）","example":"The government will initiate a new policy on green education next term. 政府将于下学期启动绿色教育新政策。","derivative":"initiation /ˌɪnɪʃɪ'eɪʃ(ə)n/ n.开始；发起"},{"id":2585,"word":"initiative","pronunciation":"/ɪ'nɪʃətɪv/","meaning":"n.主动性，积极性；主动权；倡议","unit":9,"lesson":4,"seq":7,"isStar":false},{"id":2586,"word":"initial","pronunciation":"/'ɪnɪʃl/","meaning":"adj.最初的，开始的","unit":9,"lesson":4,"seq":8,"isStar":false,"memo":"【构词】in-（进入）+ iti-（开始，源自ire‘去’）+ -al → ‘刚进去’的状态→最初的；联想‘英式茶’——第一杯initial tea最提神！","example":"Her initial reaction to the policy change was confusion and skepticism. 她对政策变动的最初反应是困惑与怀疑。","derivative":"initially /ɪˈnɪʃəli/ adv.最初；起初"},{"id":2587,"word":"embark","pronunciation":"/ɪmˈbɑːk/","meaning":"v.上船；开始","unit":9,"lesson":4,"seq":9,"isStar":false},{"id":2588,"word":"launch","pronunciation":"/lɒntʃ/","meaning":"v.开始从事；发起；发射 n.(航天器的) 发射；(产品的)上市；(事件的)发起","unit":9,"lesson":4,"seq":10,"isStar":false,"memo":"【构词】l-（lift）+ aunch（≈ lunge猛冲）→ ‘抬升+猛冲’→ 发射！火箭点火那刻：‘浪冲！’","example":"They will launch the new app next Monday. 他们将于下周一上线新应用。","derivative":"launcher /'lɔːntʃə/ n.发射器；launching /'lɔːntʃɪŋ/ n.发行"},{"id":2589,"word":"minimum","pronunciation":"/ˈmɪnɪməm/","meaning":"n.最小值；最少量 adj.最低的；最小的","unit":9,"lesson":4,"seq":11,"isStar":false,"memo":"min-（小）+ -imum（最…）→ 最小值！记成‘民imum’：老百姓只求最低生活保障～","example":"The lab requires a minimum of three peer-reviewed sources for each thesis. 实验室要求每篇论文至少引用三篇同行评议文献。","derivative":"minimize /'mɪnɪmaɪz/ v.使最小化；减少"},{"id":2590,"word":"maximum","pronunciation":"/ˈmæksɪməm/","meaning":"n.最大量；最大限度 adj.最高的；最多的","unit":9,"lesson":4,"seq":12,"isStar":false,"memo":"max（最大缩写）+ -imum（名词后缀）→ 就是‘max值’！考试卷面分100，你考99？抱歉，maximum是100！","example":"The lab set the maximum safe voltage for the experiment. 实验室设定了该实验的安全最高电压。","derivative":"maximize /'mæksɪmaɪz/ v. 最大化"},{"id":2591,"word":"minimal","pronunciation":"/ˈmɪnɪməl/","meaning":"adj.极小的，极少的","unit":9,"lesson":4,"seq":13,"isStar":false},{"id":2592,"word":"miniature","pronunciation":"/ˈmɪnətʃə(r)/","meaning":"adj.微型的，小型的 n.微型画","unit":9,"lesson":4,"seq":14,"isStar":false,"memo":"【谐音+联想】‘迷你’+‘ature’（像nature自然）→迷你得像大自然缩微版！小到能放掌心的模型～","example":"The museum displayed a hand-painted miniature of the Forbidden City. 博物馆展出了手绘的紫禁城微缩模型。","derivative":"miniaturize /'mɪnɪtʃəraɪz/ v.使微型化；缩小"},{"id":2593,"word":"minority","pronunciation":"/maɪˈnɒrɪti/","meaning":"n.少数；少数民族","unit":9,"lesson":4,"seq":15,"isStar":false},{"id":2594,"word":"minimise","pronunciation":"/-ize/","meaning":"ˈmɪnɪmaɪz/ v.使减少到最低限度，使最小化；低估","unit":9,"lesson":4,"seq":16,"isStar":false},{"id":2595,"word":"maximise","pronunciation":"/-ize/","meaning":"ˈmæksɪmaɪz/ v.使增加到最大限度；充分利用","unit":9,"lesson":4,"seq":17,"isStar":false},{"id":2596,"word":"major","pronunciation":"/ˈmeɪdʒə(r)/","meaning":"adj.主要的；重大的 n.(大学的)主修科目，专业","unit":9,"lesson":4,"seq":18,"isStar":false},{"id":2597,"word":"mass","pronunciation":"/mæs/","meaning":"n.大量；群众 v.聚集 adj.大批的；数量极多的","unit":9,"lesson":4,"seq":19,"isStar":false,"memo":"谐音‘麻丝’——一堆乱麻缠成团，就是‘一堆/大量’！物理里是质量，社会里是群众（mass media大众媒体），adj.大规模的——麻丝太多，剪不断理还乱！","example":"The company launched a mass production of eco-friendly batteries. 公司启动了环保电池的大规模生产。","derivative":"massive /ˈmæsɪv/ adj.巨大的；massively /ˈmæsɪvli/ adv.大量地"},{"id":2598,"word":"massive","pronunciation":"/ˈmæsɪv/","meaning":"adj.大而重的；巨大的，强大的","unit":9,"lesson":4,"seq":20,"isStar":false},{"id":2599,"word":"tiny","pronunciation":"/ˈtaɪni/","meaning":"adj.极小的，微小的","unit":9,"lesson":4,"seq":21,"isStar":false},{"id":2600,"word":"parameter","pronunciation":"/pəˈræmɪtə(r)/","meaning":"n.范围，界限，参数","unit":9,"lesson":4,"seq":22,"isStar":false,"memo":"para-（旁边）+meter（测量）→在旁边划出的测量边界，即‘参数’或‘决定因素’！","example":"Age and education level are key parameters in this study. 年龄和教育程度是本研究的关键参数。","derivative":"parametric /ˌpærəˈmetrɪk/ adj. 参数的"},{"id":2601,"word":"metric","pronunciation":"/ˈmetrɪk/","meaning":"adj.米制的；公制的 n.度量工具，衡量指标","unit":9,"lesson":4,"seq":23,"isStar":false},{"id":2602,"word":"geometry","pronunciation":"/dʒiˈɒmɪtri/","meaning":"n.几何(学)；几何形状","unit":9,"lesson":4,"seq":24,"isStar":false},{"id":2603,"word":"symmetry","pronunciation":"/'simetri/","meaning":"n.对称","unit":9,"lesson":4,"seq":25,"isStar":false},{"id":2604,"word":"cemetery","pronunciation":"/'semətri/","meaning":"n.墓地，公墓","unit":9,"lesson":4,"seq":26,"isStar":false},{"id":2605,"word":"diameter","pronunciation":"/'daɪ'æmɪtə(r)/","meaning":"n.直径","unit":9,"lesson":4,"seq":27,"isStar":false},{"id":2606,"word":"thermometer","pronunciation":"/'θɜːmɒmɪtə(r)/","meaning":"n.温度计","unit":9,"lesson":4,"seq":28,"isStar":false},{"id":2607,"word":"paradise","pronunciation":"/'pærədais/","meaning":"n.天堂，乐园（指美好的环境）","unit":9,"lesson":4,"seq":29,"isStar":false},{"id":2608,"word":"paradox","pronunciation":"/'pærədoks/","meaning":"n.悖论；矛盾的人（或事物、情况）","unit":9,"lesson":4,"seq":30,"isStar":false,"memo":"para-（相反）+ dox（希腊语‘观点’）→ ‘相反的观点’，即自相矛盾的结论，比如‘越减肥越胖’这种让人挠头的悖论。","example":"Climate change presents a paradox: economic growth often harms environmental sustainability. 气候变化呈现悖论：经济增长常损害环境可持续性。","derivative":"paradoxical /ˌpærə'dɒksɪk(ə)l/ adj.自相矛盾的"},{"id":2609,"word":"orthodox","pronunciation":"/'ɔːθədɒks/","meaning":"adj.传统的，正统的","unit":9,"lesson":4,"seq":31,"isStar":false,"memo":"谐音+联想：‘奥特斗克思’→奥特曼打怪前先‘ orthodox ’（正统套路）：光之国规定动作不能乱改！ortho=正+dox=观点→正统观点。","example":"Many students challenge orthodox teaching methods in digital classrooms. 许多学生在数字课堂中挑战传统教学方法。","derivative":"orthodoxy /'ɔːθədɒksɪ/ n.正统观念；正统信仰"},{"id":2610,"word":"parade","pronunciation":"/'pə'reɪd/","meaning":"n.游行，阅兵；炫耀\tv.游行，炫耀","unit":9,"lesson":4,"seq":32,"isStar":false},{"id":2611,"word":"patrol","pronunciation":"/'pə'trəʊl/","meaning":"n & v.巡逻，巡查","unit":9,"lesson":4,"seq":33,"isStar":false},{"id":2612,"word":"cruise","pronunciation":"/'kruːz/","meaning":"v.乘船游览\tn.乘船游览；航行","unit":9,"lesson":4,"seq":34,"isStar":false},{"id":2613,"word":"patriot","pronunciation":"/'pætriət/","meaning":"n.爱国者","unit":9,"lesson":4,"seq":35,"isStar":false},{"id":2614,"word":"patriotic","pronunciation":"/'pætri'ɒtɪk/","meaning":"adj.爱国的","unit":9,"lesson":4,"seq":36,"isStar":false},{"id":2615,"word":"parasite","pronunciation":"/'pærəsaɪt/","meaning":"n.寄生虫；靠他人为生的人","unit":9,"lesson":4,"seq":37,"isStar":false,"memo":"联想 para-(旁边) + sit(坐) + e → 他总是坐在别人旁边,依附着别人,看起来就像个“寄生虫”。","example":"These flies carry a dangerous parasite. 这些苍蝇携带着一种危险的寄生虫。"},{"id":2616,"word":"paradigm","pronunciation":"/'pærədaɪm/","meaning":"n.范例，典范，样式","unit":9,"lesson":4,"seq":38,"isStar":false},{"id":2617,"word":"sense","pronunciation":"/sens/","meaning":"n.(对重大事情的)感觉,意识,见识,理智 v.感觉到,意识到,觉察出","unit":9,"lesson":4,"seq":39,"isStar":false,"memo":"谐音 单词发音类似“神似”→神似是一种“感觉”。","example":"Even an imagined companion can give the bird a sense of security. 即使是想象中的同伴也能给鸟儿一种安全感。","derivative":"sensible /'sensəbl/ adj.明智的,合理的;可感觉到的,明显的; sensitive /'sensətɪv/ adj.善解人意的;敏感的; sensitivity /ˌsensə'tɪvəti/ n.体贴;敏感性;灵敏度"},{"id":2618,"word":"sensible","pronunciation":"/'sensəbl/","meaning":"adj.明智的,合理的,可感觉到的,明显的","unit":9,"lesson":4,"seq":40,"isStar":false},{"id":2619,"word":"sensitive","pronunciation":"/'sensətɪv/","meaning":"adj.善解人意的,敏感的","unit":9,"lesson":4,"seq":41,"isStar":false,"memo":"sen-（感觉）+ -sitive（易…的）→ 感觉太‘敏’，风吹草动都‘感’觉得到！","example":"She is highly sensitive to cultural differences in classroom discussions. 她对课堂讨论中的文化差异极为敏感。","derivative":"sensitivity /ˌsensɪ'tɪvəti/ n.敏感性；敏感度"},{"id":2620,"word":"sensation","pronunciation":"/sen'seiʃn/","meaning":"n.知觉,感觉,轰动","unit":9,"lesson":4,"seq":42,"isStar":false,"example":"There wasn't any discomfort, just a mild warming sensation. 没有任何不适,只有轻微发热的感觉。","derivative":"sensational /sen'seɪʃənl/ adj.轰动的;耸人听闻的"},{"id":2621,"word":"sentiment","pronunciation":"/'sentɪmənt/","meaning":"n.(基于情感的)观点,看法,情绪","unit":9,"lesson":4,"seq":43,"isStar":false,"memo":"联想 sent(send 的过去式) + i(我) + m(联想“妹”) + ent → 假如你把我妹妹送出去,我是会闹“情绪”的。","example":"This is a sentiment I wholeheartedly agree with. 这种观点我完全赞同。","derivative":"sentimental /sentɪ'mentl/ adj.情感的;伤感的;多愁善感的"},{"id":2622,"word":"nonsense","pronunciation":"/'nɒnsns/","meaning":"n.胡扯,胡言乱语;毫无意义的话","unit":9,"lesson":4,"seq":44,"isStar":false,"example":"You're talking nonsense! 你在胡说八道!"},{"id":2623,"word":"intensive","pronunciation":"/ɪn'tensɪv/","meaning":"adj.加强的,密集的,彻底的,十分细致的","unit":9,"lesson":4,"seq":45,"isStar":false,"example":"They are intensive studies of people's spending...","derivative":"intense; intensity; intensify"},{"id":2624,"word":"intense","pronunciation":"/ɪn'tens/","meaning":"adj.很大的,十分强烈的,激烈的","unit":9,"lesson":4,"seq":46,"isStar":false,"example":"He is under intense pressure to resign.他承受着很大的辞职压力。","derivative":"intensity /ɪn'tensəti/ n.强烈;紧张\nintensify /n'tensɪfaɪ/ v.增强,加剧"},{"id":2625,"word":"dense","pronunciation":"/dens/","meaning":"adj.密集的,稠密的","unit":9,"lesson":4,"seq":47,"isStar":false,"derivative":"density; condense; condensation"},{"id":2626,"word":"condense","pronunciation":"/kən'dens/","meaning":"v.凝结,压缩,浓缩","unit":9,"lesson":4,"seq":48,"isStar":false,"memo":"con-(共同,一起)+dense(稠密的)→压缩;浓缩","example":"The mayor condensed his speech to allow time for his audience to raise questions.市长缩短了发言时间,以便给听众留出提问的时间。","derivative":"condensation /ˌkɒnden'seɪʃn/ n.冷凝,凝结"},{"id":2627,"word":"capital","pronunciation":"/'kæpɪtl/","meaning":"n.首都,资本,资金 adj.大写的","unit":9,"lesson":4,"seq":49,"isStar":false,"memo":"【谐音+联想】‘凯皮托尔’——首都（如华盛顿Capitol）像盖大楼一样‘凯’旋立‘皮’厚‘托’起国家核心！","example":"Beijing serves as China's political and cultural capital. 北京是中国的政治与文化首都。","derivative":"capitalism /ˈkæpɪtəlɪzəm/ n.资本主义；capitalist /ˈkæpɪtəlɪst/ n.资本家"},{"id":2628,"word":"capacity","pronunciation":"/kə'pesəti/","meaning":"n.容量；能力","unit":9,"lesson":4,"seq":50,"isStar":false,"memo":"cap（帽子，象征‘容纳’）+ acity（状态）→ 帽子能装几颗糖？就是‘容量’！脑子能装多少知识？就是‘能力’！一词双关，帽子真能装！","example":"His mental capacity impressed the neurologist during the test. 他在测试中展现的认知能力给神经科医生留下深刻印象。","derivative":"capacitor /kəˈpæsɪtə/ n.电容器"},{"id":2629,"word":"capable","pronunciation":"/'keɪpəbl/","meaning":"adj.有能力的；能力强的","unit":9,"lesson":4,"seq":51,"isStar":false,"memo":"cap-（头，引申为‘能力顶点’）+ -able（能…的）→ 头脑在线，就能干！谐音‘开炮able’——火力全开，稳稳能行！","example":"She is highly capable of leading complex research projects. 她完全有能力领导复杂的科研项目。","derivative":"capability /ˌkeɪpə'bɪləti/ n. 能力；性能"},{"id":2630,"word":"capture","pronunciation":"/'kæptʃə(r)/","meaning":"v.捕获 n.(被)捕获","unit":9,"lesson":4,"seq":52,"isStar":false,"memo":"【谐音】‘开扑彻’——警察开扑彻（扑上去）抓坏人！动词本义就是‘捕捉’。","example":"The drone captured stunning aerial footage of the campus. 无人机拍摄了校园震撼的空中影像。","derivative":"captivate /'kæptɪveɪt/ v.迷住；capturing /'kæptʃərɪŋ/ n.捕获；captured /'kæptʃəd/ adj.被俘获的"},{"id":2631,"word":"captive","pronunciation":"/'kæptɪv/","meaning":"adj.被监禁的 n.囚徒","unit":9,"lesson":4,"seq":53,"isStar":false},{"id":2632,"word":"capsule","pronunciation":"/'kæpsjuːl/","meaning":"n.(装药物的)胶囊；太空舱","unit":9,"lesson":4,"seq":54,"isStar":false},{"id":2633,"word":"caption","pronunciation":"/'kæpʃn/","meaning":"n.(图片、漫画等的)说明文字；(电视屏幕上的)字幕；标题","unit":9,"lesson":4,"seq":55,"isStar":false},{"id":2634,"word":"clutch","pronunciation":"/klʌtʃ/","meaning":"v.紧握；抓紧 n.控制；离合器","unit":9,"lesson":4,"seq":56,"isStar":false},{"id":2635,"word":"cape","pronunciation":"/keɪp/","meaning":"n.披风；斗篷；岬角","unit":9,"lesson":4,"seq":57,"isStar":false},{"id":2636,"word":"escape","pronunciation":"/'iːskeɪp/","meaning":"v.逃跑；逃避；摆脱 n.逃跑","unit":9,"lesson":4,"seq":58,"isStar":false},{"id":2637,"word":"cabin","pronunciation":"/'kæbɪn/","meaning":"n.小木屋；船舱；客舱","unit":9,"lesson":4,"seq":59,"isStar":false},{"id":2638,"word":"cabinet","pronunciation":"/'kæbɪnət/","meaning":"n.内阁；储藏柜；陈列柜","unit":9,"lesson":4,"seq":60,"isStar":false},{"id":2639,"word":"cable","pronunciation":"/'keɪbl/","meaning":"n.缆绳；电缆","unit":9,"lesson":4,"seq":61,"isStar":false,"memo":"谐音‘凯布尔’→‘凯旋的缆绳’！海底电缆扛着数据大军凯旋登陆～","example":"Fiber-optic cables now carry most international internet traffic. 光纤电缆现承载大部分国际互联网流量。","derivative":"cablecast /'keiblkɑːst/ v.有线电视转播"},{"id":2640,"word":"collide","pronunciation":"/kəˈlaɪd/","meaning":"v.碰撞，相撞；抵触，冲突","unit":10,"lesson":1,"seq":1,"isStar":false},{"id":2641,"word":"clash","pronunciation":"/klæʃ/","meaning":"n.冲突；不协调；撞击声 v.冲突；争论","unit":10,"lesson":1,"seq":2,"isStar":false},{"id":2642,"word":"crash","pronunciation":"/kræʃ/","meaning":"v.碰撞，撞击，坠毁；暴跌 n.撞车，碰撞","unit":10,"lesson":1,"seq":3,"isStar":false},{"id":2643,"word":"crush","pronunciation":"/krʌʃ/","meaning":"v.压碎，捣碎；镇压 n.(狭小空间中)拥挤的人群；迷恋","unit":10,"lesson":1,"seq":4,"isStar":false},{"id":2644,"word":"smash","pronunciation":"/smæʃ/","meaning":"n.破碎  v.打碎；猛击；粉碎","unit":10,"lesson":1,"seq":5,"isStar":false},{"id":2645,"word":"shatter","pronunciation":"/ˈʃætə(r)/","meaning":"v.(使)破碎，碎裂；使极为惊愕难过","unit":10,"lesson":1,"seq":6,"isStar":false},{"id":2646,"word":"crumble","pronunciation":"/ˈkrʌmbl/","meaning":"v.(使)粉碎；碎裂，崩裂，坍塌；崩溃","unit":10,"lesson":1,"seq":7,"isStar":false},{"id":2647,"word":"ashamed","pronunciation":"/əˈʃeɪmd/","meaning":"adj.惭愧的，羞愧的；尴尬的","unit":10,"lesson":1,"seq":8,"isStar":false,"memo":"联想 ash(灰) + a + me(我) + d(联想“的”) → 她说我的脸上有灰,我顿感“羞愧的”。","example":"He was ashamed of having asked such a silly question. 他因问了这样一个愚蠢的问题而感到羞愧。"},{"id":2648,"word":"collapse","pronunciation":"/kəˈlæps/","meaning":"n. & v.倒塌，坍塌；崩溃","unit":10,"lesson":1,"seq":9,"isStar":false,"memo":"联想 col-(都,一起) + lap(音似“来扑”) + se → 大家都来扑向这张床,结果床“坍塌”了。","example":"To our surprise, the roof collapsed under the weight of snow. 令我们惊讶的是,房顶在雪的重压下坍塌了。"},{"id":2649,"word":"elapse","pronunciation":"/ɪˈlæps/","meaning":"v.(时间)消逝，流逝","unit":10,"lesson":1,"seq":10,"isStar":false,"memo":"联想 e(字母音似“姨”) + lap(音似“来扑”) + se → 时光“流逝”,阿姨也长出了皱纹,原来谁也抓(留)不住时间。","example":"Many years had elapsed before they returned to their original urban areas. 多年以后,他们才回到原来的市区。"},{"id":2650,"word":"dome","pronunciation":"/dəʊm/","meaning":"n.穹顶，圆屋顶；圆顶状物","unit":10,"lesson":1,"seq":11,"isStar":false,"memo":"谐音‘兜米’——兜住一‘米’阳光的圆顶！dome = dom（统治，如domain）+ -e → 原指‘主宰性建筑’，今指穹顶，罩得住全场！","example":"The museum's glass dome allows natural light to flood the central hall. 博物馆的玻璃圆顶让自然光倾泻入中央大厅。","derivative":"domed /dəʊmd/ adj.有圆屋顶的"},{"id":2651,"word":"Catholic","pronunciation":"/ˈkæθəlik/","meaning":"adj.天主教的  n.天主教徒","unit":10,"lesson":1,"seq":12,"isStar":false},{"id":2652,"word":"chapel","pronunciation":"/ˈtʃæpəl/","meaning":"n.小教堂","unit":10,"lesson":1,"seq":13,"isStar":false},{"id":2653,"word":"domestic","pronunciation":"/dəˈmestɪk/","meaning":"adj.本国的，国内的；家用的；家庭的","unit":10,"lesson":1,"seq":14,"isStar":false,"memo":"【构词】dom-（家，拉丁 domus）+ -estic →‘家里的’！联想到‘domestic helper’（家政帮手）、‘domestic flight’（国内航班）。","example":"Domestic demand plays a crucial role in sustaining national economic growth. 国内需求在支撑国民经济增长中起关键作用。","derivative":"domesticate /dəˈmestɪkeɪt/ v.驯养；domestication /ˌdəmɛstɪˈkeɪʃən/ n.驯化"},{"id":2654,"word":"dominate","pronunciation":"/ˈdɒmɪneɪt/","meaning":"v.支配，统治，控制，影响；(在比赛中)占有优势，占据主动","unit":10,"lesson":1,"seq":15,"isStar":false},{"id":2655,"word":"dominance","pronunciation":"/ˈdɒminəns/","meaning":"n.优势；支配，控制","unit":10,"lesson":1,"seq":16,"isStar":false},{"id":2656,"word":"predominate","pronunciation":"/prɪˈdɒmɪneɪt/","meaning":"v.(在数量上)占优势；占主导地位","unit":10,"lesson":1,"seq":17,"isStar":false,"memo":"[构词] pre-(提前) + dominate(支配)→提前占据支配地位→占主导地位","example":"A person's life is predominated by traditional custom. 一个人的一生都受传统习俗的支配。"},{"id":2657,"word":"predominant","pronunciation":"/prɪˈdɒminənt/","meaning":"adj.显著的；盛行的；占优势的；主导的","unit":10,"lesson":1,"seq":18,"isStar":false,"example":"Information services will be predominant in the future. 未来,信息服务将占据主导地位。","derivative":"predominance /prɪ'dmɪnəns/ n.(数量上的)优势;主导地位"},{"id":2658,"word":"control","pronunciation":"/'kɒn'trəʊl/","meaning":"v. 指挥；控制，支配 n. 管理，控制，支配","unit":10,"lesson":1,"seq":19,"isStar":false,"example":"Man can't be controlled by computers. 人不能被电脑控制。"},{"id":2659,"word":"manipulate","pronunciation":"/mə'nɪpjuleɪt/","meaning":"v. 操纵，控制；（熟练地）操作，使用","unit":10,"lesson":1,"seq":20,"isStar":false,"memo":"[谐音] 单词发音类似“摸你扑了它”→工作的时候,你一会儿摸摸这台机器,一会儿扑向那台机器,说明你能“熟练地操作”它们。","example":"The technology uses a pen to manipulate a computer. 这项技术使用一支笔来操作计算机。","derivative":"manipulation /mənɪpju'leʃn/ n.操纵,(暗中)控制\nmanipulative /mə'nɪpjələtɪv/ adj.善于操纵的;会控制的"},{"id":2660,"word":"moderate","pronunciation":"/'mɒdərət/","meaning":"v. (使)缓和，(使)减轻；节制，克制","unit":10,"lesson":1,"seq":21,"isStar":false,"memo":"[联想] mode(联想 model) + rate(速度)→模特走路的速度是“适度的”。","example":"Moderate levels of conflict can motivate people. 适度的争论可以激励人们。","derivative":"moderation /ˌmɒdə'reɪʃn/ n.适度,适中\nmoderator /'mɒdəreɪtə(r)/ n.调解人,调停人"},{"id":2661,"word":"accelerate","pronunciation":"/æk'seləreɪt/","meaning":"v. (使) 加速，加快","unit":10,"lesson":1,"seq":22,"isStar":false,"memo":"[联想] ac-(一再地)+cele(音似“赛了”)+rate(速度)→一再地比赛,到了最后阶段需要“加速”。","example":"It would accelerate the progress of AI research. 这将加速人工智能研究的进展。"},{"id":2662,"word":"tolerate","pronunciation":"/'tɒləreɪt/","meaning":"v. 容忍，容许；忍受，忍耐","unit":10,"lesson":1,"seq":23,"isStar":false,"memo":"联想 tole(音似“逃了”) + rate(速度)→他以很快的速度逃跑了,因为“忍受”不了了。","example":"Reporters can tolerate rejection of their ideas if they get a fair hearing. 如果记者们的观点得到了公平的听取,那么他们就可以容忍别人的反对。","derivative":"tolerant /'tɒlərənt/ adj.容忍的;宽容的 tolerance /'tɒlərəns/ n.忍受;宽容 tolerable /'tɒlərəbl/ adj.可接受的;可忍受的"},{"id":2663,"word":"endure","pronunciation":"/ɪn'djuə(r)/","meaning":"v. 忍受；持续存在","unit":10,"lesson":1,"seq":24,"isStar":false,"memo":"联想 end(最后) + u(字母音同 you) + re (字母音似“阿姨”)→最后你实在“忍受”不了阿姨的唠叨了。","example":"It's never a question of whether you enjoy your job and your life, but only how much you can endure. 问题从来不在于你是否喜欢自己的工作和生活,而仅仅在于你能忍受多少。","derivative":"endurance /ɪn'djʊərəns/ n.忍耐力,耐久力"},{"id":2664,"word":"duration","pronunciation":"/djʊ'reɪʃn/","meaning":"n. 持续，持续时间","unit":10,"lesson":1,"seq":25,"isStar":false,"memo":"构词 dur(持续,持久) + -ation(名词后缀)→持续,持续时间","example":"His wounds knocked him out of combat for the duration. 在整个战斗期间,他的伤一直令他无法参战。"},{"id":2665,"word":"tenure","pronunciation":"/'tenjə(r)/","meaning":"n. 任期，任职","unit":10,"lesson":1,"seq":26,"isStar":false},{"id":2666,"word":"evaporate","pronunciation":"/ɪ'væpəreɪt/","meaning":"v. (使)蒸发，挥发；(逐渐)消失","unit":10,"lesson":1,"seq":27,"isStar":false,"memo":"构词 e-(向外) + vapor(蒸汽) + -ate(动词后缀)→(使)蒸发,挥发","example":"Water evaporates and rises as visible drops to form clouds. 水蒸发后上升,变成可见的水滴进而形成云。","derivative":"evaporation /ɪˌvæpə'reɪʃn/ n.蒸发;(逐渐)消失"},{"id":2667,"word":"vanish","pronunciation":"/'vænɪʃ/","meaning":"v. 突然消失；不存在","unit":10,"lesson":1,"seq":28,"isStar":false,"memo":"谐音 单词发音类似“哇,你失”→哇,你“突然消失”不见了。","example":"My glasses seem to have vanished. 我的眼镜似乎不翼而飞了。"},{"id":2668,"word":"hamper","pronunciation":"/'hæmpə(r)/","meaning":"v. 妨碍，阻止","unit":10,"lesson":1,"seq":29,"isStar":false,"memo":"[联想] ham(联想“汉姆”,人名)+p(联想“扑”)+er(联想“表示人的后缀”)→汉姆扑在一个人身上,“阻止”对方进球。","example":"The program has been hampered by lack of funds. 该计划因缺乏资金而受到阻碍。"},{"id":2669,"word":"hinder","pronunciation":"/'hɪndə(r)/","meaning":"v. 妨碍，阻碍","unit":10,"lesson":1,"seq":30,"isStar":false,"memo":"[谐音] 单词发音类似“恨得”→她恨这个人恨得牙痒痒,想要“阻碍”他继续行事。","example":"Climate change hinders economic development. 气候变化阻碍了经济发展。","derivative":"hindrance /'hindrəns/ n. 妨碍;造成妨碍的人(或物)"},{"id":2670,"word":"obstacle","pronunciation":"/'obstokl/","meaning":"n.障碍，阻碍","unit":10,"lesson":1,"seq":31,"isStar":false,"memo":"[谐音] 单词发音类似“哦,不是特抠”→我不是特别抠,我只是面临经济“障碍”。","example":"Age is not a major obstacle to their employment. 年龄并不是他们就业的主要障碍。"},{"id":2671,"word":"prevent","pronunciation":"/prɪ'vent/","meaning":"v.阻止，阻碍","unit":10,"lesson":1,"seq":32,"isStar":false,"memo":"[联想] pre-(前面)+vent(联想 went)→他走到我们前面,试图“阻止”我们。","example":"The new system helps to prevent hackers from breaking into websites. 这个新系统有助于防止黑客入侵网站。","derivative":"prevention /ˌprev'enʃn/ n.预防;防止\npreventive /prɪ'ventɪv/ adj.预防性的,防备的"},{"id":2672,"word":"exclude","pronunciation":"/ɪk'skluːd/","meaning":"v.不包括，不放在考虑之列；把……排斥在外 adj.独有的，排外的","unit":10,"lesson":1,"seq":33,"isStar":false,"memo":"[构词] ex-(外)+clud(=close)+e→把……关在外面→不包括;把……排斥在外","example":"They exclude those who have stopped looking for a job. 他们排除了那些已经停止找工作的人。","derivative":"exclusive /k'skluːsv/ n.独家新闻,独家报道 adj.独有的;排外的\nexclusion /ˌɪk'skluːʒn/ n.排斥;排除在外"},{"id":2673,"word":"conclude","pronunciation":"/kən'kluːd/","meaning":"v.得出结论；总结；结束","unit":10,"lesson":1,"seq":34,"isStar":false,"memo":"[构词] con-(所有)+clud(=close)+e→所有的都关闭了→结束","example":"Before the conference was over, I would conclude another 10 points. 会议结束前,我再总结十点。","derivative":"conclusive /kən'kluːsɪv/ adj.结论性的\nconclusion /kən'kluːʒn/ n.结论;结束"},{"id":2674,"word":"eliminate","pronunciation":"/ɪ'lɪmɪneɪt/","meaning":"v.排除，消除；（比赛中）淘汰","unit":10,"lesson":1,"seq":35,"isStar":false,"memo":"[构词] e-(出)+limin(限制)+-ate(动词后缀)→从限制中出去→排除,消除","example":"In the first round of the competition, three teams were eliminated. 比赛的第一轮淘汰了三支队伍。","derivative":"elimination /ɪˌlmɪ'neɪn/ n.排除;淘汰;消灭"},{"id":2675,"word":"discharge","pronunciation":"/dɪs'tʃɑːdʒ/","meaning":"v.排出；释放；解雇；准许离开","unit":10,"lesson":1,"seq":36,"isStar":false,"memo":"[构词] dis-(否定前缀)+charge(使承担责任)→不用承担责任→释放;准许离开","example":"The child had been treated and was being prepared for discharge. 这个孩子已经接受了治疗,目前正在准备出院。","derivative":"/ds'tʃɑːdʒ/ n.排出(物);出院;免职"},{"id":2676,"word":"convenience","pronunciation":"/kən'viːniəns/","meaning":"n.方便，便利；便利设施","unit":10,"lesson":1,"seq":37,"isStar":false,"memo":"[联想] con-(所有,都)+venien(音似“为您”)+ce→所有服务都是为了您的“方便”。","example":"It's no accident that most gas stations have..."},{"id":2677,"word":"handy","pronunciation":"/'hændi/","meaning":"adj.手边的，就近的；方便的，便利的","unit":10,"lesson":1,"seq":38,"isStar":false,"memo":"【构词】hand（手）+ -y（形容词后缀）→手边的；方便的","example":"The girl is hurt, but we have no handy substitute. 这个女孩受伤了，但我们手边没有替补。"},{"id":2678,"word":"convince","pronunciation":"/kən'vɪns/","meaning":"v.使确信；使信服；说服","unit":10,"lesson":1,"seq":39,"isStar":false,"memo":"【联想】con-（一起，都）+ vince（音似“吻死”）→我们都使劲地亲吻你，想使你确信，我们真的爱你→使确信","example":"You will be pleased to convince people with good arguments. 你会很乐意用有力的论据来说服人们。","derivative":"convincing /kənˈvɪnsɪŋ/ adj.令人信服的，有说服力的"},{"id":2679,"word":"automate","pronunciation":"/'ɔːtəmeɪt/","meaning":"v.使自动化","unit":10,"lesson":1,"seq":40,"isStar":false,"memo":"【联想】auto-（自动的）+ m（联想 move）+ -ate（动词后缀）→使自动化","example":"They would need to automate its manufacturing and service industries. 他们需要实现制造业和服务业的自动化。","derivative":"automation /ˌɔːtəˈmeɪʃn/ n.自动化"},{"id":2680,"word":"automatic","pronunciation":"/,ɔːtə'mætɪk/","meaning":"n.自动换挡汽车 adj.自动的，自动化的；无意识的","unit":10,"lesson":1,"seq":41,"isStar":false,"memo":"【对照】automate v.使自动化→automatic n. & adj.","example":"My camera has manual and automatic functions. 我的照相机有手调和自动两种功能。","derivative":"automatically /ˌːtəˈmætɪkli/ adv.自动地；无意识地"},{"id":2681,"word":"vehicle","pronunciation":"/'vi:ıkl/","meaning":"n.交通工具,车辆;手段,工具","unit":10,"lesson":1,"seq":42,"isStar":false,"memo":"【谐音】单词发音类似“违要扣”→“车辆”等“交通工具”违规行驶要扣分。","example":"Motor vehicles are important contributors to urban air pollution. 机动车是造成城市空气污染的重要因素。"},{"id":2682,"word":"saddle","pronunciation":"/'sædl/","meaning":"n.马鞍;(自行车或摩托车的)车座 v.给(马)备鞍","unit":10,"lesson":1,"seq":43,"isStar":false,"memo":"【谐音】单词发音类似“赛道”→在赛道上骑马要配备“马鞍”。","example":"Raise your head a little bit and hold the saddle. 稍微抬起头，握住马鞍。"},{"id":2683,"word":"pedal","pronunciation":"/'pedl/","meaning":"n.(自行车等的)踏板;(钢琴、风琴等的)踏板 v.骑自行车;踩踏板","unit":10,"lesson":1,"seq":44,"isStar":false,"memo":"【谐音】单词发音类似“拍打”→拍打的节奏和“踩踏板”的节奏类似。","example":"She pressed her foot down sharply on the brake pedal. 她猛踩刹车踏板。"},{"id":2684,"word":"pedestrian","pronunciation":"/pe'destrian/","meaning":"n.行人,步行者 adj.行人的;平庸乏味的","unit":10,"lesson":1,"seq":45,"isStar":false,"memo":"【联想】pede（联想 pedal）+ str（联想 street）+ -ian（表示人的后缀）→他骑自行车穿过大街，“行人”纷纷避让。","example":"His style is so pedestrian that the book becomes a real bore. 他的文风很平庸，以致那本书成了一本真正乏味的书。"},{"id":2685,"word":"array","pronunciation":"/ə'reɪ/","meaning":"n.大量;排列 v.排列","unit":10,"lesson":1,"seq":46,"isStar":false,"memo":"联想 ar-(一再)+ray(光线)→一再地将“大量”珠宝“排列”在光线下。","example":"We saw arrays of fruit and vegetables. 我们看到了大量水果蔬菜。"},{"id":2686,"word":"display","pronunciation":"/di'spleɪ/","meaning":"v.陈列,展出,展示;显露,显示 n.陈列,展览;展示,表演","unit":10,"lesson":1,"seq":47,"isStar":false,"memo":"联想 dis(音似“弟死”)+play(玩)→弟弟死活要玩玩具,因为他想给客人“展示”一下。","example":"They have a better view of what are on display. 他们对所展示的物品有更好的看法。"},{"id":2687,"word":"exhibit","pronunciation":"/ɪg'zɪbɪt/","meaning":"n.展览品,陈列品 v.展出,陈列","unit":10,"lesson":1,"seq":48,"isStar":false,"memo":"联想 ex-(向外)+hibi(联想 Hebe,人名)+t(联想“她”)→Hebe 把她的作品向外展示→展出","example":"I heard the recent sculpture exhibit was kind of disappointing. 我听说最近的雕塑展有点令人失望。","derivative":"exhibition /ˌeksɪ'bɪʃn/ n.展览(品);展示"},{"id":2688,"word":"inhibit","pronunciation":"/ɪn'hɪbɪt/","meaning":"v.阻止,阻碍;抑制;使拘束","unit":10,"lesson":1,"seq":49,"isStar":false,"memo":"联想 in(里面)+hibi(联想 Hebe,人名)+t(联想“他”)→Hebe 在里面“阻止”他出来。","example":"The managing director's presence inhibited them from asking questions. 总经理的在场使他们不便问问题。","derivative":"inhibition /ˌɪnh'bɪʃn/ n.阻止;禁止"},{"id":2689,"word":"prohibit","pronunciation":"/prə'hɪbɪt/","meaning":"v.禁止,阻止","unit":10,"lesson":1,"seq":50,"isStar":false,"memo":"联想 pro-(前面)+hibi(联想 Hebe,人名)+t(联想“他”)→Hebe 站在他的前面,“阻止”他离开。","example":"The high cost of equipment prohibits many people from taking up this sport. 昂贵的装备令许多人对这项运动望而却步。","derivative":"prohibition /ˌprəʊɪ'bɪʃn/ n.(尤指通过法律的)禁止,阻止\nprohibitive /prə'hɪbətɪv/ adj.(以法令)禁止的;贵得买不起的"},{"id":2690,"word":"choke","pronunciation":"/tʃəʊk/","meaning":"v.(使)窒息,卡住;(使)哽噎;堵塞 n.窒息;哽噎","unit":10,"lesson":1,"seq":51,"isStar":false,"memo":"谐音 单词发音类似“撬开”→医生撬开婴儿的嘴,取出了“卡住”的鱼刺。","example":"Very small toys can choke a baby. 很小的玩具可使婴儿窒息。"},{"id":2691,"word":"embrace","pronunciation":"/ɪm'breɪs/","meaning":"v.拥抱;包括,包含;欣然接受","unit":10,"lesson":1,"seq":52,"isStar":false,"memo":"构词 em-(使,进入)+brace(手臂)→使进入手臂→拥抱","example":"It's imperative for us to embrace a workplace revolution. 我们必须迎接一场职场变革。"},{"id":2692,"word":"mobile","pronunciation":"/'məʊbaɪl/","meaning":"adj.可移动的","unit":10,"lesson":1,"seq":53,"isStar":false,"memo":"构词 mob(= move) + -ile(形容词后缀)→可移动的","example":"It's illegal to chat into a hand-held mobile phone while driving. 开车时使用手持移动电话聊天是违法的。","derivative":"mobilise/-ize /'məʊbəlaɪz/ v.组织,动员;调用"},{"id":2693,"word":"emotion","pronunciation":"/ɪ'məʊʃn/","meaning":"n.情感,情绪","unit":10,"lesson":1,"seq":54,"isStar":false,"memo":"构词 e-(向外) + motion(移动)→向外移动、流露出来的东西→情感,情绪","example":"Suppressed emotions can contribute to stress-related disorders. 情绪压抑会导致与压力相关的疾病。","derivative":"emotional /ɪ'məʊʃənl/ adj.情绪的;情绪激动的;有感染力的"},{"id":2694,"word":"rational","pronunciation":"/'reʃnl/","meaning":"adj.合理的,理性的;理智的","unit":10,"lesson":1,"seq":55,"isStar":false,"memo":"联想 ratio(比率) + n(a)(联想“拿”) + -al(形容词后缀)→他总是拿比率作依据,是个很“理性的”人。","example":"I suggest that students should be more rational when it comes to certificates. 我建议学生在证书问题上应该更加理性。"},{"id":2695,"word":"irrational","pronunciation":"/ɪ'ræʃənl/","meaning":"adj.不合理的,不理性的","unit":10,"lesson":1,"seq":56,"isStar":false},{"id":2696,"word":"motivate","pronunciation":"/'maʊtɪveɪt/","meaning":"v.成为……的动机;激发,激励","unit":10,"lesson":1,"seq":57,"isStar":false,"memo":"构词 motiv(e)(动机) + -ate(动词后缀)→使有动机→成为……的动机;激发","example":"The murder was motivated by hatred. 这起谋杀是由仇恨激起的。","derivative":"motivation /ˌməʊtɪ'veɪʃn/ n.动机;动力"},{"id":2697,"word":"motel","pronunciation":"/ˈməʊˈtel/","meaning":"n.汽车旅馆","unit":10,"lesson":1,"seq":58,"isStar":false,"memo":"构词 mo(= motor,汽车) + tel(= hotel,旅馆)→汽车旅馆","example":"Let's find a motel so that we can get an early start tomorrow. 我们去找个汽车旅馆,这样明天就可以早点出发了。"},{"id":2698,"word":"promote","pronunciation":"/prəˈməʊt/","meaning":"v.促进，推动；提升；推销","unit":10,"lesson":1,"seq":59,"isStar":false,"memo":"构词 pro-(向前) + mot(= move) + e→向前移动→促进,推动","derivative":"promotion; prompt 形近 impromptu; impetus 相关 impulse; impulsive 扩 pulse 走跑 antagonism 形近"},{"id":2699,"word":"remote","pronunciation":"/rɪˈməʊt/","meaning":"adj.遥远的；疏远的；远程的","unit":10,"lesson":1,"seq":60,"isStar":false,"memo":"【构词】re-(回) + mot( = move) + e→往回移动,离目标越来越远→遥远的","example":"In remote mountain areas, voters arrived on horseback. 在偏远山区,选民们骑马赶来。"},{"id":2700,"word":"prompt","pronunciation":"/prɒmpt/","meaning":"adj.立即的 v.促使；激励 n.提示","unit":10,"lesson":1,"seq":61,"isStar":false,"memo":"【联想】pro-(在前) + m(联想“妹”) + pt(联想“扑他”)→妹妹看到面前的哥哥,立即扑向他→立即的","example":"Professors can give prompt feedback to students' homework. 教授可以对学生的家庭作业给予及时的反馈。"},{"id":2701,"word":"impromptu","pronunciation":"/ɪmˈprɒmptjuː/","meaning":"adj. & adv.无准备的/地；即兴的/地","unit":10,"lesson":1,"seq":62,"isStar":false},{"id":2702,"word":"agitate","pronunciation":"/ˈædʒɪteɪt/","meaning":"v.鼓动，煽动；使焦虑不安；搅动","unit":10,"lesson":1,"seq":63,"isStar":false,"memo":"【谐音】单词发音类似“爱激他的”→你总是爱用话语激他→煽动","example":"The speaker is agitating for the repeal of a tax. 这位演讲者在鼓动废除一项征税。","derivative":"agitation /ˌædʒˈteɪʃn/ n.焦虑不安;煽动"},{"id":2703,"word":"antagonism","pronunciation":"/ænˈtaɡənɪzəm/","meaning":"n.对抗情绪；敌对；敌意","unit":10,"lesson":1,"seq":64,"isStar":false,"memo":"【联想】ant(i)-(对抗) + agon(联想 agony,痛苦) + -ism(名词后缀)→痛苦源于“对抗情绪”。","example":"The antagonism he felt towards his old enemy was still very strong. 他对宿敌的敌意仍然十分强烈。"},{"id":2704,"word":"impetus","pronunciation":"/ˈɪmpɪtəs/","meaning":"n.动力；推动","unit":10,"lesson":1,"seq":65,"isStar":false,"memo":"【联想】im-( = in-,里面) + pet(宠物) + us(我们)→在家里养宠物,可以“推动”我们责任感的培养。","example":"The debate seems to have lost much of its initial impetus. 辩论会似乎没有开始时那么大的冲劲了。"},{"id":2705,"word":"impulse","pronunciation":"/ˈɪmpʌls/","meaning":"n.冲动，心血来潮；推动力；刺激","unit":10,"lesson":1,"seq":66,"isStar":false,"memo":"【联想】im-( = in-,里面) + pul(联想“扑了”) + se→内心的“冲动”让我想要扑过去。","example":"Natural impulses of anger are expressed through acts of violence. 愤怒的自然冲动会通过暴力行为表现出来。","derivative":"impulsive /ɪmˈpʌlsɪv/ adj.凭冲动行事的;易冲动的"},{"id":2706,"word":"pulse","pronunciation":"/pʌls/","meaning":"n.脉搏 v.搏动，跳动","unit":10,"lesson":1,"seq":67,"isStar":false,"memo":"【对照】人在冲动(impulse)时,脉搏(pulse)跳得很快。","example":"His heart pulsed with excitement. 他的心激动地怦怦直跳。"},{"id":2707,"word":"locomotive","pronunciation":"/ˌləʊkəˈməʊtɪv/","meaning":"n.机车；火车头 adj.移动的，运动的","unit":10,"lesson":1,"seq":68,"isStar":false,"memo":"【联想】loco(音似“唠嗑”) + mot( = move) + -ive(后缀)→他们在“移动的”“火车头”里唠。","example":"Energy to drive a steam locomotive can be stored. 驱动蒸汽机车的能量可以被储存。"},{"id":2708,"word":"loom","pronunciation":"/luːm/","meaning":"v.赫然显现；（尤指）令人惊恐地隐现；显得突出；逼近 n.织布机","unit":10,"lesson":1,"seq":69,"isStar":false,"memo":"联想 loo(形似100)+m(联想“妹”)→100米外有个妹妹，在人群中“显得突出”。","example":"Today Mars looms as humanity's next area to explore. 如今，火星隐约成为人类下一个要探索的领域。"},{"id":2709,"word":"boom","pronunciation":"/buːm/","meaning":"n.繁荣，激增；流行 v.繁荣；隆隆作响","unit":10,"lesson":1,"seq":70,"isStar":false,"memo":"联想 boo(形似600)+m(联想meter)→方圆600米内都是一派“繁荣”的景象。","example":"The thunder boomed like a cannon. 雷声隆隆，像大炮一样。"},{"id":2710,"word":"flourish","pronunciation":"/ˈflʌrɪʃ/","meaning":"v.繁荣；兴旺；茁壮成长","unit":10,"lesson":1,"seq":72,"isStar":false,"memo":"构词 flour(=flower)+-ish(动词后缀)→像开花一样→繁荣；茁壮成长","example":"The company has continued to flourish over the years. 该公司多年来一直蓬勃发展。"},{"id":2711,"word":"bloom","pronunciation":"/bluːm/","meaning":"v.开花；兴旺 n.花朵","unit":10,"lesson":1,"seq":73,"isStar":false,"memo":"联想 bloo(形似6,100)+m(联想“妹”)→花园里的6,100朵花在妹妹的精心照料下“开花”了。","example":"With the development in science and technology, man can make various flowers bloom before their time. 随着科学技术的发展，人们可以使各种各样的花提前绽放。"},{"id":2712,"word":"gloom","pronunciation":"/gluːm/","meaning":"n.忧郁，愁闷，无望；幽暗，黑暗，昏暗","unit":10,"lesson":1,"seq":74,"isStar":false},{"id":2713,"word":"elect","pronunciation":"/'ɪlekt/","meaning":"v.选举，推选；选择，决定（做某事） n.选修课程","unit":10,"lesson":2,"seq":1,"isStar":false,"memo":"构词 e-(出) + lect(选择) → 选择出 → 选举;选择","example":"He has been successfully elected Prime Minister. 他已成功当选首相。","derivative":"election /ɪˈlekʃn/ n.选举,推选(尤指从政); elective /ɪˈlektɪv/ adj.选举的;可选择的;选修的 n.选修课程"},{"id":2714,"word":"select","pronunciation":"/sɪ'lekt/","meaning":"v.选择；挑选","unit":10,"lesson":2,"seq":2,"isStar":false,"memo":"构词 se-(分开) + lect(选择) → 挑选","example":"He hasn't been selected for the team. 他未能入选该队。","derivative":"selection /sɪˈlekʃn/ n.选择,挑选;选拔; selective /sɪˈlektɪv/ adj.选择性的,有选择的"},{"id":2715,"word":"collective","pronunciation":"/'kɒl'ektɪv/","meaning":"adj.集体的，共有的，共同的","unit":10,"lesson":2,"seq":3,"isStar":false,"memo":"构词 collect(收集) + -ive(形容词后缀) → 收集在一起的 → 集体的,共有的","example":"It was a collective decision. 这是集体的决定。"},{"id":2716,"word":"neglect","pronunciation":"/nɪ'glect/","meaning":"v.疏于照顾；忽视，不予重视；疏漏，疏忽 n.忽略，忽视","unit":10,"lesson":2,"seq":4,"isStar":false,"memo":"构词 neg-(未) + lect(选择) → 未选 → 忽视;疏漏","example":"They tend to neglect training in analytical skills. 他们往往会忽视分析技能的训练。","derivative":"n.忽略,忽视; neglectful /nɪˈɡlektfl/ adj.马虎的;不重视的;忽视的"},{"id":2717,"word":"negligible","pronunciation":"/'neglɪdʒəbl/","meaning":"adj.可以忽视的，微不足道的，不值得一提的","unit":10,"lesson":2,"seq":5,"isStar":false,"memo":"对照 neglect v.&n.忽视 → negligible adj.","example":"Although most birds have only a negligible sense of smell, they have acute vision. 虽然大多数鸟类只有微弱的嗅觉,但它们的视力却非常敏锐。"},{"id":2718,"word":"negligent","pronunciation":"/'neglɪdʒənt/","meaning":"adj.疏忽的；放松的；漫不经心的","unit":10,"lesson":2,"seq":6,"isStar":false,"example":"He waved his hand in a negligent gesture. 他漫不经心地挥了挥手。"},{"id":2719,"word":"ignore","pronunciation":"/ɪɡ'nɔː(r)/","meaning":"v.忽视，对……不予理会，不予理睬","unit":10,"lesson":2,"seq":7,"isStar":false,"memo":"谐音 单词发音类似“一个闹”→他面对一个吵闹的人所采取的行动就是“忽视”对方。","example":"It ignores the fact that you are now beginning to be responsible for yourself. 它忽略了一个事实,那就是你现在开始要对自己负责了。"},{"id":2720,"word":"ignorant","pronunciation":"/'ɪɡnərənt/","meaning":"adj.无知的，愚昧的；很无礼的","unit":10,"lesson":2,"seq":8,"isStar":false,"example":"It is not so bad being ignorant if you are totally ignorant. 如果你完全无知，那么无知也不是坏事。","derivative":"ignorance /'ɡnərəns/ n.无知"},{"id":2721,"word":"annoy","pronunciation":"/ə'noɪ/","meaning":"v.使恼怒，使生气；打扰","unit":10,"lesson":2,"seq":9,"isStar":false,"memo":"[联想] an(一个) + noy(音似“闹”) → 这个小孩一个劲地闹，着实让家长生气 → 使生气","example":"Her twin sister often brings friends home and this annoys her. 她的双胞胎妹妹经常带朋友回家，这让她很恼火。"},{"id":2722,"word":"notion","pronunciation":"/'nəʊʃn/","meaning":"n.观念，想法","unit":10,"lesson":2,"seq":10,"isStar":false,"memo":"[谐音] 单词发音类似“闹心”→女儿错误的“想法”使我很闹心。","example":"We should form the notion that waste is quite shameful. 我们应该形成浪费非常可耻的观念。"},{"id":2723,"word":"lecture","pronunciation":"/'lektʃə(r)/","meaning":"n.(通常指大学里的)讲座，讲课，演讲 v.(尤指在大学里)开讲座，讲授，讲课","unit":10,"lesson":2,"seq":11,"isStar":false,"memo":"[构词] lect(说，讲) + -ure(后缀) → 讲座，讲课，演讲","example":"She gave lectures on how to become a public speaker. 她举办了关于如何成为一名公众演说家的讲座。","derivative":"lecturer /'lektʃərə(r)/ n.讲课者，演讲者"},{"id":2724,"word":"dialect","pronunciation":"/'daɪəlekt/","meaning":"n.方言，土话","unit":10,"lesson":2,"seq":12,"isStar":false,"memo":"[联想] dia(联想“嗲”) + lect(说) → 他们说的“方言”听起来很嗲。","example":"It was difficult to understand the local dialect. 这种当地的方言很难懂。"},{"id":2725,"word":"dispute","pronunciation":"/dɪ'spjuːt/","meaning":"n.争论，辩论，纠纷 v.对……表示异议（或怀疑）","unit":10,"lesson":2,"seq":13,"isStar":false,"memo":"[构词] dis-(分开) + put(思考) + e → 不同的思考，想法不一 → 争论","example":"It could lead to more out-of-court settlements of such disputes. 这可能会导致更多此类纠纷的庭外和解。","derivative":"disputable /dɪ'spjuːtəbl/ adj.可质疑的；可商榷的"},{"id":2726,"word":"debate","pronunciation":"/dɪ'beɪt/","meaning":"n. & v.争论，辩论","unit":10,"lesson":2,"seq":14,"isStar":false,"memo":"[构词] de-(往下) + bat(= beat) + e → 把对手往下打 → 争论，辩论","example":"There was a most irritating end to every one of these debates. 每次这样的辩论都以一种极其令人恼火的方式收场。"},{"id":2727,"word":"beat","pronunciation":"/bit/","meaning":"v.打败（某人），敲打 n.跳动（声），击鼓声，振翅声","unit":10,"lesson":2,"seq":15,"isStar":false,"example":"You almost beat the world's champions. 你差点就打败了世界冠军。"},{"id":2728,"word":"whip","pronunciation":"/wɪp/","meaning":"n.鞭子 v.鞭策；鞭打","unit":10,"lesson":2,"seq":16,"isStar":false,"memo":"联想 whi(音似we)+p(音似“扑”)→我们扑上去“鞭打”它。","example":"The rider cracked his whip to make the horse run faster. 骑马的人甩动鞭子让马跑得更快。"},{"id":2729,"word":"bat","pronunciation":"/bæt/","meaning":"n.球棒，球拍，球板；蝙蝠 v.用球板（棒）击（球）；眨眼","unit":10,"lesson":2,"seq":17,"isStar":false,"memo":"联想 不要用球拍(bat)击打蝙蝠(bat)。","example":"Do you have a baseball bat? 你有棒球棒吗?"},{"id":2730,"word":"combat","pronunciation":"/'kɒmbæt/","meaning":"n.战斗，搏斗；打仗 v.与……搏斗，战斗","unit":10,"lesson":2,"seq":18,"isStar":false,"memo":"构词 com-(一起)+bat(=beat)→战斗","example":"He was killed in combat. 他在战斗中阵亡。","derivative":"combative /'kɒmbətv/ adj.好战的;好争论的"},{"id":2731,"word":"battle","pronunciation":"/'bætl/","meaning":"n.战斗，战争；较量 v.搏斗；奋斗；斗争","unit":10,"lesson":2,"seq":19,"isStar":false,"memo":"构词 bat(=beat)+t+-le(后缀)→战斗","example":"There exists the eternal battle between good and evil in the world. 世界上善恶之间存在永无休止的较量。"},{"id":2732,"word":"conflict","pronunciation":"/'kɒnflikt/","meaning":"n.抵触，冲突，矛盾；战争","unit":10,"lesson":2,"seq":20,"isStar":false,"memo":"联想 con-(所有)+flict(音似“飞来剋他”)→所有人飞奔过来(打)他,因为发生了“冲突”。","example":"The results of the new research would seem to conflict with existing theories. 这项新的研究结果似乎与现有的理论相冲突。"},{"id":2733,"word":"impart","pronunciation":"/ɪm'pɑːt/","meaning":"v.传授；告知","unit":10,"lesson":2,"seq":21,"isStar":false,"memo":"联想 i(我)+m(联想“妹”)+part(音似“怕他”)→我妹妹胆小,害怕那个“传授”知识的老师提问她。","example":"We can absorb information for the purpose of imparting it to others. 我们可以为了向他人告知信息而吸收信息。"},{"id":2734,"word":"tuition","pronunciation":"/'juː'ʃn/","meaning":"n.学费；教学","unit":10,"lesson":2,"seq":22,"isStar":false,"memo":"谐音 单词发音类似“吐一身”→他交“学费”的时候正好胃部不适,吐了一身。","example":"The students have been protesting against the increased tuition. 学生们一直在抗议学费上涨。"},{"id":2735,"word":"intuition","pronunciation":"/ˌɪntju'ɪʃn/","meaning":"n.直觉力；（一种）直觉","unit":10,"lesson":2,"seq":23,"isStar":false,"memo":"in(里面) + tuition(学费)→他在家里就知道今年的学费会涨,他的“直觉”太准了。","example":"His intuition was telling him that something was wrong. 他的直觉告诉他有些不对劲。","derivative":"intuitive /ɪnˈtjuɪtɪv/ adj.直觉的;易懂的"},{"id":2736,"word":"depart","pronunciation":"/dɪ'pɑːt/","meaning":"v.离开；出发，启程","unit":10,"lesson":2,"seq":24,"isStar":false,"memo":"单词发音类似“弟怕他”→弟弟因为怕他所以“离开”了。","example":"Flights for Rome depart from Terminal 3. 飞往罗马的航班从3号航站楼出发。","derivative":"departure /dɪpɑːtʃə(r)/ n.离开;背离"},{"id":2737,"word":"quit","pronunciation":"/kwɪt/","meaning":"v.停止，放弃，离职","unit":10,"lesson":2,"seq":25,"isStar":false,"memo":"qui(音似“快”) + t(联想“踢”)→快把他踢出去→放弃;离职","example":"The man has decided to quit his computer class. 这个人决定放弃他的计算机课。"},{"id":2738,"word":"partial","pronunciation":"/'pɑːʃl/","meaning":"adj.部分的，局部的，偏袒的","unit":10,"lesson":2,"seq":26,"isStar":false},{"id":2739,"word":"department","pronunciation":"/dɪ'pɑːtmənt/","meaning":"n.部；司；局；处；系；（医院的）科；部门","unit":10,"lesson":2,"seq":27,"isStar":false,"memo":"de-(分开) + part(部分) + -ment(名词后缀)→分开的各个部分→部门","example":"He works in the Physical Education Department. 他在体育系工作。"},{"id":2740,"word":"apartment","pronunciation":"/ə'pɑːtmənt/","meaning":"n.公寓","unit":10,"lesson":2,"seq":28,"isStar":false,"memo":"a(一) + part(部分) + -ment(名词后缀)→一个个分开的部分(单间)就是“公寓”。","example":"We sat down in the apartment and watched the game in near silence. 我们在公寓里坐下来,静静地观看比赛。"},{"id":2741,"word":"flat","pronunciation":"/flæt/","meaning":"adj.平坦的；平的；无趣的 n.公寓","unit":10,"lesson":2,"seq":29,"isStar":false,"memo":"fl(联想“飞来”) + at(在)→一只鸟飞来,落在一个“平坦的”地方。","example":"He felt very flat after his friends had gone home. 他的朋友们回家后,他感到兴味索然。","derivative":"n.公寓"},{"id":2742,"word":"terrace","pronunciation":"/'terəs/","meaning":"n.露天平台；阳台","unit":10,"lesson":2,"seq":30,"isStar":false,"memo":"ter(音似“特”) + race(比赛)→这个“露天平台”特别大,能在上面举办跑步比赛。","example":"They want a terrace on the roof. 他们想在屋顶上建个露台。"},{"id":2743,"word":"pasture","pronunciation":"/'pɑːstʃə(r)/","meaning":"n.牧场 v.放牧","unit":10,"lesson":2,"seq":31,"isStar":false,"memo":"坐车路过(pass)的牧场(pasture)如同画(picture)一般美丽。","example":"You can use sensors looking down at the ground to check pasture quality. 你可以使用传感器朝下对准地面,以检测牧场的质量。","derivative":"v.放牧"},{"id":2744,"word":"ranch","pronunciation":"/ræntʃ/","meaning":"n.牧场；大农场","unit":10,"lesson":2,"seq":32,"isStar":false},{"id":2745,"word":"particle","pronunciation":"/'pɑːrtɪkl/","meaning":"n.颗粒；微粒；极小量","unit":10,"lesson":2,"seq":33,"isStar":false},{"id":2746,"word":"particular","pronunciation":"/pə'tɪkjʊlə(r)/","meaning":"adj.特别的；特定的；挑剔的 n.细节","unit":10,"lesson":2,"seq":34,"isStar":false,"memo":"谐音 单词发音类似“怕踢哭了”→他怕自己“特别的”脚法把别人踢哭了。","example":"They are particular about the quality of toilet paper. 他们对卫生纸的质量很挑剔。\nparticularly /pə'tɪkjələli/ adv.特别;尤其","derivative":"particularly /pə'tɪkjələli/ adv.特别;尤其"},{"id":2747,"word":"apart","pronunciation":"/ə'pɑːt/","meaning":"adv.相隔；分开 adj.分离的","unit":10,"lesson":2,"seq":35,"isStar":false,"memo":"联想 a(一)+part(部分)→一个一个部分地→分开","example":"The thing that sets children apart from adults is not their ignorance. 孩子和成年人的区别不在于他们的无知。"},{"id":2748,"word":"compartment","pronunciation":"/kəm'pɑːtmənt/","meaning":"n.(客车车厢内的)隔间；(家具等的)分隔间","unit":10,"lesson":2,"seq":36,"isStar":false,"memo":"构词 com-(共同)+part(部分)+-ment(名词后缀)→共同把一个整体分割成的各个部分→隔间;分隔间","example":"With the help of my brother, I opened the door of the compartment. 在我哥哥的帮助下,我打开了隔间的门。"},{"id":2749,"word":"partition","pronunciation":"/'pɑːtɪʃn/","meaning":"n.隔断；分割 v.将……隔开；分割","unit":10,"lesson":2,"seq":37,"isStar":false,"memo":"构词 part(部分,分开)+-ition(后缀)→隔断;分割","example":"The room is partitioned into three sections. 这间屋子被隔为三小间。"},{"id":2750,"word":"decorate","pronunciation":"/'dekorət/","meaning":"v.装饰；装修","unit":10,"lesson":2,"seq":38,"isStar":false,"memo":"联想 de(音似“弟”)+cor(联想 core)+-ate(动词后缀)→弟弟的核心想法就是将新房子“装修”得漂漂亮亮的。","example":"They decorated the room with flowers and balloons. 他们用花和气球装饰了房间。","derivative":"decoration /ˌdekə'reɪʃn/ n.装饰,装潢\ndecorative /'dekərətɪv/ adj.装饰性的,作装饰用的"},{"id":2751,"word":"core","pronunciation":"/kɔː(r)/","meaning":"n.核儿；核心 adj.最重要的；主要的","unit":10,"lesson":2,"seq":39,"isStar":false,"memo":"谐音 单词发音类似“靠”→大家都依靠的那个人就是“核心”。","example":"This report goes to the core of the argument. 这没有到不了的彼岸,没有行不至的远方。"},{"id":2752,"word":"ornament","pronunciation":"/'ɔːnəmənt/","meaning":"n.装饰；装饰品 v.装饰；点缀","unit":10,"lesson":2,"seq":40,"isStar":false,"memo":"谐音 单词发音类似“哦那美特”→哦,那座房子真美,“装饰”得特别豪华。","example":"The baroque style is rich in ornament. 巴洛克风格以丰富的装饰为特色。","derivative":"ornamental /ˌɔːrnə'mentl/ adj.装饰性的,点缀的"},{"id":2753,"word":"cosmetic","pronunciation":"/kɒz'metɪk/","meaning":"adj.表面的；装门面的；化妆用的；美容的 n.化妆品；美容品","unit":10,"lesson":2,"seq":41,"isStar":false},{"id":2754,"word":"make-up","pronunciation":"/'meɪkʌp/","meaning":"n.化妆品；组成；构成；性格特点","unit":10,"lesson":2,"seq":42,"isStar":false},{"id":2755,"word":"structure","pronunciation":"/'strʌktʃə(r)/","meaning":"n.结构；构造 v.系统安排；精心组织","unit":10,"lesson":2,"seq":43,"isStar":false,"memo":"谐音 单词发音类似“死抓可扯”→死抓着一个物品,可能会扯坏它的“结构”。","example":"Bees have a complex social structure. 蜜蜂有着复杂的社会结构。","derivative":"structural /'strʌktʃərəl/ adj.结构(或构造)上的"},{"id":2756,"word":"construct","pronunciation":"/kən'strʌkt/","meaning":"v.修建；建造","unit":10,"lesson":2,"seq":44,"isStar":false,"memo":"联想 con-(所有)+struct(联想 structure)→所有建筑的结构都是工人“修建”的。","example":"The building was constructed in 1993. 这座建筑建造于1993年。","derivative":"construction /kən'strʌkʃn/ n.建筑;建造"},{"id":2757,"word":"instruct","pronunciation":"/ɪn'strʌkt/","meaning":"v.命令，指示；教授，传授（技能等）","unit":10,"lesson":2,"seq":45,"isStar":false,"memo":"联想 in(里面)+struct(音似“死抓个他”)→他们在里面死死抓着他的衣领,“命令”他别再执迷不悟了。","example":"She arrived at 10 o'clock as instructed. 她依照指示于10点钟到达。","derivative":"instruction /ɪn'strkʃn/ n.用法说明;命令,指示\ninstructor /ɪn'strʌktə(r)/ n.教练;导师\ninstructive /ɪn'strktɪv/ adj.富有教益的;增长知识的"},{"id":2758,"word":"establish","pronunciation":"/ɪ'steblɪʃ/","meaning":"v.建立，创立，设立","unit":10,"lesson":2,"seq":46,"isStar":false,"memo":"联想 e-(联想前缀 en-,使)+stabl(联想 stable)+-ish(动词后缀)→他的才能使他能平稳地“创立”了该学校。","example":"They plan to establish a new school in this area. 他们计划在这个地区创立一所新学校。","derivative":"establishment /ɪ'stæblɪʃmənt/ n.建立;企业"},{"id":2759,"word":"erect","pronunciation":"/ɪ'rekt/","meaning":"v.建造；创立；竖立 adj.垂直的；直立的","unit":10,"lesson":2,"seq":47,"isStar":false,"memo":"对照 城市里建造(erect)很多路和桥是正确的(correct)。","example":"The church was erected in 1582. 此教堂建造于1582年。","derivative":"erection /ɪ'rekn/ n.建造;竖立"},{"id":2760,"word":"architecture","pronunciation":"/'ɑːkɪtektʃə(r)/","meaning":"n.建筑学；建筑风格；结构","unit":10,"lesson":2,"seq":48,"isStar":false,"memo":"联想 ar(联想 art)+chi+tecture(联想 structure)→“建筑学”是一种结构的艺术。","example":"The building is a prime example of the 1960s architecture. 这座大楼是20世纪60年代的典型建筑。"},{"id":2761,"word":"architect","pronunciation":"/'ɑːkɪtekt/","meaning":"n.建筑师；设计师；创造者","unit":10,"lesson":2,"seq":49,"isStar":false,"example":"He is an architect practising in Texas. 他是个在得克萨斯州执业的建筑师。"},{"id":2762,"word":"infrastructure","pronunciation":"/'ɪnfrastrʌktʃə(r)/","meaning":"n.基础设施；基础建设","unit":10,"lesson":2,"seq":50,"isStar":false,"memo":"联想 in(里面)+fra+structure(结构)→一定要重视房子里面的结构,搞好“基础设施”的建设。","example":"They lack a suitable economic infrastructure. 它们缺乏合适的经济基础设施。"},{"id":2763,"word":"tank","pronunciation":"/tæŋk/","meaning":"n.坦克；（贮放液体或气体的）箱 v.彻底失败；破产","unit":10,"lesson":2,"seq":51,"isStar":false,"memo":"谐音 单词发音类似“坦克”。","example":"Both dolphins were put in the same tank. 两只海豚都被放在同一个水箱里。"},{"id":2764,"word":"bullet","pronunciation":"/'bʊlɪt/","meaning":"n.子弹，弹丸","unit":10,"lesson":2,"seq":52,"isStar":false,"memo":"谐音 单词发音类似“崩了他”→“子弹”已上膛,如果他再作恶,警察必会崩了他。","example":"He had fired five bullets from his gun. 他开枪射击了五发子弹。"},{"id":2765,"word":"navy","pronunciation":"/'neɪvɪ/","meaning":"n.海军；海军部队","unit":10,"lesson":2,"seq":53,"isStar":false,"memo":"谐音 单词发音类似“那位”→那位哥哥是一名“海军”军官。","example":"The North had an established army, navy, and government. 北方已经建立了陆军、海军和政府。","derivative":"naval /'neɪvl/ adj.海军的"},{"id":2766,"word":"corps","pronunciation":"/ko:(r)/","meaning":"n.军，兵团；一群人","unit":10,"lesson":2,"seq":54,"isStar":false,"memo":"谐音 单词发音类似“靠”→他们靠着“一群人”赢得了战争。","example":"The Marine Corps is on a mission. 海军陆战队在执行任务。"},{"id":2767,"word":"military","pronunciation":"/'mɪlɪtəri/","meaning":"n.军人；军队；军方 adj.军事的；武装的","unit":10,"lesson":2,"seq":55,"isStar":false,"memo":"联想 mili(音似“没了”)+tary(音似 tree)→敌人“军方”经过的地方,连树都没有留下。","example":"The government increased military spending this year. 政府今年增加了军费开支。"},{"id":2768,"word":"militant","pronunciation":"/'mɪlɪtənt/","meaning":"adj.好战的；激进的 n.激进分子","unit":10,"lesson":2,"seq":56,"isStar":false,"memo":"(谐音) 单词发音类似“灭了他的”→这个常说“灭了他的”的“激进分子”是“好战的”。","example":"Militant groups have been blamed for a series of attacks in the region. 武装组织被指应为该地区发生的一系列袭击事件负责。","derivative":"militancy /'mɪlɪtənsi/ n.战斗性,交战状态"},{"id":2769,"word":"siege","pronunciation":"/siːdʒ/","meaning":"n.包围，围攻；封锁","unit":10,"lesson":2,"seq":57,"isStar":false},{"id":2770,"word":"besiege","pronunciation":"/bɪˈsiːdʒ/","meaning":"v. 围困；包围","unit":10,"lesson":2,"seq":58,"isStar":false,"memo":"be-siege（被‘siege’围攻）→ siege读/siːdʒ/，谐音‘死姐’，被‘死姐’堵宿舍门要作业，妥妥被围困！","example":"The professor was besieged by students asking for grade reviews. 教授被要求复核成绩的学生团团围住。","derivative":"besiegement /bɪ'siːdʒmənt/ n. 围困；包围"},{"id":2771,"word":"attack","pronunciation":"/əˈtæk/","meaning":"v. & n. 袭击，攻击；批评","unit":10,"lesson":2,"seq":59,"isStar":false,"memo":"(联想) a(一个) + ttack(音似tank)→一辆坦克正在“袭击”敌人。","example":"The soldier was accused of running away when the enemy attacked. 这个士兵被指控在敌人进攻时逃跑。"},{"id":2772,"word":"tactic","pronunciation":"/ˈtæktɪk/","meaning":"n. 策略，手段，战术","unit":10,"lesson":2,"seq":60,"isStar":false,"memo":"(联想) tac(音似 tank) + tic→用坦克进攻需要“策略”。","example":"They use effective tactics to defeat their competitors. 他们使用有效的战术来击败竞争对手。"},{"id":2773,"word":"tact","pronunciation":"/tækt/","meaning":"n. （处事、言谈等）老练，圆通，得体；机敏","unit":10,"lesson":2,"seq":61,"isStar":false},{"id":2774,"word":"contact","pronunciation":"/ˈkɒntækt/","meaning":"v. 联系，联络 n. 联系，联络，触摸，接触","unit":10,"lesson":2,"seq":62,"isStar":false,"memo":"(构词) con-(共同) + tact (= touch)→共同触碰→联系","example":"They have little close contact with adults. 他们几乎不与成年人密切接触。"},{"id":2775,"word":"intact","pronunciation":"/ɪnˈtækt/","meaning":"adj. 完好无损的，完整的","unit":10,"lesson":2,"seq":63,"isStar":false,"memo":"(构词) in-(没有) + tact (= touch)→没有被触摸过的→完好无损的","example":"Most of the house remains intact even after two hundred years. 即使过了两百年,这房子的大部分还保持完好。"},{"id":2776,"word":"assault","pronunciation":"/əˈsɔːlt/","meaning":"v. 猛烈攻击，袭击  n. 攻击，袭击","unit":10,"lesson":2,"seq":64,"isStar":false,"memo":"(联想) as-(一再地) + saul(音似“骚”) + t(联想“他”)→一再地骚扰他→攻击,袭击","example":"Assaults often happen on school campuses in the war. 在战争中,校园里经常发生袭击事件。"},{"id":2777,"word":"insult","pronunciation":"/ˈɪnsʌlt/","meaning":"n. 辱骂；侮辱","unit":10,"lesson":2,"seq":65,"isStar":false,"memo":"(联想) in(音似“言”) + sult(联想 result)→意见不合时不能用语言“辱骂”得到结果。"},{"id":2778,"word":"consult","pronunciation":"/kənˈsʌlt/","meaning":"v. 咨询；请教；商议，商量；查阅","unit":10,"lesson":2,"seq":66,"isStar":false,"memo":"con-(所有的)+sult(联想 result)→通过“咨询”,所有的问题都有了结果。","example":"If the pain continues, consult your doctor. 如果疼痛持续不消退,要请医生诊治。","derivative":"consultation /ˌkɒnsəl'teɪʃn/ n.咨询;商讨\nconsultative /kən'sʌltətv/ adj.咨询的;顾问的\nconsultant /kən'sltənt/ n.顾问"},{"id":2779,"word":"counsel","pronunciation":"/ˈkaʊnsəl/","meaning":"n. 律师；法律顾问 v. 提供专业咨询；建议","unit":10,"lesson":2,"seq":67,"isStar":false,"memo":"coun-(= com-,所有)+sel(联想 sell)→你最好找个“律师”寻求“建议”,别轻易把你所有的家产都变卖了。","example":"The court then heard counsel for the woman. 法庭接着听取了这位女士所请的辩护律师的陈述。"},{"id":2780,"word":"condolence","pronunciation":"/kənˈdəʊləns/","meaning":"n. 吊唁，哀悼","unit":10,"lesson":2,"seq":68,"isStar":false},{"id":2781,"word":"convention","pronunciation":"/kənˈvenʃn/","meaning":"n. 习俗，惯例；大会","unit":10,"lesson":2,"seq":69,"isStar":false,"memo":"con-(所有)+vention(音似“文身”)→这里的所有人都文身,这是当地的“习俗”。","example":"Convention demands that a club member should resign in such a situation. 惯例要求俱乐部成员在这种情况下应该辞职。","derivative":"conventional /kən'venʃənl/ adj.墨守成规的;传统的"},{"id":2782,"word":"convene","pronunciation":"/kənˈviːn/","meaning":"v. 聚集，集合；开会","unit":10,"lesson":2,"seq":70,"isStar":false,"memo":"con-(所有)+vene(音似 went)→所有人都去“开会”了。","example":"The committee will convene at 11:30 AM next Thursday. 委员会将在下星期四上午11:30开会。"},{"id":2783,"word":"convey","pronunciation":"/kənˈveɪ/","meaning":"v. 表达，传递，传送，运送","unit":10,"lesson":2,"seq":71,"isStar":false,"memo":"con-(所有)+vey(音似 way)→所有东西都已在路上“运送”。","example":"A good teacher must know how to convey his ideas. 一个好老师必须知道如何表达他的思想。","derivative":"conveyance /kən'veɪəns/ n.传送,运送"},{"id":2784,"word":"survey","pronunciation":"/ˈsɜːveɪ/","meaning":"n. 调查；测量","unit":10,"lesson":2,"seq":72,"isStar":false,"memo":"sur-(上面)+vey(音似 way)→他们正在路上“调查”真相。","example":"He surveyed 165 households. 他调查了165户家庭。"},{"id":2785,"word":"invest","pronunciation":"/ɪnˈvest/","meaning":"v. 投资，投入","unit":10,"lesson":2,"seq":73,"isStar":false,"memo":"in-(进入)+vest(联想 west)→深入西部大开发,需要很多“投资”。","example":"They need to invest more in hospital staff and facilities. 他们需要在医院人员和设施方面加大投资。","derivative":"investor /ɪn'vestə(r)/ n.投资者;投资机构\ninvestment /ɪn'vestmənt/ n.投资"},{"id":2786,"word":"investigate","pronunciation":"/ɪnˈvestɪgeɪt/","meaning":"v.调查，侦查；研究","unit":10,"lesson":2,"seq":74,"isStar":false,"memo":"invest(投资) + i(我) + gate(大门) → 我投资之前会在对方大门口“调查”清楚背景。","example":"We are better able to investigate social phenomena than physical phenomena. 我们更擅长研究社会现象而不是物理现象。","derivative":"investigation /ɪnˌvestɪˈɡeɪʃn/ n. 调查\ninvestigator /ɪnvestɪɡeɪtə(r)/ n. 调查者，侦察员"},{"id":2787,"word":"investigator","pronunciation":"/ɪnˈvestɪgətə(r)/","meaning":"n.调查者，侦察员","unit":10,"lesson":2,"seq":75,"isStar":false},{"id":2788,"word":"census","pronunciation":"/ˈsensəs/","meaning":"n.(官方的)统计，人口普查，人口调查","unit":10,"lesson":2,"seq":76,"isStar":false,"example":"A national census is taken every ten years. 每十年进行一次全国人口普查。"},{"id":2789,"word":"consensus","pronunciation":"/kənˈsensəs/","meaning":"n.共同意见，一致看法，共识","unit":10,"lesson":2,"seq":77,"isStar":false,"memo":"con-(共同) + sens(感觉) + -us(名词后缀) → 共同的感觉 → 共同意见，共识","example":"The consensus among economists is that immigration should not be encouraged. 经济学家的共识是，不应该鼓励移民。"},{"id":2790,"word":"unanimous","pronunciation":"/juˈnænɪməs/","meaning":"adj.(决定或意见)一致的，一致同意的","unit":10,"lesson":2,"seq":78,"isStar":false,"memo":"u(音似 you) + na(音似“奶”) + nim(联想“你妹”) + -ous(形容词后缀) → 你奶奶和你妹妹的意见是“一致的”。","example":"The decision was not unanimous. 这项决定没有得到一致同意。"},{"id":2791,"word":"reconcile","pronunciation":"/rɪˈkɒnsaɪl/","meaning":"v.使和谐一致，协调；使和解，和好；将就，妥协","unit":10,"lesson":2,"seq":79,"isStar":false,"memo":"re(字母音似“阿姨”) + con(联想前缀，所有) + cile(联想“吃了”) → 阿姨和所有人吃过饭就和解了 → 使和解，和好","example":"The couple could not reconcile their differences. 这对夫妇无法调和他们之间的分歧。","derivative":"reconciliation /rekənsɪliˈeɪʃn/ n. 和解；协调\nreconciliatory /ˌrekənˈsliətəri/ adj. 调解的；和解的"},{"id":2792,"word":"retreat","pronunciation":"/rɪˈtriːt/","meaning":"v. & n.撤退；退却","unit":10,"lesson":2,"seq":80,"isStar":false,"memo":"re-(回) + treat(处理) → 处理回去 → 撤退；退却","example":"The army was in full retreat. 部队全线撤退。"},{"id":2793,"word":"repel","pronunciation":"/rɪˈpel/","meaning":"v.击退，驱逐，推开，赶走，驱除","unit":10,"lesson":3,"seq":1,"isStar":false,"memo":"[联想] re-(重复) + pel(音似“迫”)→重复地压迫出去→驱逐;赶走","example":"This kind of material can repel heat and moisture. 这种材料能够耐热防潮。"},{"id":2794,"word":"expel","pronunciation":"/ɪkˈspel/","meaning":"v.把……开除；驱逐出境；排出","unit":10,"lesson":3,"seq":2,"isStar":false,"memo":"[联想] ex-(往外) + pel(音似“迫”)→把……压迫出去→驱逐出境;排出","example":"Cultivating positive interpersonal relationships helped him expel solitary feelings. 培养积极的人际关系帮助他摆脱孤独感。"},{"id":2795,"word":"propel","pronunciation":"/prəˈpel/","meaning":"v.推动，驱动，迫使，驱使","unit":10,"lesson":3,"seq":3,"isStar":false,"memo":"[联想] pro-(往前) + pel (音似“迫”)→迫使……往前走→推动,驱动","example":"Anger propelled her into action. 怒火驱使她行动起来。","derivative":"propeller /prə'pelə(r)/ n.螺旋桨"},{"id":2796,"word":"compel","pronunciation":"/kəmˈpel/","meaning":"v.强迫，迫使；引起(反应)","unit":10,"lesson":3,"seq":4,"isStar":false,"memo":"[联想] com-(所有,一起) + pel(音似“迫”)→时间紧迫,他“迫使”所有人一起加快行动。","example":"He spoke with an authority that compelled the attention of the whole crowd. 他用权威的口气讲话,引起了整个人群的注意。"},{"id":2797,"word":"squeeze","pronunciation":"/skwiz/","meaning":"n. & v.压，挤，捏","unit":10,"lesson":3,"seq":5,"isStar":false,"memo":"[谐音] 单词发音类似“死贵死”→这件衣服死(很)贵,你要死死地往下“压”价。","example":"Cut the lemon in half and squeeze the juice into the bowl. 把柠檬一切为二,将汁挤到碗里。"},{"id":2798,"word":"direct","pronunciation":"/də'rekt; da'rekt/","meaning":"v.指导；指挥 adj.笔直的；直接的","unit":10,"lesson":3,"seq":6,"isStar":false,"memo":"[联想] di(联想“弟”) + re(字母音似“阿姨”) + ct(音似“他”)→弟弟试图“指挥”阿姨干这干那,气得阿姨装要剋(打)他。","example":"Now we have the most direct evidence yet that he is right. 现在我们有了最直接的证据证明他是对的。","derivative":"direction /də'rekʃn; daɪ'rekʃn/ n.方向;方位\ndirector /də'rektə(r); daɪ'rektə(r)/ n.董事;理事;经理\ndirectory /də'rektəri; daɪ'rektəri/ n.名录;电话簿;(计算机的)目录"},{"id":2799,"word":"directory","pronunciation":"/də'rektəri; da'rektəri/","meaning":"n.名录；电话簿；（计算机的）目录","unit":10,"lesson":3,"seq":7,"isStar":false},{"id":2800,"word":"connect","pronunciation":"/kə'nekt/","meaning":"v.(使)连接；联结；接通","unit":10,"lesson":3,"seq":8,"isStar":false,"memo":"联想 con-(所有)+ne(音似“奶”)+ct(音似“剋他”)→所有的奶奶都“联结”起来去剋(打)他。","example":"It is a great way to connect with the community. 这是与社区建立联系的好方法。","derivative":"connection /kəˈnekʃn/ n.联系;联结"},{"id":2801,"word":"associate","pronunciation":"/ə'səʊsiət; ə'səʊʃiət/","meaning":"n.同事；伙伴 adj.副的","unit":10,"lesson":3,"seq":9,"isStar":false,"memo":"联想 as-(一再地)+so(如此)+ci(音似“吸”)+ate(后缀)→他们的优点如此吸引对方,于是他们开始“联系”。","example":"His son has got some sincere associates. 他的儿子有一些真诚的伙伴。","derivative":"association /əˌsəʊsiˈeʃn; ˌæsəʊʃiˈeɪʃn/ n.协会,社团;关联;联想,联系"},{"id":2802,"word":"link","pronunciation":"/lɪŋk/","meaning":"v.连接；联系 n.环节","unit":10,"lesson":3,"seq":10,"isStar":false,"memo":"谐音 单词发音类似“拎个”→他拎出一条线索,“联系”起全文脉络。","example":"The two factors are directly linked. 这两个因素直接联系在一起。"},{"id":2803,"word":"junction","pronunciation":"/'dʒʌŋkʃn/","meaning":"n.(公路或铁路的)交叉路口；汇合处；结合处","unit":10,"lesson":3,"seq":11,"isStar":false,"example":"The police have installed cameras at dangerous road junctions. 警察在危险的交叉路口安装了摄像头。"},{"id":2804,"word":"conjunction","pronunciation":"/kən'dʒʌŋkʃn/","meaning":"n.连词；结合；同时发生","unit":10,"lesson":3,"seq":12,"isStar":false,"memo":"联想 conj.是 conjunction 的缩写。","example":"All were grown in conjunction with mouse cells. 它们都是与小鼠细胞一起生长的。"},{"id":2805,"word":"mingle","pronunciation":"/'mɪŋgl/","meaning":"v.(使)与……结合；使混合；使联结","unit":10,"lesson":3,"seq":13,"isStar":false,"memo":"联想 min(联想“敏”,人名)+g(联想“哥”)+le(联想“了”)→阿敏和朋友的哥哥结为夫妻了→与……结合","example":"If we mingle with the crowd, we shall not be noticed. 如果我们混在人群里,就不会被注意到了。"},{"id":2806,"word":"combine","pronunciation":"/kəm'bain/","meaning":"v.(使)联合；(使)结合","unit":10,"lesson":3,"seq":14,"isStar":false,"memo":"联想 com(联想 company)+bine(联想“并”)→公司合并就是指公司“联合”。"},{"id":2807,"word":"tie","pronunciation":"/taɪ/","meaning":"n.领带；联系 v.系；使紧密结合","unit":10,"lesson":3,"seq":15,"isStar":false,"example":"The firm has close ties with an American corporation. 这家公司与一家美国的公司关系密切。"},{"id":2808,"word":"relevant","pronunciation":"/'reləvənt/","meaning":"adj.紧密相关的；切题的；有意义的","unit":10,"lesson":3,"seq":16,"isStar":false,"memo":"联想 re-(重复)+le(音似“了”)+vant(音似“问他”)→人们重复地问了他,因为这件事跟他是“紧密相关的”。","example":"We try to make the experience relevant to individual lives. 我们努力让该体验与个人生活息息相关。","derivative":"relevance /reləvəns/ n.相关性;意义"},{"id":2809,"word":"integrate","pronunciation":"/'ɪntɪgreɪt/","meaning":"v.(使)合并；(使)结合；(使)成为一体","unit":10,"lesson":3,"seq":17,"isStar":false,"memo":"联想 inte(音似“音体”)+grate(音同great)→音乐、体育“结合”好,全面发展促成长。","example":"They have not made any effort to integrate with the local community. 他们完全没有尝试融入本地社区。","derivative":"integration /ˌɪntɪˈɡreɪʃn/ n.结合;一体化"},{"id":2810,"word":"integral","pronunciation":"/'ɪntɪgrəl; ɪn'tegral/","meaning":"adj.必需的；不可或缺的","unit":10,"lesson":3,"seq":18,"isStar":false,"memo":"联想 integr(联想 integrate)+-al(形容词后缀)→使成为一体的→必需的;不可或缺的","example":"Practical experience is integral to the course. 实践经验是这门课程不可缺少的部分。"},{"id":2811,"word":"integrity","pronunciation":"/ɪn'tegrəti/","meaning":"n.诚实正直；完整；完好","unit":10,"lesson":3,"seq":19,"isStar":false,"memo":"联想 integr(联想 integrate)+-ity(名词后缀)→成为一体→完整","example":"A man of integrity is the one of integrity. 一个诚实正直的人才是完整的人。"},{"id":2812,"word":"disintegrate","pronunciation":"/dɪs'ɪntɡreɪt/","meaning":"v.解体；分裂；瓦解","unit":10,"lesson":3,"seq":20,"isStar":false},{"id":2813,"word":"concrete","pronunciation":"/'kɒŋkrɪt/","meaning":"adj.具体的；有形的 n.混凝土","unit":10,"lesson":3,"seq":21,"isStar":false,"memo":"构词 con-(所有)+cret(=create)+-e→所有创造的东西都是“具体的”。","example":"The concrete was ready mixed. 混凝土是搅拌好的。"},{"id":2814,"word":"emigrate","pronunciation":"/'emɪɡreɪt/","meaning":"v.移居国外；移民","unit":10,"lesson":3,"seq":22,"isStar":false},{"id":2815,"word":"migrate","pronunciation":"/'maɪ'ɡreɪt/","meaning":"v.迁徙；移居；迁移","unit":10,"lesson":3,"seq":23,"isStar":false,"example":"We find that some birds migrate twice a year. 我们发现,一些鸟类每年都会迁徙两次。","derivative":"migration /maɪ'greɪʃn/ n.迁徙;移居,迁移"},{"id":2816,"word":"immigrate","pronunciation":"/'ɪmɪɡreɪt/","meaning":"v.(从外地)移居；移民","unit":10,"lesson":3,"seq":24,"isStar":false},{"id":2817,"word":"immigrant","pronunciation":"/'ɪmɪɡrənt/","meaning":"n.(外来)移民；外侨","unit":10,"lesson":3,"seq":25,"isStar":false,"memo":"[构词] im-(= in-,入) + migrant(移民)→(外来)移民;外侨","example":"Immigrants from all over the world populate this city. 来自世界各地的移民居住在这个城市。"},{"id":2818,"word":"emigrant","pronunciation":"/'emɪɡrənt/","meaning":"n.移居外国的人；移民","unit":10,"lesson":3,"seq":26,"isStar":false},{"id":2819,"word":"migrant","pronunciation":"/'maɪɡrənt/","meaning":"n.移居者，移民；候鸟；迁徙动物 adj.迁移的，迁徙的","unit":10,"lesson":3,"seq":27,"isStar":false},{"id":2820,"word":"candidate","pronunciation":"/'kændɪdət; 'kændɪdɪt/","meaning":"n.候选人；应试者","unit":10,"lesson":3,"seq":28,"isStar":false,"memo":"[联想] can(能够) + did(做) + ate(eat 的过去式)→“候选人”太紧张了,他能做的就是先吃点东西缓解情绪。","example":"There are some presidential candidates running for their first term in office. 有一些总统候选人在参加他们的第一个任期竞选。","derivative":"candidacy /'kændɪdəsi/ n.候选人的资格(或身份)"},{"id":2821,"word":"recruit","pronunciation":"/rɪ'kruːt/","meaning":"n.新兵，新成员 v.招募(新兵)；吸收(新成员)","unit":10,"lesson":3,"seq":29,"isStar":false,"memo":"联想 re(字母音似“阿姨”) + cru(音似“可入”) + it(它) → 阿姨可以加入这个俱乐部(它),即阿姨可以被“吸收”为“新成员”。","example":"New teachers and staff have to be recruited. 必须招聘新的教师和工作人员。","derivative":"recruitment /rɪ'kruːtmənt/ n.吸收(新成员);征募(新兵)"},{"id":2822,"word":"enrol(l)","pronunciation":"/ɪn'roʊl/","meaning":"v.招(生)，吸收(成员)；注册，登记","unit":10,"lesson":3,"seq":30,"isStar":false},{"id":2823,"word":"roll","pronunciation":"/rəʊl/","meaning":"n.卷；名单 v.滚动","unit":10,"lesson":3,"seq":31,"isStar":false,"example":"They bought a roll of toilet paper. 他们买了一卷卫生纸。","derivative":"roller /'rəʊlə(r)/ n.滚筒;巨浪"},{"id":2824,"word":"register","pronunciation":"/'redʒɪstə(r)/","meaning":"n.名册，登记簿 v.登记，注册","unit":10,"lesson":3,"seq":32,"isStar":false,"memo":"联想 re-(重复,再) + g(联想“哥”) + ister (联想 sister) → 那个哥哥和那个姐姐再次“登记”结婚了。","example":"The property register will say whether the property is freehold or leasehold. 房产登记簿会注明房产是永久产权还是租赁产权。","derivative":"registration /ˌredʒɪ'streɪʃn/ n.注册,登记\nregistrar /ˌredʒɪ'strɑː(r)/ n.登记员;户籍管理员"},{"id":2825,"word":"participate","pronunciation":"/pɑːˈtɪsɪpeɪt/","meaning":"v.参与，参加","unit":10,"lesson":3,"seq":33,"isStar":false},{"id":2826,"word":"anticipate","pronunciation":"/ænˈtɪsɪpeɪt/","meaning":"v.预料，预期，预见，期望","unit":10,"lesson":3,"seq":34,"isStar":false,"memo":"谐音 单词发音类似“俺提吸陪她”→俺提着一兜可以吸的果冻去医院陪她,“期望”她会很高兴。","example":"We anticipate that sales will rise next year. 我们预料明年销售量将会增加。","derivative":"anticipation /ænˌtɪsɪ'peɪʃn/ n.预料,预计"},{"id":2827,"word":"antique","pronunciation":"/ænˈtɪk/","meaning":"n.古物，古董 adj.古老的；古董的","unit":10,"lesson":3,"seq":35,"isStar":false,"memo":"谐音 单词发音类似“俺提个”→俺提个“古董”去给行家看看。","example":"They found the antiques there more valuable. 他们发现那里的古董更有价值。"},{"id":2828,"word":"ancient","pronunciation":"/ˈeɪnʃənt/","meaning":"adj.古代的；古老的","unit":10,"lesson":3,"seq":36,"isStar":false,"memo":"谐音 单词发音类似“俺神仙”→俺喜欢那个神仙,他经常出现在“古老的”神话里。","example":"The pyramids were built in ancient times. 金字塔建造于古代。"},{"id":2829,"word":"explode","pronunciation":"/ɪkˈspləʊd/","meaning":"v.爆炸；激增","unit":10,"lesson":3,"seq":37,"isStar":false,"memo":"联想 ex-(向外) + plo(联想爆炸的声音) + de(联想前缀,往下)→烟花朝外“爆炸”后又坠落下来。","example":"A second bomb exploded. 第二枚炸弹爆炸了。","derivative":"explosion /ɪkspləʊʒn/ n.爆炸;激增\nexplosive /ɪkˈspləsɪv/ n.爆炸物,炸药 adj.能引起爆炸的"},{"id":2830,"word":"explore","pronunciation":"/ɪkˈsplɔː(r)/","meaning":"v.勘查，探索，研究，探讨","unit":10,"lesson":3,"seq":38,"isStar":false,"memo":"联想 ex-(向外) + plore(音似“扑姥”)→他朝外扑向来做客的姥姥,同她“探索”过去的事情。","example":"This book explores the musical interest and needs of children. 这本书探讨了儿童对音乐的兴趣和需求。","derivative":"exploration /ˌekspləˈreʃn/ n.探索,勘查"},{"id":2831,"word":"exploit","pronunciation":"/ɪkˈspləʊt/","meaning":"v.利用；开发，开采","unit":10,"lesson":3,"seq":39,"isStar":false,"memo":"联想 ex-(向外) + plo(音似“扑落”) + it(它)→猫咪向外扑落杂物,“开发”了它的专属领地。","example":"The studio is exploiting public opinion. 该工作室在利用公众舆论。"},{"id":2832,"word":"tap","pronunciation":"/tæp/","meaning":"n.水龙头；阀门；轻拍 v.轻敲，轻拍；利用；开发","unit":10,"lesson":3,"seq":40,"isStar":false,"memo":"联想 ta(联想“他”) + p(联想“拍”)→他“轻拍”了一下我的肩。","example":"It is a waste to leave the tap running. 让水龙头一直开着流水真是浪费。"},{"id":2833,"word":"tub","pronunciation":"/tʌb/","meaning":"n.盒；盆；缸；浴缸","unit":10,"lesson":3,"seq":41,"isStar":false,"memo":"谐音 单词发音类似“踏步”→他们拿着饭“盒”踏步,排队打饭。","example":"There were tubs of flowers on the balcony. 阳台上有一盆盆的花。"},{"id":2834,"word":"utilise","pronunciation":"/-ize/","meaning":"ˈjuːtaɪlaɪz/ v.使用，利用","unit":10,"lesson":3,"seq":42,"isStar":false},{"id":2835,"word":"utility","pronunciation":"/ˈjuːˈtɪləti/","meaning":"n.公用事业；实用，效用；实用程序","unit":10,"lesson":3,"seq":43,"isStar":false,"memo":"对照 utilise/-ize v.使用,利用→utility n.","example":"The utility ends up abandoning the plant anyway. 最终公用事业公司还是放弃了这座发电厂。"},{"id":2836,"word":"appliance","pronunciation":"/əˈplaɪəns/","meaning":"n.家用器具；家用电器","unit":10,"lesson":3,"seq":44,"isStar":false,"memo":"[对照] apply v.应用→y变i加ance→appliance n.","example":"Don't turn on any electric appliance without permission.未经许可,不得擅自打开任何电器设备。"},{"id":2837,"word":"mechanic","pronunciation":"/məˈkænɪk/","meaning":"n.机械师；机械修理工；技工","unit":10,"lesson":3,"seq":45,"isStar":false,"memo":"[对照] 他是一名机械修理工(mechanic),负责修理各种机器(machine)。","example":"I took my car to the mechanic to get it fixed.我把车送到修理工那里修理。","derivative":"mechanical /məˈkænɪkl/ adj.机动的;机械的\nmechanics /məˈkænɪks/ n.机械学\nmechanism /ˈmekənɪzəm/ n.机械装置;机制"},{"id":2838,"word":"equip","pronunciation":"/ɪ'kwɪp/","meaning":"v.配备；装备；使有所准备；使有能力","unit":10,"lesson":3,"seq":46,"isStar":false,"memo":"[谐音] 单词发音类似“一块布”→每个仆人都“配备”有一块布。","example":"When cars are equipped with such systems, thefts may drop by one third.当汽车配备了这样的系统,盗窃可能会减少三分之一。","derivative":"equipment /ˈkwɪpmənt/ n.设备;装备"},{"id":2839,"word":"gadget","pronunciation":"/'gædʒɪt/","meaning":"n.小器具；小装置","unit":10,"lesson":3,"seq":47,"isStar":false,"memo":"[谐音] 单词发音类似“改进它”→大产品的升级离不开对一些“小装置”的改进。","example":"We'll observe how students use the gadgets.我们会观察学生们如何使用这些小装置。","derivative":"gadgetry /ˈɡædʒɪtri/ n.小器具,小装置"},{"id":2840,"word":"instal(l)","pronunciation":"/ɪn'stoʊl/","meaning":"v.安装，设置","unit":10,"lesson":3,"seq":48,"isStar":false},{"id":2841,"word":"screw","pronunciation":"/skruː/","meaning":"n.螺丝（钉） v.用螺丝钉固定；拧紧","unit":10,"lesson":3,"seq":49,"isStar":false,"memo":"[谐音] 单词发音类似“四个儒”→四个儒雅的书生拧成一股绳,力量不可小觑→拧紧","example":"A screw is stronger than a nail.螺丝钉比普通钉子更牢固。"},{"id":2842,"word":"scrutiny","pronunciation":"/'skruːtəni/","meaning":"n.仔细检查；认真彻底的审查","unit":10,"lesson":3,"seq":50,"isStar":false,"memo":"[联想] scru(音似“四个儒”)+tiny(微小的)→四个儒生“仔细检查”那些微小的物件。","example":"Her argument doesn't really stand up to scrutiny.她的论点经不起认真推敲。"},{"id":2843,"word":"employ","pronunciation":"/ɪm'plɔɪ/","meaning":"v.雇用；应用，运用","unit":10,"lesson":3,"seq":51,"isStar":false,"example":"The plants employ chemical warfare to protect themselves. 这些植物采取化学战的方式保护自己。","derivative":"employment /ɪm'plɔɪmənt/ n.工作;雇用\nemployer /ɪm'plɔɪə(r)/ n.雇主;老板\nemployee /ɪm'plɔɪiː/ n.受雇者;雇员"},{"id":2844,"word":"deploy","pronunciation":"/dɪ'plɔɪ/","meaning":"v.部署，调度（军队或武器），有效地利用","unit":10,"lesson":3,"seq":52,"isStar":false},{"id":2845,"word":"plausible","pronunciation":"/'plɔːzəbl/","meaning":"adj.似乎有道理的；似乎可信的","unit":10,"lesson":3,"seq":53,"isStar":false,"memo":"[联想] plaus(音似“扑老死”) + -ible(形容词后缀)→武松扑向老虎并把老虎打死了，这个故事是“似乎可信的”。","example":"Her story sounded perfectly plausible. 她的说辞听起来完全合理。"},{"id":2846,"word":"abstract","pronunciation":"/'æbstrækt/","meaning":"n.摘要，概要 adj.抽象（派）的","unit":10,"lesson":3,"seq":54,"isStar":false,"memo":"[联想] abs-(=ab-,离开) + tract(音似“拽个它”)→拽着它离开→摘要;提取","example":"They can abstract precious medicines from ordinary substances. 他们能从普通物质中提取珍贵药物。"},{"id":2847,"word":"extract","pronunciation":"/ɪk'strækt/","meaning":"v.取出；提取","unit":10,"lesson":3,"seq":55,"isStar":false,"memo":"[构词] ex-(向外) + tract(拽,拉)→向外拽→取出","example":"The following extract is taken from her new novel. 下面一段摘自她的新小说。","derivative":"extraction /k'strækʃn/ n.提取;拔出"},{"id":2848,"word":"contract","pronunciation":"/'kɒntrækt/","meaning":"n.合同；契约","unit":10,"lesson":3,"seq":56,"isStar":false,"memo":"[构词] con-(一起,相互) + tract(拽,拉)→拉到一起→合同,契约","example":"He mailed me the contract. 他把合同寄给了我。","derivative":"contraction /kən'trækʃn/ n.收缩;缩小"},{"id":2849,"word":"subtract","pronunciation":"/sʌb'trækt/","meaning":"v.减去，减掉","unit":10,"lesson":3,"seq":57,"isStar":false,"memo":"[构词] sub-(往下) + tract(拽,拉)→往下拽→减去,减掉","example":"This subtracts loss in value of factories and equipment. 这减去了工厂和设备的价值损失。"},{"id":2850,"word":"attract","pronunciation":"/ə'trækt/","meaning":"v.吸引；引起","unit":10,"lesson":3,"seq":58,"isStar":false,"memo":"联想 at-(一再地)+tract(拽,拉)→吸引;引起","example":"All the key words are printed in bold type so as to attract readers' attention. 所有的关键词都用粗体字印刷,以吸引读者的注意。","derivative":"attraction /ə'trækʃn/ n.吸引,吸引力\nattractive /ə'træktɪv/ adj.有吸引力的"},{"id":2851,"word":"distract","pronunciation":"/dɪ'strækt/","meaning":"v.转移（注意力）；使分心","unit":10,"lesson":3,"seq":59,"isStar":false,"memo":"构词 dis-(分开,分散)+tract(拽,拉)→转移(注意力);使分心","example":"You're distracting me from my work. 你使我不能专心工作。","derivative":"distraction /dɪ'strækʃn/ n.使人分心的事物"},{"id":2852,"word":"drag","pronunciation":"/dræg/","meaning":"v.拖，拉，拽 n.累赘","unit":10,"lesson":3,"seq":60,"isStar":false,"memo":"谐音 单词发音类似“拽个”→拖,拉,拽","example":"The luggage is too heavy to lift—you'll have to drag it. 这件行李太重了,提不起来——你得拖着走。"},{"id":2853,"word":"tow","pronunciation":"/taʊ/","meaning":"n.(车、船等的)牵引，拽 v.(用绳索或链条)拖，拉，牵引","unit":10,"lesson":3,"seq":61,"isStar":false,"memo":"谐音 单词发音类似“拖”。","example":"Our car was towed away by the police. 我们的汽车被警察拖走了。"},{"id":2854,"word":"haul","pronunciation":"/hɔːl/","meaning":"v.拉，拖，拽；用力缓慢挪动到（某处） n.大批赃物；旅程；拉，拖，拽","unit":10,"lesson":3,"seq":62,"isStar":false,"memo":"谐音 单词发音类似“嚎”→纤夫拉船时发出的声音像“嚎”,拖得很长→拉,拖,拽","example":"The car was hauled out of the river. 汽车被拖出了河。"},{"id":2855,"word":"accumulate","pronunciation":"/ə'kjumjəleɪt/","meaning":"v.积累，积聚；（数量）逐渐增加","unit":10,"lesson":3,"seq":63,"isStar":false,"memo":"联想 ac-(一再地)+cumu(音似“可莫”)+late(晚)→我一再强调,六级可莫准备晚了,要提前“积累”词汇。","example":"Dust soon accumulates if the rooms are not swept. 如果不打扫房间,灰尘很快就会越积越多。","derivative":"accumulation /ə,kjuːmjə'leɪʃn/ n.积累\naccumulative /ə'kjumjələtɪv/ adj.累积的"},{"id":2856,"word":"cumulative","pronunciation":"/'kjumjələtɪv/","meaning":"adj.累积的，积聚的；累计的","unit":10,"lesson":3,"seq":64,"isStar":false,"example":"Depression is often caused by the cumulative effects of stress and overwork. 抑郁症通常是压力和过度劳累的累积效应造成的。"},{"id":2857,"word":"centralise","pronunciation":"/-ize/","meaning":"'sentrəlaɪz/ v.使……处于中央的控制之下，集权控制","unit":10,"lesson":3,"seq":65,"isStar":false},{"id":2858,"word":"concentrate","pronunciation":"/'kɒnsntreɪt/","meaning":"n.浓缩物 v.集中，专心于","unit":10,"lesson":3,"seq":66,"isStar":false,"memo":"构词 con-(共同)+centr(=centre)+-ate(动词后缀)→共同以……为中心→集中","example":"Many studies reveal that eating breakfast helps people concentrate. 许多研究表明,吃早餐有助于人们集中注意力。","derivative":"concentration /ˌkɒnsn'treɪn/ n.专心,专注;重视;浓度"},{"id":2859,"word":"dynamic","pronunciation":"/daɪ'næmɪk/","meaning":"n.动力 adj.精力充沛的，充满活力的","unit":10,"lesson":4,"seq":1,"isStar":false,"memo":"联想 dy(联想“大雁”)+na(联想“拿”)+mic(音似“麦克”)→大雁是个内向的人,但只要拿起麦克风,她就充满活力→充满活力的","example":"He was a dynamic young advertising executive. 他是一位充满活力的年轻广告主管。","derivative":"dynamics /daɪˈnæmɪks/ n.动力学;力度"},{"id":2860,"word":"energy","pronunciation":"/'enədʒi/","meaning":"n.精力；活力；干劲；力量；能量","unit":10,"lesson":4,"seq":2,"isStar":false,"memo":"谐音 单词发音类似“俺奶鸡”→俺奶奶还抓鸡呢,“精力”特别旺盛。","example":"That is a waste of time and energy. 那是对时间和精力的浪费。","derivative":"energetic /enəˈdʒetɪk/ adj.精力充沛的,充满活力的\nenergetically /enəˈdʒetɪkli/ adv.精力充沛地,充满活力地"},{"id":2861,"word":"animate","pronunciation":"/'ænɪmeɪt/","meaning":"v.使具活力，使生气勃勃","unit":10,"lesson":4,"seq":3,"isStar":false},{"id":2862,"word":"activate","pronunciation":"/'æktɪveɪt/","meaning":"v.使活动；激活；使活化","unit":10,"lesson":4,"seq":4,"isStar":false,"memo":"对照 act v.&n.行动→active adj.活跃的→activate v.","example":"Researchers succeeded in determining how coffee activated different areas of the brain. 研究人员成功确定了咖啡是如何激活大脑的不同区域的。"},{"id":2863,"word":"battery","pronunciation":"/'bætri, 'bætəri/","meaning":"n.电池","unit":10,"lesson":4,"seq":5,"isStar":false,"memo":"对照 她试图在市面上寻找一款更好的(better)电池(battery),但结果让她大失所望。","example":"They have long believed in the promise of batteries to change the world. 长期以来,他们一直相信电池能够改变世界。"},{"id":2864,"word":"enthusiastic","pronunciation":"/ɪnθjuːzi'æstɪk/","meaning":"adj.热心的，热情的","unit":10,"lesson":4,"seq":6,"isStar":false,"example":"He wasn't discouraged and soon got as enthusiastic as ever. 他并不气馁，很快就恢复了一如既往的热情。","derivative":"enthusiast n.爱好者; enthusiasm n.热情，热心; enthusiastically adv.热心地，热情地"},{"id":2865,"word":"indifferent","pronunciation":"/ɪn'dɪfrənt/","meaning":"adj.冷漠的，不关心的","unit":10,"lesson":4,"seq":7,"isStar":false,"memo":"[联想] in-(否定前缀) + different(不同的) →对于没有什么不同的事物，人们的态度通常是“冷漠的”。","example":"They are indifferent and keep on throwing garbage into the river. 他们漠不关心，并继续往河里扔垃圾。","derivative":"indifference n.冷漠，漠不关心"},{"id":2866,"word":"differentiate","pronunciation":"/dɪfə'renʃieɪt/","meaning":"v.区分，区别","unit":10,"lesson":4,"seq":8,"isStar":false,"memo":"[对照] 他擅长区分(differentiate)不同的(different)事物，找出它们的不同(difference)。","example":"I can't differentiate one variety from another. 我无法区分不同的品种。","derivative":"differentiation n.区分，区别"},{"id":2867,"word":"sober","pronunciation":"/'səʊbə(r)/","meaning":"adj.未喝醉的，清醒的 v.使清醒","unit":10,"lesson":4,"seq":9,"isStar":false,"memo":"[对照] 喝完苏打水(soda)你会很清醒的(sober)。","example":"I turn to eccentric measures to try to keep my mind sober. 我开始采取一些古怪的方法来努力保持头脑清醒。"},{"id":2868,"word":"soda","pronunciation":"/'səʊdə/","meaning":"n.苏打汽水","unit":10,"lesson":4,"seq":10,"isStar":false,"memo":"[谐音] 单词发音类似“苏打”。","example":"Add some soda to the whisky, please. 请在威士忌中加点苏打水。"},{"id":2869,"word":"passion","pronunciation":"/'pæʃn/","meaning":"n.激情，热情","unit":10,"lesson":4,"seq":11,"isStar":false},{"id":2870,"word":"compassion","pronunciation":"/kəm'pæʃn/","meaning":"n.同情，怜悯","unit":10,"lesson":4,"seq":12,"isStar":false,"memo":"[联想] com-(所有，都) + passion(激情)→该事件使人们群情激愤，对受害者充满了“同情”。"},{"id":2871,"word":"compass","pronunciation":"/'kʌmpəs/","meaning":"n.指南针；范围","unit":10,"lesson":4,"seq":13,"isStar":false,"memo":"联想 com(联想 come) + pass(通过) → 通过森林时容易迷路，需要用“指南针”才能确认方向。","example":"We had to rely on a compass and a lot of luck to get here. 我们只得靠指南针和很多的好运才来到这里。"},{"id":2872,"word":"compact","pronunciation":"/kəm'pækt/","meaning":"v./adj. adj.紧密的，密集的，敦实的","unit":10,"lesson":4,"seq":14,"isStar":false,"memo":"联想 com-(所有，都) + pact (音似“拍个它”) → 做年糕时，所有人都过来拍它，把它“压紧”。","example":"Their bodies are sleek and compact. 它们的身体光滑而紧实。"},{"id":2873,"word":"impact","pronunciation":"/'ɪmpækt/","meaning":"n.作用；影响；冲击力","unit":10,"lesson":4,"seq":15,"isStar":false,"memo":"联想 im-(= in-, 进入) + pact (音似“拍个它”) → 进入房间拍它会对其产生“影响”。","example":"The new policy will impact the economic development of the country. 新政策将会对这个国家的经济发展产生影响。"},{"id":2874,"word":"influence","pronunciation":"/'ɪnfluəns/","meaning":"n.影响(力)，作用；有影响的人(或事物) v.影响，对……起作用","unit":10,"lesson":4,"seq":16,"isStar":false,"memo":"构词 in-(入) + flu(= flow) + -ence(后缀) → 流入某物(从而波及) → 影响","example":"Some experts are suggesting that we turn peer influence to good use in education. 一些专家建议我们在教育中充分利用同伴影响的积极作用。"},{"id":2875,"word":"influential","pronunciation":"/ɪn'fluːənʃl/","meaning":"adj.有影响力的","unit":10,"lesson":4,"seq":17,"isStar":false,"memo":"对照 influence n. & v.影响 → influential adj.","example":"She is one of the most influential figures in local politics. 她是本地政坛最有影响力的人物之一。"},{"id":2876,"word":"compatible","pronunciation":"/kəm'pætəbl/","meaning":"adj.兼容的，可共用的；可共存的；(因思想、志趣等相投而)关系好的","unit":10,"lesson":4,"seq":18,"isStar":false,"memo":"联想 com-(一起，相互) + pat (音似“拍打”) + -ible(形容词后缀) → 那两个人可以相互拍打肩膀，他们是“关系好的”朋友。","example":"His political views weren't compatible with mine. 他的政治观点和我的政治观点不相容。","derivative":"compatibility /kəmˌpætəˈbɪləti/ n.和睦相处；并存；相容"},{"id":2877,"word":"tedious","pronunciation":"/'tiːdiəs/","meaning":"adj.枯燥乏味的；冗长的","unit":10,"lesson":4,"seq":19,"isStar":false,"memo":"[联想] tedi(联想“特地”)+o(形似甜甜圈)+us(我们)→我们特地去到奶奶家和她一起做甜甜圈,以消解她“枯燥乏味”的情绪。","example":"It is really tedious to sit in the office reading newspapers and drinking tea. 坐在办公室读报纸、喝茶真是一件乏味的事情。"},{"id":2878,"word":"dull","pronunciation":"/dʌl/","meaning":"v.减轻；(使)变麻木；使不活泼 adj.枯燥无味的；无聊的；不明亮的","unit":10,"lesson":4,"seq":20,"isStar":false,"memo":"[联想] du(联想“读”)+ll(形似罗马数字2)→她今天读了两本“无聊的”书。","example":"Life in a small town could be deadly dull. 小城镇的生活可能乏味至极。"},{"id":2879,"word":"routine","pronunciation":"/ruː'tiːn/","meaning":"n.常规，惯例；例行公事；例行程序，例程 adj.常规的，例行公事的","unit":10,"lesson":4,"seq":21,"isStar":false,"memo":"[谐音] 单词发音类似“路听”→虽然老板比较忙,但也会按照“惯例”在路上听秘书汇报工作。","example":"I have to handle some routine tasks. 我不得不处理一些日常工作。"},{"id":2880,"word":"agenda","pronunciation":"/ə'dʒendə/","meaning":"n.(会议的)议程表，议事日程","unit":10,"lesson":4,"seq":22,"isStar":false,"memo":"[联想] a(一)+gen(音似“件”)+da(联想“大”)→一件大(事)→大事必须放在“议程表”里。","example":"Playing cards was on the agenda. 打牌被提上了日程。"},{"id":2881,"word":"summary","pronunciation":"/'sʌməri/","meaning":"n.总结，概括，概要 adj.总结性的；概括的，概要的","unit":10,"lesson":4,"seq":23,"isStar":false,"example":"The following is a summary of our conclusions. 现将我们的几点结论综述如下。","derivative":"summarise/-ize /'sʌməraɪz/ v.总结;概括"},{"id":2882,"word":"sum","pronunciation":"/sʌm/","meaning":"n.金额，款项；总数 v.总结，概括","unit":10,"lesson":4,"seq":24,"isStar":false,"example":"He has been donating a large sum of money to charity. 他一直在向慈善机构捐赠大笔款项。"},{"id":2883,"word":"audit","pronunciation":"/'ɔːdɪt/","meaning":"n.审计，稽核；(质量或标准的)审查，检查 v.审计，稽核","unit":10,"lesson":4,"seq":25,"isStar":false},{"id":2884,"word":"arithmetic","pronunciation":"/ə'riθmətɪk/","meaning":"n.算术；算术运算","unit":10,"lesson":4,"seq":26,"isStar":false,"memo":"[谐音] 单词发音类似“阿瑞斯没听课”→阿瑞斯没听“算术”课,所以“算术运算”得了零分。","example":"It is just as important as a knowledge of the basic arithmetic formulas. 它和掌握基本的算术公式一样重要。"},{"id":2885,"word":"atlas","pronunciation":"/'ætləs/","meaning":"n.地图册；地图集","unit":10,"lesson":4,"seq":27,"isStar":false},{"id":2886,"word":"brochure","pronunciation":"/'braʊʃə(r)/","meaning":"n.手册，小册子","unit":10,"lesson":4,"seq":28,"isStar":false,"memo":"联想 bro(联想 brother)+chu(联想“出”)+re(字母音似“阿姨”)→哥哥出去递给过路的阿姨一个“小册子”。","example":"They can find the application forms in the brochure. 他们可以在小册子里找到申请表。"},{"id":2887,"word":"leaflet","pronunciation":"/'liːflət/","meaning":"n.传单，小册子","unit":10,"lesson":4,"seq":29,"isStar":false,"memo":"构词 leaf(叶→页)+-let(小)→传单;小册子","example":"She had 500 leaflets to stuff into envelopes. 她要把500份传单装进信封里。"},{"id":2888,"word":"graph","pronunciation":"/ɡrɑːf/","meaning":"n.图，图表，曲线图","unit":10,"lesson":4,"seq":30,"isStar":false,"example":"In the graph, the population of farmers has decreased sharply in the past 10 years. 在图表中,农民的数量在过去10年内急剧减少。","derivative":"graphic /'græfɪk/ adj.绘画的;图样的 n.图表,图形; graphically /'græfɪkli/ adv.以书画(或图表)形式;形象地,生动地"},{"id":2889,"word":"career","pronunciation":"/kə'riə(r)/","meaning":"n.生涯，职业；经历；事业","unit":10,"lesson":4,"seq":31,"isStar":false,"memo":"联想 car(车)+-eer(名词后缀)→他们是从事不同“职业”的人,坐的车也不同;车走过的路就是他们的“经历”。","example":"He is at the peak of his career. 他正处在事业的巅峰。"},{"id":2890,"word":"carpenter","pronunciation":"/'kɑːpəntə(r)/","meaning":"n.木工；木匠","unit":10,"lesson":4,"seq":32,"isStar":false,"memo":"联想 car(车)+pen(音似“棚”)+t+-er(表示人的后缀)→古时候,制作车和车棚的人是“木匠”。","example":"They were skilled carpenters themselves. 他们自己就是技术熟练的木匠。"},{"id":2891,"word":"carriage","pronunciation":"/'kærɪdʒ/","meaning":"n.(火车的)客车厢；四轮马车；运输","unit":10,"lesson":4,"seq":33,"isStar":false,"memo":"构词 carri(=carry)+-age(名词后缀)→与“运送”相关的事物→客车厢;四轮马车","example":"There are workers pushing carriages. 有推着四轮马车的工人。"},{"id":2892,"word":"carrier","pronunciation":"/'kæriə(r)/","meaning":"n.运输工具；运载工具；携带者","unit":10,"lesson":4,"seq":34,"isStar":false,"memo":"对照 carry v.运送;携带→carrier n.","example":"He is a water carrier. 他是一个送水员。"},{"id":2893,"word":"cart","pronunciation":"/kɑːt/","meaning":"n.手推车；购物车；运货马车","unit":10,"lesson":4,"seq":35,"isStar":false,"memo":"谐音 单词发音类似“卡他”→他推“购物车”上扶梯时,车卡住了。"},{"id":2894,"word":"caravan","pronunciation":"/'kærəvæn/","meaning":"n.旅行拖车；大篷车；(尤指穿越沙漠的)旅行队，车队","unit":10,"lesson":4,"seq":36,"isStar":false},{"id":2895,"word":"cargo","pronunciation":"/'kɑːɡəʊ/","meaning":"n.(船或飞机装载的)货物","unit":10,"lesson":4,"seq":37,"isStar":false,"memo":"联想 car(车)+go(走了)→车装满“货物”就走了。","example":"You can contract with us to deliver your cargo. 你可以和我们签订合同,由我们负责运输货物。"},{"id":2896,"word":"charge","pronunciation":"/tʃɑːdʒ/","meaning":"n.收费；控告；责任 v.收(费)；控告；起诉；充电","unit":10,"lesson":4,"seq":38,"isStar":false,"memo":"联想 cha(联想“叉”)+r(形似叉子)+ge(联想“哥”)→你用叉子叉到哥哥的手了,哥哥开玩笑说,你得负“责任”,否则就要“控告”你。","example":"He faces trial on several charges. 他面临针对多项指控的审判。"},{"id":2897,"word":"numerical","pronunciation":"/njuː'merɪkl/","meaning":"adj.数字的；用数字表示的","unit":10,"lesson":4,"seq":39,"isStar":false,"memo":"构词 numer(=number)+-ical(形容词后缀)→数字的;用数字表示的","example":"The results are expressed in descending numerical order. 结果按数字降序列出。"},{"id":2898,"word":"numerous","pronunciation":"/'njuːmərəs/","meaning":"adj.众多的；许多的","unit":10,"lesson":4,"seq":40,"isStar":false,"memo":"构词 numer(=number)+-ous(形容词后缀)→数量多的→许多的","example":"This scale took numerous factors into consideration. 这个量表考虑了许多因素。"},{"id":2899,"word":"innumerable","pronunciation":"/ɪ'njuːmərəbl/","meaning":"adj.无数的，大量的，多得数不清的","unit":10,"lesson":4,"seq":41,"isStar":false,"memo":"构词 in-(否定前缀)+numer(=number)+-able(形容词后缀)→不能用数量衡量的→无数的,大量的","example":"This mountain was the home of innumerable birds. 这座山是无数鸟儿的家园。"},{"id":2900,"word":"biology","pronunciation":"/baɪ'ɒlədʒi/","meaning":"n.生物学","unit":10,"lesson":4,"seq":42,"isStar":false,"memo":"构词 bio(生物)+-logy(名词后缀,表学科)→有关生物的学科→生物学","example":"Biology is one of my favourite subjects. 生物是我最喜欢的学科之一。"},{"id":2901,"word":"antibiotic","pronunciation":"/æntɪbaɪ'ɒtɪk/","meaning":"n.抗生素  adj.抗生的；抗菌的","unit":10,"lesson":4,"seq":43,"isStar":false},{"id":2902,"word":"biochemistry","pronunciation":"/baɪəu'kemɪstrɪ/","meaning":"n.生物化学","unit":10,"lesson":4,"seq":44,"isStar":false},{"id":2903,"word":"biotechnology","pronunciation":"/baɪəʊtek'nɒlədʒi/","meaning":"n.生物科技","unit":10,"lesson":4,"seq":45,"isStar":false},{"id":2904,"word":"biography","pronunciation":"/baɪ'ɒgrəfi/","meaning":"n.传记","unit":10,"lesson":4,"seq":46,"isStar":false,"memo":"[构词] bio-(生物,生命) + graph(写) + -y(名词后缀)→对生命的书写→传记","example":"The book gives potted biographies of all the major painters. 这本书简述了所有重要画家的生平。"},{"id":2905,"word":"autobiography","pronunciation":"/ɔːtəbaɪ'ɒgrəfi/","meaning":"n.自传","unit":10,"lesson":4,"seq":47,"isStar":false},{"id":2906,"word":"expressway","pronunciation":"/ɪk'spresweɪ/","meaning":"n.(美国)高速公路","unit":10,"lesson":4,"seq":48,"isStar":false},{"id":2907,"word":"halfway","pronunciation":"/haʊf'weɪ/","meaning":"adv. & adj.半途(的)，中间(的)","unit":10,"lesson":4,"seq":49,"isStar":false},{"id":2908,"word":"subway","pronunciation":"/'sʌbweɪ/","meaning":"n.地铁；地下通道","unit":10,"lesson":4,"seq":50,"isStar":false,"memo":"[构词] sub-(在……下面) + way(路)→在地下的路→地铁;地下通道","example":"I've never been on the subway. 我从来没坐过地铁。"},{"id":2909,"word":"convoy","pronunciation":"/'kɒnvɒɪ/","meaning":"n.(尤指有士兵护送的)车队，船队 v.护送；护航","unit":10,"lesson":4,"seq":51,"isStar":false},{"id":2910,"word":"envoy","pronunciation":"/'envɒɪ/","meaning":"n.使者，使节；(谈判等的)代表","unit":10,"lesson":4,"seq":52,"isStar":false},{"id":2911,"word":"tailor","pronunciation":"/'teɪlə(r)/","meaning":"n.裁缝  v.定做；调整","unit":10,"lesson":4,"seq":53,"isStar":false,"memo":"构词 tail(切,剪)+-or(后缀)→进行切和剪的人→裁缝","example":"He works as a tailor. 他是一个裁缝。"},{"id":2912,"word":"curtail","pronunciation":"/'kɜː'teɪl/","meaning":"v.缩短；减缩","unit":10,"lesson":4,"seq":54,"isStar":false},{"id":2913,"word":"detail","pronunciation":"/'diːteɪl/","meaning":"n.细节；详情","unit":10,"lesson":4,"seq":55,"isStar":false,"memo":"构词 de-(表加强)+tail(切)→切开(成很小的份);切碎→细节","example":"Can you tell me the story in detail? 你能详细地给我讲下这个故事吗?","derivative":"detailed /'diːteɪld/ adj.详细的;细致的"},{"id":2914,"word":"stitch","pronunciation":"/stɪtʃ/","meaning":"n.(缝纫的)一针，针脚；缝  v.缝补","unit":10,"lesson":4,"seq":56,"isStar":false,"memo":"谐音 单词发音类似“撕地契”→地契被撕碎了,得“一针”一针地“缝”起来。","example":"Put a stitch in the corner of the pocket to keep it in place. 在口袋角那儿缝一针把它固定住。"},{"id":2915,"word":"stigma","pronunciation":"/'stɪɡmə/","meaning":"n.耻辱；羞耻","unit":10,"lesson":4,"seq":57,"isStar":false},{"id":2916,"word":"lipstick","pronunciation":"/'lɪpstɪk/","meaning":"n.口红；唇膏","unit":10,"lesson":4,"seq":58,"isStar":false},{"id":2917,"word":"matter","pronunciation":"/'mætə(r)/","meaning":"n.物质；问题  v.重要","unit":10,"lesson":4,"seq":59,"isStar":false,"memo":"谐音 单词发音类似“买它”→这种“物质”很“重要”,买下它吧。","example":"Somehow it didn't seem to matter much any more. 不知怎么地,这似乎已经不大重要了。"},{"id":2918,"word":"maternal","pronunciation":"/mə'tɜːnl/","meaning":"adj.母亲的；母系的","unit":10,"lesson":4,"seq":60,"isStar":false},{"id":2919,"word":"maternity","pronunciation":"/mə'tɜːnəti/","meaning":"n.母性；母亲身份；怀孕","unit":10,"lesson":4,"seq":61,"isStar":false},{"id":2920,"word":"metaphor","pronunciation":"/'metəfə(r); 'metəfɔː(r)/","meaning":"n.暗喻；隐喻","unit":10,"lesson":4,"seq":62,"isStar":false}];
